window["\x45\x4c\x45\x4d\x45\x4e\x54\x5f\x44\x45\x53\x43\x52\x49\x50\x54\x49\x4f\x4e\x53"] = {
  "\x48":
    "\u6c2b\x28\x48\x79\x64\x72\x6f\x67\x65\x6e\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x48\uff0c\u539f\u5b50\u5e8f\x20\x31\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u4e00\u9031\u671f\u3001\u7b2c\x20\x31\x20\u65cf\x28\x73\x20\u5340\u584a\x29\uff0c\u662f\u5168\u5b87\u5b99\u69cb\u9020\u6700\u7c21\u55ae\u3001\u8c50\u5ea6\u6700\u9ad8\u4e14\u8cea\u91cf\u6700\u8f15\u7684\u5143\u7d20\u3002\x31\x37\x36\x36\x20\u5e74\uff0c\u5361\u6587\u8fea\u8a31\x28\x48\x65\x6e\x72\x79\x20\x43\x61\x76\x65\x6e\x64\x69\x73\x68\x29\u900f\u904e\u91d1\u5c6c\u8207\u9178\u53cd\u61c9\u8fa8\u8b58\u51fa\u6c2b\u6c23\uff0c\u4e26\u7a31\u4e4b\u70ba\u300c\u53ef\u71c3\u7a7a\u6c23\u300d\uff1b\u96a8\u5f8c\u62c9\u74e6\u7bc0\x28\x41\x6e\x74\x6f\x69\x6e\x65\x20\x4c\x61\x76\x6f\x69\x73\x69\x65\x72\x29\u89c0\u5bdf\u5230\u5176\u71c3\u71d2\u6703\u7522\u751f\u6c34\uff0c\u4fbf\u7d50\u5408\u5e0c\u81d8\u8a9e\u5b57\u6839\u300c\x68\x79\x64\x72\x6f\u300d\x28\u6c34\x29\u8207\u300c\x67\x65\x6e\x65\x73\u300d\x28\u7522\u751f\u8005\x29\u5c07\u5176\u547d\u540d\u70ba\u300c\x48\x79\x64\x72\x6f\x67\x65\x6e\u300d\uff0c\u610f\u70ba\u300c\u6210\u6c34\u4e4b\u6e90\u300d\u3002\u96d6\u7136\u6c2b\u5728\u9031\u671f\u8868\u4e2d\u6392\u5728\u9e7c\u91d1\u5c6c\u4e0a\u65b9\uff0c\u4f46\u5176\u6027\u8cea\u5728\u5e38\u58d3\u4e0b\u66f4\u63a5\u8fd1\u975e\u91d1\u5c6c\uff0c\u50c5\u5728\u6975\u9ad8\u58d3\u74b0\u5883\x28\u5982\u6728\u661f\u6838\u5fc3\x29\u4e0b\u624d\u53ef\u80fd\u5448\u73fe\u91d1\u5c6c\u614b\u3002\x0a\x0a\u5728\u5316\u5b78\u884c\u70ba\u4e0a\uff0c\u6c2b\u7684\u96fb\u5b50\u7d44\u614b\u70ba\x20\x31\x73\u00b9\uff0c\u5176\u96fb\u8ca0\u5ea6\x28\u7d04\x20\x32\x2e\x32\x30\x29\u4f7f\u5176\u80fd\u8207\u975e\u91d1\u5c6c\u5143\u7d20\u5f62\u6210\u5171\u50f9\u9375\uff0c\u4ea6\u80fd\u8207\u96fb\u8ca0\u5ea6\u6975\u4f4e\u7684\u91d1\u5c6c\u7d50\u5408\u5f62\u6210\u6c2b\u8ca0\u96e2\u5b50\x28\x48\u207b\x29\u3002\u6700\u95dc\u9375\u7684\u89c0\u5ff5\u662f\u300c\u6c2b\u9375\u300d\x28\x48\x79\x64\x72\x6f\x67\x65\x6e\x20\x42\x6f\x6e\x64\x69\x6e\x67\x29\uff1a\u7576\u6c2b\u8207\u96fb\u8ca0\u5ea6\u6975\u5f37\u7684\u6c1f\x28\x46\x29\u3001\u6c27\x28\x4f\x29\u3001\u6c2e\x28\x4e\x29\u7d50\u5408\u6642\uff0c\u6975\u5316\u5f8c\u7684\u6c2b\u539f\u5b50\u6703\u8207\u9130\u8fd1\u5206\u5b50\u7684\u5b64\u96fb\u5b50\u5c0d\u7522\u751f\u5f37\u70c8\u7684\u975c\u96fb\u5438\u5f15\u529b\u3002\u9019\u4e0d\u50c5\u89e3\u91cb\u4e86\u70ba\u4ec0\u9ebc\u6c34\x28\x48\u2082\x4f\x29\u64c1\u6709\u7570\u5e38\u9ad8\u7684\u6cb8\u9ede\u8207\u6bd4\u71b1\uff0c\u4e5f\u662f\u7a69\u5b9a\u86cb\u767d\u8cea\u7d50\u69cb\u8207\x20\x44\x4e\x41\x20\u96d9\u87ba\u65cb\u7684\u95dc\u9375\u3002\u6b64\u5916\uff0c\u5176\u6700\u5e38\u898b\u7684\u540c\u4f4d\u7d20\u300c\u6c15\u300d\u662f\u81ea\u7136\u754c\u4e2d\u552f\u4e00\u4e0d\u542b\u4e2d\u5b50\u7684\u539f\u5b50\uff0c\u9019\u7a2e\u7d14\u7cb9\u7684\u7d50\u69cb\u4f7f\u5176\u5728\u7269\u7406\u7814\u7a76\u4e2d\u5177\u6709\u7279\u6b8a\u5730\u4f4d\u3002\x0a\x0a\u5728\u96fb\u5316\u5b78\u9818\u57df\uff0c\u6c2b\u626e\u6f14\u8457\u57fa\u6e96\u5b9a\u7fa9\u8005\u7684\u89d2\u8272\u3002\u5316\u5b78\u5bb6\u898f\u5b9a\u5728\u6a19\u6e96\u72c0\u614b\u4e0b\uff0c\u300c\u6a19\u6e96\u6c2b\u96fb\u6975\u300d\x28\x53\x74\x61\x6e\x64\x61\x72\x64\x20\x48\x79\x64\x72\x6f\x67\x65\x6e\x20\x45\x6c\x65\x63\x74\x72\x6f\x64\x65\x2c\x20\x53\x48\x45\x29\u7684\u96fb\u4f4d\u503c\u70ba\x20\x30\x20\u4f0f\u7279\uff0c\u9019\u5c31\u50cf\u662f\u6e2c\u91cf\u6d77\u62d4\u9ad8\u5ea6\u6642\u7684\u300c\u6d77\u5e73\u9762\u300d\uff0c\u6240\u6709\u5143\u7d20\u7684\u6a19\u6e96\u96fb\u6975\u96fb\u4f4d\u90fd\u4ee5\u6b64\u70ba\u57fa\u6e96\u9032\u884c\u91cf\u5316\uff0c\u9032\u800c\u5efa\u7acb\u8d77\u96fb\u5316\u5b78\u5e8f\u3002\u5728\u73fe\u4ee3\u80fd\u6e90\u61c9\u7528\u4e0a\uff0c\u6c2b\u5247\u662f\u300c\u80fd\u6e90\u8f49\u578b\u300d\u7684\u660e\u661f\u3002\u76ee\u524d\u7814\u7a76\u91cd\u9ede\u5728\u65bc\u5229\u7528\u518d\u751f\u80fd\u6e90\u96fb\u89e3\u6c34\u7684\u300c\u7da0\u6c2b\u300d\x28\x47\x72\x65\x65\x6e\x20\x48\x79\x64\x72\x6f\x67\x65\x6e\x29\u6280\u8853\uff0c\u4ee5\u53ca\u8cea\u5b50\u4ea4\u63db\u819c\u71c3\u6599\u96fb\u6c60\x28\x50\x45\x4d\x46\x43\x29\u7684\u6548\u80fd\u63d0\u5347\u3002\u7136\u800c\uff0c\u6c2b\u539f\u5b50\u6975\u5c0f\u7684\u7279\u6027\u4f7f\u5176\u5bb9\u6613\u64f4\u6563\u9032\u5165\u91d1\u5c6c\u5167\u90e8\u5c0e\u81f4\u300c\u6c2b\u8106\u300d\x28\x48\x79\x64\x72\x6f\x67\x65\x6e\x20\x45\x6d\x62\x72\x69\x74\x74\x6c\x65\x6d\x65\x6e\x74\x29\uff0c\u9019\u662f\u8f38\u6c2b\u7ba1\u7dda\u5de5\u7a0b\u5fc5\u9808\u514b\u670d\u7684\u6750\u6599\u79d1\u5b78\u96e3\u984c\u3002\x0a\x0a\u6c2b\u5728\u7269\u7406\u7279\u6027\u4e0a\u5c55\u73fe\u51fa\u8a31\u591a\u53cd\u76f4\u89ba\u7684\u73fe\u8c61\u3002\u4f8b\u5982\uff0c\u7d14\u6c2b\u6c23\u71c3\u71d2\u96d6\u7136\u80fd\u91cb\u653e\u5de8\u5927\u80fd\u91cf\uff0c\u4f46\u5176\u706b\u7130\u5728\u7a7a\u6c23\u4e2d\u5e7e\u4e4e\u662f\u8089\u773c\u770b\u4e0d\u898b\u7684\u6de1\u85cd\u8272\uff0c\u5728\u767d\u5929\u89c0\u5bdf\u6642\u6975\u96e3\u767c\u73fe\uff0c\u751a\u81f3\u9700\u8981\u5229\u7528\u7279\u6b8a\u7684\u7d05\u5916\u7dda\u5075\u6e2c\u5668\u624d\u80fd\u5b9a\u4f4d\u706b\u707d\u3002\u6b64\u5916\uff0c\u6db2\u6c2b\u7684\u5bc6\u5ea6\u6975\u4f4e\uff0c\u540c\u6a23\u9ad4\u7a4d\u7684\u6db2\u9ad4\uff0c\u6db2\u6c2b\u7684\u91cd\u91cf\u50c5\u6709\u6c34\u7684\u7d04\u5341\u56db\u5206\u4e4b\u4e00\u3002\u9019\u7a2e\u517c\u5177\u6975\u7aef\u8f15\u76c8\u8207\u5de8\u5927\u80fd\u91cf\u5bc6\u5ea6\u7684\u7279\u6027\uff0c\u4f7f\u5176\u6210\u70ba\u6df1\u7a7a\u63a2\u7d22\u4e2d\u4e0d\u53ef\u6216\u7f3a\u7684\u706b\u7bad\u71c3\u6599\u3002\u5b83\u65e2\u662f\u5b87\u5b99\u8a95\u751f\u7684\u7b2c\u4e00\u500b\u5143\u7d20\uff0c\u4e5f\u662f\u4eba\u985e\u9081\u5411\u6c38\u7e8c\u80fd\u6e90\u793e\u6703\u7684\u91cd\u8981\u6a4b\u6a11\u3002",
  "\x48\x65":
    "\u6c26\x28\x48\x65\x6c\x69\x75\x6d\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x48\x65\uff0c\u539f\u5b50\u5e8f\x20\x32\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u4e00\u9031\u671f\u3001\u7b2c\x20\x31\x38\x20\u65cf\x28\u7a00\u6709\u6c23\u9ad4\uff0c\x73\x20\u5340\u584a\x29\uff0c\u662f\u5168\u5b87\u5b99\u542b\u91cf\u50c5\u6b21\u65bc\u6c2b\u7684\u5143\u7d20\u3002\u5b83\u662f\u552f\u4e00\u5148\u5728\u5730\u7403\u4e4b\u5916\u88ab\u8fa8\u8b58\u51fa\u7684\u5316\u5b78\u5143\u7d20\uff1a\x31\x38\x36\x38\x20\u5e74\u65e5\u5168\u98df\u671f\u9593\uff0c\u5929\u6587\u5b78\u5bb6\u5728\u592a\u967d\u5149\u8b5c\u4e2d\u767c\u73fe\u4e00\u689d\u4e0d\u660e\u7684\u91d1\u9ec3\u8272\u8b5c\u7dda\uff0c\u96a8\u5373\u4ee5\u5e0c\u81d8\u8a9e\u300c\x48\x65\x6c\x69\x6f\x73\u300d\x28\u592a\u967d\x29\u5c07\u5176\u547d\u540d\u70ba\x20\x48\x65\x6c\x69\x75\x6d\u3002\u76f4\u5230\x20\x31\x38\x39\x35\x20\u5e74\uff0c\u5316\u5b78\u5bb6\u624d\u6b63\u5f0f\u5f9e\u91d4\u923e\u7926\u4e2d\u5206\u96e2\u51fa\u6c26\u6c23\uff0c\u8b49\u5be6\u5176\u5728\u5730\u7403\u7684\u5b58\u5728\u3002\u7531\u65bc\u6c26\u7684\u8cea\u91cf\u6975\u8f15\u4e14\u5177\u5099\u9ad8\u5ea6\u5316\u5b78\u60f0\u6027\uff0c\u4e00\u65e6\u91cb\u653e\u81f3\u5927\u6c23\u4e2d\u4fbf\u6703\u9038\u6563\u81f3\u5916\u592a\u7a7a\uff0c\u4f7f\u5176\u5728\u5730\u6bbc\u4e2d\u986f\u5f97\u683c\u5916\u7a00\u6709\u4e14\u5177\u6230\u7565\u50f9\u503c\u3002\x0a\x0a\u5f9e\u96fb\u5b50\u7d50\u69cb\u89c0\u5bdf\uff0c\u6c26\u5177\u6709\u5c01\u9589\u4e14\u7a69\u5b9a\u7684\x20\x31\x73\u00b2\x20\u7d44\u614b\uff0c\u9019\u4f7f\u5176\u5177\u5099\u5168\u9031\u671f\u8868\u4e2d\u6700\u9ad8\u7684\u7b2c\u4e00\u96fb\u96e2\u80fd\u8207\u6975\u4f4e\u7684\u6975\u5316\u7387\u3002\u7531\u65bc\u6c26\u539f\u5b50\u9593\u7684\u51e1\u5f97\u74e6\u529b\x28\x56\x61\x6e\x20\x64\x65\x72\x20\x57\x61\x61\x6c\x73\x20\x46\x6f\x72\x63\x65\x29\u5fae\u5f31\u81f3\u6975\uff0c\u5b83\u5728\u5e38\u58d3\u4e0b\u662f\u552f\u4e00\u7121\u6cd5\u50c5\u900f\u904e\u964d\u6eab\u800c\u51dd\u56fa\u7684\u7269\u8cea\uff0c\u5176\u6cb8\u9ede\x28\x34\x2e\x32\x32\x20\x4b\x29\u4ea6\u70ba\u6240\u6709\u5143\u7d20\u4e2d\u6700\u4f4e\u3002\u5728\u9ad8\u4e2d\u5316\u5b78\u63a2\u8a0e\u6c23\u9ad4\u6027\u8cea\u6642\uff0c\u6c26\u6c23\u56e0\u5176\u539f\u5b50\u534a\u5f91\u6975\u5c0f\u4e14\u4ea4\u4e92\u4f5c\u7528\u529b\u5fae\u4e4e\u5176\u5fae\uff0c\u88ab\u8996\u70ba\u6700\u63a5\u8fd1\u300c\u7406\u60f3\u6c23\u9ad4\u300d\x28\x49\x64\x65\x61\x6c\x20\x47\x61\x73\x29\u884c\u70ba\u7684\u771f\u5be6\u6c23\u9ad4\u5be6\u4f8b\uff0c\u662f\u7406\u89e3\u6ce2\u4ee5\u8033\u5b9a\u5f8b\u3001\u67e5\u7406\u5b9a\u5f8b\u8207\u5206\u58d3\u5b9a\u5f8b\u6642\u7684\u91cd\u8981\u79d1\u5b78\u57fa\u6e96\u3002\x0a\x0a\u5728\u73fe\u4ee3\u79d1\u6280\u61c9\u7528\u4e2d\uff0c\u6c26\u7684\u4f4e\u6eab\u7269\u7406\u7279\u6027\u4e0d\u53ef\u66ff\u4ee3\u3002\u6db2\u6c26\u662f\u8d85\u5c0e\u6280\u8853\u7684\u6838\u5fc3\uff0c\u88ab\u5ee3\u6cdb\u7528\u65bc\u91ab\u7642\u7528\u7684\u6838\u78c1\u5171\u632f\u6210\u50cf\x28\x4d\x52\x49\x29\u8207\u5927\u578b\u5f37\u5b50\u5c0d\u649e\u6a5f\x28\x4c\x48\x43\x29\uff0c\u5c07\u8d85\u5c0e\u78c1\u9435\u51b7\u537b\u81f3\u6975\u4f4e\u6eab\u4ee5\u7dad\u6301\u96f6\u96fb\u963b\u72c0\u614b\u3002\u5728\u534a\u5c0e\u9ad4\u7522\u696d\uff0c\u6c26\u6c23\u7684\u9ad8\u71b1\u5c0e\u7387\u8207\u60f0\u6027\u4f7f\u5176\u6210\u70ba\u77fd\u6676\u5713\u88fd\u7a0b\x28\u5982\u5316\u5b78\u6c23\u76f8\u6c89\u7a4d\x29\u4e2d\u95dc\u9375\u7684\u51b7\u537b\u4ecb\u8cea\u8207\u8f09\u6c23\u3002\u503c\u5f97\u6ce8\u610f\u7684\u662f\uff0c\u5730\u7403\u4e0a\u7684\u6c26\u4e3b\u8981\u4f86\u81ea\u5730\u6bbc\u4e2d\u653e\u5c04\u6027\u5143\u7d20\x28\u5982\u923e\u3001\u91f7\x29\u7684\x20\u03b1\x20\u8870\u8b8a\uff0c\u5373\x20\u03b1\x20\u7c92\u5b50\u672c\u8cea\u4e0a\u5c31\u662f\u6c26\u7684\u539f\u5b50\u6838\x28\u2074\x48\x65\u00b2\u207a\x29\uff0c\u9019\u4e9b\u6c26\u6c23\u88ab\u5c01\u5b58\u65bc\u5929\u7136\u6c23\u7926\u5e8a\u4e2d\uff0c\u5c6c\u65bc\u4e0d\u53ef\u518d\u751f\u7684\u8cc7\u6e90\uff0c\u4e00\u65e6\u8017\u76e1\u4fbf\u96e3\u4ee5\u56de\u6536\u3002\x0a\x0a\u6c26\u5728\u7269\u7406\u6975\u9650\u4e0b\u5c55\u73fe\u51fa\u5b8f\u89c0\u7684\u91cf\u5b50\u73fe\u8c61\u3002\u7576\u6eab\u5ea6\u964d\u81f3\x20\x32\x2e\x31\x37\x20\x4b\x28\u5373\x20\u03bb\x20\u9ede\x29\u4ee5\u4e0b\u6642\uff0c\u6db2\u6c26\u6703\u8f49\u8b8a\u70ba\u300c\u8d85\u6d41\u9ad4\u300d\x28\x53\x75\x70\x65\x72\x66\x6c\x75\x69\x64\x29\uff0c\u5448\u73fe\u96f6\u9ecf\u5ea6\u72c0\u614b\uff0c\u80fd\u7121\u963b\u529b\u5730\u7a7f\u904e\u6975\u7d30\u5fae\u7684\u5b54\u9699\uff0c\u751a\u81f3\u9006\u8457\u91cd\u529b\u6500\u722c\u5bb9\u5668\u58c1\u800c\u6d41\u51fa\u5bb9\u5668\u3002\u6b64\u5916\uff0c\u8072\u97f3\u5728\u6c26\u6c23\u4e2d\u7684\u50b3\u64ad\u901f\u5ea6\u7d04\u70ba\u7a7a\u6c23\u7684\u4e09\u500d\uff0c\u9019\u5c0e\u81f4\u5438\u5165\u6c26\u6c23\u5f8c\u6703\u66ab\u6642\u6539\u8b8a\u8072\u8154\u7684\u5171\u632f\u983b\u7387\uff0c\u7522\u751f\u8072\u97f3\u8b8a\u5c16\u7684\u300c\u5510\u8001\u9d28\u6548\u679c\u300d\u3002\u9019\u7a2e\u5143\u7d20\u517c\u5177\u7d55\u5c0d\u7684\u5316\u5b78\u60f0\u6027\u8207\u6975\u7aef\u7684\u7269\u7406\u7279\u6027\uff0c\u4f7f\u5176\u6210\u70ba\u4eba\u985e\u63a2\u7d22\u7269\u8cea\u6975\u4f4e\u6eab\u72c0\u614b\u8207\u91cf\u5b50\u529b\u5b78\u908a\u754c\u7684\u91cd\u8981\u5a92\u4ecb\u3002",
  "\x4c\x69":
    "\u92f0\x28\x4c\x69\x74\x68\x69\x75\x6d\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x4c\x69\uff0c\u539f\u5b50\u5e8f\x20\x33\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u4e8c\u9031\u671f\u3001\u7b2c\x20\x31\x20\u65cf\x28\u9e7c\u91d1\u5c6c\x29\u3002\x31\x38\x31\x37\x20\u5e74\u7531\u745e\u5178\u5316\u5b78\u5bb6\u963f\u723e\u8cbb\u5fb7\u68ee\x28\x4a\x6f\x68\x61\x6e\x20\x41\x72\x66\x77\x65\x64\x73\x6f\x6e\x29\u5728\u900f\u92f0\u9577\u77f3\u7926\u4e2d\u767c\u73fe\u3002\u5176\u540d\u7a31\u6e90\u65bc\u5e0c\u81d8\u8a9e\u5b57\u6839\u300c\x6c\x69\x74\x68\x6f\x73\u300d\x28\u77f3\u982d\x29\uff0c\u8c61\u5fb5\u5176\u4f5c\u70ba\u9996\u500b\u5728\u7926\u77f3\u4e2d\u88ab\u8fa8\u8b58\u51fa\u7684\u9e7c\u91d1\u5c6c\uff0c\u6709\u5225\u65bc\u65e9\u671f\u5f9e\u690d\u7269\u7070\u71fc\u4e2d\u63d0\u53d6\u51fa\u7684\u9209\u8207\u9240\u3002\u92f0\u662f\u81ea\u7136\u754c\u4e2d\u6700\u8f15\u7684\u91d1\u5c6c\u5143\u7d20\uff0c\u5bc6\u5ea6\u50c5\u7d04\x20\x30\x2e\x35\x33\x34\x20\x67\x2f\x63\x6d\u00b3\uff0c\u7d04\u70ba\u6c34\u7684\u4e00\u534a\uff0c\u80fd\u8f15\u6613\u6d6e\u65bc\u6c34\u9762\u751a\u81f3\u662f\u77f3\u881f\u6cb9\u4e4b\u4e0a\u3002\x0a\x0a\u92f0\u7684\u50f9\u96fb\u5b50\u7d44\u614b\u70ba\x20\x5b\x48\x65\x5d\x32\x73\u00b9\uff0c\u7531\u65bc\u5176\u539f\u5b50\u534a\u5f91\u6975\u5c0f\u4e14\u96fb\u8377\u5bc6\u5ea6\u9ad8\uff0c\u92f0\u96e2\u5b50\x28\x4c\x69\u207a\x29\u5728\u6c34\u6eb6\u6db2\u4e2d\u5177\u6709\u6975\u5f37\u7684\u6c34\u5408\u80fd\uff0c\u9019\u5c0e\u81f4\u92f0\u5c55\u73fe\u51fa\u8207\u540c\u65cf\u5143\u7d20\u7565\u5fae\u4e0d\u540c\u7684\u7269\u7406\u5316\u5b78\u6027\u8cea\u3002\u5728\u9031\u671f\u8868\u4e2d\uff0c\u92f0\u8207\u76f8\u9130\u65cf\u7684\u9382\x28\x4d\x67\x29\u5b58\u5728\u986f\u8457\u7684\u300c\u5c0d\u89d2\u7dda\u898f\u5247\u300d\x28\x44\x69\x61\x67\x6f\x6e\x61\x6c\x20\x52\x65\x6c\x61\x74\x69\x6f\x6e\x73\x68\x69\x70\x29\uff0c\u5728\u5316\u5408\u7269\u7684\u6eb6\u89e3\u5ea6\u8207\u53cd\u61c9\u8da8\u52e2\u4e0a\u5177\u6709\u9ad8\u5ea6\u76f8\u4f3c\u6027\u3002\u5728\u96fb\u5316\u5b78\u5e8f\u5217\u4e2d\uff0c\u92f0\u64c1\u6709\u6975\u5927\u7684\u6a19\u6e96\u6c27\u5316\u96fb\u4f4d\x28\x45\u2070\x20\u2248\x20\x33\x2e\x30\x34\x35\x20\x56\x29\uff0c\u9019\u610f\u5473\u8457\u5b83\u6975\u6613\u5931\u53bb\u96fb\u5b50\uff0c\u662f\u5df2\u77e5\u91d1\u5c6c\u4e2d\u6700\u5f37\u7684\u9084\u539f\u5291\u4e4b\u4e00\u3002\x0a\x0a\u92f0\u88ab\u8b7d\u70ba\u80fd\u6e90\u8f49\u578b\u7684\u300c\u767d\u91d1\u300d\uff0c\u662f\u7576\u4ee3\u9ad8\u80fd\u91cf\u5bc6\u5ea6\u5132\u80fd\u7cfb\u7d71\u7684\u6838\u5fc3\u3002\u92f0\u96e2\u5b50\u96fb\u6c60\x28\x4c\x49\x42\x73\x29\u5229\u7528\u92f0\u96e2\u5b50\u5728\u9670\u6975\u8207\u967d\u6975\u9593\u7684\u5d4c\u5165\u8207\u812b\u5d4c\u884c\u70ba\uff0c\u5ee3\u6cdb\u9a45\u52d5\u4e86\u667a\u6167\u578b\u624b\u6a5f\u3001\u96fb\u52d5\u8eca\u53ca\u96fb\u7db2\u5132\u80fd\u7cfb\u7d71\u3002\u9664\u4e86\u96fb\u5316\u5b78\u61c9\u7528\uff0c\u92f0\u5728\u51b6\u91d1\u5de5\u696d\u4e2d\u80fd\u8207\u92c1\u3001\u9382\u69cb\u6210\u9ad8\u5f37\u5ea6\u4e14\u4f4e\u5bc6\u5ea6\u7684\u300c\u92c1\u92f0\u5408\u91d1\u300d\uff0c\u662f\u822a\u592a\u5de5\u7a0b\u6e1b\u8f15\u6a5f\u8eab\u91cd\u91cf\u7684\u95dc\u9375\u6750\u6599\u3002\u5728\u91ab\u7642\u9818\u57df\uff0c\u7279\u5b9a\u5291\u91cf\u7684\u78b3\u9178\u92f0\x28\x4c\x69\u2082\x43\x4f\u2083\x29\u4ea6\u88ab\u7528\u65bc\u8abf\u7bc0\u795e\u7d93\u50b3\u5c0e\u7269\u8cea\uff0c\u662f\u7cbe\u795e\u91ab\u5b78\u4e2d\u6cbb\u7642\u96d9\u6975\u6027\u969c\u7919\x28\u8e81\u9b31\u75c7\x29\u7684\u91cd\u8981\u85e5\u7269\u3002\x0a\x0a\u92f0\u5728\u5316\u5b78\u7279\u6027\u4e0a\u5177\u6709\u4e00\u500b\u7368\u7279\u7684\u53cd\u76f4\u89ba\u73fe\u8c61\uff1a\u5b83\u662f\u552f\u4e00\u80fd\u5728\u5e38\u6eab\u4e0b\u8207\u6c2e\u6c23\x28\x4e\u2082\x29\u76f4\u63a5\u53cd\u61c9\u751f\u6210\u6c2e\u5316\u92f0\x28\x4c\x69\u2083\x4e\x29\u7684\u9e7c\u91d1\u5c6c\uff0c\u9019\u4f7f\u5f97\u92f0\u91d1\u5c6c\u5728\u8655\u7406\u6642\u5fc5\u9808\u5728\u6c2c\u6c23\u74b0\u5883\u4e0b\u9032\u884c\u3002\u96d6\u7136\u92f0\u91d1\u5c6c\u6975\u5ea6\u67d4\u8edf\uff0c\u751a\u81f3\u53ef\u4ee5\u7528\u666e\u901a\u7f8e\u5de5\u5200\u5207\u958b\uff0c\u4f46\u5176\u65b0\u9bae\u5207\u9762\u5728\u7a7a\u6c23\u4e2d\u6703\u8fc5\u901f\u7531\u9280\u767d\u8272\u8f49\u70ba\u7070\u9ed1\u8272\u3002\u6b64\u5916\uff0c\u92f0\u662f\u5b87\u5b99\u5927\u7206\u70b8\u521d\u671f\u7522\u751f\u7684\u5c11\u6578\u539f\u59cb\u5143\u7d20\u4e4b\u4e00\uff0c\u4f46\u5728\u73fe\u4ee3\u5929\u6587\u89c0\u6e2c\u4e2d\u5176\u542b\u91cf\u537b\u9060\u4f4e\u65bc\u7406\u8ad6\u9810\u6e2c\u503c\uff0c\u9019\u5728\u5929\u6587\u7269\u7406\u5b78\u4e2d\u88ab\u7a31\u70ba\u300c\u5b87\u5b99\u92f0\u554f\u984c\u300d\uff0c\u81f3\u4eca\u4ecd\u662f\u63a2\u7d22\u5b87\u5b99\u6f14\u5316\u7684\u4e00\u500b\u91cd\u8981\u8b0e\u5718\u3002",
  "\x42\x65":
    "\u9239\x28\x42\x65\x72\x79\x6c\x6c\x69\x75\x6d\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x42\x65\uff0c\u539f\u5b50\u5e8f\x20\x34\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u4e8c\u9031\u671f\u3001\u7b2c\x20\x32\x20\u65cf\x28\u9e7c\u571f\u91d1\u5c6c\uff0c\x73\x20\u5340\u584a\x29\u3002\u5176\u540d\u7a31\u6e90\u65bc\u4e3b\u8981\u7926\u77f3\u7da0\u67f1\u77f3\x28\x42\x65\x72\x79\x6c\x29\uff0c\u8a9e\u6e90\u70ba\u5e0c\u81d8\u8a9e\x20\x62\x65\x72\x79\x6c\x6c\x6f\x73\u3002\x31\x37\x39\x38\x20\u5e74\u7531\u6cd5\u570b\u5316\u5b78\u5bb6\u6c83\u514b\u862d\x28\x4c\x6f\x75\x69\x73\x2d\x4e\x69\x63\x6f\x6c\x61\x73\x20\x56\x61\x75\x71\x75\x65\x6c\x69\x6e\x29\u5728\u5206\u6790\u7926\u77f3\u6642\u9996\u6b21\u8fa8\u8b58\u51fa\u5176\u6c27\u5316\u7269\u3002\u7531\u65bc\u5176\u9e7d\u985e\u5e36\u6709\u751c\u5473\uff0c\u65e9\u671f\u66fe\u88ab\u547d\u540d\u70ba\u300c\x47\x6c\x75\x63\x69\x6e\x69\x75\x6d\u300d\x28\u8a9e\u6e90\u610f\u70ba\u751c\x29\uff0c\u4f46\u56e0\u5176\u91d1\u5c6c\u7c89\u5875\u8207\u5316\u5408\u7269\u5177\u5099\u9ad8\u5ea6\u5287\u6bd2\u6027\uff0c\u5f8c\u7d71\u4e00\u4ee5\u9239\u547d\u540d\uff0c\u4ee5\u53cd\u6620\u5176\u7926\u7269\u4f86\u6e90\u8eab\u5206\u3002\u96d6\u7136\u8eab\u70ba\u9e7c\u571f\u91d1\u5c6c\u7684\u4e00\u54e1\uff0c\u9239\u5728\u8a31\u591a\u6027\u8cea\u4e0a\u537b\u5c55\u73fe\u51fa\u986f\u8457\u7684\u7368\u7279\u6027\u3002\x0a\x0a\u5728\u5316\u5b78\u6027\u8cea\u4e0a\uff0c\u9239\u7684\u96fb\u5b50\u7d44\u614b\u70ba\x20\x31\x73\u00b2\x20\x32\x73\u00b2\u3002\u8eab\u70ba\u65cf\u7fa4\u4e2d\u539f\u5b50\u534a\u5f91\u6700\u5c0f\u7684\u6210\u54e1\uff0c\u9239\u5177\u6709\u6975\u9ad8\u7684\u96fb\u8377\u5bc6\u5ea6\uff0c\u9019\u4f7f\u5176\u5316\u5b78\u884c\u70ba\u8207\u9031\u671f\u8868\u53f3\u4e0b\u65b9\u7684\u92c1\x28\x41\x6c\x29\u5448\u73fe\u986f\u8457\u7684\u300c\u5c0d\u89d2\u7dda\u898f\u5247\u300d\x28\x44\x69\x61\x67\x6f\x6e\x61\x6c\x20\x52\x65\x6c\x61\x74\x69\x6f\x6e\x73\x68\x69\x70\x29\u3002\u8207\u5178\u578b\u7684\u9e7c\u571f\u91d1\u5c6c\u4e0d\u540c\uff0c\u9239\u7684\u5316\u5408\u7269\u5c55\u73fe\u51fa\u8f03\u5f37\u7684\u5171\u50f9\u6027\uff0c\u4e14\u5176\u6c27\u5316\u7269\x28\x42\x65\x4f\x29\u8207\u6c2b\u6c27\u5316\u7269\x28\x42\x65\x28\x4f\x48\x29\u2082\x29\u7686\u5177\u5099\u5169\u6027\x28\x41\x6d\x70\x68\x6f\x74\x65\x72\x69\x63\x29\u7279\u5fb5\uff0c\u65e2\u80fd\u8207\u5f37\u9178\u53cd\u61c9\uff0c\u4ea6\u80fd\u6eb6\u65bc\u5f37\u9e7c\u7522\u751f\u9239\u9178\u6839\u96e2\u5b50\u3002\u9019\u7a2e\u504f\u96e2\u540c\u65cf\u898f\u5f8b\u7684\u7279\u6027\uff0c\u662f\u9ad8\u4e2d\u5316\u5b78\u5728\u7406\u89e3\u5143\u7d20\u9031\u671f\u6027\u8207\u96e2\u5b50\u6975\u5316\u80fd\u529b\u6642\u6975\u4f73\u7684\u63a2\u7a76\u5be6\u4f8b\u3002\x0a\x0a\u5728\u73fe\u4ee3\u5de5\u696d\u8207\u6750\u6599\u79d1\u5b78\u4e2d\uff0c\u9239\u56e0\u5176\u7269\u7406\u6975\u9650\u6027\u8cea\u800c\u4e0d\u53ef\u66ff\u4ee3\u3002\u7531\u65bc\u5176\u539f\u5b50\u5e8f\u6975\u4f4e\uff0c\u5c0d\x20\x58\x20\u5c04\u7dda\u7684\u5438\u6536\u80fd\u529b\u6975\u5f31\uff0c\u56e0\u6b64\u662f\u88fd\u9020\x20\x58\x20\u5c04\u7dda\u7ba1\u8f38\u51fa\u7a97\u53e3\x28\x58\x2d\x72\x61\x79\x20\x77\x69\x6e\x64\x6f\x77\x29\u7684\u6838\u5fc3\u6750\u6599\u3002\u5728\u5408\u91d1\u61c9\u7528\u65b9\u9762\uff0c\u300c\u9239\u9285\u5408\u91d1\u300d\u7d50\u5408\u4e86\u6975\u9ad8\u7684\u786c\u5ea6\u3001\u5c0e\u96fb\u6027\u8207\u6297\u75b2\u52de\u6027\uff0c\u5ee3\u6cdb\u7528\u65bc\u822a\u592a\u5100\u5668\u3001\u7cbe\u5bc6\u96fb\u5b50\u63a5\u9ede\u4ee5\u53ca\u5728\u6613\u71c3\u6613\u7206\u74b0\u5883\u4e2d\u4f7f\u7528\u7684\u300c\u4e0d\u7522\u751f\u706b\u82b1\u5de5\u5177\u300d\u3002\u6b64\u5916\uff0c\u9239\u5177\u5099\u512a\u7570\u7684\u4e2d\u5b50\u53cd\u5c04\u80fd\u529b\u8207\u4f4e\u4e2d\u5b50\u5438\u6536\u622a\u9762\uff0c\u4f7f\u5176\u5728\u6838\u7269\u7406\u7814\u7a76\u8207\u6838\u53cd\u61c9\u7210\u4e2d\u88ab\u7528\u4f5c\u53cd\u5c04\u5c64\u6750\u6599\uff0c\u7cbe\u78ba\u63a7\u5236\u4e2d\u5b50\u6d41\u5411\u3002\x0a\x0a\u9239\u5728\u822a\u592a\u5de5\u7a0b\u4e2d\u5c55\u73fe\u4e86\u5353\u8d8a\u7684\u6bd4\u525b\u5ea6\x28\u6bd4\u5f48\u6027\u6a21\u6578\x29\uff0c\u5176\u525b\u6027\u7d04\u70ba\u92fc\u7684\x20\x31\x2e\x35\x20\u500d\uff0c\u91cd\u91cf\u537b\u50c5\u70ba\u92c1\u7684\u4e09\u5206\u4e4b\u4e8c\uff0c\u4f7f\u5176\u6210\u70ba\u7cbe\u5bc6\u5149\u5b78\u7d50\u69cb\u7684\u9996\u9078\u3002\u8a79\u59c6\u65af\u00b7\u97cb\u4f2f\u592a\u7a7a\u671b\u9060\u93e1\x28\x4a\x57\x53\x54\x29\u90a3\u5de8\u5927\u7684\u91d1\u9ec3\u8272\u4e3b\u93e1\u5373\u662f\u4ee5\u9239\u91d1\u5c6c\u6253\u9020\uff0c\u5229\u7528\u5176\u5728\u6975\u4f4e\u6eab\u74b0\u5883\u4e0b\u512a\u7570\u7684\u5c3a\u5bf8\u7a69\u5b9a\u6027\u78ba\u4fdd\u6210\u50cf\u54c1\u8cea\u3002\u7136\u800c\uff0c\u9239\u53ca\u5176\u5316\u5408\u7269\u5177\u5099\u56b4\u91cd\u7684\u5438\u5165\u6027\u6bd2\u6027\uff0c\u9577\u671f\u63a5\u89f8\u7c89\u5875\u53ef\u80fd\u5c0e\u81f4\u81f4\u6b7b\u6027\u7684\u300c\u9239\u4e2d\u6bd2\u300d\x28\x42\x65\x72\x79\x6c\x6c\x69\x6f\x73\x69\x73\x29\uff0c\u56e0\u6b64\u5728\u6750\u6599\u52a0\u5de5\u4e2d\u5fc5\u9808\u63a1\u53d6\u6975\u56b4\u82db\u7684\u8ca0\u58d3\u9632\u8b77\u63aa\u65bd\u3002\u9019\u7a2e\u5353\u8d8a\u7269\u7406\u7279\u6027\u8207\u9ad8\u5ea6\u751f\u7269\u5371\u96aa\u6027\u7684\u4e26\u5b58\uff0c\u78ba\u7acb\u4e86\u9239\u5728\u5c16\u7aef\u79d1\u6280\u6750\u6599\u4e2d\u51b7\u5cfb\u800c\u95dc\u9375\u7684\u5730\u4f4d\u3002",
  "\x42":
    "\u787c\x28\x42\x6f\x72\x6f\x6e\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x42\uff0c\u539f\u5b50\u5e8f\x20\x35\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u4e8c\u9031\u671f\u3001\u7b2c\x20\x31\x33\x20\u65cf\x28\x70\x20\u5340\u584a\x29\uff0c\u662f\u8a72\u65cf\u552f\u4e00\u7684\u985e\u91d1\u5c6c\u5143\u7d20\u3002\u5176\u540d\u7a31\u6e90\u65bc\u963f\u62c9\u4f2f\u8a9e\u300c\x42\x75\x72\x61\x71\u300d\u6216\u6ce2\u65af\u8a9e\u300c\x42\x75\x72\x61\x68\u300d\uff0c\u610f\u6307\u5176\u6700\u91cd\u8981\u7684\u7926\u77f3\u2014\u2014\u787c\u7802\x28\x42\x6f\x72\x61\x78\x29\u3002\x31\x38\x30\x38\x20\u5e74\uff0c\u6cd5\u570b\u5316\u5b78\u5bb6\u6234\u7dad\x28\x48\x75\x6d\x70\x68\x72\x79\x20\x44\x61\x76\x79\x29\u3001\u84cb\x2d\u5442\u85a9\u514b\x28\x47\x61\x79\x2d\x4c\x75\x73\x73\x61\x63\x29\u8207\u6cf0\u7d0d\u723e\x28\x54\x68\x65\x6e\x61\x72\x64\x29\u5e7e\u4e4e\u540c\u6642\u5229\u7528\u9240\u9084\u539f\u787c\u9178\u88fd\u5f97\u7d14\u787c\u3002\u5118\u7ba1\u787c\u5728\u81ea\u7136\u754c\u4e2d\u4e0d\u4ee5\u6e38\u96e2\u614b\u5b58\u5728\uff0c\u4f46\u5176\u6c27\u5316\u7269\u8207\u787c\u9178\u9e7d\u5728\u5730\u6bbc\u4e2d\u5206\u5e03\u5ee3\u6cdb\uff0c\u662f\u690d\u7269\u751f\u9577\u5fc5\u9700\u7684\u5fae\u91cf\u5143\u7d20\u3002\x0a\x0a\u5728\u96fb\u5b50\u7d50\u69cb\u4e0a\uff0c\u787c\u7684\u57fa\u614b\u7d44\u614b\u70ba\x20\x31\x73\u00b2\x32\x73\u00b2\x32\x70\u00b9\u3002\u7531\u65bc\u50f9\u6bbc\u5c64\u50c5\u6709\u4e09\u500b\u96fb\u5b50\uff0c\u787c\u5728\u5f62\u6210\u5171\u50f9\u9375\u6642\u5e38\u5448\u73fe\u300c\u7f3a\u96fb\u5b50\u6027\u300d\uff0c\u4f8b\u5982\u5728\u4e09\u6c1f\u5316\u787c\x28\x42\x46\u2083\x29\u4e2d\uff0c\u787c\u539f\u5b50\u5468\u570d\u50c5\u6709\u516d\u500b\u96fb\u5b50\uff0c\u9019\u4f7f\u5176\u5177\u5099\u6975\u5f37\u7684\x20\x4c\x65\x77\x69\x73\x20\u9178\u7279\u5fb5\uff0c\u80fd\u8f15\u6613\u63a5\u53d7\u5b64\u96fb\u5b50\u5c0d\u3002\u6b64\u5916\uff0c\u787c\u539f\u5b50\u50be\u5411\u65bc\u5f62\u6210\u8907\u96dc\u7684\u5171\u50f9\u7db2\u7d61\u7d50\u69cb\uff0c\u5176\u6700\u7a69\u5b9a\u7684\u540c\u7d20\u7570\u5f62\u9ad4\u662f\u4ee5\x20\x42\u2081\u2082\x20\u4e8c\u5341\u9762\u9ad4\u70ba\u57fa\u672c\u55ae\u5143\u7684\u6676\u9ad4\uff0c\u9019\u8ce6\u4e88\u4e86\u787c\u6975\u9ad8\u7684\u786c\u5ea6\x28\u50c5\u6b21\u65bc\u91d1\u525b\u77f3\x29\u8207\u9ad8\u7194\u9ede\x28\u7d04\x20\x32\x30\x37\x36\x20\u00b0\x43\x29\uff0c\u5c55\u73fe\u51fa\u7570\u65bc\u540c\u65cf\u91d1\u5c6c\u5143\u7d20\u7684\u7269\u7406\u7279\u5fb5\u3002\x0a\x0a\u73fe\u4ee3\u6750\u6599\u79d1\u5b78\u4e2d\uff0c\u787c\u662f\u6539\u9032\u6750\u6599\u6027\u80fd\u7684\u95dc\u9375\u5143\u7d20\u3002\u5728\u534a\u5c0e\u9ad4\u7522\u696d\uff0c\u787c\u662f\u77fd\u6676\u5713\u6700\u4e3b\u8981\u7684\x20\x70\x20\u578b\u647b\u96dc\u5291\x28\x44\x6f\x70\x61\x6e\x74\x29\uff0c\u7528\u4ee5\u8abf\u6574\u80fd\u9699\u7d50\u69cb\uff1b\u5728\u5316\u5b78\u5de5\u696d\uff0c\u787c\u77fd\u9178\u73bb\u7483\x28\x42\x6f\x72\x6f\x73\x69\x6c\x69\x63\x61\x74\x65\x20\x67\x6c\x61\x73\x73\x29\u56e0\u5177\u5099\u6975\u4f4e\u7684\u71b1\u81a8\u8139\u4fc2\u6578\u8207\u512a\u7570\u7684\u5316\u5b78\u6297\u6027\uff0c\u6210\u70ba\u5be6\u9a57\u5ba4\u5668\u6750\u8207\u9ad8\u7d1a\u5eda\u5177\u7684\u9996\u9078\u3002\u6b64\u5916\uff0c\u787c\u4e2d\u5b50\u6355\u7372\u6cbb\u7642\x28\x42\x4e\x43\x54\x29\u662f\u7576\u524d\u653e\u5c04\u91ab\u5b78\u7684\u524d\u6cbf\u65b9\u5411\uff0c\u5229\u7528\x20\u00b9\u2070\x42\x20\u6355\u6349\u71b1\u4e2d\u5b50\u5f8c\u91cb\u653e\u51fa\u7684\u9ad8\u80fd\x20\u03b1\x20\u7c92\u5b50\u4f86\u7cbe\u78ba\u64ca\u788e\u764c\u7d30\u80de\uff0c\u5be6\u73fe\u5206\u5b50\u7b49\u7d1a\u7684\u6a19\u9776\u653e\u7642\u3002\u5728\u80fd\u6e90\u9818\u57df\uff0c\u787c\u6c2b\u5316\u9209\x28\x4e\x61\x42\x48\u2084\x29\u4f5c\u70ba\u9ad8\u5bb9\u91cf\u5132\u6c2b\u6750\u6599\uff0c\u4ea6\u662f\u71c3\u6599\u96fb\u6c60\u7814\u7a76\u7684\u71b1\u9ede\u3002\x0a\x0a\u787c\u5c55\u73fe\u51fa\u8a31\u591a\u4ee4\u4eba\u8457\u8ff7\u7684\u7d50\u69cb\u7570\u69cb\u73fe\u8c61\u3002\u4f8b\u5982\uff0c\u6c2e\u5316\u787c\x28\x42\x4e\x29\u8207\u78b3\u5177\u6709\u7b49\u96fb\u5b50\u7d50\u69cb\uff0c\u80fd\u5f62\u6210\u8207\u77f3\u58a8\u7d50\u69cb\u76f8\u4f3c\u7684\u300c\u516d\u65b9\u6c2e\u5316\u787c\u300d\x28\x68\x2d\x42\x4e\uff0c\u4fd7\u7a31\u767d\u77f3\u58a8\x29\u8207\u786c\u5ea6\u63a5\u8fd1\u947d\u77f3\u7684\u300c\u7acb\u65b9\u6c2e\u5316\u787c\u300d\x28\x63\x2d\x42\x4e\x29\u3002\u6709\u8da3\u7684\u662f\uff0c\u787c\u5728\u6975\u9ad8\u58d3\u4e0b\u6703\u5c55\u73fe\u8d85\u5c0e\u6027\uff0c\u4e14\u5176\u8207\u6c2b\u5f62\u6210\u7684\u300c\u787c\u70f7\u300d\x28\x42\x6f\x72\x61\x6e\x65\x73\x29\u5bb6\u65cf\uff0c\u5176\u591a\u4e2d\u5fc3\u9375\x28\u5982\u4e09\u4e2d\u5fc3\u4e8c\u96fb\u5b50\u9375\uff0c\x33\x63\x2d\x32\x65\x29\u6253\u7834\u4e86\u50b3\u7d71\u8def\u6613\u65af\u7d50\u69cb\u5f0f\u7684\u4e8c\u4e2d\u5fc3\u4e8c\u96fb\u5b50\u6a21\u578b\uff0c\u8feb\u4f7f\u5316\u5b78\u5bb6\u4fee\u6b63\u5c0d\u5171\u50f9\u9375\u7684\u57fa\u790e\u5b9a\u7fa9\uff0c\u6210\u70ba\u7406\u89e3\u975e\u5178\u578b\u5316\u5b78\u9375\u7d50\u7684\u5fc5\u4fee\u8ab2\u3002",
  "\x43":
    "\u78b3\x28\x43\x61\x72\x62\x6f\x6e\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x43\uff0c\u539f\u5b50\u5e8f\x20\x36\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u4e8c\u9031\u671f\u3001\u7b2c\x20\x31\x34\x20\u65cf\x28\x70\x20\u5340\u584a\x29\uff0c\u662f\u69cb\u6210\u5730\u7403\u751f\u547d\u8207\u6709\u6a5f\u5316\u5b78\u7684\u6838\u5fc3\u5143\u7d20\u3002\u5176\u540d\u7a31\u6e90\u65bc\u62c9\u4e01\u8a9e\u300c\x63\x61\x72\x62\x6f\u300d\uff0c\u610f\u70ba\u6728\u70ad\u3002\u78b3\u5728\u53f2\u524d\u6642\u4ee3\u5373\u4ee5\u6728\u70ad\u8207\u947d\u77f3\u7684\u5f62\u5f0f\u88ab\u4eba\u985e\u77e5\u66c9\uff0c\u76f4\u5230\x20\x31\x37\x37\x32\x20\u5e74\uff0c\u62c9\u74e6\u7bc0\x28\x41\x6e\x74\x6f\x69\x6e\x65\x20\x4c\x61\x76\x6f\x69\x73\x69\x65\x72\x29\u900f\u904e\u71c3\u71d2\u5be6\u9a57\u8b49\u660e\u947d\u77f3\u8207\u6728\u70ad\u7686\u7531\u76f8\u540c\u7684\u5143\u7d20\u7d44\u6210\u3002\u78b3\u662f\u5b87\u5b99\u4e2d\u8c50\u5ea6\u7b2c\u56db\u7684\u5143\u7d20\uff0c\u5728\u5730\u6bbc\u4e2d\u5247\u4ee5\u77f3\u7070\u5ca9\u3001\u5316\u77f3\u71c3\u6599\u53ca\u6709\u6a5f\u5206\u5b50\u7b49\u5f62\u5f0f\u5faa\u74b0\uff0c\u5176\u7368\u7279\u7684\u9375\u7d50\u80fd\u529b\u662f\u81ea\u7136\u754c\u8907\u96dc\u6027\u7684\u6839\u6e90\u3002\x0a\x0a\u78b3\u7684\u6838\u5fc3\u5316\u5b78\u7279\u5fb5\u5728\u65bc\u5176\x20\x31\x73\u00b2\x32\x73\u00b2\x32\x70\u00b2\x20\u7684\u96fb\u5b50\u7d44\u614b\u8207\u6975\u5f37\u7684\u300c\u81ea\u6210\u93c8\u80fd\u529b\u300d\x28\x43\x61\x74\x65\x6e\x61\x74\x69\x6f\x6e\x29\u3002\u78b3\u539f\u5b50\u5177\u5099\u4e2d\u7b49\u7684\u96fb\u8ca0\u5ea6\x28\u7d04\x20\x32\x2e\x35\x35\x29\uff0c\u80fd\u900f\u904e\x20\x73\x70\u00b3\u3001\x73\x70\u00b2\x20\u6216\x20\x73\x70\x20\u6df7\u6210\u8ecc\u57df\u8207\u81ea\u8eab\u6216\u5176\u4ed6\u5143\u7d20\u5f62\u6210\u7a69\u5b9a\u7684\u55ae\u9375\u3001\u96d9\u9375\u6216\u4e09\u9375\u3002\u9019\u7a2e\u9ad8\u5ea6\u7684\u9375\u7d50\u9748\u6d3b\u6027\uff0c\u4f7f\u78b3\u80fd\u5efa\u69cb\u5f9e\u7c21\u55ae\u7684\u7532\u70f7\x28\x43\x48\u2084\x29\u5230\u8907\u96dc\u7684\u86cb\u767d\u8cea\u3001\u805a\u5408\u7269\u7b49\u7121\u7aae\u591a\u6a23\u7684\u5206\u5b50\u3002\u6b64\u5916\uff0c\u78b3\u64c1\u6709\u6975\u70ba\u8c50\u5bcc\u7684\u540c\u7d20\u7570\u5f62\u9ad4\uff0c\u5f9e\u7d55\u7de3\u4e14\u786c\u5ea6\u6975\u9ad8\u7684\u947d\u77f3\u5230\u5c0e\u96fb\u4e14\u67d4\u8edf\u7684\u77f3\u58a8\uff0c\u5c55\u73fe\u4e86\u6676\u9ad4\u7d50\u69cb\u6c7a\u5b9a\u5b8f\u89c0\u6027\u8cea\u7684\u6975\u81f4\u7bc4\u4f8b\u3002\x0a\x0a\u5728\u53f0\u7063\u9ad8\u4e2d\u5316\u5b78\u8ab2\u7db1\u4e2d\uff0c\u78b3\u53ca\u5176\u5316\u5408\u7269\u662f\u71b1\u5316\u5b78\u8207\u96fb\u5316\u5b78\u7684\u91cd\u8981\u57fa\u6e96\u3002\u4f8b\u5982\uff0c\u6a19\u6e96\u71c3\u71d2\u71b1\u7684\u5b9a\u7fa9\u5e38\u8207\u78b3\u7684\u5b8c\u5168\u71c3\u71d2\u76f8\u95dc\uff0c\u4e14\u78b3\u6975\u5e38\u88ab\u7528\u4f5c\u96fb\u6c60\u7684\u96fb\u6975\u6750\u6599\x28\u5982\u4e7e\u96fb\u6c60\u4e2d\u7684\u77f3\u58a8\u68d2\u6216\u92f0\u96fb\u6c60\u7684\u8ca0\u6975\x29\u3002\u5728\u73fe\u4ee3\u79d1\u6280\u4e2d\uff0c\u78b3\u6750\u6599\u5df2\u9032\u5165\u5948\u7c73\u5c3a\u5ea6\uff1a\u78b3\u5948\u7c73\u7ba1\x28\x43\x4e\x54\x73\x29\u5177\u5099\u6975\u9ad8\u7684\u6297\u62c9\u5f37\u5ea6\u8207\u71b1\u5c0e\u7387\uff0c\u800c\u55ae\u5c64\u78b3\u539f\u5b50\u69cb\u6210\u7684\u300c\u77f3\u58a8\u70ef\u300d\x28\x47\x72\x61\x70\x68\x65\x6e\x65\x29\u5247\u56e0\u5176\u5353\u8d8a\u7684\u96fb\u5b50\u9077\u79fb\u7387\u8207\u6a5f\u68b0\u97cc\u6027\uff0c\u88ab\u8996\u70ba\u4e0b\u4e00\u4ee3\u67d4\u6027\u96fb\u5b50\u8207\u8d85\u9ad8\u983b\u5143\u4ef6\u7684\u5922\u5e7b\u6750\u6599\u3002\u540c\u6642\uff0c\u6d3b\u6027\u78b3\u7684\u9ad8\u5b54\u9699\u7387\u5728\u74b0\u5883\u5de5\u7a0b\u7684\u5438\u9644\u8207\u904e\u6ffe\u4e2d\u4ea6\u626e\u6f14\u4e0d\u53ef\u6216\u7f3a\u7684\u89d2\u8272\u3002\x0a\x0a\u78b3\u5728\u6975\u9650\u7269\u7406\u72c0\u614b\u4e0b\u7684\u8868\u73fe\u540c\u6a23\u9a5a\u4eba\u3002\u96d6\u7136\u947d\u77f3\u662f\u81ea\u7136\u754c\u786c\u5ea6\u6700\u9ad8\u7684\u7269\u8cea\uff0c\u4f46\u5728\u7f3a\u6c27\u74b0\u5883\u4e0b\u5c07\u77f3\u58a8\u52a0\u71b1\u81f3\x20\x33\x30\x30\x30\x20\u00b0\x43\x20\u4ee5\u4e0a\uff0c\u77f3\u58a8\u6703\u6607\u83ef\u800c\u975e\u7194\u5316\u3002\u800c\u5728\u5730\u7403\u79d1\u5b78\u4e2d\uff0c\u653e\u5c04\u6027\u540c\u4f4d\u7d20\x20\u00b9\u2074\x43\x20\u7684\u8870\u8b8a\u7279\u6027\x28\u534a\u8870\u671f\u7d04\x20\x35\x37\x33\x30\x20\u5e74\x29\u70ba\u6709\u6a5f\u8003\u53e4\u63d0\u4f9b\u4e86\u7cbe\u78ba\u7684\u6642\u9593\u5c3a\u898f\uff0c\u7a31\u70ba\u300c\u78b3\u5b9a\u5e74\u6cd5\u300d\u3002\u6700\u53cd\u76f4\u89ba\u7684\u73fe\u8c61\u83ab\u904e\u65bc\uff0c\u5118\u7ba1\u947d\u77f3\u5728\u5e38\u6eab\u5e38\u58d3\u4e0b\u88ab\u8a8d\u70ba\u662f\u6c38\u6046\u7684\u8c61\u5fb5\uff0c\u4f46\u5728\u71b1\u529b\u5b78\u4e0a\uff0c\u77f3\u58a8\u624d\u662f\u78b3\u5728\u6a19\u6e96\u72c0\u614b\u4e0b\u6700\u7a69\u5b9a\u7684\u76f8\u3002\u9019\u610f\u5473\u8457\u947d\u77f3\u6b63\u4ee5\u6975\u5176\u7de9\u6162\u7684\u901f\u5ea6\u5411\u77f3\u58a8\u8f49\u5316\uff0c\u53ea\u662f\u5176\u6d3b\u5316\u80fd\u6975\u9ad8\uff0c\u4f7f\u9019\u4e00\u904e\u7a0b\u5728\u4eba\u985e\u6587\u660e\u5c3a\u5ea6\u4e0b\u89c0\u6e2c\u4e0d\u5230\uff0c\u5145\u5206\u9ad4\u73fe\u4e86\u52d5\u529b\u5b78\u8207\u71b1\u529b\u5b78\u4e4b\u9593\u7684\u7cbe\u5f69\u89d2\u529b\u3002",
  "\x4e":
    "\u6c2e\x28\x4e\x69\x74\x72\x6f\x67\x65\x6e\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x4e\uff0c\u539f\u5b50\u5e8f\x20\x37\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u4e8c\u9031\u671f\u3001\u7b2c\x20\x31\x35\x20\u65cf\x28\x70\x20\u5340\u584a\x29\uff0c\u662f\u5730\u7403\u5927\u6c23\u4e2d\u542b\u91cf\u6700\u591a\u7684\u6210\u5206\x28\u7d04\u4f54\x20\x37\x38\x25\x29\u3002\x31\x37\x37\x32\x20\u5e74\u7531\u8607\u683c\u862d\u79d1\u5b78\u5bb6\u9b6f\u745f\u798f\x28\x44\x61\x6e\x69\x65\x6c\x20\x52\x75\x74\x68\x65\x72\x66\x6f\x72\x64\x29\u767c\u73fe\u3002\u5176\u540d\u7a31\u6e90\u65bc\u5e0c\u81d8\u8a9e\u300c\x6e\x69\x74\x72\x6f\x6e\u300d\x28\u785d\u77f3\x29\u8207\u300c\x67\x65\x6e\x65\x73\u300d\x28\u7522\u751f\x29\uff0c\u610f\u6307\u300c\u785d\u77f3\u7684\u4f86\u6e90\u300d\u3002\u96d6\u7136\u6c23\u614b\u6c2e\x28\x4e\u2082\x29\u5728\u5e38\u6eab\u4e0b\u6027\u8cea\u6975\u5176\u60f0\u6027\uff0c\u4f46\u5b83\u537b\u662f\u86cb\u767d\u8cea\u3001\u6838\u9178\u7b49\u751f\u7269\u5206\u5b50\u7684\u95dc\u9375\u7d44\u6210\u5143\u7d20\uff0c\u5728\u751f\u547d\u5faa\u74b0\u8207\u5de5\u696d\u88fd\u7a0b\u4e2d\u7686\u5177\u5099\u7121\u53ef\u53d6\u4ee3\u7684\u5730\u4f4d\u3002\x0a\x0a\u6c2e\u7684\u96fb\u5b50\u7d44\u614b\u70ba\x20\x31\x73\u00b2\x32\x73\u00b2\x32\x70\u00b3\uff0c\u5176\u50f9\u6bbc\u5c64\u534a\u586b\u6eff\u7684\u7279\u5fb5\u8ce6\u4e88\u5176\u7a69\u5b9a\u7684\u96fb\u5b50\u7d50\u69cb\u3002\u6c2e\u5206\u5b50\x28\x4e\u2082\x29\u5167\u542b\u6709\u6975\u5f37\u7684\u5171\u50f9\u4e09\u9375\x28\x4e\u2261\x4e\x29\uff0c\u9375\u80fd\u9ad8\u9054\x20\x39\x34\x31\x20\x6b\x4a\x2f\x6d\x6f\x6c\uff0c\u9019\u4f7f\u5f97\u6c2e\u6c23\u5728\u5927\u591a\u6578\u5316\u5b78\u53cd\u61c9\u4e2d\u8868\u73fe\u5f97\u975e\u5e38\u5b89\u5b9a\uff0c\u5e38\u7528\u4f5c\u534a\u5c0e\u9ad4\u5c01\u88dd\u3001\u98df\u54c1\u4fdd\u9bae\u6216\u5316\u5b78\u5be6\u9a57\u4e2d\u7684\u4fdd\u8b77\u6c23\u9ad4\u3002\u6c2e\u7684\u96fb\u8ca0\u5ea6\u9ad8\u9054\x20\x33\x2e\x30\x34\uff0c\u50c5\u6b21\u65bc\u6c1f\u8207\u6c27\uff0c\u9019\u4f7f\u5176\u80fd\u8207\u6c2b\u5f62\u6210\u986f\u8457\u7684\u300c\u6c2b\u9375\u300d\x28\u5982\u5728\x20\x4e\x48\u2083\x20\u4e2d\x29\uff0c\u5c0d\u5206\u5b50\u7684\u6eb6\u89e3\u5ea6\u8207\u6cb8\u9ede\u7522\u751f\u6c7a\u5b9a\u6027\u5f71\u97ff\u3002\u6b64\u5916\uff0c\u6c2e\u5c55\u73fe\u4e86\u5f9e\x20\x2d\x33\x28\u5982\u6c28\x29\u5230\x20\x2b\x35\x28\u5982\u785d\u9178\x29\u6975\u5176\u5bec\u5ee3\u7684\u6c27\u5316\u614b\u5206\u5e03\uff0c\u662f\u6c27\u5316\u9084\u539f\u5316\u5b78\u4e2d\u7814\u7a76\u50f9\u614b\u8b8a\u5316\u7684\u91cd\u8981\u5c0d\u8c61\u3002\x0a\x0a\u5728\u5de5\u696d\u8207\u74b0\u5883\u9818\u57df\uff0c\u6c2e\u7684\u56fa\u5b9a\u8207\u5faa\u74b0\u662f\u95dc\u9375\u547d\u984c\u3002\u54c8\u67cf\u6cd5\x28\x48\x61\x62\x65\x72\x2d\x42\x6f\x73\x63\x68\x20\x50\x72\x6f\x63\x65\x73\x73\x29\u900f\u904e\u9ad8\u58d3\u9ad8\u6eab\u50ac\u5316\uff0c\u5c07\u5927\u6c23\u4e2d\u7684\x20\x4e\u2082\x20\u8f49\u5316\u70ba\u6c28\x28\x4e\x48\u2083\x29\uff0c\u9019\u4e00\u7a81\u7834\u89e3\u6c7a\u4e86\u5316\u5b78\u80a5\u6599\u7684\u9700\u6c42\uff0c\u652f\u6490\u4e86\u73fe\u4ee3\u5168\u7403\u4eba\u53e3\u7684\u751f\u5b58\u3002\u5728\u53f0\u7063\u9ad8\u4e2d\u8ab2\u7a0b\u4e2d\uff0c\u6c2e\u6c27\u5316\u7269\x28\x4e\x4f\u2093\x29\u8207\u785d\u9178\x28\x48\x4e\x4f\u2083\x29\u7684\u5316\u5b78\u6027\u8cea\u3001\u4ee5\u53ca\u5176\u5728\u9178\u96e8\u5f62\u6210\u8207\u5149\u5316\u5b78\u7159\u9727\u4e2d\u7684\u89d2\u8272\uff0c\u662f\u74b0\u5883\u5316\u5b78\u7684\u91cd\u9ede\u3002\u73fe\u4ee3\u61c9\u7528\u4e2d\uff0c\u6db2\u6c2e\x28\u6cb8\u9ede\x20\x2d\x31\x39\x36\x20\u00b0\x43\x29\u88ab\u5ee3\u6cdb\u7528\u4f5c\u8d85\u5c0e\u6750\u6599\u8207\u751f\u7269\u6a23\u672c\u7684\u4f4e\u6eab\u4fdd\u5b58\u4ecb\u8cea\uff0c\u800c\u5728\u80fd\u6e90\u6280\u8853\u4e0a\uff0c\u9ad8\u80fd\u6c2e\u6750\u6599\x28\u5982\u758a\u6c2e\u5316\u7269\x29\u5247\u662f\u706b\u7bad\u63a8\u9032\u5291\u8207\u5b89\u5168\u6c23\u56ca\u89f8\u767c\u5668\u7684\u6838\u5fc3\u3002\x0a\x0a\u6c2e\u5143\u7d20\u5177\u5099\u67d0\u4e9b\u6975\u7aef\u4e14\u53cd\u76f4\u89ba\u7684\u5316\u5b78\u884c\u70ba\u3002\u4f8b\u5982\uff0c\u96d6\u7136\x20\x4e\u2082\x20\u96e3\u4ee5\u53cd\u61c9\uff0c\u4f46\u56fa\u6c2e\u7d30\u83cc\u537b\u80fd\u5229\u7528\u7cbe\u5de7\u7684\u9176\u7cfb\u7d71\u5728\u5e38\u6eab\u5e38\u58d3\u4e0b\u62c6\u89e3\u6c2e\u6c2e\u4e09\u9375\u3002\u5728\u7206\u70b8\u5316\u5b78\u4e2d\uff0c\u7531\u65bc\x20\x4e\u2082\x20\u5206\u5b50\u6975\u5176\u7a69\u5b9a\uff0c\u8a31\u591a\u542b\u6c2e\u5316\u5408\u7269\x28\u5982\x20\x54\x4e\x54\x20\u6216\u785d\u5316\u7518\u6cb9\x29\u5728\u5206\u89e3\u6210\x20\x4e\u2082\x20\u6642\u6703\u91cb\u653e\u51fa\u6975\u5927\u7684\u53cd\u61c9\u71b1\u8207\u6c23\u9ad4\u9ad4\u7a4d\uff0c\u9019\u6b63\u662f\u70b8\u85e5\u5a01\u529b\u7684\u4f86\u6e90\u3002\u6709\u8da3\u7684\u662f\uff0c\u5728\u6975\u9ad8\u58d3\u74b0\u5883\u4e0b\x28\u7d04\u767e\u842c\u5927\u6c23\u58d3\x29\uff0c\u6c2e\u53ef\u4ee5\u8f49\u8b8a\u70ba\u55ae\u9375\u9023\u63a5\u7684\u6676\u9ad4\u7db2\u7d61\x28\u805a\u5408\u6c2e\x29\uff0c\u5176\u80fd\u91cf\u5bc6\u5ea6\u9060\u9ad8\u65bc\u4efb\u4f55\u5df2\u77e5\u5316\u5b78\u7269\u8cea\uff0c\u88ab\u79d1\u5b78\u5bb6\u9810\u6e2c\u70ba\u6f5b\u5b58\u7684\u672a\u4f86\u9ad8\u6548\u80fd\u6e05\u6f54\u71c3\u6599\u3002\u9019\u7a2e\u7531\u300c\u6975\u81f4\u7a69\u5b9a\u300d\u5230\u300c\u6975\u81f4\u52d5\u614b\u300d\u7684\u8f49\u8b8a\uff0c\u7cbe\u78ba\u8a6e\u91cb\u4e86\u6c2e\u5143\u7d20\u5728\u5316\u5b78\u4e16\u754c\u4e2d\u7684\u96d9\u91cd\u6027\u683c\u3002",
  "\x4f":
    "\u6c27\x28\x4f\x78\x79\x67\x65\x6e\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x4f\uff0c\u539f\u5b50\u5e8f\x20\x38\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u4e8c\u9031\u671f\u3001\u7b2c\x20\x31\x36\x20\u65cf\x28\u6c27\u65cf\u5143\u7d20\uff0c\x70\x20\u5340\u584a\x29\uff0c\u662f\u5730\u6bbc\u4e2d\u542b\u91cf\u6700\u8c50\u5bcc\u4e14\u5c0d\u751f\u547d\u81f3\u95dc\u91cd\u8981\u7684\u975e\u91d1\u5c6c\u5143\u7d20\u3002\x31\x37\x37\x30\x20\u5e74\u4ee3\uff0c\u666e\u5229\u65af\u7279\u91cc\x28\x4a\x6f\x73\x65\x70\x68\x20\x50\x72\x69\x65\x73\x74\x6c\x65\x79\x29\u8207\u820d\u52d2\x28\x43\x61\x72\x6c\x20\x57\x69\x6c\x68\x65\x6c\x6d\x20\x53\x63\x68\x65\x65\x6c\x65\x29\u5206\u5225\u7368\u7acb\u767c\u73fe\u4e86\u6c27\u6c23\uff1b\u96a8\u5f8c\u62c9\u74e6\u7bc0\x28\x41\x6e\x74\x6f\x69\x6e\x65\x20\x4c\x61\x76\x6f\x69\x73\x69\x65\x72\x29\u6b63\u78ba\u6307\u51fa\u5176\u5728\u71c3\u71d2\u8207\u547c\u5438\u4e2d\u7684\u89d2\u8272\uff0c\u4e26\u7d50\u5408\u5e0c\u81d8\u8a9e\u5b57\u6839\u300c\x6f\x78\x79\x73\u300d\x28\u9178\x29\u8207\u300c\x67\x65\x6e\x65\x73\u300d\x28\u7522\u751f\u8005\x29\u5c07\u5176\u547d\u540d\u70ba\u300c\x4f\x78\x79\x67\x65\x6e\u300d\uff0c\u8aa4\u4ee5\u70ba\u6c27\u662f\u6240\u6709\u9178\u985e\u5fc5\u5099\u7684\u6210\u5206\u3002\u6c27\u5728\u81ea\u7136\u754c\u4e3b\u8981\u4ee5\u96d9\u539f\u5b50\u5206\u5b50\x28\x4f\u2082\x29\u5f62\u5f0f\u5b58\u5728\uff0c\u5728\u5927\u6c23\u9ad8\u5c64\u5247\u5b58\u5728\u540c\u7d20\u7570\u5f62\u9ad4\u81ed\u6c27\x28\x4f\u2083\x29\uff0c\u5169\u8005\u5c0d\u5730\u7403\u751f\u614b\u5c4f\u969c\u8207\u80fd\u91cf\u4ee3\u8b1d\u7686\u5177\u5099\u6838\u5fc3\u5730\u4f4d\u3002\x0a\x0a\u6c27\u7684\u57fa\u614b\u96fb\u5b50\u7d44\u614b\u70ba\x20\x31\x73\u00b2\x20\x32\x73\u00b2\x20\x32\x70\u2074\uff0c\u5176\u96fb\u8ca0\u5ea6\u9ad8\u9054\x20\x33\x2e\x34\x34\uff0c\u5728\u5168\u9031\u671f\u8868\u4e2d\u50c5\u6b21\u65bc\u6c1f\u3002\u9019\u7a2e\u6975\u5f37\u7684\u596a\u53d6\u96fb\u5b50\u80fd\u529b\u4f7f\u5176\u6210\u70ba\u512a\u7570\u7684\u6c27\u5316\u5291\uff0c\u80fd\u8207\u9664\u5c11\u6578\u7a00\u6709\u6c23\u9ad4\u5916\u7684\u7d55\u5927\u591a\u6578\u5143\u7d20\u5f62\u6210\u6c27\u5316\u7269\u3002\u5728\u5316\u5b78\u9375\u7d50\u4e2d\uff0c\u6c27\u80fd\u5f62\u6210\u986f\u8457\u7684\u6c2b\u9375\x28\x48\x79\x64\x72\x6f\x67\x65\x6e\x20\x42\x6f\x6e\x64\x69\x6e\x67\x29\uff0c\u9019\u4e0d\u50c5\u8ce6\u4e88\u4e86\u6c34\x28\x48\u2082\x4f\x29\u7570\u5e38\u7684\u9ad8\u6cb8\u9ede\uff0c\u4ea6\u662f\u751f\u7269\u5316\u5b78\u53cd\u61c9\u4e2d\u5206\u5b50\u8fa8\u8b58\u7684\u7269\u7406\u57fa\u790e\u3002\u503c\u5f97\u6ce8\u610f\u7684\u662f\uff0c\u6839\u64da\u5206\u5b50\u8ecc\u57df\u7406\u8ad6\x28\x4d\x4f\x20\x54\x68\x65\x6f\x72\x79\x29\uff0c\u6c27\u5206\u5b50\x28\x4f\u2082\x29\u5177\u6709\u5169\u500b\u672a\u6210\u5c0d\u96fb\u5b50\uff0c\u9019\u4f7f\u5176\u5728\u6db2\u614b\u6642\u5448\u73fe\u6de1\u85cd\u8272\u4e14\u5177\u5099\u300c\u9806\u78c1\u6027\u300d\x28\x50\x61\x72\x61\x6d\x61\x67\x6e\x65\x74\x69\x73\x6d\x29\uff0c\u80fd\u88ab\u5f37\u78c1\u5834\u5438\u5f15\uff0c\u9019\u8207\u50b3\u7d71\u8def\u6613\u65af\u7d50\u69cb\u5f0f\u9810\u6e2c\u7684\u6210\u5c0d\u96fb\u5b50\u73fe\u8c61\u622a\u7136\u4e0d\u540c\u3002\x0a\x0a\u5728\u53f0\u7063\u9ad8\u4e2d\u5316\u5b78\u8ab2\u7a0b\u4e2d\uff0c\u6c27\u662f\u5b9a\u7fa9\u6c27\u5316\u9084\u539f\u53cd\u61c9\u8207\u71c3\u71d2\u71b1\u7684\u57fa\u6e96\u5143\u7d20\u3002\u73fe\u4ee3\u79d1\u6280\u4e2d\uff0c\u6c27\u7684\u61c9\u7528\u5f9e\u50b3\u7d71\u92fc\u9435\u7cbe\u7149\x28\u8f49\u7210\u7149\u92fc\x29\u5ef6\u4f38\u81f3\u9ad8\u7aef\u80fd\u6e90\u8207\u74b0\u4fdd\u6280\u8853\u3002\u4f8b\u5982\uff0c\u300c\u8cea\u5b50\u4ea4\u63db\u819c\u71c3\u6599\u96fb\u6c60\u300d\x28\x50\x45\x4d\x46\x43\x29\u5229\u7528\u6c27\u6c23\u4f5c\u70ba\u9670\u6975\u53cd\u61c9\u7269\uff0c\u8207\u6c2b\u7d50\u5408\u7522\u751f\u96fb\u6d41\u4e26\u6392\u51fa\u7d14\u6c34\u3002\u6b64\u5916\uff0c\u9ad8\u7d14\u5ea6\u6c27\u6c23\u5728\u534a\u5c0e\u9ad4\u7522\u696d\u4e2d\u7528\u65bc\u77fd\u6676\u5713\u7684\u300c\u71b1\u6c27\u5316\u88fd\u7a0b\u300d\x28\x54\x68\x65\x72\x6d\x61\x6c\x20\x4f\x78\x69\x64\x61\x74\x69\x6f\x6e\x29\uff0c\u4ee5\u751f\u9577\u95dc\u9375\u7684\u4e8c\u6c27\u5316\u77fd\u7d55\u7de3\u5c64\u3002\u5728\u74b0\u5883\u79d1\u5b78\u4e2d\uff0c\u6eb6\u6c27\u91cf\x28\x44\x4f\x29\u8207\u751f\u5316\u9700\u6c27\u91cf\x28\x42\x4f\x44\x29\u5247\u662f\u8a55\u4f30\u6c34\u9ad4\u6c61\u67d3\u7a0b\u5ea6\u7684\u6838\u5fc3\u6307\u6a19\uff0c\u76f4\u63a5\u53cd\u6620\u4e86\u751f\u614b\u7cfb\u7d71\u7684\u5065\u5eb7\u72c0\u6cc1\u3002\x0a\x0a\u6c27\u5c55\u73fe\u4e86\u591a\u6a23\u4e14\u6975\u7aef\u7684\u5316\u5b78\u7279\u5fb5\u3002\u96d6\u7136\u6c27\u6c23\u652f\u6301\u751f\u547d\uff0c\u4f46\u9ad8\u6fc3\u5ea6\u7684\u6d3b\u6027\u6c27\x28\x52\x4f\x53\x29\u5982\u81ea\u7531\u57fa\uff0c\u537b\u662f\u5c0e\u81f4\u751f\u7269\u8001\u5316\u8207\u6750\u6599\u8150\u8755\x28\u6c27\u5316\x29\u7684\u4e3b\u56e0\uff0c\u9019\u4fc3\u4f7f\u4e86\u6750\u6599\u79d1\u5b78\u4e2d\u6297\u6c27\u5316\u5857\u5c64\u8207\u751f\u91ab\u6297\u6c27\u5316\u5291\u7684\u7814\u767c\u3002\u53cd\u76f4\u89ba\u7684\u662f\uff0c\u6c27\u6c23\u96d6\u7136\u652f\u6301\u71c3\u71d2\uff0c\u4f46\u5176\u672c\u8eab\u4e26\u4e0d\u5177\u5099\u53ef\u71c3\u6027\u3002\u6b64\u5916\uff0c\u81ed\u6c27\x28\x4f\u2083\x29\u96d6\u7136\u5728\u5e73\u6d41\u5c64\u5438\u6536\u7d2b\u5916\u7dda\u5b88\u8b77\u751f\u547d\uff0c\u4f46\u5728\u5c0d\u6d41\u5c64\u537b\u662f\u5f37\u70c8\u523a\u6fc0\u547c\u5438\u9053\u7684\u6c61\u67d3\u7269\uff0c\u5c55\u73fe\u51fa\u300c\u4f4d\u7f6e\u6c7a\u5b9a\u6027\u8cea\u300d\u7684\u74b0\u5883\u7279\u5fb5\u3002\u9019\u7a2e\u5f9e\u7dad\u6301\u547c\u5438\u5230\u9a45\u52d5\u5de5\u696d\u7cbe\u5bc6\u88fd\u7a0b\u7684\u591a\u91cd\u8eab\u5206\uff0c\u4f7f\u6c27\u6210\u70ba\u5316\u5b78\u7814\u7a76\u4e2d\u6700\u57fa\u790e\u537b\u4e5f\u6700\u8907\u96dc\u7684\u5c0d\u8c61\u3002",
  "\x46":
    "\u6c1f\x28\x46\x6c\x75\x6f\x72\x69\x6e\x65\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x46\uff0c\u539f\u5b50\u5e8f\x20\x39\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u4e8c\u9031\u671f\u3001\u7b2c\x20\x31\x37\x20\u65cf\x28\u9e75\u7d20\uff0c\x70\x20\u5340\u584a\x29\uff0c\u662f\u81ea\u7136\u754c\u4e2d\u5316\u5b78\u6027\u8cea\u6700\u6d3b\u6f51\u4e14\u96fb\u8ca0\u5ea6\u6700\u5f37\u7684\u5143\u7d20\u3002\u5176\u540d\u7a31\u6e90\u65bc\u62c9\u4e01\u8a9e\u300c\x66\x6c\x75\x65\x72\x65\u300d\x28\u6d41\u52d5\x29\uff0c\u521d\u8877\u662f\u6307\u5176\u4e3b\u8981\u7926\u77f3\u87a2\u77f3\x28\x43\x61\x46\u2082\x29\u5728\u51b6\u91d1\u4e2d\u4f5c\u70ba\u52a9\u7194\u5291\u7684\u7279\u6027\u3002\u7531\u65bc\u6c1f\u6c23\x28\x46\u2082\x29\u6975\u5176\u66b4\u70c8\u7684\u53cd\u61c9\u6027\uff0c\u8a31\u591a\u65e9\u671f\u5316\u5b78\u5bb6\u5728\u5617\u8a66\u5206\u96e2\u5b83\u6642\u4e0d\u5e78\u4e2d\u6bd2\u6216\u53d7\u50b7\uff0c\u76f4\u5230\x20\x31\x38\x38\x36\x20\u5e74\u83ab\u74e6\u6851\x28\x48\x65\x6e\x72\x69\x20\x4d\x6f\x69\x73\x73\x61\x6e\x29\u624d\u900f\u904e\u4f4e\u6eab\u96fb\u89e3\u6c1f\u5316\u6c2b\u9240\u6eb6\u6db2\u6210\u529f\u5206\u96e2\u51fa\u9019\u7a2e\u6de1\u9ec3\u8272\u6c23\u9ad4\uff0c\u4e26\u56e0\u6b64\u7372\u5f97\u8afe\u8c9d\u723e\u734e\u3002\u56e0\u5176\u5e7e\u4e4e\u80fd\u8207\u4efb\u4f55\u7269\u8cea\u53cd\u61c9\u7684\u7279\u6027\uff0c\u6c1f\u5728\u5316\u5b78\u754c\u7d20\u6709\u300c\u5316\u5b78\u4e4b\u864e\u300d\u7684\u7a31\u865f\u3002\x0a\x0a\u6c1f\u7684\u96fb\u5b50\u7d44\u614b\u70ba\x20\x31\x73\u00b2\x20\x32\x73\u00b2\x20\x32\x70\u2075\uff0c\u5176\u96fb\u8ca0\u5ea6\u9ad8\u9054\x20\x33\x2e\x39\x38\uff0c\u5c45\u5168\u5143\u7d20\u4e4b\u51a0\u3002\u6975\u5c0f\u7684\u539f\u5b50\u534a\u5f91\u8207\u6975\u5f37\u7684\u6838\u5c0d\u50f9\u96fb\u5b50\u5438\u5f15\u529b\uff0c\u4f7f\u6c1f\u80fd\u8207\u5e7e\u4e4e\u6240\u6709\u5143\u7d20\u5f62\u6210\u5316\u5408\u7269\uff0c\u751a\u81f3\u80fd\u8feb\u4f7f\u90e8\u5206\u7a00\u6709\u6c23\u9ad4\x28\u5982\u6c19\x29\u53c3\u8207\u5316\u5b78\u9375\u7d50\u3002\u5728\u6c2b\u9375\u89c0\u5ff5\u4e2d\uff0c\u6c1f\u5316\u6c2b\x28\x48\x46\x29\u80fd\u5f62\u6210\u6975\u5f37\u7684\u6c2b\u9375\uff0c\u5c0e\u81f4\u5176\u5728\u6c34\u4e2d\u5448\u73fe\u5f31\u9178\u6027\x28\u4e0d\u540c\u65bc\u5176\u4ed6\u6c2b\u9e75\u9178\u7684\u5f37\u9178\u6027\x29\uff0c\u4e14\u5206\u5b50\u9593\u9ad8\u5ea6\u7de0\u5408\u3002\u6c1f\u96e2\u5b50\x28\x46\u207b\x29\u5177\u6709\u6975\u4f73\u7684\u5316\u5b78\u7a69\u5b9a\u6027\u8207\u8f03\u5c0f\u7684\u96e2\u5b50\u534a\u5f91\uff0c\u80fd\u8f15\u6613\u66ff\u63db\u751f\u7269\u6750\u6599\u6216\u7926\u7269\u6676\u683c\u4e2d\u7684\u7fa5\u57fa\uff0c\u4f8b\u5982\u5728\u7259\u9f52\u8868\u9762\u5f62\u6210\u6297\u9178\u8755\u7684\u6c1f\u78f7\u7070\u77f3\uff0c\u9019\u4e5f\u662f\u98f2\u6c34\u52a0\u6c1f\u9810\u9632\u9f72\u9f52\u7684\u79d1\u5b78\u4f9d\u64da\u3002\x0a\x0a\u73fe\u4ee3\u6750\u6599\u79d1\u5b78\u5c0d\u6c1f\u7684\u4f9d\u8cf4\u7a0b\u5ea6\u6975\u9ad8\u3002\u805a\u56db\u6c1f\u4e59\u70ef\x28\x50\x54\x46\x45\uff0c\u4fd7\u7a31\u7279\u6c1f\u9f8d\x29\u5177\u5099\u6975\u4f73\u7684\u8010\u5316\u5b78\u8150\u8755\u6027\u8207\u4f4e\u6469\u64e6\u4fc2\u6578\uff0c\u662f\u5be6\u9a57\u5ba4\u9ad8\u6eab\u9ad8\u9178\u9e7c\u74b0\u5883\u8207\u822a\u592a\u5143\u4ef6\u7684\u91cd\u8981\u5857\u5c64\u3002\u5728\u534a\u5c0e\u9ad4\u8207\u5fae\u96fb\u5b50\u9818\u57df\uff0c\u6c1f\u57fa\u6c23\u9ad4\x28\u5982\x20\x53\x46\u2086\u3001\x4e\x46\u2083\x29\u662f\u7cbe\u5bc6\u8755\u523b\u6280\u8853\u7684\u6838\u5fc3\uff0c\u7528\u65bc\u7cbe\u78ba\u96d5\u523b\u6676\u5713\u8868\u9762\u7d50\u69cb\u3002\u6b64\u5916\uff0c\u6c1f\u5728\u92f0\u96e2\u5b50\u96fb\u6c60\u4e2d\u626e\u6f14\u95dc\u9375\u89d2\u8272\uff0c\u5176\u96fb\u89e3\u8cea\u9e7d\u985e\u5982\u516d\u6c1f\u78f7\u9178\u92f0\x28\x4c\x69\x50\x46\u2086\x29\uff0c\u5229\u7528\u6c1f\u539f\u5b50\u7684\u96fb\u8ca0\u5ea6\u63d0\u5347\u96fb\u5316\u5b78\u7a69\u5b9a\u6027\u8207\u96e2\u5b50\u50b3\u5c0e\u6548\u7387\uff0c\u76f4\u63a5\u5f71\u97ff\u4e86\u884c\u52d5\u88dd\u7f6e\u8207\u96fb\u52d5\u8eca\u7684\u7e8c\u822a\u8868\u73fe\u3002\x0a\x0a\u6c1f\u5c55\u73fe\u4e86\u8a31\u591a\u6975\u81f4\u7684\u7269\u7406\u5316\u5b78\u73fe\u8c61\u3002\u78b3\uff0d\u6c1f\u9375\x28\x43\x2d\x46\x20\x42\x6f\x6e\x64\x29\u662f\u5df2\u77e5\u6709\u6a5f\u5316\u5b78\u4e2d\u6700\u5f37\u7684\u5171\u50f9\u9375\u4e4b\u4e00\uff0c\u9019\u8ce6\u4e88\u4e86\u5168\u6c1f\u5316\u5408\u7269\x28\x50\x46\x41\x53\x29\u6975\u7aef\u7684\u7a69\u5b9a\u6027\uff0c\u537b\u4e5f\u4f7f\u5176\u6210\u70ba\u74b0\u5883\u4e2d\u96e3\u4ee5\u964d\u89e3\u7684\u300c\u6c38\u4e45\u5316\u5b78\u7269\u8cea\u300d\uff0c\u5f15\u767c\u73fe\u4ee3\u74b0\u5883\u5de5\u7a0b\u5c0d\u6c1f\u5faa\u74b0\u7684\u6df1\u5ea6\u53cd\u601d\u3002\u5728\u6838\u5de5\u696d\u4e2d\uff0c\u516d\u6c1f\u5316\u923e\x28\x55\x46\u2086\x29\u56e0\u5177\u5099\u63ee\u767c\u6027\uff0c\u6210\u70ba\u5206\u96e2\u923e\u540c\u4f4d\u7d20\u4ee5\u88fd\u9020\u71c3\u6599\u7684\u6838\u5fc3\u4ecb\u8cea\u3002\u6709\u8da3\u7684\u662f\uff0c\u96d6\u7136\u6c1f\u6c23\u80fd\u8b93\u92fc\u68c9\u81ea\u71c3\u751a\u81f3\u8b93\u6c34\u71c3\u71d2\uff0c\u4f46\u5176\u96e2\u5b50\u5f62\u614b\u537b\u6975\u5ea6\u7a69\u5b9a\u4e14\u5b89\u5168\uff0c\u9019\u7a2e\u7531\u300c\u6975\u5ea6\u4e0d\u5b89\u300d\u5230\u300c\u6975\u5ea6\u7a69\u5b9a\u300d\u7684\u6027\u8cea\u8f49\u8b8a\uff0c\u5145\u5206\u9ad4\u73fe\u4e86\u539f\u5b50\u6838\u5c0d\u96fb\u5b50\u638c\u63a7\u529b\u5c0d\u7269\u8cea\u7279\u6027\u7684\u6c7a\u5b9a\u6027\u5f71\u97ff\u3002",
  "\x4e\x65":
    "\u6c16\x28\x4e\x65\x6f\x6e\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x4e\x65\uff0c\u539f\u5b50\u5e8f\x20\x31\x30\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u4e8c\u9031\u671f\u3001\u7b2c\x20\x31\x38\x20\u65cf\x28\u7a00\u6709\u6c23\u9ad4\uff0c\x70\x20\u5340\u584a\x29\u3002\x31\x38\x39\x38\x20\u5e74\u7531\u82f1\u570b\u5316\u5b78\u5bb6\u62c9\u59c6\u9f4a\x28\x57\x69\x6c\x6c\x69\x61\x6d\x20\x52\x61\x6d\x73\x61\x79\x29\u8207\u7279\u62c9\u5f17\u65af\x28\x4d\x6f\x72\x72\x69\x73\x20\x54\x72\x61\x76\x65\x72\x73\x29\u5728\u6db2\u614b\u7a7a\u6c23\u7684\u5206\u993e\u6b98\u9918\u7269\u4e2d\u767c\u73fe\u3002\u5176\u540d\u7a31\u6e90\u65bc\u5e0c\u81d8\u8a9e\u300c\x6e\x65\x6f\x73\u300d\uff0c\u610f\u70ba\u300c\u65b0\u300d\u3002\u6c16\u5728\u5730\u7403\u5927\u6c23\u4e2d\u7684\u542b\u91cf\u7a00\u5c11\x28\u50c5\u7d04\x20\x31\x38\x20\x70\x70\x6d\x29\uff0c\u4f46\u5728\u5168\u5b87\u5b99\u7684\u5143\u7d20\u8c50\u5ea6\u4e2d\u537b\u4f4d\u5c45\u7b2c\u4e94\u3002\u5b83\u662f\u5178\u578b\u7684\u9ad8\u5ea6\u60f0\u6027\u5143\u7d20\uff0c\u5728\u6a19\u6e96\u72c0\u614b\u4e0b\u70ba\u7121\u8272\u3001\u7121\u5473\u7684\u55ae\u539f\u5b50\u6c23\u9ad4\uff0c\u50c5\u5728\u7279\u5b9a\u9ad8\u80fd\u7269\u7406\u689d\u4ef6\u6216\u6975\u7aef\u5be6\u9a57\u5ba4\u74b0\u5883\u4e0b\u624d\u53ef\u80fd\u5c55\u73fe\u5fae\u5f31\u7684\u9375\u7d50\u8da8\u5411\u3002\x0a\x0a\u6c16\u7684\u96fb\u5b50\u7d44\u614b\u70ba\x20\x31\x73\u00b2\x20\x32\x73\u00b2\x20\x32\x70\u2076\uff0c\u9054\u6210\u4e86\u5b8c\u7f8e\u7684\u516b\u9685\u9ad4\x28\x4f\x63\x74\x65\x74\x20\x52\x75\x6c\x65\x29\u7a69\u5b9a\u7d50\u69cb\u3002\u5176\u7b2c\u4e00\u96fb\u96e2\u80fd\u6975\u9ad8\uff0c\u4e14\u96fb\u8ca0\u5ea6\u5728\u5be6\u969b\u5316\u5b78\u610f\u7fa9\u4e0a\u5e7e\u4e4e\u70ba\u96f6\uff0c\u9019\u4f7f\u5f97\u6c16\u539f\u5b50\u4e0d\u50be\u5411\u8207\u4efb\u4f55\u5143\u7d20\u5206\u4eab\u6216\u8f49\u79fb\u96fb\u5b50\u3002\u6c16\u7684\u5316\u5b78\u6027\u8cea\u6975\u5176\u55ae\u7d14\uff0c\u9019\u4f7f\u5176\u5728\u9ad8\u4e2d\u8ab2\u7a0b\u4e2d\u6210\u70ba\u5b9a\u7fa9\u300c\u539f\u5b50\u7d50\u69cb\u7a69\u5b9a\u6027\u300d\u8207\u300c\u55ae\u539f\u5b50\u5206\u5b50\u5f62\u5f0f\u5b58\u5728\u300d\u7684\u6700\u4f73\u7bc4\u4f8b\u3002\u5176\u6cb8\u9ede\u50c5\u70ba\x20\x32\x37\x2e\x31\x20\x4b\x28\u7d04\x20\x2d\x32\x34\x36\x20\u00b0\x43\x29\uff0c\u5728\u6db2\u614b\u6642\u5177\u5099\u512a\u7570\u7684\u88fd\u51b7\u80fd\u529b\uff0c\u5176\u55ae\u4f4d\u9ad4\u7a4d\u7684\u88fd\u51b7\u6548\u7387\u7d04\u70ba\u6db2\u6c26\u7684\x20\x34\x30\x20\u500d\u3001\u6db2\u6c2b\u7684\x20\x33\x20\u500d\uff0c\u5728\u4f4e\u6eab\u5de5\u7a0b\u4e2d\u5177\u6709\u986f\u8457\u7684\u71b1\u529b\u5b78\u512a\u52e2\u3002\x0a\x0a\u5728\u5de5\u696d\u8207\u5149\u96fb\u61c9\u7528\u4e0a\uff0c\u6c16\u6700\u77e5\u540d\u7684\u7279\u6027\u662f\u5176\u5728\u771f\u7a7a\u653e\u96fb\u7ba1\u4e2d\u6703\u767c\u51fa\u6975\u5177\u8fa8\u8b58\u5ea6\u7684\u6a58\u7d05\u8272\u5149\u8292\u3002\u9019\u7a2e\u7279\u5fb5\u8b5c\u7dda\u6e90\u65bc\u96fb\u5b50\u53d7\u6fc0\u5f8c\u56de\u6b78\u57fa\u614b\u91cb\u653e\u7684\u7279\u5b9a\u80fd\u91cf\uff0c\u6210\u70ba\u300c\u9713\u8679\u71c8\u300d\x28\x4e\x65\x6f\x6e\x20\x4c\x69\x67\x68\x74\x73\x29\u4e00\u8a5e\u7684\u8d77\u6e90\u3002\u5118\u7ba1\u73fe\u4ee3\u5f69\u8272\u71c8\u5177\u5e38\u586b\u5145\u5176\u4ed6\u6c23\u9ad4\u6216\u87a2\u5149\u7c89\uff0c\u4f46\u6b63\u5b97\u7684\u4eae\u6a59\u8272\u5149\u59cb\u7d42\u4f86\u81ea\u7d14\u6c16\u3002\u5728\u73fe\u4ee3\u9ad8\u79d1\u6280\u9818\u57df\uff0c\u6c16\u662f\u534a\u5c0e\u9ad4\u300c\u6e96\u5206\u5b50\u96f7\u5c04\u300d\x28\x45\x78\x63\x69\x6d\x65\x72\x20\x4c\x61\x73\x65\x72\x29\u88fd\u7a0b\u4e0d\u53ef\u6216\u7f3a\u7684\u6210\u5206\uff0c\u7279\u5225\u662f\u5728\u6df1\u7d2b\u5916\u5149\x28\x44\x55\x56\x29\u66dd\u5149\u6a5f\u4e2d\uff0c\u6c16\u4f5c\u70ba\u8f09\u6c23\u5354\u52a9\u6c26\u6c16\u96f7\u5c04\u7a69\u5b9a\u904b\u884c\uff0c\u9019\u4f7f\u6c16\u7684\u4f9b\u61c9\u93c8\u7a69\u5b9a\u5ea6\u6210\u70ba\u5168\u7403\u6676\u7247\u7522\u80fd\u7684\u95dc\u9375\u6307\u6a19\u3002\x0a\x0a\u6c16\u5c55\u73fe\u51fa\u7a00\u6709\u6c23\u9ad4\u5bb6\u65cf\u4e2d\u6975\u81f4\u7684\u7269\u7406\u7d14\u7cb9\u6027\u3002\u5b83\u662f\u6240\u6709\u5143\u7d20\u4e2d\u53cd\u61c9\u6027\u6700\u4f4e\u7684\u6210\u54e1\u4e4b\u4e00\uff0c\u76ee\u524d\u5c1a\u672a\u5728\u5927\u6c23\u4e2d\u767c\u73fe\u4efb\u4f55\u81ea\u7136\u5b58\u5728\u7684\u6c16\u5316\u5408\u7269\u3002\u5728\u5730\u7403\u7269\u7406\u5b78\u4e2d\uff0c\u7531\u65bc\u6c16\u662f\u5316\u5b78\u60f0\u6027\u7684\u4e14\u4e0d\u53c3\u8207\u751f\u7269\u5faa\u74b0\uff0c\u5730\u6bbc\u8207\u5927\u6c23\u4e2d\u6c16\u540c\u4f4d\u7d20\x28\u5982\x20\u00b2\u2070\x4e\x65\x2c\x20\u00b2\u00b9\x4e\x65\x2c\x20\u00b2\u00b2\x4e\x65\x29\u7684\u7d44\u6210\u6bd4\u4f8b\uff0c\u88ab\u79d1\u5b78\u5bb6\u4f5c\u70ba\u7814\u7a76\u884c\u661f\u8d77\u6e90\u8207\u706b\u5c71\u6392\u6c23\u7684\u91cd\u8981\u5316\u5b78\u6a19\u8a18\u3002\u6b64\u5916\uff0c\u6c16\u6c23\u96d6\u7136\u5bc6\u5ea6\u6bd4\u7a7a\u6c23\u5c0f\uff0c\u4f46\u8207\u6c26\u6c23\u4e0d\u540c\uff0c\u5b83\u4e0d\u6703\u4f7f\u8072\u5e36\u632f\u52d5\u983b\u7387\u5347\u9ad8\u5230\u7522\u751f\u660e\u986f\u7684\u300c\u5510\u8001\u9d28\u8072\u97f3\u300d\u6548\u679c\uff0c\u9019\u6e90\u65bc\u5176\u76f8\u5c0d\u5206\u5b50\u91cf\u8207\u7a7a\u6c23\u8f03\u70ba\u63a5\u8fd1\u3002\u9019\u7a2e\u65e2\u96b1\u8eab\u65bc\u5927\u6c23\u3001\u53c8\u986f\u8000\u65bc\u79d1\u6280\u7684\u5149\u5b78\u7279\u5fb5\uff0c\u4f7f\u6c16\u6210\u70ba\u5fae\u89c0\u7a69\u5b9a\u8207\u5b8f\u89c0\u61c9\u7528\u7d50\u5408\u7684\u8c61\u5fb5\u3002",
  "\x4e\x61":
    "\u9209\x28\x53\x6f\x64\x69\x75\x6d\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x4e\x61\uff0c\u539f\u5b50\u5e8f\x20\x31\x31\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u4e09\u9031\u671f\u3001\u7b2c\x20\x31\x20\u65cf\x28\u9e7c\u91d1\u5c6c\uff0c\x73\x20\u5340\u584a\x29\u3002\u5176\u540d\u7a31\u6e90\u65bc\u62c9\u4e01\u8a9e\u300c\x4e\x61\x74\x72\x69\x75\x6d\u300d\uff0c\u6700\u65e9\u6307\u57c3\u53ca\u9e7d\u6e56\u7522\u51fa\u7684\u5929\u7136\u9e7c\x28\x4e\x61\x74\x72\x6f\x6e\x29\uff0c\u800c\u82f1\u6587\u540d\u7a31\x20\x53\x6f\x64\x69\x75\x6d\x20\u5247\u6e90\u65bc\u8607\u6253\x28\x53\x6f\x64\x61\x29\u3002\x31\x38\x30\x37\x20\u5e74\uff0c\u82f1\u570b\u5316\u5b78\u5bb6\u6234\u7dad\x28\x48\x75\x6d\x70\x68\x72\x79\x20\x44\x61\x76\x79\x29\u900f\u904e\u96fb\u89e3\u7194\u878d\u6c2b\u6c27\u5316\u9209\u9996\u6b21\u5206\u96e2\u51fa\u91d1\u5c6c\u9209\u3002\u5728\u81ea\u7136\u754c\u4e2d\uff0c\u9209\u56e0\u6975\u5f37\u7684\u5316\u5b78\u6d3b\u6027\u800c\u4e0d\u4ee5\u6e38\u96e2\u614b\u5b58\u5728\uff0c\u4e3b\u8981\u4ee5\u6c2f\u5316\u9209\x28\x4e\x61\x43\x6c\x29\u7684\u5f62\u5f0f\u5ee3\u6cdb\u5206\u5e03\u65bc\u6d77\u6c34\u8207\u9e7d\u7926\u4e2d\uff0c\u662f\u7dad\u6301\u7d30\u80de\u6ef2\u900f\u58d3\u8207\u795e\u7d93\u50b3\u5c0e\u4e0d\u53ef\u6216\u7f3a\u7684\u751f\u7269\u5143\u7d20\u3002\x0a\x0a\u5728\u5316\u5b78\u884c\u70ba\u4e0a\uff0c\u9209\u7684\u96fb\u5b50\u7d44\u614b\u70ba\x20\x5b\x4e\x65\x5d\x33\x73\u00b9\uff0c\u50c5\u9700\u5931\u53bb\u4e00\u500b\u50f9\u96fb\u5b50\u5373\u53ef\u9054\u6210\u7a69\u5b9a\u7684\u516b\u9685\u9ad4\u7d50\u69cb\uff0c\u56e0\u6b64\u5177\u6709\u6975\u4f4e\u7684\u7b2c\u4e00\u96fb\u96e2\u80fd\u8207\u5f37\u9084\u539f\u6027\u3002\u9209\u5728\u9ad8\u4e2d\u5316\u5b78\u5be6\u9a57\u4e2d\u5c55\u73fe\u51fa\u9bae\u660e\u7684\u7279\u5fb5\uff1a\u5176\u706b\u7130\u53cd\u61c9\x28\x46\x6c\x61\x6d\x65\x20\x74\x65\x73\x74\x29\u5448\u73fe\u660e\u4eae\u7684\u7279\u5fb5\u9ec3\u8272\uff1b\u8207\u6c34\u53cd\u61c9\u6642\u6703\u5287\u70c8\u6d6e\u65bc\u6c34\u9762\x28\u5bc6\u5ea6\x20\x30\x2e\x39\x37\x20\x67\x2f\x63\x6d\u00b3\x20\u5c0f\u65bc\u6c34\x29\uff0c\u4e26\u7522\u751f\u6c2b\u6c23\u8207\u5f37\u9e7c\u6027\u7684\u6c2b\u6c27\u5316\u9209\uff0c\u91cb\u653e\u7684\u53cd\u61c9\u71b1\u8db3\u4ee5\u4f7f\u9209\u7194\u5316\u6210\u9280\u767d\u8272\u7403\u72c0\u3002\u70ba\u4e86\u9632\u6b62\u8207\u7a7a\u6c23\u4e2d\u7684\u6c27\u6c23\u6216\u6c34\u84b8\u6c23\u53cd\u61c9\uff0c\u5be6\u9a57\u5ba4\u4e2d\u5fc5\u9808\u5c07\u9209\u4fdd\u5b58\u5728\u7926\u7269\u6cb9\u6216\u7164\u6cb9\u4e2d\u3002\x0a\x0a\u5728\u96fb\u5316\u5b78\u8207\u5de5\u696d\u61c9\u7528\u4e0a\uff0c\u9209\u7684\u6a19\u6e96\u6c27\u5316\u96fb\u4f4d\x28\x45\u2070\x20\u2248\x20\x2b\x32\x2e\x37\x31\x20\x56\x29\u6975\u8ca0\uff0c\u4f7f\u5176\u6210\u70ba\u5f37\u529b\u7684\u9084\u539f\u5291\u3002\u73fe\u4ee3\u79d1\u6280\u5229\u7528\u6db2\u614b\u9209\u512a\u7570\u7684\u71b1\u50b3\u5c0e\u80fd\u529b\uff0c\u5c07\u5176\u4f5c\u70ba\u5feb\u4e2d\u5b50\u589e\u6b96\u53cd\u61c9\u7210\u7684\u51b7\u537b\u5291\uff1b\u800c\u5728\u7167\u660e\u6280\u8853\u4e2d\uff0c\u9ad8\u58d3\u9209\u71c8\u56e0\u5177\u5099\u6975\u5f37\u7684\u9ec3\u5149\u7a7f\u900f\u529b\uff0c\u88ab\u5ee3\u6cdb\u7528\u65bc\u9053\u8def\u8207\u96a7\u9053\u7167\u660e\u3002\u96a8\u8457\u80fd\u6e90\u8f49\u578b\uff0c\u9209\u96e2\u5b50\u96fb\u6c60\x28\x53\x6f\x64\x69\x75\x6d\x2d\x69\x6f\x6e\x20\x62\x61\x74\x74\x65\x72\x69\x65\x73\x29\u56e0\u9209\u8cc7\u6e90\u8c50\u5bcc\u4e14\u6210\u672c\u4f4e\u5ec9\uff0c\u6b63\u6210\u70ba\u5927\u898f\u6a21\u96fb\u7db2\u5132\u80fd\u7cfb\u7d71\u4e2d\u66ff\u4ee3\u92f0\u96fb\u6c60\u7684\u91cd\u8981\u7814\u7a76\u65b9\u5411\u3002\x0a\x0a\u9209\u91d1\u5c6c\u5c55\u73fe\u51fa\u8a31\u591a\u5178\u578b\u7684\u91d1\u5c6c\u7269\u7406\u7279\u6027\uff0c\u537b\u4e5f\u5177\u5099\u53cd\u76f4\u89ba\u7684\u6a5f\u68b0\u6027\u8cea\u3002\u5b83\u6975\u5176\u67d4\u8edf\uff0c\u5728\u5e38\u6eab\u4e0b\u53ef\u4ee5\u7528\u666e\u901a\u5c0f\u5200\u8f15\u6613\u5207\u958b\uff0c\u66b4\u9732\u51fa\u9280\u767d\u8272\u7684\u91d1\u5c6c\u5149\u6fa4\uff0c\u4f46\u8a72\u8868\u9762\u6703\u5728\u6578\u79d2\u5167\u8fc5\u901f\u6c27\u5316\u8b8a\u6697\u3002\u6709\u8da3\u7684\u662f\uff0c\u96d6\u7136\u9209\u8207\u6c2f\x28\x43\x6c\u2082\x29\u55ae\u8cea\u7686\u5177\u5099\u5287\u6bd2\u6216\u5f37\u8150\u8755\u6027\uff0c\u4f46\u5169\u8005\u5316\u5408\u5f8c\u7684\u6c2f\u5316\u9209\u537b\u662f\u751f\u7269\u5fc5\u9700\u7684\u98df\u9e7d\u3002\u6b64\u5916\uff0c\u9209\u8207\u9240\u5f62\u6210\u7684\u5408\u91d1\x28\x4e\x61\x4b\x29\u5728\u5e38\u6eab\u4e0b\u5448\u6db2\u614b\uff0c\u9019\u7a2e\u300c\u91d1\u5c6c\u6db2\u9ad4\u300d\u7684\u7279\u6027\u4f7f\u5176\u5728\u9ad8\u6eab\u71b1\u4ea4\u63db\u5de5\u7a0b\u4e2d\u5177\u5099\u7368\u7279\u7684\u61c9\u7528\u50f9\u503c\u3002",
  "\x4d\x67":
    "\u9382\x28\x4d\x61\x67\x6e\x65\x73\x69\x75\x6d\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x4d\x67\uff0c\u539f\u5b50\u5e8f\x20\x31\x32\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u4e09\u9031\u671f\u3001\u7b2c\x20\x32\x20\u65cf\x28\u9e7c\u571f\u91d1\u5c6c\uff0c\x73\x20\u5340\u584a\x29\u3002\u5176\u540d\u7a31\u6e90\u65bc\u5e0c\u81d8\u8272\u85a9\u5229\u5730\u5340\u7684\u53e4\u5730\u540d\u300c\x4d\x61\x67\x6e\x65\x73\x69\x61\u300d\x28\u9ea5\u683c\u5c3c\u897f\u4e9e\x29\uff0c\u8a72\u5730\u76db\u7522\u82e6\u571f\x28\x4d\x67\x4f\x29\u3002\x31\x38\x30\x38\x20\u5e74\u7531\u6234\u7dad\x28\x48\x75\x6d\x70\x68\x72\x79\x20\x44\x61\x76\x79\x29\u900f\u904e\u96fb\u89e3\u6cd5\u9996\u6b21\u5206\u96e2\u3002\u9382\u662f\u5730\u6bbc\u4e2d\u8c50\u5ea6\u7b2c\u516b\u7684\u5143\u7d20\uff0c\u4ea6\u662f\u6d77\u6c34\u4e2d\u7684\u4e3b\u8981\u967d\u96e2\u5b50\u4e4b\u4e00\uff0c\u5c0d\u690d\u7269\u7684\u8449\u7da0\u7d20\u7d50\u69cb\u8207\u4eba\u985e\u7684\u9175\u7d20\u53cd\u61c9\u81f3\u95dc\u91cd\u8981\u3002\u5728\u9ad8\u4e2d\u5316\u5b78\u8ab2\u7a0b\u4e2d\uff0c\u9382\u5e38\u4f5c\u70ba\u63a2\u7a76\u91d1\u5c6c\u53cd\u61c9\u6027\u8da8\u52e2\x28\u8207\u6c34\u3001\u9178\u53cd\u61c9\x29\u7684\u91cd\u8981\u89c0\u5bdf\u5c0d\u8c61\u3002\x0a\x0a\u9382\u7684\u96fb\u5b50\u7d44\u614b\u70ba\x20\x5b\x4e\x65\x5d\x33\x73\u00b2\uff0c\u5728\u5316\u5b78\u53cd\u61c9\u4e2d\u50be\u5411\u5931\u53bb\u5169\u500b\u96fb\u5b50\u5f62\u6210\x20\x4d\x67\u00b2\u207a\u3002\u76f8\u8f03\u65bc\u540c\u9031\u671f\u7684\u9209\uff0c\u9382\u7684\u539f\u5b50\u534a\u5f91\u8f03\u5c0f\u4e14\u50f9\u96fb\u5b50\u8f03\u591a\uff0c\u56e0\u6b64\u91d1\u5c6c\u9375\u8f03\u5f37\uff0c\u7194\u9ede\u8207\u786c\u5ea6\u4e5f\u8f03\u9ad8\u3002\u5728\u5e38\u6eab\u4e0b\uff0c\u9382\u7684\u8868\u9762\u6703\u5f62\u6210\u4e00\u5c64\u7dfb\u5bc6\u7684\u6c27\u5316\u819c\x28\x4d\x67\x4f\x29\uff0c\u4f7f\u5176\u5177\u5099\u4e00\u5b9a\u7684\u6297\u8150\u8755\u6027\uff0c\u56e0\u6b64\u4e0d\u50cf\u9209\u90a3\u6a23\u9700\u8981\u4fdd\u5b58\u5728\u6cb9\u4e2d\u3002\u7136\u800c\uff0c\u9382\u689d\u5728\u7a7a\u6c23\u4e2d\u9ede\u71c3\u6642\u6703\u767c\u51fa\u8000\u773c\u7684\u5f37\u70c8\u767d\u5149\x28\u542b\u6709\u8c50\u5bcc\u7d2b\u5916\u7dda\x29\uff0c\u4e26\u80fd\u8207\u6c27\u6c23\u751a\u81f3\u4e8c\u6c27\u5316\u78b3\x28\x43\x4f\u2082\x29\u53cd\u61c9\uff0c\u9019\u4f7f\u5f97\u9382\u706b\u4e0d\u80fd\u4f7f\u7528\u4e8c\u6c27\u5316\u78b3\u6ec5\u706b\u5668\u64b2\u6ec5\uff0c\u5fc5\u9808\u4f7f\u7528\u4e7e\u7c89\u6216\u7802\u571f\u63a9\u57cb\u3002\x0a\x0a\u5728\u53f0\u7063\u9ad8\u4e2d\u6559\u6750\u8207\u73fe\u4ee3\u5de5\u696d\u4e2d\uff0c\u9382\u7684\u5316\u5b78\u61c9\u7528\u6975\u70ba\u5ee3\u6cdb\u3002\u5728\u6709\u6a5f\u5408\u6210\u4e2d\uff0c\u9382\u8207\u9e75\u4ee3\u70f7\u53cd\u61c9\u751f\u6210\u7684\u300c\u683c\u6c0f\u8a66\u5291\u300d\x28\x47\x72\x69\x67\x6e\x61\x72\x64\x20\x72\x65\x61\x67\x65\x6e\x74\x29\u662f\u5efa\u69cb\u78b3\uff0d\u78b3\u9375\u7684\u6838\u5fc3\u5de5\u5177\u3002\u5728\u74b0\u4fdd\u8207\u6750\u6599\u9818\u57df\uff0c\u9382\u5408\u91d1\u56e0\u5176\u5bc6\u5ea6\u50c5\u7d04\u92c1\u7684\u4e09\u5206\u4e4b\u4e8c\uff0c\u662f\u76ee\u524d\u5be6\u7528\u91d1\u5c6c\u4e2d\u6700\u8f15\u7684\u7d50\u69cb\u6750\u6599\uff0c\u88ab\u5927\u91cf\u61c9\u7528\u65bc\u822a\u592a\u3001\u884c\u52d5\u96fb\u5b50\u8a2d\u5099\u5e95\u6bbc\u4ee5\u53ca\u81ea\u884c\u8eca\u8eca\u67b6\u4ee5\u5be6\u73fe\u8f15\u91cf\u5316\u3002\u6b64\u5916\uff0c\u6c34\u6eb6\u6db2\u4e2d\u7684\x20\x4d\x67\u00b2\u207a\x20\u8207\x20\x43\x61\u00b2\u207a\x20\u662f\u5b9a\u7fa9\u300c\u6c34\u8cea\u786c\u5ea6\u300d\u7684\u4e3b\u8981\u6307\u6a19\uff0c\u76f4\u63a5\u5f71\u97ff\u4e86\u5de5\u696d\u934b\u7210\u6548\u80fd\u8207\u6c11\u751f\u6d17\u6ecc\u9ad4\u9a57\u3002\x0a\x0a\u9382\u5c55\u73fe\u51fa\u6975\u5177\u7279\u8272\u7684\u7269\u7406\u7279\u5fb5\u8207\u751f\u7269\u5316\u5b78\u95dc\u806f\u6027\u3002\u5b83\u662f\u8449\u7da0\u7d20\u5206\u5b50\u7684\u6838\u5fc3\u91d1\u5c6c\u539f\u5b50\uff0c\u5c31\u50cf\u8840\u7d05\u7d20\u4e2d\u7684\u9435\u4e00\u6a23\uff0c\u8ca0\u8cac\u5149\u5408\u4f5c\u7528\u4e2d\u7684\u96fb\u5b50\u50b3\u905e\u8207\u80fd\u91cf\u8f49\u63db\u3002\u53cd\u76f4\u89ba\u7684\u662f\uff0c\u96d6\u7136\u9382\u91d1\u5c6c\u672c\u8eab\u6975\u6613\u6c27\u5316\u71c3\u71d2\uff0c\u4f46\u5728\u73fe\u4ee3\u5de5\u7a0b\u4e2d\uff0c\u5b83\u537b\u662f\u512a\u826f\u7684\x53\x61\x63\x72\x69\x66\x69\x63\x69\x61\x6c\x20\x41\x6e\x6f\x64\x65\x28\u72a7\u7272\u967d\u6975\x29\uff0c\u5e38\u88ab\u9023\u63a5\u5728\u5730\u4e0b\u7ba1\u7dda\u6216\u8239\u5e95\uff0c\u5229\u7528\u5176\u66f4\u8ca0\u7684\u96fb\u4f4d\u512a\u5148\u767c\u751f\u6c27\u5316\u53cd\u61c9\uff0c\u4ee5\u4fdd\u8b77\u92fc\u9435\u7d50\u69cb\u514d\u65bc\u93fd\u8755\u3002\u9019\u7a2e\u5f9e\u652f\u6301\u690d\u7269\u751f\u547d\u5230\u5b88\u8b77\u73fe\u4ee3\u57fa\u5efa\u7684\u591a\u91cd\u8eab\u5206\uff0c\u9ad4\u73fe\u4e86\u9382\u5728\u81ea\u7136\u8207\u79d1\u6280\u9593\u7684\u6a4b\u6a11\u5730\u4f4d\u3002",
  "\x41\x6c":
    "\u92c1\x28\x41\x6c\x75\x6d\x69\x6e\x75\x6d\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x41\x6c\uff0c\u539f\u5b50\u5e8f\x20\x31\x33\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u4e09\u9031\u671f\u3001\u7b2c\x20\x31\x33\x20\u65cf\x28\x70\x20\u5340\u584a\x29\u3002\u540d\u7a31\u6e90\u65bc\u62c9\u4e01\u8a9e\u300c\x61\x6c\x75\x6d\x65\x6e\u300d\x28\u660e\u792c\x29\u3002\u96d6\u7136\u92c1\u662f\u5730\u6bbc\u4e2d\u542b\u91cf\u6700\u8c50\u5bcc\u7684\u91d1\u5c6c\u5143\u7d20\x28\u7d04\u4f54\x20\x38\x25\x29\uff0c\u4f46\u7531\u65bc\u5176\u8207\u6c27\u7d50\u5408\u529b\u6975\u5f37\uff0c\u4eba\u985e\u76f4\u5230\x20\x31\x39\x20\u4e16\u7d00\u624d\u7531\u5967\u65af\u7279\x28\x48\x61\x6e\x73\x20\x43\x68\x72\x69\x73\x74\x69\x61\x6e\x20\u00d8\x72\x73\x74\x65\x64\x29\u8207\u7dad\u52d2\x28\x46\x72\x69\x65\x64\x72\x69\x63\x68\x20\x57\u00f6\x68\x6c\x65\x72\x29\u5206\u96e2\u51fa\u7d14\u92c1\u3002\u5728\x20\x31\x39\x20\u4e16\u7d00\u4e2d\u8449\uff0c\u92c1\u66fe\u56e0\u63d0\u7149\u56f0\u96e3\u800c\u6bd4\u9ec3\u91d1\u66f4\u73cd\u8cb4\uff0c\u76f4\u5230\u970d\u723e\uff0d\u57c3\u9b6f\u6cd5\x28\x48\x61\x6c\x6c\x2d\x48\u00e9\x72\x6f\x75\x6c\x74\x20\x70\x72\x6f\x63\x65\x73\x73\x29\u96fb\u89e3\u6cd5\u7684\u767c\u660e\uff0c\u624d\u4f7f\u92c1\u6210\u70ba\u73fe\u4ee3\u6587\u660e\u4e0d\u53ef\u6216\u7f3a\u7684\u300c\u5de5\u696d\u5e95\u8272\u300d\u3002\x0a\x0a\u92c1\u7684\u96fb\u5b50\u7d44\u614b\u70ba\x20\x5b\x4e\x65\x5d\x33\x73\u00b2\x33\x70\u00b9\uff0c\u6700\u7a69\u5b9a\u6c27\u5316\u614b\u70ba\x20\x2b\x33\u3002\u92c1\u6700\u986f\u8457\u7684\u5316\u5b78\u7279\u6027\u662f\u5176\u300c\u5169\u6027\u300d\x28\x41\x6d\x70\x68\x6f\x74\x65\x72\x69\x63\x29\uff1a\u5b83\u4e0d\u50c5\u80fd\u6eb6\u65bc\u5f37\u9178\uff0c\u4ea6\u80fd\u6eb6\u65bc\u5f37\u9e7c\x28\u5982\x20\x4e\x61\x4f\x48\x29\uff0c\u4e26\u7522\u751f\u6c2b\u6c23\x28\x48\u2082\x29\u8207\u92c1\u9178\u6839\u96e2\u5b50\x28\x5b\x41\x6c\x28\x4f\x48\x29\u2084\x5d\u207b\x29\u3002\u6b64\u5916\uff0c\u92c1\u5177\u5099\u5353\u8d8a\u7684\u300c\u920d\u5316\u73fe\u8c61\u300d\x28\x50\x61\x73\x73\x69\x76\x61\x74\x69\x6f\x6e\x29\uff0c\u5728\u5927\u6c23\u4e2d\u6703\u8fc5\u901f\u5f62\u6210\u4e00\u5c64\u50c5\u6578\u5948\u7c73\u539a\u3001\u6975\u5176\u7dfb\u5bc6\u4e14\u9644\u8457\u529b\u5f37\u7684\u4e8c\u6c27\u5316\u92c1\x28\x41\x6c\u2082\x4f\u2083\x29\u4fdd\u8b77\u5c64\uff0c\u6709\u6548\u963b\u6b62\u5167\u5c64\u91d1\u5c6c\u9032\u4e00\u6b65\u6c27\u5316\uff0c\u9019\u4f7f\u5f97\u92c1\u96d6\u70ba\u6d3b\u6f51\u91d1\u5c6c\uff0c\u537b\u5177\u5099\u512a\u7570\u7684\u8010\u5019\u6027\u3002\x0a\x0a\u5728\u53f0\u7063\u9ad8\u4e2d\u8ab2\u7db1\u8207\u5de5\u7a0b\u61c9\u7528\u4e2d\uff0c\u92c1\u7684\u6c27\u5316\u9084\u539f\u5316\u5b78\u6975\u5177\u4ee3\u8868\u6027\u3002\u92c1\u71b1\u53cd\u61c9\x28\x54\x68\x65\x72\x6d\x69\x74\x65\x20\x72\x65\x61\x63\x74\x69\x6f\x6e\x29\u5229\u7528\u92c1\u5c0d\u6c27\u6975\u5f37\u7684\u89aa\u548c\u529b\uff0c\u5728\u9ede\u71c3\u5f8c\u8207\u6c27\u5316\u9435\u53cd\u61c9\u7522\u751f\u7194\u878d\u9435\u4e26\u91cb\u653e\u5de8\u5927\u71b1\u80fd\uff0c\u5e38\u7528\u65bc\u91ce\u5916\u9435\u8ecc\u710a\u63a5\u3002\u5728\u5de5\u696d\u898f\u6a21\u4e0a\uff0c\u92c1\u662f\u900f\u904e\u96fb\u89e3\u6eb6\u65bc\u7194\u878d\u51b0\u6676\u77f3\x28\x4e\x61\u2083\x41\x6c\x46\u2086\x29\u7684\u6c27\u5316\u92c1\u4f86\u88fd\u5099\u3002\u73fe\u4ee3\u6750\u6599\u79d1\u5b78\u4e2d\uff0c\u92c1\u8207\u9285\u3001\u9382\u3001\u92c5\u7d44\u6210\u7684\u300c\u92c1\u5408\u91d1\u300d\x28\u5982\u675c\u62c9\u92c1\uff0c\x44\x75\x72\x61\x6c\x75\x6d\x69\x6e\x29\u5177\u5099\u9ad8\u5f37\u5ea6\u91cd\u91cf\u6bd4\uff0c\u662f\u822a\u7a7a\u5668\u8207\u9ad8\u9435\u8eca\u9ad4\u7684\u4e3b\u5e79\u6750\u6599\u3002\u5176\u9ad8\u5c0e\u96fb\u7387\x28\u50c5\u6b21\u65bc\u9280\u3001\u9285\u3001\u91d1\x29\u4e14\u8cea\u91cf\u8f03\u8f15\u7684\u7279\u5fb5\uff0c\u4e5f\u4f7f\u5176\u6210\u70ba\u9ad8\u58d3\u8f38\u96fb\u7dda\u8def\u7684\u9996\u9078\u8f09\u9ad4\u3002\x0a\x0a\u92c1\u5728\u7926\u7269\u5b78\u8207\u7279\u6b8a\u61c9\u7528\u4e2d\u5c55\u73fe\u4e86\u8de8\u9818\u57df\u7684\u7279\u8cea\u3002\u81ea\u7136\u754c\u4e2d\u7684\u7d05\u5bf6\u77f3\u8207\u85cd\u5bf6\u77f3\uff0c\u5176\u672c\u8cea\u7686\u70ba\x20\u03b1\x2d\x41\x6c\u2082\x4f\u2083\x28\u525b\u7389\x29\uff0c\u50c5\u56e0\u5fae\u91cf\u904e\u6e21\u91d1\u5c6c\u96dc\u8cea\u800c\u5448\u73fe\u4e0d\u540c\u8272\u6fa4\u3002\u53cd\u76f4\u89ba\u7684\u662f\uff0c\u5118\u7ba1\u92c1\u5c0d\u6c27\u53cd\u61c9\u6d3b\u6027\u6975\u9ad8\uff0c\u4f46\u92c1\u7c89\u8207\u6c27\u5316\u5291\u6df7\u5408\u5f8c\u537b\u662f\u9ad8\u6027\u80fd\u706b\u7bad\u63a8\u9032\u5291\u8207\u70b8\u85e5\u7684\u91cd\u8981\u6dfb\u52a0\u7269\uff0c\u5229\u7528\u5176\u6975\u9ad8\u7684\u71c3\u71d2\u71b1\u503c\u7522\u751f\u63a8\u529b\u3002\u5728\u6c11\u751f\u61c9\u7528\u4e0a\uff0c\u92c1\u7f50\u8207\u92c1\u7b94\u7684\u56de\u6536\u518d\u5229\u7528\x28\u518d\u751f\u92c1\x29\u6240\u9700\u7684\u80fd\u91cf\u50c5\u70ba\u96fb\u89e3\u92c1\u7684\x20\x35\x25\uff0c\u9019\u4f7f\u5176\u6210\u70ba\u73fe\u4ee3\u5faa\u74b0\u7d93\u6fdf\u8207\u6c38\u7e8c\u767c\u5c55\u4e2d\uff0c\u78b3\u8db3\u8de1\u8a55\u4f30\u6700\u5177\u6307\u6a19\u6027\u7684\u91d1\u5c6c\u5143\u7d20\u3002",
  "\x53\x69":
    "\u77fd\x28\x53\x69\x6c\x69\x63\x6f\x6e\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x53\x69\uff0c\u539f\u5b50\u5e8f\x20\x31\x34\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u4e09\u9031\u671f\u3001\u7b2c\x20\x31\x34\x20\u65cf\x28\u78b3\u65cf\u5143\u7d20\uff0c\x70\x20\u5340\u584a\x29\uff0c\u662f\u5730\u6bbc\u4e2d\u542b\u91cf\u50c5\u6b21\u65bc\u6c27\u7684\u7b2c\u4e8c\u5927\u5143\u7d20\u3002\u5176\u540d\u7a31\u6e90\u65bc\u62c9\u4e01\u8a9e\u300c\x73\x69\x6c\x65\x78\u300d\x28\u71e7\u77f3\x29\u3002\u96d6\u7136\u77fd\u7684\u5316\u5408\u7269\u5982\u77f3\u82f1\x28\x53\x69\x4f\u2082\x29\u81ea\u53e4\u5c31\u88ab\u7528\u65bc\u88fd\u4f5c\u73bb\u7483\uff0c\u4f46\u76f4\u5230\x20\x31\x38\x32\x34\x20\u5e74\u624d\u7531\u745e\u5178\u5316\u5b78\u5bb6\u8c9d\u9f4a\u91cc\u70cf\u65af\x28\x4a\u00f6\x6e\x73\x20\x4a\x61\x63\x6f\x62\x20\x42\x65\x72\x7a\x65\x6c\x69\x75\x73\x29\u5206\u96e2\u51fa\u7d14\u77fd\u3002\u77fd\u5728\u81ea\u7136\u754c\u4e0d\u4ee5\u6e38\u96e2\u614b\u5b58\u5728\uff0c\u800c\u662f\u4ee5\u8907\u96dc\u7684\u77fd\u9178\u9e7d\u6216\u4e8c\u6c27\u5316\u77fd\u5f62\u5f0f\u69cb\u6210\u5730\u6bbc\u7684\u9aa8\u67b6\uff0c\u662f\u5ca9\u77f3\u5708\u7684\u6838\u5fc3\u7d44\u6210\uff0c\u4ea6\u662f\u73fe\u4ee3\u8cc7\u8a0a\u6587\u660e\u7684\u57fa\u77f3\u3002\x0a\x0a\u5728\u5fae\u89c0\u884c\u70ba\u4e0a\uff0c\u77fd\u7684\u96fb\u5b50\u7d44\u614b\u70ba\x20\x5b\x4e\x65\x5d\x33\x73\u00b2\x33\x70\u2074\uff0c\u8207\u78b3\u540c\u5c6c\u4e00\u65cf\uff0c\u5177\u5099\u76f8\u4f3c\u7684\u56db\u50f9\u9375\u7d50\u7279\u6027\u3002\u7136\u800c\uff0c\u77fd\u7684\u539f\u5b50\u534a\u5f91\u8f03\u5927\uff0c\u96e3\u4ee5\u50cf\u78b3\u4e00\u6a23\u5f62\u6210\u7a69\u5b9a\u7684\x20\x70\u03c0\x2d\x70\u03c0\x20\u96d9\u9375\uff0c\u56e0\u6b64\u77fd\u4e3b\u8981\u900f\u904e\x20\x73\x70\u00b3\x20\u6df7\u6210\u8ecc\u57df\u5f62\u6210\u7a69\u5b9a\u7684\u5171\u50f9\u7db2\u8def\u56fa\u9ad4\u3002\u7d14\u77fd\u6676\u9ad4\u5177\u6709\u985e\u91d1\u525b\u77f3\u7d50\u69cb\uff0c\u7194\u9ede\u9ad8\u9054\x20\x31\x34\x31\x34\x20\u00b0\x43\u3002\u77fd\u6700\u986f\u8457\u7684\u7269\u7406\u7279\u6027\u5728\u65bc\u5176\u534a\u5c0e\u9ad4\u6027\u8cea\x28\x53\x65\x6d\x69\x63\x6f\x6e\x64\x75\x63\x74\x6f\x72\x29\uff1a\u5728\u7d55\u5c0d\u96f6\u5ea6\u6642\u662f\u7d55\u7de3\u9ad4\uff0c\u4f46\u96a8\u6eab\u5ea6\u5347\u9ad8\u6216\u900f\u904e\u300c\u647b\u96dc\u300d\x28\x44\x6f\x70\x69\x6e\x67\x29\u7a0b\u5e8f\uff0c\u5176\u5c0e\u96fb\u6027\u6703\u986f\u8457\u63d0\u5347\uff0c\u9019\u4f7f\u5176\u6210\u70ba\u5fae\u96fb\u5b50\u5143\u4ef6\u4e2d\u63a7\u5236\u96fb\u6d41\u6d41\u52d5\u7684\u7406\u60f3\u6750\u6599\u3002\x0a\x0a\u5728\u53f0\u7063\u9ad8\u4e2d\u5316\u5b78\u8207\u7522\u696d\u8108\u7d61\u4e2d\uff0c\u77fd\u662f\u534a\u5c0e\u9ad4\u88fd\u7a0b\u8207\u6750\u6599\u79d1\u5b78\u7684\u4ee3\u540d\u8a5e\u3002\u900f\u904e\u5c07\u78f7\x28\x50\x29\u6216\u787c\x28\x42\x29\u647b\u5165\u8d85\u9ad8\u7d14\u5ea6\u77fd\x28\u7b49\u7d1a\u9700\u9054\x20\x39\x4e\x20\u81f3\x20\x31\x31\x4e\x29\u4e2d\uff0c\u53ef\u5206\u5225\u88fd\u5f97\x20\x6e\x20\u578b\u8207\x20\x70\x20\u578b\u534a\u5c0e\u9ad4\uff0c\u9032\u800c\u5efa\u69cb\u51fa\u96fb\u6676\u9ad4\u8207\u7a4d\u9ad4\u96fb\u8def\x28\x49\x43\x29\u3002\u4e8c\u6c27\u5316\u77fd\x28\x53\x69\x4f\u2082\x29\u5728\u6559\u6750\u4e2d\u5e38\u4f5c\u70ba\u300c\u5171\u50f9\u7db2\u8def\u56fa\u9ad4\u300d\u7684\u5178\u578b\u7bc4\u4f8b\uff0c\u5176\u9ad8\u7194\u9ede\u8207\u5316\u5b78\u7a69\u5b9a\u6027\u4f7f\u5176\u5728\u5149\u7e96\u901a\u8a0a\u4e2d\u626e\u6f14\u95dc\u9375\u89d2\u8272\u3002\u6b64\u5916\uff0c\u77fd\u9178\u9e7d\u5316\u5b78\u5ef6\u4f38\u51fa\u7684\u73bb\u7483\u3001\u9676\u74f7\u8207\u6c34\u6ce5\u5de5\u696d\uff0c\u4ee5\u53ca\u5177\u5099\u512a\u7570\u8010\u71b1\u8207\u758f\u6c34\u6027\u7684\u6709\u6a5f\u77fd\u9ad8\u5206\u5b50\x28\u77fd\u9748\x2f\u77fd\u6a61\u81a0\uff0c\x53\x69\x6c\x69\x63\x6f\x6e\x65\x73\x29\uff0c\u7686\u5c55\u73fe\u4e86\u77fd\u5728\u50b3\u7d71\u8207\u9ad8\u79d1\u6280\u7522\u696d\u9593\u7684\u8de8\u5ea6\u3002\x0a\x0a\u77fd\u5c55\u73fe\u4e86\u8207\u78b3\u622a\u7136\u4e0d\u540c\u7684\u71b1\u529b\u5b78\u7279\u5fb5\uff0c\u6700\u5178\u578b\u7684\u5c0d\u6bd4\u5728\u65bc\u6c27\u5316\u7269\uff1a\u78b3\u7684\u6c27\u5316\u7269\x28\x43\x4f\u2082\x29\u662f\u7368\u7acb\u7684\u6c23\u9ad4\u5206\u5b50\uff0c\u800c\u77fd\u7684\u6c27\u5316\u7269\x28\x53\x69\x4f\u2082\x29\u5247\u662f\u7d50\u69cb\u5805\u786c\u7684\u5de8\u578b\u5206\u5b50\u7db2\u8def\uff0c\u9019\u89e3\u91cb\u4e86\u70ba\u4f55\u5730\u7403\u8868\u9762\u4e0d\u662f\u6c23\u614b\u4e8c\u6c27\u5316\u77fd\u3002\u6709\u8da3\u7684\u662f\uff0c\u96d6\u7136\u77fd\u662f\u5730\u6bbc\u7684\u5bf5\u5152\uff0c\u4f46\u5728\u751f\u7269\u6709\u6a5f\u9ad4\u4e2d\u7684\u4f54\u6bd4\u537b\u6975\u4f4e\uff0c\u9019\u53cd\u6620\u4e86\u751f\u547d\u6f14\u5316\u5c0d\u300c\u78b3\u93c8\u300d\u9748\u6d3b\u6027\u8207\u300c\u77fd\u93c8\u300d\u7a69\u5b9a\u6027\u4e4b\u9593\u7684\u53d6\u6368\u3002\u6b64\u5916\uff0c\u7d14\u77fd\u96d6\u7136\u770b\u4f3c\u91d1\u5c6c\uff0c\u5177\u5099\u6df1\u7070\u8272\u7684\u91d1\u5c6c\u5149\u6fa4\u4e14\u8cea\u8106\uff0c\u4f46\u5b83\u5728\u5149\u96fb\u6548\u61c9\u4e0b\u7684\u5353\u8d8a\u8868\u73fe\uff0c\u4f7f\u5176\u6210\u70ba\u592a\u967d\u80fd\u96fb\u6c60\x28\x50\x68\x6f\x74\x6f\x76\x6f\x6c\x74\x61\x69\x63\x20\x63\x65\x6c\x6c\x73\x29\u4e2d\u5c07\u5149\u80fd\u8f49\u5316\u70ba\u96fb\u80fd\u7684\u6700\u6838\u5fc3\u8f09\u9ad4\u3002",
  "\x50":
    "\u78f7\x28\x50\x68\x6f\x73\x70\x68\x6f\x72\x75\x73\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x50\uff0c\u539f\u5b50\u5e8f\x20\x31\x35\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u4e09\u9031\u671f\u3001\u7b2c\x20\x31\x35\x20\u65cf\x28\u6c2e\u65cf\u5143\u7d20\uff0c\x70\x20\u5340\u584a\x29\uff0c\u662f\u7dad\u6301\u751f\u547d\u907a\u50b3\u8207\u80fd\u91cf\u4ee3\u8b1d\u7684\u95dc\u9375\u5143\u7d20\u3002\x31\x36\x36\x39\x20\u5e74\uff0c\u5fb7\u570b\u7149\u91d1\u8853\u5e2b\u5e03\u862d\u5fb7\x28\x48\x65\x6e\x6e\x69\x6e\x67\x20\x42\x72\x61\x6e\x64\x29\u5728\u84b8\u993e\u5927\u91cf\u5c3f\u6db2\u5c0b\u627e\u54f2\u4eba\u77f3\u6642\uff0c\u610f\u5916\u5206\u96e2\u51fa\u80fd\u81ea\u767c\u767c\u5149\u7684\u7269\u8cea\uff0c\u56e0\u800c\u7d50\u5408\u5e0c\u81d8\u8a9e\u5b57\u6839\u300c\x70\x68\x6f\x73\u300d\x28\u5149\x29\u8207\u300c\x70\x68\x6f\x72\x6f\x73\u300d\x28\u651c\u5e36\u8005\x29\u547d\u540d\u70ba\x20\x50\x68\x6f\x73\x70\x68\x6f\x72\x75\x73\u3002\u78f7\u5728\u81ea\u7136\u754c\u4e3b\u8981\u4ee5\u78f7\u9178\u9e7d\x28\u5982\u78f7\u7070\u77f3\x29\u7684\u5f62\u5f0f\u5b58\u5728\uff0c\u662f\u69cb\u6210\u53bb\u6c27\u6838\u7cd6\u6838\u9178\x28\x44\x4e\x41\x29\u3001\u6838\u7cd6\u6838\u9178\x28\x52\x4e\x41\x29\u8207\u4e09\u78f7\u9178\u817a\u82f7\x28\x41\x54\x50\x29\u78f7\u9178\u9aa8\u67b6\u7684\u6838\u5fc3\u6210\u5206\u3002\x0a\x0a\u78f7\u7684\u96fb\u5b50\u7d44\u614b\u70ba\x20\x5b\x4e\x65\x5d\x33\x73\u00b2\x33\x70\u00b3\uff0c\u5176\u6700\u5177\u4ee3\u8868\u6027\u7684\u5316\u5b78\u7279\u5fb5\u662f\u8c50\u5bcc\u7684\u540c\u7d20\u7570\u5f62\u9ad4\u3002\u6700\u5e38\u898b\u7684\u5305\u62ec\uff1a\u5287\u6bd2\u4e14\u6975\u6613\u81ea\u71c3\u7684\u300c\u767d\u78f7\u300d\x28\x50\u2084\x29\uff0c\u5176\u5206\u5b50\u5448\u6b63\u56db\u9762\u9ad4\u7d50\u69cb\uff0c\u9375\u89d2\u50c5\x20\x36\x30\u00b0\x20\u5c0e\u81f4\u5f35\u529b\u6975\u5927\uff0c\u6d3b\u6027\u6975\u9ad8\uff1b\u4ee5\u53ca\u7d50\u69cb\u8f03\u7a69\u5b9a\u3001\u5448\u93c8\u72c0\u805a\u5408\u7269\u7684\u300c\u7d05\u78f7\u300d\uff0c\u5e38\u88ab\u7528\u65bc\u5b89\u5168\u706b\u67f4\u3002\u5169\u8005\u7684\u6027\u8cea\u5dee\u7570\u5728\u9ad8\u4e2d\u5316\u5b78\u4e2d\u5e38\u7528\u65bc\u8aaa\u660e\u300c\u7d50\u69cb\u6c7a\u5b9a\u6027\u8cea\u300d\u7684\u539f\u7406\u3002\u78f7\u7684\u6c27\u5316\u614b\u5206\u5e03\u5ee3\u6cdb\uff0c\u5f9e\x20\x2d\x33\x28\u5982\u78f7\u5316\u6c2b\x20\x50\x48\u2083\x29\u5230\x20\x2b\x35\x28\u5982\u78f7\u9178\x20\x48\u2083\x50\x4f\u2084\x29\uff0c\u5728\u6c27\u5316\u9084\u539f\u53cd\u61c9\u4e2d\u5c55\u73fe\u51fa\u8907\u96dc\u7684\u6f14\u8b8a\u904e\u7a0b\u3002\x0a\x0a\u5728\u53f0\u7063\u9ad8\u4e2d\u8ab2\u7db1\u8207\u8fb2\u696d\u79d1\u6280\u4e2d\uff0c\u78f7\u662f\u80a5\u6599\u4e09\u5927\u5143\u7d20\x28\x4e\x2d\x50\x2d\x4b\x29\u4e4b\u4e00\u3002\u78f7\u9178\x28\x48\u2083\x50\x4f\u2084\x29\u53ca\u5176\u591a\u7a2e\u9178\u5f0f\u9e7d\x28\u5982\x20\x4e\x61\x48\u2082\x50\x4f\u2084\u3001\x4e\x61\u2082\x48\x50\x4f\u2084\x29\u5728\u751f\u7269\u5316\u5b78\u4e2d\u662f\u6975\u5176\u91cd\u8981\u7684\u7de9\u885d\u9ad4\u7cfb\x28\x42\x75\x66\x66\x65\x72\x20\x73\x79\x73\x74\x65\x6d\x29\uff0c\u8ca0\u8cac\u8abf\u7bc0\u7d30\u80de\u5167\u7684\x20\x70\x48\x20\u503c\u3002\u6b64\u5916\uff0c\u78f7\u9178\u9223\x28\x43\x61\u2083\x28\x50\x4f\u2084\x29\u2082\x29\u662f\u810a\u690e\u52d5\u7269\u9aa8\u9abc\u8207\u7259\u9f52\u7684\u4e3b\u8981\u6210\u5206\u3002\u5728\u534a\u5c0e\u9ad4\u5de5\u696d\uff0c\u78f7\u5e38\u88ab\u7528\u4f5c\u77fd\u6676\u5713\u7684\u647b\u96dc\u5291\u4ee5\u88fd\u9020\x20\x6e\x20\u578b\u534a\u5c0e\u9ad4\u3002\u7136\u800c\uff0c\u74b0\u5883\u79d1\u5b78\u4ea6\u95dc\u6ce8\u78f7\u6392\u653e\u5c0e\u81f4\u7684\u300c\u6c34\u9ad4\u512a\u990a\u5316\u300d\x28\x45\x75\x74\x72\x6f\x70\x68\x69\x63\x61\x74\x69\x6f\x6e\x29\u554f\u984c\uff0c\u9019\u662f\u56e0\u78f7\u9178\u9e7d\u904e\u91cf\u5c0e\u81f4\u85fb\u985e\u7206\u767c\u6027\u751f\u9577\uff0c\u9032\u800c\u8017\u76e1\u6c34\u5e95\u6eb6\u6c27\u7684\u751f\u614b\u707d\u96e3\u3002\x0a\x0a\u78f7\u5c55\u73fe\u4e86\u8a31\u591a\u8ff7\u4eba\u7684\u5149\u5316\u5b78\u73fe\u8c61\u3002\u767d\u78f7\u5728\u7a7a\u6c23\u4e2d\u7de9\u6162\u6c27\u5316\u91cb\u653e\u7684\u80fd\u91cf\u6703\u6fc0\u767c\u51fa\u7da0\u8272\u5fae\u5149\uff0c\u9019\u66fe\u88ab\u8aa4\u8a8d\u70ba\u9748\u7570\u73fe\u8c61\x28\u9b3c\u706b\x29\uff0c\u4e5f\u662f\u300c\u5316\u5b78\u767c\u5149\u300d\x28\x43\x68\x65\x6d\x69\x6c\x75\x6d\x69\x6e\x65\x73\x63\x65\x6e\x63\x65\x29\u7684\u65e9\u671f\u89c0\u6e2c\u5be6\u4f8b\u3002\u53cd\u76f4\u89ba\u7684\u662f\uff0c\u96d6\u7136\u767d\u78f7\u63a5\u89f8\u7a7a\u6c23\u5373\u5287\u71c3\uff0c\u4f46\u5b83\u5728\u6c34\u4e2d\u537b\u7570\u5e38\u7a69\u5b9a\uff0c\u56e0\u6b64\u5be6\u9a57\u5ba4\u4e2d\u5fc5\u9808\u5c07\u767d\u78f7\u4fdd\u5b58\u5728\u6c34\u4e2d\u4ee5\u9694\u96e2\u6c27\u6c23\u3002\u6b64\u5916\uff0c\u78f7\u8207\u6c27\u5f62\u6210\u7684\u6c27\u5316\u7269\x20\x50\u2084\x4f\u2081\u2080\x28\u4e94\u6c27\u5316\u4e8c\u78f7\x29\u5177\u6709\u6975\u5f37\u7684\u5438\u6c34\u6027\uff0c\u662f\u5be6\u9a57\u5ba4\u4e2d\u6027\u80fd\u512a\u7570\u7684\u4e7e\u71e5\u5291\uff0c\u751a\u81f3\u80fd\u5c07\u8a31\u591a\u6709\u6a5f\u5316\u5408\u7269\u4e2d\u7684\u6c2b\u3001\u6c27\u4ee5\u6c34\u5206\u5b50\u6bd4\u4f8b\u5f37\u884c\u812b\u53bb\uff0c\u5c55\u73fe\u5176\u5728\u71b1\u529b\u5b78\u4e0a\u7684\u5f37\u5927\u596a\u6c34\u529b\u3002",
  "\x53":
    "\u786b\x28\x53\x75\x6c\x66\x75\x72\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x53\uff0c\u539f\u5b50\u5e8f\x20\x31\x36\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u4e09\u9031\u671f\u3001\u7b2c\x20\x31\x36\x20\u65cf\x28\u6c27\u65cf\u5143\u7d20\uff0c\x70\x20\u5340\u584a\x29\uff0c\u662f\u4eba\u985e\u81ea\u53e4\u4fbf\u5df2\u719f\u77e5\u7684\u975e\u91d1\u5c6c\u5143\u7d20\u3002\u5176\u82f1\u6587\u540d\u7a31\u6e90\u65bc\u62c9\u4e01\u8a9e\u300c\x73\x75\x6c\x66\x75\x72\x69\x75\x6d\u300d\uff0c\u5728\u53e4\u4ee3\u5178\u7c4d\u4e2d\u5e38\u8207\u300c\u786b\u78fa\u300d\u6216\u300c\u786b\u706b\u300d\u76f8\u9023\u3002\u96d6\u7136\u786b\u5728\u5e38\u6eab\u4e0b\u662f\u9bae\u9ec3\u8272\u7684\u8106\u6027\u56fa\u9ad4\uff0c\u4f46\u5728\u81ea\u7136\u754c\u4e2d\u5e38\u4ee5\u706b\u5c71\u6eab\u6cc9\u5468\u570d\u7684\u6e38\u96e2\u614b\u6216\u91d1\u5c6c\u786b\u5316\u7269\x28\u5982\u9ec3\u9435\u7926\x20\x46\x65\x53\u2082\x29\u5f62\u5f0f\u5b58\u5728\u3002\u62c9\u74e6\u7bc0\x28\x41\x6e\x74\x6f\x69\x6e\x65\x20\x4c\x61\x76\x6f\x69\x73\x69\x65\x72\x29\u5728\x20\x31\x37\x37\x37\x20\u5e74\u6b63\u5f0f\u5c07\u786b\u5217\u70ba\u5316\u5b78\u5143\u7d20\uff0c\u78ba\u7acb\u5176\u5728\u5fae\u89c0\u5316\u5b78\u7814\u7a76\u4e2d\u7684\u5730\u4f4d\u3002\x0a\x0a\u786b\u7684\u96fb\u5b50\u7d44\u614b\u70ba\x20\x5b\x4e\x65\x5d\x33\x73\u00b2\x33\x70\u2074\uff0c\u6700\u7a69\u5b9a\u7684\u7d50\u69cb\u662f\u4ee5\u516b\u500b\u786b\u539f\u5b50\u69cb\u6210\u7684\u74b0\u72c0\u5206\u5b50\x20\x53\u2088\u3002\u786b\u7684\u540c\u7d20\u7570\u5f62\u9ad4\u8f49\u8b8a\u662f\u9ad8\u4e2d\u71b1\u5316\u5b78\u8207\u76f8\u5716\u7814\u7a76\u7684\u7d93\u5178\u6559\u6750\uff1a\u96a8\u6eab\u5ea6\u5347\u9ad8\uff0c\u9ec3\u8272\u7684\u91dd\u72c0\u300c\u659c\u65b9\u786b\u300d\u6703\u8f49\u8b8a\u70ba\u300c\u55ae\u659c\u786b\u300d\uff0c\u82e5\u7e7c\u7e8c\u52a0\u71b1\u81f3\u7194\u5316\u4e26\u9a5f\u51b7\uff0c\u5247\u6703\u5f62\u6210\u5177\u5099\u5f48\u6027\u7684\u6df1\u8910\u8272\u300c\u5851\u6027\u786b\u300d\u3002\u786b\u5177\u6709\x20\x2d\x32\x20\u5230\x20\x2b\x36\x20\u7684\u5bec\u5ee3\u6c27\u5316\u614b\uff0c\u9019\u4f7f\u5176\u80fd\u5f62\u6210\u591a\u6a23\u5316\u7684\u6c27\u5316\u7269\u8207\u9178\u985e\uff0c\u5982\u4e8c\u6c27\u5316\u786b\x28\x53\x4f\u2082\x29\u3001\u4e09\u6c27\u5316\u786b\x28\x53\x4f\u2083\x29\u4ee5\u53ca\u6700\u91cd\u8981\u7684\u5de5\u696d\u6bcd\u6a5f\u6750\u6599\u2014\u2014\u786b\u9178\x28\x48\u2082\x53\x4f\u2084\x29\u3002\x0a\x0a\u786b\u9178\x28\x48\u2082\x53\x4f\u2084\x29\u5728\u53f0\u7063\u9ad8\u4e2d\u6559\u6750\u4e2d\u88ab\u5b9a\u4f4d\u70ba\u5f37\u9178\u3001\u812b\u6c34\u5291\u8207\u5f37\u6c27\u5316\u5291\u3002\u5728\u5de5\u696d\u4e0a\uff0c\u786b\u662f\u900f\u904e\u300c\u63a5\u89f8\u6cd5\u300d\x28\x43\x6f\x6e\x74\x61\x63\x74\x20\x50\x72\x6f\x63\x65\x73\x73\x29\u88fd\u5099\u786b\u9178\uff0c\u8a72\u88fd\u7a0b\u76f4\u63a5\u53cd\u6620\u4e86\u52d5\u529b\u5b78\x28\u50ac\u5316\u5291\u4f7f\u7528\x29\u8207\u71b1\u529b\u5b78\u5e73\u8861\u7684\u61c9\u7528\u3002\u6750\u6599\u79d1\u5b78\u4e2d\uff0c\u786b\u6700\u8457\u540d\u7684\u8ca2\u737b\u5728\u65bc\u6a61\u81a0\u7684\u300c\u786b\u5316\u53cd\u61c9\u300d\x28\x56\x75\x6c\x63\x61\x6e\x69\x7a\x61\x74\x69\x6f\x6e\x29\uff0c\u900f\u904e\u786b\u6a4b\u8de8\u93c8\u7d50\u69cb\u5927\u5e45\u63d0\u5347\u6a61\u81a0\u7684\u5f37\u5ea6\u8207\u8010\u71b1\u6027\u3002\u74b0\u5883\u5de5\u7a0b\u65b9\u9762\uff0c\u7164\u70ad\u71c3\u71d2\u7522\u751f\u7684\x20\x53\x4f\u2082\x20\u662f\u5f62\u6210\u9178\u96e8\u7684\u4e3b\u8981\u539f\u56e0\uff0c\u5176\u8207\u5927\u6c23\u4e2d\u7684\u6c34\u5206\u4f5c\u7528\u5f62\u6210\u4e9e\u786b\u9178\u8207\u786b\u9178\uff0c\u5c0d\u751f\u614b\u74b0\u5883\u5177\u5099\u986f\u8457\u7684\u7834\u58de\u529b\u3002\x0a\x0a\u786b\u5728\u751f\u7269\u5316\u5b78\u8207\u6750\u6599\u79d1\u5b78\u4e2d\u5e38\u5c55\u73fe\u51fa\u7279\u6b8a\u7684\u55c5\u89ba\u8207\u7d50\u69cb\u7279\u6027\u3002\u96d6\u7136\u7d14\u786b\u7121\u5473\uff0c\u4f46\u5176\u9084\u539f\u614b\u5316\u5408\u7269\u5982\u786b\u5316\u6c2b\x28\x48\u2082\x53\x29\u5177\u5099\u660e\u986f\u7684\u721b\u96de\u86cb\u6c23\u5473\uff0c\u800c\u6d0b\u8525\u8207\u5927\u849c\u4e2d\u7684\u6709\u6a5f\u786b\u6210\u5206\u5247\u662f\u5176\u7368\u7279\u98a8\u5473\u7684\u4f86\u6e90\u3002\u5728\u86cb\u767d\u8cea\u7d50\u69cb\u4e2d\uff0c\u5169\u500b\u534a\u80f1\u80fa\u9178\u6b98\u57fa\u9593\u5f62\u6210\u7684\u300c\u96d9\u786b\u9375\u300d\x28\x44\x69\x73\x75\x6c\x66\x69\x64\x65\x20\x62\x6f\x6e\x64\x29\u662f\u7a69\u5b9a\u86cb\u767d\u8cea\u4e09\u7d1a\u7d50\u69cb\u7684\u91cd\u8981\u652f\u67f1\uff0c\u9019\u4e5f\u662f\u6c7a\u5b9a\u4eba\u985e\u9aee\u578b\x28\u5982\u81ea\u7136\u6372\x29\u7684\u5206\u5b50\u57fa\u790e\u3002\u6709\u8da3\u7684\u662f\uff0c\u786b\u5728\u6975\u7aef\u74b0\u5883\x28\u5982\u6df1\u6d77\u71b1\u6db2\u5674\u53e3\x29\u4e0b\u80fd\u652f\u6301\u5316\u5b78\u5408\u6210\u751f\u7269\u7fa4\u843d\uff0c\u5c55\u73fe\u4e86\u5728\u7f3a\u4e4f\u5149\u5408\u4f5c\u7528\u7684\u60c5\u6cc1\u4e0b\uff0c\u5143\u7d20\u5faa\u74b0\u5982\u4f55\u9a45\u52d5\u751f\u547d\u5947\u8e5f\u7684\u53e6\u4e00\u7a2e\u53ef\u80fd\u3002",
  "\x43\x6c":
    "\u6c2f\x28\x43\x68\x6c\x6f\x72\x69\x6e\x65\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x43\x6c\uff0c\u539f\u5b50\u5e8f\x20\x31\x37\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u4e09\u9031\u671f\u3001\u7b2c\x20\x31\x37\x20\u65cf\x28\u9e75\u7d20\uff0c\x70\x20\u5340\u584a\x29\uff0c\u662f\u81ea\u7136\u754c\u4e2d\u5316\u5b78\u6027\u8cea\u6975\u5176\u6d3b\u6f51\u7684\u975e\u91d1\u5c6c\u5143\u7d20\u3002\u5176\u540d\u7a31\u6e90\u65bc\u5e0c\u81d8\u8a9e\u300c\x63\x68\x6c\x6f\x72\x6f\x73\u300d\uff0c\u610f\u70ba\u300c\u9ec3\u7da0\u8272\u300d\uff0c\u63cf\u8ff0\u4e86\u5176\u55ae\u8cea\u6c23\u9ad4\u7684\u7279\u5fb5\u8272\u6fa4\u3002\x31\x37\x37\x34\x20\u5e74\u7531\u745e\u5178\u5316\u5b78\u5bb6\u820d\u52d2\x28\x43\x61\x72\x6c\x20\x57\x69\x6c\x68\x65\x6c\x6d\x20\x53\x63\x68\x65\x65\x6c\x65\x29\u900f\u904e\u4e8c\u6c27\u5316\u9333\u8207\u9e7d\u9178\u53cd\u61c9\u9996\u6b21\u88fd\u5f97\uff0c\u4f46\u7576\u6642\u8aa4\u4ee5\u70ba\u662f\u5316\u5408\u7269\uff0c\u76f4\u5230\x20\x31\x38\x31\x30\x20\u5e74\u624d\u7531\u6234\u7dad\x28\x48\x75\x6d\x70\x68\x72\x79\x20\x44\x61\x76\x79\x29\u78ba\u8a8d\u5176\u55ae\u8cea\u5730\u4f4d\u3002\u6c2f\u5728\u81ea\u7136\u754c\u4e3b\u8981\u4ee5\u6c2f\u96e2\u5b50\x28\x43\x6c\u207b\x29\u5f62\u5f0f\u5b58\u5728\u65bc\u6d77\u6c34\u8207\u7926\u9e7d\u4e2d\uff0c\u662f\u7dad\u6301\u751f\u7269\u9ad4\u6ef2\u900f\u58d3\u8207\u80c3\u9178\x28\x48\x43\x6c\x29\u7684\u6838\u5fc3\u6210\u5206\u3002\x0a\x0a\u5728\u5fae\u89c0\u7279\u5fb5\u4e0a\uff0c\u6c2f\u7684\u96fb\u5b50\u7d44\u614b\u70ba\x20\x5b\x4e\x65\x5d\x33\x73\u00b2\x33\x70\u2075\uff0c\u5177\u5099\u9ad8\u9054\x20\x33\x2e\x31\x36\x20\u7684\u96fb\u8ca0\u5ea6\uff0c\u8868\u73fe\u51fa\u5f37\u70c8\u7684\u596a\u53d6\u96fb\u5b50\u50be\u5411\u3002\u5728\u6a19\u6e96\u72c0\u614b\u4e0b\uff0c\u6c2f\u4ee5\u96d9\u539f\u5b50\u5206\u5b50\x28\x43\x6c\u2082\x29\u5f62\u5f0f\u5b58\u5728\uff0c\u5177\u5099\u5f37\u6c27\u5316\u6027\u3002\u6c2f\u80fd\u8207\u5e7e\u4e4e\u6240\u6709\u91d1\u5c6c\u53cd\u61c9\u751f\u6210\u96e2\u5b50\u9375\u7d50\u6676\uff0c\u4ea6\u80fd\u8207\u6c2b\u6c23\u53cd\u61c9\u751f\u6210\u6c2f\u5316\u6c2b\x28\x48\x43\x6c\x29\u3002\u5728\u53f0\u7063\u9ad8\u4e2d\u8ab2\u7a0b\u4e2d\uff0c\u6c2f\u6c23\u7684\u88fd\u5099\u8207\u5176\u5728\u6c34\u4e2d\u7684\u6b67\u5316\u53cd\u61c9\x28\u751f\u6210\x20\x48\x43\x6c\x20\u8207\x20\x48\x43\x6c\x4f\x29\u662f\u7406\u89e3\u9178\u9e7c\u5e73\u885d\u8207\u6c27\u5316\u9084\u539f\u7684\u7d93\u5178\u6848\u4f8b\u3002\u6b21\u6c2f\u9178\x28\x48\x43\x6c\x4f\x29\u5177\u5099\u6975\u5f37\u7684\u6c27\u5316\u80fd\u529b\uff0c\u662f\u6f02\u767d\u6c34\u8207\u81ea\u4f86\u6c34\u6d88\u6bd2\u6280\u8853\u7684\u5316\u5b78\u57fa\u790e\u3002\x0a\x0a\u5728\u73fe\u4ee3\u5de5\u696d\u8207\u6750\u6599\u79d1\u5b78\u4e2d\uff0c\u6c2f\u662f\u5408\u6210\u805a\u6c2f\u4e59\u70ef\x28\x50\x56\x43\x29\u7684\u6838\u5fc3\u539f\u6599\uff0c\u9019\u7a2e\u6cdb\u7528\u5851\u81a0\u5ee3\u6cdb\u61c9\u7528\u65bc\u5efa\u7bc9\u7ba1\u6750\u8207\u91ab\u7642\u5668\u6750\u3002\u5728\u96fb\u5316\u5b78\u9818\u57df\uff0c\u6c2f\u6c23\u7684\u6a19\u6e96\u9084\u539f\u96fb\u4f4d\x28\x45\u2070\x20\u2248\x20\x2b\x31\x2e\x33\x36\x20\x56\x29\u4f7f\u5176\u5e38\u4f5c\u70ba\u5f37\u6c27\u5316\u5291\u3002\u534a\u5c0e\u9ad4\u7522\u696d\u5247\u5229\u7528\u9ad8\u7d14\u5ea6\u6c2f\u6c23\u9032\u884c\u300c\u4e7e\u5f0f\u8755\u523b\u300d\x28\x44\x72\x79\x20\x45\x74\x63\x68\x69\x6e\x67\x29\uff0c\u4ee5\u7cbe\u78ba\u79fb\u9664\u6676\u5713\u8868\u9762\u7684\u591a\u9918\u6750\u6599\u3002\u74b0\u5883\u5de5\u7a0b\u4e2d\uff0c\u96d6\u7136\u6c2f\u662f\u512a\u826f\u7684\u6d88\u6bd2\u5291\uff0c\u4f46\u5176\u8207\u6c34\u4e2d\u6709\u6a5f\u7269\u751f\u6210\u7684\u526f\u7522\u7269\x28\u5982\u4e09\u9e75\u7532\u70f7\x29\u4ea6\u662f\u73fe\u4ee3\u6de8\u6c34\u6280\u8853\u4e2d\u9700\u56b4\u683c\u76e3\u63a7\u7684\u81f4\u764c\u98a8\u96aa\u56e0\u5b50\u3002\x0a\x0a\u6c2f\u5c55\u73fe\u51fa\u8a31\u591a\u986f\u8457\u7684\u5316\u5b78\u77db\u76fe\u6027\u3002\u96d6\u7136\u6c2f\u6c23\u5728\u7b2c\u4e00\u6b21\u4e16\u754c\u5927\u6230\u4e2d\u66fe\u88ab\u4f5c\u70ba\u7a92\u606f\u6027\u6bd2\u6c23\u4f7f\u7528\uff0c\u4f46\u5176\u96e2\u5b50\u5f62\u614b\x28\x43\x6c\u207b\x29\u537b\u662f\u751f\u547d\u9ad4\u4e0d\u53ef\u6216\u7f3a\u7684\u96fb\u89e3\u8cea\u3002\u7269\u7406\u7279\u6027\u4e0a\uff0c\u6c2f\u6c23\u7684\u5bc6\u5ea6\u7d04\u70ba\u7a7a\u6c23\u7684\x20\x32\x2e\x35\x20\u500d\uff0c\u9019\u4f7f\u5176\u5728\u6d29\u6f0f\u6642\u6703\u7a4d\u805a\u65bc\u4f4e\u7aaa\u8655\uff0c\u5f62\u6210\u96b1\u5f62\u4e14\u81f4\u547d\u7684\u5a01\u8105\u3002\u53cd\u76f4\u89ba\u7684\u662f\uff0c\u5118\u7ba1\u6c2f\u5316\u9209\x28\u98df\u9e7d\x29\u6975\u6613\u6eb6\u65bc\u6c34\uff0c\u4f46\u67d0\u4e9b\u6c2f\u5316\u7269\u5982\u6c2f\u5316\u9280\x28\x41\x67\x43\x6c\x29\u537b\u662f\u6975\u96e3\u6eb6\u7684\u767d\u8272\u6c89\u6fb1\uff0c\u9019\u4e00\u7279\u6027\u88ab\u5ee3\u6cdb\u61c9\u7528\u65bc\u5316\u5b78\u5206\u6790\u4e2d\u7684\u6c2f\u96e2\u5b50\u5b9a\u91cf\u6aa2\u6e2c\u3002\u9019\u7a2e\u5f9e\u6c11\u751f\u5fc5\u9700\u54c1\u5230\u9ad8\u7aef\u88fd\u7a0b\u8f09\u9ad4\u7684\u8f49\u8b8a\uff0c\u7cbe\u78ba\u9ad4\u73fe\u4e86\u6c2f\u5143\u7d20\u5728\u81ea\u7136\u8207\u5de5\u696d\u9593\u7684\u95dc\u9375\u5730\u4f4d\u3002",
  "\x41\x72":
    "\u6c2c\x28\x41\x72\x67\x6f\x6e\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x41\x72\uff0c\u539f\u5b50\u5e8f\x20\x31\x38\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u4e09\u9031\u671f\u3001\u7b2c\x20\x31\x38\x20\u65cf\x28\u7a00\u6709\u6c23\u9ad4\uff0c\x70\x20\u5340\u584a\x29\uff0c\u662f\u5927\u6c23\u4e2d\u542b\u91cf\u6700\u8c50\u5bcc\u7684\u7a00\u6709\u6c23\u9ad4\x28\u7d04\u4f54\u9ad4\u7a4d\u7684\x20\x30\x2e\x39\x33\x25\x29\u3002\u5176\u540d\u7a31\u6e90\u65bc\u5e0c\u81d8\u8a9e\u300c\x61\x72\x67\x6f\x73\u300d\uff0c\u610f\u70ba\u300c\u61f6\u60f0\u300d\u6216\u300c\u4e0d\u6d3b\u6f51\u300d\uff0c\u53cd\u6620\u4e86\u5176\u6975\u9ad8\u7684\u5316\u5b78\u7a69\u5b9a\u6027\u3002\x31\x38\x39\x34\x20\u5e74\u7531\u745e\u5229\u7537\u7235\x28\x4c\x6f\x72\x64\x20\x52\x61\x79\x6c\x65\x69\x67\x68\x29\u8207\u62c9\u59c6\u9f4a\x28\x57\x69\x6c\x6c\x69\x61\x6d\x20\x52\x61\x6d\x73\x61\x79\x29\u900f\u904e\u79fb\u9664\u7a7a\u6c23\u4e2d\u7684\u6c27\u3001\u6c2e\u8207\u4e8c\u6c27\u5316\u78b3\u5f8c\u5206\u96e2\u5f97\u51fa\u3002\u6c2c\u662f\u7a00\u6709\u6c23\u9ad4\u5bb6\u65cf\u4e2d\u9996\u500b\u88ab\u5206\u96e2\u51fa\u7684\u6210\u54e1\uff0c\u5176\u767c\u73fe\u6253\u7834\u4e86\u7576\u6642\u8a8d\u70ba\u7a7a\u6c23\u50c5\u7531\u6c2e\u8207\u6c27\u7d44\u6210\u7684\u50b3\u7d71\u8a8d\u77e5\u3002\x0a\x0a\u6c2c\u7684\u96fb\u5b50\u7d44\u614b\u70ba\x20\x5b\x4e\x65\x5d\x33\x73\u00b2\x33\x70\u2076\uff0c\u64c1\u6709\u5b8c\u7f8e\u7684\u516b\u9685\u9ad4\u7d50\u69cb\uff0c\u4f7f\u5176\u7b2c\u4e00\u96fb\u96e2\u80fd\u6975\u9ad8\u4e14\u96fb\u8ca0\u5ea6\u5e7e\u4e4e\u70ba\u96f6\u3002\u6c2c\u5728\u6a19\u6e96\u72c0\u614b\u4e0b\u70ba\u7121\u8272\u3001\u7121\u5473\u7684\u55ae\u539f\u5b50\u6c23\u9ad4\uff0c\u7531\u65bc\u539f\u5b50\u9593\u51e1\u5f97\u74e6\u529b\u5fae\u5f31\uff0c\u5176\u6cb8\u9ede\u50c5\u70ba\x20\x2d\x31\x38\x35\x2e\x38\x20\u00b0\x43\u3002\u5728\u9ad8\u4e2d\u5316\u5b78\u63a2\u8a0e\u539f\u5b50\u91cf\u8207\u5206\u5b50\u91cf\u7684\u5dee\u7570\u6642\uff0c\u6c2c\u5e38\u88ab\u7528\u4f86\u5c0d\u6bd4\u96d9\u539f\u5b50\u5206\u5b50\u6c23\u9ad4\u3002\u6b64\u5916\uff0c\u6c2c\u5728\u5927\u6c23\u4e2d\u7684\u542b\u91cf\u9060\u9ad8\u65bc\u5176\u4ed6\u7a00\u6709\u6c23\u9ad4\uff0c\u4e3b\u8981\u6e90\u65bc\u5730\u6bbc\u4e2d\u9240\u7684\u540c\u4f4d\u7d20\x28\u2074\u2070\x4b\x29\u7d93\u7531\u96fb\u5b50\u6355\u7372\x28\x45\x6c\x65\x63\x74\x72\x6f\x6e\x20\x43\x61\x70\x74\x75\x72\x65\x29\u8870\u8b8a\u800c\u7522\u751f\u7684\u7d2f\u7a4d\u3002\x0a\x0a\u5728\u73fe\u4ee3\u5de5\u696d\u8207\u5c16\u7aef\u79d1\u6280\u61c9\u7528\u4e2d\uff0c\u6c2c\u7684\u60f0\u6027\u4f7f\u5176\u6210\u70ba\u7406\u60f3\u7684\u300c\u4fdd\u8b77\u6c23\u9ad4\u300d\u3002\u5728\u710a\u63a5\u5de5\u7a0b\x28\u5982\x20\x54\x49\x47\x20\u710a\u63a5\x29\u4e2d\uff0c\u6c2c\u80fd\u9694\u7d55\u7a7a\u6c23\uff0c\u9632\u6b62\u9ad8\u6eab\u4e0b\u7684\u91d1\u5c6c\u767c\u751f\u6c27\u5316\uff1b\u5728\u534a\u5c0e\u9ad4\u7522\u696d\uff0c\u77fd\u6676\u5713\u7684\u751f\u9577\u88fd\u7a0b\u5fc5\u9808\u5728\u7d14\u6c2c\u74b0\u5883\u4e0b\u9032\u884c\uff0c\u4ee5\u78ba\u4fdd\u6676\u683c\u7d50\u69cb\u7684\u5b8c\u7f8e\u3002\u6b64\u5916\uff0c\u7531\u65bc\u6c2c\u7684\u71b1\u50b3\u5c0e\u7387\u4f4e\u65bc\u7a7a\u6c23\uff0c\u5b83\u5e38\u88ab\u586b\u5145\u65bc\u96d9\u5c64\u4e2d\u7a7a\u73bb\u7483\u4e2d\u4f5c\u70ba\u9694\u71b1\u5c64\uff0c\u63d0\u5347\u80fd\u6e90\u6548\u7387\u3002\u5728\u7167\u660e\u6280\u8853\u9818\u57df\uff0c\u6c2c\u6c23\u8207\u5fae\u91cf\u6c5e\u84b8\u6c23\u6df7\u5408\u5f8c\uff0c\u5728\u653e\u96fb\u7ba1\u4e2d\u6703\u767c\u51fa\u6de1\u85cd\u8272\u7684\u5149\u8292\uff0c\u662f\u51b7\u9670\u6975\u71c8\u7ba1\u8207\u87a2\u5149\u71c8\u7684\u5e38\u898b\u586b\u5145\u6c23\u9ad4\u3002\x0a\x0a\u95dc\u65bc\u6c2c\u7684\u79d1\u5b78\u7814\u7a76\u5c55\u73fe\u4e86\u5176\u5728\u5e74\u4ee3\u6e2c\u5b9a\u4e0a\u7684\u7368\u7279\u50f9\u503c\u3002\u300c\u9240\uff0d\u6c2c\u5b9a\u5e74\u6cd5\u300d\x28\x4b\x2d\x41\x72\x20\x64\x61\x74\x69\x6e\x67\x29\u5229\u7528\x20\u2074\u2070\x4b\x20\u8870\u8b8a\u70ba\x20\u2074\u2070\x41\x72\x20\u7684\u901f\u7387\uff0c\u6210\u70ba\u5730\u8cea\u5b78\u5bb6\u6e2c\u91cf\u6578\u767e\u842c\u5e74\u524d\u706b\u5c71\u5ca9\u5e74\u9f61\u7684\u95dc\u9375\u5de5\u5177\u3002\u6709\u8da3\u7684\u662f\uff0c\u96d6\u7136\u6c2c\u88ab\u8996\u70ba\u6975\u5ea6\u60f0\u6027\uff0c\u4f46\u5728\u6975\u4f4e\u6eab\u8207\u7279\u6b8a\u689d\u4ef6\u4e0b\uff0c\u79d1\u5b78\u5bb6\u5df2\u6210\u529f\u5408\u6210\u51fa\u9996\u500b\u7a69\u5b9a\u7684\u6c2c\u5316\u5408\u7269\u2014\u2014\u6c1f\u6c2c\u5316\u6c2b\x28\x48\x41\x72\x46\x29\uff0c\u9019\u6311\u6230\u4e86\u5c0d\u7a00\u6709\u6c23\u9ad4\u5b8c\u5168\u4e0d\u53c3\u8207\u9375\u7d50\u7684\u50b3\u7d71\u5b9a\u7fa9\u3002\u9019\u7a2e\u5f9e\u300c\u61f6\u60f0\u300d\u5230\u53c3\u8207\u7cbe\u5bc6\u79d1\u6280\u8207\u5730\u8cea\u63a2\u7d22\u7684\u89d2\u8272\u8f49\u8b8a\uff0c\u4f7f\u6c2c\u6210\u70ba\u7a00\u6709\u6c23\u9ad4\u7814\u7a76\u4e2d\u6975\u5177\u4ee3\u8868\u6027\u7684\u5143\u7d20\u3002",
  "\x4b":
    "\u9240\x28\x50\x6f\x74\x61\x73\x73\x69\x75\x6d\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x4b\uff0c\u539f\u5b50\u5e8f\x20\x31\x39\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u56db\u9031\u671f\u3001\u7b2c\x20\x31\x20\u65cf\x28\u9e7c\u91d1\u5c6c\uff0c\x73\x20\u5340\u584a\x29\uff0c\u662f\u6975\u5ea6\u6d3b\u6f51\u4e14\u5c0d\u751f\u547d\u81f3\u95dc\u91cd\u8981\u7684\u91d1\u5c6c\u5143\u7d20\u3002\u82f1\u6587\u540d\u7a31\u6e90\u65bc\u300c\x70\x6f\x74\x61\x73\x68\u300d\x28\u8349\u6728\u7070\x29\uff0c\u7b26\u865f\x20\x4b\x20\u5247\u4f86\u81ea\u62c9\u4e01\u8a9e\u300c\x4b\x61\x6c\x69\x75\x6d\u300d\u3002\x31\x38\x30\x37\x20\u5e74\u7531\u6234\u7dad\x28\x48\x75\x6d\x70\x68\x72\x79\x20\x44\x61\x76\x79\x29\u900f\u904e\u96fb\u89e3\u7194\u878d\u6c2b\u6c27\u5316\u9240\u9996\u6b21\u5206\u96e2\u51fa\u91d1\u5c6c\u9240\uff0c\u4ed6\u4e5f\u56e0\u6b64\u89c0\u5bdf\u5230\u9240\u5728\u6c34\u4e2d\u5287\u70c8\u53cd\u61c9\u5f15\u767c\u7684\u7d2b\u8272\u706b\u7130\u3002\u9240\u5728\u5730\u6bbc\u4e2d\u542b\u91cf\u6392\u540d\u7b2c\u4e03\uff0c\u4e3b\u8981\u4ee5\u7926\u7269\u9e7d\u5f62\u5f0f\u5b58\u5728\uff0c\u662f\u7d30\u80de\u5167\u4e3b\u8981\u7684\u967d\u96e2\u5b50\uff0c\u8ca0\u8cac\u7dad\u6301\u795e\u7d93\u50b3\u5c0e\u8207\u5fc3\u81df\u640f\u52d5\u3002\x0a\x0a\u5728\u7269\u7406\u8207\u5316\u5b78\u6027\u8cea\u4e0a\uff0c\u9240\u7684\u96fb\u5b50\u7d44\u614b\u70ba\x20\x5b\x41\x72\x5d\x34\x73\u00b9\uff0c\u5176\u539f\u5b50\u534a\u5f91\u8f03\u540c\u9031\u671f\u7684\u9223\u5927\uff0c\u7b2c\u4e00\u96fb\u96e2\u80fd\u6975\u4f4e\u3002\u9240\u5c55\u73fe\u51fa\u5178\u578b\u7684\u9e7c\u91d1\u5c6c\u7279\u5fb5\uff1a\u5176\u706b\u7130\u53cd\u61c9\u5448\u73fe\u7279\u5fb5\u6027\u7684\u6de1\u7d2b\u8272\x28\u900f\u904e\u9237\u85cd\u73bb\u7483\u89c0\u5bdf\u66f4\u4f73\x29\uff1b\u8207\u6c34\u53cd\u61c9\u7684\u901f\u5ea6\u6bd4\u9209\u66f4\u5287\u70c8\uff0c\u91cb\u653e\u51fa\u7684\u6c2b\u6c23\u6703\u7acb\u5373\u56e0\u53cd\u61c9\u71b1\u800c\u81ea\u71c3\u3002\u9240\u7684\u5bc6\u5ea6\u50c5\u7d04\x20\x30\x2e\x38\x36\x20\x67\x2f\x63\x6d\u00b3\uff0c\u80fd\u6d6e\u65bc\u6c34\u9762\u3002\u5728\u9ad8\u4e2d\u5316\u5b78\u5be6\u9a57\u4e2d\uff0c\u9240\u5fc5\u9808\u4fdd\u5b58\u5728\u7926\u7269\u6cb9\u4e2d\u4ee5\u9694\u7d55\u7a7a\u6c23\u8207\u6c34\u5206\uff0c\u56e0\u70ba\u5176\u8868\u9762\u6703\u8fc5\u901f\u6c27\u5316\u4e26\u5f62\u6210\u53ef\u80fd\u5f15\u767c\u7206\u70b8\u7684\u904e\u6c27\u5316\u7269\u5c64\u3002\x0a\x0a\u5728\u53f0\u7063\u9ad8\u4e2d\u8ab2\u7db1\u8207\u8fb2\u696d\u8108\u7d61\u4e2d\uff0c\u9240\u662f\u80a5\u6599\u4e09\u5927\u4e3b\u6210\u5206\x28\x4e\x2d\x50\x2d\x4b\x29\u4e2d\u8abf\u7bc0\u690d\u7269\u6c34\u5206\u5e73\u8861\u8207\u9175\u7d20\u6d3b\u6027\u7684\u6838\u5fc3\u3002\u5728\u96fb\u5316\u5b78\u9818\u57df\uff0c\u9240\u7684\u6a19\u6e96\u6c27\u5316\u96fb\u4f4d\x28\x45\u2070\x20\u2248\x20\x2b\x32\x2e\x39\x33\x20\x56\x29\u6975\u8ca0\uff0c\u4f7f\u5176\u6210\u70ba\u6700\u5f37\u5927\u7684\u9084\u539f\u5291\u4e4b\u4e00\u3002\u73fe\u4ee3\u80fd\u6e90\u7814\u7a76\u4e2d\uff0c\u9240\u96e2\u5b50\u96fb\u6c60\x28\x4b\x2d\x69\x6f\x6e\x20\x62\x61\x74\x74\x65\x72\x69\x65\x73\x29\u56e0\u9240\u8cc7\u6e90\u5728\u5168\u7403\u5206\u5e03\u5747\u52fb\u4e14\u80fd\u91cf\u5bc6\u5ea6\u6f5b\u529b\u5927\uff0c\u88ab\u8996\u70ba\u672a\u4f86\u5927\u898f\u6a21\u5132\u80fd\u7cfb\u7d71\u7684\u7af6\u722d\u8005\u3002\u6b64\u5916\uff0c\u9209\u9240\u5408\u91d1\x28\x4e\x61\x4b\x29\u5728\u5e38\u6eab\u4e0b\u5448\u73fe\u6db2\u614b\uff0c\u5177\u5099\u6975\u9ad8\u7684\u71b1\u50b3\u5c0e\u6548\u80fd\uff0c\u88ab\u61c9\u7528\u65bc\u67d0\u4e9b\u6838\u53cd\u61c9\u7210\u7684\u51b7\u537b\u7cfb\u7d71\u4e2d\u3002\x0a\x0a\u9240\u5c55\u73fe\u51fa\u6975\u81f4\u7684\u6a5f\u68b0\u6027\u8cea\u8207\u751f\u7269\u91cd\u8981\u6027\u3002\u5b83\u6975\u5176\u67d4\u8edf\uff0c\u5728\u5e38\u6eab\u4e0b\u53ef\u4ee5\u7528\u666e\u901a\u62b9\u5200\u8f15\u6613\u5207\u958b\uff0c\u66b4\u9732\u51fa\u9583\u4eae\u7684\u9280\u767d\u8272\u5207\u9762\uff0c\u4f46\u8a72\u8868\u9762\u6703\u4ee5\u8089\u773c\u53ef\u898b\u7684\u901f\u5ea6\u8fc5\u901f\u8f49\u70ba\u7070\u6697\u3002\u5728\u751f\u7269\u9ad4\u5167\uff0c\u9209\u9240\u5e6b\u6d66\x28\x4e\x61\u207a\x2f\x4b\u207a\x20\x70\x75\x6d\x70\x29\u8017\u8cbb\u4e86\u4eba\u9ad4\u7d04\u4e09\u5206\u4e4b\u4e00\u7684\u80fd\u91cf\u4f86\u7dad\u6301\u7d30\u80de\u819c\u5167\u5916\u7684\u96fb\u4f4d\u5dee\uff0c\u9019\u662f\u6240\u6709\u751f\u7406\u529f\u80fd\u7684\u7269\u7406\u57fa\u790e\u3002\u53cd\u76f4\u89ba\u7684\u662f\uff0c\u96d6\u7136\u9240\u5143\u7d20\u5c0d\u65bc\u751f\u547d\u4e0d\u53ef\u6216\u7f3a\uff0c\u4f46\u9ad8\u6fc3\u5ea6\u7684\u9240\u96e2\u5b50\x28\u5982\u6c2f\u5316\u9240\u6eb6\u6db2\x29\u537b\u6703\u5e72\u64fe\u5fc3\u96fb\u4fe1\u865f\uff0c\u5c0e\u81f4\u5fc3\u81df\u9a5f\u505c\uff0c\u9019\u7a2e\u7531\u300c\u751f\u547d\u652f\u67f1\u300d\u5230\u300c\u751f\u7406\u5a01\u8105\u300d\u7684\u5fae\u5999\u5e73\u8861\uff0c\u5c55\u73fe\u4e86\u9e7c\u91d1\u5c6c\u5728\u751f\u7269\u5316\u5b78\u4e2d\u9a5a\u4eba\u7684\u8abf\u63a7\u529b\u3002",
  "\x43\x61":
    "\u9223\x28\x43\x61\x6c\x63\x69\x75\x6d\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x43\x61\uff0c\u539f\u5b50\u5e8f\x20\x32\x30\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u56db\u9031\u671f\u3001\u7b2c\x20\x32\x20\u65cf\x28\u9e7c\u571f\u91d1\u5c6c\uff0c\x73\x20\u5340\u584a\x29\uff0c\u662f\u69cb\u6210\u751f\u7269\u9aa8\u67b6\u8207\u5730\u7403\u5ca9\u77f3\u5708\u7684\u91cd\u8981\u5143\u7d20\u3002\u5176\u540d\u7a31\u6e90\u65bc\u62c9\u4e01\u8a9e\u300c\x63\x61\x6c\x78\u300d\uff0c\u610f\u6307\u77f3\u7070\u3002\x31\x38\x30\x38\x20\u5e74\u7531\u6234\u7dad\x28\x48\x75\x6d\x70\x68\x72\x79\x20\x44\x61\x76\x79\x29\u900f\u904e\u96fb\u89e3\u6c5e\u8207\u77f3\u7070\u7684\u6df7\u5408\u7269\u88fd\u5f97\u9223\u6c5e\u9f4a\uff0c\u96a8\u5f8c\u84b8\u993e\u51fa\u7d14\u9223\u3002\u9223\u5728\u5730\u6bbc\u8c50\u5ea6\u6392\u540d\u7b2c\u4e94\uff0c\u5ee3\u6cdb\u5b58\u5728\u65bc\u77f3\u7070\u5ca9\x28\x43\x61\x43\x4f\u2083\x29\u3001\u77f3\u818f\x28\x43\x61\x53\x4f\u2084\u00b7\x32\x48\u2082\x4f\x29\u8207\u6c1f\u77f3\u4e2d\uff0c\u4e0d\u50c5\u662f\u73fe\u4ee3\u5efa\u7bc9\u5de5\u696d\u7684\u57fa\u77f3\uff0c\u66f4\u662f\u591a\u7d30\u80de\u751f\u7269\u9032\u884c\u4fe1\u865f\u50b3\u905e\u8207\u7dad\u6301\u7d50\u69cb\u5f37\u5ea6\u7684\u6838\u5fc3\u5143\u7d20\u3002\x0a\x0a\u5728\u5316\u5b78\u884c\u70ba\u4e0a\uff0c\u9223\u7684\u96fb\u5b50\u7d44\u614b\u70ba\x20\x5b\x41\x72\x5d\x34\x73\u00b2\uff0c\u50be\u5411\u5931\u53bb\u5169\u500b\u50f9\u96fb\u5b50\u5f62\u6210\u7a69\u5b9a\u7684\x20\x43\x61\u00b2\u207a\u3002\u76f8\u8f03\u65bc\u540c\u9031\u671f\u7684\u9240\uff0c\u9223\u7684\u539f\u5b50\u534a\u5f91\u8f03\u5c0f\u4e14\u6709\u6548\u6838\u96fb\u8377\u8f03\u5927\uff0c\u56e0\u6b64\u91d1\u5c6c\u9375\u8f03\u5f37\uff0c\u786c\u5ea6\u8207\u7194\u9ede\u4e5f\u986f\u8457\u63d0\u5347\u3002\u9223\u7684\u706b\u7130\u53cd\u61c9\u5448\u73fe\u7279\u5fb5\u7684\u78da\u7d05\u8272\u3002\u96d6\u7136\u9223\u5728\u5e38\u6eab\u4e0b\u6703\u8207\u6c34\u7de9\u6162\u53cd\u61c9\u91cb\u653e\u6c2b\u6c23\uff0c\u4f46\u5728\u7a7a\u6c23\u4e2d\u5176\u8868\u9762\u6703\u5f62\u6210\u4e0d\u5920\u7dfb\u5bc6\u7684\u6c27\u5316\u819c\uff0c\u56e0\u6b64\u4ecd\u9700\u59a5\u5584\u4fdd\u5b58\u3002\u5728\u9ad8\u4e2d\u5316\u5b78\u63a2\u8a0e\u6eb6\u6db2\u5e73\u8861\u6642\uff0c\u78b3\u9178\u9223\x28\x43\x61\x43\x4f\u2083\x29\u7684\u6eb6\u89e3\u5e73\u8861\u8207\u5176\u5728\u542b\u6709\x20\x43\x4f\u2082\x20\u7684\u6c34\u4e2d\u751f\u6210\u78b3\u9178\u6c2b\u9223\x28\x43\x61\x28\x48\x43\x4f\u2083\x29\u2082\x29\u7684\u53cd\u61c9\uff0c\u662f\u7406\u89e3\u9418\u4e73\u77f3\u6d1e\u7a74\u5f62\u6210\u8207\u5730\u4e0b\u6c34\u786c\u5ea6\u8f49\u63db\u7684\u95dc\u9375\u57fa\u790e\u3002\x0a\x0a\u5728\u73fe\u4ee3\u5de5\u696d\u8207\u74b0\u5883\u79d1\u5b78\u9818\u57df\uff0c\u9223\u7684\u5316\u5408\u7269\u61c9\u7528\u7121\u6240\u4e0d\u5728\u3002\u77f3\u7070\x28\x43\x61\x4f\x29\u8207\u6d88\u77f3\u7070\x28\x43\x61\x28\x4f\x48\x29\u2082\x29\u5ee3\u6cdb\u7528\u65bc\u9178\u6027\u5ee2\u6c34\u8655\u7406\u3001\u571f\u58e4\u6539\u826f\u53ca\u6392\u7159\u812b\u786b\u5de5\u7a0b\u3002\u5efa\u7bc9\u9818\u57df\u5247\u4ee5\u6c34\u6ce5\u8207\u6df7\u51dd\u571f\u4f5c\u70ba\u4e3b\u8981\u6d88\u8cbb\u7aef\u3002\u5728\u91ab\u5b78\u61c9\u7528\u4e0a\uff0c\u9223\u96e2\u5b50\u662f\u808c\u8089\u6536\u7e2e\u3001\u8840\u6db2\u51dd\u56fa\u53ca\u795e\u7d93\u905e\u8cea\u91cb\u653e\u7684\u7b2c\u4e8c\u4fe1\u4f7f\uff0c\u5176\u6fc3\u5ea6\u5728\u4eba\u9ad4\u5167\u53d7\u5230\u8377\u723e\u8499\u7cbe\u5bc6\u8abf\u7bc0\u3002\u6b64\u5916\uff0c\u91d1\u5c6c\u9223\u5e38\u88ab\u7528\u4f5c\u51b6\u91d1\u904e\u7a0b\u4e2d\u7684\u9084\u539f\u5291\uff0c\u5354\u52a9\u5f9e\u7926\u7269\u4e2d\u63d0\u53d6\u927b\u3001\u92ef\u8207\u923e\u7b49\u6602\u8cb4\u91d1\u5c6c\u3002\x0a\x0a\u95dc\u65bc\u9223\u7684\u81ea\u7136\u898f\u5f8b\u5b58\u5728\u4e00\u500b\u8ff7\u4eba\u7684\u71b1\u529b\u5b78\u73fe\u8c61\uff1a\u6c2b\u6c27\u5316\u9223\x28\x43\x61\x28\x4f\x48\x29\u2082\x29\u7684\u6eb6\u89e3\u5ea6\u96a8\u6eab\u5ea6\u5347\u9ad8\u800c\u4e0b\u964d\uff0c\u9019\u8207\u5927\u591a\u6578\u56fa\u9ad4\u9e7d\u985e\u80cc\u9053\u800c\u99b3\u3002\u5728\u5730\u7403\u5316\u5b78\u4e2d\uff0c\u9223\u96e2\u5b50\u8207\u4e8c\u6c27\u5316\u78b3\u5f62\u6210\u7684\u78b3\u9178\u9e7d\u88dc\u511f\u6df1\u5ea6\x28\x43\x43\x44\x29\u662f\u6d77\u6d0b\u9178\u5316\u7684\u91cd\u8981\u7de9\u885d\u6a5f\u5236\u3002\u6709\u8da3\u7684\u662f\uff0c\u96d6\u7136\u91d1\u5c6c\u9223\u5728\u65e5\u5e38\u751f\u6d3b\u4e2d\u6975\u96e3\u4ee5\u7d14\u91d1\u5c6c\u5f62\u614b\u51fa\u73fe\uff0c\u4f46\u5b83\u5728\u4eba\u985e\u6587\u660e\u4e2d\u7684\u75d5\u8de1\u537b\u662f\u6c38\u6046\u7684\u2014\u2014\u5f9e\u53e4\u57c3\u53ca\u91d1\u5b57\u5854\u7684\u77f3\u7070\u5ca9\u5230\u73fe\u4ee3\u6469\u5929\u5927\u6a13\u7684\u92fc\u7b4b\u6df7\u51dd\u571f\uff0c\u9223\u59cb\u7d42\u652f\u6490\u8457\u5b8f\u89c0\u4e16\u754c\u7684\u7d50\u69cb\u3002\u9019\u7a2e\u5f9e\u5fae\u89c0\u4fe1\u865f\u50b3\u905e\u5230\u5b8f\u89c0\u5de5\u7a0b\u7d50\u69cb\u7684\u8de8\u5ea6\uff0c\u4f7f\u9223\u6210\u70ba\u9031\u671f\u8868\u4e2d\u529f\u80fd\u6700\u70ba\u5747\u8861\u7684\u5143\u7d20\u4e4b\u4e00\u3002",
  "\x53\x63":
    "\u9227\x28\x53\x63\x61\x6e\x64\x69\x75\x6d\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x53\x63\uff0c\u539f\u5b50\u5e8f\x20\x32\x31\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u56db\u9031\u671f\u3001\u7b2c\x20\x33\x20\u65cf\x28\u7b2c\u4e00\u904e\u6e21\u5143\u7d20\u7cfb\u5217\uff0c\x64\x20\u5340\u584a\x29\u3002\u5176\u540d\u7a31\u6e90\u65bc\u62c9\u4e01\u8a9e\u300c\x53\x63\x61\x6e\x64\x69\x61\u300d\uff0c\u610f\u6307\u65af\u582a\u5730\u90a3\u7dad\u4e9e\u534a\u5cf6\u3002\x31\x38\x37\x39\x20\u5e74\u7531\u745e\u5178\u5316\u5b78\u5bb6\u5c3c\u723e\u68ee\x28\x4c\x61\x72\x73\x20\x46\x72\x65\x64\x72\x69\x6b\x20\x4e\x69\x6c\x73\x6f\x6e\x29\u5728\u5206\u6790\u77fd\u9239\u91d4\u7926\u6642\u9996\u6b21\u5206\u96e2\u3002\u9227\u662f\u9580\u5f97\u5217\u592b\u9810\u8a00\u4e2d\u7684\u300c\u985e\u787c\u300d\x28\x45\x6b\x61\x2d\x62\x6f\x72\x6f\x6e\x29\uff0c\u5176\u767c\u73fe\u6709\u529b\u5730\u8b49\u5be6\u4e86\u9031\u671f\u8868\u7684\u9810\u6e2c\u80fd\u529b\u3002\u96d6\u7136\u9227\u5e38\u88ab\u6b78\u985e\u70ba\u300c\u7a00\u571f\u5143\u7d20\u300d\uff0c\u4f46\u5176\u5728\u5730\u6bbc\u4e2d\u7684\u8c50\u5ea6\u5176\u5be6\u9ad8\u65bc\u925b\u8207\u932b\uff0c\u50c5\u56e0\u5206\u5e03\u6975\u5176\u5206\u6563\u800c\u96e3\u4ee5\u5927\u898f\u6a21\u958b\u63a1\u3002\x0a\x0a\u9227\u7684\u96fb\u5b50\u7d44\u614b\u70ba\x20\x5b\x41\x72\x5d\x33\x64\u00b9\x34\x73\u00b2\uff0c\u5176\u5316\u5b78\u6027\u8cea\u6975\u5176\u55ae\u4e00\uff0c\u5e7e\u4e4e\u50c5\u5c55\u73fe\u51fa\x20\x2b\x33\x20\u6c27\u5316\u614b\u3002\u7531\u65bc\x20\x53\x63\u00b3\u207a\x20\u7684\u96e2\u5b50\u534a\u5f91\u8f03\u5c0f\u4e14\u5177\u6709\u8f03\u5f37\u7684\u6975\u5316\u80fd\u529b\uff0c\u5176\u5316\u5b78\u884c\u70ba\u8207\u92c1\x28\x41\x6c\x29\u5c55\u73fe\u51fa\u9a5a\u4eba\u7684\u76f8\u4f3c\u6027\uff0c\u800c\u975e\u5178\u578b\u7684\u904e\u6e21\u91d1\u5c6c\u3002\u5728\u9ad8\u4e2d\u5316\u5b78\u63a2\u8a0e\u904e\u6e21\u91d1\u5c6c\u7684\u5b9a\u7fa9\u6642\uff0c\u9227\u5e38\u88ab\u8996\u70ba\u4e00\u500b\u7279\u4f8b\uff1a\u7531\u65bc\u5176\u5f62\u6210\u96e2\u5b50\u5f8c\x20\x64\x20\u8ecc\u57df\u70ba\u7a7a\x28\x64\u2070\x29\uff0c\u6545\u5176\u5316\u5408\u7269\u901a\u5e38\u5448\u73fe\u7121\u8272\u4e14\u4e0d\u5177\u5099\u9806\u78c1\u6027\x28\x44\x69\x61\x6d\x61\x67\x6e\x65\x74\x69\x63\x29\uff0c\u9019\u8207\u5176\u4ed6\u5177\u6709\u8272\u5f69\u7e7d\u7d1b\x20\x64\x2d\x64\x20\u8ecc\u57df\u8e8d\u9077\u7684\u904e\u6e21\u91d1\u5c6c\u622a\u7136\u4e0d\u540c\u3002\x0a\x0a\u5728\u73fe\u4ee3\u61c9\u7528\u4e2d\uff0c\u9227\u662f\u9ad8\u6548\u80fd\u5408\u91d1\u7684\u95dc\u9375\u6dfb\u52a0\u5291\u3002\u92c1\u9227\u5408\u91d1\x28\x41\x6c\x2d\x53\x63\x20\x61\x6c\x6c\x6f\x79\x29\u5177\u5099\u6975\u9ad8\u7684\u5f37\u5ea6\u3001\u512a\u7570\u7684\u8010\u71b1\u6027\u8207\u826f\u597d\u7684\u710a\u63a5\u6027\u80fd\uff0c\u88ab\u5ee3\u6cdb\u61c9\u7528\u65bc\u822a\u592a\u5143\u4ef6\u3001\u6230\u9b25\u6a5f\u6a5f\u8eab\u4ee5\u53ca\u9ad8\u7aef\u9ad4\u80b2\u5668\u6750\x28\u5982\u7af6\u8cfd\u7d1a\u81ea\u884c\u8eca\u67b6\u8207\u68d2\u7403\u68cd\x29\u3002\u5728\u7167\u660e\u79d1\u6280\u9818\u57df\uff0c\u9227\u7898\u71c8\x28\x53\x63\x61\x6e\x64\x69\x75\x6d\x2d\x69\x6f\x64\x69\x64\x65\x20\x6c\x61\x6d\x70\x73\x29\u5229\u7528\u9227\u7684\u5149\u8b5c\u7279\u5fb5\uff0c\u80fd\u767c\u51fa\u6975\u5176\u63a5\u8fd1\u967d\u5149\u7684\u767d\u5149\uff0c\u6210\u70ba\u9ad4\u80b2\u5834\u9928\u8207\u5927\u578b\u651d\u5f71\u68da\u9ad8\u7167\u5ea6\u7167\u660e\u7684\u9996\u9078\u3002\u6b64\u5916\uff0c\u6c27\u5316\u9227\x28\x53\x63\u2082\x4f\u2083\x29\u4ea6\u88ab\u7528\u65bc\u88fd\u4f5c\u56fa\u614b\u6c27\u5316\u7269\u71c3\u6599\u96fb\u6c60\x28\x53\x4f\x46\x43\x29\u7684\u96fb\u89e3\u8cea\uff0c\u63d0\u5347\u5176\u5728\u8f03\u4f4e\u6eab\u5ea6\u4e0b\u7684\u5c0e\u96fb\u6548\u7387\u3002\x0a\x0a\u9227\u5c55\u73fe\u4e86\u904e\u6e21\u91d1\u5c6c\u4e2d\u7368\u7279\u7684\u300c\u985e\u4e3b\u65cf\u300d\u7279\u5fb5\uff0c\u5176\u7194\u9ede\u986f\u8457\u9ad8\u65bc\u5e38\u898b\u7684\u92c1\uff0c\u4f46\u5bc6\u5ea6\u537b\u50c5\u7d04\x20\x32\x2e\x39\x39\x20\x67\x2f\x63\x6d\u00b3\uff0c\u9019\u4f7f\u5176\u6210\u70ba\u6750\u6599\u79d1\u5b78\u4e2d\u5be6\u73fe\u300c\u9ad8\u5f37\u5ea6\u8207\u4f4e\u5bc6\u5ea6\u300d\u5e73\u8861\u7684\u6307\u6a19\u5143\u7d20\u3002\u6709\u8da3\u7684\u662f\uff0c\u96d6\u7136\u9227\u5728\u5730\u6bbc\u4e2d\u96e3\u4ee5\u63d0\u7149\uff0c\u4f46\u5728\u67d0\u4e9b\u6046\u661f\u7684\u5149\u8b5c\u89c0\u6e2c\u4e2d\u537b\u5c55\u73fe\u51fa\u6975\u9ad8\u7684\u8c50\u5ea6\u3002\u9019\u7a2e\u65e2\u64c1\u6709\u904e\u6e21\u91d1\u5c6c\u7684\u8eab\u5206\uff0c\u537b\u5728\u5316\u5b78\u884c\u70ba\u4e0a\u504f\u5411\u4e3b\u65cf\u5143\u7d20\u7684\u7279\u8cea\uff0c\u4f7f\u9227\u6210\u70ba\u7814\u7a76\u9031\u671f\u8868\u904e\u6e21\u5340\u908a\u754c\u898f\u5f8b\u7684\u6700\u4f73\u6848\u4f8b\u3002\u5176\u5728\u4f4e\u6eab\u4e0b\u5c0d\u6c27\u7684\u9ad8\u89aa\u548c\u529b\uff0c\u4e5f\u4f7f\u5176\u5728\u51b6\u91d1\u5de5\u696d\u4e2d\u626e\u6f14\u91cd\u8981\u7684\u9664\u6c27\u5291\u89d2\u8272\u3002",
  "\x54\x69":
    "\u9226\x28\x54\x69\x74\x61\x6e\x69\x75\x6d\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x54\x69\uff0c\u539f\u5b50\u5e8f\x20\x32\x32\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u56db\u9031\u671f\u3001\u7b2c\x20\x34\x20\u65cf\x28\x64\x20\u5340\u584a\x29\uff0c\u88ab\u8b7d\u70ba\u300c\u592a\u7a7a\u6642\u4ee3\u7684\u91d1\u5c6c\u300d\u3002\x31\x37\x39\x31\x20\u5e74\u7531\u82f1\u570b\u696d\u9918\u7926\u7269\u5b78\u5bb6\u683c\u96f7\u6208\u723e\x28\x57\x69\x6c\x6c\x69\x61\x6d\x20\x47\x72\x65\x67\x6f\x72\x29\u9996\u6b21\u767c\u73fe\uff0c\u96a8\u5f8c\u514b\u62c9\u666e\u7f85\u7279\x28\x4d\x61\x72\x74\x69\x6e\x20\x48\x65\x69\x6e\x72\x69\x63\x68\x20\x4b\x6c\x61\x70\x72\x6f\x74\x68\x29\u4ee5\u5e0c\u81d8\u795e\u8a71\u4e2d\u7684\u5de8\u4eba\u65cf\u300c\u6cf0\u5766\u300d\x28\x54\x69\x74\x61\x6e\x73\x29\u5c07\u5176\u547d\u540d\uff0c\u8c61\u5fb5\u5176\u9a5a\u4eba\u7684\u5f37\u5ea6\u3002\u9226\u5728\u5730\u6bbc\u4e2d\u7684\u8c50\u5ea6\u9ad8\u5c45\u7b2c\u4e5d\uff0c\u4e3b\u8981\u5b58\u5728\u65bc\u9226\u9435\u7926\u8207\u91d1\u7d05\u77f3\u4e2d\u3002\u5118\u7ba1\u5206\u5e03\u5ee3\u6cdb\uff0c\u4f46\u56e0\u5176\u5728\u6eab\u9ad8\u4e0b\u6975\u6613\u8207\u6c27\u3001\u6c2e\u53cd\u61c9\uff0c\u4eba\u985e\u76f4\u5230\x20\x31\x39\x31\x30\x20\u5e74\u624d\u6210\u529f\u88fd\u5f97\u9ad8\u7d14\u5ea6\u7684\u91d1\u5c6c\u9226\u3002\x0a\x0a\u9226\u7684\u96fb\u5b50\u7d44\u614b\u70ba\x20\x5b\x41\x72\x5d\x33\x64\u00b2\x34\x73\u00b2\uff0c\u6700\u7a69\u5b9a\u7684\u6c27\u5316\u614b\u70ba\x20\x2b\x34\x28\u5982\x20\x54\x69\x4f\u2082\x29\u3002\u9226\u6700\u986f\u8457\u7684\u5316\u5b78\u7279\u6027\u662f\u5353\u8d8a\u7684\u300c\u920d\u5316\u73fe\u8c61\u300d\x28\x50\x61\x73\x73\x69\x76\x61\x74\x69\x6f\x6e\x29\uff1a\u5728\u5927\u6c23\u4e2d\u5176\u8868\u9762\u6703\u8fc5\u901f\u751f\u6210\u4e00\u5c64\u6975\u5176\u7dfb\u5bc6\u3001\u900f\u660e\u4e14\u9644\u8457\u529b\u6975\u5f37\u7684\u4e8c\u6c27\u5316\u9226\u4fdd\u8b77\u819c\uff0c\u4f7f\u5176\u5728\u6d77\u6c34\u3001\u738b\u6c34\u53ca\u5927\u591a\u6578\u5f37\u9178\u4e2d\u5177\u5099\u6975\u4f73\u7684\u8010\u8150\u8755\u6027\u3002\u9226\u7684\u9ad8\u5f37\u5ea6\u91cd\u91cf\u6bd4\u8207\u512a\u7570\u7684\u5f48\u6027\u6a21\u6578\uff0c\u4f7f\u5176\u5728\u6a5f\u68b0\u6027\u8cea\u4e0a\u512a\u65bc\u92c1\u8207\u92fc\u3002\u5728\u9ad8\u4e2d\u5316\u5b78\u63a2\u8a0e\u932f\u5408\u7269\u6642\uff0c\u9226\u7684\u4f4e\u50f9\u614b\u96e2\u5b50\x28\u5982\x20\x54\x69\u00b3\u207a\x29\u5448\u73fe\u6de1\u7d2b\u8272\uff0c\u6e90\u65bc\u5176\x20\x64\x20\u8ecc\u57df\u7684\u96fb\u5b50\u8e8d\u9077\uff0c\u5e38\u88ab\u7528\u4f5c\u9084\u539f\u5291\u3002\x0a\x0a\u5728\u53f0\u7063\u9ad8\u4e2d\u6559\u6750\u8207\u73fe\u4ee3\u5de5\u696d\u4e2d\uff0c\u4e8c\u6c27\u5316\u9226\x28\x54\x69\x4f\u2082\x29\u7684\u61c9\u7528\u6700\u5177\u6307\u6a19\u6027\u3002\u4f5c\u70ba\u4e00\u7a2e\u9ad8\u6298\u5c04\u7387\u7684\u767d\u8272\u984f\u6599\x28\u9226\u767d\u7c89\x29\uff0c\u5b83\u88ab\u5ee3\u6cdb\u7528\u65bc\u5857\u6599\u8207\u9632\u66ec\u971c\uff1b\u800c\u5176\u4f5c\u70ba\u300c\u5149\u89f8\u5a92\u300d\u7684\u7279\u6027\uff0c\u80fd\u5728\u7d2b\u5916\u7dda\u7167\u5c04\u4e0b\u5206\u89e3\u6709\u6a5f\u6c61\u67d3\u7269\uff0c\u662f\u73fe\u4ee3\u74b0\u5883\u5316\u5b78\u7684\u91cd\u8981\u6280\u8853\u3002\u5728\u822a\u592a\u5de5\u7a0b\u4e2d\uff0c\u9226\u5408\u91d1\u662f\u98db\u6a5f\u767c\u52d5\u6a5f\u8207\u9ad8\u6eab\u7d50\u69cb\u4ef6\u7684\u6838\u5fc3\u6750\u6599\u3002\u6b64\u5916\uff0c\u7531\u65bc\u9226\u5c0d\u4eba\u9ad4\u7d44\u7e54\u5177\u5099\u512a\u7570\u7684\u300c\u751f\u7269\u76f8\u5bb9\u6027\u300d\x28\x42\x69\x6f\x63\x6f\x6d\x70\x61\x74\x69\x62\x69\x6c\x69\x74\x79\x29\uff0c\u4e14\u5176\u6a19\u6e96\u96fb\u6975\u96fb\u4f4d\u4f7f\u5176\u5728\u751f\u7269\u9ad4\u6db2\u4e2d\u6975\u5176\u7a69\u5b9a\uff0c\u56e0\u6b64\u662f\u88fd\u9020\u4eba\u5de5\u9aa8\u9abc\u3001\u7259\u6839\u8207\u5fc3\u81df\u74e3\u819c\u7684\u9996\u9078\u91ab\u7528\u6750\u6599\u3002\x0a\x0a\u9226\u5c55\u73fe\u4e86\u8a31\u591a\u6975\u81f4\u7684\u6750\u6599\u7279\u6027\u3002\u5b83\u662f\u5c11\u6578\u80fd\u5728\u6c2e\u6c23\u4e2d\u71c3\u71d2\u7684\u91d1\u5c6c\uff0c\u53cd\u6620\u4e86\u5176\u5728\u9ad8\u6eab\u4e0b\u6975\u9ad8\u7684\u53cd\u61c9\u6d3b\u6027\u3002\u5728\u7269\u7406\u8a2d\u8a08\u4e0a\uff0c\u9226\u8207\u93b3\u7d44\u6210\u7684\u5408\u91d1\x28\x4e\x69\x74\x69\x6e\x6f\x6c\x29\u662f\u8457\u540d\u7684\u300c\u5f62\u72c0\u8a18\u61b6\u5408\u91d1\u300d\uff0c\u80fd\u5728\u53d7\u529b\u8b8a\u5f62\u5f8c\u900f\u904e\u52a0\u71b1\u56de\u5fa9\u539f\u59cb\u7d50\u69cb\u3002\u53cd\u76f4\u89ba\u7684\u662f\uff0c\u5118\u7ba1\u9226\u88ab\u8a8d\u70ba\u662f\u786c\u91d1\u5c6c\uff0c\u4f46\u5176\u5c0e\u71b1\u6027\u8207\u5c0e\u96fb\u6027\u537b\u76f8\u5c0d\u8f03\u5dee\u3002\u9019\u7a2e\u5177\u5099\u5de8\u4eba\u4e4b\u529b\u537b\u53c8\u5c0d\u751f\u547d\u6eab\u67d4\u76f8\u5f85\u7684\u5143\u7d20\uff0c\u7cbe\u78ba\u8a6e\u91cb\u4e86\u904e\u6e21\u91d1\u5c6c\u5f9e\u6975\u7aef\u5316\u5b78\u6027\u8cea\u5230\u7cbe\u5bc6\u6750\u6599\u61c9\u7528\u7684\u5b8c\u7f8e\u8de8\u5ea6\uff0c\u662f\u7406\u89e3\u73fe\u4ee3\u6750\u6599\u79d1\u5b78\u4e0d\u53ef\u6216\u7f3a\u7684\u4e00\u74b0\u3002",
  "\x56":
    "\u91e9\x28\x56\x61\x6e\x61\x64\x69\x75\x6d\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x56\uff0c\u539f\u5b50\u5e8f\x20\x32\x33\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u56db\u9031\u671f\u3001\u7b2c\x20\x35\x20\u65cf\x28\x64\x20\u5340\u584a\x29\u3002\x31\x38\x30\x31\x20\u5e74\u7531\u58a8\u897f\u54e5\u7926\u7269\u5b78\u5bb6\u5fb7\u91cc\u5967\x28\x41\x6e\x64\x72\u00e9\x73\x20\x4d\x61\x6e\x75\x65\x6c\x20\x64\x65\x6c\x20\x52\u00ed\x6f\x29\u9996\u6b21\u767c\u73fe\uff0c\u5f8c\u56e0\u5176\u9e7d\u985e\u6eb6\u6db2\u8272\u5f69\u8c50\u5bcc\uff0c\u745e\u5178\u5316\u5b78\u5bb6\u585e\u592b\u65af\u7279\u502b\x28\x4e\x69\x6c\x73\x20\x47\x61\x62\x72\x69\x65\x6c\x20\x53\x65\x66\x73\x74\x72\u00f6\x6d\x29\u4ee5\u5317\u6b50\u7f8e\u9e97\u5973\u795e\u51e1\u5a1c\u8fea\u7d72\x28\x56\x61\x6e\x61\x64\x69\x73\x29\u4e4b\u540d\u5c07\u5176\u547d\u540d\u70ba\x20\x56\x61\x6e\x61\x64\x69\x75\x6d\u3002\u91e9\u662f\u5178\u578b\u7684\u904e\u6e21\u91d1\u5c6c\uff0c\u4e3b\u8981\u4ee5\u7926\u7269\u8207\u5316\u77f3\u71c3\u6599\u4e2d\u7684\u96dc\u8cea\u5f62\u5f0f\u5b58\u5728\uff0c\u662f\u73fe\u4ee3\u92fc\u9435\u5de5\u696d\u8207\u5927\u898f\u6a21\u5132\u80fd\u6280\u8853\u4e2d\u7684\u95dc\u9375\u6230\u7565\u5143\u7d20\u3002\x0a\x0a\u91e9\u7684\u96fb\u5b50\u7d44\u614b\u70ba\x20\x5b\x41\x72\x5d\x33\x64\u00b3\x34\x73\u00b2\uff0c\u5177\u5099\u5f9e\x20\x2b\x32\x20\u5230\x20\x2b\x35\x20\u7684\u9023\u7e8c\u6c27\u5316\u614b\u3002\u5728\u9ad8\u4e2d\u5316\u5b78\u5be6\u9a57\u4e2d\uff0c\u91e9\u662f\u6f14\u793a\u300c\u6c27\u5316\u9084\u539f\u8207\u8272\u5f69\u8b8a\u5316\u300d\u6700\u7cbe\u5f69\u7684\u6559\u6750\uff1a\u900f\u904e\u92c5\u6c5e\u9f4a\u5c07\u9ec3\u8272\u7684\u4e94\u50f9\u91e9\x28\x56\x4f\u2082\u207a\x29\u9010\u6b65\u9084\u539f\uff0c\u6703\u89c0\u5bdf\u5230\u85cd\u8272\u7684\u56db\u50f9\x28\x56\x4f\u00b2\u207a\x29\u3001\u7da0\u8272\u7684\u4e09\u50f9\x28\x56\u00b3\u207a\x29\u4ee5\u53ca\u7d2b\u8272\u7684\u4e8c\u50f9\x28\x56\u00b2\u207a\x29\u3002\u9019\u7a2e\u7e7d\u7d1b\u7684\u984f\u8272\u8f49\u8b8a\u76f4\u63a5\u53cd\u6620\u4e86\x20\x64\x20\u8ecc\u57df\u5728\u4e0d\u540c\u96fb\u5b50\u6392\u5e03\u4e0b\u7684\u80fd\u91cf\u5206\u88c2\u3002\u91e9\u7684\u6a19\u6e96\u96fb\u6975\u96fb\u4f4d\u5206\u5e03\u7dca\u5bc6\uff0c\u4f7f\u5176\u5728\u5316\u5b78\u53cd\u61c9\u4e2d\u5c55\u73fe\u51fa\u6975\u4f73\u7684\u96fb\u5b50\u8f49\u79fb\u80fd\u529b\uff0c\u9019\u4e5f\u662f\u5176\u5728\u50ac\u5316\u53cd\u61c9\u4e2d\u8868\u73fe\u512a\u7570\u7684\u5fae\u89c0\u539f\u56e0\u3002\x0a\x0a\u5728\u5de5\u696d\u8207\u74b0\u5883\u5de5\u7a0b\u8108\u7d61\u4e2d\uff0c\u4e94\u6c27\u5316\u4e8c\u91e9\x28\x56\u2082\x4f\u2085\x29\u662f\u300c\u63a5\u89f8\u6cd5\u300d\x28\x43\x6f\x6e\x74\x61\x63\x74\x20\x50\x72\x6f\x63\x65\x73\x73\x29\u88fd\u53d6\u786b\u9178\u7684\u6838\u5fc3\u50ac\u5316\u5291\uff0c\u5b83\u80fd\u6709\u6548\u964d\u4f4e\u4e8c\u6c27\u5316\u786b\u6c27\u5316\u70ba\u4e09\u6c27\u5316\u786b\u7684\u6d3b\u5316\u80fd\u3002\u5728\u51b6\u91d1\u5b78\u4e2d\uff0c\u91e9\u662f\u92fc\u9435\u7684\u300c\u5de5\u696d\u7dad\u751f\u7d20\u300d\uff0c\u50c5\u9700\u6dfb\u52a0\u5fae\u91cf\x28\u7d04\x20\x30\x2e\x31\x25\x29\u5373\u53ef\u5927\u5e45\u63d0\u5347\u92fc\u6750\u7684\u97cc\u6027\u3001\u5f37\u5ea6\u8207\u8010\u71b1\u6027\x28\u5982\u9ad8\u5f37\u5ea6\u5de5\u5177\u92fc\x29\u3002\u7576\u524d\u80fd\u6e90\u79d1\u6280\u7684\u524d\u6cbf\u61c9\u7528\u662f\u300c\u91e9\u6c27\u5316\u9084\u539f\u6db2\u6d41\u96fb\u6c60\u300d\x28\x56\x52\x46\x42\x29\uff0c\u5229\u7528\u91e9\u5728\u6eb6\u6db2\u4e2d\u591a\u50f9\u614b\u8b8a\u5316\u7684\u7279\u6027\u4f86\u5132\u5b58\u96fb\u80fd\uff0c\u56e0\u5176\u5faa\u74b0\u58fd\u547d\u9577\u3001\u5b89\u5168\u6027\u9ad8\u4e14\u53ef\u5927\u898f\u6a21\u90e8\u7f72\uff0c\u88ab\u8996\u70ba\u642d\u914d\u518d\u751f\u80fd\u6e90\u96fb\u7db2\u7684\u6700\u4f73\u5927\u578b\u5132\u80fd\u65b9\u6848\u3002\x0a\x0a\u91e9\u5728\u751f\u7269\u5b78\u8207\u7269\u7406\u7279\u6027\u4e0a\u4ea6\u5c55\u73fe\u51fa\u5947\u7279\u7684\u4e00\u9762\u3002\u67d0\u4e9b\u6df1\u6d77\u751f\u7269\u5982\u6d77\u9798\x28\x53\x65\x61\x20\x73\x71\x75\x69\x72\x74\x73\x29\u5177\u5099\u6975\u5f37\u7684\u805a\u91e9\u80fd\u529b\uff0c\u5176\u8840\u6db2\u4e2d\u7684\u91e9\u6fc3\u5ea6\u751a\u81f3\u6bd4\u5468\u570d\u6d77\u6c34\u9ad8\u51fa\u767e\u842c\u500d\uff0c\u9019\u53cd\u6620\u4e86\u904e\u6e21\u91d1\u5c6c\u5728\u751f\u547d\u6f14\u5316\u4e2d\u53ef\u80fd\u626e\u6f14\u7684\u7368\u7279\u751f\u7269\u89d2\u8272\u3002\u5728\u8d85\u5c0e\u7814\u7a76\u4e2d\uff0c\u77fd\u5316\u91e9\x28\x56\u2083\x53\x69\x29\u662f\u9996\u6279\u88ab\u767c\u73fe\u7684\x20\x41\x31\x35\x20\u578b\u8d85\u5c0e\u9ad4\uff0c\u5c55\u73fe\u51fa\u91e9\u5728\u6975\u7aef\u7269\u7406\u689d\u4ef6\u4e0b\u7684\u96fb\u5b50\u8026\u5408\u6f5b\u529b\u3002\u9019\u7a2e\u7531\u7e7d\u7d1b\u7684\u5316\u5b78\u984f\u8272\u6f14\u8b8a\u5230\u6c89\u7a69\u7684\u92fc\u9435\u5f37\u5316\u8207\u80fd\u6e90\u5132\u5099\uff0c\u4f7f\u91e9\u6210\u70ba\u904e\u6e21\u91d1\u5c6c\u4e2d\u517c\u5177\u5be6\u9a57\u7f8e\u5b78\u8207\u5be6\u6230\u50f9\u503c\u7684\u4ee3\u8868\u5143\u7d20\u3002",
  "\x43\x72":
    "\u927b\x28\x43\x68\x72\x6f\x6d\x69\x75\x6d\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x43\x72\uff0c\u539f\u5b50\u5e8f\x20\x32\x34\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u56db\u9031\u671f\u3001\u7b2c\x20\x36\x20\u65cf\x28\x64\x20\u5340\u584a\x29\u3002\u5176\u540d\u7a31\u6e90\u65bc\u5e0c\u81d8\u8a9e\u300c\x63\x68\x72\x6f\x6d\x61\u300d\x28\u984f\u8272\x29\uff0c\u610f\u6307\u5176\u5316\u5408\u7269\u5448\u73fe\u7e7d\u7d1b\u591a\u6a23\u7684\u8272\u5f69\u3002\x31\x37\x39\x37\x20\u5e74\u7531\u6cd5\u570b\u5316\u5b78\u5bb6\u6c83\u514b\u862d\x28\x4c\x6f\x75\x69\x73\x2d\x4e\x69\x63\x6f\x6c\x61\x73\x20\x56\x61\x75\x71\x75\x65\x6c\x69\x6e\x29\u5728\u5206\u6790\u897f\u4f2f\u5229\u4e9e\u7d05\u925b\u7926\u6642\u767c\u73fe\u3002\u927b\u662f\u5730\u6bbc\u4e2d\u5e38\u898b\u7684\u904e\u6e21\u91d1\u5c6c\uff0c\u4ee5\u5176\u5353\u8d8a\u7684\u786c\u5ea6\u8207\u6297\u8150\u8755\u7279\u6027\u8457\u7a31\uff0c\u662f\u73fe\u4ee3\u51b6\u91d1\u5de5\u696d\u4e2d\u8ce6\u4e88\u91d1\u5c6c\u300c\u4e0d\u93fd\u300d\u7279\u6027\u7684\u6838\u5fc3\u5143\u7d20\u3002\x0a\x0a\u927b\u7684\u96fb\u5b50\u7d44\u614b\u70ba\x20\x5b\x41\x72\x5d\x33\x64\u2075\x34\x73\u00b9\uff0c\u9019\u7a2e\u300c\u534a\u5168\u6eff\u300d\u7684\u8ecc\u57df\u5206\u5e03\u662f\u70ba\u4e86\u9054\u6210\u8f03\u4f4e\u7684\u80fd\u91cf\u72c0\u614b\uff0c\u662f\u9ad8\u4e2d\u5316\u5b78\u63a2\u8a0e\u96fb\u5b50\u6392\u5e03\u7570\u5e38\u898f\u5f8b\u7684\u5178\u578b\u6848\u4f8b\u3002\u927b\u5e38\u898b\u7684\u6c27\u5316\u614b\u6709\x20\x2b\x32\u3001\x2b\x33\x20\u8207\x20\x2b\x36\u3002\u5728\u6c34\u6eb6\u6db2\u4e2d\uff0c\u927b\u9178\u6839\x28\x43\x72\x4f\u2084\u00b2\u207b\uff0c\u9ec3\u8272\x29\u8207\u4e8c\u927b\u9178\u6839\x28\x43\x72\u2082\x4f\u2087\u00b2\u207b\uff0c\u6a58\u8272\x29\u96a8\x20\x70\x48\x20\u503c\u6539\u8b8a\u800c\u8f49\u79fb\u7684\u5e73\u8861\u53cd\u61c9\uff0c\u662f\u7406\u89e3\u5316\u5b78\u5e73\u8861\u8207\u52d2\u6c99\u7279\u5217\u539f\u7406\u7684\u6838\u5fc3\u5be6\u9a57\u3002\u6b64\u5916\uff0c\u4e09\u50f9\u927b\u96e2\u5b50\x28\x43\x72\u00b3\u207a\x29\u5177\u5099\u7a69\u5b9a\u7684\x20\x64\u00b3\x20\u7d50\u69cb\uff0c\u5e38\u5f62\u6210\u984f\u8272\u591a\u8b8a\u7684\u932f\u96e2\u5b50\uff1b\u800c\u516d\u50f9\u927b\x28\u5982\x20\x43\x72\x4f\u2083\x29\u5247\u5177\u5099\u6975\u5f37\u7684\u6c27\u5316\u6027\uff0c\u4f46\u56e0\u5176\u81f4\u764c\u6027\uff0c\u5728\u74b0\u5883\u76e3\u6e2c\u4e2d\u9700\u56b4\u683c\u7ba1\u63a7\u3002\x0a\x0a\u5728\u6750\u6599\u79d1\u5b78\u8207\u96fb\u5316\u5b78\u4e2d\uff0c\u927b\u7684\u300c\u920d\u5316\u73fe\u8c61\u300d\x28\x50\x61\x73\x73\x69\x76\x61\x74\x69\x6f\x6e\x29\u6975\u70ba\u91cd\u8981\u3002\u927b\u80fd\u65bc\u8868\u9762\u751f\u6210\u4e00\u5c64\u6975\u8584\u4e14\u7dfb\u5bc6\u7684\u6c27\u5316\u927b\x28\x43\x72\u2082\x4f\u2083\x29\u4fdd\u8b77\u819c\uff0c\u6709\u6548\u963b\u7d55\u5167\u90e8\u91d1\u5c6c\u9032\u4e00\u6b65\u6c27\u5316\uff0c\u9019\u4f7f\u927b\u6210\u70ba\u88fd\u9020\u4e0d\u93fd\u92fc\x28\u542b\u927b\u91cf\u9700\u5927\u65bc\x20\x31\x30\x2e\x35\x25\x29\u7684\u95dc\u9375\u6210\u5206\u3002\u5728\u53f0\u7063\u9ad8\u4e2d\u6559\u6750\u4e2d\uff0c\u4e8c\u927b\u9178\u9240\x28\x4b\u2082\x43\x72\u2082\x4f\u2087\x29\u5728\u9178\u6027\u689d\u4ef6\u4e0b\u662f\u6a19\u6e96\u7684\u5f37\u6c27\u5316\u5291\uff0c\u5e38\u7528\u65bc\u6c27\u5316\u9084\u539f\u6ef4\u5b9a\u53ca\u9187\u985e\u7684\u6aa2\u9a57\u3002\u73fe\u4ee3\u79d1\u6280\u4ea6\u5229\u7528\u96fb\u89e3\u934d\u927b\u6280\u8853\u63d0\u5347\u6a5f\u68b0\u96f6\u4ef6\u7684\u8010\u78e8\u6027\u8207\u5149\u6fa4\u611f\uff0c\u5c55\u73fe\u4e86\u927b\u5728\u5de5\u7a0b\u61c9\u7528\u4e2d\u517c\u5177\u7f8e\u89c0\u8207\u6a5f\u80fd\u7684\u96d9\u91cd\u8eab\u5206\u3002\x0a\x0a\u927b\u5c55\u73fe\u4e86\u6975\u70ba\u8ff7\u4eba\u7684\u5149\u5b78\u7279\u5fb5\u3002\u81ea\u7136\u754c\u4e2d\u7684\u7d05\u5bf6\u77f3\x28\x52\x75\x62\x79\x29\u4e4b\u6240\u4ee5\u5448\u73fe\u9bae\u7d05\uff0c\u672c\u8cea\u4e0a\u662f\u525b\u7389\u6676\u683c\u4e2d\u90e8\u5206\u7684\u92c1\u96e2\u5b50\u88ab\u927b\u96e2\u5b50\u53d6\u4ee3\u5f8c\u6240\u7522\u751f\u7684\x20\x64\x2d\x64\x20\u8ecc\u57df\u8e8d\u9077\u80fd\u91cf\u5438\u6536\u3002\u53cd\u76f4\u89ba\u7684\u662f\uff0c\u927b\u96d6\u7136\u662f\u6975\u5176\u5805\u786c\u7684\u91d1\u5c6c\x28\u83ab\u6c0f\u786c\u5ea6\u7d04\x20\x38\x2e\x35\x29\uff0c\u4f46\u5176\u672c\u8eab\u537b\u5177\u6709\u8106\u6027\uff0c\u96e3\u4ee5\u55ae\u7368\u4f5c\u70ba\u7d50\u69cb\u6750\u6599\u4f7f\u7528\u3002\u6b64\u5916\uff0c\u4e8c\u6c27\u5316\u927b\x28\x43\x72\x4f\u2082\x29\u56e0\u5176\u512a\u7570\u7684\u78c1\u6027\uff0c\u5728\u65e9\u671f\u9ad8\u968e\u78c1\u5e36\u9304\u97f3\u6280\u8853\u4e2d\u626e\u6f14\u95dc\u9375\u89d2\u8272\u3002\u9019\u7a2e\u5f9e\u7d05\u5bf6\u77f3\u7684\u83ef\u9e97\u8272\u5f69\u5230\u4e0d\u93fd\u92fc\u7684\u6c89\u7a69\u525b\u5805\uff0c\u7cbe\u78ba\u8a6e\u91cb\u4e86\u927b\u5143\u7d20\u5728\u904e\u6e21\u91d1\u5c6c\u4e2d\u7368\u7279\u7684\u7f8e\u5b78\u8207\u5de5\u85dd\u50f9\u503c\u3002",
  "\x4d\x6e":
    "\u9333\x28\x4d\x61\x6e\x67\x61\x6e\x65\x73\x65\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x4d\x6e\uff0c\u539f\u5b50\u5e8f\x20\x32\x35\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u56db\u9031\u671f\u3001\u7b2c\x20\x37\x20\u65cf\x28\x64\x20\u5340\u584a\x29\u3002\u5176\u540d\u7a31\u6e90\u65bc\u62c9\u4e01\u8a9e\u300c\x6d\x61\x67\x6e\x65\x73\u300d\x28\u78c1\u77f3\x29\uff0c\u65e9\u5e74\u5316\u5b78\u5bb6\u5e38\u5c07\u5176\u6c27\u5316\u7269\u8207\u78c1\u9435\u7926\u6df7\u6dc6\u3002\x31\x37\x37\x34\x20\u5e74\u7531\u745e\u5178\u5316\u5b78\u5bb6\u7518\u6069\x28\x4a\x6f\x68\x61\x6e\x20\x47\x6f\x74\x74\x6c\x69\x65\x62\x20\x47\x61\x68\x6e\x29\u900f\u904e\u78b3\u9084\u539f\u4e8c\u6c27\u5316\u9333\u9996\u6b21\u5206\u96e2\u51fa\u7d14\u9333\u3002\u9333\u662f\u5730\u6bbc\u4e2d\u542b\u91cf\u975e\u5e38\u8c50\u5bcc\u7684\u904e\u6e21\u91d1\u5c6c\uff0c\u96d6\u7136\u5176\u91d1\u5c6c\u55ae\u8cea\u4e26\u4e0d\u50cf\u9435\u90a3\u6a23\u5ee3\u6cdb\u4f7f\u7528\uff0c\u4f46\u5176\u4f5c\u70ba\u5408\u91d1\u5143\u7d20\u8207\u6c27\u5316\u5291\uff0c\u5728\u91cd\u5de5\u696d\u8207\u73fe\u4ee3\u96fb\u6c60\u6280\u8853\u4e2d\u5360\u6709\u6230\u7565\u5730\u4f4d\u3002\x0a\x0a\u9333\u7684\u96fb\u5b50\u7d44\u614b\u70ba\x20\x5b\x41\x72\x5d\x33\x64\u2075\x34\x73\u00b2\uff0c\u5177\u5099\u534a\u586b\u6eff\u7684\x20\x64\x20\u8ecc\u57df\u3002\u9019\u4f7f\u5176\u64c1\u6709\u904e\u6e21\u91d1\u5c6c\u4e2d\u6700\u5bec\u5ee3\u7684\u6c27\u5316\u614b\u5206\u5e03\x28\u5f9e\x20\x2d\x33\x20\u5230\x20\x2b\x37\x29\uff0c\u5176\u4e2d\x20\x2b\x32\u3001\x2b\x34\u3001\x2b\x37\x20\u6700\u70ba\u5e38\u898b\u3002\u904e\u9333\u9178\u9240\x28\x4b\x4d\x6e\x4f\u2084\x29\u662f\u53f0\u7063\u9ad8\u4e2d\u5316\u5b78\u7684\u6838\u5fc3\u95dc\u9375\u5b57\uff0c\u5176\u5728\u9178\u6027\u3001\u4e2d\u6027\u53ca\u5f37\u9e7c\u6027\u74b0\u5883\u4e2d\u9084\u539f\u7522\u7269\u7684\u4e0d\u540c\x28\u5206\u5225\u70ba\x20\x4d\x6e\u00b2\u207a\u3001\x4d\x6e\x4f\u2082\u3001\x4d\x6e\x4f\u2084\u00b2\u207b\x29\uff0c\u662f\u5b78\u7fd2\u6c27\u5316\u9084\u539f\u53cd\u61c9\u8a08\u91cf\u8207\u984f\u8272\u8b8a\u5316\u7684\u6a19\u6e96\u7bc4\u4f8b\u3002\u6b64\u5916\uff0c\u4e8c\u6c27\u5316\u9333\x28\x4d\x6e\x4f\u2082\x29\u5728\u904e\u6c27\u5316\u6c2b\u5206\u89e3\u5be6\u9a57\u4e2d\u626e\u6f14\u7684\u89f8\u5a92\u89d2\u8272\uff0c\u4ea6\u662f\u9ad8\u4e2d\u5be6\u9a57\u8ab2\u7a0b\u5c0d\u300c\u50ac\u5316\u4f5c\u7528\u300d\u7684\u555f\u8499\u89c0\u9ede\u3002\x0a\x0a\u5728\u92fc\u9435\u5de5\u696d\u4e2d\uff0c\u9333\u662f\u4e0d\u53ef\u6216\u7f3a\u7684\u812b\u786b\u5291\u8207\u812b\u6c27\u5291\u3002\u9333\u92fc\x28\x48\x61\x64\x66\x69\x65\x6c\x64\x20\x73\x74\x65\x65\x6c\x29\u56e0\u5176\u6975\u4f73\u7684\u8010\u78e8\u6027\u8207\u9ad8\u97cc\u6027\uff0c\u88ab\u7528\u65bc\u9435\u8def\u9053\u5c94\u8207\u788e\u77f3\u6a5f\u7d44\u4ef6\u3002\u5728\u73fe\u4ee3\u80fd\u6e90\u9818\u57df\uff0c\u9333\u5728\u92f0\u96fb\u6c60\u6750\u6599\u4e2d\u626e\u6f14\u95dc\u9375\u89d2\u8272\uff0c\u4f8b\u5982\u92f0\u93b3\u9333\u9237\x28\x4e\x4d\x43\x29\u4e09\u5143\u96fb\u6c60\u8207\u9333\u9178\u92f0\u96fb\u6c60\uff0c\u5229\u7528\u9333\u96e2\u5b50\u4f4e\u6210\u672c\u4e14\u9ad8\u5b89\u5168\u6027\u7684\u512a\u52e2\u63d0\u5347\u5132\u80fd\u6548\u80fd\u3002\u96fb\u5316\u5b78\u65b9\u9762\uff0c\u9333\u7684\u6a19\u6e96\u9084\u539f\u96fb\u4f4d\x28\x45\u2070\x29\u5c55\u73fe\u5176\u5728\u7279\u5b9a\u74b0\u5883\u4e0b\u6613\u88ab\u6c27\u5316\u7684\u7279\u5fb5\uff0c\u9019\u4f7f\u5176\u6c27\u5316\u7269\u6210\u70ba\u88fd\u5099\u4e7e\u96fb\u6c60\u8207\u9e7c\u6027\u96fb\u6c60\u8ca0\u6975\u6d3b\u6027\u7269\u8cea\u7684\u4e3b\u529b\u6750\u6599\u3002\x0a\x0a\u9333\u5728\u751f\u7269\u5b78\u8207\u5730\u7403\u5316\u5b78\u4e2d\u5b58\u5728\u7368\u7279\u7684\u73fe\u8c61\u3002\u5b83\u662f\u690d\u7269\u5149\u5408\u4f5c\u7528\u300c\u653e\u6c27\u4e2d\u5fc3\u300d\x28\x4f\x45\x43\x29\u7684\u6838\u5fc3\u539f\u5b50\uff0c\u8ca0\u8cac\u50ac\u5316\u6c34\u5206\u5b50\u7684\u88c2\u89e3\uff0c\u662f\u5730\u7403\u5927\u6c23\u6c27\u6c23\u5faa\u74b0\u7684\u5e55\u5f8c\u63a8\u624b\u3002\u6709\u8da3\u7684\u662f\uff0c\u6df1\u6d77\u5e95\u90e8\u5206\u5e03\u8457\u5927\u91cf\u7684\u300c\u9333\u6838\u300d\x28\x4d\x61\x6e\x67\x61\x6e\x65\x73\x65\x20\x6e\x6f\x64\x75\x6c\x65\x73\x29\uff0c\u9019\u4e9b\u5bcc\u542b\u9333\u3001\u93b3\u3001\u9237\u7684\u7926\u7269\u7403\u9ad4\u88ab\u8996\u70ba\u672a\u4f86\u6df1\u6d77\u7926\u7522\u7684\u6f5b\u529b\u4f86\u6e90\u3002\u53cd\u76f4\u89ba\u7684\u662f\uff0c\u9333\u96d6\u7136\u662f\u92fc\u9435\u5408\u91d1\u7684\u95dc\u9375\uff0c\u4f46\u7d14\u9333\u672c\u8eab\u6975\u8106\u4e14\u6975\u6613\u5728\u6f6e\u6fd5\u7a7a\u6c23\u4e2d\u93fd\u8755\u3002\u9019\u7a2e\u5f9e\u9a45\u52d5\u751f\u547d\u5149\u5408\u4f5c\u7528\u5230\u652f\u6490\u92fc\u9435\u6587\u660e\u7684\u591a\u91cd\u7dad\u5ea6\uff0c\u5c55\u73fe\u4e86\u9333\u5728\u9031\u671f\u8868\u4e2d\u627f\u5148\u555f\u5f8c\u7684\u5316\u5b78\u5f35\u529b\u3002",
  "\x46\x65":
    "\u9435\x28\x49\x72\x6f\x6e\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x46\x65\uff0c\u539f\u5b50\u5e8f\x20\x32\x36\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u56db\u9031\u671f\u3001\u7b2c\x20\x38\x20\u65cf\x28\x64\x20\u5340\u584a\x29\u3002\u5176\u540d\u7a31\u6e90\u65bc\u53e4\u82f1\u8a9e\u300c\x69\x72\x65\x6e\u300d\uff0c\u62c9\u4e01\u8a9e\u540d\u70ba\u300c\x46\x65\x72\x72\x75\x6d\u300d\u3002\u9435\u662f\u5b87\u5b99\u4e2d\u8cea\u91cf\u6700\u7a69\u5b9a\u7684\u5143\u7d20\uff0c\u4ea6\u662f\u5730\u7403\u6838\u5fc3\u7684\u4e3b\u8981\u6210\u5206\x28\u69cb\u6210\u5730\u78c1\u7684\u4f86\u6e90\x29\u3002\u4eba\u985e\u5c0d\u9435\u7684\u61c9\u7528\u53ef\u8ffd\u6eaf\u81f3\u6578\u5343\u5e74\u524d\u7684\u9435\u5668\u6642\u4ee3\u3002\u96d6\u7136\u7d14\u9435\u5728\u81ea\u7136\u754c\u4e2d\u7f55\u898b\x28\u591a\u5b58\u5728\u65bc\u9695\u77f3\u4e2d\x29\uff0c\u4f46\u5176\u6c27\u5316\u7269\u5982\u8d64\u9435\u7926\x28\x46\x65\u2082\x4f\u2083\x29\u8207\u78c1\u9435\u7926\x28\x46\x65\u2083\x4f\u2084\x29\u5206\u5e03\u6975\u5ee3\uff0c\u900f\u904e\u7149\u9435\u9ad8\u7210\u7684\u9084\u539f\u53cd\u61c9\uff0c\u9435\u6210\u70ba\u652f\u6490\u73fe\u4ee3\u5de5\u696d\u6587\u660e\u7684\u9aa8\u67b6\u3002\x0a\x0a\u9435\u7684\u96fb\u5b50\u7d44\u614b\u70ba\x20\x5b\x41\x72\x5d\x33\x64\u2076\x34\x73\u00b2\uff0c\u5e38\u898b\u6c27\u5316\u614b\u70ba\x20\x2b\x32\x28\u4e9e\u9435\x29\u8207\x20\x2b\x33\x28\u9435\x29\u3002\u5728\u9ad8\u4e2d\u5316\u5b78\u95dc\u65bc\u932f\u96e2\u5b50\u7684\u8a0e\u8ad6\u4e2d\uff0c\u9435\u8207\u786b\u6c30\u9178\u6839\x28\x53\x43\x4e\u207b\x29\u53cd\u61c9\u7522\u751f\u7684\u8840\u7d05\u8272\u7d61\u5408\u7269\x20\x5b\x46\x65\x28\x53\x43\x4e\x29\x5d\u00b2\u207a\uff0c\u662f\u6aa2\u9a57\u4e09\u50f9\u9435\u96e2\u5b50\u7684\u9748\u654f\u5b9a\u6027\u65b9\u6cd5\u3002\u6b64\u5916\uff0c\u9435\u8207\u6c30\u6839\u5f62\u6210\u7684\u4e9e\u9435\u6c30\u5316\u9240\x28\u9ec3\u8840\u9e7d\x29\u53ca\u9435\u6c30\u5316\u9240\x28\u8d64\u8840\u9e7d\x29\uff0c\u5728\u8207\u4e0d\u540c\u50f9\u614b\u9435\u96e2\u5b50\u4f5c\u7528\u4e0b\u751f\u6210\u7684\u300c\u666e\u9b6f\u58eb\u85cd\u300d\x28\x50\x72\x75\x73\x73\x69\x61\x6e\x20\x42\x6c\x75\x65\x29\u6c89\u6fb1\uff0c\u662f\u7406\u89e3\u914d\u4f4d\u5316\u5b78\u8207\u8272\u5f69\u751f\u6210\u7684\u6838\u5fc3\u6848\u4f8b\u3002\u9435\u4ea6\u5177\u5099\u5f37\u78c1\u6027\x28\x46\x65\x72\x72\x6f\x6d\x61\x67\x6e\x65\x74\x69\x73\x6d\x29\uff0c\u5176\u672a\u6210\u5c0d\u96fb\u5b50\u5728\u6676\u683c\u4e2d\u7684\u5b9a\u5411\u6392\u5217\uff0c\u5960\u5b9a\u4e86\u96fb\u78c1\u5b78\u767c\u5c55\u7684\u7269\u8cea\u57fa\u790e\u3002\x0a\x0a\u5728\u53f0\u7063\u9ad8\u4e2d\u8ab2\u7db1\u8207\u5de5\u7a0b\u9818\u57df\uff0c\u9435\u7684\u8150\u8755\u8207\u9632\u8b77\u662f\u6975\u5176\u91cd\u8981\u7684\u8ab2\u984c\u3002\u900f\u904e\u6a19\u6e96\u96fb\u6975\u96fb\u4f4d\x28\x45\u2070\x29\u7684\u5206\u6790\uff0c\u5b78\u751f\u80fd\u7406\u89e3\u300c\u72a7\u7272\u967d\u6975\u6cd5\u300d\u8207\u300c\u5916\u52a0\u96fb\u6d41\u6cd5\u300d\u9632\u93fd\u7684\u96fb\u5316\u5b78\u539f\u7406\u3002\u9ad8\u7210\u7149\u9435\u4e2d\uff0c\u7126\u70ad\u4f5c\u70ba\u9084\u539f\u5291\u5c07\u9435\u7926\u77f3\u8f49\u5316\u70ba\u751f\u9435\uff0c\u9032\u800c\u7149\u88fd\u6210\u78b3\u92fc\u3001\u5408\u91d1\u92fc\u7b49\u6750\u6599\uff0c\u662f\u71b1\u5316\u5b78\u8207\u6c27\u5316\u9084\u539f\u61c9\u7528\u7684\u6975\u81f4\u5c55\u73fe\u3002\u5728\u751f\u7269\u5316\u5b78\u4e2d\uff0c\u9435\u662f\u8840\u7d05\u7d20\x28\x48\x65\x6d\x6f\x67\x6c\x6f\x62\x69\x6e\x29\u7684\u6838\u5fc3\uff0c\u5229\u7528\x20\x46\x65\u00b2\u207a\x20\u8207\x20\x46\x65\u00b3\u207a\x20\u6c27\u5316\u614b\u7684\u8f49\u63db\uff0c\u8ca0\u8cac\u6c27\u6c23\u5728\u8840\u6db2\u4e2d\u7684\u8f09\u904b\u8207\u91cb\u653e\uff0c\u5c55\u73fe\u4e86\u904e\u6e21\u91d1\u5c6c\u5728\u751f\u547d\u7dad\u6301\u4e2d\u7684\u7cbe\u5bc6\u8abf\u63a7\u3002\x0a\x0a\u9435\u5728\u6838\u5b50\u7269\u7406\u4e2d\u5177\u6709\u7279\u6b8a\u7684\u6975\u9650\u5730\u4f4d\uff0c\u5176\u539f\u5b50\u6838\u7684\u300c\u5e73\u5747\u7d50\u5408\u80fd\u300d\u6700\u9ad8\uff0c\u9019\u610f\u5473\u8457\u9435\u662f\u6838\u878d\u5408\u8207\u6838\u5206\u88c2\u7684\u6700\u7d42\u7d42\u9ede\uff0c\u662f\u6046\u661f\u751f\u547d\u7d42\u7d50\u524d\u7684\u6700\u5f8c\u7522\u7269\u3002\u5728\u65e5\u5e38\u73fe\u8c61\u4e2d\uff0c\u9435\u7684\u751f\u93fd\x28\u6c27\u5316\x29\u904e\u7a0b\u6d89\u53ca\u8907\u96dc\u7684\u96fb\u5316\u5b78\u5faa\u74b0\uff0c\u4e14\u5176\u7522\u7269\u9ad4\u7a4d\u81a8\u8139\u6703\u7834\u58de\u91d1\u5c6c\u5167\u90e8\u7d50\u69cb\uff0c\u9019\u8207\u92c1\u7684\u920d\u5316\u5b8c\u5168\u4e0d\u540c\u3002\u6709\u8da3\u7684\u662f\uff0c\u96d6\u7136\u9435\u88ab\u8996\u70ba\u6c89\u91cd\u7684\u91cd\u91d1\u5c6c\uff0c\u4f46\u5176\u7c89\u672b\u5728\u67d0\u4e9b\u689d\u4ef6\u4e0b\u5177\u5099\u6975\u9ad8\u7684\u53cd\u61c9\u6027\u3002\u9019\u7a2e\u5f9e\u6046\u661f\u5167\u90e8\u7684\u7a69\u5b9a\u5dd4\u5cf0\u5230\u4eba\u985e\u751f\u7406\u5faa\u74b0\u7684\u6838\u5fc3\u89d2\u8272\uff0c\u4f7f\u9435\u6210\u70ba\u9023\u7d50\u5b87\u5b99\u6f14\u5316\u8207\u4eba\u985e\u6587\u660e\u6700\u5f37\u97cc\u7684\u5316\u5b78\u7d10\u5e36\u3002",
  "\x43\x6f":
    "\u9237\x28\x43\x6f\x62\x61\x6c\x74\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x43\x6f\uff0c\u539f\u5b50\u5e8f\x20\x32\x37\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u56db\u9031\u671f\u3001\u7b2c\x20\x39\x20\u65cf\x28\x64\x20\u5340\u584a\x29\u3002\u5176\u540d\u7a31\u6e90\u65bc\u5fb7\u8a9e\u300c\x4b\x6f\x62\x6f\x6c\x64\u300d\uff0c\u610f\u6307\u50b3\u8aaa\u4e2d\u7684\u300c\u5730\u7cbe\u300d\u6216\u300c\u5996\u602a\u300d\uff0c\u56e0\u65e9\u671f\u5fb7\u570b\u7926\u5de5\u767c\u73fe\u9019\u7a2e\u7926\u77f3\u96e3\u4ee5\u51b6\u7149\u4e14\u91cb\u653e\u6709\u6bd2\u7159\u9727\uff0c\u8a8d\u70ba\u53d7\u5996\u602a\u8a5b\u5492\u800c\u547d\u540d\u3002\x31\x37\x33\x35\x20\u5e74\u7531\u745e\u5178\u5316\u5b78\u5bb6\u5e03\u862d\u7279\x28\x47\x65\x6f\x72\x67\x20\x42\x72\x61\x6e\x64\x74\x29\u5206\u96e2\u51fa\u7d14\u9237\uff0c\u8b49\u5be6\u85cd\u8272\u73bb\u7483\u7684\u6210\u8272\u6e90\u65bc\u6b64\u5143\u7d20\u3002\u9237\u5728\u81ea\u7136\u754c\u4e2d\u5e38\u8207\u93b3\u3001\u9285\u5171\u751f\uff0c\u662f\u73fe\u4ee3\u5de5\u696d\u8207\u9ad8\u7cbe\u5bc6\u5408\u91d1\u4e2d\u4e0d\u53ef\u6216\u7f3a\u7684\u300c\u5de5\u696d\u9f52\u8f2a\u300d\u3002\x0a\x0a\u9237\u7684\u96fb\u5b50\u7d44\u614b\u70ba\x20\x5b\x41\x72\x5d\x33\x64\u2077\x34\x73\u00b2\uff0c\u8207\u9435\u3001\u93b3\u540c\u5c6c\u9435\u65cf\u5143\u7d20\uff0c\u5177\u5099\u5f37\u78c1\u6027\x28\x46\x65\x72\x72\x6f\x6d\x61\x67\x6e\x65\x74\x69\x73\x6d\x29\u4e14\u5c45\u79ae\u6eab\u5ea6\u6975\u9ad8\u3002\u5728\u5316\u5b78\u6027\u8cea\u4e0a\uff0c\u9237\u6700\u5e38\u898b\u7684\u6c27\u5316\u614b\u70ba\x20\x2b\x32\x20\u8207\x20\x2b\x33\u3002\u5728\u9ad8\u4e2d\u5316\u5b78\u5be6\u9a57\u4e2d\uff0c\u4e8c\u6c2f\u5316\u9237\x28\x43\x6f\x43\x6c\u2082\x29\u8a66\u7d19\u96a8\u542b\u6c34\u91cf\u6539\u8b8a\u984f\u8272\u7684\u73fe\u8c61\x28\u85cd\u8272\u7121\u6c34\u8b8a\u7c89\u7d05\u516d\u6c34\u5408\u7269\x29\uff0c\u662f\u63a2\u7a76\u52d2\u6c99\u7279\u5217\u539f\u7406\u8207\u6c34\u5408\u96e2\u5b50\u7d50\u69cb\u7684\u7d93\u5178\u6559\u6750\u3002\u6b64\u5916\uff0c\u9237\u80fd\u5f62\u6210\u6975\u5176\u591a\u6a23\u4e14\u7a69\u5b9a\u7684\u932f\u5408\u7269\uff0c\u9019\u5728\u914d\u4f4d\u5316\u5b78\x28\x43\x6f\x6f\x72\x64\x69\x6e\x61\x74\x69\x6f\x6e\x20\x43\x68\x65\x6d\x69\x73\x74\x72\x79\x29\u7684\u767c\u5c55\u53f2\u4e0a\u5177\u6709\u91cc\u7a0b\u7891\u610f\u7fa9\u3002\x0a\x0a\u5728\u73fe\u4ee3\u61c9\u7528\u8207\u80fd\u6e90\u79d1\u6280\u4e2d\uff0c\u9237\u662f\u92f0\u96e2\u5b50\u96fb\u6c60\x28\u5982\x20\x4c\x43\x4f\x20\u8207\x20\x4e\x4d\x43\x20\u96fb\u6c60\x29\u6b63\u6975\u6750\u6599\u7684\u6838\u5fc3\u6210\u5206\uff0c\u5c0d\u63d0\u5347\u96fb\u6c60\u80fd\u91cf\u5bc6\u5ea6\u8207\u7a69\u5b9a\u6027\u81f3\u95dc\u91cd\u8981\u3002\u5728\u6750\u6599\u79d1\u5b78\u9818\u57df\uff0c\u9237\u57fa\u8d85\u5408\u91d1\x28\x53\x75\x70\x65\x72\x61\x6c\x6c\x6f\x79\x73\x29\u5177\u5099\u5353\u8d8a\u7684\u6297\u9ad8\u6eab\u8815\u8b8a\u6027\u80fd\uff0c\u88ab\u5ee3\u6cdb\u7528\u65bc\u5674\u5c04\u767c\u52d5\u6a5f\u8449\u7247\u8207\u71c3\u6c23\u6e26\u8f2a\u6a5f\u3002\u6b64\u5916\uff0c\u7dad\u751f\u7d20\x20\x42\u2081\u2082\x28\u9237\u80fa\u7d20\x29\u662f\u552f\u4e00\u542b\u6709\u904e\u6e21\u91d1\u5c6c\u7684\u751f\u7269\u5206\u5b50\uff0c\u5c0d\u795e\u7d93\u7cfb\u7d71\u8207\u7d05\u8840\u7403\u7684\u7522\u751f\u5177\u6709\u6838\u5fc3\u4f5c\u7528\uff0c\u5c55\u73fe\u4e86\u9237\u5728\u751f\u547d\u79d1\u5b78\u4e2d\u7684\u5fae\u91cf\u537b\u95dc\u9375\u7684\u89d2\u8272\u3002\x0a\x0a\u9237\u5728\u653e\u5c04\u6027\u61c9\u7528\u4e0a\u5177\u6709\u986f\u8457\u7684\u7279\u6027\uff0c\u540c\u4f4d\u7d20\x20\u2076\u2070\x43\x6f\x20\u80fd\u91cb\u653e\u9ad8\u80fd\x20\u03b3\x20\u5c04\u7dda\uff0c\u5ee3\u6cdb\u61c9\u7528\u65bc\u764c\u75c7\u653e\u5c04\u6cbb\u7642\u53ca\u91ab\u7642\u5668\u6750\u7684\u5de5\u696d\u6ec5\u83cc\u3002\u5728\u8996\u89ba\u7f8e\u5b78\u4e0a\uff0c\u9237\u85cd\x28\x43\x6f\x62\x61\x6c\x74\x20\x42\x6c\x75\x65\x29\u984f\u6599\u81ea\u53e4\u5373\u88ab\u7528\u65bc\u88fd\u4f5c\u9752\u82b1\u74f7\u8207\u5f69\u8272\u73bb\u7483\uff0c\u5176\u767c\u8272\u529b\u5f37\u4e14\u71b1\u7a69\u5b9a\u6027\u6975\u4f73\u3002\u6709\u8da3\u7684\u662f\uff0c\u96d6\u7136\u9237\u662f\u95dc\u9375\u7684\u5de5\u696d\u6230\u7565\u8cc7\u6e90\uff0c\u4f46\u5176\u5168\u7403\u7522\u91cf\u9ad8\u5ea6\u96c6\u4e2d\u65bc\u5c11\u6578\u5730\u5340\uff0c\u9019\u4f7f\u5f97\u9237\u7684\u56de\u6536\u6280\u8853\u8207\u4ee3\u9237\u6750\u6599\u7684\u7814\u767c\u6210\u70ba\u7576\u4ee3\u6750\u6599\u4f9b\u61c9\u93c8\u5b89\u5168\u7684\u91cd\u8981\u8ab2\u984c\u3002",
  "\x4e\x69":
    "\u93b3\x28\x4e\x69\x63\x6b\x65\x6c\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x4e\x69\uff0c\u539f\u5b50\u5e8f\x20\x32\x38\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u56db\u9031\u671f\u3001\u7b2c\x20\x31\x30\x20\u65cf\x28\x64\x20\u5340\u584a\x29\u3002\u5176\u540d\u7a31\u6e90\u65bc\u5fb7\u8a9e\u300c\x4b\x75\x70\x66\x65\x72\x6e\x69\x63\x6b\x65\x6c\u300d\uff0c\u610f\u70ba\u300c\u9b54\u9b3c\u7684\u9285\u300d\uff0c\u56e0\u5176\u7926\u77f3\u5916\u89c0\u4f3c\u9285\u537b\u7121\u6cd5\u7149\u51fa\u9285\u800c\u5f97\u540d\u3002\x31\x37\x35\x31\x20\u5e74\u7531\u745e\u5178\u5316\u5b78\u5bb6\u514b\u9686\u65af\u6cf0\u7279\x28\x41\x78\x65\x6c\x20\x46\x72\x65\x64\x72\x69\x6b\x20\x43\x72\x6f\x6e\x73\x74\x65\x64\x74\x29\u9996\u6b21\u5206\u96e2\u51fa\u7d14\u91d1\u5c6c\u93b3\u3002\u93b3\u5728\u5730\u6bbc\u4e2d\u5206\u5e03\u5ee3\u6cdb\uff0c\u4e14\u5927\u91cf\u5b58\u5728\u65bc\u5730\u6838\u4e2d\uff0c\u8207\u9435\u5171\u540c\u69cb\u6210\u4e86\u5730\u7403\u7684\u78c1\u5834\u57fa\u790e\uff0c\u662f\u73fe\u4ee3\u51b6\u91d1\u5de5\u696d\u8ce6\u4e88\u6750\u6599\u300c\u6297\u8755\u6027\u300d\u8207\u300c\u97cc\u6027\u300d\u7684\u9748\u9b42\u5143\u7d20\u3002\x0a\x0a\u93b3\u7684\u96fb\u5b50\u7d44\u614b\u70ba\x20\x5b\x41\x72\x5d\x33\x64\u2078\x34\x73\u00b2\uff0c\u5177\u5099\u5178\u578b\u7684\u904e\u6e21\u91d1\u5c6c\u7279\u5fb5\u3002\u5b83\u5728\u5e38\u6eab\u4e0b\u5c0d\u6c27\u8207\u6c34\u6975\u5176\u7a69\u5b9a\uff0c\u8868\u9762\u6703\u5f62\u6210\u7dfb\u5bc6\u7684\u920d\u5316\u819c\u4ee5\u963b\u6b62\u9032\u4e00\u6b65\u6c27\u5316\u3002\u5728\u5316\u5b78\u53cd\u61c9\u4e2d\uff0c\u93b3\u4e3b\u8981\u5c55\u73fe\x20\x2b\x32\x20\u6c27\u5316\u614b\uff0c\u5176\u6c34\u5408\u96e2\u5b50\x20\x4e\x69\u00b2\u207a\x20\u5448\u73fe\u7279\u5fb5\u7684\u7fe0\u7da0\u8272\u3002\u5728\u9ad8\u4e2d\u5316\u5b78\u63a2\u8a0e\u6709\u6a5f\u5408\u6210\u6642\uff0c\u96f7\u5c3c\u93b3\x28\x52\x61\x6e\x65\x79\x20\x4e\x69\x63\x6b\x65\x6c\x29\u662f\u6975\u70ba\u91cd\u8981\u7684\u591a\u76f8\u50ac\u5316\u5291\uff0c\u80fd\u6709\u6548\u50ac\u5316\u70ef\u70f4\u3001\u7094\u70f4\u7684\u52a0\u6c2b\u53cd\u61c9\x28\x48\x79\x64\x72\x6f\x67\x65\x6e\x61\x74\x69\x6f\x6e\x29\uff0c\u9019\u53cd\u6620\u4e86\u904e\u6e21\u91d1\u5c6c\x20\x64\x20\u8ecc\u57df\u5177\u5099\u512a\u7570\u7684\u96fb\u5b50\u5438\u9644\u8207\u8f49\u79fb\u80fd\u529b\u3002\x0a\x0a\u5728\u53f0\u7063\u9ad8\u4e2d\u8ab2\u7db1\u8207\u5de5\u696d\u61c9\u7528\u4e2d\uff0c\u93b3\u5728\u96fb\u89e3\u7cbe\u7149\u8207\u4e0d\u93fd\u92fc\u88fd\u9020\u4e2d\u5360\u6709\u6838\u5fc3\u5730\u4f4d\u3002\u542b\u93b3\u4e0d\u93fd\u92fc\x28\u5982\x20\x33\x30\x34\x20\u4e0d\u93fd\u92fc\uff0c\u542b\x20\x38\x25\x20\u93b3\x29\u5177\u5099\u6975\u4f73\u7684\u8010\u9178\u9e7c\u8150\u8755\u6027\u80fd\uff0c\u662f\u5316\u5de5\u8a2d\u5099\u8207\u6c11\u751f\u9910\u5177\u7684\u4e3b\u529b\u6750\u6599\u3002\u5728\u96fb\u5316\u5b78\u9818\u57df\uff0c\u93b3\u57fa\u96fb\u6c60\x28\u5982\u65e9\u671f\u93b3\u9398\u96fb\u6c60\u53ca\u7576\u524d\u7684\u93b3\u6c2b\u96fb\u6c60\x20\x4e\x69\x2d\x4d\x48\x29\u5728\u96fb\u529b\u5b58\u5132\u767c\u5c55\u53f2\u4e2d\u626e\u6f14\u91cd\u8981\u89d2\u8272\u3002\u6b64\u5916\uff0c\u96fb\u934d\u93b3\u6280\u8853\u56e0\u5176\u5149\u6fa4\u6301\u4e45\u4e14\u786c\u5ea6\u9ad8\uff0c\u88ab\u5ee3\u6cdb\u7528\u65bc\u7cbe\u5bc6\u96f6\u4ef6\u7684\u8868\u9762\u8655\u7406\uff0c\u63d0\u5347\u5176\u6297\u78e8\u640d\u8207\u88dd\u98fe\u6548\u679c\u3002\x0a\x0a\u93b3\u5c55\u73fe\u4e86\u67d0\u4e9b\u53cd\u76f4\u89ba\u7684\u6750\u6599\u884c\u70ba\uff0c\u6700\u8457\u540d\u7684\u5be6\u4f8b\u70ba\u93b3\u9226\u5408\u91d1\x28\x4e\x69\x74\x69\x6e\x6f\x6c\x29\uff0c\u9019\u662f\u4e00\u7a2e\u5177\u5099\u300c\u5f62\u72c0\u8a18\u61b6\u6548\u61c9\u300d\x28\x53\x68\x61\x70\x65\x20\x4d\x65\x6d\x6f\x72\x79\x20\x45\x66\x66\x65\x63\x74\x29\u8207\u8d85\u5f48\u6027\u7684\u667a\u80fd\u6750\u6599\uff0c\u80fd\u8a18\u4f4f\u539f\u59cb\u69cb\u9020\u4e26\u5728\u52a0\u71b1\u5f8c\u6062\u5fa9\uff0c\u5ee3\u6cdb\u61c9\u7528\u65bc\u7259\u9f52\u77ef\u6b63\u7dda\u8207\u5fc3\u8840\u7ba1\u652f\u67b6\u3002\u7269\u7406\u6027\u8cea\u4e0a\uff0c\u93b3\u5177\u5099\u5f37\u78c1\u6027\uff0c\u662f\u88fd\u9020\u5f37\u529b\u6c38\u4e45\u78c1\u9435\x28\u5982\u92c1\u93b3\u9237\u5408\u91d1\x20\x41\x6c\x6e\x69\x63\x6f\x29\u7684\u91cd\u8981\u6210\u5206\u3002\u6709\u8da3\u7684\u662f\uff0c\u5118\u7ba1\u93b3\u5c0d\u73fe\u4ee3\u79d1\u6280\u81f3\u95dc\u91cd\u8981\uff0c\u4f46\u90e8\u5206\u4eba\u7fa4\u5c0d\u93b3\u91d1\u5c6c\u5b58\u5728\u904e\u654f\u53cd\u61c9\uff0c\u9019\u4fc3\u4f7f\u4e86\u6750\u6599\u79d1\u5b78\u5728\u63a5\u89f8\u4eba\u9ad4\u76ae\u819a\u7684\u7a7f\u6234\u88dd\u7f6e\u4e2d\uff0c\u9700\u5c0d\u93b3\u91cb\u653e\u91cf\u9032\u884c\u56b4\u683c\u9650\u5236\u3002",
  "\x43\x75":
    "\u9285\x28\x43\x6f\x70\x70\x65\x72\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x43\x75\uff0c\u539f\u5b50\u5e8f\x20\x32\x39\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u56db\u9031\u671f\u3001\u7b2c\x20\x31\x31\x20\u65cf\x28\x64\x20\u5340\u584a\x29\u3002\u5176\u540d\u7a31\u6e90\u65bc\u62c9\u4e01\u8a9e\u300c\x43\x75\x70\x72\x75\x6d\u300d\uff0c\u610f\u6307\u5730\u4e2d\u6d77\u7684\u585e\u6d66\u8def\u65af\u5cf6\u3002\u9285\u662f\u4eba\u985e\u6700\u65e9\u4f7f\u7528\u7684\u91d1\u5c6c\u4e4b\u4e00\uff0c\u5176\u61c9\u7528\u53f2\u8de8\u8d8a\u4e86\u9752\u9285\u6642\u4ee3\u81f3\u4eca\u3002\u9285\u5728\u81ea\u7136\u754c\u4e2d\u53ef\u4ee5\u6e38\u96e2\u614b\u5b58\u5728\uff0c\u4ea6\u5ee3\u6cdb\u5b58\u5728\u65bc\u9ec3\u9285\u7926\x28\x43\x75\x46\x65\x53\u2082\x29\u8207\u5b54\u96c0\u77f3\x28\x43\x75\u2082\x28\x4f\x48\x29\u2082\x43\x4f\u2083\x29\u4e2d\u3002\u9285\u4ee5\u5176\u7279\u6709\u7684\u7d05\u68d5\u8272\u5149\u6fa4\u8207\u5353\u8d8a\u7684\u5c0e\u96fb\u5c0e\u71b1\u6027\u80fd\uff0c\u6210\u70ba\u96fb\u529b\u6587\u660e\u8207\u901a\u8a0a\u79d1\u6280\u7684\u9aa8\u5e79\u6750\u6599\u3002\x0a\x0a\u9285\u7684\u96fb\u5b50\u7d44\u614b\u70ba\x20\x5b\x41\x72\x5d\x33\x64\u00b9\u2070\x34\x73\u00b9\uff0c\u9019\u662f\u70ba\u4e86\u9054\u6210\x20\x33\x64\x20\u8ecc\u57df\u5168\u6eff\u7684\u7a69\u5b9a\u80fd\u91cf\u72c0\u614b\uff0c\u662f\u9ad8\u4e2d\u5316\u5b78\u8a0e\u8ad6\u96fb\u5b50\u6392\u5e03\u4f8b\u5916\u898f\u5f8b\u7684\u6307\u6a19\u6848\u4f8b\u3002\u9285\u5e38\u898b\u6c27\u5316\u614b\u70ba\x20\x2b\x31\x28\u4e9e\u9285\x29\u8207\x20\x2b\x32\x28\u9285\x29\u3002\u5728\u9ad8\u4e2d\u6559\u6750\u4e2d\uff0c\u4e8c\u50f9\u9285\u96e2\u5b50\u5728\u6c34\u6eb6\u6db2\u4e2d\u7684\u6c34\u5408\u96e2\u5b50\x20\x5b\x43\x75\x28\x48\u2082\x4f\x29\u2084\x5d\u00b2\u207a\x20\u5448\u73fe\u6df1\u85cd\u8272\uff0c\u800c\u52a0\u5165\u904e\u91cf\u6c28\u6c34\u5f8c\u751f\u6210\u7684\u56db\u80fa\u6839\u5408\u9285\u96e2\u5b50\x20\x5b\x43\x75\x28\x4e\x48\u2083\x29\u2084\x5d\u00b2\u207a\x20\u5247\u5448\u73fe\u6975\u5177\u8fa8\u8b58\u5ea6\u7684\u6df1\u85cd\u7d2b\u8272\u3002\u6b64\u5916\uff0c\u900f\u904e\u9285\u8207\u6fc3\u3001\u7a00\u785d\u9178\u53cd\u61c9\u7522\u751f\u7684\u4e8c\u6c27\u5316\u6c2e\u8207\u4e00\u6c27\u5316\u6c2e\uff0c\u662f\u5b78\u751f\u7406\u89e3\u6c27\u5316\u9084\u539f\u52d5\u529b\u5b78\u5dee\u7570\u7684\u5fc5\u4fee\u5be6\u9a57\u3002\x0a\x0a\u5728\u96fb\u5316\u5b78\u9818\u57df\uff0c\u9285\u7684\u6a19\u6e96\u9084\u539f\u96fb\u4f4d\x28\x45\u2070\x20\u2248\x20\x2b\x30\x2e\x33\x34\x20\x56\x29\u4f7f\u5176\u6392\u5728\u6c2b\u4e4b\u5f8c\uff0c\u7121\u6cd5\u8207\u7a00\u9178\u53cd\u61c9\u91cb\u653e\u6c2b\u6c23\uff0c\u4f46\u5728\u96fb\u89e3\u7cbe\u7149\u9285\u7684\u88fd\u7a0b\u4e2d\uff0c\u9019\u4e00\u7279\u6027\u5bb9\u8a31\u96dc\u8cea\u91d1\u5c6c\x28\u5982\u91d1\u3001\u9280\x29\u6c89\u964d\u70ba\u967d\u6975\u6ce5\uff0c\u9054\u6210\u6975\u9ad8\u7d14\u5ea6\u7684\u63d0\u7149\u3002\u73fe\u4ee3\u79d1\u6280\u4e2d\uff0c\u9285\u7684\u5c0e\u96fb\u6027\x28\u50c5\u6b21\u65bc\u9280\x29\u4f7f\u5176\u6210\u70ba\u96fb\u8def\u677f\u5e03\u7dda\u8207\u99ac\u9054\u7e5e\u7d44\u7684\u6838\u5fc3\u3002\u6750\u6599\u79d1\u5b78\u65b9\u9762\uff0c\u9285\u8207\u92c5\u69cb\u6210\u7684\u9ec3\u9285\x28\x42\x72\x61\x73\x73\x29\u53ca\u8207\u932b\u69cb\u6210\u7684\u9752\u9285\x28\x42\x72\x6f\x6e\x7a\x65\x29\uff0c\u900f\u904e\u5408\u91d1\u5316\u5927\u5e45\u63d0\u5347\u4e86\u6a5f\u68b0\u5f37\u5ea6\u8207\u52a0\u5de5\u6027\u80fd\uff0c\u5ee3\u6cdb\u61c9\u7528\u65bc\u7cbe\u5bc6\u6a21\u5177\u8207\u5100\u5668\u96f6\u90e8\u4ef6\u3002\x0a\x0a\u9285\u5728\u751f\u7269\u5b78\u8207\u73fe\u8c61\u5b78\u4e0a\u5c55\u73fe\u51fa\u7368\u7279\u7684\u9b45\u529b\u3002\u5b83\u662f\u8a31\u591a\u7121\u810a\u690e\u52d5\u7269\x28\u5982\u8edf\u9ad4\u52d5\u7269\x29\u9ad4\u5167\u300c\u8840\u85cd\u86cb\u767d\u300d\u7684\u6838\u5fc3\uff0c\u8ca0\u8cac\u8f09\u904b\u6c27\u6c23\uff0c\u9019\u8207\u4eba\u985e\u8840\u7d05\u7d20\u4e2d\u7684\u9435\u7570\u66f2\u540c\u5de5\u3002\u5728\u74b0\u5883\u4e2d\uff0c\u9285\u8868\u9762\u56e0\u6c27\u5316\u800c\u7522\u751f\u7684\u7da0\u8272\u300c\u9285\u7da0\u300d\x28\x50\x61\x74\x69\x6e\x61\x29\u672c\u8cea\u4e0a\u662f\u9e7c\u5f0f\u78b3\u9178\u9285\uff0c\u4e0d\u50c5\u5177\u5099\u53e4\u6a38\u7684\u7f8e\u611f\uff0c\u66f4\u80fd\u4fdd\u8b77\u5167\u90e8\u91d1\u5c6c\u4e0d\u518d\u53d7\u4fb5\u8755\u3002\u6b64\u5916\uff0c\u9285\u5177\u5099\u5929\u7136\u7684\u6297\u5fae\u751f\u6027\uff0c\u80fd\u6709\u6548\u6bba\u6ec5\u63a5\u89f8\u5176\u8868\u9762\u7684\u7d30\u83cc\u8207\u75c5\u6bd2\uff0c\u4f7f\u5176\u5728\u73fe\u4ee3\u516c\u5171\u885b\u751f\u8a2d\u65bd\u8207\u91ab\u7642\u5efa\u7bc9\u7684\u8868\u9762\u6750\u6599\u8a2d\u8a08\u4e2d\u518d\u5ea6\u53d7\u5230\u91cd\u8996\u3002",
  "\x5a\x6e":
    "\u92c5\x28\x5a\x69\x6e\x63\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x5a\x6e\uff0c\u539f\u5b50\u5e8f\x20\x33\x30\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u56db\u9031\u671f\u3001\u7b2c\x20\x31\x32\x20\u65cf\x28\x64\x20\u5340\u584a\x29\u3002\u5176\u540d\u7a31\u53ef\u80fd\u6e90\u65bc\u5fb7\u8a9e\u300c\x5a\x69\x6e\x6b\x65\u300d\uff0c\u610f\u6307\u5176\u5728\u7194\u7210\u4e2d\u51b7\u51dd\u51fa\u7684\u9f52\u72c0\u7d50\u6676\u3002\u92c5\u7684\u4f7f\u7528\u53ef\u8ffd\u6eaf\u81f3\u53e4\u4ee3\u8207\u9285\u7194\u7149\u6210\u9ec3\u9285\u3002\x31\x37\x34\x36\x20\u5e74\u7531\u5fb7\u570b\u5316\u5b78\u5bb6\u99ac\u683c\u62c9\u592b\x28\x41\x6e\x64\x72\x65\x61\x73\x20\x53\x69\x67\x69\x73\x6d\x75\x6e\x64\x20\x4d\x61\x72\x67\x67\x72\x61\x66\x29\u6b63\u5f0f\u5206\u96e2\u51fa\u7d14\u91d1\u5c6c\u92c5\u3002\u92c5\u5728\u5730\u6bbc\u4e2d\u8c50\u5ea6\u6392\u540d\u7b2c\x20\x32\x34\uff0c\u4e3b\u8981\u7926\u77f3\u70ba\u9583\u92c5\u7926\x28\x5a\x6e\x53\x29\u3002\u7531\u65bc\u5176\x20\x33\x64\x20\u8ecc\u57df\u5df2\u5168\u6eff\uff0c\u4e0d\u53c3\u8207\u5178\u578b\u904e\u6e21\u91d1\u5c6c\u7684\x20\x64\x2d\x64\x20\u8ecc\u57df\u8e8d\u9077\uff0c\u56e0\u6b64\u5176\u5316\u5408\u7269\u591a\u5448\u7121\u8272\uff0c\u5e38\u88ab\u8996\u70ba\u904e\u6e21\u91d1\u5c6c\u8207\u4e3b\u65cf\u5143\u7d20\u9593\u7684\u6a4b\u6a11\u3002\x0a\x0a\u5728\u5316\u5b78\u6027\u8cea\u4e0a\uff0c\u92c5\u7684\u96fb\u5b50\u7d44\u614b\u70ba\x20\x5b\x41\x72\x5d\x33\x64\u00b9\u2070\x34\x73\u00b2\uff0c\u5728\u5316\u5408\u7269\u4e2d\u5e7e\u4e4e\u50c5\u5c55\u73fe\x20\x2b\x32\x20\u6c27\u5316\u614b\u3002\u92c5\u5177\u5099\u986f\u8457\u7684\u300c\u5169\u6027\u300d\x28\x41\x6d\x70\x68\x6f\x74\x65\x72\x69\x63\x29\u7279\u5fb5\uff1a\u5176\u91d1\u5c6c\u55ae\u8cea\u3001\u6c27\u5316\u7269\x28\x5a\x6e\x4f\x29\u8207\u6c2b\u6c27\u5316\u7269\x28\x5a\x6e\x28\x4f\x48\x29\u2082\x29\u65e2\u80fd\u6eb6\u65bc\u5f37\u9178\uff0c\u4ea6\u80fd\u6eb6\u65bc\u5f37\u9e7c\u7522\u751f\u92c5\u9178\u6839\u96e2\u5b50\x20\x5b\x5a\x6e\x28\x4f\x48\x29\u2084\x5d\u00b2\u207b\u3002\u5728\u9ad8\u4e2d\u5be6\u9a57\u4e2d\uff0c\u92c5\u7247\u8207\u7a00\u786b\u9178\u53cd\u61c9\u91cb\u653e\u6c2b\u6c23\u662f\u88fd\u5099\u5c11\u91cf\u6c2b\u6c23\u7684\u5e38\u7528\u65b9\u6cd5\u3002\u6b64\u5916\uff0c\u92c5\u96e2\u5b50\x28\x5a\x6e\u00b2\u207a\x29\u5177\u6709\u8f03\u5f37\u7684\u914d\u5408\u80fd\u529b\uff0c\u80fd\u8207\u6c28\u6c34\u5f62\u6210\u7a69\u5b9a\u7684\u56db\u80fa\u5408\u92c5\u932f\u96e2\u5b50\x20\x5b\x5a\x6e\x28\x4e\x48\u2083\x29\u2084\x5d\u00b2\u207a\uff0c\u9019\u5728\u5b9a\u6027\u5206\u6790\u4e2d\u662f\u5340\u5225\u92c5\u8207\u5176\u4ed6\u91d1\u5c6c\u96e2\u5b50\u7684\u91cd\u8981\u624b\u6bb5\u3002\x0a\x0a\u5728\u96fb\u5316\u5b78\u61c9\u7528\u8207\u9632\u8755\u5de5\u7a0b\u4e2d\uff0c\u92c5\u626e\u6f14\u8457\u300c\u72a7\u7272\u967d\u6975\u300d\u7684\u6838\u5fc3\u89d2\u8272\u3002\u7531\u65bc\u92c5\u7684\u6a19\u6e96\u6c27\u5316\u96fb\u4f4d\u8f03\u9ad8\x28\x45\u2070\x20\u2248\x20\x30\x2e\x37\x36\x20\x56\x29\uff0c\u5176\u6d3b\u6027\u5927\u65bc\u9435\uff0c\u56e0\u6b64\u5728\u300c\u934d\u92c5\u92fc\u9435\u300d\x28\u5982\u5e38\u898b\u7684\u767d\u9435\x29\u4e2d\uff0c\u5373\u4fbf\u8868\u9762\u53d7\u640d\uff0c\u92c5\u4e5f\u6703\u512a\u5148\u767c\u751f\u6c27\u5316\u53cd\u61c9\u4ee5\u4fdd\u8b77\u5167\u5c64\u9435\u6750\u4e0d\u88ab\u93fd\u8755\u3002\u5728\u96fb\u6c60\u79d1\u6280\u9818\u57df\uff0c\u92c5\u662f\u4e7e\u96fb\u6c60\x28\u78b3\u92c5\u96fb\u6c60\x29\u8207\u9e7c\u6027\u96fb\u6c60\u7684\u8ca0\u6975\u6750\u6599\uff0c\u900f\u904e\u91d1\u5c6c\u92c5\u7684\u6c27\u5316\u91cb\u653e\u96fb\u5b50\u63d0\u4f9b\u52d5\u529b\u3002\u6b64\u5916\uff0c\u92c5\u8207\u9285\u7d44\u6210\u7684\u300c\u9ec3\u9285\u300d\u5408\u91d1\u5177\u5099\u512a\u7570\u7684\u52a0\u5de5\u6027\u80fd\u8207\u6297\u8755\u529b\uff0c\u5ee3\u6cdb\u61c9\u7528\u65bc\u6a02\u5668\u3001\u7cbe\u5bc6\u6a5f\u68b0\u96f6\u4ef6\u8207\u5efa\u7bc9\u4e94\u91d1\u4e2d\u3002\x0a\x0a\u92c5\u5728\u751f\u7269\u5316\u5b78\u8207\u751f\u547d\u79d1\u5b78\u4e2d\u5177\u5099\u6975\u9ad8\u50f9\u503c\uff0c\u662f\u4eba\u9ad4\u5167\u50c5\u6b21\u65bc\u9435\u7684\u7b2c\u4e8c\u5927\u5fc5\u9700\u5fae\u91cf\u904e\u6e21\u91d1\u5c6c\u3002\u5b83\u662f\u8d85\u904e\u4e09\u767e\u7a2e\u9175\u7d20\x28\u5982\u78b3\u9178\u9150\u9176\u3001\x44\x4e\x41\x20\u805a\u5408\u9176\x29\u7684\u6d3b\u6027\u4e2d\u5fc3\uff0c\u5c0d\u86cb\u767d\u8cea\u5408\u6210\u3001\u7d30\u80de\u5206\u88c2\u53ca\u514d\u75ab\u7cfb\u7d71\u7684\u904b\u4f5c\u81f3\u95dc\u91cd\u8981\uff0c\u56e0\u6b64\u88ab\u8b7d\u70ba\u300c\u751f\u547d\u4e4b\u5143\u7d20\u300d\u3002\u53cd\u76f4\u89ba\u7684\u662f\uff0c\u96d6\u7136\u91d1\u5c6c\u92c5\u5728\u5e38\u6eab\u4e0b\u8cea\u5730\u8f03\u8106\uff0c\u4f46\u7576\u52a0\u71b1\u81f3\x20\x31\x30\x30\u2013\x31\x35\x30\x20\u00b0\x43\x20\u6642\uff0c\u5176\u5ef6\u5c55\u6027\u6703\u5927\u5e45\u63d0\u5347\uff0c\u8b8a\u5f97\u6613\u65bc\u58d3\u5ef6\u6210\u5f62\u3002\u9019\u7a2e\u5f9e\u5b88\u8b77\u5927\u578b\u92fc\u9435\u7d50\u69cb\u7684\u5de5\u696d\u5e95\u8272\uff0c\u5230\u652f\u6490\u5fae\u89c0\u751f\u7269\u4ee3\u8b1d\u7684\u95dc\u9375\u9a45\u52d5\u8005\uff0c\u7cbe\u78ba\u5c55\u73fe\u4e86\u92c5\u5143\u7d20\u5728\u6750\u6599\u79d1\u5b78\u8207\u751f\u547d\u73fe\u8c61\u9593\u7684\u5e73\u8861\u4e4b\u7f8e\u3002",
  "\x47\x61":
    "\u93b5\x28\x47\x61\x6c\x6c\x69\x75\x6d\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x47\x61\uff0c\u539f\u5b50\u5e8f\x20\x33\x31\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u56db\u9031\u671f\u3001\u7b2c\x20\x31\x33\x20\u65cf\x28\x70\x20\u5340\u584a\x29\u3002\u93b5\u662f\u9580\u5f97\u5217\u592b\x28\x4d\x65\x6e\x64\x65\x6c\x65\x65\x76\x29\u9810\u8a00\u4e2d\u7684\u300c\u985e\u92c1\u300d\x28\x45\x6b\x61\x2d\x61\x6c\x75\x6d\x69\x6e\x75\x6d\x29\uff0c\u5176\u6027\u8cea\u8207\u9810\u6e2c\u9a5a\u4eba\u543b\u5408\uff0c\u6210\u70ba\u9031\u671f\u8868\u7406\u8ad6\u7684\u91cd\u8981\u652f\u67f1\u3002\x31\x38\x37\x35\x20\u5e74\u7531\u6cd5\u570b\u5316\u5b78\u5bb6\u5e03\u74e6\u535a\u5fb7\u6717\x28\x4c\x65\x63\x6f\x71\x20\x64\x65\x20\x42\x6f\x69\x73\x62\x61\x75\x64\x72\x61\x6e\x29\u900f\u904e\u5149\u8b5c\u5206\u6790\u767c\u73fe\uff0c\u4e26\u4ee5\u6cd5\u570b\u7684\u62c9\u4e01\u8a9e\u540d\u7a31\x20\x47\x61\x6c\x6c\x69\x61\x20\u547d\u540d\u3002\u93b5\u5728\u81ea\u7136\u754c\u4e2d\u4e0d\u4ee5\u6e38\u96e2\u614b\u5b58\u5728\uff0c\u4e3b\u8981\u4ee5\u75d5\u91cf\u5206\u6563\u65bc\u92c1\u571f\u7926\u8207\u92c5\u7926\u4e2d\uff0c\u662f\u73fe\u4ee3\u5fae\u96fb\u5b50\u8207\u5149\u96fb\u7522\u696d\u7684\u95dc\u9375\u6230\u7565\u6750\u6599\u3002\x0a\x0a\u93b5\u7684\u96fb\u5b50\u7d44\u614b\u70ba\x20\x5b\x41\x72\x5d\x33\x64\u00b9\u2070\x34\x73\u00b2\x34\x70\u00b9\uff0c\u5728\u5316\u5b78\u6027\u8cea\u4e0a\u5448\u73fe\x20\x2b\x33\x20\u6c27\u5316\u614b\uff0c\u4e14\u5177\u5099\u8207\u92c1\u76f8\u4f3c\u7684\u5169\u6027\x28\x41\x6d\x70\x68\x6f\x74\x65\x72\x69\x63\x29\u7279\u5fb5\u3002\u93b5\u6700\u5f15\u4eba\u6ce8\u76ee\u7684\u7269\u7406\u7279\u5fb5\u662f\u5176\u7570\u5e38\u4f4e\u7684\u7194\u9ede\x28\x32\x39\x2e\x37\x36\x20\u00b0\x43\x29\uff0c\u9019\u610f\u5473\u8457\u5b83\u5728\u6eab\u6696\u7684\u5ba4\u6eab\u4e0b\u6216\u662f\u7f6e\u65bc\u624b\u638c\u4e2d\u4fbf\u6703\u7194\u5316\u70ba\u6db2\u614b\uff0c\u4f46\u5176\u6cb8\u9ede\u537b\u9ad8\u9054\x20\x32\x32\x32\x39\x20\u00b0\x43\uff0c\u4f7f\u5176\u64c1\u6709\u6240\u6709\u5143\u7d20\u4e2d\u8de8\u5ea6\u6700\u9577\u7684\u6db2\u614b\u6eab\u5ea6\u7bc4\u570d\u3002\u6b64\u5916\uff0c\u93b5\u8207\u6c34\u76f8\u4f3c\uff0c\u5728\u51dd\u56fa\u6642\u9ad4\u7a4d\u6703\u81a8\u8139\x28\u7d04\x20\x33\x2e\x31\x25\x29\uff0c\u56e0\u6b64\u91d1\u5c6c\u93b5\u4e0d\u53ef\u5132\u5b58\u65bc\u73bb\u7483\u6216\u91d1\u5c6c\u5bb9\u5668\u4e2d\uff0c\u4ee5\u9632\u5bb9\u5668\u56e0\u51cd\u8139\u800c\u7834\u88c2\u3002\x0a\x0a\u5728\u53f0\u7063\u9ad8\u4e2d\u5316\u5b78\u8207\u534a\u5c0e\u9ad4\u7522\u696d\u8108\u7d61\u4e2d\uff0c\u93b5\u7684\u5316\u5408\u7269\u2014\u2014\u7837\u5316\u93b5\x28\x47\x61\x41\x73\x29\u8207\u6c2e\u5316\u93b5\x28\x47\x61\x4e\x29\u5177\u6709\u6838\u5fc3\u5730\u4f4d\u3002\u7837\u5316\u93b5\u5177\u5099\u6bd4\u77fd\u66f4\u9ad8\u7684\u96fb\u5b50\u9077\u79fb\u7387\u8207\u76f4\u63a5\u80fd\u9699\x28\x44\x69\x72\x65\x63\x74\x20\x62\x61\x6e\x64\x67\x61\x70\x29\uff0c\u662f\u9ad8\u983b\u901a\u8a0a\u5143\u4ef6\u8207\u9ad8\u6548\u7387\u592a\u967d\u80fd\u96fb\u6c60\u7684\u9996\u9078\u6750\u6599\uff1b\u800c\u6c2e\u5316\u93b5\u5247\u662f\u88fd\u4f5c\u85cd\u5149\x20\x4c\x45\x44\x20\u8207\u7b2c\u4e09\u4ee3\u534a\u5c0e\u9ad4\u529f\u7387\u5143\u4ef6\u7684\u95dc\u9375\uff0c\u652f\u6490\u4e86\u73fe\u4ee3\u5149\u96fb\u6280\u8853\u7684\u9769\u547d\u3002\u5728\u6750\u6599\u79d1\u5b78\u4e2d\uff0c\u93b5\u3001\u92a6\u3001\u932b\u7d44\u6210\u7684\u5408\u91d1\x28\x47\x61\x6c\x69\x6e\x73\x74\x61\x6e\x29\u5728\u5e38\u6eab\u4e0b\u5448\u6db2\u614b\u4e14\u7121\u6bd2\uff0c\u5df2\u88ab\u5ee3\u6cdb\u61c9\u7528\u65bc\u53d6\u4ee3\u50b3\u7d71\u6c34\u9280\u9ad4\u6eab\u8a08\u4e2d\u7684\u6c5e\uff0c\u964d\u4f4e\u74b0\u5883\u6c59\u67d3\u98a8\u96aa\u3002\x0a\x0a\u93b5\u5c55\u73fe\u4e86\u67d0\u4e9b\u7279\u6b8a\u7684\u5316\u5b78\u4fb5\u8755\u73fe\u8c61\u3002\u7576\u6db2\u614b\u93b5\u8207\u92c1\u63a5\u89f8\u6642\uff0c\u93b5\u6703\u6ef2\u5165\u92c1\u7684\u6676\u754c\x28\x47\x72\x61\x69\x6e\x20\x62\x6f\x75\x6e\x64\x61\x72\x79\x29\uff0c\u7834\u58de\u5176\u91d1\u5c6c\u9375\u7d50\u7d50\u69cb\uff0c\u5c0e\u81f4\u5805\u786c\u7684\u92c1\u6750\u8b8a\u5f97\u5982\u540c\u7d19\u5f35\u822c\u8106\u5f31\uff0c\u9019\u7a2e\u73fe\u8c61\u7a31\u70ba\u300c\u93b5\u8106\u300d\u3002\u6b64\u5916\uff0c\u93b5\u5728\u786b\u9178\u8207\u91cd\u927b\u9178\u9240\u6eb6\u6db2\u4e2d\u6703\u5c55\u73fe\u51fa\u898f\u5f8b\u6536\u7e2e\u8207\u64f4\u5f35\u7684\u300c\u93b5\u5fc3\u8df3\u300d\x28\x47\x61\x6c\x6c\x69\x75\x6d\x20\x42\x65\x61\x74\x69\x6e\x67\x20\x48\x65\x61\x72\x74\x29\u96fb\u5316\u5b78\u632f\u76ea\u73fe\u8c61\uff0c\u6a21\u64ec\u4e86\u751f\u7269\u5fc3\u81df\u7684\u8108\u52d5\u3002\u9019\u7a2e\u5f9e\u6975\u4f4e\u7194\u9ede\u7684\u7269\u7406\u5947\u8da3\uff0c\u5230\u9a45\u52d5\u73fe\u4ee3\x20\x35\x47\x20\u901a\u8a0a\u8207\x20\x4c\x45\x44\x20\u7167\u660e\u7684\u6750\u6599\u7279\u6027\uff0c\u4f7f\u93b5\u6210\u70ba\u9031\u671f\u8868\u4e2d\u6975\u5177\u9b45\u529b\u4e14\u6280\u8853\u50f9\u503c\u6975\u9ad8\u7684\u5143\u7d20\u3002",
  "\x47\x65":
    "\u937a\x28\x47\x65\x72\x6d\x61\x6e\x69\x75\x6d\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x47\x65\uff0c\u539f\u5b50\u5e8f\x20\x33\x32\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u56db\u9031\u671f\u3001\u7b2c\x20\x31\x34\x20\u65cf\x28\u78b3\u65cf\u5143\u7d20\uff0c\x70\x20\u5340\u584a\x29\u3002\u937a\u662f\u9580\u5f97\u5217\u592b\u9810\u8a00\u4e2d\u7684\u300c\u985e\u77fd\u300d\x28\x45\x6b\x61\x2d\x73\x69\x6c\x69\x63\x6f\x6e\x29\uff0c\u5176\u6027\u8cea\u7684\u767c\u73fe\u9032\u4e00\u6b65\u978f\u56fa\u4e86\u9031\u671f\u5f8b\u7684\u6b0a\u5a01\u3002\x31\x38\x38\x36\x20\u5e74\u7531\u5fb7\u570b\u5316\u5b78\u5bb6\u6eab\u514b\u52d2\x28\x43\x6c\x65\x6d\x65\x6e\x73\x20\x57\x69\x6e\x6b\x6c\x65\x72\x29\u5728\u5206\u6790\u786b\u9280\u937a\u7926\u6642\u9996\u6b21\u5206\u96e2\uff0c\u4e26\u4ee5\u5176\u7956\u570b\u5fb7\u570b\x28\x47\x65\x72\x6d\x61\x6e\x69\x61\x29\u547d\u540d\u3002\u937a\u662f\u4e00\u7a2e\u7070\u767d\u8272\u3001\u5177\u5099\u91d1\u5c6c\u5149\u6fa4\u7684\u985e\u91d1\u5c6c\u5143\u7d20\uff0c\u5176\u6676\u9ad4\u7d50\u69cb\u8207\u947d\u77f3\u76f8\u4f3c\uff0c\u6027\u8cea\u4ecb\u65bc\u77fd\u8207\u932b\u4e4b\u9593\uff0c\u662f\u534a\u5c0e\u9ad4\u7269\u7406\u5b78\u767c\u5c55\u53f2\u4e0a\u7684\u958b\u8def\u5148\u92d2\u3002\x0a\x0a\u937a\u7684\u96fb\u5b50\u7d44\u614b\u70ba\x20\x5b\x41\x72\x5d\x33\x64\u00b9\u2070\x34\x73\u00b2\x34\x70\u00b2\uff0c\u5176\u5316\u5b78\u6027\u8cea\u53d7\x20\x31\x34\x20\u65cf\u8da8\u52e2\u5f71\u97ff\uff0c\u4e3b\u8981\u6c27\u5316\u614b\u70ba\x20\x2b\x34\u3002\u937a\u7684\u96fb\u8ca0\u5ea6\x28\x32\x2e\x30\x31\x29\u7565\u9ad8\u65bc\u77fd\uff0c\u4f7f\u5176\u5316\u5b78\u9375\u7d50\u5e36\u6709\u66f4\u660e\u986f\u7684\u5171\u50f9\u7279\u5fb5\u3002\u8eab\u70ba\u9593\u63a5\u80fd\u9699\u534a\u5c0e\u9ad4\uff0c\u937a\u7684\u80fd\u5e36\u5bec\u5ea6\x28\x42\x61\x6e\x64\x67\x61\x70\x29\u7d04\u70ba\x20\x30\x2e\x36\x37\x20\x65\x56\uff0c\u986f\u8457\u5c0f\u65bc\u77fd\x28\x31\x2e\x31\x20\x65\x56\x29\uff0c\u9019\u4f7f\u5f97\u937a\u5143\u4ef6\u5728\u8655\u7406\u7d05\u5916\u7dda\u8a0a\u865f\u6642\u8868\u73fe\u512a\u7570\u3002\u5728\u9ad8\u4e2d\u5316\u5b78\u63a2\u8a0e\u56fa\u9ad4\u7d50\u69cb\u6642\uff0c\u937a\u5e38\u88ab\u4f5c\u70ba\u300c\u539f\u5b50\u6676\u9ad4\u300d\u7684\u7bc4\u4f8b\uff0c\u5176\u786c\u5ea6\u9ad8\u3001\u8cea\u8106\uff0c\u4e14\u4e0d\u6eb6\u65bc\u7a00\u9178\u6216\u9e7c\uff0c\u50c5\u80fd\u6eb6\u65bc\u5f37\u6c27\u5316\u6027\u9178\u6216\u7194\u878d\u9e7c\u3002\x0a\x0a\u937a\u5728\u73fe\u4ee3\u5149\u5b78\u8207\u96fb\u5b50\u6280\u8853\u4e2d\u5177\u6709\u4e0d\u53ef\u66ff\u4ee3\u7684\u61c9\u7528\u3002\x31\x39\x34\x37\x20\u5e74\u4eba\u985e\u53f2\u4e0a\u7b2c\u4e00\u500b\u96fb\u6676\u9ad4\u5373\u662f\u4ee5\u937a\u88fd\u6210\uff0c\u96d6\u7136\u96a8\u5f8c\u5728\u7a4d\u9ad4\u96fb\u8def\u9818\u57df\u88ab\u77fd\u53d6\u4ee3\uff0c\u4f46\u937a\u5728\u7d05\u5916\u7dda\u5149\u5b78\x28\u5982\u591c\u8996\u93e1\u3001\u71b1\u50cf\u5100\x29\u4e2d\u4ecd\u662f\u6838\u5fc3\u6750\u6599\uff0c\u56e0\u5176\u5c0d\u7d05\u5916\u5149\u5177\u6709\u6975\u4f73\u7684\u900f\u904e\u7387\u3002\u5728\u901a\u8a0a\u79d1\u6280\u4e2d\uff0c\u4e8c\u6c27\u5316\u937a\x28\x47\x65\x4f\u2082\x29\u5e38\u88ab\u647b\u5165\u5149\u7e96\u82af\u90e8\uff0c\u7528\u4ee5\u63d0\u9ad8\u6298\u5c04\u7387\u4e26\u964d\u4f4e\u8a0a\u865f\u640d\u6bc0\uff0c\u78ba\u4fdd\u8cc7\u8a0a\u7684\u9ad8\u901f\u50b3\u8f38\u3002\u6b64\u5916\uff0c\u937a\u5728\u592a\u967d\u80fd\u9818\u57df\u5e38\u8207\u93b5\u7d50\u5408\u88fd\u6210\u591a\u63a5\u9762\u592a\u967d\u80fd\u96fb\u6c60\uff0c\u61c9\u7528\u65bc\u5c0d\u80fd\u91cf\u8f49\u63db\u6548\u7387\u8981\u6c42\u6975\u9ad8\u7684\u822a\u592a\u8207\u4eba\u9020\u885b\u661f\u5de5\u7a0b\u3002\x0a\x0a\u937a\u5728\u6750\u6599\u63d0\u7d14\u6280\u8853\u4e2d\u5177\u6709\u91cd\u8981\u7684\u5730\u4f4d\u3002\u5340\u57df\u7194\u7149\u6cd5\x28\x5a\x6f\x6e\x65\x20\x52\x65\x66\x69\x6e\x69\x6e\x67\x29\u6700\u521d\u5373\u662f\u70ba\u4e86\u63d0\u7d14\u937a\u4ee5\u9054\u5230\u534a\u5c0e\u9ad4\u7b49\u7d1a\x28\u7d14\u5ea6\u9ad8\u9054\x20\x39\x39\x2e\x39\x39\x39\x39\x39\x39\x39\x25\x29\u800c\u958b\u767c\uff0c\u9019\u4e00\u6280\u8853\u5f8c\u4f86\u63a8\u5ee3\u81f3\u6240\u6709\u96fb\u5b50\u7d1a\u6750\u6599\u7684\u751f\u7522\u3002\u6709\u8da3\u7684\u662f\uff0c\u96d6\u7136\u937a\u5c0d\u4eba\u985e\u4e26\u975e\u5fc5\u9700\u5143\u7d20\uff0c\u4f46\u67d0\u4e9b\u6709\u6a5f\u937a\u5316\u5408\u7269\u66fe\u88ab\u5ba3\u7a31\u5177\u5099\u514d\u75ab\u8abf\u7bc0\u529f\u80fd\uff0c\u7136\u800c\u7f3a\u4e4f\u79d1\u5b78\u5be6\u8b49\u4e14\u5177\u5099\u6f5b\u5728\u814e\u6bd2\u6027\uff0c\u9019\u63d0\u9192\u4e86\u985e\u91d1\u5c6c\u5143\u7d20\u5728\u751f\u7269\u9ad4\u5167\u4ee3\u8b1d\u7684\u8907\u96dc\u6027\u3002\u9019\u7a2e\u5f9e\u534a\u5c0e\u9ad4\u59cb\u7956\u5230\u73fe\u4ee3\u7d05\u5916\u7dda\u5149\u5b78\u5fc3\u81df\u7684\u8eab\u5206\u8f49\u8b8a\uff0c\u9ad4\u73fe\u4e86\u937a\u5728\u8cc7\u8a0a\u6642\u4ee3\u4e0d\u53ef\u78e8\u6ec5\u7684\u6b77\u53f2\u8207\u73fe\u5be6\u50f9\u503c\u3002",
  "\x41\x73":
    "\u7837\x28\x41\x72\x73\x65\x6e\x69\x63\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x41\x73\uff0c\u539f\u5b50\u5e8f\x20\x33\x33\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u56db\u9031\u671f\u3001\u7b2c\x20\x31\x35\x20\u65cf\x28\u6c2e\u65cf\u5143\u7d20\uff0c\x70\x20\u5340\u584a\x29\u3002\u5176\u540d\u7a31\u6e90\u65bc\u5e0c\u81d8\u8a9e\u300c\x61\x72\x73\x65\x6e\x69\x6b\x6f\x6e\u300d\uff0c\u610f\u6307\u9ec3\u8272\u96cc\u9ec3\u3002\u7837\u5728\u81ea\u7136\u754c\u4e2d\u4ee5\u591a\u7a2e\u786b\u5316\u7269\u7926\u77f3\x28\u5982\u6bd2\u7802\x29\u5f62\u5f0f\u5b58\u5728\uff0c\u81ea\u53e4\u5373\u56e0\u5176\u6bd2\u6027\u8207\u7149\u91d1\u8853\u95dc\u806f\u800c\u805e\u540d\u3002\x31\x32\x35\x30\x20\u5e74\u5de6\u53f3\uff0c\u5927\u963f\u723e\u4f2f\u7279\x28\x41\x6c\x62\x65\x72\x74\x75\x73\x20\x4d\x61\x67\x6e\x75\x73\x29\u88ab\u8a8d\u70ba\u662f\u9996\u4f4d\u5206\u96e2\u51fa\u55ae\u8cea\u7837\u7684\u4eba\u3002\u96d6\u7136\u7837\u5728\u6c11\u4fd7\u6587\u5316\u4e2d\u5e38\u8207\u4e2d\u6bd2\u806f\u60f3\u5728\u4e00\u8d77\uff0c\u4f46\u5728\u73fe\u4ee3\u6750\u6599\u79d1\u5b78\u8207\u8fb2\u696d\u79d1\u6280\u4e2d\uff0c\u5b83\u537b\u662f\u6975\u5176\u7cbe\u5bc6\u4e14\u4e0d\u53ef\u6216\u7f3a\u7684\u529f\u80fd\u5143\u7d20\u3002\x0a\x0a\u7837\u7684\u96fb\u5b50\u7d44\u614b\u70ba\x20\x5b\x41\x72\x5d\x33\x64\u00b9\u2070\x34\x73\u00b2\x34\x70\u00b3\uff0c\u5448\u73fe\u985e\u91d1\u5c6c\u7279\u6027\u3002\u5b83\u5177\u5099\u591a\u7a2e\u540c\u7d20\u7570\u5f62\u9ad4\uff0c\u5176\u4e2d\u6700\u7a69\u5b9a\u7684\u662f\u91d1\u5c6c\u72c0\u7684\u7070\u8272\u7837\uff0c\u5177\u5099\u5c64\u72c0\u6676\u9ad4\u7d50\u69cb\u8207\u5fae\u5f31\u7684\u5c0e\u96fb\u6027\u3002\u7837\u5728\u5e38\u58d3\u4e0b\u52a0\u71b1\u6703\u76f4\u63a5\u300c\u6607\u83ef\u300d\u800c\u4e0d\u7d93\u904e\u6db2\u614b\uff0c\u9019\u662f\u9ad8\u4e2d\u5316\u5b78\u8a0e\u8ad6\u76f8\u8b8a\u5316\u6642\u5e38\u7528\u7684\u5178\u578b\u7bc4\u4f8b\u3002\u7837\u7684\u6c27\u5316\u614b\u5206\u5e03\u7531\x20\x2d\x33\x20\u5230\x20\x2b\x35\uff0c\u5e38\u898b\u5316\u5408\u7269\u5982\u4e09\u6c27\u5316\u4e8c\u7837\x28\x41\x73\u2082\x4f\u2083\uff0c\u4fd7\u7a31\u7812\u971c\x29\u5177\u6709\u5287\u6bd2\u3002\u5728\u5206\u5b50\u7d50\u69cb\u63a2\u8a0e\u4e2d\uff0c\u7837\u5316\u6c2b\x28\x41\x73\x48\u2083\x29\u7684\u7acb\u9ad4\u7d50\u69cb\u53ef\u5229\u7528\x20\x56\x53\x45\x50\x52\x20\u7406\u8ad6\u9810\u6e2c\u70ba\u4e09\u89d2\u9310\u5f62\uff0c\u8207\u6c28\u6c23\u76f8\u4f3c\u4f46\u9375\u89d2\u8f03\u5c0f\uff0c\u53cd\u6620\u4e86\u4e2d\u5fc3\u539f\u5b50\u534a\u5f91\u589e\u5927\u5c0d\u9375\u7d50\u7684\u5f71\u97ff\u3002\x0a\x0a\u5728\u53f0\u7063\u9ad8\u4e2d\u8ab2\u7db1\u8207\u534a\u5c0e\u9ad4\u9818\u57df\uff0c\u7837\u662f\u96fb\u5b50\u5de5\u696d\u7684\u91cd\u8981\u647b\u96dc\u5291\u3002\u900f\u904e\u5c07\u7837\u539f\u5b50\u647b\u5165\u77fd\u6676\u5713\u4e2d\uff0c\u53ef\u63d0\u4f9b\u984d\u5916\u7684\u50f9\u96fb\u5b50\uff0c\u5f62\u6210\x20\x6e\x20\u578b\u534a\u5c0e\u9ad4\u3002\u66f4\u91cd\u8981\u7684\u662f\uff0c\u7837\u8207\u93b5\u7d44\u6210\u7684\u300c\u7837\u5316\u93b5\u300d\x28\x47\x61\x41\x73\x29\u5177\u5099\u9ad8\u96fb\u5b50\u901f\u7387\u8207\u767c\u5149\u7279\u6027\uff0c\u662f\u5fae\u6ce2\u901a\u8a0a\u8207\u7d05\u5916\u7dda\u96f7\u5c04\u4e8c\u6975\u9ad4\u7684\u6838\u5fc3\u3002\u74b0\u5883\u5316\u5b78\u65b9\u9762\uff0c\u7837\u5728\u5730\u4e0b\u6c34\u4e2d\u7684\u6c61\u67d3\x28\u5982\u8457\u540d\u7684\u70cf\u8173\u75c5\u4e8b\u4ef6\x29\u662f\u53f0\u7063\u516c\u885b\u53f2\u4e0a\u91cd\u8981\u7684\u8ab2\u984c\uff0c\u9019\u4fc3\u4f7f\u4e86\u74b0\u5883\u5de5\u7a0b\u4e2d\u5c0d\u7837\u7269\u7a2e\u5206\u6790\x28\u5982\u4e9e\u7837\u9178\u6839\x20\x41\x73\x4f\u2083\u00b3\u207b\x20\u8207\u7837\u9178\u6839\x20\x41\x73\x4f\u2084\u00b3\u207b\x29\u53ca\u76f8\u95dc\u5438\u9644\u6280\u8853\u7684\u6df1\u5ea6\u7814\u7a76\u3002\x0a\x0a\u7837\u5c55\u73fe\u4e86\u5316\u5b78\u9451\u5b9a\u53f2\u4e0a\u7684\u91cc\u7a0b\u7891\u7279\u5fb5\u3002\x31\x38\x33\x36\x20\u5e74\u958b\u767c\u7684\u300c\u99ac\u6c0f\u8a66\u9a57\u300d\x28\x4d\x61\x72\x73\x68\x20\x74\x65\x73\x74\x29\u5229\u7528\u7837\u8207\u92c5\u3001\u9178\u53cd\u61c9\u751f\u6210\x20\x41\x73\x48\u2083\x20\u7684\u7279\u6027\uff0c\u80fd\u5728\u6cd5\u91ab\u9451\u5b9a\u4e2d\u7cbe\u78ba\u5075\u6e2c\u6975\u5fae\u91cf\u7684\u7837\u3002\u6709\u8da3\u7684\u662f\uff0c\u96d6\u7136\u7837\u4ee5\u6bd2\u6027\u8457\u7a31\uff0c\u4f46\u5728\u6975\u5fae\u91cf\u7684\u60c5\u6cc1\u4e0b\uff0c\u4e09\u6c27\u5316\u4e8c\u7837\u5df2\u88ab\u73fe\u4ee3\u91ab\u5b78\u8f49\u5316\u70ba\u6cbb\u7642\u7279\u5b9a\u985e\u578b\u767d\u8840\u75c5\x28\x41\x50\x4c\x29\u7684\u6a19\u9776\u85e5\u7269\u3002\u9019\u7a2e\u5f9e\u300c\u8b00\u6bba\u4e4b\u738b\u300d\u5230\u300c\u534a\u5c0e\u9ad4\u57fa\u77f3\u300d\u8207\u300c\u6297\u764c\u826f\u85e5\u300d\u7684\u89d2\u8272\u6f14\u8b8a\uff0c\u7cbe\u78ba\u8a6e\u91cb\u4e86\u5316\u5b78\u5143\u7d20\u5728\u4e0d\u540c\u6fc3\u5ea6\u8207\u5316\u5b78\u74b0\u5883\u4e0b\uff0c\u5c0d\u4eba\u985e\u6587\u660e\u7522\u751f\u7684\u77db\u76fe\u800c\u5de8\u5927\u7684\u5f71\u97ff\u529b\u3002",
  "\x53\x65":
    "\u7852\x28\x53\x65\x6c\x65\x6e\x69\x75\x6d\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x53\x65\uff0c\u539f\u5b50\u5e8f\x20\x33\x34\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u56db\u9031\u671f\u3001\u7b2c\x20\x31\x36\x20\u65cf\x28\u6c27\u65cf\u5143\u7d20\uff0c\x70\x20\u5340\u584a\x29\u3002\x31\x38\x31\x37\x20\u5e74\u7531\u745e\u5178\u5316\u5b78\u5bb6\u8c9d\u9f4a\u91cc\u70cf\u65af\x28\x4a\u00f6\x6e\x73\x20\x4a\x61\x63\x6f\x62\x20\x42\x65\x72\x7a\x65\x6c\x69\x75\x73\x29\u5728\u8655\u7406\u786b\u9178\u5ee0\u6b98\u6e23\u6642\u767c\u73fe\u3002\u5176\u540d\u7a31\u6e90\u65bc\u5e0c\u81d8\u8a9e\u300c\x53\x65\x6c\x65\x6e\x65\u300d\x28\u6708\u4eae\x29\uff0c\u4ee5\u547c\u61c9\u6027\u8cea\u76f8\u4f3c\u4f46\u66f4\u65e9\u767c\u73fe\u7684\u78b2\x28\x54\x65\x6c\x6c\x75\x73\uff0c\u5730\u7403\x29\u3002\u7852\u5728\u81ea\u7136\u754c\u4e2d\u6975\u5c11\u4ee5\u55ae\u8cea\u5b58\u5728\uff0c\u4e3b\u8981\u4f34\u751f\u65bc\u786b\u5316\u7269\u7926\u77f3\u4e2d\u3002\u5b83\u662f\u751f\u547d\u9ad4\u5fc5\u9700\u7684\u5fae\u91cf\u5143\u7d20\uff0c\u4ea6\u662f\u6750\u6599\u79d1\u5b78\u4e2d\u7814\u7a76\u300c\u5149\u96fb\u6548\u61c9\u300d\u8207\u534a\u5c0e\u9ad4\u7279\u6027\u7684\u91cd\u8981\u5c0d\u8c61\u3002\x0a\x0a\u7852\u7684\u96fb\u5b50\u7d44\u614b\u70ba\x20\x5b\x41\x72\x5d\x33\x64\u00b9\u2070\x34\x73\u00b2\x34\x70\u2074\uff0c\u5177\u5099\u660e\u986f\u7684\u975e\u91d1\u5c6c\u5411\u985e\u91d1\u5c6c\u904e\u6e21\u7279\u5fb5\u3002\u5b83\u64c1\u6709\u8c50\u5bcc\u7684\u540c\u7d20\u7570\u5f62\u9ad4\uff0c\u5176\u4e2d\u7070\u8272\u91d1\u5c6c\u7852\u662f\u6700\u7a69\u5b9a\u7684\u5f62\u5f0f\uff0c\u5177\u5099\u9577\u93c8\u72c0\u5206\u5b50\u7d50\u69cb\u3002\u7852\u6700\u91cd\u8981\u7684\u7269\u7406\u7279\u6027\u662f\u5176\u986f\u8457\u7684\u300c\u5149\u96fb\u5c0e\u6027\u300d\x28\x50\x68\x6f\x74\x6f\x63\x6f\x6e\x64\x75\x63\x74\x69\x76\x69\x74\x79\x29\uff1a\u5728\u5149\u7167\u4e0b\u5176\u96fb\u5c0e\u7387\u6703\u6025\u5287\u589e\u52a0\uff0c\u9019\u4f7f\u5176\u6210\u70ba\u65e9\u671f\u5149\u96fb\u5143\u4ef6\u7814\u767c\u7684\u6838\u5fc3\u3002\u7852\u7684\u6c27\u5316\u614b\u7531\x20\x2d\x32\x20\u5230\x20\x2b\x36\uff0c\u5176\u542b\u6c27\u9178\u5982\u4e9e\u7852\u9178\x28\x48\u2082\x53\x65\x4f\u2083\x29\u8207\u7852\u9178\x28\x48\u2082\x53\x65\x4f\u2084\x29\u7684\u9178\u6027\u898f\u5f8b\uff0c\u662f\u9ad8\u4e2d\u5316\u5b78\u63a2\u8a0e\u9031\u671f\u8868\u542b\u6c27\u9178\u5f37\u5ea6\u8da8\u52e2\u7684\u91cd\u8981\u88dc\u5145\u8cc7\u6599\u3002\x0a\x0a\u5728\u73fe\u4ee3\u79d1\u6280\u4e2d\uff0c\u7852\u7684\u5149\u96fb\u7279\u6027\u88ab\u5ee3\u6cdb\u61c9\u7528\u65bc\u5f71\u5370\u6a5f\u7684\u5149\u63a5\u6536\u9f13\x28\u65e9\u671f\x20\x58\x65\x72\x6f\x78\x20\u88fd\u7a0b\x29\u4ee5\u53ca\u592a\u967d\u80fd\u96fb\u6c60\u4e2d\u3002\u7279\u5225\u662f\u300c\u9285\u92a6\u93b5\u7852\u300d\x28\x43\x49\x47\x53\x29\u8584\u819c\u592a\u967d\u80fd\u96fb\u6c60\uff0c\u56e0\u5176\u9ad8\u5149\u5438\u6536\u4fc2\u6578\u8207\u826f\u597d\u7684\u6750\u6599\u97cc\u6027\uff0c\u88ab\u8996\u70ba\u6975\u5177\u6f5b\u529b\u7684\u5149\u4f0f\u6280\u8853\u3002\u5728\u5de5\u696d\u88fd\u9020\u4e2d\uff0c\u7852\u88ab\u5927\u91cf\u7528\u65bc\u73bb\u7483\u9664\u8272\u8207\u8457\u8272\uff0c\u80fd\u4e2d\u548c\u9435\u96dc\u8cea\u7522\u751f\u7684\u7da0\u8272\uff0c\u6216\u5728\u8f03\u9ad8\u6fc3\u5ea6\u4e0b\u7522\u751f\u9bae\u8c54\u7684\u300c\u5bf6\u77f3\u7d05\u300d\u73bb\u7483\u3002\u5728\u751f\u7269\u5316\u5b78\u9818\u57df\uff0c\u7852\u662f\u9ea9\u80f1\u7518\u80bd\u904e\u6c27\u5316\u7269\u9176\x28\x47\x50\x78\x29\u7684\u6838\u5fc3\u7d44\u6210\uff0c\u8ca0\u8cac\u6e05\u9664\u7d30\u80de\u5167\u7684\u81ea\u7531\u57fa\uff0c\u5c0d\u63d0\u5347\u4eba\u9ad4\u514d\u75ab\u529b\u8207\u6297\u6c27\u5316\u5177\u6709\u6838\u5fc3\u4f5c\u7528\u3002\x0a\x0a\u7852\u5728\u5316\u5b78\u53cd\u61c9\u4e2d\u8868\u73fe\u51fa\u6975\u4f73\u7684\u300c\u5149\u654f\u611f\u5ea6\u300d\uff0c\u5b83\u662f\u6700\u65e9\u88ab\u89c0\u6e2c\u5230\u5177\u5099\u5149\u751f\u4f0f\u6253\u6548\u61c9\u7684\u56fa\u9ad4\u7269\u8cea\uff0c\u958b\u555f\u4e86\u73fe\u4ee3\u5f71\u50cf\u50b3\u611f\u5668\u7684\u5148\u6cb3\u3002\u6709\u8da3\u7684\u662f\uff0c\u96d6\u7136\u7852\u662f\u5fae\u91cf\u5fc5\u9700\u5143\u7d20\uff0c\u4f46\u5176\u651d\u53d6\u91cf\u5340\u9593\u6975\u7a84\uff0c\u904e\u91cf\u651d\u53d6\u6703\u5c0e\u81f4\u7852\u4e2d\u6bd2\uff0c\u5c55\u73fe\u51fa\u986f\u8457\u7684\u751f\u7269\u5316\u5b78\u8907\u96dc\u6027\u3002\u5728\u74b0\u5883\u79d1\u5b78\u4e2d\uff0c\u7852\u7684\u56de\u6536\u4ea6\u53d7\u5230\u91cd\u8996\uff0c\u56e0\u70ba\u5b83\u8207\u6c5e\u7b49\u91cd\u91d1\u5c6c\u5177\u6709\u6975\u5f37\u7684\u89aa\u548c\u529b\uff0c\u80fd\u5f62\u6210\u7a69\u5b9a\u7684\u7852\u5316\u7269\u9032\u800c\u964d\u4f4e\u5176\u751f\u7269\u6bd2\u6027\u3002\u9019\u7a2e\u5f9e\u6708\u5149\u822c\u7684\u767c\u73fe\u53f2\u5230\u5b88\u8b77\u7d30\u80de\u5065\u5eb7\u7684\u9632\u79a6\u6a5f\u5236\uff0c\u4f7f\u7852\u6210\u70ba\u904e\u6e21\u5340\u5143\u7d20\u4e2d\u5177\u5099\u6df1\u539a\u8de8\u9818\u57df\u50f9\u503c\u7684\u6210\u54e1\u3002",
  "\x42\x72":
    "\u6eb4\x28\x42\x72\x6f\x6d\x69\x6e\x65\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x42\x72\uff0c\u539f\u5b50\u5e8f\x20\x33\x35\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u56db\u9031\u671f\u3001\u7b2c\x20\x31\x37\x20\u65cf\x28\u9e75\u7d20\uff0c\x70\x20\u5340\u584a\x29\u3002\u5176\u540d\u7a31\u6e90\u65bc\u5e0c\u81d8\u8a9e\u300c\x62\x72\x6f\x6d\x6f\x73\u300d\uff0c\u610f\u70ba\u300c\u60e1\u81ed\u300d\uff0c\u53cd\u6620\u4e86\u5176\u84b8\u6c23\u5177\u6709\u5f37\u70c8\u7684\u523a\u6fc0\u6027\u6c23\u5473\u3002\x31\x38\x32\x36\x20\u5e74\u7531\u6cd5\u570b\u5316\u5b78\u5bb6\u5df4\u62c9\u723e\x28\x41\x6e\x74\x6f\x69\x6e\x65\x20\x4a\u00e9\x72\u00f4\x6d\x65\x20\x42\x61\x6c\x61\x72\x64\x29\u8207\u5fb7\u570b\u5316\u5b78\u5bb6\u52d2\u7dad\x28\x43\x61\x72\x6c\x20\x4c\u00f6\x77\x69\x67\x29\u5206\u5225\u7368\u7acb\u767c\u73fe\u3002\u6eb4\u662f\u9031\u671f\u8868\u4e2d\u6975\u5176\u7279\u6b8a\u7684\u5143\u7d20\uff0c\u5b83\u662f\u5e38\u6eab\u5e38\u58d3\u4e0b\u552f\u4e00\u5448\u6db2\u614b\u7684\u975e\u91d1\u5c6c\u5143\u7d20\uff0c\u5728\u81ea\u7136\u754c\u4e2d\u4e3b\u8981\u4ee5\u6eb4\u96e2\u5b50\x28\x42\x72\u207b\x29\u7684\u5f62\u5f0f\u5b58\u5728\u65bc\u6d77\u6c34\u8207\u82e6\u6ef7\u4e2d\uff0c\u8c50\u5ea6\u9060\u4f4e\u65bc\u6c2f\u8207\u6c1f\u3002\x0a\x0a\u6eb4\u7684\u96fb\u5b50\u7d44\u614b\u70ba\x20\x5b\x41\x72\x5d\x33\x64\u00b9\u2070\x34\x73\u00b2\x34\x70\u2075\uff0c\u96fb\u8ca0\u5ea6\u7d04\u70ba\x20\x32\x2e\x39\x36\uff0c\u5177\u5099\u5f37\u70c8\u7684\u6c27\u5316\u6027\u3002\u5728\u6a19\u6e96\u72c0\u614b\u4e0b\uff0c\u6eb4\u4ee5\u96d9\u539f\u5b50\u5206\u5b50\x28\x42\x72\u2082\x29\u5f62\u5f0f\u5b58\u5728\uff0c\u662f\u4e00\u7a2e\u6df1\u7d05\u8910\u8272\u3001\u6975\u6613\u63ee\u767c\u7684\u6db2\u9ad4\u3002\u5728\u53f0\u7063\u9ad8\u4e2d\u5316\u5b78\u5be6\u9a57\u4e2d\uff0c\u6eb4\u5728\u6709\u6a5f\u6eb6\u5291\x28\u5982\u56db\u6c2f\u5316\u78b3\x20\x43\x43\x6c\u2084\x29\u4e2d\u7684\u6eb6\u89e3\u5ea6\u9060\u5927\u65bc\u6c34\uff0c\u4e14\u5448\u73fe\u7279\u5fb5\u7684\u7d05\u68d5\u8272\uff0c\u9019\u4f7f\u5176\u6210\u70ba\u6aa2\u9a57\u6709\u6a5f\u5316\u5408\u7269\u300c\u4e0d\u98fd\u548c\u5ea6\u300d\u7684\u95dc\u9375\u8a66\u5291\u3002\u900f\u904e\u6eb4\u6c34\u892a\u8272\u53cd\u61c9\uff0c\u5b78\u751f\u53ef\u4ee5\u76f4\u89c0\u5730\u89c0\u5bdf\u5230\u70ef\u70f4\u6216\u7094\u70f4\u767c\u751f\u7684\u89aa\u96fb\u52a0\u6210\u53cd\u61c9\u3002\u6b64\u5916\uff0c\u6eb4\u8207\u5176\u4ed6\u9e75\u7d20\x28\x46\u2082\u3001\x43\x6c\u2082\u3001\x49\u2082\x29\u7684\u6d3b\u6027\u8da8\u52e2\u6bd4\u8f03\uff0c\u662f\u7406\u89e3\u5143\u7d20\u9031\u671f\u5f8b\u4e2d\u975e\u91d1\u5c6c\u6027\u8b8a\u5316\u898f\u5f8b\u7684\u7d93\u5178\u6848\u4f8b\u3002\x0a\x0a\u5728\u73fe\u4ee3\u5de5\u696d\u8207\u91ab\u5b78\u9818\u57df\uff0c\u6eb4\u7684\u61c9\u7528\u8de8\u8d8a\u4e86\u5b89\u5168\u8207\u79d1\u6280\u3002\u542b\u6eb4\u963b\u71c3\u5291\x28\x42\x46\x52\x73\x29\u662f\u96fb\u5b50\u7522\u54c1\u8207\u5efa\u7bc9\u6750\u6599\u4e2d\u9810\u9632\u706b\u707d\u7684\u91cd\u8981\u6dfb\u52a0\u5291\uff0c\u5229\u7528\u6eb4\u81ea\u7531\u57fa\u5728\u9ad8\u6eab\u4e0b\u6355\u6349\u71c3\u71d2\u9023\u9396\u53cd\u61c9\u4e2d\u7684\u6d3b\u6027\u6c2b\uff0c\u9054\u6210\u6291\u71c3\u6548\u679c\u3002\u5728\u5f71\u50cf\u6280\u8853\u53f2\u4e2d\uff0c\u6eb4\u5316\u9280\x28\x41\x67\x42\x72\x29\u5c0d\u5149\u7684\u6975\u9ad8\u654f\u611f\u5ea6\uff0c\u4f7f\u5176\u6210\u70ba\u50b3\u7d71\u81a0\u5377\u651d\u5f71\u7684\u611f\u5149\u6838\u5fc3\u3002\u5728\u74b0\u5883\u79d1\u5b78\u4e2d\uff0c\u7531\u65bc\u6eb4\u7684\u5f37\u63ee\u767c\u6027\u8207\u7a7f\u900f\u6027\uff0c\u542b\u6eb4\u6709\u6a5f\u5316\u5408\u7269\x28\u5982\u6eb4\u5316\u7532\u70f7\x29\u66fe\u88ab\u5ee3\u6cdb\u7528\u4f5c\u71fb\u84b8\u6bba\u87f2\u5291\uff0c\u4f46\u56e0\u5176\u5c0d\u81ed\u6c27\u5c64\u7684\u7834\u58de\u6f5b\u529b\uff0c\u76ee\u524d\u5df2\u53d7\u5230\u570b\u969b\u516c\u7d04\u7684\u56b4\u683c\u7ba1\u63a7\u3002\x0a\x0a\u6eb4\u5728\u7269\u7406\u884c\u70ba\u4e0a\u8868\u73fe\u51fa\u986f\u8457\u7684\u5bc6\u5ea6\u8207\u64f4\u6563\u7279\u5fb5\u3002\u5176\u84b8\u6c23\u5bc6\u5ea6\u7d04\u70ba\u7a7a\u6c23\u7684\x20\x35\x2e\x35\x20\u500d\uff0c\u6d29\u6f0f\u6642\u6703\u8fc5\u901f\u7a4d\u805a\u65bc\u4f4e\u7aaa\u8655\uff0c\u5c0d\u547c\u5438\u9053\u9ecf\u819c\u5177\u5099\u5f37\u5927\u7684\u4fb5\u8755\u6027\u3002\u6709\u8da3\u7684\u662f\uff0c\u96d6\u7136\u6eb4\u55ae\u8cea\u5177\u5099\u5287\u6bd2\uff0c\u4f46\u5728\u6d77\u6d0b\u751f\u7269\x28\u5982\u67d0\u4e9b\u6d77\u85fb\x29\u4e2d\u537b\u5b58\u5728\u591a\u7a2e\u5929\u7136\u6709\u6a5f\u6eb4\u5316\u5408\u7269\u3002\u5728\u96fb\u5316\u5b78\u4e2d\uff0c\u6eb4\u7684\u6a19\u6e96\u9084\u539f\u96fb\u4f4d\x28\x45\u2070\x20\u2248\x20\x2b\x31\x2e\x30\x37\x20\x56\x29\u4f7f\u5176\u80fd\u88ab\u6c2f\u6c23\u6c27\u5316\uff0c\u9019\u662f\u5de5\u696d\u4e0a\u5f9e\u6d77\u6c34\u4e2d\u63d0\u6eb4\u7684\u57fa\u790e\u5316\u5b78\u539f\u7406\u3002\u9019\u7a2e\u5f9e\u6df1\u8272\u8150\u8755\u6027\u6db2\u9ad4\u5230\u4fdd\u8b77\u73fe\u4ee3\u96fb\u8def\u677f\u5b89\u5168\u7684\u8f49\u8b8a\uff0c\u5c55\u73fe\u4e86\u6eb4\u5728\u9e75\u7d20\u5bb6\u65cf\u4e2d\u65e2\u66b4\u70c8\u53c8\u5be6\u7528\u7684\u96d9\u91cd\u7279\u5fb5\u3002",
  "\x4b\x72":
    "\u6c2a\x28\x4b\x72\x79\x70\x74\x6f\x6e\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x4b\x72\uff0c\u539f\u5b50\u5e8f\x20\x33\x36\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u56db\u9031\u671f\u3001\u7b2c\x20\x31\x38\x20\u65cf\x28\u7a00\u6709\u6c23\u9ad4\uff0c\x70\x20\u5340\u584a\x29\u3002\u5176\u540d\u7a31\u6e90\u65bc\u5e0c\u81d8\u8a9e\u300c\x6b\x72\x79\x70\x74\x6f\x73\u300d\uff0c\u610f\u70ba\u300c\u96b1\u85cf\u300d\u3002\x31\x38\x39\x38\x20\u5e74\u7531\u82f1\u570b\u5316\u5b78\u5bb6\u62c9\u59c6\u9f4a\x28\x57\x69\x6c\x6c\x69\x61\x6d\x20\x52\x61\x6d\x73\x61\x79\x29\u8207\u7279\u62c9\u5f17\u65af\x28\x4d\x6f\x72\x72\x69\x73\x20\x54\x72\x61\x76\x65\x72\x73\x29\u5728\u6db2\u614b\u7a7a\u6c23\u5206\u993e\u5f8c\u7684\u6b98\u9918\u7269\u4e2d\u767c\u73fe\u3002\u6c2a\u5728\u5927\u6c23\u4e2d\u7684\u542b\u91cf\u6975\u5176\u7a00\u5c11\x28\u7d04\x20\x31\x2e\x31\x34\x20\x70\x70\x6d\x29\uff0c\u662f\u5178\u578b\u7684\u5316\u5b78\u60f0\u6027\u6c23\u9ad4\uff0c\u5728\u5e38\u6eab\u4e0b\u4ee5\u7121\u8272\u3001\u7121\u5473\u7684\u55ae\u539f\u5b50\u5f62\u614b\u5b58\u5728\uff0c\u50c5\u5728\u6975\u7aef\u9ad8\u80fd\u689d\u4ef6\u4e0b\u80fd\u5c55\u73fe\u5fae\u5f31\u7684\u9375\u7d50\u50be\u5411\u3002\x0a\x0a\u6c2a\u7684\u96fb\u5b50\u7d44\u614b\u70ba\x20\x5b\x41\x72\x5d\x33\x64\u00b9\u2070\x34\x73\u00b2\x34\x70\u2076\uff0c\u64c1\u6709\u7684\u516b\u9685\u9ad4\u7d50\u69cb\u4f7f\u5176\u7b2c\u4e00\u96fb\u96e2\u80fd\u6975\u9ad8\uff0c\u5316\u5b78\u7a69\u5b9a\u6027\u6975\u5f37\u3002\u96d6\u7136\u6c2a\u66fe\u88ab\u8a8d\u70ba\u5b8c\u5168\u4e0d\u53c3\u8207\u5316\u5b78\u53cd\u61c9\uff0c\u4f46\u5728\x20\x31\x39\x36\x30\x20\u5e74\u4ee3\u79d1\u5b78\u5bb6\u6210\u529f\u5408\u6210\u51fa\u4e8c\u6c1f\u5316\u6c2a\x28\x4b\x72\x46\u2082\x29\uff0c\u9019\u662f\u4e00\u7a2e\u50c5\u80fd\u5728\u6975\u4f4e\u6eab\u4e0b\u7a69\u5b9a\u5b58\u5728\u7684\u5f37\u6c27\u5316\u5291\uff0c\u5176\u767c\u73fe\u6311\u6230\u4e86\u7a00\u6709\u6c23\u9ad4\u7d55\u5c0d\u60f0\u6027\u7684\u50b3\u7d71\u5b9a\u7fa9\u3002\u6c2a\u7684\u5206\u5b50\u9593\u51e1\u5f97\u74e6\u529b\u8f03\u6c26\u3001\u6c16\u66f4\u5f37\uff0c\u4f7f\u5176\u6cb8\u9ede\x28\u7d04\x20\x2d\x31\x35\x33\x2e\x34\x20\u00b0\x43\x29\u8f03\u9ad8\u3002\u5728\u9ad8\u4e2d\u5316\u5b78\u63a2\u8a0e\u7406\u60f3\u6c23\u9ad4\u884c\u70ba\u8207\u5206\u5b50\u904b\u52d5\u8ad6\u6642\uff0c\u6c2a\u7684\u9ad8\u539f\u5b50\u8cea\u91cf\u8207\u8f03\u5927\u7684\u6975\u5316\u7387\uff0c\u4f7f\u5176\u8207\u6c26\u6c23\u5728\u5be6\u969b\u6c23\u9ad4\u504f\u5dee\u7684\u8868\u73fe\u4e0a\u5f62\u6210\u986f\u8457\u5c0d\u6bd4\u3002\x0a\x0a\u5728\u73fe\u4ee3\u7cbe\u5bc6\u79d1\u6280\u8207\u5ea6\u91cf\u8861\u53f2\u4e0a\uff0c\u6c2a\u5177\u6709\u4e0d\u53ef\u66ff\u4ee3\u7684\u5730\u4f4d\u3002\x31\x39\x36\x30\x20\u5e74\u81f3\x20\x31\x39\x38\x33\x20\u5e74\u9593\uff0c\u570b\u969b\u55ae\u4f4d\u5236\u5c07\u300c\u516c\u5c3a\u300d\u5b9a\u7fa9\u70ba\u6c2a\x2d\x38\x36\x20\u540c\u4f4d\u7d20\u5728\u771f\u7a7a\u4e2d\u767c\u5c04\u8b5c\u7dda\u6ce2\u9577\u7684\u7279\u5b9a\u500d\u6578\uff0c\u5c55\u73fe\u4e86\u5176\u539f\u5b50\u5149\u8b5c\u6975\u9ad8\u7684\u7a69\u5b9a\u6027\u3002\u61c9\u7528\u65b9\u9762\uff0c\u6c2a\u6c23\u586b\u5145\u65bc\u9ad8\u6548\u7387\u7701\u96fb\u71c8\u6ce1\u8207\u9583\u5149\u71c8\u4e2d\uff0c\u80fd\u5728\u9ad8\u6eab\u4e0b\u4fdd\u8b77\u71c8\u7d72\u4e26\u767c\u51fa\u6975\u5f37\u7684\u767d\u5149\uff0c\u5ee3\u6cdb\u7528\u65bc\u9ad8\u901f\u651d\u5f71\u8207\u6a5f\u5834\u8dd1\u9053\u5c0e\u5f15\u71c8\u3002\u6b64\u5916\uff0c\u6c2a\u6c1f\u6e96\u5206\u5b50\u96f7\u5c04\x28\x4b\x72\x46\x20\x6c\x61\x73\x65\x72\x29\u5728\u534a\u5c0e\u9ad4\u5149\u523b\u6280\u8853\u4e2d\u626e\u6f14\u95dc\u9375\u89d2\u8272\uff0c\u5229\u7528\u5176\u767c\u51fa\u7684\u6df1\u7d2b\u5916\u5149\x28\x32\x34\x38\x20\x6e\x6d\x29\u523b\u5283\u5948\u7c73\u7b49\u7d1a\u7684\u96fb\u8def\u5716\u5f62\u3002\x0a\x0a\u95dc\u65bc\u6c2a\u7684\u7269\u7406\u7279\u5fb5\uff0c\u5176\u5728\u653e\u96fb\u7ba1\u4e2d\u6703\u767c\u51fa\u660e\u4eae\u7684\u9ec3\u7da0\u8272\u6216\u6a58\u8272\u5149\u8292\uff0c\u9019\u7a2e\u5149\u8b5c\u7279\u6027\u4f7f\u5176\u5728\u5149\u5b78\u7814\u7a76\u4e2d\u88ab\u7528\u4f5c\u6821\u6e96\u6e90\u3002\u6709\u8da3\u7684\u662f\uff0c\u6c2a\u5728\u5927\u6c23\u4e2d\u7684\u542b\u91cf\u96d6\u7136\u7a00\u5fae\uff0c\u4f46\u5b83\u662f\u6838\u5206\u88c2\u53cd\u61c9\u7684\u526f\u7522\u7269\u4e4b\u4e00\uff0c\u56e0\u6b64\u76e3\u6e2c\u5927\u6c23\u4e2d\u6c2a\x2d\x38\x35\x28\u2078\u2075\x4b\x72\x29\u7684\u6fc3\u5ea6\uff0c\u6210\u70ba\u570b\u969b\u9593\u5075\u6e2c\u79d8\u5bc6\u6838\u6b66\u8a66\u9a57\u6216\u6838\u5ee2\u6599\u8655\u7406\u6d3b\u52d5\u7684\u91cd\u8981\u6280\u8853\u624b\u6bb5\u3002\u6b64\u5916\uff0c\u7531\u65bc\u6c2a\u5177\u5099\u4e00\u5b9a\u7684\u9ebb\u9189\u6548\u80fd\x28\u96d6\u7136\u5176\u5206\u58d3\u9700\u6975\u9ad8\x29\uff0c\u5b83\u5728\u6f5b\u6c34\u91ab\u5b78\u4e2d\u4e5f\u662f\u7814\u7a76\u9ad8\u58d3\u60f0\u6027\u6c23\u9ad4\u5c0d\u795e\u7d93\u5f71\u97ff\u7684\u5c0d\u8c61\u4e4b\u4e00\u3002\u6c2a\u5143\u7d20\u9019\u7a2e\u5f9e\u5927\u6c23\u4e2d\u7684\u96b1\u8eab\u8005\u5230\u7cbe\u5bc6\u91cf\u6e2c\u57fa\u6e96\u7684\u8f49\u8b8a\uff0c\u9ad4\u73fe\u4e86\u7a00\u6709\u6c23\u9ad4\u5728\u5fae\u89c0\u7a69\u5b9a\u8207\u5b8f\u89c0\u61c9\u7528\u9593\u7684\u5f35\u529b\u3002",
  "\x52\x62":
    "\u92a3\x28\x52\x75\x62\x69\x64\x69\x75\x6d\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x52\x62\uff0c\u539f\u5b50\u5e8f\x20\x33\x37\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u4e94\u9031\u671f\u3001\u7b2c\x20\x31\x20\u65cf\x28\u9e7c\u91d1\u5c6c\uff0c\x73\x20\u5340\u584a\x29\u3002\u5176\u540d\u7a31\u6e90\u65bc\u62c9\u4e01\u8a9e\u300c\x72\x75\x62\x69\x64\x75\x73\u300d\uff0c\u610f\u70ba\u300c\u6df1\u7d05\u300d\uff0c\u5f97\u540d\u65bc\u5176\u5149\u8b5c\u4e2d\u5169\u689d\u7279\u5fb5\u6027\u7684\u6df1\u7d05\u8272\u8b5c\u7dda\u3002\x31\x38\x36\x31\x20\u5e74\u7531\u5fb7\u570b\u5316\u5b78\u5bb6\u672c\u751f\x28\x52\x6f\x62\x65\x72\x74\x20\x42\x75\x6e\x73\x65\x6e\x29\u8207\u57fa\u5e0c\u970d\u592b\x28\x47\x75\x73\x74\x61\x76\x20\x4b\x69\x72\x63\x68\x68\x6f\x66\x66\x29\u5229\u7528\u5149\u8b5c\u5100\u5728\u92f0\u96f2\u6bcd\u7926\u4e2d\u767c\u73fe\u3002\u92a3\u662f\u5730\u6bbc\u4e2d\u542b\u91cf\u6392\u540d\u7b2c\x20\x32\x33\x20\u7684\u5143\u7d20\uff0c\u8c50\u5ea6\u8207\u9285\u76f8\u8fd1\uff0c\u4f46\u56e0\u5176\u5206\u5e03\u6975\u5176\u5206\u6563\u4e14\u5316\u5b78\u6d3b\u6027\u6975\u9ad8\uff0c\u901a\u5e38\u4f34\u751f\u65bc\u92f0\u7926\u8207\u9240\u7926\u4e2d\uff0c\u662f\u7814\u7a76\u8d85\u51b7\u539f\u5b50\u7269\u7406\u8207\u91cf\u5b50\u5149\u5b78\u7684\u6838\u5fc3\u6750\u6599\u3002\x0a\x0a\u5728\u5316\u5b78\u884c\u70ba\u4e0a\uff0c\u92a3\u7684\u96fb\u5b50\u7d44\u614b\u70ba\x20\x5b\x4b\x72\x5d\x35\x73\u00b9\uff0c\u5176\u50f9\u96fb\u5b50\u9060\u96e2\u539f\u5b50\u6838\uff0c\u5c0e\u81f4\u5176\u7b2c\u4e00\u96fb\u96e2\u80fd\u6975\u4f4e\u3002\u92a3\u8868\u73fe\u51fa\u6975\u5176\u72c2\u66b4\u7684\u9e7c\u91d1\u5c6c\u7279\u6027\uff1a\u5176\u706b\u7130\u53cd\u61c9\u5448\u73fe\u7279\u5fb5\u7684\u7d2b\u7d05\u8272\uff1b\u8207\u6c34\u53cd\u61c9\u7684\u5287\u70c8\u7a0b\u5ea6\u9060\u8d85\u9209\u8207\u9240\uff0c\u5373\u4fbf\u5728\x20\x2d\x31\x30\x30\x20\u00b0\x43\x20\u7684\u51b0\u584a\u4e0a\u4e5f\u80fd\u767c\u751f\u7206\u70b8\u6027\u53cd\u61c9\u3002\u5728\u53f0\u7063\u9ad8\u4e2d\u5316\u5b78\u95dc\u65bc\u9031\u671f\u6027\u8da8\u52e2\u7684\u63a2\u8a0e\u4e2d\uff0c\u92a3\u662f\u9a57\u8b49\u300c\u91d1\u5c6c\u6d3b\u6027\u96a8\u539f\u5b50\u5e8f\u589e\u52a0\u800c\u589e\u52a0\u300d\u7684\u6700\u4f73\u5be6\u4f8b\u3002\u7531\u65bc\u5176\u6975\u6613\u8207\u7a7a\u6c23\u4e2d\u7684\u6c27\u6c23\u53ca\u6c34\u5206\u53cd\u61c9\uff0c\u91d1\u5c6c\u92a3\u5fc5\u9808\u5c01\u88dd\u5728\u5145\u6eff\u60f0\u6027\u6c23\u9ad4\u7684\u5b89\u74ff\u74f6\u4e2d\uff0c\u6216\u4fdd\u5b58\u5728\u56b4\u683c\u812b\u6c34\u7684\u7926\u7269\u6cb9\u5167\u3002\x0a\x0a\u5728\u73fe\u4ee3\u5c16\u7aef\u61c9\u7528\u4e2d\uff0c\u92a3\u5728\u7cbe\u5bc6\u6642\u983b\u8207\u91cf\u5b50\u8a08\u7b97\u9818\u57df\u5177\u6709\u9818\u5148\u5730\u4f4d\u3002\u92a3\u539f\u5b50\u9418\x28\x52\x75\x62\x69\x64\x69\x75\x6d\x20\x41\x74\x6f\x6d\x69\x63\x20\x43\x6c\x6f\x63\x6b\x29\u5229\u7528\u5176\u539f\u5b50\u7684\u8d85\u7cbe\u7d30\u80fd\u7d1a\u8e8d\u9077\uff0c\u63d0\u4f9b\u4e86\u6975\u9ad8\u7a69\u5b9a\u6027\u7684\u6642\u9593\u57fa\u6e96\uff0c\u5ee3\u6cdb\u61c9\u7528\u65bc\u5168\u7403\u5b9a\u4f4d\u7cfb\u7d71\x28\x47\x50\x53\x29\u7684\u885b\u661f\u8207\u96fb\u8a0a\u57fa\u5730\u53f0\u3002\u5728\u4f4e\u6eab\u7269\u7406\u5b78\u4e2d\uff0c\u92a3\u539f\u5b50\u662f\u5be6\u73fe\u300c\u73bb\u8272\x2d\u611b\u56e0\u65af\u5766\u51dd\u805a\u300d\x28\x42\x45\x43\x29\u7684\u9996\u9078\u7269\u7a2e\uff0c\u79d1\u5b78\u5bb6\u900f\u904e\u96f7\u5c04\u51b7\u537b\u8207\u78c1\u6355\u7372\u6280\u8853\uff0c\u6210\u529f\u5c07\u92a3\u539f\u5b50\u51b7\u537b\u81f3\u63a5\u8fd1\u7d55\u5c0d\u96f6\u5ea6\uff0c\u958b\u555f\u4e86\u7814\u7a76\u91cf\u5b50\u529b\u5b78\u5b8f\u89c0\u73fe\u8c61\u7684\u65b0\u9818\u57df\u3002\u6b64\u5916\uff0c\u92a3\u9e7d\u5728\u7279\u7a2e\u73bb\u7483\u8207\u5149\u96fb\u7ba1\u4e2d\u4ea6\u6709\u5c11\u91cf\u61c9\u7528\uff0c\u4ee5\u63d0\u5347\u5149\u96fb\u8f49\u5316\u6548\u7387\u3002\x0a\x0a\u92a3\u5c55\u73fe\u4e86\u67d0\u4e9b\u53cd\u76f4\u89ba\u7684\u7269\u7406\u6027\u8cea\u3002\u96d6\u7136\u5b83\u662f\u56fa\u614b\u91d1\u5c6c\uff0c\u4f46\u5176\u7194\u9ede\u50c5\u7d04\x20\x33\x39\x2e\x33\x20\u00b0\x43\uff0c\u9019\u610f\u5473\u8457\u5b83\u5728\u708e\u71b1\u74b0\u5883\u4e0b\u6703\u7194\u5316\u70ba\u6db2\u614b\u3002\u5728\u96fb\u5316\u5b78\u4e2d\uff0c\u92a3\u7684\u6a19\u6e96\u6c27\u5316\u96fb\u4f4d\x28\x45\u2070\x20\u2248\x20\x2b\x32\x2e\x39\x38\x20\x56\x29\u6392\u5728\u96fb\u5316\u5b78\u5e8f\u7684\u6975\u7aef\u524d\u7aef\uff0c\u53cd\u6620\u51fa\u5176\u6975\u6613\u5931\u53bb\u96fb\u5b50\u8b8a\u6210\u92a3\u96e2\u5b50\x28\x52\x62\u207a\x29\u7684\u50be\u5411\u3002\u6709\u8da3\u7684\u662f\uff0c\u92a3\u96e2\u5b50\u5728\u751f\u7269\u9ad4\u5167\u8207\u9240\u96e2\u5b50\x28\x4b\u207a\x29\u6975\u5176\u76f8\u4f3c\uff0c\u80fd\u88ab\u7d30\u80de\u5167\u7684\u96e2\u5b50\u901a\u9053\u8aa4\u8a8d\u4e26\u651d\u5165\uff0c\u9019\u4f7f\u5176\u5728\u751f\u7406\u7814\u7a76\u4e2d\u5e38\u88ab\u7528\u4f5c\u8ffd\u8e64\u9240\u4ee3\u8b1d\u7684\u5316\u5b78\u6a19\u8a18\u3002\u9019\u7a2e\u5f9e\u672c\u751f\u71c8\u4e0b\u7684\u7d2b\u7d05\u9583\u5149\u5230\u91cf\u5b50\u4e16\u754c\u4e2d\u7d55\u5c0d\u96f6\u5ea6\u7684\u63a2\u91dd\uff0c\u7cbe\u78ba\u8a6e\u91cb\u4e86\u9e7c\u91d1\u5c6c\u5143\u7d20\u5728\u6975\u9650\u6d3b\u6027\u8207\u7cbe\u5bc6\u7269\u7406\u61c9\u7528\u9593\u7684\u5e73\u8861\u3002",
  "\x53\x72":
    "\u9376\x28\x53\x74\x72\x6f\x6e\x74\x69\x75\x6d\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x53\x72\uff0c\u539f\u5b50\u5e8f\x20\x33\x38\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u4e94\u9031\u671f\u3001\u7b2c\x20\x32\x20\u65cf\x28\u9e7c\u571f\u91d1\u5c6c\uff0c\x73\x20\u5340\u584a\x29\u3002\u5176\u540d\u7a31\u6e90\u65bc\u8607\u683c\u862d\u7684\u5c0f\u93ae\u65af\u7279\u6717\u8482\u5b89\x28\x53\x74\x72\x6f\x6e\x74\x69\x61\x6e\x29\uff0c\u7576\u5730\u7926\u77f3\u4e2d\u9996\u6b21\u767c\u73fe\u4e86\u8a72\u5143\u7d20\u7684\u78b3\u9178\u9e7d\u7926\u7269\u3002\x31\x37\x39\x30\x20\u5e74\u7531\u514b\u52de\u798f\u5fb7\x28\x41\x64\x61\x69\x72\x20\x43\x72\x61\x77\x66\x6f\x72\x64\x29\u8fa8\u8b58\u51fa\u5176\u8207\u92c7\u7684\u5dee\u7570\uff0c\u96a8\u5f8c\u65bc\x20\x31\x38\x30\x38\x20\u5e74\u7531\u6234\u7dad\x28\x48\x75\x6d\x70\x68\x72\x79\x20\x44\x61\x76\x79\x29\u900f\u904e\u96fb\u89e3\u6cd5\u5206\u96e2\u51fa\u7d14\u91d1\u5c6c\u3002\u9227\u662f\u5178\u578b\u7684\u6d3b\u6027\u91d1\u5c6c\uff0c\u5728\u5730\u6bbc\u4e2d\u4ee5\u5929\u9752\u77f3\x28\x53\x72\x53\x4f\u2084\x29\u8207\u83f1\u9376\u7926\x28\x53\x72\x43\x4f\u2083\x29\u5f62\u5f0f\u5b58\u5728\uff0c\u662f\u7814\u7a76\u5143\u7d20\u6027\u8cea\u96a8\u539f\u5b50\u5e8f\u905e\u589e\u800c\u5448\u73fe\u898f\u5f8b\u8b8a\u5316\u7684\u91cd\u8981\u5be6\u4f8b\u3002\x0a\x0a\u5728\u5316\u5b78\u6027\u8cea\u4e0a\uff0c\u9236\u7684\u96fb\u5b50\u7d44\u614b\u70ba\x20\x5b\x4b\x72\x5d\x35\x73\u00b2\uff0c\u5728\u53cd\u61c9\u4e2d\u50be\u5411\u5931\u53bb\u5169\u500b\u96fb\u5b50\u5f62\u6210\u7a69\u5b9a\u7684\x20\x53\x72\u00b2\u207a\u3002\u9376\u7684\u6a19\u6e96\u6c27\u5316\u96fb\u4f4d\x28\x45\u2070\x20\u2248\x20\x32\x2e\x38\x39\x20\x56\x29\u9ad8\u65bc\u9223\u800c\u4f4e\u65bc\u92c7\uff0c\u53cd\u6620\u51fa\u9e7c\u571f\u91d1\u5c6c\u7531\u4e0a\u800c\u4e0b\u91d1\u5c6c\u6d3b\u6027\u589e\u5f37\u7684\u9031\u671f\u6027\u8da8\u52e2\u3002\u5728\u9ad8\u4e2d\u5316\u5b78\u5be6\u9a57\u4e2d\uff0c\u9236\u6700\u4ee4\u4eba\u5370\u8c61\u6df1\u523b\u7684\u7279\u5fb5\u662f\u5176\u706b\u7130\u53cd\u61c9\u5448\u73fe\u6975\u5177\u8fa8\u8b58\u5ea6\u7684\u300c\u6df1\u7d05\u8272\u300d\u6216\u300c\u6d0b\u7d05\u8272\u300d\u3002\u6b64\u5916\uff0c\u9236\u5316\u5408\u7269\u7684\u6eb6\u89e3\u5ea6\u898f\u5f8b\u4ea6\u662f\u6c89\u6fb1\u5206\u6790\u7684\u91cd\u9ede\uff1a\u8207\u9223\u76f8\u4f3c\uff0c\u5176\u786b\u9178\u9e7d\x28\x53\x72\x53\x4f\u2084\x29\u6975\u96e3\u6eb6\u65bc\u6c34\uff0c\u800c\u5176\u6c2b\u6c27\u5316\u7269\x28\x53\x72\x28\x4f\x48\x29\u2082\x29\u7684\u9e7c\u6027\u8207\u6eb6\u89e3\u5ea6\u5247\u96a8\u6eab\u5ea6\u5347\u9ad8\u800c\u589e\u52a0\u3002\x0a\x0a\u73fe\u4ee3\u79d1\u6280\u4e2d\uff0c\u9236\u7684\u61c9\u7528\u8de8\u8d8a\u4e86\u7cbe\u5bc6\u5149\u5b78\u8207\u80fd\u6e90\u91ab\u5b78\u3002\u9236\u9178\u92c7\x28\x53\x72\x54\x69\x4f\u2083\x29\u5177\u6709\u6975\u9ad8\u7684\u6298\u5c04\u7387\u8207\u4ecb\u96fb\u5e38\u6578\uff0c\u662f\u88fd\u9020\u8d85\u5c0e\u8584\u819c\u8207\u9676\u74f7\u96fb\u5bb9\u5668\u7684\u95dc\u9375\u9435\u96fb\u6750\u6599\u3002\u5728\u91ab\u5b78\u61c9\u7528\u4e0a\uff0c\u7a69\u5b9a\u540c\u4f4d\u7d20\u9236\x28\u5982\u9236\x2d\x38\x38\x29\u56e0\u5176\u5316\u5b78\u6027\u8cea\u8207\u9223\u76f8\u4f3c\uff0c\u80fd\u88ab\u9aa8\u9abc\u5438\u6536\uff0c\u5e38\u7528\u65bc\u7de9\u89e3\u9aa8\u75db\uff1b\u7136\u800c\uff0c\u6838\u5206\u88c2\u526f\u7522\u7269\u9236\x2d\x39\x30\x28\u2079\u2070\x53\x72\x29\u5247\u56e0\u5177\u5099\u653e\u5c04\u6027\u4e14\u534a\u8870\u671f\u9577\uff0c\u4e00\u65e6\u9032\u5165\u98df\u7269\u93c8\u4e26\u7a4d\u805a\u65bc\u9aa8\u9abc\u4e2d\uff0c\u6703\u5c0d\u4eba\u9ad4\u7522\u751f\u9577\u671f\u8f3b\u5c04\u5371\u5bb3\u3002\u6b64\u5916\uff0c\u6c2f\u5316\u9236\x28\x53\x72\x43\x6c\u2082\x29\u5e38\u6dfb\u52a0\u65bc\u6297\u654f\u611f\u7259\u9f52\u4e2d\uff0c\u5229\u7528\u5176\u8207\u7259\u5be6\u8cea\u53cd\u61c9\u5f62\u6210\u6c89\u6fb1\uff0c\u5c01\u5835\u7259\u5c0f\u7ba1\u4ee5\u7de9\u89e3\u654f\u611f\u4e0d\u9069\u3002\x0a\x0a\u9236\u5728\u6975\u9650\u8a08\u91cf\u5b78\u4e2d\u5c55\u73fe\u4e86\u4ee4\u4eba\u9a5a\u5606\u7684\u7269\u7406\u7279\u6027\u3002\u76ee\u524d\u4e16\u754c\u4e0a\u6700\u7cbe\u78ba\u7684\u6642\u9593\u6e2c\u91cf\u5de5\u5177\u4e4b\u4e00\u5373\u70ba\u300c\u9236\u539f\u5b50\u6676\u683c\u9418\u300d\x28\x53\x74\x72\x6f\x6e\x74\x69\x75\x6d\x20\x6c\x61\x74\x74\x69\x63\x65\x20\x63\x6c\x6f\x63\x6b\x29\uff0c\u5229\u7528\u9236\u539f\u5b50\u5728\u7279\u5b9a\u983b\u7387\u4e0b\u7684\u80fd\u7d1a\u8e8d\u9077\uff0c\u5176\u7a69\u5b9a\u5ea6\u9060\u8d85\u50b3\u7d71\u7684\u92ab\u539f\u5b50\u9418\uff0c\u6578\u5341\u5104\u5e74\u7684\u8aa4\u5dee\u50c5\u70ba\u4e00\u79d2\uff0c\u6210\u70ba\u65b0\u4e00\u4ee3\u570b\u969b\u79d2\u5b9a\u7fa9\u7684\u6f5b\u529b\u57fa\u6e96\u3002\u6709\u8da3\u7684\u662f\uff0c\u96d6\u7136\u7d14\u9236\u91d1\u5c6c\u8868\u9762\u6703\u8fc5\u901f\u6c27\u5316\u5448\u73fe\u9ec3\u8272\uff0c\u4f46\u5176\u5167\u5c64\u5247\u662f\u9280\u767d\u8272\u5149\u6fa4\u3002\u9019\u7a2e\u5f9e\u7480\u74a8\u7159\u706b\u7684\u6210\u8272\u5291\u5230\u652f\u6490\u6df1\u7a7a\u5c0e\u822a\u7684\u9ad8\u7cbe\u5ea6\u8a08\u6642\uff0c\u5c55\u73fe\u4e86\u9236\u5728\u5316\u5b78\u7a69\u5b9a\u6027\u8207\u7269\u7406\u7cbe\u5bc6\u61c9\u7528\u9593\u7684\u7368\u7279\u5f35\u529b\u3002",
  "\x59":
    "\u91d4\x28\x59\x74\x74\x72\x69\x75\x6d\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x59\uff0c\u539f\u5b50\u5e8f\x20\x33\x39\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u4e94\u9031\u671f\u3001\u7b2c\x20\x33\x20\u65cf\x28\u7b2c\u4e00\u904e\u6e21\u5143\u7d20\u7cfb\u5217\uff0c\x64\x20\u5340\u584a\x29\u3002\x31\x37\x39\x34\x20\u5e74\u7531\u82ac\u862d\u5316\u5b78\u5bb6\u52a0\u591a\u6797\x28\x4a\x6f\x68\x61\x6e\x20\x47\x61\x64\x6f\x6c\x69\x6e\x29\u5f9e\u745e\u5178\u4f0a\u7279\u6bd4\x28\x59\x74\x74\x65\x72\x62\x79\x29\u5c0f\u93ae\u7684\u7926\u77f3\u4e2d\u767c\u73fe\uff0c\u8a72\u5c0f\u93ae\u96a8\u5f8c\u8a95\u751f\u4e86\u56db\u500b\u5143\u7d20\u7684\u540d\u7a31\u3002\u96d6\u7136\u91d4\u5728\u9031\u671f\u8868\u4e2d\u4f4d\u65bc\u9227\u4e0b\u65b9\uff0c\u4e14\u5728\u7269\u7406\u6027\u8cea\u4e0a\u8207\u946d\u7cfb\u5143\u7d20\u6975\u5176\u76f8\u4f3c\uff0c\u56e0\u800c\u5e38\u88ab\u6b78\u985e\u70ba\u300c\u7a00\u571f\u5143\u7d20\u300d\u3002\u5b83\u662f\u7b2c\u4e00\u500b\u88ab\u767c\u73fe\u7684\u7a00\u571f\u5143\u7d20\uff0c\u5176\u55ae\u8cea\u5448\u9280\u767d\u8272\u4e14\u5177\u5099\u91d1\u5c6c\u5149\u6fa4\uff0c\u4e3b\u8981\u5b58\u5728\u65bc\u78f7\u91d4\u7926\u8207\u9ed1\u7a00\u91d1\u7926\u4e2d\u3002\x0a\x0a\u91d4\u7684\u96fb\u5b50\u7d44\u614b\u70ba\x20\x5b\x4b\x72\x5d\x34\x64\u00b9\x35\x73\u00b2\uff0c\u5728\u5316\u5408\u7269\u4e2d\u5e7e\u4e4e\u50c5\u5c55\u73fe\x20\x2b\x33\x20\u6c27\u5316\u614b\u3002\u7531\u65bc\u91d4\u7684\u96e2\u5b50\u534a\u5f91\u8207\u91cd\u946d\u7cfb\u5143\u7d20\u76f8\u8fd1\uff0c\u5176\u5316\u5b78\u884c\u70ba\u8207\u946d\u3001\u9227\u9ad8\u5ea6\u4e00\u81f4\uff0c\u5c55\u73fe\u51fa\u9ad8\u5ea6\u7684\u5316\u5b78\u7a69\u5b9a\u6027\u3002\u91d4\u7684\u6c27\u5316\u7269\x28\x59\u2082\x4f\u2083\x29\u5448\u73fe\u767d\u8272\uff0c\u5177\u5099\u9ad8\u7194\u9ede\u8207\u4f4e\u71b1\u81a8\u8139\u4fc2\u6578\u3002\u5728\u9ad8\u4e2d\u5316\u5b78\u63a2\u8a0e\u932f\u5408\u7269\u8207\u6c27\u5316\u7269\u6027\u8cea\u6642\uff0c\u91d4\u53ef\u8996\u70ba\u904e\u6e21\u91d1\u5c6c\u5340\u584a\u4e2d\uff0c\u6027\u8cea\u76f8\u5c0d\u55ae\u4e00\u4e14\u898f\u5f8b\u7684\u4ee3\u8868\uff0c\u5176\u6c2b\u6c27\u5316\u7269\u4e0d\u5177\u5099\u5169\u6027\uff0c\u9019\u8207\u9031\u671f\u8868\u5de6\u5074\u7684\u9239\u3001\u92c1\u5f62\u6210\u5c0d\u6bd4\u3002\x0a\x0a\u91d4\u5728\u8d85\u5c0e\u6280\u8853\u8207\u5149\u96fb\u5de5\u7a0b\u4e2d\u5177\u6709\u9769\u547d\u6027\u7684\u5730\u4f4d\u3002\x31\x39\x38\x37\x20\u5e74\u6731\u7d93\u6b66\u7b49\u79d1\u5b78\u5bb6\u767c\u73fe\u7684\u300c\u91d4\u92c7\u9285\u6c27\u300d\x28\x59\x42\x43\x4f\x29\uff0c\u662f\u4eba\u985e\u6b77\u53f2\u4e0a\u7b2c\u4e00\u500b\u81e8\u754c\u6eab\u5ea6\u9ad8\u65bc\u6db2\u6c2e\u6cb8\u9ede\x28\x37\x37\x20\x4b\x29\u7684\u9ad8\u6eab\u8d85\u5c0e\u9ad4\uff0c\u9019\u4f7f\u5f97\u8d85\u5c0e\u73fe\u8c61\u7684\u5be6\u969b\u61c9\u7528\u6210\u672c\u5927\u5e45\u4e0b\u964d\u3002\u6b64\u5916\uff0c\u91d4\u92c1\u77f3\u69b4\u77f3\x28\x59\x41\x47\x29\u662f\u88fd\u9020\u96f7\u5c04\u5668\u7684\u6838\u5fc3\u6676\u9ad4\uff0c\u7279\u5225\u662f\u647b\u91f9\u91d4\u92c1\u77f3\u69b4\u77f3\x28\x4e\x64\x3a\x59\x41\x47\x29\u96f7\u5c04\uff0c\u5ee3\u6cdb\u61c9\u7528\u65bc\u91ab\u7642\u624b\u8853\u3001\u5de5\u696d\u5207\u5272\u8207\u8ecd\u4e8b\u6e2c\u8ddd\u3002\u5728\u986f\u793a\u79d1\u6280\u4e2d\uff0c\u91d4\u5316\u5408\u7269\u9577\u671f\u88ab\u7528\u4f5c\u986f\u50cf\u7ba1\u8207\x20\x4c\x45\x44\x20\u7684\u7d05\u8272\u87a2\u5149\u7c89\u57fa\u8cea\uff0c\u78ba\u4fdd\u4e86\u9ad8\u54c1\u8cea\u7684\u8272\u5f69\u9084\u539f\u3002\x0a\x0a\u95dc\u65bc\u91d4\u7684\u7269\u7406\u7279\u6027\uff0c\u5b83\u5c55\u73fe\u51fa\u5353\u8d8a\u7684\u5408\u91d1\u5f37\u5316\u80fd\u529b\u3002\u5728\u9382\u5408\u91d1\u6216\u92c1\u5408\u91d1\u4e2d\u52a0\u5165\u5fae\u91cf\u91d4\uff0c\u80fd\u986f\u8457\u63d0\u5347\u5728\u9ad8\u6eab\u4e0b\u7684\u6a5f\u68b0\u5f37\u5ea6\u8207\u6297\u6c27\u5316\u6027\u80fd\uff0c\u4f7f\u5176\u6210\u70ba\u5674\u5c04\u767c\u52d5\u6a5f\u8207\u6838\u53cd\u61c9\u7210\u7d50\u69cb\u4ef6\u7684\u7406\u60f3\u9078\u64c7\u3002\u6709\u8da3\u7684\u662f\uff0c\u91d4\u5c0d\u6c27\u5177\u6709\u6975\u5f37\u7684\u89aa\u548c\u529b\uff0c\u5176\u6c27\u5316\u7269\u5c64\u7dfb\u5bc6\u4e14\u7a69\u5b9a\uff0c\u9019\u4f7f\u5f97\u91d4\u53ca\u5176\u5408\u91d1\u5728\u6975\u7aef\u9ad8\u71b1\u74b0\u5883\u4e2d\u4ecd\u80fd\u4fdd\u6301\u7d50\u69cb\u5b8c\u6574\u3002\u9019\u7a2e\u5f9e\u5f15\u767c\u8d85\u5c0e\u9769\u547d\u7684\u8907\u96dc\u6c27\u5316\u7269\uff0c\u5230\u5f37\u5316\u73fe\u4ee3\u822a\u592a\u5668\u6750\u7684\u5fae\u91cf\u6dfb\u52a0\u5291\uff0c\u4f7f\u91d4\u6210\u70ba\u9023\u7d50\u56fa\u614b\u7269\u7406\u8207\u6750\u6599\u5de5\u7a0b\u7684\u95dc\u9375\u7d10\u5e36\u3002",
  "\x5a\x72":
    "\u92ef\x28\x5a\x69\x72\x63\x6f\x6e\x69\x75\x6d\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x5a\x72\uff0c\u539f\u5b50\u5e8f\x20\x34\x30\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u4e94\u9031\u671f\u3001\u7b2c\x20\x34\x20\u65cf\x28\x64\x20\u5340\u584a\x29\u3002\u5176\u540d\u7a31\u6e90\u65bc\u7926\u7269\u300c\u92ef\u77f3\u300d\x28\x5a\x69\x72\x63\x6f\x6e\x29\uff0c\u8a9e\u6e90\u81ea\u6ce2\u65af\u8a9e\x20\x7a\x61\x72\x67\x75\x6e\uff0c\u610f\u70ba\u300c\u5982\u91d1\u5b50\u822c\u7684\u984f\u8272\u300d\u3002\x31\x37\x38\x39\x20\u5e74\u7531\u5fb7\u570b\u5316\u5b78\u5bb6\u514b\u62c9\u666e\u7f85\u7279\x28\x4d\x61\x72\x74\x69\x6e\x20\x48\x65\x69\x6e\x72\x69\x63\x68\x20\x4b\x6c\x61\x70\x72\x6f\x74\x68\x29\u5728\u5206\u6790\u92ef\u77f3\u6642\u5206\u96e2\u51fa\u5176\u6c27\u5316\u7269\uff0c\u4e26\u65bc\x20\x31\x38\x32\x34\x20\u5e74\u7531\u8c9d\u9f4a\u91cc\u70cf\u65af\x28\x4a\u00f6\x6e\x73\x20\x4a\x61\x63\x6f\x62\x20\x42\x65\x72\x7a\x65\x6c\x69\x75\x73\x29\u88fd\u5f97\u4e0d\u7d14\u7684\u91d1\u5c6c\u3002\u92ef\u5728\u5730\u6bbc\u4e2d\u5206\u5e03\u5ee3\u6cdb\uff0c\u4ee5\u5176\u5353\u8d8a\u7684\u8010\u8150\u8755\u6027\u8207\u6297\u9ad8\u6eab\u80fd\u529b\uff0c\u5728\u6838\u5de5\u7a0b\u8207\u5316\u5b78\u8a2d\u5099\u9818\u57df\u626e\u6f14\u8457\u4fdd\u96aa\u7d72\u822c\u7684\u95dc\u9375\u89d2\u8272\u3002\x0a\x0a\u92ef\u7684\u96fb\u5b50\u7d44\u614b\u70ba\x20\x5b\x4b\x72\x5d\x34\x64\u00b2\x35\x73\u00b2\uff0c\u6700\u7a69\u5b9a\u7684\u6c27\u5316\u614b\u70ba\x20\x2b\x34\u3002\u8207\u540c\u65cf\u7684\u9226\u76f8\u4f3c\uff0c\u92ef\u5177\u6709\u512a\u7570\u7684\u300c\u920d\u5316\u73fe\u8c61\u300d\x28\x50\x61\x73\x73\x69\x76\x61\x74\x69\x6f\x6e\x29\uff0c\u5728\u5927\u6c23\u4e2d\u6703\u8fc5\u901f\u5f62\u6210\u4e00\u5c64\u6975\u5176\u7a69\u5b9a\u4e14\u7d30\u5bc6\u7684\u6c27\u5316\u819c\x28\x5a\x72\x4f\u2082\x29\uff0c\u9019\u4f7f\u5f97\u92ef\u5728\u5f37\u9178\u3001\u5f37\u9e7c\u751a\u81f3\u8150\u8755\u6027\u6975\u5f37\u7684\u7194\u878d\u9e7d\u4e2d\u4ecd\u80fd\u4fdd\u6301\u7a69\u5b9a\u3002\u92ef\u8207\u540c\u65cf\u7684\u927f\x28\x48\x66\x29\u6027\u8cea\u6975\u5176\u76f8\u4f3c\x28\u539f\u5b50\u534a\u5f91\u76f8\u8fd1\x29\uff0c\u9019\u5c0e\u81f4\u5169\u8005\u5728\u81ea\u7136\u754c\u4e2d\u59cb\u7d42\u5171\u751f\u4e14\u6975\u96e3\u5206\u96e2\u3002\u5728\u9ad8\u4e2d\u5316\u5b78\u63a2\u8a0e\u91d1\u5c6c\u53cd\u61c9\u6027\u6642\uff0c\u92ef\u5c55\u73fe\u4e86\u9ad8\u5316\u5b78\u6d3b\u6027\u8207\u5b8f\u89c0\u5316\u5b78\u7a69\u5b9a\u6027\u7684\u77db\u76fe\u7d71\u4e00\uff1a\u96d6\u7136\u5176\u6a19\u6e96\u6c27\u5316\u96fb\u4f4d\u8f03\u9ad8\x28\x45\u2070\x20\u2248\x20\x31\x2e\x34\x35\x20\x56\x29\uff0c\u4f46\u56e0\u920d\u5316\u819c\u4fdd\u8b77\uff0c\u5176\u5b8f\u89c0\u6297\u8755\u529b\u9060\u8d85\u8a31\u591a\u8cb4\u91d1\u5c6c\u3002\x0a\x0a\u5728\u73fe\u4ee3\u61c9\u7528\u4e2d\uff0c\u92ef\u662f\u6838\u80fd\u767c\u96fb\u4e0d\u53ef\u6216\u7f3a\u7684\u652f\u67f1\u3002\u92ef\u5408\u91d1\x28\x5a\x69\x72\x63\x61\x6c\x6f\x79\x29\u5177\u6709\u6975\u4f4e\u7684\u4e2d\u5b50\u5438\u6536\u622a\u9762\x28\x4e\x65\x75\x74\x72\x6f\x6e\x20\x63\x61\x70\x74\x75\x72\x65\x20\x63\x72\x6f\x73\x73\x2d\x73\x65\x63\x74\x69\x6f\x6e\x29\u8207\u5353\u8d8a\u7684\u9ad8\u6eab\u9ad8\u58d3\u8010\u53d7\u6027\uff0c\u88ab\u7528\u4f5c\u6838\u5b50\u71c3\u6599\u68d2\u7684\u5305\u8986\u6750\u6599\u3002\u5728\u6750\u6599\u79d1\u5b78\u4e2d\uff0c\u4e8c\u6c27\u5316\u92ef\x28\x5a\x72\x4f\u2082\x29\u7684\u71b1\u7a69\u5b9a\u6027\u6975\u4f73\uff0c\u5e38\u88ab\u88fd\u6210\u8010\u706b\u78da\u8207\u5769\u581d\uff1b\u6b64\u5916\uff0c\u900f\u904e\u6dfb\u52a0\u91d4\u7a69\u5b9a\u5316\u7684\u300c\u6c27\u5316\u92ef\u9676\u74f7\u300d\u5177\u5099\u8207\u92fc\u76f8\u4eff\u7684\u9ad8\u5f37\u5ea6\u8207\u97cc\u6027\u3002\u5c0d\u65bc\u5927\u773e\u800c\u8a00\uff0c\u6700\u719f\u6089\u7684\u83ab\u904e\u65bc\u300c\u7acb\u65b9\u6c27\u5316\u92ef\u300d\x28\x43\x75\x62\x69\x63\x20\x5a\x69\x72\x63\x6f\x6e\x69\x61\x29\uff0c\u5176\u9ad8\u6298\u5c04\u7387\u8207\u786c\u5ea6\u4f7f\u5176\u6210\u70ba\u947d\u77f3\u7684\u6700\u4f73\u4ee3\u7528\u54c1\u3002\x0a\x0a\u92ef\u5c55\u73fe\u4e86\u67d0\u4e9b\u53cd\u76f4\u89ba\u7684\u7269\u7406\u5316\u5b78\u7279\u5fb5\u3002\u5118\u7ba1\u92ef\u584a\u9ad4\u5177\u5099\u9a5a\u4eba\u7684\u7a69\u5b9a\u6027\uff0c\u4f46\u92ef\u7684\u7d30\u788e\u7c89\u672b\u6216\u5228\u5c51\u537b\u6975\u6613\u81ea\u71c3\x28\x50\x79\x72\x6f\x70\x68\x6f\x72\x69\x63\x29\uff0c\u8207\u7a7a\u6c23\u63a5\u89f8\u6642\u80fd\u7522\u751f\u767d\u71b1\u5316\u7684\u706b\u7130\u3002\u6b64\u5916\uff0c\u92ef\u5c0d\u6c27\u3001\u6c2e\u3001\u6c2b\u6c23\u5177\u6709\u6975\u5f37\u7684\u5438\u6536\u80fd\u529b\uff0c\u9019\u4f7f\u5176\u5728\u96fb\u5b50\u7ba1\u88fd\u7a0b\u4e2d\u88ab\u7528\u4f5c\u300c\u53bb\u6c23\u5291\u300d\x28\x47\x65\x74\x74\x65\x72\x29\u4ee5\u7dad\u6301\u9ad8\u5ea6\u771f\u7a7a\u3002\u6709\u8da3\u7684\u662f\uff0c\u92ef\u7684\u6c27\u5316\u7269\u5728\u7279\u5b9a\u58d3\u529b\u8207\u6eab\u5ea6\u4e0b\u80fd\u7522\u751f\u76f8\u8b8a\uff0c\u900f\u904e\u63a7\u5236\u6676\u9ad4\u7d50\u69cb\u8f49\u5316\uff0c\u79d1\u5b78\u5bb6\u7814\u767c\u51fa\u5177\u5099\u300c\u81ea\u6211\u4fee\u5fa9\u300d\u6f5b\u529b\u7684\u9676\u74f7\u6750\u6599\u3002\u9019\u7a2e\u7531\u5b88\u8b77\u6838\u53cd\u61c9\u7210\u6838\u5fc3\u7684\u51b7\u5cfb\uff0c\u5230\u65e5\u5e38\u73e0\u5bf6\u5149\u8292\u7684\u83ef\u9e97\uff0c\u7cbe\u78ba\u9ad4\u73fe\u4e86\u92ef\u5728\u6975\u7aef\u79d1\u6280\u8207\u6c11\u751f\u61c9\u7528\u9593\u7684\u5ee3\u6cdb\u8de8\u5ea6\u3002",
  "\x4e\x62":
    "\u922e\x28\x4e\x69\x6f\x62\x69\x75\x6d\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x4e\x62\uff0c\u539f\u5b50\u5e8f\x20\x34\x31\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u4e94\u9031\u671f\u3001\u7b2c\x20\x35\x20\u65cf\x28\x64\x20\u5340\u584a\x29\u3002\u5176\u540d\u7a31\u6e90\u65bc\u5e0c\u81d8\u795e\u8a71\u4e2d\u5766\u5854\u6d1b\u65af\x28\x54\x61\x6e\x74\x61\x6c\x75\x73\x29\u7684\u5973\u5152\u5c3c\u4fc4\u4f2f\x28\x4e\x69\x6f\x62\x65\x29\uff0c\u4ee5\u6b64\u6697\u793a\u922e\u8207\u7b2c\x20\x36\x20\u9031\u671f\u7684\u926d\x28\x54\x61\x29\u5728\u6027\u8cea\u4e0a\u6975\u5176\u76f8\u4f3c\u4e14\u96e3\u4ee5\u5206\u96e2\u3002\x31\x38\x30\x31\x20\u5e74\u7531\u82f1\u570b\u5316\u5b78\u5bb6\u54c8\u5207\u7279\x28\x43\x68\x61\x72\x6c\x65\x73\x20\x48\x61\x74\x63\x68\x65\x74\x74\x29\u5728\u5206\u6790\u7926\u77f3\u6642\u767c\u73fe\uff0c\u4e26\u56e0\u5176\u4f86\u6e90\u800c\u66fe\u88ab\u547d\u540d\u70ba\u300c\x43\x6f\x6c\x75\x6d\x62\x69\x75\x6d\u300d\u3002\u922e\u5728\u81ea\u7136\u754c\u4e3b\u8981\u5b58\u5728\u65bc\u922e\u9435\u7926\u4e2d\uff0c\u662f\u7576\u4ee3\u9ad8\u5f37\u5ea6\u92fc\u6750\u8207\u8d85\u5c0e\u6280\u8853\u7684\u6838\u5fc3\u91d1\u5c6c\u3002\x0a\x0a\u5728\u96fb\u5b50\u7d44\u614b\u4e0a\uff0c\u922e\u5448\u73fe\u7570\u5e38\u7684\x20\x5b\x4b\x72\x5d\x34\x64\u2074\x35\x73\u00b9\x20\u6392\u5e03\uff0c\u50be\u5411\u65bc\u5728\x20\x34\x64\x20\u8207\x20\x35\x73\x20\u8ecc\u57df\u9593\u9054\u6210\u80fd\u91cf\u5e73\u8861\uff0c\u6700\u7a69\u5b9a\u7684\u6c27\u5316\u614b\u70ba\x20\x2b\x35\u3002\u7531\u65bc\u922e\u8207\u926d\u53d7\u5230\u300c\u946d\u7cfb\u6536\u7e2e\u300d\u6548\u61c9\u7684\u9593\u63a5\u5f71\u97ff\x28\u926d\u7684\u534a\u5f91\u7e2e\u5c0f\x29\uff0c\u5169\u8005\u7684\u539f\u5b50\u534a\u5f91\u8207\u5316\u5b78\u884c\u70ba\u6975\u5176\u76f8\u8fd1\uff0c\u7686\u5177\u5099\u5353\u8d8a\u7684\u6297\u9178\u8755\u80fd\u529b\u8207\u9ad8\u7194\u9ede\u7279\u5fb5\u3002\u922e\u5728\u5e38\u6eab\u4e0b\u8868\u9762\u6703\u751f\u6210\u7dfb\u5bc6\u7684\u6c27\u5316\u819c\uff0c\u9019\u4f7f\u5176\u5728\u751f\u7406\u74b0\u5883\u4e2d\u8868\u73fe\u51fa\u512a\u7570\u7684\u751f\u7269\u76f8\u5bb9\u6027\uff0c\u4ea6\u662f\u9ad8\u4e2d\u5316\u5b78\u5728\u7406\u89e3\u904e\u6e21\u5143\u7d20\u5316\u5b78\u6027\u8cea\u8207\u534a\u5c0e\u9ad4\u6c27\u5316\u819c\u5e72\u6d89\u73fe\u8c61\u6642\u7684\u7d55\u4f73\u6848\u4f8b\u3002\x0a\x0a\u5728\u73fe\u4ee3\u61c9\u7528\u4e2d\uff0c\u922e\u662f\u300c\u9ad8\u5f37\u5ea6\u4f4e\u5408\u91d1\u92fc\u300d\x28\x48\x53\x4c\x41\x29\u7684\u95dc\u9375\u5fae\u91cf\u6dfb\u52a0\u5291\uff0c\u50c5\u9700\u52a0\u5165\u842c\u5206\u4e4b\u5e7e\u7684\u922e\uff0c\u5373\u53ef\u7d30\u5316\u92fc\u6750\u6676\u7c92\uff0c\u986f\u8457\u63d0\u5347\u6a4b\u6a11\u3001\u8f38\u96fb\u5854\u8207\u6cb9\u6c23\u7ba1\u7dda\u7684\u6297\u9707\u8207\u710a\u63a5\u6027\u80fd\u3002\u5728\u96fb\u5b78\u8207\u7cbe\u5bc6\u91ab\u7642\u9818\u57df\uff0c\u922e\u9226\x28\x4e\x62\x2d\x54\x69\x29\u8207\u922e\u4e09\u932b\x28\x4e\x62\u2083\x53\x6e\x29\u5408\u91d1\u662f\u88fd\u9020\u8d85\u5c0e\u78c1\u9435\u7684\u6838\u5fc3\u6750\u6599\uff0c\u5ee3\u6cdb\u61c9\u7528\u65bc\u6838\u78c1\u5171\u632f\u6210\u50cf\x28\x4d\x52\x49\x29\u8207\u5927\u578b\u7c92\u5b50\u5c0d\u649e\u6a5f\u3002\u6b64\u5916\uff0c\u922e\u5728\u96fb\u5b50\u696d\u4e2d\u88ab\u7528\u65bc\u88fd\u9020\u9ad8\u6027\u80fd\u9676\u74f7\u96fb\u5bb9\u5668\uff0c\u4e26\u5728\u822a\u592a\u5de5\u7a0b\u4e2d\u4f5c\u70ba\u5674\u5c04\u767c\u52d5\u6a5f\u5674\u5634\u7684\u8010\u9ad8\u6eab\u5857\u5c64\u3002\x0a\x0a\u922e\u5728\u5149\u5b78\u8207\u7269\u7406\u7279\u6027\u4e0a\u5c55\u73fe\u51fa\u8ff7\u4eba\u7684\u73fe\u8c61\u3002\u900f\u904e\u96fb\u89e3\u967d\u6975\u8655\u7406\uff0c\u922e\u8868\u9762\u751f\u6210\u7684\u6c27\u5316\u5c64\u539a\u5ea6\u53ef\u96a8\u96fb\u58d3\u7cbe\u78ba\u8abf\u6574\uff0c\u9032\u800c\u7522\u751f\u5982\u5f69\u8679\u822c\u7684\u8584\u819c\u5e72\u6d89\u8272\u5f69\uff0c\u9019\u4f7f\u5176\u5728\u9ad8\u7d1a\u9996\u98fe\u8207\u7d00\u5ff5\u5e63\u8a2d\u8a08\u4e2d\u7368\u6a39\u4e00\u683c\u3002\u6709\u8da3\u7684\u662f\uff0c\u96d6\u7136\u922e\u7684\u5316\u5b78\u53cd\u61c9\u6027\u96a8\u6eab\u5ea6\u5347\u9ad8\u800c\u5287\u589e\uff0c\u4f46\u5176\u4f4e\u4e2d\u5b50\u5438\u6536\u622a\u9762\u4f7f\u5176\u5728\u6838\u53cd\u61c9\u7210\u7d50\u69cb\u6750\u6599\u4e2d\u5360\u6709\u4e00\u5e2d\u4e4b\u5730\u3002\u9019\u7a2e\u5f9e\u9a45\u52d5\u5fae\u89c0\u8d85\u5c0e\u96fb\u6d41\u5230\u652f\u6490\u5b8f\u89c0\u92fc\u9435\u57fa\u5efa\u7684\u7279\u6027\uff0c\u7cbe\u78ba\u8a6e\u91cb\u4e86\u922e\u5728\u904e\u6e21\u91d1\u5c6c\u4e2d\u7a69\u5b9a\u8207\u5c16\u7aef\u517c\u5177\u7684\u5b9a\u4f4d\u3002",
  "\x4d\x6f":
    "\u926c\x28\x4d\x6f\x6c\x79\x62\x64\x65\x6e\x75\x6d\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x4d\x6f\uff0c\u539f\u5b50\u5e8f\x20\x34\x32\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u4e94\u9031\u671f\u3001\u7b2c\x20\x36\x20\u65cf\x28\x64\x20\u5340\u584a\x29\u3002\u5176\u540d\u7a31\u6e90\u65bc\u5e0c\u81d8\u8a9e\u300c\x6d\x6f\x6c\x79\x62\x64\x6f\x73\u300d\uff0c\u610f\u6307\u300c\u925b\u300d\uff0c\u56e0\u5176\u7926\u77f3\u8f1d\u926c\u7926\x28\x4d\x6f\x53\u2082\x29\u7684\u5916\u89c0\u8207\u77f3\u58a8\u3001\u925b\u7926\u6975\u5176\u76f8\u4f3c\u3002\x31\x37\x37\x38\x20\u5e74\u7531\u745e\u5178\u5316\u5b78\u5bb6\u820d\u52d2\x28\x43\x61\x72\x6c\x20\x57\x69\x6c\x68\x65\x6c\x6d\x20\x53\x63\x68\x65\x65\x6c\x65\x29\u8fa8\u8b58\u51fa\u5176\u4e0d\u540c\u65bc\u925b\u8207\u77f3\u58a8\u7684\u7279\u6027\uff0c\u96a8\u5f8c\u7531\u8036\u723e\u59c6\x28\x50\x65\x74\x65\x72\x20\x4a\x61\x63\x6f\x62\x20\x48\x6a\x65\x6c\x6d\x29\u65bc\x20\x31\x37\x38\x31\x20\u5e74\u88fd\u5f97\u7d14\u91d1\u5c6c\u3002\u926c\u662f\u5730\u6bbc\u4e2d\u91cd\u8981\u7684\u96e3\u7194\u91d1\u5c6c\uff0c\u7194\u9ede\u9ad8\u9054\x20\x32\x36\x32\x33\x20\u00b0\x43\uff0c\u662f\u652f\u6490\u73fe\u4ee3\u9ad8\u6eab\u5de5\u696d\u8207\u751f\u7269\u56fa\u6c2e\u4f5c\u7528\u7684\u6838\u5fc3\u5143\u7d20\u3002\x0a\x0a\u926c\u7684\u96fb\u5b50\u7d44\u614b\u70ba\x20\x5b\x4b\x72\x5d\x34\x64\u2075\x35\x73\u00b9\uff0c\u5177\u5099\u534a\u586b\u6eff\u7684\x20\x64\x20\u8207\x20\x73\x20\u8ecc\u57df\uff0c\u9019\u7a2e\u9ad8\u5ea6\u5c0d\u7a31\u6027\u4f7f\u5176\u5177\u6709\u7a69\u5b9a\u7684\u96fb\u5b50\u6392\u5e03\uff0c\u6c27\u5316\u614b\u53ef\u7531\x20\x2d\x32\x20\u5206\u5e03\u81f3\x20\x2b\x36\u3002\u926c\u7684\u539f\u5b50\u534a\u5f91\u8f03\u5927\uff0c\u4f7f\u5176\u5728\u5408\u91d1\u4e2d\u80fd\u6709\u6548\u963b\u6b62\u91d1\u5c6c\u539f\u5b50\u9593\u7684\u6ed1\u79fb\u3002\u5728\u9ad8\u4e2d\u5316\u5b78\u63a2\u8a0e\u751f\u7269\u50ac\u5316\u5291\u6642\uff0c\u926c\u662f\u6975\u5c11\u6578\u5c0d\u751f\u547d\u5fc5\u9700\u7684\u7b2c\u4e94\u9031\u671f\u91d1\u5c6c\uff1a\u5b83\u662f\u300c\u56fa\u6c2e\u9176\u300d\x28\x4e\x69\x74\x72\x6f\x67\x65\x6e\x61\x73\x65\x29\u7684\u91cd\u8981\u6d3b\u6027\u4e2d\u5fc3\uff0c\u8ca0\u8cac\u5728\u5e38\u6eab\u5e38\u58d3\u4e0b\u5c07\u5927\u6c23\u4e2d\u7684\x20\x4e\u2082\x20\u62c6\u89e3\u4e26\u8f49\u5316\u70ba\u6c28\u3002\u9019\u7a2e\u5728\u6eab\u548c\u689d\u4ef6\u4e0b\u7834\u89e3\u6975\u5f37\u6c2e\u4e09\u9375\u7684\u80fd\u529b\uff0c\u5c55\u73fe\u4e86\u926c\u5353\u8d8a\u7684\u96fb\u5b50\u8f49\u79fb\u8207\u914d\u5408\u4f4d\u5316\u5b78\u7279\u6027\u3002\x0a\x0a\u5728\u53f0\u7063\u9ad8\u4e2d\u8ab2\u7db1\u8207\u5de5\u696d\u61c9\u7528\u8108\u7d61\u4e2d\uff0c\u926c\u5e38\u51fa\u73fe\u5728\u300c\u927b\u926c\u92fc\u300d\u7684\u5f37\u5316\u6982\u5ff5\u88e1\u3002\u926c\u80fd\u986f\u8457\u63d0\u5347\u5408\u91d1\u92fc\u5728\u6975\u7aef\u9ad8\u6eab\u4e0b\u7684\u5f37\u5ea6\u3001\u786c\u5ea6\u8207\u6297\u8150\u8755\u6027\uff0c\u662f\u706b\u529b\u767c\u96fb\u5ee0\u84b8\u6c23\u7ba1\u8def\u3001\u822a\u592a\u767c\u52d5\u6a5f\u96f6\u4ef6\u8207\u8ecd\u4e8b\u88dd\u7532\u7684\u9996\u9078\u3002\u5728\u5316\u5b78\u5de5\u696d\u4e2d\uff0c\u926c\u5316\u5408\u7269\x28\u5982\u926c\u9178\u92a8\x29\u662f\u77f3\u6cb9\u812b\u786b\u88fd\u7a0b\u4e2d\u7684\u95dc\u9375\u89f8\u5a92\uff1b\u800c\u4e8c\u786b\u5316\u926c\x28\x4d\x6f\x53\u2082\x29\u5247\u56e0\u5176\u5c64\u72c0\u6676\u9ad4\u7d50\u69cb\u8207\u77f3\u58a8\u76f8\u4f3c\uff0c\u5177\u5099\u6975\u4f73\u7684\u8010\u9ad8\u6eab\u6f64\u6ed1\u6027\u80fd\uff0c\u5ee3\u6cdb\u61c9\u7528\u65bc\u91cd\u578b\u6a5f\u4ef6\u8207\u822a\u592a\u6f64\u6ed1\u3002\u96fb\u5316\u5b78\u65b9\u9762\uff0c\u926c\u5e38\u88ab\u7528\u4f5c\u8584\u819c\u592a\u967d\u80fd\u96fb\u6c60\u7684\u80cc\u96fb\u6975\u6750\u6599\uff0c\u5c55\u73fe\u5176\u7a69\u5b9a\u7684\u5c0e\u96fb\u8207\u8010\u8755\u80fd\u529b\u3002\x0a\x0a\u926c\u5728\u6750\u6599\u79d1\u5b78\u4e2d\u5c55\u73fe\u4e86\u986f\u8457\u7684\u7269\u7406\u6027\u8cea\u8de8\u5ea6\u3002\u96d6\u7136\u926c\u91d1\u5c6c\u5177\u5099\u6975\u9ad8\u7684\u786c\u5ea6\uff0c\u4f46\u5728\u52a0\u5165\u7279\u5b9a\u6bd4\u4f8b\u7684\u9338\u5f8c\u6703\u5c55\u73fe\u51fa\u6975\u4f73\u7684\u5ef6\u5c55\u6027\u3002\u53cd\u76f4\u89ba\u7684\u662f\uff0c\u926c\u7684\u71b1\u81a8\u8139\u4fc2\u6578\u6975\u4f4e\uff0c\u9019\u4f7f\u5176\u8207\u73bb\u7483\u5177\u6709\u826f\u597d\u7684\u5c01\u63a5\u6027\u80fd\uff0c\u5728\u88fd\u9020\u5927\u529f\u7387\u771f\u7a7a\u7ba1\u8207\u96fb\u5b50\u7ba1\u5ea7\u4e2d\u626e\u6f14\u95dc\u9375\u89d2\u8272\u3002\u6b64\u5916\uff0c\u926c\u5728\u6975\u4f4e\u6eab\u4e0b\u6703\u8868\u73fe\u51fa\u8d85\u5c0e\u6027\u3002\u9019\u7a2e\u5f9e\u5b88\u8b77\u690d\u7269\u751f\u9577\u7684\u56fa\u6c2e\u5947\u8e5f\uff0c\u5230\u652f\u6490\u9ad8\u6eab\u51b6\u91d1\u8207\u7cbe\u5bc6\u96fb\u5b78\u7684\u91cd\u4efb\uff0c\u4f7f\u926c\u6210\u70ba\u904e\u6e21\u91d1\u5c6c\u4e2d\u517c\u5177\u751f\u91ab\u8207\u5de5\u7a0b\u50f9\u503c\u7684\u4ee3\u8868\u6027\u5143\u7d20\u3002",
  "\x54\x63":
    "\u939d\x28\x54\x65\x63\x68\x6e\x65\x74\x69\x75\x6d\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x54\x63\uff0c\u539f\u5b50\u5e8f\x20\x34\x33\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u4e94\u9031\u671f\u3001\u7b2c\x20\x37\x20\u65cf\x28\x64\x20\u5340\u584a\x29\u3002\u5176\u540d\u7a31\u6e90\u65bc\u5e0c\u81d8\u8a9e\u300c\x74\x65\x63\x68\x6e\x65\x74\x6f\x73\u300d\uff0c\u610f\u70ba\u300c\u4eba\u5de5\u88fd\u9020\u300d\uff0c\u662f\u4eba\u985e\u6b77\u53f2\u4e0a\u7b2c\u4e00\u500b\u900f\u904e\u4eba\u5de5\u6838\u53cd\u61c9\u88fd\u5f97\u7684\u5143\u7d20\u3002\x31\x39\x33\x37\x20\u5e74\u7531\u8cfd\u683c\u745e\x28\x45\x6d\x69\x6c\x69\x6f\x20\x53\x65\x67\x72\u00e8\x29\u8207\u4f69\u91cc\u57c3\x28\x43\x61\x72\x6c\x6f\x20\x50\x65\x72\x72\x69\x65\x72\x29\u5728\u8655\u7406\u88ab\u6c18\u6838\u8f5f\u64ca\u904e\u7684\u926c\u7b94\u4e2d\u5206\u96e2\u5f97\u51fa\u3002\u939d\u662f\u9031\u671f\u8868\u4e2d\u6975\u70ba\u7279\u6b8a\u7684\u6210\u54e1\uff1a\u5b83\u662f\u539f\u5b50\u5e8f\u6700\u5c0f\u4e14\u6c92\u6709\u7a69\u5b9a\u540c\u4f4d\u7d20\u7684\u653e\u5c04\u6027\u5143\u7d20\u3002\u5118\u7ba1\u9580\u5f97\u5217\u592b\u66fe\u7cbe\u78ba\u9810\u8a00\u5176\u70ba\u300c\u985e\u9333\u300d\x28\x45\x6b\x61\x2d\x6d\x61\x6e\x67\x61\x6e\x65\x73\x65\x29\uff0c\u4f46\u56e0\u5176\u6975\u4e0d\u7a69\u5b9a\u7684\u6838\u6027\u8cea\uff0c\u5730\u7403\u539f\u751f\u74b0\u5883\u4e2d\u5e7e\u4e4e\u4e0d\u5b58\u5728\u939d\uff0c\u4e3b\u8981\u4f86\u6e90\u70ba\u6838\u53cd\u61c9\u7210\u7684\u88c2\u8b8a\u526f\u7522\u7269\u3002\x0a\x0a\u5728\u5316\u5b78\u7279\u5fb5\u4e0a\uff0c\u939d\u7684\u96fb\u5b50\u7d44\u614b\u70ba\x20\x5b\x4b\x72\x5d\x34\x64\u2075\x35\x73\u00b2\uff0c\u5176\u5316\u5b78\u884c\u70ba\u8207\u540c\u65cf\u7684\u9333\x28\x4d\x6e\x29\u53ca\u9338\x28\x52\x65\x29\u9ad8\u5ea6\u76f8\u4f3c\u3002\u5e38\u898b\u6c27\u5316\u614b\u70ba\x20\x2b\x34\x20\u8207\x20\x2b\x37\uff0c\u5176\u4e2d\u904e\u939d\u9178\u6839\u96e2\u5b50\x28\x54\x63\x4f\u2084\u207b\x29\u8207\u904e\u9333\u9178\u6839\u7d50\u69cb\u76f8\u4f3c\u3002\u7531\u65bc\u6240\u6709\u540c\u4f4d\u7d20\u7686\u5177\u5099\u653e\u5c04\u6027\x28\u4e3b\u8981\u70ba\u939d\x2d\x39\x39\x29\uff0c\u939d\u7684\u5316\u5b78\u7814\u7a76\u5fc5\u9808\u5728\u53d7\u63a7\u74b0\u5883\u4e0b\u9032\u884c\u3002\u6839\u64da\u6838\u7269\u7406\u898f\u5f8b\uff0c\u539f\u5b50\u5e8f\u70ba\u5947\u6578\u7684\u5143\u7d20\x28\u5982\x20\x54\x63\x20\u8207\x20\x50\x6d\x29\u901a\u5e38\u6bd4\u9130\u8fd1\u7684\u5076\u6578\u5143\u7d20\u4e0d\u7a69\u5b9a\uff0c\u9019\u89e3\u91cb\u4e86\u70ba\u4f55\u939d\u5728\u9031\u671f\u8868\u7a69\u5b9a\u7684\u904e\u6e21\u5143\u7d20\u5340\u57df\u4e2d\uff0c\u537b\u7a81\u5140\u5730\u6210\u70ba\u4e00\u5ea7\u300c\u4e0d\u7a69\u5b9a\u7684\u5b64\u5cf6\u300d\u3002\x0a\x0a\u5728\u73fe\u4ee3\u61c9\u7528\u4e2d\uff0c\u939d\u5728\u6838\u5b50\u91ab\u5b78\u5f71\u50cf\u8a3a\u65b7\u4e2d\u5360\u6709\u7d71\u6cbb\u5730\u4f4d\u3002\u4e9e\u7a69\u614b\u540c\u4f4d\u7d20\x20\u2079\u2079\u1d50\x54\x63\x20\u5177\u5099\u6975\u4f73\u7684\u7269\u7406\u7279\u6027\uff1a\u5176\u534a\u8870\u671f\u50c5\u7d04\x20\x36\x20\u5c0f\u6642\uff0c\u4e14\u91cb\u653e\u7684\x20\u03b3\x20\u5c04\u7dda\u80fd\u91cf\u9069\u4e2d\x28\x31\x34\x30\x20\x6b\x65\x56\x29\uff0c\u80fd\u8207\u591a\u7a2e\u751f\u5316\u5206\u5b50\u87af\u5408\u6210\u6a19\u9776\u85e5\u7269\uff0c\u7528\u65bc\u9aa8\u9abc\u3001\u5fc3\u81df\u3001\u7532\u72c0\u817a\u53ca\u816b\u7624\u7684\u7cbe\u78ba\u9020\u5f71\uff0c\u800c\u5c0d\u4eba\u9ad4\u7522\u751f\u7684\u8f3b\u5c04\u5291\u91cf\u6975\u4f4e\u3002\u5728\u5de5\u696d\u9632\u8755\u9818\u57df\uff0c\u904e\u939d\u9178\u9e7d\u8868\u73fe\u51fa\u512a\u65bc\u927b\u9178\u9e7d\u7684\u92fc\u9435\u7de9\u8755\u6027\u80fd\uff0c\u50c5\u9700\u6975\u4f4e\u6fc3\u5ea6\u5373\u53ef\u9632\u6b62\u91d1\u5c6c\u93fd\u8755\uff0c\u4f46\u56e0\u5176\u653e\u5c04\u6027\u9650\u5236\uff0c\u76ee\u524d\u50c5\u7528\u65bc\u5c01\u9589\u5f0f\u7684\u7279\u6b8a\u5faa\u74b0\u7cfb\u7d71\u3002\x0a\x0a\u939d\u5728\u5929\u6587\u7269\u7406\u5b78\u4e2d\u626e\u6f14\u8457\u300c\u6046\u661f\u6f14\u5316\u300d\u7684\u6307\u8def\u6a19\u3002\x31\x39\x35\x32\x20\u5e74\uff0c\u79d1\u5b78\u5bb6\u5728\u67d0\u4e9b\u7d05\u5de8\u661f\x28\u7a31\u70ba\u939d\u661f\x29\u7684\u5149\u8b5c\u4e2d\u89c0\u6e2c\u5230\u939d\u7684\u8b5c\u7dda\uff0c\u7531\u65bc\u5176\u534a\u8870\u671f\u9060\u77ed\u65bc\u661f\u9ad4\u5e74\u9f61\uff0c\u9019\u8b49\u5be6\u4e86\u6046\u661f\u5167\u90e8\u6b63\u6301\u7e8c\u9032\u884c\u8457\u91cd\u6838\u5408\u6210\u904e\u7a0b\x28\x73\x2d\u904e\u7a0b\x29\uff0c\u70ba\u73fe\u4ee3\u5929\u9ad4\u7269\u7406\u5b78\u63d0\u4f9b\u4e86\u5be6\u9a57\u8b49\u64da\u3002\u53cd\u76f4\u89ba\u7684\u662f\uff0c\u5118\u7ba1\u939d\u5728\u5730\u7403\u4e0a\u6975\u5176\u7a00\u5c11\uff0c\u4f46\u5176\u9577\u671f\u5b58\u5728\u7684\u540c\u4f4d\u7d20\x20\u2079\u2079\x54\x63\x20\u662f\u6838\u5ee2\u6599\u9577\u6548\u7ba1\u7406\u4e2d\u5fc5\u9808\u8655\u7406\u7684\u95dc\u9375\u7269\u7a2e\u3002\u9019\u7a2e\u5f9e\u91ab\u9662\u88e1\u7684\u7cbe\u6e96\u8a3a\u65b7\u5230\u661f\u7a7a\u6df1\u8655\u7684\u5143\u7d20\u8a95\u751f\u8b49\u64da\uff0c\u7cbe\u78ba\u8a6e\u91cb\u4e86\u939d\u4f5c\u70ba\u4eba\u5de5\u5143\u7d20\u8207\u5b87\u5b99\u5be6\u9a57\u5ba4\u6a4b\u6a11\u7684\u7368\u7279\u6027\u3002",
  "\x52\x75":
    "\u91d5\x28\x52\x75\x74\x68\x65\x6e\x69\x75\x6d\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x52\x75\uff0c\u539f\u5b50\u5e8f\x20\x34\x34\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u4e94\u9031\u671f\u3001\u7b2c\x20\x38\x20\u65cf\x28\x64\x20\u5340\u584a\x29\uff0c\u5c6c\u65bc\u9251\u65cf\u5143\u7d20\x28\x50\x47\x4d\x29\u3002\x31\x38\x34\x34\x20\u5e74\u7531\u4fc4\u7f85\u65af\u5316\u5b78\u5bb6\u514b\u52de\u65af\x28\x4b\x61\x72\x6c\x20\x45\x72\x6e\x73\x74\x20\x43\x6c\x61\x75\x73\x29\u5f9e\u70cf\u62c9\u5c71\u7684\u9251\u7926\u6b98\u6e23\u4e2d\u767c\u73fe\uff0c\u4e26\u4ee5\u5176\u7956\u570b\u4fc4\u7f85\u65af\u7684\u62c9\u4e01\u8a9e\u540d\u7a31\x20\x52\x75\x74\x68\x65\x6e\x69\x61\x20\u547d\u540d\u3002\u91d5\u662f\u5730\u6bbc\u4e2d\u6700\u7a00\u6709\u7684\u91d1\u5c6c\u4e4b\u4e00\uff0c\u5177\u5099\u6975\u9ad8\u7684\u7194\u9ede\u8207\u5316\u5b78\u7a69\u5b9a\u6027\uff0c\u662f\u73fe\u4ee3\u96fb\u5b50\u5de5\u696d\u8207\u50ac\u5316\u5316\u5b78\u4e2d\u63d0\u5347\u6750\u6599\u8010\u4e45\u6027\u7684\u6838\u5fc3\u6dfb\u52a0\u5143\u7d20\u3002\x0a\x0a\u91d5\u7684\u96fb\u5b50\u7d44\u614b\u70ba\x20\x5b\x4b\x72\x5d\x34\x64\u2077\x35\x73\u00b9\uff0c\u5176\u5316\u5b78\u6027\u8cea\u6975\u5176\u8907\u96dc\u4e14\u591a\u8b8a\uff0c\u6c27\u5316\u614b\u53ef\u7531\x20\x2d\x32\x20\u8de8\u8d8a\u81f3\x20\x2b\x38\u3002\u5176\u4e2d\x20\x2b\x33\x20\u8207\x20\x2b\x34\x20\u662f\u6700\u5e38\u898b\u7684\u7a69\u5b9a\u72c0\u614b\uff0c\u800c\u516b\u50f9\u7684\u56db\u6c27\u5316\u91d5\x28\x52\x75\x4f\u2084\x29\u8207\u92e8\x28\x4f\x73\x29\u76f8\u4f3c\uff0c\u662f\u5177\u5099\u5f37\u6c27\u5316\u6027\u4e14\u6613\u63ee\u767c\u7684\u9ec3\u8272\u56fa\u9ad4\u3002\u91d5\u5c0d\u591a\u7a2e\u5316\u5b78\u8a66\u5291\u8868\u73fe\u51fa\u9ad8\u5ea6\u7684\u60f0\u6027\uff0c\u751a\u81f3\u80fd\u62b5\u6297\u738b\u6c34\u7684\u4fb5\u8755\uff0c\u9019\u6e90\u65bc\u5176\u539f\u5b50\u534a\u5f91\u9069\u4e2d\u4e14\u96fb\u5b50\u96f2\u5206\u5e03\u7dca\u5bc6\uff0c\u4f7f\u5176\u5728\u5f62\u6210\u904e\u6e21\u91d1\u5c6c\u932f\u5408\u7269\u6642\u5c55\u73fe\u51fa\u5353\u8d8a\u7684\u914d\u4f4d\u7a69\u5b9a\u6027\uff0c\u662f\u9ad8\u4e2d\u5316\u5b78\u5728\u7406\u89e3\u591a\u50f9\u614b\u904e\u6e21\u5143\u7d20\u884c\u70ba\u6642\u7684\u6df1\u5ea6\u6848\u4f8b\u3002\x0a\x0a\u5728\u73fe\u4ee3\u61c9\u7528\u4e2d\uff0c\u91d5\u662f\u8cc7\u8a0a\u7522\u696d\u7684\u5e55\u5f8c\u63a8\u624b\u3002\u5176\u6700\u95dc\u9375\u7684\u7528\u9014\u5728\u65bc\u786c\u789f\u7684\u300c\u5782\u76f4\u9304\u5f71\u6280\u8853\u300d\x28\x50\x4d\x52\x29\uff0c\u900f\u904e\u5728\u8a18\u9304\u5c64\u4e4b\u9593\u593e\u5165\u6578\u500b\u539f\u5b50\u539a\u5ea6\u7684\u91d5\u8584\u819c\uff0c\u5229\u7528\u5176\u53cd\u9435\u78c1\u8026\u5408\u7279\u6027\u5927\u5e45\u63d0\u5347\u5132\u5b58\u5bc6\u5ea6\u3002\u6b64\u5916\uff0c\u91d5\u57fa\u50ac\u5316\u5291\u5728\u5408\u6210\u6c28\x28\x48\x61\x62\x65\x72\x20\x70\x72\x6f\x63\x65\x73\x73\x29\u7684\u6539\u826f\u88fd\u7a0b\u4e2d\u8868\u73fe\u512a\u7570\uff0c\u80fd\u5728\u8f03\u4f4e\u58d3\u4e0b\u904b\u4f5c\uff1b\u800c\u5728\u7da0\u80fd\u9818\u57df\uff0c\u91d5\u7684\u932f\u5408\u7269\u662f\u300c\u67d3\u6599\u654f\u5316\u592a\u967d\u80fd\u96fb\u6c60\u300d\x28\x44\x53\x53\x43\x29\u4e2d\u9ad8\u6548\u7684\u5149\u654f\u5316\u5291\u3002\u5728\u6750\u6599\u640d\u58de\u9632\u6cbb\u4e0a\uff0c\u5c07\u5c11\u91cf\u91d5\u52a0\u5165\u9226\u5408\u91d1\u4e2d\u53ef\u986f\u8457\u63d0\u5347\u5176\u5728\u5f37\u9178\u74b0\u5883\u4e0b\u7684\u6297\u8755\u80fd\u529b\u3002\x0a\x0a\u91d5\u5728\u5149\u5b78\u8207\u751f\u91ab\u7814\u7a76\u4e2d\u5c55\u73fe\u51fa\u7368\u7279\u7684\u73fe\u8c61\u3002\u91d5\u7d05\x28\x52\x75\x74\x68\x65\x6e\x69\x75\x6d\x20\x72\x65\x64\x29\u662f\u4e00\u7a2e\u5e36\u6709\u5f37\u96fb\u8377\u7684\u7121\u6a5f\u67d3\u8272\u5291\uff0c\u5728\u986f\u5fae\u89c0\u5bdf\u4e2d\u5e38\u88ab\u7528\u4f86\u6a19\u5b9a\u7d30\u80de\u819c\u4e0a\u7684\u591a\u7cd6\u3002\u6709\u8da3\u7684\u662f\uff0c\u96d6\u7136\u91d5\u91d1\u5c6c\u672c\u8eab\u786c\u5ea6\u6975\u9ad8\u4e14\u8010\u78e8\uff0c\u4f46\u5b83\u537b\u975e\u5e38\u8106\uff0c\u96e3\u4ee5\u55ae\u7368\u52a0\u5de5\uff0c\u56e0\u6b64\u591a\u4ee5\u934d\u5c64\u6216\u5408\u91d1\u5f62\u5f0f\u5b58\u5728\u3002\u6b64\u5916\uff0c\u91d5\u9178\u92f0\x28\x4c\x69\u2082\x52\x75\x4f\u2083\x29\u7b49\u6c27\u5316\u7269\u5728\u96fb\u6c60\u96fb\u6975\u6750\u6599\u7684\u7814\u7a76\u4e2d\u5c55\u73fe\u4e86\u8d85\u8d8a\u50b3\u7d71\u5c64\u72c0\u6c27\u5316\u7269\u7684\u5bb9\u91cf\u4e0a\u9650\uff0c\u63ed\u793a\u4e86\u904e\u6e21\u91d1\u5c6c\u5728\u6975\u9650\u5132\u80fd\u4e2d\u7684\u6f5b\u529b\u3002\u9019\u7a2e\u5f9e\u51b7\u5cfb\u7684\u5de5\u696d\u5408\u91d1\u5230\u7cbe\u5de7\u7684\u592a\u967d\u80fd\u6355\u7372\u8005\u7684\u8f49\u8b8a\uff0c\u7cbe\u78ba\u8a6e\u91cb\u4e86\u91d5\u5728\u7b2c\u4e94\u9031\u671f\u5143\u7d20\u4e2d\u7684\u8de8\u754c\u50f9\u503c\u3002",
  "\x52\x68":
    "\u92a0\x28\x52\x68\x6f\x64\x69\x75\x6d\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x52\x68\uff0c\u539f\u5b50\u5e8f\x20\x34\x35\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u4e94\u9031\u671f\u3001\u7b2c\x20\x39\x20\u65cf\x28\x64\x20\u5340\u584a\x29\u3002\u5176\u540d\u7a31\u6e90\u65bc\u5e0c\u81d8\u8a9e\u300c\x72\x68\x6f\x64\x6f\x6e\u300d\uff0c\u610f\u70ba\u300c\u73ab\u7470\u8272\u300d\uff0c\u5f97\u540d\u65bc\u5176\u9e7d\u985e\u6eb6\u6db2\u5448\u73fe\u7684\u9bae\u8c54\u7c89\u7d05\u8272\u3002\x31\x38\x30\x33\x20\u5e74\u7531\u82f1\u570b\u5316\u5b78\u5bb6\u6c83\u62c9\u65af\u9813\x28\x57\x69\x6c\x6c\x69\x61\x6d\x20\x48\x79\x64\x65\x20\x57\x6f\x6c\x6c\x61\x73\x74\x6f\x6e\x29\u5f9e\u7c97\u9251\u7926\u4e2d\u767c\u73fe\u3002\u92a0\u662f\u4e16\u754c\u4e0a\u6700\u6602\u8cb4\u4e14\u7a00\u6709\u7684\u5929\u7136\u8cb4\u91d1\u5c6c\u4e4b\u4e00\uff0c\u5176\u5730\u6bbc\u542b\u91cf\u6975\u5fae\u3002\u5b83\u5177\u5099\u5353\u8d8a\u7684\u53cd\u5c04\u7387\u3001\u6975\u9ad8\u7684\u7194\u9ede\x28\x31\x39\x36\x34\x20\u00b0\x43\x29\u8207\u9a5a\u4eba\u7684\u6297\u6c27\u5316\u80fd\u529b\uff0c\u88ab\u8996\u70ba\u6975\u9ad8\u7aef\u5de5\u696d\u8207\u9996\u98fe\u5de5\u85dd\u7684\u9802\u7d1a\u6750\u6599\u3002\x0a\x0a\u92a0\u7684\u96fb\u5b50\u7d44\u614b\u70ba\x20\x5b\x4b\x72\x5d\x34\x64\u2078\x35\x73\u00b9\uff0c\u5728\u5316\u5b78\u884c\u70ba\u4e0a\u5c55\u73fe\u51fa\u986f\u8457\u7684\u60f0\u6027\u3002\u5b83\u662f\u9251\u65cf\u5143\u7d20\u4e2d\u96fb\u5b78\u8207\u71b1\u5b78\u6027\u8cea\u6975\u70ba\u7a69\u5b9a\u7684\u6210\u54e1\uff0c\u5373\u4f7f\u5728\u6975\u7aef\u9ad8\u6eab\u4e0b\u4e5f\u4e0d\u6703\u8207\u6c27\u6c23\u53cd\u61c9\u3002\u92a0\u5e38\u898b\u7684\u6c27\u5316\u614b\u70ba\x20\x2b\x33\uff0c\u5176\u5f62\u6210\u7684\u914d\u5408\u7269\u5e38\u5177\u5099\u9ad8\u5ea6\u7684\u7d50\u69cb\u5c0d\u7a31\u6027\u3002\u7531\u65bc\u5176\u539f\u5b50\u534a\u5f91\u8207\u53cd\u61c9\u6d3b\u6027\u7279\u9ede\uff0c\u92a0\u5728\u50ac\u5316\u53cd\u61c9\u4e2d\u80fd\u6709\u6548\u5730\u63a7\u5236\u5206\u5b50\u9375\u7d50\u7684\u65b7\u88c2\u8207\u751f\u6210\uff0c\u9019\u4f7f\u5176\u5728\u9ad8\u4e2d\u5316\u5b78\u63a2\u8a0e\u591a\u76f8\u50ac\u5316\u8207\u6d3b\u5316\u80fd\u964d\u4f4e\u7684\u6a5f\u5236\u4e2d\uff0c\u6210\u70ba\u6975\u5177\u4ee3\u8868\u6027\u7684\u9ad8\u6548\u50ac\u5316\u5291\u7bc4\u4f8b\u3002\x0a\x0a\u5728\u53f0\u7063\u9ad8\u4e2d\u8ab2\u7a0b\u8207\u74b0\u5883\u4fdd\u8b77\u8b70\u984c\u4e2d\uff0c\u92a0\u6700\u95dc\u9375\u7684\u61c9\u7528\u5728\u65bc\u6c7d\u8eca\u5ee2\u6c23\u8655\u7406\u7684\u300c\u4e09\u5143\u89f8\u5a92\u8f49\u5316\u5668\u300d\u3002\u92a0\u4e3b\u8981\u8ca0\u8cac\u50ac\u5316\u6c2e\u6c27\u5316\u7269\x28\x4e\x4f\u2093\x29\u7684\u9084\u539f\u53cd\u61c9\uff0c\u5c07\u5176\u8f49\u5316\u70ba\u7121\u5bb3\u7684\u6c2e\u6c23\uff0c\u5c0d\u7de9\u89e3\u90fd\u5e02\u5149\u5316\u5b78\u7159\u9727\u81f3\u95dc\u91cd\u8981\u3002\u6b64\u5916\uff0c\u5728\u7cbe\u5bc6\u5149\u5b78\u9818\u57df\uff0c\u7531\u65bc\u92a0\u7684\u53cd\u5c04\u7387\u6975\u9ad8\u4e14\u5316\u5b78\u7a69\u5b9a\u6027\u512a\u65bc\u9280\uff0c\u5e38\u88ab\u7528\u65bc\u88fd\u9020\u9ad8\u7d1a\u63a2\u7167\u71c8\u3001\u96fb\u5f71\u653e\u6620\u6a5f\u7684\u53cd\u5c04\u93e1\u53ca\u96f7\u5c04\u5171\u632f\u8154\u3002\u5728\u9ad8\u7d1a\u73e0\u5bf6\u696d\u4e2d\uff0c\u92a0\u88ab\u5ee3\u6cdb\u7528\u65bc\u767d\u8272\u9ec3\u91d1\u7684\u8868\u9762\u96fb\u934d\uff0c\u8ce6\u4e88\u98fe\u54c1\u7480\u74a8\u7684\u9280\u767d\u8272\u5149\u6fa4\u8207\u9632\u522e\u8010\u78e8\u7684\u7279\u6027\u3002\x0a\x0a\u92a0\u5c55\u73fe\u4e86\u6750\u6599\u79d1\u5b78\u4e2d\u300c\u6975\u5c0f\u5291\u91cf\u3001\u6975\u5927\u529f\u80fd\u300d\u7684\u7279\u8cea\u3002\u96d6\u7136\u5b83\u6975\u5c11\u55ae\u7368\u4f5c\u70ba\u7d50\u69cb\u4ef6\u4f7f\u7528\uff0c\u4f46\u53ea\u8981\u5728\u9251\u6216\u9200\u4e2d\u52a0\u5165\u5c11\u91cf\u92a0\uff0c\u4fbf\u80fd\u986f\u8457\u63d0\u5347\u6750\u6599\u7684\u786c\u5ea6\u8207\u6297\u62c9\u5f37\u5ea6\uff0c\u9019\u7a2e\u5f37\u5316\u6548\u61c9\u5728\u822a\u7a7a\u5668\u706b\u661f\u585e\u96fb\u6975\u8207\u71b1\u96fb\u5076\u6eab\u5ea6\u611f\u6e2c\u5668\x28\u5982\u9251\u92a0\u71b1\u96fb\u5076\x29\u4e2d\u4e0d\u53ef\u6216\u7f3a\u3002\u53cd\u76f4\u89ba\u7684\u662f\uff0c\u96d6\u7136\u92a0\u7684\u55ae\u8cea\u6781\u5176\u4e0d\u6d3b\u6f51\uff0c\u4f46\u5176\u7d30\u788e\u7c89\u672b\u537b\u80fd\u5c55\u73fe\u51fa\u9a5a\u4eba\u7684\u6d3b\u6027\u3002\u9019\u7a2e\u7531\u73ab\u7470\u8272\u6eb6\u6db2\u4e2d\u8403\u53d6\u51fa\u7684\u9280\u767d\u91d1\u5c6c\uff0c\u5f9e\u5b88\u8b77\u5730\u7403\u5927\u6c23\u54c1\u8cea\u5230\u88dd\u98fe\u9802\u7d1a\u5962\u83ef\u54c1\uff0c\u5c55\u73fe\u4e86\u904e\u6e21\u91d1\u5c6c\u5728\u6975\u81f4\u7a00\u7f3a\u6027\u4e0b\u7684\u95dc\u9375\u5f71\u97ff\u529b\u3002",
  "\x50\x64":
    "\u9200\x28\x50\x61\x6c\x6c\x61\x64\x69\x75\x6d\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x50\x64\uff0c\u539f\u5b50\u5e8f\x20\x34\x36\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u4e94\u9031\u671f\u3001\u7b2c\x20\x31\x30\x20\u65cf\x28\x64\x20\u5340\u584a\x29\u3002\u5176\u540d\u7a31\u6e90\u65bc\x20\x31\x38\x30\x32\x20\u5e74\u767c\u73fe\u7684\u667a\u795e\u661f\x28\x41\x73\x74\x65\x72\x6f\x69\x64\x20\x50\x61\x6c\x6c\x61\x73\x29\uff0c\u800c\u8a72\u661f\u540d\u53c8\u53d6\u81ea\u5e0c\u81d8\u667a\u6167\u5973\u795e\u96c5\u5178\u5a1c\u3002\x31\x38\x30\x33\x20\u5e74\u7531\u6c83\u62c9\u65af\u9813\x28\x57\x69\x6c\x6c\x69\x61\x6d\x20\x48\x79\x64\x65\x20\x57\x6f\x6c\x6c\x61\x73\x74\x6f\x6e\x29\u767c\u73fe\u3002\u9200\u662f\u9251\u65cf\u5143\u7d20\u4e2d\u5bc6\u5ea6\u6700\u4f4e\u3001\u7194\u9ede\u6700\u4f4e\u4e14\u6700\u5177\u53cd\u61c9\u6d3b\u6027\u7684\u4e00\u54e1\u3002\u5b83\u5177\u5099\u7368\u7279\u7684\u9280\u767d\u8272\u5149\u6fa4\uff0c\u4e14\u5728\u5e38\u6eab\u4e0b\u4e0d\u8207\u6c27\u6c23\u53cd\u61c9\uff0c\u662f\u7576\u4ee3\u96fb\u5b50\u5de5\u696d\u3001\u5316\u5b78\u50ac\u5316\u8207\u6c2b\u80fd\u6280\u8853\u4e2d\u8209\u8db3\u8f15\u91cd\u7684\u6230\u7565\u5143\u7d20\u3002\x0a\x0a\u9200\u7684\u96fb\u5b50\u7d44\u614b\u70ba\x20\x5b\x4b\x72\x5d\x34\x64\u00b9\u2070\uff0c\u9019\u662f\u4e00\u500b\u6975\u5176\u7279\u6b8a\u7684\u6848\u4f8b\uff0c\u5176\x20\x35\x73\x20\u8ecc\u57df\u70ba\u7a7a\u800c\x20\x34\x64\x20\u8ecc\u57df\u5168\u6eff\uff0c\u9019\u4f7f\u5176\u5728\u5316\u5b78\u53cd\u61c9\u4e2d\u50be\u5411\u65bc\u900f\u904e\u6df7\u6210\u8ecc\u57df\u8207\u591a\u7a2e\u914d\u9ad4\u5f62\u6210\u7a69\u5b9a\u7684\u5e73\u9762\u56db\u65b9\u5f62\u6216\u516b\u9762\u9ad4\u932f\u5408\u7269\u3002\u9200\u7684\u96fb\u8ca0\u5ea6\x28\u7d04\x20\x32\x2e\x32\x30\x29\u8207\u6c2b\u6975\u5176\u63a5\u8fd1\uff0c\u9019\u8ce6\u4e88\u4e86\u5b83\u6700\u5177\u4ee3\u8868\u6027\u7684\u7269\u7406\u7279\u5fb5\uff1a\u9200\u662f\u8457\u540d\u7684\u300c\u6c2b\u6c23\u6d77\u7dbf\u300d\uff0c\u5728\u5ba4\u6eab\u4e0b\u80fd\u5438\u6536\u5176\u9ad4\u7a4d\x20\x39\x30\x30\x20\u500d\u4ee5\u4e0a\u7684\u6c2b\u6c23\u3002\u6c2b\u539f\u5b50\u6703\u586b\u5145\u5728\u9200\u539f\u5b50\u7684\u6676\u683c\u9593\u9699\u4e2d\uff0c\u5f62\u6210\u975e\u6574\u6bd4\u7684\u6c2b\u5316\u9200\uff0c\u9019\u7a2e\u7368\u7279\u7684\u9593\u9699\u578b\u6c2b\u5316\u7269\u6027\u8cea\uff0c\u4f7f\u9200\u6210\u70ba\u7814\u7a76\u6750\u6599\u5438\u6c2b\u8207\u6c2b\u8106\u6a5f\u5236\u7684\u6a19\u6e96\u6a23\u672c\u3002\x0a\x0a\u5728\u73fe\u4ee3\u61c9\u7528\u4e2d\uff0c\u9200\u5728\u6709\u6a5f\u5408\u6210\u5316\u5b78\u4e2d\u64c1\u6709\u7d71\u6cbb\u5730\u4f4d\u3002\x32\x30\x31\x30\x20\u5e74\u8afe\u8c9d\u723e\u5316\u5b78\u734e\u7684\u300c\u9200\u50ac\u5316\u4ea4\u53c9\u5076\u806f\u53cd\u61c9\u300d\x28\u5982\x20\x53\x75\x7a\x75\x6b\x69\x20\u53cd\u61c9\x29\u5229\u7528\u9200\u539f\u5b50\u512a\u7570\u7684\u96fb\u5b50\u8f49\u79fb\u80fd\u529b\uff0c\u7cbe\u78ba\u5730\u9023\u63a5\u78b3\u539f\u5b50\uff0c\u662f\u88fd\u9020\u88fd\u85e5\u3001\u8fb2\u85e5\u8207\u6709\u6a5f\u96fb\u5b50\x28\x4f\x4c\x45\x44\x29\u7684\u6838\u5fc3\u6280\u8853\u3002\u6b64\u5916\uff0c\u9200\u5728\u6c7d\u8eca\u4e09\u5143\u89f8\u5a92\u8f49\u5316\u5668\u4e2d\u8ca0\u8cac\u6c27\u5316\u4e00\u6c27\u5316\u78b3\u8207\u78b3\u6c2b\u5316\u5408\u7269\u3002\u5728\u6c2b\u80fd\u6280\u8853\u4e2d\uff0c\u9200\u819c\u88ab\u7528\u4f5c\u8d85\u9ad8\u7d14\u5ea6\u6c2b\u6c23\u7684\u6de8\u5316\u904e\u6ffe\u5668\uff0c\u56e0\u70ba\u53ea\u6709\u6c2b\u539f\u5b50\u80fd\u7a7f\u900f\u9200\u7684\u6676\u683c\uff0c\u5176\u9918\u96dc\u8cea\u7686\u88ab\u963b\u9694\uff0c\u9019\u5728\u534a\u5c0e\u9ad4\u88fd\u7a0b\u7684\u9ad8\u7d14\u5ea6\u6c23\u9ad4\u4f9b\u61c9\u4e2d\u81f3\u95dc\u91cd\u8981\u3002\x0a\x0a\u9200\u5c55\u73fe\u4e86\u904e\u6e21\u91d1\u5c6c\u5728\u6975\u7aef\u74b0\u5883\u4e0b\u7684\u654f\u611f\u6027\u8207\u591a\u529f\u80fd\u6027\u3002\u96d6\u7136\u5b83\u5728\u5e38\u58d3\u4e0b\u76f8\u5c0d\u7a69\u5b9a\uff0c\u4f46\u7576\u66b4\u9732\u65bc\u786b\u84b8\u6c23\u6642\u6703\u7522\u751f\u8b8a\u8272\uff0c\u9019\u5728\u96fb\u5b50\u63a5\u9ede\u8a2d\u8a08\u4e2d\u662f\u5fc5\u9808\u8003\u91cf\u7684\u8150\u8755\u98a8\u96aa\u3002\u6709\u8da3\u7684\u662f\uff0c\u9200\u91d1\x28\x50\x61\x6c\x6c\x61\x64\x69\x75\x6d\x20\x67\x6f\x6c\x64\x29\u662f\u7259\u79d1\u5668\u6750\u4e2d\u5e38\u7528\u7684\u5408\u91d1\u6210\u5206\uff0c\u56e0\u5176\u512a\u7570\u7684\u6297\u8150\u8755\u6027\u8207\u751f\u7269\u76f8\u5bb9\u6027\u3002\u5728\u7269\u7406\u6027\u8cea\u4e0a\uff0c\u9200\u5438\u6536\u6c2b\u6c23\u5f8c\u9ad4\u7a4d\u6703\u767c\u751f\u986f\u8457\u81a8\u8139\uff0c\u9019\u4e00\u7279\u6027\u4e5f\u88ab\u61c9\u7528\u65bc\u6c2b\u6c23\u611f\u6e2c\u5668\u7684\u958b\u767c\u3002\u9019\u7a2e\u5f9e\u661f\u7a7a\u4e4b\u540d\u5230\u5fae\u89c0\u6c2b\u539f\u5b50\u6ffe\u7db2\u7684\u8eab\u5206\u8de8\u5ea6\uff0c\u7cbe\u78ba\u8a6e\u91cb\u4e86\u9200\u5728\u73fe\u4ee3\u6750\u6599\u79d1\u5b78\u8207\u7da0\u8272\u5316\u5b78\u4e2d\u4e0d\u53ef\u66ff\u4ee3\u7684\u5730\u4f4d\u3002",
  "\x41\x67":
    "\u9280\x28\x53\x69\x6c\x76\x65\x72\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x41\x67\uff0c\u539f\u5b50\u5e8f\x20\x34\x37\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u4e94\u9031\u671f\u3001\u7b2c\x20\x31\x31\x20\u65cf\x28\x64\x20\u5340\u584a\x29\u3002\u5176\u540d\u7a31\u6e90\u65bc\u53e4\u82f1\u8a9e\x20\x53\x65\x6f\x6c\x66\x6f\x72\uff0c\u800c\u7b26\u865f\x20\x41\x67\x20\u5247\u53d6\u81ea\u62c9\u4e01\u8a9e\x20\x41\x72\x67\x65\x6e\x74\x75\x6d\uff0c\u610f\u70ba\u300c\u9583\u8000\u300d\u6216\u300c\u767d\u8272\u300d\u3002\u9280\u662f\u4eba\u985e\u6700\u65e9\u767c\u73fe\u4e26\u4f7f\u7528\u7684\u91d1\u5c6c\u4e4b\u4e00\uff0c\u81ea\u53e4\u4ee5\u4f86\u4fbf\u8207\u91d1\u3001\u9285\u4e26\u5217\u70ba\u8ca8\u5e63\u91d1\u5c6c\u3002\u9280\u5728\u5730\u6bbc\u4e2d\u5e38\u4ee5\u6e38\u96e2\u614b\u81ea\u7136\u9280\u6216\u786b\u5316\u7269\u7926\u77f3\u5f62\u5f0f\u5b58\u5728\uff0c\u5177\u5099\u5353\u8d8a\u7684\u5c0e\u96fb\u8207\u5c0e\u71b1\u6027\u80fd\uff0c\u662f\u73fe\u4ee3\u96fb\u5b50\u5de5\u696d\u8207\u5149\u96fb\u7522\u696d\u4e2d\u8ffd\u6c42\u6975\u81f4\u6548\u80fd\u7684\u6838\u5fc3\u6750\u6599\u3002\x0a\x0a\u9280\u7684\u96fb\u5b50\u7d44\u614b\u70ba\x20\x5b\x4b\x72\x5d\x34\x64\u00b9\u2070\x35\x73\u00b9\uff0c\u70ba\u4e86\u9054\u6210\x20\x34\x64\x20\u8ecc\u57df\u5168\u6eff\u7684\u7a69\u5b9a\u7d44\u614b\uff0c\u5176\u50f9\u96fb\u5b50\u6392\u5e03\u5c55\u73fe\u51fa\u8207\u9285\u3001\u91d1\u76f8\u4f3c\u7684\u898f\u5f8b\u3002\u9280\u7684\u96fb\u8ca0\u5ea6\u7d04\u70ba\x20\x31\x2e\x39\x33\uff0c\u6700\u5e38\u898b\u7684\u6c27\u5316\u614b\u70ba\x20\x2b\x31\u3002\u5728\u53f0\u7063\u9ad8\u4e2d\u5316\u5b78\u5be6\u9a57\u4e2d\uff0c\u9280\u96e2\u5b50\x28\x41\x67\u207a\x29\u662f\u5b9a\u6027\u5206\u6790\u7684\u6838\u5fc3\uff1a\u5b83\u8207\u9e75\u7d20\u96e2\u5b50\u53cd\u61c9\u751f\u6210\u7684\u9e75\u5316\u9280\u6c89\u6fb1\x28\u5982\u767d\u8272\u7684\x20\x41\x67\x43\x6c\u3001\u6de1\u9ec3\u8272\u7684\x20\x41\x67\x42\x72\u3001\u9ec3\u8272\u7684\x20\x41\x67\x49\x29\uff0c\u662f\u7406\u89e3\u6c89\u6fb1\u5e73\u8861\u8207\u6eb6\u5ea6\u7a4d\x28\x4b\x73\x70\x29\u7684\u7d93\u5178\u6559\u6750\u3002\u6b64\u5916\uff0c\u9280\u96e2\u5b50\u8207\u6c28\u6c34\u5f62\u6210\u7684\u932f\u96e2\u5b50\x20\x5b\x41\x67\x28\x4e\x48\u2083\x29\u2082\x5d\u207a\x20\u5177\u5099\u7279\u6b8a\u7684\u5316\u5b78\u6d3b\u6027\uff0c\u662f\u9032\u884c\u300c\u9280\u93e1\u53cd\u61c9\u300d\x28\x54\x6f\x6c\x6c\x65\x6e\x73\x27\x20\x72\x65\x61\x67\x65\x6e\x74\x29\u6aa2\u9a57\u919b\u985e\u7684\u91cd\u8981\u8a66\u5291\u3002\x0a\x0a\u5728\u96fb\u5316\u5b78\u8207\u5de5\u696d\u61c9\u7528\u4e2d\uff0c\u9280\u7684\u6a19\u6e96\u9084\u539f\u96fb\u4f4d\x28\x45\u2070\x20\u2248\x20\x2b\x30\x2e\x38\x30\x20\x56\x29\u4f7f\u5176\u5177\u5099\u512a\u7570\u7684\u5316\u5b78\u7a69\u5b9a\u6027\uff0c\u50c5\u80fd\u6eb6\u65bc\u5f37\u6c27\u5316\u6027\u9178\x28\u5982\u785d\u9178\x29\u3002\u9280\u7684\u96fb\u5c0e\u7387\u4f4d\u5c45\u6240\u6709\u91d1\u5c6c\u4e4b\u51a0\uff0c\u9019\u4f7f\u5176\u6210\u70ba\u9ad8\u7aef\u97f3\u97ff\u7dda\u8def\u3001\u534a\u5c0e\u9ad4\u5c01\u88dd\u53ca\u822a\u592a\u7cbe\u5bc6\u63a5\u9ede\u7684\u9996\u9078\u3002\u5728\u80fd\u6e90\u9818\u57df\uff0c\u9280\u6f3f\u662f\u592a\u967d\u80fd\u96fb\u6c60\u677f\x28\x50\x68\x6f\x74\x6f\x76\x6f\x6c\x74\x61\x69\x63\x20\x63\x65\x6c\x6c\x73\x29\u4e2d\u6536\u96c6\u96fb\u6d41\u7684\u95dc\u9375\u5c0e\u96fb\u5c64\u3002\u6b64\u5916\uff0c\u9280\u5177\u5099\u986f\u8457\u7684\u300c\u5fae\u52d5\u529b\u6548\u61c9\u300d\x28\x4f\x6c\x69\x67\x6f\x64\x79\x6e\x61\x6d\x69\x63\x20\x65\x66\x66\x65\x63\x74\x29\uff0c\u6975\u4f4e\u6fc3\u5ea6\u7684\u9280\u96e2\u5b50\u5373\u53ef\u7834\u58de\u7d30\u83cc\u7684\u9176\u7cfb\u7d71\uff0c\u56e0\u6b64\u5ee3\u6cdb\u61c9\u7528\u65bc\u71d2\u71d9\u50b7\u85e5\u818f\u3001\u9664\u81ed\u7e96\u7dad\u53ca\u73fe\u4ee3\u91ab\u7642\u690d\u5165\u7269\u7684\u8868\u9762\u6297\u83cc\u8655\u7406\u3002\x0a\x0a\u9280\u5728\u5149\u5b78\u7279\u6027\u4e0a\u8868\u73fe\u51fa\u8fd1\u4e4e\u5b8c\u7f8e\u7684\u7269\u7406\u6027\u8cea\uff0c\u5176\u5c0d\u53ef\u898b\u5149\u7684\u53cd\u5c04\u7387\u9ad8\u9054\x20\x39\x35\x25\x20\u4ee5\u4e0a\uff0c\u662f\u88fd\u9020\u9ad8\u54c1\u8cea\u5e73\u9762\u93e1\u8207\u671b\u9060\u93e1\u53cd\u5c04\u93e1\u7684\u50b3\u7d71\u6750\u6599\u3002\u6709\u8da3\u7684\u662f\uff0c\u96d6\u7136\u9280\u672c\u8eab\u4e0d\u8207\u6c27\u6c23\u53cd\u61c9\uff0c\u4f46\u5b83\u5c0d\u7a7a\u6c23\u4e2d\u75d5\u91cf\u7684\u786b\u5316\u6c2b\x28\x48\u2082\x53\x29\u6975\u5176\u654f\u611f\uff0c\u6703\u53cd\u61c9\u751f\u6210\u9ed1\u8272\u7684\u786b\u5316\u9280\x28\x41\x67\u2082\x53\x29\uff0c\u9019\u5c31\u662f\u9280\u5668\u653e\u7f6e\u4e45\u4e86\u6703\u767c\u9ed1\u8b8a\u6697\u7684\u5316\u5b78\u771f\u76f8\u3002\u800c\u5728\u651d\u5f71\u53f2\u4e0a\uff0c\u6eb4\u5316\u9280\x28\x41\x67\x42\x72\x29\u7684\u611f\u5149\u7279\u6027\u652f\u6490\u4e86\u9577\u9054\u767e\u5e74\u7684\u5e95\u7247\u5de5\u696d\u3002\u9019\u7a2e\u5f9e\u5be6\u9a57\u5ba4\u7684\u9280\u93e1\u5947\u8e5f\u5230\u9a45\u52d5\u7da0\u8272\u80fd\u6e90\u7684\u50b3\u5c0e\u6838\u5fc3\uff0c\u5c55\u73fe\u4e86\u9280\u5143\u7d20\u5728\u7f8e\u5b78\u3001\u5316\u5b78\u8207\u73fe\u4ee3\u5de5\u7a0b\u9593\u7684\u5b8c\u7f8e\u8de8\u5ea6\u3002",
  "\x43\x64":
    "\u9398\x28\x43\x61\x64\x6d\x69\x75\x6d\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x43\x64\uff0c\u539f\u5b50\u5e8f\x20\x34\x38\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u4e94\u9031\u671f\u3001\u7b2c\x20\x31\x32\x20\u65cf\x28\x64\x20\u5340\u584a\x29\u3002\x31\x38\x31\x37\x20\u5e74\u7531\u5fb7\u570b\u5316\u5b78\u5bb6\u65af\u7279\u7f85\u9081\u723e\x28\x46\x72\x69\x65\x64\x72\x69\x63\x68\x20\x53\x74\x72\x6f\x68\x6d\x65\x79\x65\x72\x29\u5728\u7814\u7a76\u92c5\u7926\u77f3\u6642\u610f\u5916\u767c\u73fe\u3002\u5176\u540d\u7a31\u6e90\u65bc\u62c9\u4e01\u8a9e\x20\x63\x61\x64\x6d\x69\x61\uff0c\u610f\u6307\u542b\u92c5\u7684\u7926\u77f3\u3002\u9398\u5728\u81ea\u7136\u754c\u4e2d\u6975\u5c11\u4ee5\u7368\u7acb\u7926\u5e8a\u5b58\u5728\uff0c\u901a\u5e38\u4f34\u751f\u65bc\u92c5\u7926\u4e2d\u3002\u7531\u65bc\u5176\u7279\u6b8a\u7684\u7269\u7406\u5316\u5b78\u6027\u8cea\uff0c\u9398\u66fe\u88ab\u5927\u91cf\u7528\u65bc\u96fb\u934d\u8207\u96fb\u6c60\u5de5\u696d\uff0c\u4f46\u56e0\u5176\u5c0d\u74b0\u5883\u8207\u4eba\u9ad4\u5177\u5099\u9ad8\u5ea6\u7d2f\u7a4d\u6bd2\u6027\uff0c\u73fe\u4eca\u5df2\u53d7\u5230\u5404\u570b\u74b0\u5883\u5de5\u7a0b\u898f\u7bc4\u7684\u56b4\u683c\u76e3\u63a7\u3002\x0a\x0a\u9398\u7684\u96fb\u5b50\u7d44\u614b\u70ba\x20\x5b\x4b\x72\x5d\x34\x64\u00b9\u2070\x35\x73\u00b2\uff0c\u8207\u540c\u65cf\u7684\u92c5\u76f8\u4f3c\uff0c\u5176\x20\x33\x64\x20\u8ecc\u57df\u5168\u6eff\u800c\u4e0d\u53c3\u8207\u5178\u578b\u904e\u6e21\u91d1\u5c6c\u7684\x20\x64\x2d\x64\x20\u8ecc\u57df\u8e8d\u9077\uff0c\u56e0\u6b64\u5176\u5316\u5408\u7269\u591a\u5448\u7121\u8272\u6216\u9ec3\u8272\u3002\u9398\u5728\u5316\u5408\u7269\u4e2d\u7a69\u5b9a\u5448\u73fe\x20\x2b\x32\x20\u6c27\u5316\u614b\u3002\u5728\u5316\u5b78\u6027\u8cea\u4e0a\uff0c\u9398\u6bd4\u92c5\u66f4\u5177\u5099\u91d1\u5c6c\u6027\uff0c\u4f46\u5728\u9178\u6027\u6eb6\u6db2\u4e2d\u7684\u53cd\u61c9\u6027\u7565\u4f4e\u3002\u5728\u9ad8\u4e2d\u5316\u5b78\u95dc\u65bc\u74b0\u5883\u4fdd\u8b77\u8207\u91cd\u91d1\u5c6c\u6c61\u67d3\u7684\u7ae0\u7bc0\u4e2d\uff0c\u9398\u662f\u6975\u5177\u6307\u6a19\u6027\u7684\u5143\u7d20\uff1a\u5b83\u6703\u53d6\u4ee3\u751f\u7269\u9aa8\u9abc\u4e2d\u7684\u9223\uff0c\u5c0e\u81f4\u56b4\u91cd\u7684\u6162\u6027\u4e2d\u6bd2\u73fe\u8c61\uff0c\u5373\u8457\u540d\u7684\u300c\u75db\u75db\u75c5\u300d\x28\x49\x74\x61\x69\x2d\x69\x74\x61\x69\x20\x64\x69\x73\x65\x61\x73\x65\x29\uff0c\u9019\u662f\u74b0\u5883\u5316\u5b78\u6559\u5b78\u4e2d\u63a2\u8a0e\u91cd\u91d1\u5c6c\u5faa\u74b0\u8207\u751f\u7269\u653e\u5927\u4f5c\u7528\u7684\u6158\u75db\u6559\u8a13\u3002\x0a\x0a\u5728\u5de5\u696d\u8207\u73fe\u4ee3\u79d1\u6280\u4e2d\uff0c\u9398\u7684\u61c9\u7528\u4e3b\u8981\u96c6\u4e2d\u65bc\u7279\u5b9a\u9818\u57df\u3002\u93b3\u9398\u96fb\u6c60\x28\x4e\x69\x2d\x43\x64\x20\x62\x61\x74\x74\x65\x72\x79\x29\u96d6\u7136\u9010\u6f38\u88ab\u92f0\u96fb\u6c60\u53d6\u4ee3\uff0c\u4f46\u5728\u9ad8\u653e\u96fb\u500d\u7387\u8207\u6975\u7aef\u6eab\u5ea6\u74b0\u5883\u4e0b\u4ecd\u5177\u5099\u53ef\u9760\u6027\u3002\u9398\u7684\u4f4e\u7194\u9ede\u7279\u6027\u4f7f\u5176\u6210\u70ba\u88fd\u9020\u6613\u7194\u5408\u91d1\x28\u5982\u4f0d\u5fb7\u5408\u91d1\uff0c\x57\x6f\x6f\x64\x27\x73\x20\x6d\x65\x74\x61\x6c\x29\u7684\u91cd\u8981\u6210\u5206\uff0c\u7528\u65bc\u81ea\u52d5\u5674\u6c34\u6ec5\u706b\u7cfb\u7d71\u7684\u71b1\u611f\u89f8\u767c\u4ef6\u3002\u5728\u5c16\u7aef\u534a\u5c0e\u9ad4\u9818\u57df\uff0c\u786b\u5316\u9398\x28\x43\x64\x53\x29\u8207\u7852\u5316\u9398\x28\x43\x64\x53\x65\x29\u662f\u6975\u4f73\u7684\u5149\u96fb\u6750\u6599\uff0c\u5e38\u88ab\u88fd\u6210\u300c\u91cf\u5b50\u9ede\u300d\x28\x51\x75\x61\x6e\x74\x75\x6d\x20\x44\x6f\x74\x73\x29\uff0c\u5229\u7528\u5176\u5927\u5c0f\u53ef\u8abf\u63a7\u7684\u80fd\u9699\u7522\u751f\u6975\u9ad8\u7d14\u5ea6\u7684\u8272\u5f69\uff0c\u5ee3\u6cdb\u61c9\u7528\u65bc\u65b0\u4e00\u4ee3\u986f\u793a\u5668\u8207\u751f\u91ab\u6210\u50cf\u6a19\u8a18\u3002\x0a\x0a\u9398\u5728\u6838\u5b50\u5de5\u7a0b\u4e2d\u5177\u5099\u4e00\u9805\u95dc\u9375\u7684\u7269\u7406\u7279\u5fb5\uff1a\u5b83\u64c1\u6709\u6975\u5927\u7684\u71b1\u4e2d\u5b50\u5438\u6536\u622a\u9762\u3002\u9019\u4f7f\u5f97\u91d1\u5c6c\u9398\u5e38\u88ab\u88fd\u6210\u6838\u53cd\u61c9\u7210\u7684\u300c\u63a7\u5236\u68d2\u300d\uff0c\u900f\u904e\u63d2\u5165\u6216\u62bd\u51fa\u4f86\u7cbe\u78ba\u8abf\u7bc0\u4e2d\u5b50\u901a\u91cf\uff0c\u78ba\u4fdd\u6838\u5206\u88c2\u9023\u9396\u53cd\u61c9\u7684\u7a69\u5b9a\u8207\u5b89\u5168\u3002\u6709\u8da3\u7684\u662f\uff0c\u96d6\u7136\u9398\u88ab\u8996\u70ba\u5287\u6bd2\uff0c\u4f46\x20\x32\x30\x30\x30\x20\u5e74\u79d1\u5b78\u5bb6\u5728\u67d0\u4e9b\u77fd\u85fb\u9ad4\u5167\u767c\u73fe\u4e86\u552f\u4e00\u7684\u300c\u9398\u9176\u300d\x28\u78b3\u9178\u9150\u9176\x29\uff0c\u986f\u793a\u4e86\u67d0\u4e9b\u751f\u547d\u5f62\u5f0f\u5728\u7f3a\u4e4f\u92c5\u7684\u6d77\u6d0b\u74b0\u5883\u4e2d\uff0c\u9032\u5316\u51fa\u4e86\u5229\u7528\u9398\u9032\u884c\u4ee3\u8b1d\u7684\u7279\u6b8a\u6a5f\u5236\u3002\u9019\u7a2e\u5f9e\u81f4\u547d\u6c61\u67d3\u7269\u5230\u7cbe\u5bc6\u6838\u80fd\u63a7\u5236\u5668\u53ca\u986f\u793a\u6280\u8853\u6838\u5fc3\u7684\u8f49\u8b8a\uff0c\u9ad4\u73fe\u4e86\u9398\u5143\u7d20\u5728\u4eba\u985e\u6587\u660e\u767c\u5c55\u4e2d\u7684\u8907\u96dc\u89d2\u8272\u3002",
  "\x49\x6e":
    "\u92a6\x28\x49\x6e\x64\x69\x75\x6d\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x49\x6e\uff0c\u539f\u5b50\u5e8f\x20\x34\x39\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u4e94\u9031\u671f\u3001\u7b2c\x20\x31\x33\x20\u65cf\x28\x70\x20\u5340\u584a\x29\u3002\x31\x38\x36\x33\x20\u5e74\u7531\u5fb7\u570b\u5316\u5b78\u5bb6\u8cf4\u5e0c\x28\x48\x69\x65\x72\x6f\x6e\x79\x6d\x6f\x75\x73\x20\x54\x68\x65\x6f\x64\x6f\x72\x20\x52\x69\x63\x68\x74\x65\x72\x29\u8207\u91cc\u5e0c\u7279\x28\x46\x65\x72\x64\x69\x6e\x61\x6e\x64\x20\x52\x65\x69\x63\x68\x29\u5728\u5229\u7528\u5149\u8b5c\u5206\u6790\u92c5\u7926\u6642\uff0c\u767c\u73fe\u4e86\u4e00\u689d\u4eae\u9e97\u7684\u975b\u85cd\u8272\x28\x49\x6e\x64\x69\x67\x6f\x29\u8b5c\u7dda\uff0c\u56e0\u800c\u5f97\u540d\u3002\u92a6\u662f\u4e00\u7a2e\u8cea\u5730\u6975\u5176\u67d4\u8edf\u3001\u5177\u5099\u9280\u767d\u8272\u5149\u6fa4\u7684\u91d1\u5c6c\uff0c\u5728\u5730\u6bbc\u4e2d\u5206\u5e03\u7a00\u6563\u3002\u5b83\u662f\u73fe\u4ee3\u96fb\u5b50\u5de5\u696d\u4e2d\u4e0d\u53ef\u6216\u7f3a\u7684\u300c\u89f8\u63a7\u9748\u9b42\u300d\uff0c\u662f\u53f0\u7063\u9ad8\u79d1\u6280\u986f\u793a\u5668\u7522\u696d\u93c8\u4e2d\u6975\u5176\u95dc\u9375\u7684\u7b56\u7565\u7269\u8cc7\u3002\x0a\x0a\u92a6\u7684\u96fb\u5b50\u7d44\u614b\u70ba\x20\x5b\x4b\x72\x5d\x34\x64\u00b9\u2070\x35\x73\u00b2\x35\x70\u00b9\uff0c\u5728\u5316\u5b78\u6027\u8cea\u4e0a\u4ee5\x20\x2b\x33\x20\u6c27\u5316\u614b\u6700\u70ba\u7a69\u5b9a\u3002\u92a6\u5177\u6709\u975e\u5e38\u4f4e\u7684\u7194\u9ede\x28\x31\x35\x36\x2e\x36\x20\u00b0\x43\x29\uff0c\u4e14\u5373\u4fbf\u5728\u6975\u4f4e\u6eab\u4e0b\u4e5f\u4fdd\u6301\u6975\u4f73\u7684\u5ef6\u5c55\u6027\u3002\u5728\u9031\u671f\u898f\u5f8b\u4e0a\uff0c\u92a6\u7684\u6027\u8cea\u4ecb\u65bc\u92c1\u8207\u9248\u4e4b\u9593\uff0c\u5176\u6c27\u5316\u7269\x20\x49\x6e\u2082\x4f\u2083\x20\u5177\u5099\u5fae\u5f31\u7684\u5169\u6027\u7279\u5fb5\u3002\u92a6\u6700\u91cd\u8981\u7684\u7269\u7406\u5316\u5b78\u7279\u5fb5\u662f\u5176\u8207\u6c27\u5316\u932b\x28\x53\x6e\x4f\u2082\x29\u7d50\u5408\u5f8c\u5f62\u6210\u7684\u300c\u6c27\u5316\u92a6\u932b\u300d\x28\x49\x6e\x64\x69\x75\x6d\x20\x54\x69\x6e\x20\x4f\x78\x69\x64\x65\x2c\x20\x49\x54\x4f\x29\u3002\x49\x54\x4f\x20\u5177\u5099\u6975\u70ba\u7f55\u898b\u7684\u7269\u7406\u7279\u6027\u7d44\u5408\uff1a\u5b83\u5728\u53ef\u898b\u5149\u4e0b\u662f\u900f\u660e\u7684\uff0c\u540c\u6642\u53c8\u5177\u5099\u826f\u597d\u7684\u5c0e\u96fb\u6027\uff0c\u9019\u5960\u5b9a\u4e86\u7576\u4ee3\u5e73\u9762\u986f\u793a\u6280\u8853\u7684\u7269\u7406\u57fa\u790e\u3002\x0a\x0a\u5728\u53f0\u7063\u9ad8\u4e2d\u8ab2\u7db1\u5ef6\u4f38\u7684\u6750\u6599\u61c9\u7528\u4e2d\uff0c\x49\x54\x4f\x20\u662f\u89f8\u63a7\u87a2\u5e55\u3001\u6db2\u6676\u986f\u793a\u5668\x28\x4c\x43\x44\x29\u53ca\u6709\u6a5f\u767c\u5149\u4e8c\u6975\u9ad4\x28\x4f\x4c\x45\x44\x29\u900f\u660e\u96fb\u6975\u7684\u6a19\u6e96\u6750\u6599\u3002\u9664\u4e86\u986f\u793a\u5668\u9818\u57df\uff0c\u92a6\u5728\u534a\u5c0e\u9ad4\u647b\u96dc\u4e2d\u4f5c\u70ba\x20\x70\x20\u578b\u647b\u96dc\u5291\uff0c\u4e26\u8207\u7837\u3001\u78f7\u7d50\u5408\u6210\u4e09\u4e94\u65cf\u534a\u5c0e\u9ad4\x28\u5982\x20\x49\x6e\x50\u3001\x49\x6e\x47\x61\x41\x73\x29\uff0c\u61c9\u7528\u65bc\u9ad8\u901f\u901a\u8a0a\u8207\u7d05\u5916\u7dda\u96f7\u5c04\u3002\u6b64\u5916\uff0c\u7531\u65bc\u92a6\u5177\u5099\u512a\u7570\u7684\u6f64\u6fd5\u6027\x28\x57\x65\x74\x74\x61\x62\x69\x6c\x69\x74\x79\x29\uff0c\u5b83\u80fd\u8207\u591a\u7a2e\u6750\u6599\u5f62\u6210\u7a69\u5b9a\u7684\u4f4e\u6eab\u710a\u6599\uff0c\u662f\u7cbe\u5bc6\u96fb\u5b50\u5c01\u88dd\u4e2d\u9632\u6b62\u71b1\u61c9\u529b\u7834\u58de\u7d44\u4ef6\u7684\u91cd\u8981\u6750\u6599\u3002\u5728\u6838\u80fd\u9818\u57df\uff0c\u92a6\u4ea6\u8207\u9280\u3001\u9398\u5171\u540c\u69cb\u6210\u63a7\u5236\u68d2\uff0c\u5229\u7528\u5176\u6355\u6349\u4e2d\u5b50\u7684\u7279\u6027\u8abf\u7bc0\u53cd\u61c9\u901f\u7387\u3002\x0a\x0a\u92a6\u5c55\u73fe\u4e86\u67d0\u4e9b\u6709\u8da3\u7684\u6a5f\u68b0\u7279\u5fb5\u3002\u7576\u5f4e\u66f2\u4e00\u6839\u91d1\u5c6c\u92a6\u68d2\u6642\uff0c\u53ef\u4ee5\u807d\u5230\u660e\u986f\u7684\u55f6\u556a\u8072\uff0c\u9019\u88ab\u7a31\u70ba\u300c\u932b\u9cf4\u300d\x28\u4f46\u92a6\u4ea6\u5177\u5099\u6b64\u73fe\u8c61\x29\uff0c\u662f\u7531\u65bc\u91d1\u5c6c\u6676\u9ad4\u767c\u751f\u5b7f\u6676\u8b8a\u5f62\x28\x54\x77\x69\x6e\x6e\x69\x6e\x67\x29\u6240\u91cb\u653e\u7684\u8072\u80fd\u3002\u6b64\u5916\uff0c\u91d1\u5c6c\u92a6\u5177\u5099\u6975\u5f37\u7684\u300c\u51b7\u710a\u300d\x28\x43\x6f\x6c\x64\x20\x77\x65\x6c\x64\x69\x6e\x67\x29\u7279\u6027\uff0c\u5728\u771f\u7a7a\u4e2d\u53ea\u8981\u5169\u584a\u4e7e\u6de8\u7684\u92a6\u9762\u63a5\u89f8\uff0c\u4e0d\u9700\u52a0\u71b1\u5373\u53ef\u7d50\u5408\u6210\u4e00\u9ad4\u3002\u6709\u8da3\u7684\u662f\uff0c\u92a6\u5728\u6db2\u614b\u6642\u80fd\u6d78\u6f64\u73bb\u7483\uff0c\u9019\u7a2e\u8207\u975e\u91d1\u5c6c\u6750\u6599\u7dca\u5bc6\u7d50\u5408\u7684\u80fd\u529b\uff0c\u4f7f\u5176\u5728\u79d1\u5b78\u5100\u5668\u88fd\u9020\u4e2d\u88ab\u7528\u4f5c\u771f\u7a7a\u5bc6\u5c01\u588a\u5708\u3002\u9019\u7a2e\u5f9e\u975b\u85cd\u5149\u8b5c\u7684\u767c\u73fe\u5230\u6307\u5c16\u89f8\u63a7\u79d1\u6280\u7684\u6838\u5fc3\uff0c\u4f7f\u92a6\u6210\u70ba\u8cc7\u8a0a\u6642\u4ee3\u4e2d\u4f4e\u8abf\u4e14\u4e0d\u53ef\u6216\u7f3a\u7684\u91d1\u5c6c\u95dc\u9375\u3002",
  "\x53\x6e":
    "\u932b\x28\x54\x69\x6e\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x53\x6e\uff0c\u539f\u5b50\u5e8f\x20\x35\x30\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u4e94\u9031\u671f\u3001\u7b2c\x20\x31\x34\x20\u65cf\x28\u78b3\u65cf\u5143\u7d20\uff0c\x70\x20\u5340\u584a\x29\u3002\u5176\u540d\u7a31\u6e90\u65bc\u53e4\u82f1\u8a9e\uff0c\u7b26\u865f\x20\x53\x6e\x20\u53d6\u81ea\u62c9\u4e01\u8a9e\x20\x53\x74\x61\x6e\x6e\x75\x6d\u3002\u932b\u662f\u4eba\u985e\u6700\u65e9\u4f7f\u7528\u7684\u91d1\u5c6c\u4e4b\u4e00\uff0c\u8207\u9285\u5408\u91d1\u5316\u88fd\u6210\u7684\u300c\u9752\u9285\u300d\u6a19\u8a8c\u4e86\u4eba\u985e\u6587\u660e\u9032\u6b65\u7684\u91cd\u8981\u968e\u6bb5\u3002\u932b\u5728\u81ea\u7136\u754c\u4e2d\u4e3b\u8981\u4ee5\u932b\u77f3\x28\x53\x6e\x4f\u2082\x29\u5f62\u5f0f\u5b58\u5728\u3002\u5b83\u662f\u5178\u578b\u7684\u91d1\u5c6c\u5143\u7d20\uff0c\u4f46\u5728\u7d50\u69cb\u8207\u884c\u70ba\u4e0a\u4ecd\u4fdd\u7559\u4e86\u78b3\u65cf\u5143\u7d20\u7279\u6709\u7684\u591a\u6a23\u6027\uff0c\u7279\u5225\u662f\u5176\u8457\u540d\u7684\u540c\u7d20\u7570\u5f62\u9ad4\u8f49\u8b8a\uff0c\u5c0d\u6750\u6599\u6b77\u53f2\u8207\u73fe\u4ee3\u96fb\u5b50\u5c01\u88dd\u7686\u5177\u5099\u6df1\u9060\u5f71\u97ff\u3002\x0a\x0a\u932b\u7684\u96fb\u5b50\u7d44\u614b\u70ba\x20\x5b\x4b\x72\x5d\x34\x64\u00b9\u2070\x35\x73\u00b2\x35\x70\u00b2\uff0c\u5e38\u898b\u6c27\u5316\u614b\u6709\x20\x2b\x32\x20\u8207\x20\x2b\x34\u3002\u5728\u9ad8\u4e2d\u5316\u5b78\u63a2\u8a0e\u6c27\u5316\u9084\u539f\u5e73\u8861\u6642\uff0c\u4e8c\u50f9\u932b\u96e2\u5b50\x28\x53\x6e\u00b2\u207a\x29\u662f\u5e38\u7528\u7684\u9084\u539f\u5291\uff0c\u80fd\u5c07\u4e09\u50f9\u9435\u96e2\u5b50\u9084\u539f\u3002\u932b\u6700\u986f\u8457\u7684\u7269\u7406\u5316\u5b78\u7279\u5fb5\u662f\u5176\u540c\u7d20\u7570\u5f62\u9ad4\uff1a\u5728\u5ba4\u6eab\u4e0b\u7a69\u5b9a\u7684\u662f\u5177\u5099\u91d1\u5c6c\u6027\u7684\u300c\u767d\u932b\u300d\x28\u03b2\x2d\x53\x6e\x29\uff0c\u4f46\u5728\u4f4e\u65bc\x20\x31\x33\x2e\x32\x20\u00b0\x43\x20\u6642\uff0c\u6703\u7de9\u6162\u8f49\u8b8a\u70ba\u975e\u91d1\u5c6c\u6027\u3001\u5177\u5099\u947d\u77f3\u7d50\u69cb\u7684\u7c89\u672b\u72c0\u300c\u7070\u932b\u300d\x28\u03b1\x2d\x53\x6e\x29\u3002\u9019\u7a2e\u8f49\u8b8a\u6703\u5c0e\u81f4\u9ad4\u7a4d\u81a8\u8139\u4e26\u4f7f\u7d50\u69cb\u5d29\u6bc0\uff0c\u5728\u6b77\u53f2\u4e0a\u88ab\u7a31\u70ba\u300c\u932b\u75ab\u300d\x28\x54\x69\x6e\x20\x70\x65\x73\x74\x29\uff0c\u66fe\u9020\u6210\u6975\u5730\u63a2\u96aa\u968a\u8207\u6230\u722d\u5f8c\u52e4\u7684\u707d\u96e3\u6027\u640d\u6bc0\u3002\x0a\x0a\u5728\u53f0\u7063\u9ad8\u4e2d\u8ab2\u7db1\u8207\u73fe\u4ee3\u5de5\u696d\u4e2d\uff0c\u932b\u7684\u5169\u6027\x28\x41\x6d\x70\x68\x6f\x74\x65\x72\x69\x63\x29\u7279\u5fb5\u662f\u91cd\u9ede\uff1a\u91d1\u5c6c\u932b\u80fd\u8207\u5f37\u9178\u53cd\u61c9\uff0c\u4ea6\u80fd\u6eb6\u65bc\u5f37\u9e7c\u7522\u751f\u932b\u9178\u6839\u96e2\u5b50\u3002\u61c9\u7528\u65b9\u9762\uff0c\u932b\u6700\u91cd\u8981\u7684\u7528\u9014\u662f\u4f5c\u70ba\u300c\u92b2\u932b\u300d\x28\x53\x6f\x6c\x64\x65\x72\x29\uff0c\u8207\u9280\u3001\u9285\u7d44\u6210\u7121\u925b\u710a\u6599\uff0c\u5c07\u96fb\u5b50\u5143\u4ef6\u56fa\u5b9a\u65bc\u96fb\u8def\u677f\u4e0a\u3002\u6b64\u5916\uff0c\u932b\u5177\u5099\u512a\u7570\u7684\u6297\u8150\u8755\u6027\u4e14\u7121\u6bd2\uff0c\u5ee3\u6cdb\u7528\u65bc\u300c\u99ac\u53e3\u9435\u300d\x28\x54\x69\x6e\x70\x6c\x61\x74\x65\x29\u7684\u751f\u7522\uff0c\u5373\u5728\u92fc\u7247\u8868\u9762\u934d\u932b\u4ee5\u88fd\u4f5c\u7f50\u982d\uff0c\u9632\u6b62\u98df\u54c1\u9178\u8755\u9435\u8cea\u3002\u5728\u5316\u5b78\u5de5\u696d\u4e2d\uff0c\u6709\u6a5f\u932b\u5316\u5408\u7269\u66fe\u88ab\u7528\u4f5c\u9632\u6c61\u5857\u6599\uff0c\u4f46\u56e0\u5176\u5c0d\u6d77\u6d0b\u751f\u614b\u5177\u5099\u56b4\u91cd\u6fc0\u7d20\u5e72\u64fe\u6bd2\u6027\uff0c\u73fe\u5df2\u53d7\u5230\u56b4\u683c\u7981\u7528\u3002\x0a\x0a\u932b\u5728\u5de5\u7a0b\u73fe\u8c61\u4e0a\u5177\u5099\u7368\u7279\u7684\u300c\u8072\u97ff\u300d\u7279\u5fb5\uff1a\u5f4e\u66f2\u932b\u68d2\u6642\uff0c\u6676\u9ad4\u6469\u64e6\u6703\u767c\u51fa\u788e\u88c2\u8072\uff0c\u7a31\u70ba\u300c\u932b\u9cf4\u300d\x28\x54\x69\x6e\x20\x63\x72\x79\x29\u3002\u5728\u6750\u6599\u79d1\u5b78\u524d\u6cbf\uff0c\u55ae\u539f\u5b50\u5c64\u7684\u932b\u2014\u2014\u300c\u932b\u70ef\u300d\x28\x53\x74\x61\x6e\x65\x6e\x65\x29\uff0c\u88ab\u9810\u6e2c\u70ba\u4e00\u7a2e\u5177\u5099\x20\x31\x30\x30\x25\x20\u5c0e\u96fb\u6548\u7387\u7684\u62d3\u6a38\u7d55\u7de3\u9ad4\uff0c\u53ef\u80fd\u5728\u672a\u4f86\u7684\u5948\u7c73\u96fb\u5b50\u5143\u4ef6\u4e2d\u5be6\u73fe\u96f6\u529f\u8017\u50b3\u5c0e\u3002\u53cd\u76f4\u89ba\u7684\u662f\uff0c\u5118\u7ba1\u932b\u88ab\u8996\u70ba\u73fe\u4ee3\u91d1\u5c6c\uff0c\u4f46\u5b83\u8207\u78b3\u3001\u77fd\u540c\u65cf\u7684\u8eab\u5206\uff0c\u4f7f\u5176\u5728\u6975\u4f4e\u6eab\u4e0b\u5c55\u73fe\u51fa\u5b8c\u5168\u4e0d\u540c\u7684\u975e\u91d1\u5c6c\u76f8\u3002\u9019\u7a2e\u5f9e\u9752\u9285\u6642\u4ee3\u7684\u6587\u660e\u57fa\u77f3\u5230\u73fe\u4ee3\u96fb\u5b50\u5c01\u88dd\u7684\u9ecf\u5408\u5291\uff0c\u5c55\u73fe\u4e86\u932b\u5143\u7d20\u5728\u9031\u671f\u8868\u904e\u6e21\u5340\u4e2d\u7a69\u5b9a\u4e14\u95dc\u9375\u7684\u5730\u4f4d\u3002",
  "\x53\x62":
    "\u92bb\x28\x41\x6e\x74\x69\x6d\x6f\x6e\x79\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x53\x62\uff0c\u539f\u5b50\u5e8f\x20\x35\x31\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u4e94\u9031\u671f\u3001\u7b2c\x20\x31\x35\x20\u65cf\x28\u6c2e\u65cf\u5143\u7d20\uff0c\x70\x20\u5340\u584a\x29\u3002\u5176\u540d\u7a31\u6e90\u65bc\u5e0c\u81d8\u8a9e\u300c\x61\x6e\x74\x69\u300d\u8207\u300c\x6d\x6f\x6e\x6f\x73\u300d\x28\u4e0d\u55ae\u7368\u5b58\u5728\x29\uff0c\u7b26\u865f\x20\x53\x62\x20\u5247\u53d6\u81ea\u62c9\u4e01\u8a9e\x20\x53\x74\x69\x62\x69\x75\x6d\x28\u8f1d\u92bb\u7926\x29\u3002\u92bb\u662f\u4eba\u985e\u81ea\u53e4\u4fbf\u5df2\u4f7f\u7528\u7684\u985e\u91d1\u5c6c\u5143\u7d20\uff0c\u5176\u786b\u5316\u7269\u5728\u53e4\u57c3\u53ca\u66fe\u88ab\u7528\u4f5c\u773c\u5f71\u3002\x31\x37\x20\u4e16\u7d00\u7531\u6cd5\u570b\u5316\u5b78\u5bb6\u5c3c\u53e4\u62c9\u00b7\u52d2\u6885\u91cc\x28\x4e\x69\x63\x6f\x6c\x61\x73\x20\x4c\u00e9\x6d\x65\x72\x79\x29\u5c0d\u5176\u5316\u5b78\u6027\u8cea\u9032\u884c\u4e86\u7cfb\u7d71\u6027\u7814\u7a76\u3002\u92bb\u5728\u5730\u6bbc\u4e2d\u4e3b\u8981\u4ee5\u8f1d\u92bb\u7926\x28\x53\x62\u2082\x53\u2083\x29\u5f62\u5f0f\u5b58\u5728\uff0c\u662f\u73fe\u4ee3\u963b\u71c3\u6280\u8853\u8207\u925b\u9178\u96fb\u6c60\u5de5\u696d\u4e2d\u7684\u6838\u5fc3\u5f37\u5316\u5143\u7d20\u3002\x0a\x0a\u92bb\u7684\u96fb\u5b50\u7d44\u614b\u70ba\x20\x5b\x4b\x72\x5d\x34\x64\u00b9\u2070\x35\x73\u00b2\x35\x70\u00b3\uff0c\u5177\u5099\u985e\u91d1\u5c6c\u7279\u5fb5\u3002\u5b83\u64c1\u6709\u56db\u7a2e\u540c\u7d20\u7570\u5f62\u9ad4\uff0c\u6700\u7a69\u5b9a\u7684\u662f\u5177\u5099\u91d1\u5c6c\u5149\u6fa4\u7684\u85cd\u767d\u8272\u300c\u9280\u92bb\u300d\uff0c\u5176\u7d50\u69cb\u8207\u7837\u3001\u77f3\u58a8\u76f8\u4f3c\uff0c\u5448\u73fe\u5c64\u72c0\u6392\u5e03\uff0c\u5c0e\u81f4\u5176\u5c0e\u96fb\u5c0e\u71b1\u6027\u80fd\u512a\u65bc\u5178\u578b\u975e\u91d1\u5c6c\u4f46\u905c\u65bc\u771f\u91d1\u5c6c\u3002\u92bb\u7684\u96fb\u8ca0\u5ea6\u70ba\x20\x32\x2e\x30\x35\uff0c\u5e38\u898b\u6c27\u5316\u614b\u70ba\x20\x2b\x33\x20\u8207\x20\x2b\x35\u3002\u5728\u5316\u5b78\u53cd\u61c9\u4e2d\uff0c\u92bb\u5c55\u73fe\u51fa\u660e\u986f\u7684\u300c\u60f0\u6027\u96fb\u5b50\u5c0d\u6548\u61c9\u300d\uff0c\u4f7f\u5176\x20\x2b\x33\x20\u50f9\u5316\u5408\u7269\u5728\u71b1\u529b\u5b78\u4e0a\u901a\u5e38\u6bd4\x20\x2b\x35\x20\u50f9\u66f4\u70ba\u7a69\u5b9a\u3002\u92bb\u53ca\u5176\u5316\u5408\u7269\u5177\u5099\u4e00\u5b9a\u7684\u6bd2\u6027\uff0c\u5176\u5316\u5b78\u884c\u70ba\u5728\u5b9a\u6027\u5206\u6790\u4e2d\u5e38\u8207\u924d\x28\x42\x69\x29\u9032\u884c\u5c0d\u6bd4\uff0c\u662f\u7406\u89e3\u904e\u6e21\u5340\u5143\u7d20\u91d1\u5c6c\u6027\u905e\u589e\u898f\u5f8b\u7684\u91cd\u8981\u6848\u4f8b\u3002\x0a\x0a\u5728\u53f0\u7063\u9ad8\u4e2d\u8ab2\u7db1\u5ef6\u4f38\u7684\u6750\u6599\u61c9\u7528\u4e2d\uff0c\u92bb\u6700\u91cd\u8981\u7684\u7528\u9014\u662f\u4f5c\u70ba\u300c\u963b\u71c3\u5291\u300d\u7684\u5354\u6548\u5291\u3002\u4e09\u6c27\u5316\u4e8c\u92bb\x28\x53\x62\u2082\x4f\u2083\x29\u5e38\u8207\u9e75\u7d20\u963b\u71c3\u5291\u4e26\u7528\uff0c\u5728\u9ad8\u6eab\u4e0b\u7522\u751f\u9e75\u5316\u92bb\u6c23\u9ad4\u6355\u6349\u81ea\u7531\u57fa\uff0c\u6709\u6548\u5ef6\u7de9\u9ad8\u5206\u5b50\u6750\u6599\u7684\u71c3\u71d2\u3002\u5728\u96fb\u5b78\u9818\u57df\uff0c\u92bb\u662f\u91cd\u8981\u7684\u534a\u5c0e\u9ad4\u647b\u96dc\u5291\uff0c\u80fd\u70ba\u77fd\u63d0\u4f9b\u96fb\u5b50\u5f62\u6210\x20\x6e\x20\u578b\u534a\u5c0e\u9ad4\u3002\u51b6\u91d1\u5de5\u696d\u4e2d\uff0c\u5c07\u92bb\u52a0\u5165\u925b\u4e2d\u88fd\u6210\u300c\u92bb\u925b\u5408\u91d1\u300d\uff0c\u80fd\u5927\u5e45\u63d0\u5347\u786c\u5ea6\u8207\u6297\u8150\u8755\u529b\uff0c\u5ee3\u6cdb\u61c9\u7528\u65bc\u6c7d\u8eca\u925b\u9178\u96fb\u6c60\u7684\u6975\u677f\u8207\u5370\u5237\u6d3b\u5b57\u91d1\u5c6c\u3002\u6b64\u5916\uff0c\u9ad8\u7d14\u5ea6\u7684\u92bb\u5316\u92a6\x28\x49\x6e\x53\x62\x29\u56e0\u5176\u6975\u9ad8\u7684\u96fb\u5b50\u9077\u79fb\u7387\uff0c\u662f\u88fd\u9020\u7d05\u5916\u7dda\u63a2\u6e2c\u5668\u8207\u9ad8\u901f\u96fb\u5b50\u5143\u4ef6\u7684\u6838\u5fc3\u6750\u6599\u3002\x0a\x0a\u92bb\u5c55\u73fe\u4e86\u67d0\u4e9b\u7279\u6b8a\u7684\u7269\u7406\u8b8a\u76f8\u7279\u5fb5\u3002\u91d1\u5c6c\u92bb\u8207\u6c34\u76f8\u4f3c\uff0c\u5728\u51b7\u537b\u51dd\u56fa\u6642\u9ad4\u7a4d\u6703\u767c\u751f\u81a8\u8139\x28\u7d04\x20\x30\x2e\x39\x35\x25\x29\uff0c\u9019\u4e00\u7279\u6027\u4f7f\u92bb\u5408\u91d1\u5728\u9444\u9020\u6642\u80fd\u5b8c\u7f8e\u586b\u5145\u6a21\u5177\uff0c\u78ba\u4fdd\u6d3b\u5b57\u5370\u5237\u6216\u7cbe\u5bc6\u96f6\u4ef6\u7684\u8f2a\u5ed3\u6e05\u6670\u3002\u6709\u8da3\u7684\u662f\uff0c\u5b58\u5728\u4e00\u7a2e\u4e0d\u7a69\u5b9a\u7684\u300c\u7206\u70b8\u92bb\u300d\x28\x45\x78\x70\x6c\x6f\x73\x69\x76\x65\x20\x61\x6e\x74\x69\x6d\x6f\x6e\x79\x29\uff0c\u7576\u7528\u92b3\u5668\u522e\u64e6\u9019\u7a2e\u96fb\u89e3\u88fd\u5f97\u7684\u975e\u6676\u614b\u92bb\u6642\uff0c\u5b83\u6703\u56e0\u91cb\u653e\u5132\u5b58\u7684\u6676\u683c\u80fd\u800c\u5287\u70c8\u767c\u751f\u76f8\u8b8a\uff0c\u91cb\u653e\u71b1\u91cf\u4e26\u8f49\u5316\u70ba\u7a69\u5b9a\u7684\u91d1\u5c6c\u614b\u3002\u9019\u7a2e\u5f9e\u53e4\u4ee3\u5316\u599d\u54c1\u5230\u73fe\u4ee3\u96fb\u5b50\u5c4f\u853d\u8207\u822a\u592a\u5408\u91d1\u7684\u8eab\u5206\u8de8\u5ea6\uff0c\u7cbe\u78ba\u8a6e\u91cb\u4e86\u92bb\u5728\u985e\u91d1\u5c6c\u754c\u4e2d\u6c89\u7a69\u4e14\u591a\u80fd\u7684\u5730\u4f4d\u3002",
  "\x54\x65":
    "\u78b2\x28\x54\x65\x6c\x6c\x75\x72\x69\x75\x6d\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x54\x65\uff0c\u539f\u5b50\u5e8f\x20\x35\x32\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u4e94\u9031\u671f\u3001\u7b2c\x20\x31\x36\x20\u65cf\x28\u6c27\u65cf\u5143\u7d20\uff0c\x70\x20\u5340\u584a\x29\u3002\x31\x37\x38\x32\x20\u5e74\u7531\u5967\u5730\u5229\u7926\u7269\u5b78\u5bb6\u7c73\u52d2\x28\x46\x72\x61\x6e\x7a\x2d\x4a\x6f\x73\x65\x70\x68\x20\x4d\u00fc\x6c\x6c\x65\x72\x20\x76\x6f\x6e\x20\x52\x65\x69\x63\x68\x65\x6e\x73\x74\x65\x69\x6e\x29\u5728\u5206\u6790\u91d1\u7926\u77f3\u6642\u767c\u73fe\uff0c\u96a8\u5f8c\u514b\u62c9\u666e\u7f85\u7279\x28\x4d\x61\x72\x74\x69\x6e\x20\x48\x65\x69\x6e\x72\x69\x63\x68\x20\x4b\x6c\x61\x70\x72\x6f\x74\x68\x29\u4ee5\u62c9\u4e01\u8a9e\u300c\x54\x65\x6c\x6c\x75\x73\u300d\x28\u5730\u7403\x29\u5c07\u5176\u547d\u540d\uff0c\u4ee5\u8207\u66f4\u65e9\u767c\u73fe\u7684\u7852\x28\u6708\u4eae\x29\u547c\u61c9\u3002\u78b2\u662f\u985e\u91d1\u5c6c\u5143\u7d20\uff0c\u5728\u5730\u6bbc\u4e2d\u6975\u5176\u7a00\u5c11\x28\u8c50\u5ea6\u8207\u9251\u76f8\u8fd1\x29\uff0c\u5e38\u4ee5\u78b2\u5316\u7269\u7684\u5f62\u5f0f\u5b58\u5728\u65bc\u91d1\u3001\u9280\u7926\u4e2d\u3002\u5b83\u662f\u73fe\u4ee3\u5149\u4f0f\u7522\u696d\u8207\u71b1\u96fb\u80fd\u6e90\u8f49\u63db\u6280\u8853\u4e2d\u7684\u95dc\u9375\u534a\u5c0e\u9ad4\u6750\u6599\u3002\x0a\x0a\u78b2\u7684\u96fb\u5b50\u7d44\u614b\u70ba\x20\x5b\x4b\x72\x5d\x34\x64\u00b9\u2070\x35\x73\u00b2\x35\x70\u2074\uff0c\u5177\u5099\u660e\u986f\u7684\u534a\u5c0e\u9ad4\u7279\u5fb5\u3002\u55ae\u8cea\u78b2\u5448\u9280\u7070\u8272\u3001\u5177\u5099\u91d1\u5c6c\u5149\u6fa4\u4e14\u8cea\u8106\uff0c\u5176\u539f\u5b50\u7d50\u69cb\u662f\u4ee5\u87ba\u65cb\u93c8\u72c0\u5206\u5b50\u7684\u5f62\u5f0f\u6392\u5e03\u3002\u78b2\u7684\u96fb\u8ca0\u5ea6\u7d04\u70ba\x20\x32\x2e\x31\uff0c\u5e38\u898b\u6c27\u5316\u614b\u70ba\x20\x2d\x32\u3001\x2b\x34\x20\u8207\x20\x2b\x36\u3002\u5728\u5316\u5b78\u898f\u5f8b\u4e0a\uff0c\u78b2\u7684\u6027\u8cea\u4ecb\u65bc\u7852\u8207\u91d9\u4e4b\u9593\u3002\u7531\u65bc\u78b2\u539f\u5b50\u7684\u6975\u5316\u7387\u8f03\u9ad8\uff0c\u5b83\u80fd\u8207\u591a\u7a2e\u91d1\u5c6c\u5f62\u6210\u5177\u6709\u534a\u5c0e\u9ad4\u7279\u6027\u7684\u91d1\u5c6c\u78b2\u5316\u7269\u3002\u5728\u9ad8\u4e2d\u5316\u5b78\u63a2\u8a0e\u65cf\u7fa4\u8da8\u52e2\u6642\uff0c\u78b2\u5316\u6c2b\x28\x48\u2082\x54\x65\x29\u7684\u9178\u6027\u8207\u9084\u539f\u6027\u7686\u5f37\u65bc\u786b\u5316\u6c2b\x28\x48\u2082\x53\x29\uff0c\u9019\u53cd\u6620\u4e86\u539f\u5b50\u534a\u5f91\u589e\u5927\u5c0e\u81f4\u9375\u7d50\u6e1b\u5f31\u7684\u8da8\u52e2\u3002\x0a\x0a\u5728\u73fe\u4ee3\u61c9\u7528\u4e2d\uff0c\u78b2\u662f\u300c\u592a\u967d\u80fd\u96fb\u6c60\u300d\u6280\u8853\u7684\u524d\u6cbf\u3002\u78b2\u5316\u9398\x28\x43\x64\x54\x65\x29\u8584\u819c\u592a\u967d\u80fd\u96fb\u6c60\u56e0\u5176\u6975\u9ad8\u7684\u5149\u5438\u6536\u4fc2\u6578\u8207\u826f\u597d\u7684\u8f49\u63db\u6548\u7387\uff0c\u88ab\u8996\u70ba\u77fd\u57fa\u96fb\u6c60\u7684\u4e3b\u8981\u7af6\u722d\u8005\u3002\u5728\u51b6\u91d1\u5b78\u4e2d\uff0c\u5c07\u5fae\u91cf\u78b2\u52a0\u5165\u4e0d\u93fd\u92fc\u6216\u9285\u4e2d\uff0c\u80fd\u986f\u8457\u6539\u5584\u5176\u6a5f\u68b0\u52a0\u5de5\u6027\u80fd\x28\u5207\u524a\u6027\x29\u800c\u4e0d\u964d\u4f4e\u8010\u8755\u6027\u3002\u6b64\u5916\uff0c\u78b2\u8207\u924d\u5f62\u6210\u7684\u5408\u91d1\x28\x42\x69\u2082\x54\x65\u2083\x29\u662f\u76ee\u524d\u5df2\u77e5\u6548\u80fd\u6700\u4f73\u7684\u5e38\u6eab\u300c\u71b1\u96fb\u6750\u6599\u300d\uff0c\u80fd\u5c07\u6eab\u5dee\u76f4\u63a5\u8f49\u5316\u70ba\u96fb\u80fd\uff0c\u5ee3\u6cdb\u61c9\u7528\u65bc\u7121\u566a\u97f3\u7684\u96fb\u5b50\u51b0\u7bb1\u3001\u592a\u7a7a\u63a2\u6e2c\u5668\u96fb\u6e90\u4ee5\u53ca\u7cbe\u5bc6\u6eab\u63a7\u8a2d\u5099\u4e2d\u3002\x0a\x0a\u78b2\u5728\u751f\u7269\u8207\u6750\u6599\u7279\u6027\u4e0a\u5c55\u73fe\u4e86\u5947\u7279\u7684\u73fe\u8c61\u3002\u96d6\u7136\u78b2\u5728\u5de5\u696d\u4e2d\u6975\u5177\u50f9\u503c\uff0c\u4f46\u4eba\u9ad4\u63a5\u89f8\u5fae\u91cf\u78b2\u5f8c\uff0c\u9ad4\u5167\u6703\u4ee3\u8b1d\u7522\u751f\u4e8c\u7532\u57fa\u78b2\x28\x28\x43\x48\u2083\x29\u2082\x54\x65\x29\uff0c\u9019\u6703\u5c0e\u81f4\u5f37\u70c8\u7684\u300c\u78b2\u5473\u547c\u5438\u300d\x28\x54\x65\x6c\x6c\x75\x72\x69\x75\x6d\x20\x62\x72\x65\x61\x74\x68\x29\uff0c\u60a3\u8005\u7684\u6c57\u6db2\u8207\u53e3\u6c23\u6703\u6563\u767c\u51fa\u6301\u4e45\u7684\u8150\u721b\u5927\u849c\u5473\uff0c\u9019\u7a2e\u73fe\u8c61\u5e38\u88ab\u7528\u65bc\u8077\u696d\u91ab\u5b78\u7684\u63a5\u89f8\u8ffd\u8e64\u3002\u6b64\u5916\uff0c\u78b2\u662f\u6975\u5c11\u6578\u80fd\u8207\u300c\u91d1\u300d\u5728\u81ea\u7136\u754c\u5f62\u6210\u5316\u5408\u7269\u7684\u5143\u7d20\x28\u5982\u78b2\u91d1\u7926\x20\x41\x75\x54\x65\u2082\x29\uff0c\u9019\u5728\u91d1\u5c6c\u5316\u5b78\u4e2d\u6975\u5176\u7279\u6b8a\u3002\u9019\u7a2e\u5f9e\u5730\u7403\u4e4b\u540d\u7684\u4f4e\u8abf\u5b58\u5728\uff0c\u5230\u9a45\u52d5\u7da0\u8272\u5149\u96fb\u8207\u6df1\u7a7a\u6eab\u5dee\u96fb\u529b\u7684\u6838\u5fc3\u8f49\u63db\u8005\uff0c\u5c55\u73fe\u4e86\u78b2\u5728\u7b2c\u4e94\u9031\u671f\u985e\u91d1\u5c6c\u4e2d\u7684\u7368\u7279\u80fd\u91cf\u5730\u4f4d\u3002",
  "\x49":
    "\u7898\x28\x49\x6f\x64\x69\x6e\x65\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x49\uff0c\u539f\u5b50\u5e8f\x20\x35\x33\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u4e94\u9031\u671f\u3001\u7b2c\x20\x31\x37\x20\u65cf\x28\u9e75\u7d20\uff0c\x70\x20\u5340\u584a\x29\u3002\x31\x38\x31\x31\x20\u5e74\u7531\u6cd5\u570b\u5316\u5b78\u5bb6\u5eab\u5716\u74e6\x28\x42\x65\x72\x6e\x61\x72\x64\x20\x43\x6f\x75\x72\x74\x6f\x69\x73\x29\u5728\u71c3\u71d2\u6d77\u85fb\u7070\u7522\u751f\u7684\u7159\u9727\u4e2d\u767c\u73fe\uff0c\u56e0\u5176\u84b8\u6c23\u5448\u73fe\u7f8e\u9e97\u7684\u7d2b\u8272\uff0c\u7531\u84cb\x2d\u5442\u85a9\u514b\x28\x47\x61\x79\x2d\x4c\x75\x73\x73\x61\x63\x29\u4f9d\u5e0c\u81d8\u8a9e\u300c\x69\x6f\x64\x65\x73\u300d\x28\u6df1\u7d2b\u8272\x29\u547d\u540d\u3002\u7898\u662f\u9e75\u7d20\u5bb6\u65cf\u4e2d\u539f\u5b50\u5e8f\u6700\u5927\u7684\u7a69\u5b9a\u975e\u91d1\u5c6c\u5143\u7d20\uff0c\u5728\u5730\u6bbc\u4e2d\u4e3b\u8981\u4ee5\u7898\u9178\u9e7d\u5f62\u5f0f\u5b58\u5728\u65bc\u785d\u77f3\u7926\u6216\u6d77\u6c34\u4e2d\u3002\u5b83\u662f\u4eba\u9ad4\u7532\u72c0\u817a\u7d20\u7684\u6838\u5fc3\u6210\u5206\uff0c\u4ea6\u662f\u5316\u5b78\u9451\u5b9a\u8207\u5149\u5b78\u6750\u6599\u4e2d\u7684\u9748\u9b42\u5143\u7d20\u3002\x0a\x0a\u7898\u7684\u96fb\u5b50\u7d44\u614b\u70ba\x20\x5b\x4b\x72\x5d\x34\x64\u00b9\u2070\x35\x73\u00b2\x35\x70\u2075\uff0c\u5448\u9ed1\u7070\u8272\u56fa\u9ad4\uff0c\u5177\u5099\u5fae\u5f31\u7684\u91d1\u5c6c\u5149\u6fa4\u3002\u7898\u6700\u8457\u540d\u7684\u7269\u7406\u7279\u6027\u662f\u300c\u6607\u83ef\u300d\x28\x53\x75\x62\x6c\x69\x6d\x61\x74\x69\x6f\x6e\x29\uff0c\u5728\u5e38\u58d3\u4e0b\u52a0\u71b1\u4e0d\u7d93\u904e\u6db2\u614b\u76f4\u63a5\u8b8a\u70ba\u7d2b\u8272\u84b8\u6c23\uff0c\u9019\u662f\u9ad8\u4e2d\u5316\u5b78\u8a0e\u8ad6\u76f8\u5716\u8207\u76f8\u8b8a\u5316\u7684\u7d93\u5178\u6559\u6750\u3002\u7898\u7684\u96fb\u8ca0\u5ea6\u70ba\x20\x32\x2e\x36\x36\uff0c\u6c27\u5316\u529b\u5f31\u65bc\u6c2f\u8207\u6eb4\u3002\u5728\u6eb6\u6db2\u5316\u5b78\u4e2d\uff0c\u7898\u5728\u975e\u6975\u6027\u6eb6\u5291\x28\u5982\x20\x43\x43\x6c\u2084\x29\u4e2d\u5448\u73fe\u7d2b\u8272\uff0c\u800c\u5728\u6975\u6027\u6eb6\u5291\x28\u5982\u4e59\u9187\x29\u6216\x20\x4b\x49\x20\u6eb6\u6db2\x28\u5f62\u6210\x20\x49\u2083\u207b\x29\u4e2d\u5448\u73fe\u7d05\u8910\u8272\u3002\u7898\u8207\u6fb1\u7c89\u53cd\u61c9\u7522\u751f\u7684\u300c\u85cd\u7d2b\u8272\u932f\u5408\u7269\u300d\uff0c\u662f\u751f\u7269\u5316\u5b78\u8207\u5206\u6790\u5316\u5b78\u4e2d\u6aa2\u9a57\u591a\u7cd6\u8207\u6c27\u5316\u5291\u6700\u9748\u654f\u7684\u9451\u5b9a\u53cd\u61c9\u3002\x0a\x0a\u5728\u53f0\u7063\u9ad8\u4e2d\u8ab2\u7db1\u8207\u91ab\u7642\u8108\u7d61\u4e2d\uff0c\u7898\u7684\u61c9\u7528\u6975\u70ba\u91cd\u8981\u3002\u7898\u9152\x28\x54\x69\x6e\x63\x74\x75\x72\x65\x20\x6f\x66\x20\x69\x6f\x64\x69\x6e\x65\x29\u8207\u512a\u7898\x28\x50\x6f\x76\x69\x64\x6f\x6e\x65\x2d\x69\x6f\x64\x69\x6e\x65\x29\u662f\u6a19\u6e96\u7684\u6d88\u6bd2\u5291\uff1b\u800c\u540c\u4f4d\u7d20\x20\u00b9\u00b3\u00b9\x49\x20\u5247\u5ee3\u6cdb\u61c9\u7528\u65bc\u7532\u72c0\u817a\u529f\u80fd\u6aa2\u67e5\u8207\u7532\u72c0\u817a\u764c\u7684\u653e\u5c04\u6cbb\u7642\u3002\u5728\u73fe\u4ee3\u5149\u5b78\u4e2d\uff0c\u7898\u662f\u6db2\u6676\u986f\u793a\u5668\x28\x4c\x43\x44\x29\u300c\u504f\u5149\u677f\u300d\u7684\u6838\u5fc3\u6750\u6599\uff0c\u5229\u7528\u7898\u5206\u5b50\u8207\u805a\u4e59\u70ef\u9187\x28\x50\x56\x41\x29\u5f62\u6210\u7684\u9577\u93c8\u7d50\u69cb\u5438\u6536\u7279\u5b9a\u65b9\u5411\u7684\u632f\u52d5\u5149\u3002\u6b64\u5916\uff0c\u5728\u6709\u6a5f\u5316\u5b78\u4e2d\uff0c\u7898\u4eff\u53cd\u61c9\x28\x49\x6f\x64\x6f\x66\x6f\x72\x6d\x20\x74\x65\x73\x74\x29\u662f\u7528\u65bc\u6aa2\u6e2c\u7279\u5b9a\u7532\u57fa\u916e\u6216\u9187\u7d50\u69cb\u7684\u91cd\u8981\u5b9a\u6027\u5206\u6790\u624b\u6bb5\u3002\u96fb\u5316\u5b78\u65b9\u9762\uff0c\u7898\u5316\u9280\x28\x41\x67\x49\x29\u56e0\u5176\u7279\u6b8a\u7684\u96e2\u5b50\u50b3\u5c0e\u6027\uff0c\u4ea6\u88ab\u7528\u65bc\u958b\u767c\u5168\u56fa\u614b\u96fb\u6c60\u3002\x0a\x0a\u7898\u5c55\u73fe\u4e86\u591a\u6a23\u7684\u5b8f\u89c0\u8207\u5fae\u89c0\u73fe\u8c61\u3002\u5b83\u662f\u6240\u6709\u9e75\u7d20\u4e2d\u552f\u4e00\u5e38\u6eab\u4e0b\u70ba\u56fa\u614b\u7684\u6210\u54e1\uff0c\u4e14\u5176\u84b8\u6c23\u58d3\u96a8\u6eab\u5ea6\u5347\u9ad8\u800c\u8fc5\u901f\u589e\u52a0\uff0c\u4f7f\u5176\u5728\u5c01\u9589\u7ba1\u4e2d\u53d7\u71b1\u80fd\u5c55\u73fe\u8ff7\u4eba\u7684\u7d2b\u8272\u5149\u9727\u3002\u6709\u8da3\u7684\u662f\uff0c\u96d6\u7136\u7898\u5728\u6c34\u4e2d\u6eb6\u89e3\u5ea6\u6975\u4f4e\uff0c\u4f46\u5728\x20\x49\u207b\x20\u96e2\u5b50\u7684\u8f14\u52a9\u4e0b\u6703\u5f62\u6210\u9ad8\u5ea6\u53ef\u6eb6\u4e14\u5177\u6c27\u5316\u529b\u7684\x20\x49\u2083\u207b\x20\u96e2\u5b50\x28\u4e09\u7898\u9670\u96e2\u5b50\x29\u3002\u6c23\u8c61\u5b78\u4e2d\uff0c\u7898\u5316\u9280\u56e0\u5176\u6676\u9ad4\u7d50\u69cb\u8207\u51b0\u6975\u70ba\u76f8\u4f3c\uff0c\u88ab\u7528\u4f5c\u4eba\u5de5\u589e\u96e8\u7684\u50ac\u5316\u5291\x28\u96f2\u7a2e\u6563\u64ad\x29\u3002\u9019\u7a2e\u5f9e\u6d77\u85fb\u4e2d\u7684\u7d2b\u8272\u9a5a\u5947\u5230\u5b88\u8b77\u4eba\u985e\u7532\u72c0\u817a\u5065\u5eb7\u8207\u9a45\u52d5\u667a\u6167\u578b\u624b\u6a5f\u87a2\u5e55\u7684\u89d2\u8272\uff0c\u7cbe\u78ba\u9ad4\u73fe\u4e86\u7898\u5728\u9e75\u7d20\u5bb6\u65cf\u4e2d\u517c\u5177\u5be6\u9a57\u7f8e\u611f\u8207\u751f\u7406\u95dc\u9375\u7684\u96d9\u91cd\u8eab\u5206\u3002",
  "\x58\x65":
    "\u6c19\x28\x58\x65\x6e\x6f\x6e\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x58\x65\uff0c\u539f\u5b50\u5e8f\x20\x35\x34\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u4e94\u9031\u671f\u3001\u7b2c\x20\x31\x38\x20\u65cf\x28\u7a00\u6709\u6c23\u9ad4\uff0c\x70\x20\u5340\u584a\x29\u3002\x31\x38\x39\x38\x20\u5e74\u7531\u82f1\u570b\u5316\u5b78\u5bb6\u62c9\u59c6\u9f4a\x28\x57\x69\x6c\x6c\x69\x61\x6d\x20\x52\x61\x6d\x73\x61\x79\x29\u8207\u7279\u62c9\u5f17\u65af\x28\x4d\x6f\x72\x72\x69\x73\x20\x54\x72\x61\x76\x65\x72\x73\x29\u5728\u6db2\u614b\u7a7a\u6c23\u5206\u993e\u7684\u6b98\u9918\u7269\u4e2d\u767c\u73fe\uff0c\u5176\u540d\u7a31\u53d6\u81ea\u5e0c\u81d8\u8a9e\u300c\x78\x65\x6e\x6f\x73\u300d\uff0c\u610f\u70ba\u300c\u964c\u751f\u4eba\u300d\u3002\u6c19\u5728\u5927\u6c23\u4e2d\u7684\u542b\u91cf\u6975\u4f4e\x28\u7d04\x20\x30\x2e\x30\x38\x37\x20\x70\x70\x6d\x29\uff0c\u4f46\u5728\u7a00\u6709\u6c23\u9ad4\u5bb6\u65cf\u4e2d\uff0c\u5b83\u4ee5\u6700\u8c50\u5bcc\u7684\u5316\u5b78\u6027\u8cea\u8207\u6700\u5177\u5f35\u529b\u7684\u7269\u7406\u7279\u6027\u8457\u7a31\uff0c\u662f\u958b\u555f\u300c\u7a00\u6709\u6c23\u9ad4\u5316\u5408\u7269\u300d\u7814\u7a76\u53f2\u7684\u95dc\u9375\u9470\u5319\u3002\x0a\x0a\u6c19\u7684\u96fb\u5b50\u7d44\u614b\u70ba\x20\x5b\x4b\x72\x5d\x34\x64\u00b9\u2070\x35\x73\u00b2\x35\x70\u2076\uff0c\u5177\u5099\u6975\u9ad8\u7a69\u5b9a\u6027\u7684\u516b\u9685\u9ad4\u7d50\u69cb\u3002\u7136\u800c\uff0c\u7531\u65bc\u5176\u96fb\u5b50\u6578\u591a\u4e14\u539f\u5b50\u534a\u5f91\u5927\uff0c\u539f\u5b50\u6838\u5c0d\u6700\u5916\u5c64\u96fb\u5b50\u7684\u675f\u7e1b\u76f8\u5c0d\u8f03\u5f31\uff0c\u5c0e\u81f4\u6c19\u5177\u6709\u7a00\u6709\u6c23\u9ad4\u4e2d\u8f03\u9ad8\u7684\u300c\u6975\u5316\u7387\u300d\u8207\u8f03\u4f4e\u7684\u300c\u7b2c\u4e00\u96fb\u96e2\u80fd\u300d\u3002\x31\x39\x36\x32\x20\u5e74\uff0c\u5316\u5b78\u5bb6\u5df4\u7279\u5229\u7279\x28\x4e\x65\x69\x6c\x20\x42\x61\x72\x74\x6c\x65\x74\x74\x29\u6210\u529f\u5408\u6210\u51fa\u7b2c\u4e00\u500b\u7a00\u6709\u6c23\u9ad4\u5316\u5408\u7269\u2014\u2014\u516d\u6c1f\u5408\u9251\u9178\u6c19\x28\x58\x65\x50\x74\x46\u2086\x29\uff0c\u9019\u9805\u7a81\u7834\u6027\u5be6\u9a57\u5fb9\u5e95\u63a8\u7ffb\u4e86\u7a00\u6709\u6c23\u9ad4\u7d55\u5c0d\u60f0\u6027\u7684\u50b3\u7d71\u6559\u689d\uff0c\u662f\u9ad8\u4e2d\u5316\u5b78\u5728\u4ecb\u7d39\u9031\u671f\u898f\u5f8b\u8207\u5316\u5b78\u9375\u7406\u8ad6\u767c\u5c55\u6642\u7684\u91cc\u7a0b\u7891\u6848\u4f8b\u3002\u76ee\u524d\u5df2\u767c\u73fe\u591a\u7a2e\u6c19\u7684\u6c1f\u5316\u7269\x28\u5982\x20\x58\x65\x46\u2082\u3001\x58\x65\x46\u2084\x29\u8207\u6c27\u5316\u7269\x28\u5982\x20\x58\x65\x4f\u2083\x29\u3002\x0a\x0a\u5728\u73fe\u4ee3\u5c16\u7aef\u79d1\u6280\u4e2d\uff0c\u6c19\u7684\u61c9\u7528\u9ad4\u73fe\u4e86\u5176\u6975\u9ad8\u7684\u5149\u96fb\u6548\u7387\u8207\u7269\u7406\u80fd\u91cf\u3002\u6c19\u71c8\u56e0\u80fd\u767c\u51fa\u6975\u5176\u660e\u4eae\u3001\u983b\u8b5c\u63a5\u8fd1\u65e5\u5149\u7684\u767d\u5149\uff0c\u88ab\u5ee3\u6cdb\u7528\u65bc\u5f71\u9662\u6295\u5f71\u6a5f\u3001\u9ad8\u901f\u651d\u5f71\u9583\u5149\u71c8\u8207\u6c7d\u8eca\u6c19\u6c23\u982d\u71c8\u3002\u5728\u822a\u592a\u9818\u57df\uff0c\u6c19\u662f\u300c\u96e2\u5b50\u63a8\u529b\u5668\u300d\x28\x49\x6f\x6e\x20\x74\x68\x72\x75\x73\x74\x65\x72\x29\u7684\u9996\u9078\u63a8\u9032\u5291\uff0c\u5229\u7528\u5176\u9ad8\u539f\u5b50\u91cf\u8207\u6613\u96fb\u96e2\u7684\u7279\u6027\uff0c\u63d0\u4f9b\u6975\u9ad8\u6bd4\u885d\u7684\u9577\u6548\u52d5\u529b\uff0c\u652f\u6490\u6df1\u7a7a\u63a2\u6e2c\u5668\u7684\u9577\u9014\u822a\u884c\u3002\u5728\u91ab\u5b78\u4e0a\uff0c\u9ad8\u7d14\u5ea6\u6c19\u6c23\u5c55\u73fe\u51fa\u5353\u8d8a\u7684\u9ebb\u9189\u6027\u80fd\uff0c\u4e14\u4e0d\u6703\u53c3\u8207\u4ee3\u8b1d\u3001\u526f\u4f5c\u7528\u4f4e\uff0c\u662f\u7406\u60f3\u4f46\u6210\u672c\u8f03\u9ad8\u7684\u300c\u74b0\u5883\u53cb\u5584\u9ebb\u9189\u5291\u300d\u3002\u6b64\u5916\uff0c\u5728\u6838\u7269\u7406\u4e2d\uff0c\u6db2\u6c19\u88ab\u7528\u65bc\u5efa\u69cb\u5de8\u5927\u7684\u63a2\u6e2c\u5668\uff0c\u4ee5\u641c\u5c0b\u795e\u7955\u7684\u6697\u7269\u8cea\u3002\x0a\x0a\u6c19\u5c55\u73fe\u4e86\u67d0\u4e9b\u53cd\u76f4\u89ba\u7684\u7269\u7406\u8207\u5316\u5b78\u884c\u70ba\u3002\u4f8b\u5982\uff0c\u5728\u8d85\u9ad8\u58d3\u689d\u4ef6\u4e0b\uff0c\u6c19\u53ef\u4ee5\u8f49\u5316\u70ba\u91d1\u5c6c\u614b\uff0c\u5448\u73fe\u51fa\u5c0e\u96fb\u6027\u3002\u5728\u5316\u5b78\u9375\u7d50\u65b9\u9762\uff0c\u4e8c\u6c1f\u5316\u6c19\x28\x58\x65\x46\u2082\x29\u5c55\u73fe\u4e86\u5178\u578b\u7684\u300c\u8d85\u50f9\u5206\u5b50\u300d\u7279\u5fb5\uff0c\u5176\u4e2d\u5fc3\u539f\u5b50\u6c19\u5468\u570d\u5b58\u5728\u5341\u500b\u50f9\u96fb\u5b50\uff0c\u9019\u6311\u6230\u4e86\u8def\u6613\u65af\u7d50\u69cb\u5f0f\u7684\u57fa\u790e\u9810\u6e2c\u3002\u6b64\u5916\uff0c\u5728\u5927\u6c23\u79d1\u5b78\u7814\u7a76\u4e2d\uff0c\u5730\u7403\u5927\u6c23\u5c64\u4e2d\u6c19\u542b\u91cf\u7684\u77ed\u7f3a\x28\u76f8\u5c0d\u65bc\u9695\u77f3\x29\u88ab\u7a31\u70ba\u300c\u907a\u5931\u7684\u6c19\u554f\u984c\u300d\uff0c\u5f15\u767c\u4e86\u5730\u7403\u8d77\u6e90\u8207\u5ca9\u77f3\u5708\u56fa\u6c2e\u56fa\u6c19\u6a5f\u5236\u7684\u6df1\u5ea6\u8faf\u8ad6\u3002\u9019\u7a2e\u5f9e\u5927\u6c23\u4e2d\u7a00\u8584\u7684\u964c\u751f\u4eba\u5230\u6311\u6230\u5316\u5b78\u9375\u6975\u9650\u4e26\u63a8\u52d5\u6df1\u7a7a\u822a\u884c\u8005\u7684\u8f49\u8b8a\uff0c\u7cbe\u78ba\u8a6e\u91cb\u4e86\u6c19\u5728\u9031\u671f\u8868\u672b\u7aef\u4e0d\u53ef\u5ffd\u8996\u7684\u7368\u7279\u5149\u8292\u3002",
  "\x43\x73":
    "\u92ab\x28\x43\x65\x73\x69\x75\x6d\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x43\x73\uff0c\u539f\u5b50\u5e8f\x20\x35\x35\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u516d\u9031\u671f\u3001\u7b2c\x20\x31\x20\u65cf\x28\u9e7c\u91d1\u5c6c\uff0c\x73\x20\u5340\u584a\x29\u3002\u5176\u540d\u7a31\u6e90\u65bc\u62c9\u4e01\u8a9e\u300c\x63\x61\x65\x73\x69\x75\x73\u300d\uff0c\u610f\u70ba\u300c\u5929\u85cd\u8272\u300d\uff0c\u5f97\u540d\u65bc\u5176\u5728\u5149\u8b5c\u4e2d\u7279\u5fb5\u6027\u7684\u5929\u85cd\u8272\u8b5c\u7dda\u3002\x31\x38\x36\x30\x20\u5e74\u7531\u5fb7\u570b\u5316\u5b78\u5bb6\u672c\u751f\x28\x52\x6f\x62\x65\x72\x74\x20\x42\x75\x6e\x73\x65\x6e\x29\u8207\u57fa\u5e0c\u970d\u592b\x28\x47\x75\x73\x74\x61\x76\x20\x4b\x69\x72\x63\x68\x68\x6f\x66\x66\x29\u5229\u7528\u65b0\u767c\u660e\u7684\u767c\u660e\u5149\u8b5c\u5100\u5728\u7926\u6cc9\u6c34\u4e2d\u767c\u73fe\u3002\u92ab\u662f\u7a69\u5b9a\u5143\u7d20\u4e2d\u91d1\u5c6c\u6d3b\u6027\u6700\u5f37\u3001\u96fb\u8ca0\u5ea6\u6700\u4f4e\x28\u7d04\x20\x30\x2e\x37\x39\x29\u7684\u6210\u54e1\u3002\u7531\u65bc\u5176\u6975\u9ad8\u7684\u53cd\u61c9\u6027\u8207\u7a00\u6709\u6027\uff0c\u92ab\u5728\u73fe\u4ee3\u7cbe\u5bc6\u7269\u7406\u8207\u822a\u592a\u52d5\u529b\u5b78\u4e2d\u5177\u6709\u7121\u53ef\u53d6\u4ee3\u7684\u5730\u4f4d\u3002\x0a\x0a\u5728\u5316\u5b78\u6027\u8cea\u4e0a\uff0c\u92ab\u7684\u96fb\u5b50\u7d44\u614b\u70ba\x20\x5b\x58\x65\x5d\x36\x73\u00b9\uff0c\u5176\u50f9\u96fb\u5b50\u53d7\u539f\u5b50\u6838\u675f\u7e1b\u6975\u5f31\uff0c\u7b2c\u4e00\u96fb\u96e2\u80fd\u70ba\u5168\u5143\u7d20\u6700\u4f4e\u3002\u9019\u4f7f\u5f97\u92ab\u5c55\u73fe\u51fa\u6975\u81f4\u7684\u9e7c\u91d1\u5c6c\u7279\u5fb5\uff1a\u5176\u706b\u7130\u53cd\u61c9\u5448\u73fe\u7279\u5fb5\u7684\u6de1\u7d2b\u8272\uff1b\u8207\u6c34\u53cd\u61c9\u7684\u5287\u70c8\u7a0b\u5ea6\u5448\u7206\u70b8\u6027\uff0c\u751a\u81f3\u5728\x20\x2d\x31\x31\x36\x20\u00b0\x43\x20\u7684\u51b0\u584a\u4e0a\u4e5f\u80fd\u767c\u751f\u53cd\u61c9\u3002\u5728\u53f0\u7063\u9ad8\u4e2d\u5316\u5b78\u63a2\u8a0e\u9031\u671f\u898f\u5f8b\u6642\uff0c\u92ab\u662f\u9a57\u8b49\u300c\u539f\u5b50\u534a\u5f91\u6700\u5927\u3001\u91d1\u5c6c\u6027\u6700\u5f37\u300d\u8da8\u52e2\u7684\u95dc\u9375\u6307\u6a19\u3002\u7531\u65bc\u5176\u6975\u6613\u5931\u53bb\u96fb\u5b50\uff0c\u92ab\u5177\u6709\u6975\u5927\u7684\u6a19\u6e96\u6c27\u5316\u96fb\u4f4d\x28\x45\u2070\x20\u2248\x20\x33\x2e\x30\x32\x20\x56\x29\uff0c\u662f\u6975\u5f37\u7684\u9084\u539f\u5291\u3002\u91d1\u5c6c\u92ab\u5fc5\u9808\u5bc6\u5c01\u65bc\u5145\u6709\u6c2c\u6c23\u7684\u5b89\u74ff\u74f6\u6216\u4fdd\u5b58\u5728\u6975\u9ad8\u771f\u7a7a\u74b0\u5883\u4e0b\u3002\x0a\x0a\u5728\u73fe\u4ee3\u61c9\u7528\u4e2d\uff0c\u92ab\u662f\u5168\u7403\u6642\u9593\u57fa\u6e96\u7684\u5b88\u8b77\u8005\u3002\x31\x39\x36\x37\x20\u5e74\u8d77\uff0c\u570b\u969b\u55ae\u4f4d\u5236\u5c07\u300c\u79d2\u300d\u5b9a\u7fa9\u70ba\u92ab\x2d\x31\x33\x33\x20\u539f\u5b50\u57fa\u614b\u7684\u5169\u500b\u8d85\u7cbe\u7d30\u80fd\u968e\u9593\u8e8d\u9077\u6240\u5c0d\u61c9\u8f3b\u5c04\u5468\u671f\u7684\x20\x39\x2c\x31\x39\x32\x2c\x36\x33\x31\x2c\x37\x37\x30\x20\u500d\uff0c\u9019\u4f7f\u5f97\u92ab\u539f\u5b50\u9418\u6210\u70ba\u885b\u661f\u5b9a\u4f4d\u7cfb\u7d71\x28\x47\x50\x53\x29\u8207\u96fb\u8a0a\u540c\u6b65\u7684\u6838\u5fc3\u3002\u5728\u80fd\u6e90\u8207\u5149\u96fb\u9818\u57df\uff0c\u7531\u65bc\u92ab\u5177\u6709\u6975\u4f4e\u7684\u529f\u51fd\u6578\x28\x57\x6f\x72\x6b\x20\x66\x75\x6e\x63\x74\x69\x6f\x6e\x29\uff0c\u6975\u6613\u53d7\u5149\u6fc0\u767c\u91cb\u653e\u96fb\u5b50\uff0c\u56e0\u6b64\u88ab\u5ee3\u6cdb\u7528\u65bc\u5149\u96fb\u7ba1\u3001\u7d05\u5916\u7dda\u7167\u660e\u5668\u53ca\u5149\u96fb\u500d\u589e\u7ba1\u3002\u6b64\u5916\uff0c\u92ab\u96e2\u5b50\x28\x43\x73\u207a\x29\u56e0\u5176\u8cea\u91cf\u5927\u4e14\u6613\u65bc\u96fb\u96e2\uff0c\u5728\u822a\u592a\u5de5\u7a0b\u4e2d\u88ab\u4f5c\u70ba\u96e2\u5b50\u63a8\u9032\u5668\u7684\u63a8\u9032\u5291\uff0c\u70ba\u6df1\u7a7a\u63a2\u6e2c\u5668\u63d0\u4f9b\u5fae\u5c0f\u800c\u6301\u7e8c\u7684\u52d5\u529b\u3002\x0a\x0a\u92ab\u5728\u7269\u7406\u7279\u6027\u4e0a\u5c55\u73fe\u51fa\u986f\u8457\u7684\u6975\u9650\u7279\u5fb5\u3002\u5b83\u662f\u5c11\u6578\u5728\u63a5\u8fd1\u5ba4\u6eab\u5373\u7194\u5316\u7684\u91d1\u5c6c\x28\u7194\u9ede\u50c5\x20\x32\x38\x2e\x34\x34\x20\u00b0\x43\x29\uff0c\u5728\u6eab\u6696\u7684\u74b0\u5883\u4e0b\u6703\u5448\u73fe\u91d1\u8272\u7684\u6db2\u614b\u5149\u6fa4\u3002\u6709\u8da3\u7684\u662f\uff0c\u96d6\u7136\u92ab\u91d1\u5c6c\u6975\u5176\u6d3b\u6f51\uff0c\u4f46\u5176\u540c\u4f4d\u7d20\x20\u00b9\u00b3\u2077\x43\x73\x20\u662f\u6838\u5206\u88c2\u7684\u91cd\u8981\u526f\u7522\u7269\uff0c\u5177\u5099\u5f37\u653e\u5c04\u6027\u4e14\u6613\u8207\u6c34\u53cd\u61c9\u9032\u5165\u5faa\u74b0\uff0c\u56e0\u6b64\u5728\u6838\u74b0\u5883\u76e3\u6e2c\u4e2d\u662f\u95dc\u9375\u7684\u6307\u6a19\u7269\u7a2e\u3002\u5728\u5316\u5b78\u7814\u7a76\u4e2d\uff0c\u6c1f\u5316\u92ab\x28\x43\x73\x46\x29\u5e38\u4f5c\u70ba\u63d0\u4f9b\u6d3b\u6027\u6c1f\u96e2\u5b50\u7684\u4f86\u6e90\uff0c\u56e0\u5176\u96e2\u5b50\u534a\u5f91\u5927\u5c0e\u81f4\u6676\u683c\u80fd\u76f8\u5c0d\u8f03\u4f4e\uff0c\u4f7f\u6c1f\u96e2\u5b50\u66f4\u6613\u65bc\u53c3\u8207\u53cd\u61c9\u3002\u9019\u7a2e\u5f9e\u5b9a\u7fa9\u6642\u9593\u7cbe\u5ea6\u7684\u6c89\u7a69\u5230\u63a5\u89f8\u6c34\u5206\u6642\u7684\u72c2\u66b4\u53cd\u61c9\uff0c\u7cbe\u78ba\u8a6e\u91cb\u4e86\u92ab\u5728\u5143\u7d20\u9031\u671f\u8868\u5e95\u7aef\u7684\u7368\u7279\u6975\u7aef\u6027\u683c\u3002",
  "\x42\x61":
    "\u92c7\x28\x42\x61\x72\x69\x75\x6d\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x42\x61\uff0c\u539f\u5b50\u5e8f\x20\x35\x36\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u516d\u9031\u671f\u3001\u7b2c\x20\x32\x20\u65cf\x28\u9e7c\u571f\u91d1\u5c6c\uff0c\x73\x20\u5340\u584a\x29\u3002\u5176\u540d\u7a31\u6e90\u65bc\u5e0c\u81d8\u8a9e\u300c\x62\x61\x72\x79\x73\u300d\uff0c\u610f\u70ba\u300c\u6c89\u91cd\u300d\uff0c\u5f97\u540d\u65bc\u5176\u5e38\u898b\u7926\u77f3\u91cd\u6676\u77f3\x28\x42\x61\x53\x4f\u2084\x29\u7684\u9ad8\u5bc6\u5ea6\u3002\x31\x38\x30\x38\x20\u5e74\u7531\u82f1\u570b\u5316\u5b78\u5bb6\u6234\u7dad\x28\x48\x75\x6d\x70\x68\x72\x79\x20\x44\x61\x76\x79\x29\u900f\u904e\u96fb\u89e3\u7194\u878d\u92c7\u9e7d\u9996\u6b21\u5206\u96e2\u3002\u92c7\u5728\u5730\u6bbc\u4e2d\u5206\u5e03\u5ee3\u6cdb\uff0c\u662f\u7814\u7a76\u9e7c\u571f\u91d1\u5c6c\u7531\u4e0a\u81f3\u4e0b\u6027\u8cea\u905e\u8b8a\x28\u5982\u6eb6\u89e3\u5ea6\u898f\u5f8b\x29\u7684\u6307\u6a19\u5143\u7d20\uff0c\u4ea6\u662f\u6750\u6599\u79d1\u5b78\u4e2d\u88fd\u9020\u8d85\u5c0e\u9ad4\u8207\u771f\u7a7a\u96fb\u5b50\u5143\u4ef6\u7684\u91cd\u8981\u539f\u6599\u3002\x0a\x0a\u5728\u5316\u5b78\u884c\u70ba\u4e0a\uff0c\u92c7\u7684\u96fb\u5b50\u7d44\u614b\u70ba\x20\x5b\x58\x65\x5d\x36\x73\u00b2\uff0c\u50be\u5411\u5931\u53bb\u5169\u500b\u50f9\u96fb\u5b50\u5f62\u6210\u7a69\u5b9a\u7684\x20\x42\x61\u00b2\u207a\u3002\u92c7\u7684\u91d1\u5c6c\u6d3b\u6027\u5728\u9e7c\u571f\u91d1\u5c6c\u4e2d\u6975\u9ad8\uff0c\u5728\u7a7a\u6c23\u4e2d\u6703\u8fc5\u901f\u6c27\u5316\u5f62\u6210\u6c27\u5316\u92c7\x28\x42\x61\x4f\x29\u8207\u6c2e\u5316\u92c7\x28\x42\x61\u2083\x4e\u2082\x29\uff0c\u56e0\u6b64\u5fc5\u9808\u4fdd\u5b58\u5728\u7164\u6cb9\u6216\u77f3\u881f\u6cb9\u4e2d\u3002\u5728\u9ad8\u4e2d\u5316\u5b78\u63a2\u8a0e\u6c89\u6fb1\u53cd\u61c9\u6642\uff0c\u92c7\u96e2\u5b50\u662f\u6aa2\u9a57\u786b\u9178\u6839\x28\x53\x4f\u2084\u00b2\u207b\x29\u7684\u91cd\u8981\u8a66\u5291\uff0c\u7522\u751f\u7684\u767d\u8272\u786b\u9178\u92c7\x28\x42\x61\x53\x4f\u2084\x29\u6c89\u6fb1\u5373\u4f7f\u5728\u5f37\u9178\u4e2d\u4e5f\u4e0d\u6eb6\u89e3\uff0c\u9019\u8207\u78b3\u9178\u92c7\x28\x42\x61\x43\x4f\u2083\x29\u5f62\u6210\u9bae\u660e\u5c0d\u6bd4\u3002\u6b64\u5916\uff0c\u92c7\u7684\u706b\u7130\u53cd\u61c9\u5448\u73fe\u7279\u5fb5\u7684\u860b\u679c\u7da0\u8272\uff0c\u5e38\u7528\u65bc\u7159\u706b\u88fd\u9020\u4ee5\u63d0\u4f9b\u7279\u5b9a\u7684\u8272\u6fa4\u3002\x0a\x0a\u5728\u91ab\u5b78\u8207\u6750\u6599\u79d1\u5b78\u9818\u57df\uff0c\u92c7\u5c55\u73fe\u4e86\u6975\u5927\u7684\u8de8\u754c\u61c9\u7528\u50f9\u503c\u3002\u786b\u9178\u92c7\u56e0\u5176\u9ad8\u539f\u5b50\u5e8f\u80fd\u6709\u6548\u963b\u64cb\x20\x58\x20\u5c04\u7dda\uff0c\u4e14\u5728\u80c3\u9178\u4e2d\u5b8c\u5168\u4e0d\u6eb6\u89e3\u800c\u4e0d\u5177\u6bd2\u6027\uff0c\u88ab\u5ee3\u6cdb\u7528\u4f5c\u6d88\u5316\u9053\u651d\u5f71\u7684\u9020\u5f71\u5291\x28\u4fd7\u7a31\u300c\u92c7\u9910\u300d\x29\u3002\u5728\u5c16\u7aef\u79d1\u6280\u65b9\u9762\uff0c\u92c7\u662f\u88fd\u9020\u9ad8\u6eab\u8d85\u5c0e\u9ad4\u300c\u91d4\u92c7\u9285\u6c27\u300d\x28\x59\x42\x43\x4f\x29\u7684\u95dc\u9375\u6210\u5206\uff0c\u9019\u985e\u6750\u6599\u5728\u6db2\u6c2e\u6eab\u5ea6\u4e0b\u5373\u53ef\u5c55\u73fe\u96f6\u96fb\u963b\u7279\u6027\u3002\u5728\u96fb\u5b50\u5de5\u696d\u4e2d\uff0c\u91d1\u5c6c\u92c7\u5e38\u88ab\u88fd\u6210\u771f\u7a7a\u7ba1\u7684\u300c\u6d88\u6c23\u5291\u300d\x28\x47\x65\x74\x74\x65\x72\x29\uff0c\u5229\u7528\u5176\u6975\u5f37\u7684\u5316\u5b78\u6d3b\u6027\u5438\u6536\u6b98\u9918\u7684\u5fae\u91cf\u6c27\u3001\u6c2e\u6c23\u9ad4\uff0c\u4ee5\u7dad\u6301\u7ba1\u5167\u7684\u9ad8\u5ea6\u771f\u7a7a\u74b0\u5883\u3002\x0a\x0a\u92c7\u5316\u5408\u7269\u5c55\u73fe\u4e86\u986f\u8457\u7684\u7269\u7406\u6027\u8cea\u8207\u6bd2\u6027\u77db\u76fe\u3002\u96d6\u7136\u786b\u9178\u92c7\u5728\u81e8\u5e8a\u4e0a\u6975\u5176\u5b89\u5168\uff0c\u4f46\u6240\u6709\u53ef\u6eb6\u6027\u7684\u92c7\u9e7d\x28\u5982\u6c2f\u5316\u92c7\x29\u7686\u5177\u5099\u5287\u6bd2\uff0c\u6703\u5e72\u64fe\u795e\u7d93\u50b3\u5c0e\u8207\u808c\u8089\u529f\u80fd\uff0c\u9019\u7a2e\u300c\u6eb6\u89e3\u5ea6\u6c7a\u5b9a\u5b89\u5168\u6027\u300d\u7684\u7279\u5fb5\u662f\u5316\u5b78\u5b89\u5168\u6559\u80b2\u4e2d\u7684\u7d93\u5178\u6848\u4f8b\u3002\u6709\u8da3\u7684\u662f\uff0c\u91cd\u6676\u77f3\x28\x42\x61\x53\x4f\u2084\x29\u5728\u77f3\u6cb9\u63a2\u52d8\u4e2d\u88ab\u5927\u91cf\u7528\u4f5c\u947d\u4e95\u6ce5\u6f3f\u7684\u52a0\u91cd\u5291\uff0c\u5229\u7528\u5176\u9ad8\u5bc6\u5ea6\u5354\u52a9\u5e73\u8861\u5730\u5e95\u58d3\u529b\u3002\u6b64\u5916\uff0c\u9226\u9178\u92c7\x28\x42\x61\x54\x69\x4f\u2083\x29\u662f\u4e00\u7a2e\u5177\u5099\u5f37\u9435\u96fb\u6027\u8207\u58d3\u96fb\u6548\u61c9\u7684\u9676\u74f7\u6750\u6599\uff0c\u5ee3\u6cdb\u61c9\u7528\u65bc\u96fb\u5bb9\u5668\u8207\u8d85\u97f3\u6ce2\u63db\u80fd\u5668\u3002\u9019\u7a2e\u5f9e\u5b88\u8b77\u4eba\u9ad4\u5065\u5eb7\u7684\u9020\u5f71\u6280\u8853\u5230\u652f\u6490\u96fb\u529b\u7cfb\u7d71\u7684\u7cbe\u5bc6\u96fb\u5bb9\uff0c\u9ad4\u73fe\u4e86\u92c7\u5728\u9031\u671f\u8868\u4e2d\u539a\u91cd\u4e14\u591a\u5143\u7684\u529f\u80fd\u5b9a\u4f4d\u3002",
  "\x4c\x61":
    "\u946d\x28\x4c\x61\x6e\x74\x68\x61\x6e\x75\x6d\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x4c\x61\uff0c\u539f\u5b50\u5e8f\x20\x35\x37\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u516d\u9031\u671f\u3001\u7b2c\x20\x33\x20\u65cf\x28\u6216\u8996\u70ba\u946d\u7cfb\u5143\u7d20\u7684\u958b\u7aef\uff0c\x64\x2f\x66\x20\u5340\u584a\x29\u3002\u5176\u540d\u7a31\u6e90\u65bc\u5e0c\u81d8\u8a9e\u300c\x6c\x61\x6e\x74\x68\x61\x6e\x65\x69\x6e\u300d\uff0c\u610f\u70ba\u300c\u96b1\u85cf\u300d\uff0c\u56e0\u5176\u5728\x20\x31\x38\x33\x39\x20\u5e74\u7531\u745e\u5178\u5316\u5b78\u5bb6\u83ab\u6851\u5fb7\x28\x43\x61\x72\x6c\x20\x47\x75\x73\x74\x61\x66\x20\x4d\x6f\x73\x61\x6e\x64\x65\x72\x29\u5f9e\u785d\u9178\u9230\u7684\u96dc\u8cea\u4e2d\u767c\u73fe\u6642\uff0c\u66fe\u9577\u671f\u8eb2\u907f\u5316\u5b78\u5bb6\u7684\u8fa8\u8b58\u3002\u946d\u662f\u7a00\u571f\u5143\u7d20\u4e2d\u6975\u5177\u4ee3\u8868\u6027\u7684\u6210\u54e1\uff0c\u5176\u55ae\u8cea\u5448\u9280\u767d\u8272\u3001\u8cea\u5730\u67d4\u8edf\uff0c\u662f\u73fe\u4ee3\u5149\u5b78\u73bb\u7483\u8207\u4e8c\u6b21\u96fb\u6c60\u6280\u8853\u4e2d\u63d0\u5347\u6750\u6599\u6027\u80fd\u7684\u6838\u5fc3\u6dfb\u52a0\u5143\u7d20\u3002\x0a\x0a\u5728\u96fb\u5b50\u7d50\u69cb\u4e0a\uff0c\u946d\u7684\u7d44\u614b\u70ba\x20\x5b\x58\x65\x5d\x35\x64\u00b9\x36\x73\u00b2\uff0c\u5728\u5316\u5b78\u53cd\u61c9\u4e2d\u5c55\u73fe\u51fa\u7a69\u5b9a\u7684\x20\x2b\x33\x20\u6c27\u5316\u614b\u3002\u7531\u65bc\u5176\u96e2\u5b50\u534a\u5f91\u5728\u946d\u7cfb\u5143\u7d20\u4e2d\u6700\u5927\uff0c\u946d\u8868\u73fe\u51fa\u8f03\u5f37\u7684\u5316\u5b78\u6d3b\u6027\uff0c\u5728\u7a7a\u6c23\u4e2d\u6703\u8fc5\u901f\u8b8a\u6697\u4e26\u71c3\u71d2\uff0c\u8207\u6c34\u53cd\u61c9\u5247\u6703\u91cb\u653e\u51fa\u6c2b\u6c23\u3002\u5728\u9ad8\u4e2d\u5316\u5b78\u63a2\u8a0e\u9031\u671f\u5f8b\u898f\u5f8b\u6642\uff0c\u946d\u5e38\u4f5c\u70ba\u4ecb\u7d39\u300c\u946d\u7cfb\u6536\u7e2e\u300d\x28\x4c\x61\x6e\x74\x68\x61\x6e\x69\x64\x65\x20\x43\x6f\x6e\x74\x72\x61\x63\x74\x69\x6f\x6e\x29\u7684\u8d77\u9ede\u3002\u96d6\u7136\u946d\u672c\u8eab\u4e0d\u542b\x20\x34\x66\x20\u96fb\u5b50\uff0c\u4f46\u5176\u5316\u5b78\u884c\u70ba\u8207\u5f8c\u7e8c\x20\x31\x34\x20\u500b\x20\x34\x66\x20\u5143\u7d20\u9ad8\u5ea6\u4e00\u81f4\uff0c\u5177\u5099\u5f37\u70c8\u7684\u9084\u539f\u6027\u8207\u512a\u7570\u7684\u914d\u5408\u4f4d\u5316\u5b78\u7279\u6027\uff0c\u5176\u5316\u5408\u7269\u901a\u5e38\u5448\u73fe\u7121\u8272\u4e14\u4e0d\u5177\u9806\u78c1\u6027\u3002\x0a\x0a\u946d\u5728\u73fe\u4ee3\u80fd\u6e90\u8207\u5149\u96fb\u79d1\u6280\u4e2d\u626e\u6f14\u8457\u4e0d\u53ef\u6216\u7f3a\u7684\u89d2\u8272\u3002\u5728\u4e8c\u6b21\u96fb\u6c60\u9818\u57df\uff0c\u946d\u93b3\u5408\u91d1\x28\x4c\x61\x4e\x69\u2085\x29\u662f\u93b3\u6c2b\u96fb\u6c60\x28\x4e\x69\x2d\x4d\x48\x29\u8ca0\u6975\u6750\u6599\u7684\u6838\u5fc3\uff0c\u5229\u7528\u5176\u5353\u8d8a\u7684\u300c\u5132\u6c2b\u80fd\u529b\u300d\uff0c\x20\x4c\x61\x4e\x69\u2085\x20\u80fd\u5728\u6eab\u548c\u689d\u4ef6\u4e0b\u5438\u7d0d\u4e26\u91cb\u653e\u5927\u91cf\u6c2b\u539f\u5b50\uff0c\u9019\u7a2e\u56fa\u614b\u5132\u6c2b\u6280\u8853\u5927\u5e45\u63d0\u5347\u4e86\u6df7\u5408\u52d5\u529b\u8eca\u7684\u5b89\u5168\u6027\u8207\u6548\u7387\u3002\u5728\u5149\u5b78\u5de5\u7a0b\u4e2d\uff0c\u6c27\u5316\u946d\x28\x4c\x61\u2082\x4f\u2083\x29\u88ab\u7528\u65bc\u88fd\u9020\u9ad8\u6298\u5c04\u7387\u3001\u4f4e\u8272\u6563\u7684\u7279\u6b8a\u5149\u5b78\u73bb\u7483\uff0c\u9019\u5c0d\u65bc\u76f8\u6a5f\u93e1\u982d\u3001\u986f\u5fae\u93e1\u8207\u7cbe\u5bc6\u5100\u5668\u7684\u5149\u5b78\u88dc\u511f\u81f3\u95dc\u91cd\u8981\uff0c\u80fd\u6709\u6548\u6e1b\u5c11\u8272\u5dee\u4e26\u7e2e\u5c0f\u93e1\u982d\u9ad4\u7a4d\u3002\x0a\x0a\u95dc\u65bc\u946d\u7684\u6750\u6599\u79d1\u5b78\u7279\u5fb5\uff0c\u5b83\u5c55\u73fe\u51fa\u5353\u8d8a\u7684\u50ac\u5316\u80fd\u529b\u3002\u5728\u77f3\u6cb9\u7cbe\u7149\u4e2d\uff0c\u946d\u88ab\u7528\u4f5c\u6d41\u9ad4\u50ac\u5316\u88c2\u5316\x28\x46\x43\x43\x29\u50ac\u5316\u5291\u7684\u7a69\u5b9a\u5291\uff0c\u80fd\u63d0\u9ad8\u6c7d\u6cb9\u7684\u7522\u91cf\u8207\u71b1\u7a69\u5b9a\u6027\u3002\u6709\u8da3\u7684\u662f\uff0c\u78b3\u9178\u946d\x28\x4c\x61\u2082\x43\x4f\u2083\x29\u5728\u91ab\u5b78\u4e0a\u88ab\u7528\u4f5c\u300c\u78f7\u9178\u9e7d\u7d50\u5408\u5291\u300d\uff0c\u5354\u52a9\u6d17\u814e\u60a3\u8005\u964d\u4f4e\u9ad4\u5167\u7684\u78f7\u6fc3\u5ea6\uff0c\u5c55\u73fe\u5176\u5728\u751f\u91ab\u9818\u57df\u7684\u7279\u6b8a\u50f9\u503c\u3002\u6b64\u5916\uff0c\u91d1\u5c6c\u946d\u8207\u9435\u3001\u9382\u7d44\u6210\u7684\u6df7\u5408\u7a00\u571f\u91d1\u5c6c\x28\x4d\x69\x73\x63\x68\x6d\x65\x74\x61\x6c\x29\u5177\u5099\u6975\u4f73\u7684\u8457\u706b\u6027\uff0c\u662f\u88fd\u9020\u6253\u706b\u6a5f\u71e7\u77f3\u7684\u4e3b\u8981\u6210\u5206\u3002\u9019\u7a2e\u5f9e\u96b1\u8eab\u65bc\u7926\u77f3\u4e2d\u7684\u6b77\u53f2\u5230\u652f\u6490\u7da0\u8272\u80fd\u6e90\u8207\u7cbe\u5bc6\u5149\u5b78\u7684\u73fe\u72c0\uff0c\u7cbe\u78ba\u8a6e\u91cb\u4e86\u946d\u5728\u7a00\u571f\u5bb6\u65cf\u4e2d\u958b\u62d3\u8005\u7684\u5730\u4f4d\u3002",
  "\x43\x65":
    "\u9230\x28\x43\x65\x72\x69\x75\x6d\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x43\x65\uff0c\u539f\u5b50\u5e8f\x20\x35\x38\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u516d\u9031\u671f\u3001\u946d\u7cfb\u5143\u7d20\x28\x66\x20\u5340\u584a\x29\u3002\u5176\u540d\u7a31\u6e90\u65bc\x20\x31\x38\x30\x31\x20\u5e74\u767c\u73fe\u7684\u5c0f\u884c\u661f\u300c\u7a40\u795e\u661f\u300d\x28\x43\x65\x72\x65\x73\x29\uff0c\u800c\u8a72\u661f\u540d\u53c8\u53d6\u81ea\u7f85\u99ac\u7a40\u7269\u5973\u795e\u3002\x31\x38\x30\x33\x20\u5e74\u7531\u745e\u5178\u5316\u5b78\u5bb6\u8c9d\u9f4a\u91cc\u70cf\u65af\x28\x4a\u00f6\x6e\x73\x20\x4a\x61\x63\x6f\x62\x20\x42\x65\x72\x7a\x65\x6c\x69\x75\x73\x29\u8207\u514b\u62c9\u666e\u7f85\u7279\x28\x4d\x61\x72\x74\x69\x6e\x20\x48\x65\x69\x6e\x72\x69\x63\x68\x20\x4b\x6c\x61\x70\x72\x6f\x74\x68\x29\u5206\u5225\u7368\u7acb\u767c\u73fe\u3002\u9230\u662f\u7a00\u571f\u5143\u7d20\u4e2d\u5730\u6bbc\u8c50\u5ea6\u6700\u9ad8\u7684\u6210\u54e1\x28\u751a\u81f3\u9ad8\u65bc\u9285\u8207\u932b\x29\uff0c\u5177\u5099\u7368\u7279\u7684\u96d9\u6c27\u5316\u614b\u7279\u6027\uff0c\u662f\u74b0\u5883\u50ac\u5316\u8207\u7cbe\u5bc6\u7814\u78e8\u6280\u8853\u4e2d\u7684\u6838\u5fc3\u5143\u7d20\u3002\x0a\x0a\u9230\u7684\u96fb\u5b50\u7d44\u614b\u70ba\x20\x5b\x58\x65\x5d\x34\x66\u00b9\x35\x64\u00b9\x36\x73\u00b2\uff0c\u6700\u986f\u8457\u7684\u5316\u5b78\u7279\u5fb5\u662f\u5176\u5728\u946d\u7cfb\u5143\u7d20\u4e2d\u6975\u5176\u7f55\u898b\u7684\x20\x2b\x34\x20\u7a69\u5b9a\u6c27\u5316\u614b\x28\x43\x65\u2074\u207a\x29\uff0c\u9019\u6e90\u65bc\u5176\u5931\u53bb\u56db\u500b\u96fb\u5b50\u5f8c\u80fd\u9054\u6210\u7a69\u5b9a\u7684\u7a7a\u6bbc\u5c64\u7d44\u614b\u3002\u5728\u9ad8\u4e2d\u5316\u5b78\u63a2\u8a0e\u6c27\u5316\u9084\u539f\u6ef4\u5b9a\u6642\uff0c\u9230\u9e7d\x28\u5982\u786b\u9178\u9230\x29\u662f\u5e38\u7528\u7684\u5f37\u6c27\u5316\u5291\uff0c\u5176\u6a19\u6e96\u9084\u539f\u96fb\u4f4d\x28\x45\u2070\x20\u2248\x20\x31\x2e\x36\x31\x20\x56\x29\u9ad8\u65bc\u8a31\u591a\u904e\u6e21\u91d1\u5c6c\u3002\u9230\u80fd\u8f15\u6613\u5728\x20\x2b\x33\x20\u8207\x20\x2b\x34\x20\u50f9\u4e4b\u9593\u8f49\u63db\uff0c\u9019\u7a2e\u6c27\u5316\u9084\u539f\u5faa\u74b0\u4f7f\u5176\u5728\u50ac\u5316\u53cd\u61c9\u4e2d\u8868\u73fe\u5353\u8d8a\u3002\u91d1\u5c6c\u9230\u5177\u5099\u9435\u7070\u8272\u5149\u6fa4\uff0c\u6027\u8cea\u6d3b\u6f51\uff0c\u53d7\u6469\u64e6\u6216\u649e\u64ca\u5373\u6613\u7522\u751f\u706b\u82b1\uff0c\u5c55\u73fe\u5f37\u70c8\u7684\u7126\u78f7\x28\x50\x79\x72\x6f\x70\x68\x6f\x72\x69\x63\x29\u7279\u6027\u3002\x0a\x0a\u5728\u73fe\u4ee3\u61c9\u7528\u4e2d\uff0c\u9230\u662f\u74b0\u5883\u5de5\u7a0b\u7684\u885b\u58eb\u3002\u5728\u6c7d\u8eca\u6392\u653e\u7cfb\u7d71\u7684\u300c\u4e09\u5143\u89f8\u5a92\u8f49\u5316\u5668\u300d\u4e2d\uff0c\u4e8c\u6c27\u5316\u9230\x28\x43\x65\x4f\u2082\x29\u626e\u6f14\u8457\u95dc\u9375\u7684\u5132\u6c27\x28\x4f\x78\x79\x67\x65\x6e\x20\x53\x74\x6f\x72\x61\x67\x65\x20\x43\x61\x70\x61\x63\x69\x74\x79\x29\u89d2\u8272\uff1a\u7576\u71c3\u71d2\u5ba4\u8ca7\u6c27\u6642\uff0c\u5b83\u91cb\u653e\u6c27\u6c23\u6c27\u5316\u4e00\u6c27\u5316\u78b3\uff1b\u7576\u5bcc\u6c27\u6642\u5247\u5438\u6536\u9918\u6c27\u3002\u6b64\u5916\uff0c\u4e8c\u6c27\u5316\u9230\u4ea6\u662f\u534a\u5c0e\u9ad4\u88fd\u7a0b\u4e2d\u300c\u5316\u5b78\u6a5f\u68b0\u5e73\u5766\u5316\u300d\x28\x43\x4d\x50\x29\u8207\u5149\u5b78\u93e1\u7247\u7814\u78e8\u7684\u9996\u9078\u62cb\u5149\u5291\uff0c\u5229\u7528\u5176\u5316\u5b78\u8150\u8755\u8207\u7269\u7406\u78e8\u524a\u7684\u5354\u540c\u4f5c\u7528\uff0c\u9054\u6210\u5948\u7c73\u7d1a\u7684\u5e73\u6574\u5ea6\u3002\u5728\u7d2b\u5916\u5149\u9632\u8b77\u65b9\u9762\uff0c\u4e8c\u6c27\u5316\u9230\u80fd\u6709\u6548\u5438\u6536\u7d2b\u5916\u7dda\uff0c\u5ee3\u6cdb\u61c9\u7528\u65bc\u73bb\u7483\u5de5\u696d\u8207\u90e8\u5206\u9632\u66ec\u5857\u6599\u4e2d\u3002\x0a\x0a\u9230\u5c55\u73fe\u51fa\u67d0\u4e9b\u8207\u6c27\u9ad8\u5ea6\u89aa\u548c\u7684\u7279\u7570\u7269\u7406\u73fe\u8c61\u3002\u4e8c\u6c27\u5316\u9230\u7684\u6676\u9ad4\u7d50\u69cb\u5728\u767c\u751f\u7f3a\u6c27\u6642\uff0c\u6703\u7522\u751f\u5927\u91cf\u7684\u6c27\u7a7a\u4f4d\u800c\u4e0d\u5d29\u584c\uff0c\u9019\u7a2e\u9ad8\u6c27\u79fb\u52d5\u7387\u4f7f\u5176\u5728\u56fa\u614b\u6c27\u5316\u7269\u71c3\u6599\u96fb\u6c60\x28\x53\x4f\x46\x43\x29\u4e2d\u4f5c\u70ba\u96fb\u89e3\u8cea\u6216\u96fb\u6975\u6750\u6599\u5177\u6709\u5de8\u5927\u6f5b\u529b\u3002\u6709\u8da3\u7684\u662f\uff0c\u96d6\u7136\u9230\u662f\u91d1\u5c6c\uff0c\u4f46\u5c07\u5176\u52a0\u5165\u9435\u5408\u91d1\u88fd\u6210\u7684\u6df7\u5408\u7a00\u571f\x28\x4d\x69\x73\x63\x68\x6d\x65\x74\x61\x6c\x29\u662f\u6253\u706b\u6a5f\u71e7\u77f3\u7684\u4e3b\u8981\u6210\u5206\u3002\u6b64\u5916\uff0c\u9230\u7684\u6c27\u5316\u7269\u5728\u4e0d\u540c\u50f9\u614b\u4e0b\u6703\u5448\u73fe\u5f9e\u9ec3\u8272\x28\x2b\x34\x29\u5230\u767d\u8272\x28\x2b\x33\x29\u7684\u984f\u8272\u8b8a\u5316\uff0c\u9019\u7a2e\u8b8a\u8272\u73fe\u8c61\u5e38\u88ab\u7528\u65bc\u9676\u74f7\u8207\u73bb\u7483\u7684\u8457\u8272\u3002\u9019\u7a2e\u5f9e\u661f\u7a7a\u4e4b\u540d\u5230\u6e05\u9664\u5ee2\u6c23\u6c61\u67d3\u7684\u6838\u5fc3\u89d2\u8272\uff0c\u7cbe\u78ba\u9ad4\u73fe\u4e86\u9230\u5728\u7a00\u571f\u5143\u7d20\u4e2d\u5be6\u7528\u6027\u6700\u9ad8\u4e14\u6027\u8cea\u6700\u70ba\u52d5\u614b\u7684\u7279\u5fb5\u3002",
  "\x50\x72":
    "\u9420\x28\x50\x72\x61\x73\x65\x6f\x64\x79\x6d\x69\x75\x6d\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x50\x72\uff0c\u539f\u5b50\u5e8f\x20\x35\x39\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u516d\u9031\u671f\u3001\u946d\u7cfb\u5143\u7d20\x28\x66\x20\u5340\u584a\x29\u3002\u5176\u540d\u7a31\u6e90\u65bc\u5e0c\u81d8\u8a9e\u300c\x70\x72\x61\x73\x69\x6f\x73\u300d\x28\u97ed\u83dc\u7da0\x29\u8207\u300c\x64\x69\x64\x79\x6d\x6f\x73\u300d\x28\u96d9\u80de\u80ce\x29\u3002\x31\x38\x38\x35\x20\u5e74\u7531\u5967\u5730\u5229\u5316\u5b78\u5bb6\u97cb\u723e\u65af\u5df4\u8d6b\x28\x43\x61\x72\x6c\x20\x41\x75\x65\x72\x20\x76\x6f\x6e\x20\x57\x65\x6c\x73\x62\x61\x63\x68\x29\u6210\u529f\u5c07\u7576\u6642\u8a8d\u70ba\u662f\u55ae\u4e00\u5143\u7d20\u7684\u300c\u91f9\u9420\u6df7\u5408\u7269\u300d\x28\x44\x69\x64\x79\x6d\x69\x75\x6d\x29\u5206\u96e2\uff0c\u8b49\u660e\u5176\u7531\u9420\u8207\u91f9\u5169\u7a2e\u5143\u7d20\u7d44\u6210\u3002\u9420\u662f\u4e00\u7a2e\u9280\u767d\u8272\u7684\u8edf\u91d1\u5c6c\uff0c\u5316\u5b78\u6027\u8cea\u6d3b\u6f51\uff0c\u5728\u7a7a\u6c23\u4e2d\u6703\u7de9\u6162\u5f62\u6210\u7da0\u8272\u7684\u6c27\u5316\u5c64\uff0c\u662f\u88fd\u9020\u7279\u6b8a\u5149\u5b78\u73bb\u7483\u8207\u9ad8\u5f37\u5ea6\u5408\u91d1\u7684\u91cd\u8981\u7a00\u571f\u5143\u7d20\u3002\x0a\x0a\u9420\u7684\u96fb\u5b50\u7d44\u614b\u70ba\x20\x5b\x58\x65\x5d\x34\x66\u00b3\x36\x73\u00b2\uff0c\u5728\u5316\u5b78\u884c\u70ba\u4e0a\u4e3b\u8981\u5c55\u73fe\u7a69\u5b9a\u7684\x20\x2b\x33\x20\u6c27\u5316\u614b\uff0c\u4f46\u5728\u7279\u5b9a\u689d\u4ef6\u4e0b\u4ea6\u80fd\u5f62\u6210\x20\x2b\x34\x20\u614b\x28\u5982\x20\x50\x72\x4f\u2082\x29\u3002\u9019\u7a2e\u591a\u50f9\u614b\u7279\u5fb5\u5728\u946d\u7cfb\u5143\u7d20\u4e2d\u76f8\u5c0d\u5c11\u898b\uff0c\u4f7f\u5176\u5728\u6c27\u5316\u9084\u539f\u50ac\u5316\u4e2d\u5177\u6709\u6f5b\u529b\u3002\u9420\u96e2\u5b50\x28\x50\x72\u00b3\u207a\x29\u5448\u73fe\u7279\u5fb5\u7684\u9bae\u7da0\u8272\uff0c\u5176\u5149\u8b5c\u5438\u6536\u7279\u6027\u662f\u9ad8\u4e2d\u5316\u5b78\u5728\u8a0e\u8ad6\u96fb\u5b50\u8e8d\u9077\u8207\u6210\u8272\u539f\u7406\u6642\u7684\u9032\u968e\u6848\u4f8b\u3002\u8207\u5176\u4ed6\u946d\u7cfb\u5143\u7d20\u76f8\u4f3c\uff0c\u9420\u5177\u5099\u8f03\u5f37\u7684\u96fb\u8ca0\u5ea6\u8da8\u52e2\u8207\u91d1\u5c6c\u6d3b\u6027\uff0c\u80fd\u8207\u591a\u7a2e\u975e\u91d1\u5c6c\u767c\u751f\u5287\u70c8\u53cd\u61c9\uff0c\u5176\u6c2b\u6c27\u5316\u7269\u5c55\u73fe\u51fa\u660e\u986f\u7684\u9e7c\u6027\u3002\x0a\x0a\u5728\u73fe\u4ee3\u79d1\u6280\u61c9\u7528\u4e2d\uff0c\u9420\u8207\u91f9\u5f62\u6210\u7684\u300c\u91f9\u9420\u5408\u91d1\u300d\u662f\u88fd\u9020\u8d85\u5f37\u529b\u6c38\u78c1\u6750\u6599\x28\x4e\x64\x46\x65\x42\x29\u7684\u95dc\u9375\uff0c\u80fd\u986f\u8457\u63d0\u5347\u78c1\u9435\u7684\u529b\u5b78\u5f37\u5ea6\u8207\u52a0\u5de5\u6027\u80fd\u3002\u5728\u5149\u5b78\u5de5\u7a0b\u9818\u57df\uff0c\u9420\u88ab\u7528\u65bc\u88fd\u9020\u8457\u540d\u7684\u300c\u9420\u91f9\u73bb\u7483\u300d\x28\x44\x69\x64\x79\x6d\x69\x75\x6d\x20\x67\x6c\x61\x73\x73\x29\uff0c\u9019\u7a2e\u73bb\u7483\u80fd\u7cbe\u78ba\u6ffe\u9664\u9209\u706b\u7130\u767c\u51fa\u7684\u5f37\u70c8\u9ec3\u5149\uff0c\u662f\u5439\u88fd\u73bb\u7483\u5de5\u8207\u96fb\u710a\u5de5\u4fdd\u8b77\u8b77\u76ee\u93e1\u7684\u6838\u5fc3\u6750\u6599\u3002\u6b64\u5916\uff0c\u9420\u5728\u5149\u7e96\u901a\u8a0a\u4e2d\u4ea6\u6709\u91cd\u8981\u8ca2\u737b\uff0c\u647b\u9420\u6c1f\u5316\u7269\u7e96\u7dad\u653e\u5927\u5668\x28\x50\x44\x46\x41\x29\u80fd\u6709\u6548\u653e\u5927\u7279\u5b9a\u6ce2\u6bb5\u7684\u5149\u8a0a\u865f\uff0c\u63d0\u5347\u9577\u8ddd\u96e2\u901a\u8a0a\u7684\u54c1\u8cea\u3002\x0a\x0a\u9420\u5728\u6750\u6599\u79d1\u5b78\u4e2d\u5c55\u73fe\u4e86\u5353\u8d8a\u7684\u71b1\u529b\u5b78\u7a69\u5b9a\u6027\u3002\u5c07\u5fae\u91cf\u9420\u52a0\u5165\u9382\u5408\u91d1\u4e2d\uff0c\u80fd\u5927\u5e45\u63d0\u9ad8\u6750\u6599\u7684\u9ad8\u6eab\u6297\u8815\u8b8a\u80fd\u529b\uff0c\u9019\u5c0d\u822a\u7a7a\u767c\u52d5\u6a5f\u96f6\u4ef6\u7684\u8f15\u91cf\u5316\u81f3\u95dc\u91cd\u8981\u3002\u6709\u8da3\u7684\u662f\uff0c\u6c27\u5316\u9420\x28\x50\x72\u2086\x4f\u2081\u2081\x29\u4e0d\u50c5\u662f\u9676\u74f7\u91c9\u6599\u4e2d\u7a69\u5b9a\u7684\u7da0\u8272\u4f86\u6e90\uff0c\u5176\u5728\u50ac\u5316\u9818\u57df\u9084\u80fd\u4fc3\u9032\u4e00\u6c27\u5316\u78b3\u7684\u6c27\u5316\u53cd\u61c9\u3002\u9019\u7a2e\u5f9e\u5206\u96e2\u300c\u96d9\u80de\u80ce\u5143\u7d20\u300d\u7684\u6b77\u53f2\u5de7\u5408\uff0c\u5230\u652f\u6490\u73fe\u4ee3\u9ad8\u6548\u80fd\u78c1\u9ad4\u8207\u5149\u5b78\u904e\u6ffe\u7684\u6838\u5fc3\u5730\u4f4d\uff0c\u7cbe\u78ba\u8a6e\u91cb\u4e86\u9420\u5728\u7a00\u571f\u5143\u7d20\u4e2d\u4e0d\u53ef\u66ff\u4ee3\u7684\u529f\u80fd\u89d2\u8272\u3002",
  "\x4e\x64":
    "\u91f9\x28\x4e\x65\x6f\x64\x79\x6d\x69\x75\x6d\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x4e\x64\uff0c\u539f\u5b50\u5e8f\x20\x36\x30\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u516d\u9031\u671f\u3001\u946d\u7cfb\u5143\u7d20\x28\x66\x20\u5340\u584a\x29\u3002\u5176\u540d\u7a31\u7531\u5e0c\u81d8\u8a9e\u300c\x6e\x65\x6f\x73\u300d\x28\u65b0\x29\u8207\u300c\x64\x69\x64\x79\x6d\x6f\x73\u300d\x28\u96d9\u80de\u80ce\x29\u7d44\u5408\u800c\u6210\uff0c\u8c61\u5fb5\u5176\u5f9e\u539f\u672c\u7684\u91f9\u9420\u6df7\u5408\u7269\u4e2d\u88ab\u65b0\u5206\u96e2\u51fa\u4f86\u3002\x31\x38\x38\x35\x20\u5e74\u7531\u97cb\u723e\u65af\u5df4\u8d6b\x28\x43\x61\x72\x6c\x20\x41\x75\x65\x72\x20\x76\x6f\x6e\x20\x57\x65\x6c\x73\x62\x61\x63\x68\x29\u5206\u96e2\u6210\u529f\u3002\u91f9\u662f\u946d\u7cfb\u5143\u7d20\u4e2d\u61c9\u7528\u6700\u5ee3\u3001\u7d93\u6fdf\u50f9\u503c\u6975\u9ad8\u7684\u6210\u54e1\uff0c\u55ae\u8cea\u5448\u9280\u767d\u8272\u4e14\u5177\u5099\u91d1\u5c6c\u5149\u6fa4\uff0c\u4e3b\u8981\u5b58\u5728\u65bc\u7368\u5c45\u77f3\u8207\u6c1f\u78b3\u9230\u7926\u4e2d\uff0c\u662f\u73fe\u4ee3\u9ad8\u6548\u80fd\u6c38\u78c1\u8207\u96f7\u5c04\u6280\u8853\u7684\u6280\u8853\u810a\u6a11\u3002\x0a\x0a\u91f9\u7684\u96fb\u5b50\u7d44\u614b\u70ba\x20\x5b\x58\x65\x5d\x34\x66\u2074\x36\x73\u00b2\uff0c\u5728\u5316\u5408\u7269\u4e2d\u7a69\u5b9a\u5448\u73fe\x20\x2b\x33\x20\u6c27\u5316\u614b\u3002\u91f9\u96e2\u5b50\x28\x4e\x64\u00b3\u207a\x29\u5177\u6709\u7368\u7279\u7684\u5149\u5b78\u7279\u5fb5\uff0c\u5176\u6c34\u6eb6\u6db2\u5448\u73fe\u6de1\u7d2b\u8272\uff0c\u4e14\u5728\u4e0d\u540c\u5149\u6e90\u7167\u5c04\u4e0b\u6703\u7522\u751f\u660e\u986f\u7684\u8b8a\u8272\u6548\u61c9\uff0c\u9019\u6e90\u65bc\u5176\x20\x34\x66\x20\u96fb\u5b50\u5728\u72f9\u7a84\u80fd\u968e\u9593\u7684\u8907\u96dc\u8e8d\u9077\u3002\u5728\u9ad8\u4e2d\u5316\u5b78\u63a2\u8a0e\u78c1\u6027\u6027\u8cea\u6642\uff0c\u91f9\u662f\u6975\u4f73\u7684\u5be6\u4f8b\uff1a\u7531\u65bc\u5176\u5177\u6709\u56db\u500b\u672a\u6210\u5c0d\u96fb\u5b50\uff0c\u91f9\u5c55\u73fe\u51fa\u5f37\u70c8\u7684\u9806\u78c1\u6027\u3002\u7576\u91f9\u8207\u9435\u3001\u787c\u7d50\u5408\u5f62\u6210\u6676\u9ad4\u6642\uff0c\u5f37\u5927\u7684\u78c1\u77e9\u8207\u6676\u683c\u7570\u5411\u6027\u80fd\u7522\u751f\u6975\u9ad8\u7684\u77ef\u9811\u529b\uff0c\u6210\u5c31\u4e86\u76ee\u524d\u5df2\u77e5\u6700\u5f37\u7684\u6c38\u4e45\u78c1\u9435\u3002\x0a\x0a\u5728\u73fe\u4ee3\u7522\u696d\u61c9\u7528\u4e0a\uff0c\u91f9\u9435\u787c\u78c1\u9435\x28\x4e\x64\x46\x65\x42\x20\x6d\x61\x67\x6e\x65\x74\x29\u88ab\u8b7d\u70ba\u300c\u78c1\u9435\u4e4b\u738b\u300d\u3002\u5176\u6975\u5f37\u7684\u78c1\u5834\u5f37\u5ea6\u4f7f\u96fb\u6a5f\u8a2d\u5099\u5f97\u4ee5\u5c0f\u578b\u5316\u8207\u9ad8\u6548\u5316\uff0c\u5f9e\u786c\u789f\u9a45\u52d5\u99ac\u9054\u3001\u98a8\u529b\u767c\u96fb\u6a5f\u5230\u96fb\u52d5\u8eca\u7684\u727d\u5f15\u99ac\u9054\uff0c\u7686\u662f\u91f9\u78c1\u9435\u7684\u95dc\u9375\u821e\u53f0\u3002\u5728\u5149\u5b78\u9818\u57df\uff0c\u647b\u91f9\u91d4\u92c1\u77f3\u69b4\u77f3\x28\x4e\x64\x3a\x59\x41\x47\x29\u662f\u76ee\u524d\u61c9\u7528\u6700\u5ee3\u6cdb\u7684\u56fa\u9ad4\u96f7\u5c04\u6750\u6599\uff0c\u80fd\u767c\u51fa\u9ad8\u529f\u7387\u7684\u8fd1\u7d05\u5916\u5149\uff0c\u5ee3\u6cdb\u61c9\u7528\u65bc\u96f7\u5c04\u624b\u8853\u3001\u5de5\u696d\u5207\u5272\u8207\u7cbe\u5bc6\u6e2c\u8ddd\u3002\u6b64\u5916\uff0c\u91f9\u4ea6\u88ab\u7528\u65bc\u88fd\u9020\u7279\u6b8a\u7684\u7d2b\u8272\u73bb\u7483\uff0c\u7528\u65bc\u5929\u6587\u89c0\u6e2c\u8207\u986f\u5fae\u93e1\u7167\u76f8\u7684\u8272\u5f69\u6821\u6b63\u3002\x0a\x0a\u91f9\u5728\u7269\u7406\u7279\u6027\u4e0a\u5c55\u73fe\u51fa\u986f\u8457\u7684\u7a69\u5b9a\u6027\u8207\u654f\u611f\u6027\u5e73\u8861\u3002\u96d6\u7136\u91f9\u78c1\u9435\u5177\u5099\u6975\u5f37\u78c1\u529b\uff0c\u4f46\u5176\u8010\u71b1\u6027\u8207\u6297\u8150\u8755\u6027\u76f8\u5c0d\u8f03\u5f31\uff0c\u9019\u4fc3\u4f7f\u6750\u6599\u79d1\u5b78\u754c\u958b\u767c\u51fa\u934d\u93b3\u6216\u647b\u5165\u91cd\u7a00\u571f\x28\u5982\u93d1\x29\u7684\u6539\u826f\u6280\u8853\u3002\u6709\u8da3\u7684\u662f\uff0c\u91f9\u96e2\u5b50\u80fd\u5438\u6536\u7279\u5b9a\u983b\u6bb5\u7684\u7d2b\u5916\u5149\u8207\u7d05\u5916\u5149\uff0c\u4f7f\u5176\u5728\u88fd\u9020\u592a\u967d\u773c\u93e1\u8207\u96fb\u5b50\u6ffe\u5149\u7247\u4e2d\u5177\u6709\u7279\u6b8a\u50f9\u503c\u3002\u9019\u7a2e\u5f9e\u300c\u65b0\u96d9\u80de\u80ce\u300d\u7684\u767c\u73fe\uff0c\u5230\u9a45\u52d5\u73fe\u4ee3\u7da0\u80fd\u4ea4\u901a\u8207\u7cbe\u5bc6\u96f7\u5c04\u7684\u6838\u5fc3\u9a45\u52d5\u529b\uff0c\u7cbe\u78ba\u9ad4\u73fe\u4e86\u91f9\u5728\u9031\u671f\u8868\u4e2d\u4f5c\u70ba\u529f\u80fd\u6750\u6599\u6838\u5fc3\u7684\u5353\u8d8a\u5730\u4f4d\u3002",
  "\x50\x6d":
    "\u9255\x28\x50\x72\x6f\x6d\x65\x74\x68\x69\x75\x6d\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x50\x6d\uff0c\u539f\u5b50\u5e8f\x20\x36\x31\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u516d\u9031\u671f\u3001\u946d\u7cfb\u5143\u7d20\x28\x66\x20\u5340\u584a\x29\u3002\u5176\u540d\u7a31\u6e90\u65bc\u5e0c\u81d8\u795e\u8a71\u4e2d\u70ba\u4eba\u985e\u76dc\u53d6\u706b\u7a2e\u7684\u82f1\u96c4\u666e\u7f85\u7c73\u4fee\u65af\x28\x50\x72\x6f\x6d\x65\x74\x68\x65\x75\x73\x29\uff0c\u8c61\u5fb5\u8a72\u5143\u7d20\u662f\u5f9e\u6838\u5b50\u53cd\u61c9\u7210\u7684\u300c\u7210\u706b\u300d\u4e2d\u8a95\u751f\u7684\u3002\u9255\u662f\u946d\u7cfb\u5143\u7d20\u4e2d\u552f\u4e00\u6c92\u6709\u7a69\u5b9a\u540c\u4f4d\u7d20\u7684\u653e\u5c04\u6027\u5143\u7d20\uff0c\x31\x39\x34\x35\x20\u5e74\u7531\u99ac\u6797\u65af\u57fa\x28\x4a\x61\x63\x6f\x62\x20\x41\x2e\x20\x4d\x61\x72\x69\x6e\x73\x6b\x79\x29\u7b49\u4eba\u5728\u8655\u7406\u923e\u88c2\u8b8a\u7522\u7269\u6642\u9996\u6b21\u5206\u96e2\u3002\u7531\u65bc\u5176\u6240\u6709\u540c\u4f4d\u7d20\u7684\u534a\u8870\u671f\u5747\u8f03\u77ed\uff0c\u9255\u5728\u81ea\u7136\u754c\u5730\u6bbc\u4e2d\u5e7e\u4e4e\u4e0d\u5b58\u5728\uff0c\u662f\u5178\u578b\u7684\u653e\u5c04\u6027\u7a00\u571f\u5143\u7d20\u3002\x0a\x0a\u5728\u5316\u5b78\u884c\u70ba\u4e0a\uff0c\u9255\u7684\u96fb\u5b50\u7d44\u614b\u70ba\x20\x5b\x58\x65\x5d\x34\x66\u2075\x36\x73\u00b2\uff0c\u5c55\u73fe\u51fa\u5178\u578b\u7684\x20\x2b\x33\x20\u6c27\u5316\u614b\u3002\u5176\u5316\u5b78\u6027\u8cea\u8207\u76f8\u9130\u7684\u91f9\u3001\u91e4\u6975\u5176\u76f8\u4f3c\uff0c\u4f46\u56e0\u5177\u5099\u653e\u5c04\u6027\uff0c\u5176\u7814\u7a76\u5fc5\u9808\u5728\u6975\u56b4\u5bc6\u7684\u8f3b\u5c04\u9632\u8b77\u4e0b\u9032\u884c\u3002\u9255\u6700\u7a69\u5b9a\u7684\u540c\u4f4d\u7d20\x20\u9255\x2d\x31\x34\x37\x28\u00b9\u2074\u2077\x50\x6d\x29\u534a\u8870\u671f\u7d04\u70ba\x20\x32\x2e\x36\x32\x20\u5e74\uff0c\u4e3b\u8981\u9032\u884c\x20\u03b2\x20\u8870\u8b8a\uff0c\u9019\u610f\u5473\u8457\u5b83\u80fd\u6301\u7e8c\u91cb\u653e\u4f4e\u80fd\u91cf\u7684\u96fb\u5b50\u6d41\u3002\u5728\u9ad8\u4e2d\u5316\u5b78\u63a2\u8a0e\u6838\u5316\u5b78\u8207\u540c\u4f4d\u7d20\u61c9\u7528\u6642\uff0c\u9255\u662f\u7406\u89e3\u88c2\u8b8a\u7522\u7269\u6027\u8cea\u8207\u300c\u6838\u80fd\u8f49\u5316\u70ba\u96fb\u80fd\u300d\u6a5f\u5236\u7684\u4ee3\u8868\u6027\u6848\u4f8b\u3002\x0a\x0a\u9255\u5728\u73fe\u4ee3\u79d1\u6280\u4e2d\u5c55\u73fe\u4e86\u5fae\u5c0f\u800c\u6301\u4e45\u7684\u80fd\u91cf\u512a\u52e2\u3002\u5b83\u88ab\u7528\u65bc\u88fd\u9020\u300c\u539f\u5b50\u96fb\u6c60\u300d\x28\u6216\u7a31\u6838\u96fb\u6c60\x29\uff0c\u5229\u7528\x20\u00b9\u2074\u2077\x50\x6d\x20\u8870\u8b8a\u7522\u751f\u7684\u96fb\u5b50\u8f5f\u64ca\u534a\u5c0e\u9ad4\u7522\u751f\u96fb\u6d41\u3002\u9019\u985e\u96fb\u6c60\u9ad4\u7a4d\u5fae\u5c0f\u3001\u58fd\u547d\u9577\u4e14\u4e0d\u9700\u7dad\u8b77\uff0c\u66fe\u88ab\u7528\u65bc\u5fc3\u81df\u7bc0\u5f8b\u5668\u3001\u6df1\u6d77\u63a2\u6e2c\u5668\u8207\u4eba\u9020\u885b\u661f\u7684\u7cbe\u5bc6\u96fb\u5b50\u7cfb\u7d71\u3002\u6b64\u5916\uff0c\u9255\u7684\u653e\u5c04\u6027\u7522\u751f\u7684\u87a2\u5149\u6548\u679c\u512a\u65bc\u65e9\u671f\u7684\u9433\uff0c\u4e14\u8f3b\u5c04\u5371\u5bb3\u8f03\u6613\u5c4f\u853d\uff0c\u66fe\u88ab\u5ee3\u6cdb\u7528\u65bc\u5674\u5c04\u6230\u9b25\u6a5f\u5100\u8868\u677f\u8207\u9ad8\u7aef\u6f5b\u6c34\u9336\u7684\u81ea\u767c\u5149\u5857\u6599\u3002\u5728\u539a\u5ea6\u8a08\u61c9\u7528\u4e2d\uff0c\u9255\u767c\u5c04\u7684\x20\u03b2\x20\u5c04\u7dda\u4ea6\u88ab\u7528\u4f86\u7cbe\u78ba\u6e2c\u91cf\u91d1\u5c6c\u7247\u6216\u5851\u81a0\u8584\u819c\u7684\u539a\u5ea6\u3002\x0a\x0a\u95dc\u65bc\u9255\u7684\u73fe\u8c61\uff0c\u5b83\u5728\u767c\u5149\u904e\u7a0b\u4e2d\u5c55\u73fe\u51fa\u300c\u5149\u51b7\u800c\u7121\u71b1\u300d\u7684\u7279\u5fb5\uff0c\u9019\u4f7f\u5176\u5728\u7279\u5b9a\u7cbe\u5bc6\u5149\u5b78\u5100\u5668\u4e2d\u5177\u6709\u7279\u6b8a\u50f9\u503c\u3002\u6709\u8da3\u7684\u662f\uff0c\u5118\u7ba1\u5730\u7403\u4e0a\u539f\u751f\u9255\u5df2\u6d88\u4ea1\u6b86\u76e1\uff0c\u4f46\u5929\u6587\u5b78\u5bb6\u5728\u67d0\u4e9b\u6046\u661f\x28\u5982\u666e\u745e\u8332\u6bd4\u723e\u65af\u57fa\u661f\x29\u7684\u5149\u8b5c\u4e2d\u89c0\u6e2c\u5230\u4e86\u9255\u7684\u8b5c\u7dda\uff0c\u6697\u793a\u4e86\u6046\u661f\u5167\u90e8\u6b63\u6301\u7e8c\u9032\u884c\u8457\u91cd\u6838\u5408\u6210\u904e\u7a0b\u3002\u9019\u7a2e\u5f9e\u6838\u5ee2\u6599\u4e2d\u88ab\u8403\u53d6\u51fa\u7684\u653e\u5c04\u6027\u5143\u7d20\uff0c\u5f9e\u670d\u52d9\u4eba\u985e\u5065\u5eb7\u7684\u91ab\u7642\u5100\u5668\u5230\u5c0e\u822a\u661f\u7a7a\u7684\u5fae\u5149\uff0c\u7cbe\u78ba\u8a6e\u91cb\u4e86\u9255\u4f5c\u70ba\u300c\u76dc\u706b\u8005\u300d\u5728\u6975\u7aef\u6750\u6599\u61c9\u7528\u4e2d\u7684\u7368\u7279\u50f9\u503c\u3002",
  "\x53\x6d":
    "\u91e4\x28\x53\x61\x6d\x61\x72\x69\x75\x6d\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x53\x6d\uff0c\u539f\u5b50\u5e8f\x20\x36\x32\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u516d\u9031\u671f\u3001\u946d\u7cfb\u5143\u7d20\x28\x66\x20\u5340\u584a\x29\u3002\x31\x38\x37\x39\x20\u5e74\u7531\u6cd5\u570b\u5316\u5b78\u5bb6\u5e03\u74e6\u535a\u5fb7\u6717\x28\x4c\x65\x63\x6f\x71\x20\x64\x65\x20\x42\x6f\x69\x73\x62\x61\x75\x64\x72\x61\x6e\x29\u5f9e\u922e\u91d4\u7926\u4e2d\u767c\u73fe\uff0c\u5176\u540d\u7a31\u53d6\u81ea\u7926\u77f3\u540d\u300c\x53\x61\x6d\x61\x72\x73\x6b\x69\x74\x65\u300d\uff0c\u800c\u8a72\u7926\u77f3\u53c8\u662f\u7d00\u5ff5\u4fc4\u7f85\u65af\u7926\u696d\u5b98\u54e1\u85a9\u99ac\u723e\u65af\u57fa\x28\x53\x61\x6d\x61\x72\x73\x6b\x79\x29\u800c\u547d\u540d\uff0c\u4f7f\u91e4\u6210\u70ba\u9996\u500b\u4ee5\u4eba\u540d\u9593\u63a5\u547d\u540d\u7684\u5316\u5b78\u5143\u7d20\u3002\u91e4\u662f\u4e00\u7a2e\u9280\u767d\u8272\u7684\u4e2d\u786c\u5ea6\u91d1\u5c6c\uff0c\u5316\u5b78\u6027\u8cea\u8f03\u6d3b\u6f51\uff0c\u5728\u7a7a\u6c23\u4e2d\u6703\u7de9\u6162\u6c27\u5316\uff0c\u662f\u7814\u7a76\u7a00\u571f\u78c1\u6027\u8207\u6709\u6a5f\u5408\u6210\u50ac\u5316\u7684\u6838\u5fc3\u6750\u6599\u3002\x0a\x0a\u91e4\u7684\u96fb\u5b50\u7d44\u614b\u70ba\x20\x5b\x58\x65\x5d\x34\x66\u2076\x36\x73\u00b2\uff0c\u5728\u5316\u5b78\u53cd\u61c9\u4e2d\u4e3b\u8981\u5c55\u73fe\x20\x2b\x33\x20\u6c27\u5316\u614b\u3002\u7279\u5225\u7684\u662f\uff0c\u91e4\u662f\u946d\u7cfb\u5143\u7d20\u4e2d\u5c11\u6578\u80fd\u5c55\u73fe\u7a69\u5b9a\x20\x2b\x32\x20\u614b\x28\x53\x6d\u00b2\u207a\x29\u7684\u6210\u54e1\uff0c\u9019\u6e90\u65bc\u5176\u96e2\u5b50\u5177\u5099\u63a5\u8fd1\u534a\u586b\u6eff\x20\x34\x66\u2077\x20\u7d50\u69cb\u7684\u7a69\u5b9a\u8da8\u5411\u3002\u5728\u9ad8\u4e2d\u5316\u5b78\u63a2\u8a0e\u6709\u6a5f\u5408\u6210\u52d5\u529b\u5b78\u6642\uff0c\u4e8c\u7898\u5316\u91e4\x28\x53\x6d\x49\u2082\uff0c\u53c8\u7a31\x20\x4b\x61\x67\x61\x6e\x20\u8a66\u5291\x29\u662f\u975e\u5e38\u91cd\u8981\u7684\u9084\u539f\u5291\uff0c\u80fd\u8a98\u5c0e\u8a31\u591a\u9078\u64c7\u6027\u6975\u9ad8\u7684\u78b3\uff0d\u78b3\u9375\u7d50\u53cd\u61c9\u3002\u6b64\u5916\uff0c\u91e4\u5177\u5099\u8f03\u5f37\u7684\u9806\u78c1\u6027\uff0c\u5176\u540c\u4f4d\u7d20\u5206\u5e03\u591a\u6a23\uff0c\u5176\u4e2d\x20\u00b9\u2074\u2079\x53\x6d\x20\u662f\u6975\u5f37\u7684\u4e2d\u5b50\u5438\u6536\u5291\uff0c\u9019\u4f7f\u5176\u5728\u6838\u53cd\u61c9\u7210\u7684\u7269\u7406\u8a2d\u8a08\u4e2d\u5177\u6709\u63a7\u5236\u53cd\u61c9\u901f\u7387\u7684\u529f\u80fd\u3002\x0a\x0a\u5728\u73fe\u4ee3\u61c9\u7528\u9818\u57df\uff0c\u91e4\u8207\u9237\u5f62\u6210\u7684\u300c\u91e4\u9237\u78c1\u9435\u300d\x28\x53\x6d\x43\x6f\x20\x6d\x61\x67\x6e\x65\x74\x29\u5177\u6709\u9769\u547d\u6027\u7684\u5730\u4f4d\u3002\u96d6\u7136\u78c1\u529b\u7565\u905c\u65bc\u91f9\u78c1\u9435\uff0c\u4f46\u91e4\u9237\u78c1\u9435\u5177\u5099\u5353\u8d8a\u7684\u6297\u8150\u8755\u6027\u8207\u6975\u9ad8\u6eab\u7a69\u5b9a\u6027\x28\u5c45\u79ae\u6eab\u5ea6\u9ad8\x29\uff0c\u5728\u9ad8\u6eab\u74b0\u5883\x28\u5982\u5674\u5c04\u767c\u52d5\u6a5f\u3001\u9ad8\u6eab\u611f\u6e2c\u5668\x29\u4e2d\u8868\u73fe\u512a\u7570\u4e14\u4e0d\u9700\u5857\u5c64\u3002\u5728\u91ab\u7642\u653e\u5c04\u91ab\u5b78\u4e2d\uff0c\u540c\u4f4d\u7d20\u91e4\x2d\x31\x35\x33\x28\u00b9\u2075\u00b3\x53\x6d\x29\u88ab\u88fd\u6210\u87af\u5408\u7269\u85e5\u5291\uff0c\u5229\u7528\u5176\u653e\u5c04\u6027\x20\u03b2\x20\u7c92\u5b50\u7cbe\u78ba\u7de9\u89e3\u9aa8\u764c\u5f15\u8d77\u7684\u5287\u70c8\u75bc\u75db\u3002\u6b64\u5916\uff0c\u91d4\u91e4\u9223\u787c\u9178\u9e7d\u6676\u9ad4\u5728\u96f7\u5c04\u6280\u8853\u4e2d\u4ea6\u88ab\u7528\u65bc\u88fd\u9020\u9ad8\u6548\u80fd\u7684\u7d05\u5916\u7dda\u5149\u6e90\u3002\x0a\x0a\u91e4\u5728\u5730\u7403\u5316\u5b78\u4e2d\u626e\u6f14\u8457\u300c\u6642\u5149\u6a19\u5c3a\u300d\u7684\u89d2\u8272\u3002\u91e4\x2d\u91f9\u5b9a\u5e74\u6cd5\x28\x53\x6d\x2d\x4e\x64\x20\x64\x61\x74\x69\x6e\x67\x29\u5229\u7528\x20\u00b9\u2074\u2077\x53\x6d\x20\u8870\u8b8a\u70ba\x20\u00b9\u2074\u00b3\x4e\x64\x20\u7684\u5fae\u5f31\u653e\u5c04\u6027\uff0c\u88ab\u5730\u8cea\u5b78\u5bb6\u7528\u4f86\u6e2c\u5b9a\u6975\u53e4\u8001\u5ca9\u77f3\x28\u5982\u5730\u51fd\u4f86\u6e90\u5ca9\x29\u7684\u5f62\u6210\u5e74\u9f61\u8207\u5730\u6bbc\u6f14\u5316\u904e\u7a0b\u3002\u6709\u8da3\u7684\u662f\uff0c\u91d1\u5c6c\u91e4\u5728\u5ba4\u6eab\u4e0b\u5177\u6709\u8907\u96dc\u7684\u6676\u9ad4\u7d50\u69cb\x28\u4e5d\u5c64\u5c0d\u7a31\x29\uff0c\u5728\u52a0\u71b1\u81f3\u6975\u9ad8\u6eab\u524d\u6703\u767c\u751f\u591a\u6b21\u76f8\u8b8a\u3002\u9019\u7a2e\u5f9e\u8f14\u52a9\u6709\u6a5f\u5408\u6210\u7684\u5f37\u9084\u539f\u5291\u5230\u5728\u6975\u7aef\u9ad8\u6eab\u4e0b\u5b88\u8b77\u5f15\u64ce\u904b\u4f5c\u7684\u5f37\u78c1\u9ad4\uff0c\u7cbe\u78ba\u8a6e\u91cb\u4e86\u91e4\u5728\u7a00\u571f\u5143\u7d20\u4e2d\u517c\u5177\u7a69\u5b9a\u6027\u8207\u9ad8\u53cd\u61c9\u6d3b\u6027\u7684\u96d9\u91cd\u7279\u8cea\u3002",
  "\x45\x75":
    "\u92aa\x28\x45\x75\x72\x6f\x70\x69\x75\x6d\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x45\x75\uff0c\u539f\u5b50\u5e8f\x20\x36\x33\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u516d\u9031\u671f\u3001\u946d\u7cfb\u5143\u7d20\x28\x66\x20\u5340\u584a\x29\u3002\u5176\u540d\u7a31\u6e90\u65bc\u6b50\u6d32\x28\x45\x75\x72\x6f\x70\x65\x29\u3002\x31\x39\x30\x31\x20\u5e74\u7531\u6cd5\u570b\u5316\u5b78\u5bb6\u5fb7\u99ac\u51f1\x28\x45\x75\x67\u00e8\x6e\x65\x2d\x41\x6e\x74\x6f\x6c\x65\x20\x44\x65\x6d\x61\x72\u00e7\x61\x79\x29\u5f9e\u91e4\u7684\u96dc\u8cea\u4e2d\u5206\u96e2\uff0c\u4e26\u8b49\u5be6\u5176\u5b58\u5728\u3002\u92aa\u662f\u946d\u7cfb\u5143\u7d20\u4e2d\u5316\u5b78\u6d3b\u6027\u6700\u5f37\u3001\u786c\u5ea6\u6700\u4f4e\u4e14\u5bc6\u5ea6\u6700\u5c0f\u7684\u6210\u54e1\uff0c\u5176\u9280\u767d\u8272\u7684\u91d1\u5c6c\u8868\u9762\u5728\u7a7a\u6c23\u4e2d\u6703\u8fc5\u901f\u6c27\u5316\uff0c\u751a\u81f3\u5728\u6c34\u4e2d\u6703\u50cf\u9e7c\u91d1\u5c6c\u822c\u5287\u70c8\u91cb\u653e\u6c2b\u6c23\u3002\u5b83\u662f\u73fe\u4ee3\u5149\u5b78\u986f\u793a\u8207\u9632\u507d\u6280\u8853\u4e2d\u4e0d\u53ef\u6216\u7f3a\u7684\u767c\u5149\u6838\u5fc3\u3002\x0a\x0a\u92aa\u7684\u96fb\u5b50\u7d44\u614b\u70ba\x20\x5b\x58\x65\x5d\x34\x66\u2077\x36\x73\u00b2\uff0c\u5177\u5099\u6975\u5176\u7a69\u5b9a\u7684\u534a\u586b\u6eff\x20\x34\x66\u2077\x20\u7d50\u69cb\u3002\u9019\u4f7f\u5f97\u92aa\u9664\u4e86\u6a19\u6e96\u7684\x20\x2b\x33\x20\u6c27\u5316\u614b\u5916\uff0c\u5c55\u73fe\u51fa\u6975\u70ba\u7a69\u5b9a\u4e14\u5e38\u898b\u7684\x20\x2b\x32\x20\u6c27\u5316\u614b\x28\x45\x75\u00b2\u207a\x29\uff0c\u5176\u96e2\u5b50\u534a\u5f91\u8207\u6027\u8cea\u66f4\u63a5\u8fd1\u9e7c\u571f\u91d1\u5c6c\x28\u5982\u92c7\x29\u3002\u5728\u9ad8\u4e2d\u5316\u5b78\u63a2\u8a0e\u96fb\u5b50\u7d44\u614b\u898f\u5f8b\u6642\uff0c\u92aa\u662f\u7406\u89e3\u300c\u534a\u586b\u6eff\u7a69\u5b9a\u6027\u300d\u5c0d\u5316\u5b78\u6027\u8cea\u5f71\u97ff\u7684\u6700\u4f73\u5be6\u4f8b\u3002\u6b64\u5916\uff0c\u92aa\u96e2\u5b50\u5177\u5099\u6975\u5f37\u7684\u5149\u81f4\u767c\u5149\u7279\u6027\uff0c\u4e0d\u540c\u50f9\u614b\u7684\u92aa\u80fd\u767c\u51fa\u9bae\u8c54\u7684\u8272\u5f69\uff1a\x45\x75\u00b3\u207a\x20\u7522\u751f\u660e\u4eae\u7684\u7d05\u8272\u87a2\u5149\uff0c\u800c\x20\x45\x75\u00b2\u207a\x20\u5247\u7522\u751f\u85cd\u8272\u87a2\u5149\uff0c\u9019\u5960\u5b9a\u4e86\u5b83\u5728\u5149\u5b78\u6750\u6599\u4e2d\u7684\u9818\u5c0e\u5730\u4f4d\u3002\x0a\x0a\u5728\u73fe\u4ee3\u61c9\u7528\u4e2d\uff0c\u92aa\u662f\u300c\u9ede\u4eae\u4e16\u754c\u300d\u7684\u5143\u7d20\u3002\u5b83\u662f\u65e9\u671f\u5f69\u8272\u96fb\u8996\u6a5f\x28\x43\x52\x54\x29\u4e2d\u7522\u751f\u9bae\u7d05\u8272\u7684\u6838\u5fc3\u6750\u6599\uff0c\u89e3\u6c7a\u4e86\u9577\u671f\u4ee5\u4f86\u7d05\u8272\u767c\u5149\u6548\u7387\u4f4e\u4e0b\u7684\u554f\u984c\uff1b\u73fe\u4eca\u5247\u5ee3\u6cdb\u61c9\u7528\u65bc\u4e09\u57fa\u8272\u87a2\u5149\u71c8\u3001\x4c\x45\x44\x20\u80cc\u5149\u53ca\u96fb\u6f3f\u986f\u793a\u5668\u4e2d\u3002\u5728\u5b89\u5168\u9632\u507d\u9818\u57df\uff0c\u6b50\u5143\u8207\u591a\u570b\u7d19\u5e63\u7684\u6cb9\u58a8\u4e2d\u7686\u647b\u6709\u92aa\u7684\u8907\u5408\u7269\uff0c\u5728\u7d2b\u5916\u7dda\u7167\u5c04\u4e0b\u6703\u986f\u73fe\u7279\u6709\u7684\u87a2\u5149\u53cd\u61c9\uff0c\u4f5c\u70ba\u9451\u5b9a\u771f\u507d\u7684\u6a19\u6e96\u3002\u6b64\u5916\uff0c\u92aa\u5177\u5099\u6975\u9ad8\u7684\u71b1\u4e2d\u5b50\u5438\u6536\u622a\u9762\uff0c\u4f7f\u5176\u5728\u6838\u53cd\u61c9\u7210\u4e2d\u88ab\u7528\u4f5c\u63a7\u5236\u68d2\u6750\u6599\uff0c\u7cbe\u78ba\u8abf\u7bc0\u6838\u5206\u88c2\u901f\u7387\u3002\x0a\x0a\u95dc\u65bc\u92aa\u7684\u5730\u7403\u5316\u5b78\u73fe\u8c61\uff0c\u5b83\u5c55\u73fe\u4e86\u8457\u540d\u7684\u300c\u92aa\u7570\u5e38\u300d\x28\x45\x75\x72\x6f\x70\x69\x75\x6d\x20\x61\x6e\x6f\x6d\x61\x6c\x79\x29\u3002\u5728\u5ca9\u6f3f\u6f14\u5316\u904e\u7a0b\u4e2d\uff0c\u7531\u65bc\x20\x45\x75\u00b2\u207a\x20\u7684\u6027\u8cea\u8207\x20\x43\x61\u00b2\u207a\x20\u76f8\u4f3c\uff0c\u6703\u512a\u5148\u9032\u5165\u659c\u9577\u77f3\u6676\u683c\uff0c\u5c0e\u81f4\u5269\u9918\u5ca9\u6f3f\u4e2d\u92aa\u7684\u542b\u91cf\u504f\u4f4e\uff0c\u9019\u6210\u70ba\u5730\u8cea\u5b78\u5bb6\u63a8\u6e2c\u884c\u661f\u6f14\u5316\u6b77\u53f2\u7684\u91cd\u8981\u5316\u5b78\u6307\u7d0b\u3002\u6709\u8da3\u7684\u662f\uff0c\u96d6\u7136\u92aa\u662f\u6d3b\u6027\u6975\u9ad8\u7684\u91d1\u5c6c\uff0c\u4f46\u5176\u767c\u5149\u7a69\u5b9a\u6027\u6975\u4f73\u3002\u9019\u7a2e\u5f9e\u5b9a\u7fa9\u87a2\u5e55\u8272\u5f69\u5230\u5b88\u8b77\u91d1\u878d\u5b89\u5168\u7684\u96d9\u91cd\u89d2\u8272\uff0c\u7cbe\u78ba\u8a6e\u91cb\u4e86\u92aa\u5728\u7a00\u571f\u5143\u7d20\u4e2d\u6975\u5177\u751f\u547d\u529b\u7684\u5149\u5b78\u50f9\u503c\u3002",
  "\x47\x64":
    "\u91d3\x28\x47\x61\x64\x6f\x6c\x69\x6e\x69\x75\x6d\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x47\x64\uff0c\u539f\u5b50\u5e8f\x20\x36\x34\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u516d\u9031\u671f\u3001\u946d\u7cfb\u5143\u7d20\x28\x66\x20\u5340\u584a\x29\u3002\u5176\u540d\u7a31\u662f\u70ba\u4e86\u7d00\u5ff5\u7a00\u571f\u7814\u7a76\u5148\u9a45\u3001\u82ac\u862d\u5316\u5b78\u5bb6\u52a0\u591a\u6797\x28\x4a\x6f\x68\x61\x6e\x20\x47\x61\x64\x6f\x6c\x69\x6e\x29\u3002\x31\x38\x38\x30\x20\u5e74\u7531\u99ac\u91cc\u7d0d\u514b\x28\x4a\x65\x61\x6e\x20\x43\x68\x61\x72\x6c\x65\x73\x20\x64\x65\x20\x4d\x61\x72\x69\x67\x6e\x61\x63\x29\u767c\u73fe\u3002\u91d3\u662f\u4e00\u7a2e\u9280\u767d\u8272\u7684\u8edf\u91d1\u5c6c\uff0c\u5177\u5099\u826f\u597d\u7684\u5ef6\u5c55\u6027\u3002\u5728\u6750\u6599\u79d1\u5b78\u4e2d\uff0c\u91d3\u4ee5\u5176\u5353\u8d8a\u7684\u78c1\u5b78\u7279\u6027\u8207\u4e2d\u5b50\u6355\u7372\u80fd\u529b\u8457\u7a31\uff0c\u662f\u73fe\u4ee3\u91ab\u7642\u5f71\u50cf\u8207\u6838\u80fd\u5b89\u5168\u9818\u57df\u7684\u95dc\u9375\u6230\u7565\u91d1\u5c6c\u3002\x0a\x0a\u91d3\u7684\u96fb\u5b50\u7d44\u614b\u70ba\x20\x5b\x58\x65\x5d\x34\x66\u2077\x35\x64\u00b9\x36\x73\u00b2\uff0c\u64c1\u6709\u5b8c\u7f8e\u7684\u534a\u586b\u6eff\x20\x34\x66\u2077\x20\u7d50\u69cb\u8207\u4e00\u500b\u984d\u5916\u7684\x20\x35\x64\x20\u96fb\u5b50\u3002\u9019\u8ce6\u4e88\u91d3\u6975\u9ad8\u7684\u78c1\u77e9\x28\u5177\u5099\u4e03\u500b\u672a\u6210\u5c0d\u96fb\u5b50\x29\uff0c\u4f7f\u5176\u5728\u5ba4\u6eab\u9644\u8fd1\x28\u7d04\x20\x32\x30\x20\u00b0\x43\x29\u5c55\u73fe\u51fa\u5f37\u78c1\u6027\x28\x46\x65\x72\x72\x6f\x6d\x61\x67\x6e\x65\x74\x69\x73\x6d\x29\uff0c\u662f\u5c11\u6578\u5177\u5099\u6b64\u7279\u6027\u7684\u975e\u9435\u65cf\u5143\u7d20\u3002\u5728\u9ad8\u4e2d\u5316\u5b78\u63a2\u8a0e\u78c1\u6027\u8207\u96fb\u5b50\u6392\u5e03\u6642\uff0c\u91d3\u662f\u7406\u89e3\u300c\u9806\u78c1\u6027\u300d\u8207\u300c\u9435\u78c1\u6027\u300d\u754c\u7dda\u7684\u7d93\u5178\u6848\u4f8b\u3002\u6b64\u5916\uff0c\u91d3\u7684\u7a69\u5b9a\u6c27\u5316\u614b\u70ba\x20\x2b\x33\uff0c\u5176\u96e2\u5b50\x20\x47\x64\u00b3\u207a\x20\u5177\u5099\u9ad8\u5ea6\u7684\u5316\u5b78\u7a69\u5b9a\u6027\uff0c\u80fd\u5728\u751f\u7406\u74b0\u5883\u4e0b\u900f\u904e\u87af\u5408\u4f5c\u7528\u767c\u63ee\u7279\u6b8a\u7684\u751f\u7269\u7269\u7406\u529f\u80fd\u3002\x0a\x0a\u5728\u73fe\u4ee3\u91ab\u5b78\u9818\u57df\uff0c\u91d3\u6700\u8457\u540d\u7684\u8ca2\u737b\u662f\u4f5c\u70ba\u300c\u78c1\u632f\u9020\u5f71\u300d\x28\x4d\x52\x49\x29\u7684\u5c0d\u6bd4\u5291\u3002\u7531\u65bc\x20\x47\x64\u00b3\u207a\x20\u5177\u5099\u5f37\u5927\u7684\u9806\u78c1\u6027\uff0c\u80fd\u986f\u8457\u7e2e\u77ed\u9130\u8fd1\u6c34\u5206\u5b50\u7684\u8cea\u5b50\u5f1b\u8c6b\u6642\u9593\uff0c\u5f9e\u800c\u5927\u5e45\u63d0\u5347\u5f71\u50cf\u7684\u6e05\u6670\u5ea6\u8207\u5c0d\u6bd4\uff0c\u5354\u52a9\u91ab\u5e2b\u7cbe\u78ba\u8a3a\u65b7\u816b\u7624\u8207\u8840\u7ba1\u75c5\u8b8a\u3002\u5728\u6838\u80fd\u5de5\u696d\u4e2d\uff0c\u91d3\u64c1\u6709\u6240\u6709\u5143\u7d20\u4e2d\u6700\u9ad8\u7684\u71b1\u4e2d\u5b50\u6355\u7372\u622a\u9762\uff0c\u88ab\u7a31\u70ba\u300c\u4e2d\u5b50\u6bd2\u7269\u300d\uff0c\u7528\u65bc\u88fd\u9020\u6838\u5b50\u53cd\u61c9\u7210\u7684\u7dca\u6025\u63a7\u5236\u68d2\u8207\u5c4f\u853d\u6750\u6599\uff0c\u80fd\u8fc5\u901f\u5438\u6536\u591a\u9918\u4e2d\u5b50\u4ee5\u9632\u6b62\u6838\u4e8b\u6545\u767c\u751f\u3002\u5728\u80fd\u6e90\u6280\u8853\u4e0a\uff0c\u91d3\u57fa\u5408\u91d1\u5c55\u73fe\u4e86\u986f\u8457\u7684\u300c\u78c1\u71b1\u6548\u61c9\u300d\x28\x4d\x61\x67\x6e\x65\x74\x6f\x63\x61\x6c\x6f\x72\x69\x63\x20\x65\x66\x66\x65\x63\x74\x29\uff0c\u662f\u958b\u767c\u7121\u58d3\u7e2e\u6a5f\u3001\u9ad8\u6548\u80fd\u78c1\u88fd\u51b7\u6280\u8853\u7684\u6838\u5fc3\u6750\u6599\u3002\x0a\x0a\u91d3\u5728\u6750\u6599\u7279\u6027\u4e0a\u5c55\u73fe\u4e86\u9a5a\u4eba\u7684\u300c\u7a69\u5b9a\u8207\u654f\u611f\u300d\u4e26\u5b58\u3002\u96d6\u7136\u5b83\u5728\u4e7e\u71e5\u7a7a\u6c23\u4e2d\u76f8\u5c0d\u7a69\u5b9a\uff0c\u4f46\u5728\u6f6e\u6fd5\u74b0\u5883\u4e0b\u6703\u8fc5\u901f\u6c27\u5316\u3002\u6709\u8da3\u7684\u662f\uff0c\u91d3\u5728\u6975\u4f4e\u6eab\u4e0b\u6703\u8868\u73fe\u51fa\u8d85\u5c0e\u6027\u3002\u6b64\u5916\uff0c\u5c07\u5fae\u91cf\u91d3\u52a0\u5165\u927b\u3001\u9382\u6216\u9435\u5408\u91d1\u4e2d\uff0c\u80fd\u986f\u8457\u63d0\u5347\u6750\u6599\u7684\u52a0\u5de5\u6027\u8207\u8010\u8150\u8755\u6027\u80fd\u3002\u9019\u7a2e\u5f9e\u63a2\u6e2c\u4eba\u9ad4\u5167\u90e8\u5fae\u89c0\u75c5\u7076\u5230\u7a69\u5b9a\u6838\u5b50\u53cd\u61c9\u7210\u5de8\u5927\u80fd\u91cf\u7684\u8f49\u8b8a\uff0c\u7cbe\u78ba\u8a6e\u91cb\u4e86\u91d3\u5728\u9031\u671f\u8868\u4e2d\u4f5c\u70ba\u300c\u6975\u9650\u78c1\u6027\u5c0e\u9ad4\u300d\u7684\u7368\u7279\u5730\u4f4d\u3002",
  "\x54\x62":
    "\u92f1\x28\x54\x65\x72\x62\x69\x75\x6d\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x54\x62\uff0c\u539f\u5b50\u5e8f\x20\x36\x35\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u516d\u9031\u671f\u3001\u946d\u7cfb\u5143\u7d20\x28\x66\x20\u5340\u584a\x29\u3002\x31\x38\x34\x33\x20\u5e74\u7531\u745e\u5178\u5316\u5b78\u5bb6\u83ab\u6851\u5fb7\x28\x43\x61\x72\x6c\x20\x47\x75\x73\x74\x61\x66\x20\x4d\x6f\x73\x61\x6e\x64\x65\x72\x29\u5f9e\u4f0a\u7279\u6bd4\x28\x59\x74\x74\x65\x72\x62\x79\x29\u5c0f\u93ae\u7684\u7926\u77f3\u4e2d\u5206\u96e2\u51fa\u5176\u6c27\u5316\u7269\u3002\u92f1\u662f\u4e00\u7a2e\u9280\u767d\u8272\u7684\u5ef6\u5c55\u6027\u91d1\u5c6c\uff0c\u8cea\u5730\u67d4\u8edf\u5230\u53ef\u4ee5\u7528\u5200\u5207\u958b\u3002\u5b83\u662f\u73fe\u4ee3\u986f\u793a\u6280\u8853\u3001\u8072\u5b78\u63db\u80fd\u5668\u8207\u7cbe\u5bc6\u96fb\u5b50\u5143\u4ef6\u4e2d\u4e0d\u53ef\u6216\u7f3a\u7684\u300c\u7da0\u8272\u5149\u6e90\u300d\u8207\u300c\u6a5f\u68b0\u52d5\u529b\u300d\u6838\u5fc3\u6dfb\u52a0\u5143\u7d20\u3002\x0a\x0a\u92f1\u7684\u96fb\u5b50\u7d44\u614b\u70ba\x20\x5b\x58\x65\x5d\x34\x66\u2079\x36\x73\u00b2\uff0c\u7a69\u5b9a\u6c27\u5316\u614b\u4e3b\u8981\u70ba\x20\x2b\x33\u3002\u92f1\u96e2\u5b50\x28\x54\x62\u00b3\u207a\x29\u5177\u5099\u5353\u8d8a\u7684\u5149\u5b78\u7279\u6027\uff0c\u5728\u53d7\u6fc0\u767c\u5f8c\u80fd\u767c\u51fa\u6ce2\u9577\u7d04\x20\x35\x34\x35\x20\u5948\u7c73\u7684\u5f37\u70c8\u300c\u55ae\u8272\u7da0\u5149\u300d\u3002\u5728\u9ad8\u4e2d\u5316\u5b78\u8a0e\u8ad6\u767c\u5149\u5149\u8b5c\u8207\u96fb\u5b50\u8e8d\u9077\u80fd\u91cf\u6642\uff0c\u92f1\u662f\u63a2\u7a76\x20\x66\x2d\x66\x20\u8ecc\u57df\u8e8d\u9077\u7522\u751f\u7a84\u983b\u5149\u8b5c\u7684\u6307\u6a19\u5be6\u4f8b\u3002\u6b64\u5916\uff0c\u92f1\u5177\u5099\u5f37\u5927\u7684\u78c1\u77e9\uff0c\u5728\u4f4e\u6eab\u4e0b\u5c55\u73fe\u51fa\u8907\u96dc\u7684\u78c1\u5e8f\u7d50\u69cb\uff0c\u9019\u4f7f\u5176\u5728\u5f62\u6210\u7279\u5b9a\u5408\u91d1\u6642\u80fd\u5c55\u73fe\u51fa\u5de8\u5927\u7684\u7269\u7406\u5f62\u8b8a\u7279\u6027\u3002\x0a\x0a\u5728\u73fe\u4ee3\u7522\u696d\u61c9\u7528\u4e2d\uff0c\u92f1\u662f\u300c\u4e09\u57fa\u8272\u87a2\u5149\u7c89\u300d\u4e2d\u6700\u91cd\u8981\u7684\u7da0\u8272\u6210\u5206\u3002\u5b83\u5ee3\u6cdb\u61c9\u7528\u65bc\u9ad8\u756b\u8cea\u986f\u793a\u5668\u3001\x4c\x45\x44\x20\u71c8\u5177\u53ca\u7bc0\u80fd\u71c8\u4e2d\uff0c\u8ca0\u8cac\u63d0\u4f9b\u7d14\u6de8\u7684\u7da0\u8272\u6ce2\u6bb5\uff0c\u5c0d\u63d0\u5347\u8272\u5f69\u98fd\u548c\u5ea6\u8207\u8996\u89ba\u8212\u9069\u5ea6\u81f3\u95dc\u91cd\u8981\u3002\u5728\u6750\u6599\u79d1\u5b78\u9818\u57df\uff0c\u92f1\u8207\u9435\u3001\u93d1\u7d44\u6210\u7684\u5408\u91d1\u300c\u9435\u82ac\u8afe\x2d\x44\u300d\x28\x54\x65\x72\x66\x65\x6e\x6f\x6c\x2d\x44\x29\u5177\u5099\u9a5a\u4eba\u7684\u300c\u78c1\u6b6a\u73fe\u8c61\u300d\x28\x4d\x61\x67\x6e\x65\x74\x6f\x73\x74\x72\x69\x63\x74\x69\x6f\x6e\x29\uff1a\u7576\u5916\u52a0\u78c1\u5834\u6539\u8b8a\u6642\uff0c\u6750\u6599\u6703\u7522\u751f\u986f\u8457\u7684\u5c3a\u5bf8\u8b8a\u5316\uff0c\u9019\u4f7f\u5176\u6210\u70ba\u88fd\u9020\u9ad8\u6027\u80fd\u8072\u7d0d\u3001\u5fae\u4f4d\u79fb\u81f4\u52d5\u5668\u8207\u9ad8\u9748\u654f\u5ea6\u611f\u6e2c\u5668\u7684\u6838\u5fc3\u6750\u6599\u3002\x0a\x0a\u92f1\u5728\u6975\u7aef\u7269\u7406\u72c0\u614b\u4e0b\u5c55\u73fe\u4e86\u4ee4\u4eba\u8457\u8ff7\u7684\u8b8a\u76f8\u80fd\u529b\u3002\u5b83\u5728\u6975\u4f4e\u6eab\x28\u7d04\x20\x32\x33\x30\x20\x4b\x20\u4ee5\u4e0b\x29\u6642\u6703\u5f9e\u9806\u78c1\u6027\u8f49\u8b8a\u70ba\u53cd\u9435\u78c1\u6027\uff0c\u518d\u9032\u4e00\u6b65\u8f49\u8b8a\u70ba\u9435\u78c1\u6027\uff0c\u9019\u7a2e\u591a\u6a23\u7684\u78c1\u76f8\u8b8a\u4f7f\u5176\u6210\u70ba\u7814\u7a76\u56fa\u614b\u7269\u7406\u7684\u91cd\u8981\u6a23\u672c\u3002\u6709\u8da3\u7684\u662f\uff0c\u96d6\u7136\u92f1\u5728\u5730\u6bbc\u4e2d\u6975\u5176\u7a00\u5c11\u4e14\u958b\u63a1\u4e0d\u6613\uff0c\u4f46\u53ea\u9700\u6975\u5fae\u91cf\u7684\u92f1\u647b\u96dc\uff0c\u4fbf\u80fd\u986f\u8457\u6539\u8b8a\u56fa\u614b\u96f7\u5c04\u5668\u8207\u5149\u901a\u8a0a\u5143\u4ef6\u7684\u6548\u80fd\u3002\u9019\u7a2e\u5f9e\u5b9a\u7fa9\u6578\u4f4d\u4e16\u754c\u7684\u7da0\u8272\u5149\u8b5c\u5230\u9a45\u52d5\u7cbe\u5bc6\u6a5f\u68b0\u7684\u5fae\u89c0\u5f62\u8b8a\uff0c\u7cbe\u78ba\u8a6e\u91cb\u4e86\u92f1\u5728\u7a00\u571f\u5143\u7d20\u4e2d\u7cbe\u7dfb\u4e14\u9ad8\u6548\u7684\u529f\u80fd\u5b9a\u4f4d\u3002",
  "\x44\x79":
    "\u93d1\x28\x44\x79\x73\x70\x72\x6f\x73\x69\x75\x6d\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x44\x79\uff0c\u539f\u5b50\u5e8f\x20\x36\x36\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u516d\u9031\u671f\u3001\u946d\u7cfb\u5143\u7d20\x28\x66\x20\u5340\u584a\x29\u3002\u5176\u540d\u7a31\u6e90\u65bc\u5e0c\u81d8\u8a9e\u300c\x64\x79\x73\x70\x72\x6f\x73\x69\x74\x6f\x73\u300d\uff0c\u610f\u70ba\u300c\u96e3\u4ee5\u7372\u5f97\u300d\uff0c\u53cd\u6620\u4e86\x20\x31\x38\x38\x36\x20\u5e74\u6ce2\u74e6\u535a\u5fb7\u6717\x28\x4c\x65\x63\x6f\x71\x20\x64\x65\x20\x42\x6f\x69\x73\x62\x61\x75\x64\x72\x61\x6e\x29\u6b77\u7d93\u6578\u5343\u6b21\u5206\u6b65\u7d50\u6676\u624d\u5c07\u5176\u5206\u96e2\u7684\u8271\u8f9b\u3002\u93d1\u662f\u4e00\u7a2e\u5177\u6709\u9280\u767d\u8272\u91d1\u5c6c\u5149\u6fa4\u7684\u8edf\u91d1\u5c6c\uff0c\u6027\u8cea\u76f8\u5c0d\u7a69\u5b9a\uff0c\u4f46\u5c0d\u6c34\u5206\u8207\u9178\u6975\u70ba\u654f\u611f\u3002\u5b83\u662f\u7576\u4ee3\u80fd\u6e90\u79d1\u6280\u8207\u5f37\u78c1\u6750\u6599\u4e2d\uff0c\u6c7a\u5b9a\u8a2d\u5099\u5728\u9ad8\u6eab\u4e0b\u80fd\u5426\u7a69\u5b9a\u904b\u884c\u7684\u300c\u95dc\u9375\u7a69\u5b9a\u5291\u300d\u3002\x0a\x0a\u93d1\u7684\u96fb\u5b50\u7d44\u614b\u70ba\x20\x5b\x58\x65\x5d\x34\x66\u00b9\u2070\x36\x73\u00b2\uff0c\u6700\u5e38\u898b\u7684\u6c27\u5316\u614b\u70ba\x20\x2b\x33\u3002\u93d1\u539f\u5b50\u64c1\u6709\u6975\u9ad8\u7684\u78c1\u77e9\uff0c\u5728\u4f4e\u6eab\u4e0b\u5177\u5099\u6975\u5f37\u7684\u78c1\u6027\u3002\u5728\u9ad8\u4e2d\u5316\u5b78\u63a2\u8a0e\u5143\u7d20\u9031\u671f\u6027\u8da8\u52e2\u6642\uff0c\u93d1\u662f\u7814\u7a76\x20\x34\x66\x20\u96fb\u5b50\u6578\u589e\u52a0\u5c0d\u539f\u5b50\u534a\u5f91\x28\u946d\u7cfb\u6536\u7e2e\x29\u53ca\u78c1\u4ea4\u4e92\u4f5c\u7528\u5f71\u97ff\u7684\u91cd\u8981\u5c0d\u8c61\u3002\u93d1\u5316\u5408\u7269\x28\u5982\x20\x44\x79\u2082\x4f\u2083\x29\u901a\u5e38\u5448\u73fe\u6de1\u9ec3\u7da0\u8272\uff0c\u5c55\u73fe\u51fa\u7279\u5b9a\u7684\u5149\u5b78\u5438\u6536\u8b5c\u7dda\u3002\u503c\u5f97\u6ce8\u610f\u7684\u662f\uff0c\u93d1\u7684\u4e2d\u5b50\u6355\u6349\u622a\u9762\u6975\u5927\uff0c\u9019\u4f7f\u5176\u5728\u6838\u7269\u7406\u5be6\u9a57\u4e2d\u5177\u5099\u512a\u7570\u7684\u4e2d\u5b50\u5c4f\u853d\u8207\u8abf\u7bc0\u80fd\u529b\u3002\x0a\x0a\u5728\u73fe\u4ee3\u7da0\u8272\u80fd\u6e90\u93c8\u4e2d\uff0c\u93d1\u626e\u6f14\u8457\u4e0d\u53ef\u6216\u7f3a\u7684\u300c\u8010\u71b1\u5b88\u8b77\u8005\u300d\u89d2\u8272\u3002\u91f9\u9435\u787c\x28\x4e\x64\x46\x65\x42\x29\u5f37\u78c1\u9435\u96d6\u7136\u78c1\u529b\u9a5a\u4eba\uff0c\u4f46\u5728\u9ad8\u6eab\u4e0b\u6975\u6613\u5931\u53bb\u78c1\u6027\uff1b\u900f\u904e\u52a0\u5165\u5fae\u91cf\u7684\u93d1\uff0c\u80fd\u986f\u8457\u63d0\u9ad8\u78c1\u9435\u7684\u300c\u77ef\u9811\u529b\u300d\x28\x43\x6f\x65\x72\x63\x69\x76\x69\x74\x79\x29\uff0c\u4f7f\u5176\u5728\u96fb\u52d5\u8eca\u99ac\u9054\u8207\u98a8\u529b\u767c\u96fb\u6a5f\u7684\u9ad8\u6eab\u5de5\u4f5c\u74b0\u5883\u4e2d\u4f9d\u7136\u4fdd\u6301\u5f37\u52c1\u78c1\u529b\u3002\u5728\u7167\u660e\u8207\u96f7\u5c04\u6280\u8853\u4e0a\uff0c\u93d1\u8207\u7898\u7d50\u5408\u88fd\u6210\u7684\u91d1\u5c6c\u9e75\u5316\u7269\u71c8\uff0c\u80fd\u767c\u51fa\u63a5\u8fd1\u967d\u5149\u7684\u9023\u7e8c\u5149\u8b5c\uff0c\u5e38\u7528\u65bc\u5927\u578b\u5834\u9928\u7167\u660e\uff1b\u800c\u5176\u647b\u96dc\u7684\u96f7\u5c04\u6676\u9ad4\u5247\u80fd\u767c\u51fa\u9ad8\u6548\u7684\u7d05\u5916\u8f3b\u5c04\u3002\x0a\x0a\u93d1\u5728\u6975\u4f4e\u6eab\u4e0b\u5c55\u73fe\u4e86\u67d0\u4e9b\u7279\u6b8a\u7684\u7269\u7406\u76f8\u8b8a\u7279\u5fb5\u3002\u5b83\u5728\u7d55\u5c0d\u6eab\u5ea6\x20\x38\x35\x20\x4b\x20\u4ee5\u4e0b\u6703\u5f9e\u9806\u78c1\u614b\u8f49\u8b8a\u70ba\u9435\u78c1\u614b\uff0c\u4e26\u4f34\u96a8\u986f\u8457\u7684\u6676\u683c\u5f62\u8b8a\uff0c\u9019\u4f7f\u5176\u5728\u78c1\u88fd\u51b7\u8207\u7cbe\u5bc6\u50b3\u611f\u5668\u7814\u7a76\u4e2d\u5177\u6709\u91cd\u8981\u5730\u4f4d\u3002\u6709\u8da3\u7684\u662f\uff0c\u93d1\u96d6\u7136\u88ab\u5217\u70ba\u300c\u96e3\u4ee5\u7372\u5f97\u300d\u7684\u5143\u7d20\uff0c\u4f46\u96a8\u8457\u73fe\u4ee3\u63a1\u7926\u8207\u5206\u96e2\u6280\u8853\u7684\u9032\u6b65\uff0c\u5b83\u5df2\u6210\u70ba\u652f\u6490\u6c38\u7e8c\u4ea4\u901a\u8207\u9ad8\u968e\u570b\u9632\u5de5\u696d\u7684\u6230\u7565\u652f\u67f1\u3002\u9019\u7a2e\u5f9e\u5be6\u9a57\u5ba4\u4e2d\u96e3\u4ee5\u88ab\u8fa8\u8b58\u7684\u96dc\u8cea\u5230\u9a45\u52d5\u65b0\u80fd\u6e90\u8eca\u6838\u5fc3\u99ac\u9054\u7684\u8f49\u8b8a\uff0c\u7cbe\u78ba\u8a6e\u91cb\u4e86\u93d1\u5728\u9031\u671f\u8868\u4e2d\u5f9e\u7a00\u6709\u6027\u8f49\u5316\u70ba\u95dc\u9375\u529f\u80fd\u7684\u6b77\u7a0b\u3002",
  "\x48\x6f":
    "\u9225\x28\x48\x6f\x6c\x6d\x69\x75\x6d\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x48\x6f\uff0c\u539f\u5b50\u5e8f\x20\x36\x37\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u516d\u9031\u671f\u3001\u946d\u7cfb\u5143\u7d20\x28\x66\x20\u5340\u584a\x29\u3002\u5176\u540d\u7a31\u6e90\u65bc\u745e\u5178\u9996\u90fd\u65af\u5fb7\u54e5\u723e\u6469\u7684\u62c9\u4e01\u8a9e\u540d\u7a31\u300c\x48\x6f\x6c\x6d\x69\x61\u300d\u3002\x31\x38\x37\x38\x20\u5e74\u7531\u745e\u58eb\u5316\u5b78\u5bb6\u7d22\u96f7\u7279\x28\x4d\x61\x72\x63\x20\x44\x65\x6c\x61\x66\x6f\x6e\x74\x61\x69\x6e\x65\x29\u8207\u585e\u96f7\x28\x4a\x61\x63\x71\x75\x65\x73\x2d\x4c\x6f\x75\x69\x73\x20\x53\x6f\x72\x65\x74\x29\u767c\u73fe\u8b5c\u7dda\u7570\u5e38\uff0c\u96a8\u5f8c\u7531\u745e\u5178\u5316\u5b78\u5bb6\u514b\u5229\u592b\x28\x50\x65\x72\x20\x54\x65\x6f\x64\x6f\x72\x20\x43\x6c\x65\x76\x65\x29\u6b63\u5f0f\u5206\u96e2\u3002\u9225\u662f\u4e00\u7a2e\u9280\u767d\u8272\u3001\u5177\u5099\u91d1\u5c6c\u5149\u6fa4\u7684\u8edf\u91d1\u5c6c\uff0c\u5316\u5b78\u6027\u8cea\u6d3b\u6f51\uff0c\u5728\u4e7e\u71e5\u7a7a\u6c23\u4e2d\u76f8\u5c0d\u7a69\u5b9a\uff0c\u4f46\u5728\u6f6e\u6fd5\u74b0\u5883\u4e0b\u6703\u8fc5\u901f\u6c27\u5316\u3002\u5b83\u662f\u6240\u6709\u5929\u7136\u5143\u7d20\u4e2d\u5177\u5099\u6700\u9ad8\u300c\u78c1\u77e9\u300d\u7684\u6210\u54e1\uff0c\u88ab\u8b7d\u70ba\u78c1\u5b78\u7814\u7a76\u4e2d\u7684\u6975\u81f4\u6750\u6599\u3002\x0a\x0a\u5728\u5316\u5b78\u884c\u70ba\u4e0a\uff0c\u9225\u7684\u96fb\u5b50\u7d44\u614b\u70ba\x20\x5b\x58\x65\x5d\x34\x66\u00b9\u00b9\x36\x73\u00b2\uff0c\u7a69\u5b9a\u6c27\u5316\u614b\u70ba\x20\x2b\x33\u3002\u9225\u96e2\u5b50\x28\x48\x6f\u00b3\u207a\x29\u5c55\u73fe\u51fa\u6975\u5176\u5f37\u70c8\u7684\u9806\u78c1\u6027\uff0c\u9019\u6e90\u65bc\u5176\x20\x34\x66\x20\u8ecc\u57df\u4e2d\u64c1\u6709\u5927\u91cf\u672a\u6210\u5c0d\u96fb\u5b50\u3002\u5728\u9ad8\u4e2d\u5316\u5b78\u63a2\u8a0e\u539f\u5b50\u7d50\u69cb\u8207\u78c1\u6027\u7684\u95dc\u4fc2\u6642\uff0c\u9225\u662f\u7406\u89e3\u96fb\u5b50\u6392\u5e03\u5982\u4f55\u7522\u751f\u5b8f\u89c0\u78c1\u4ea4\u4e92\u4f5c\u7528\u7684\u9802\u7d1a\u6848\u4f8b\u3002\u6b64\u5916\uff0c\u9225\u96e2\u5b50\u5177\u5099\u7368\u7279\u7684\u5149\u5b78\u6027\u8cea\uff0c\u5176\u6c27\u5316\u7269\u5728\u4e0d\u540c\u5149\u6e90\u4e0b\u6703\u7522\u751f\u986f\u8457\u7684\u8b8a\u8272\u6548\u61c9\x28\u5f9e\u9ec3\u8272\u5230\u6843\u7d05\u8272\x29\uff0c\u9019\u4f7f\u5176\u5728\u7279\u6b8a\u5149\u5b78\u73bb\u7483\u8207\u6ffe\u5149\u7247\u7684\u88fd\u9020\u4e2d\u5177\u6709\u9ad8\u5ea6\u9451\u5225\u529b\u3002\x0a\x0a\u73fe\u4ee3\u79d1\u6280\u4e2d\uff0c\u9225\u7684\u6975\u9650\u78c1\u6027\u4f7f\u5176\u6210\u70ba\u88fd\u9020\u5f37\u529b\u6c38\u78c1\u6750\u6599\u8207\u300c\u78c1\u901a\u91cf\u96c6\u4e2d\u5668\u300d\u7684\u6838\u5fc3\u6dfb\u52a0\u7269\uff0c\u80fd\u6709\u6548\u5f15\u5c0e\u4e26\u589e\u5f37\u78c1\u5834\u5f37\u5ea6\u3002\u5728\u91ab\u7642\u9818\u57df\uff0c\u300c\u9225\u96f7\u5c04\u300d\x28\x48\x6f\x3a\x59\x41\x47\x20\x6c\x61\x73\x65\x72\x29\u662f\u76ee\u524d\u6ccc\u5c3f\u5916\u79d1\u8207\u5fae\u5275\u624b\u8853\u7684\u4e3b\u529b\u5de5\u5177\uff0c\u5176\u767c\u51fa\u7684\x20\x32\x2e\x31\x20\u5fae\u7c73\u6ce2\u6bb5\u80fd\u88ab\u6c34\u5206\u5b50\u9ad8\u5ea6\u5438\u6536\uff0c\u5177\u5099\u6975\u4f73\u7684\u7d44\u7e54\u5207\u5272\u80fd\u529b\u8207\u6b62\u8840\u6548\u679c\u3002\u5728\u6838\u80fd\u5de5\u7a0b\u4e2d\uff0c\u7531\u65bc\u9225\u5177\u5099\u8f03\u9ad8\u7684\u4e2d\u5b50\u5438\u6536\u622a\u9762\uff0c\u5b83\u5e38\u88ab\u7528\u4f5c\u6838\u53cd\u61c9\u7210\u4e2d\u7684\u300c\u53ef\u71c3\u6bd2\u7269\u300d\x28\x42\x75\x72\x6e\x61\x62\x6c\x65\x20\x70\x6f\x69\x73\x6f\x6e\x29\uff0c\u5354\u52a9\u7cbe\u78ba\u8abf\u7bc0\u53cd\u61c9\u7210\u5167\u7684\u53cd\u61c9\u6027\uff0c\u78ba\u4fdd\u9577\u6548\u904b\u4f5c\u7684\u5b89\u5168\u8207\u7a69\u5b9a\u3002\x0a\x0a\u95dc\u65bc\u9225\u7684\u7269\u7406\u73fe\u8c61\uff0c\u5b83\u5728\u6975\u4f4e\u6eab\u4e0b\u6703\u5c55\u73fe\u51fa\u8907\u96dc\u7684\u78c1\u5e8f\u7d50\u69cb\uff0c\u5f9e\u9435\u78c1\u6027\u8f49\u8b8a\u70ba\u53cd\u9435\u78c1\u6027\uff0c\u9019\u4f7f\u5176\u6210\u70ba\u7814\u7a76\u56fa\u614b\u91cf\u5b50\u78c1\u5b78\u7684\u91cd\u8981\u6a23\u672c\u3002\u6709\u8da3\u7684\u662f\uff0c\u7531\u65bc\u9225\u96f7\u5c04\u5728\u4eba\u773c\u5b89\u5168\u6ce2\u6bb5\u8868\u73fe\u512a\u7570\uff0c\u5b83\u4e5f\u5ee3\u6cdb\u61c9\u7528\u65bc\u6a5f\u8f09\u96f7\u5c04\u6e2c\u8ddd\u5100\u8207\u5927\u6c23\u9059\u6e2c\u7cfb\u7d71\u4e2d\u3002\u96d6\u7136\u9225\u5728\u5730\u6bbc\u4e2d\u7684\u8c50\u5ea6\u4e26\u4e0d\u6975\u4f4e\uff0c\u4f46\u56e0\u5176\u78c1\u6027\u7279\u5fb5\u904e\u65bc\u7a81\u51fa\uff0c\u4f7f\u5176\u61c9\u7528\u9ad8\u5ea6\u96c6\u4e2d\u65bc\u7cbe\u5bc6\u80fd\u91cf\u7ba1\u7406\u8207\u9ad8\u7aef\u91ab\u7642\u6280\u8853\u3002\u9019\u7a2e\u5f9e\u5730\u540d\u7e2e\u5beb\u5230\u5b9a\u7fa9\u78c1\u5834\u5f37\u5ea6\u5dd4\u5cf0\u7684\u8f49\u8b8a\uff0c\u7cbe\u78ba\u8a6e\u91cb\u4e86\u9225\u5728\u946d\u7cfb\u5143\u7d20\u4e2d\u4e0d\u53ef\u66ff\u4ee3\u7684\u5730\u4f4d\u3002",
  "\x45\x72":
    "\u927a\x28\x45\x72\x62\x69\x75\x6d\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x45\x72\uff0c\u539f\u5b50\u5e8f\x20\x36\x38\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u516d\u9031\u671f\u3001\u946d\u7cfb\u5143\u7d20\x28\x66\x20\u5340\u584a\x29\u3002\x31\x38\x34\x33\x20\u5e74\u7531\u745e\u5178\u5316\u5b78\u5bb6\u83ab\u6851\u5fb7\x28\x43\x61\x72\x6c\x20\x47\x75\x73\x74\x61\x66\x20\x4d\x6f\x73\x61\x6e\x64\x65\x72\x29\u5f9e\u4f0a\u7279\u6bd4\x28\x59\x74\x74\x65\x72\x62\x79\x29\u5c0f\u93ae\u7684\u7926\u77f3\u4e2d\u5206\u96e2\u3002\u927a\u662f\u4e00\u7a2e\u5177\u6709\u9280\u767d\u8272\u5149\u6fa4\u7684\u97cc\u6027\u91d1\u5c6c\uff0c\u5728\u5730\u6bbc\u4e2d\u4e3b\u8981\u4f34\u751f\u65bc\u7368\u5c45\u77f3\u8207\u78f7\u91d4\u7926\u3002\u927a\u6700\u8457\u540d\u7684\u7279\u5fb5\u662f\u5176\u96e2\u5b50\u5728\u591a\u7a2e\u57fa\u8cea\u4e2d\u80fd\u767c\u51fa\u7a69\u5b9a\u7684\u7c89\u7d05\u8272\u87a2\u5149\uff0c\u4f7f\u5176\u5728\u88dd\u98fe\u7f8e\u5b78\u8207\u5149\u901a\u8a0a\u7522\u696d\u4e2d\u7686\u5360\u6709\u8209\u8db3\u8f15\u91cd\u7684\u5730\u4f4d\uff0c\u662f\u652f\u6490\u73fe\u4ee3\u5168\u7403\u7db2\u969b\u7db2\u8def\u50b3\u8f38\u6548\u7387\u7684\u300c\u5149\u5b78\u5f15\u64ce\u300d\u3002\x0a\x0a\u927a\u7684\u96fb\u5b50\u7d44\u614b\u70ba\x20\x5b\x58\x65\x5d\x34\x66\u00b9\u00b2\x36\x73\u00b2\uff0c\u6700\u7a69\u5b9a\u7684\u6c27\u5316\u614b\u70ba\x20\x2b\x33\u3002\u927a\u96e2\u5b50\x28\x45\x72\u00b3\u207a\x29\u5177\u5099\u6975\u5176\u7279\u6b8a\u7684\u5149\u5b78\u5438\u6536\u8b5c\u7dda\uff0c\u80fd\u5c07\u7279\u5b9a\u6ce2\u9577\u7684\u6fc0\u767c\u5149\u8f49\u5316\u70ba\u7a84\u983b\u7684\u87a2\u5149\u767c\u5c04\u3002\u5728\u9ad8\u4e2d\u5316\u5b78\u8a0e\u8ad6\u96fb\u5b50\u8e8d\u9077\u8207\u80fd\u968e\u898f\u5f8b\u6642\uff0c\u927a\u662f\u8aaa\u660e\x20\x66\x20\u8ecc\u57df\u96fb\u5b50\u5728\u914d\u4f4d\u5834\u4e0b\u7522\u751f\u8907\u96dc\u80fd\u968e\u5206\u88c2\u7684\u5178\u578b\u6848\u4f8b\u3002\u927a\u7684\u6c27\u5316\u7269\x28\x45\x72\u2082\x4f\u2083\x29\u5448\u73fe\u512a\u7f8e\u7684\u7c89\u7d05\u8272\uff0c\u5177\u5099\u6975\u4f73\u7684\u5316\u5b78\u7a69\u5b9a\u6027\uff0c\u5e38\u88ab\u88fd\u6210\u91c9\u6599\u8207\u7279\u6b8a\u73bb\u7483\uff0c\u4e14\u5728\u9ad8\u6eab\u4e0b\u4ecd\u80fd\u4fdd\u6301\u7a69\u5b9a\u7684\u767c\u8272\uff0c\u9019\u4f7f\u5176\u5728\u9676\u74f7\u8207\u5149\u5b78\u6ffe\u5149\u7247\u5de5\u696d\u4e2d\u5177\u6709\u6838\u5fc3\u7af6\u722d\u529b\u3002\x0a\x0a\u5728\u73fe\u4ee3\u61c9\u7528\u9818\u57df\uff0c\u927a\u662f\u5149\u7e96\u901a\u8a0a\u6280\u8853\u7684\u82f1\u96c4\u3002\u6240\u8b02\u7684\u300c\u647b\u927a\u5149\u7e96\u653e\u5927\u5668\u300d\x28\x45\x44\x46\x41\x29\u5229\u7528\x20\x45\x72\u00b3\u207a\x20\u96e2\u5b50\u7684\u7279\u5b9a\u80fd\u968e\u8e8d\u9077\uff0c\u80fd\u76f4\u63a5\u5c0d\u5149\u7e96\u4e2d\u50b3\u8f38\u7684\x20\x31\x2e\x35\x35\x20\u5fae\u7c73\u8a0a\u865f\u9032\u884c\u5149\u5b78\u653e\u5927\uff0c\u4e0d\u9700\u7d93\u904e\u96fb\u4fe1\u865f\u8f49\u63db\u3002\u7531\u65bc\u6b64\u6ce2\u6bb5\u6b63\u597d\u4f4d\u65bc\u5149\u7e96\u50b3\u8f38\u7684\u6700\u4f4e\u640d\u8017\u7a97\u53e3\uff0c\u9019\u9805\u6280\u8853\u4f7f\u5f97\u9577\u8ddd\u96e2\u3001\u8d85\u9ad8\u901f\u7684\u8de8\u6d77\u5149\u7e9c\u901a\u8a0a\u6210\u70ba\u53ef\u80fd\u3002\u5728\u91ab\u5b78\u4e0a\uff0c\u927a\u96f7\u5c04\x28\x45\x72\x3a\x59\x41\x47\x29\u767c\u51fa\u7684\x20\x32\x2e\x39\x34\x20\u5fae\u7c73\u8f3b\u5c04\u6975\u6613\u88ab\u7d44\u7e54\u8868\u5c64\u5438\u6536\uff0c\u5e38\u7528\u65bc\u7259\u79d1\u9664\u76ba\u8207\u76ae\u819a\u7f8e\u5bb9\u624b\u8853\uff0c\u5177\u5099\u5275\u50b7\u5c0f\u3001\u5fa9\u539f\u5feb\u4e14\u71b1\u640d\u50b7\u4f4e\u7684\u512a\u52e2\u3002\x0a\x0a\u927a\u5728\u6975\u9650\u6750\u6599\u61c9\u7528\u4e2d\u5c55\u73fe\u4e86\u591a\u529f\u80fd\u6027\u3002\u5b83\u662f\u91cd\u8981\u7684\u5408\u91d1\u6dfb\u52a0\u5291\uff0c\u5c07\u5fae\u91cf\u927a\u52a0\u5165\u91e9\u6216\u9382\u5408\u91d1\u4e2d\uff0c\u80fd\u986f\u8457\u63d0\u5347\u6750\u6599\u7684\u6297\u6c27\u5316\u6027\u8207\u6a5f\u68b0\u52a0\u5de5\u6027\u3002\u53cd\u76f4\u89ba\u7684\u662f\uff0c\u927a\u5728\u6838\u7269\u7406\u4e2d\u4ea6\u626e\u6f14\u91cd\u8981\u89d2\u8272\uff0c\u5176\u540c\u4f4d\u7d20\u5177\u6709\u8f03\u5927\u7684\u4e2d\u5b50\u6355\u7372\u9762\u7a4d\uff0c\u56e0\u6b64\u88ab\u7528\u4f5c\u6838\u53cd\u61c9\u7210\u7684\u63a7\u5236\u6750\u6599\u3002\u6709\u8da3\u7684\u662f\uff0c\u96d6\u7136\u927a\u901a\u5e38\u5448\u73fe\u7c89\u7d05\u8272\u7684\u8996\u89ba\u5370\u8c61\uff0c\u4f46\u91d1\u5c6c\u55ae\u8cea\u5728\u7a7a\u6c23\u4e2d\u6c27\u5316\u5f8c\u6703\u5f62\u6210\u7070\u9ed1\u8272\u7684\u8584\u819c\u3002\u9019\u7a2e\u5f9e\u6c7a\u5b9a\u5168\u7403\u7db2\u8def\u50b3\u8f38\u901f\u5ea6\u7684\u5149\u5b78\u653e\u5927\u5668\u5230\u88dd\u98fe\u85dd\u8853\u4e2d\u7684\u512a\u96c5\u7c89\u7d05\uff0c\u7cbe\u78ba\u8a6e\u91cb\u4e86\u927a\u5728\u904e\u6e21\u5340\u5143\u7d20\u4e2d\u517c\u5177\u6280\u8853\u5f35\u529b\u8207\u7f8e\u5b78\u50f9\u503c\u7684\u96d9\u91cd\u89d2\u8272\u3002",
  "\x54\x6d":
    "\u92a9\x28\x54\x68\x75\x6c\x69\x75\x6d\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x54\x6d\uff0c\u539f\u5b50\u5e8f\x20\x36\x39\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u516d\u9031\u671f\u3001\u946d\u7cfb\u5143\u7d20\x28\x66\x20\u5340\u584a\x29\u3002\u5176\u540d\u7a31\u53d6\u81ea\u5317\u6b50\u65af\u582a\u5730\u90a3\u7dad\u4e9e\u7684\u53e4\u5730\u540d\u300c\u6975\u5317\u4e4b\u5730\u300d\x28\x54\x68\x75\x6c\x65\x29\u3002\x31\x38\x37\x39\x20\u5e74\u7531\u745e\u5178\u5316\u5b78\u5bb6\u514b\u5229\u592b\x28\x50\x65\x72\x20\x54\x65\x6f\x64\x6f\x72\x20\x43\x6c\x65\x76\x65\x29\u5728\u5206\u6790\u927a\u571f\u96dc\u8cea\u6642\u767c\u73fe\u3002\u92a9\u662f\u5929\u7136\u5b58\u5728\u7684\u975e\u653e\u5c04\u6027\u946d\u7cfb\u5143\u7d20\u4e2d\u6700\u7a00\u6709\u7684\u4e00\u54e1\x28\u50c5\u512a\u65bc\u9255\x29\uff0c\u5176\u5730\u6bbc\u8c50\u5ea6\u6975\u4f4e\u3002\u5b83\u662f\u4e00\u7a2e\u9280\u767d\u8272\u3001\u5177\u5099\u9ad8\u5ea6\u5ef6\u5c55\u6027\u7684\u8edf\u91d1\u5c6c\uff0c\u96d6\u7136\u5316\u5b78\u6027\u8cea\u6d3b\u6f51\uff0c\u4f46\u5728\u7cbe\u5bc6\u96f7\u5c04\u91ab\u7642\u8207\u9632\u507d\u6280\u8853\u4e2d\u5c55\u73fe\u51fa\u7368\u7279\u7684\u61c9\u7528\u50f9\u503c\u3002\x0a\x0a\u92a9\u7684\u96fb\u5b50\u7d44\u614b\u70ba\x20\x5b\x58\x65\x5d\x34\x66\u00b9\u00b3\x36\x73\u00b2\uff0c\u5728\u5316\u5b78\u6027\u8cea\u4e0a\u4ee5\x20\x2b\x33\x20\u6c27\u5316\u614b\u6700\u70ba\u5e38\u898b\uff0c\u4f46\u5728\u6975\u7aef\u9084\u539f\u74b0\u5883\u4e0b\u4ea6\u53ef\u5c55\u73fe\x20\x2b\x32\x20\u6c27\u5316\u614b\x28\u5982\x20\x54\x6d\x49\u2082\x29\u3002\u92a9\u96e2\u5b50\x28\x54\x6d\u00b3\u207a\x29\u5728\u7d2b\u5916\u5149\u6fc0\u767c\u4e0b\u6703\u767c\u51fa\u5f37\u70c8\u7684\u9bae\u85cd\u8272\u87a2\u5149\u3002\u5728\u9ad8\u4e2d\u5316\u5b78\u95dc\u65bc\u539f\u5b50\u5e8f\u8207\u96fb\u5b50\u96f2\u5206\u5e03\u7684\u8a0e\u8ad6\u4e2d\uff0c\u92a9\u662f\u7406\u89e3\u96fb\u5b50\u6578\u8da8\u65bc\u5168\u6eff\x28\x34\x66\u00b9\u2074\x29\u524d\uff0c\u539f\u5b50\u5167\u90e8\u6709\u6548\u6838\u96fb\u8377\u589e\u52a0\u5c0d\u7269\u7406\u6027\u8cea\u5fae\u64fe\u7684\u89c0\u5bdf\u9ede\u3002\u5118\u7ba1\u92a9\u50f9\u683c\u6602\u8cb4\uff0c\u4f46\u5176\u7279\u5b9a\u7684\u5149\u5b78\u8207\u6838\u6027\u8cea\uff0c\u4f7f\u5176\u5728\u7f3a\u4e4f\u66ff\u4ee3\u65b9\u6848\u7684\u7279\u7a2e\u9818\u57df\u4e2d\u4e0d\u53ef\u6216\u7f3a\u3002\x0a\x0a\u5728\u73fe\u4ee3\u91ab\u5b78\u8207\u6838\u5b50\u6280\u8853\u4e2d\uff0c\u92a9\u5c55\u73fe\u4e86\u6975\u5927\u7684\u6f5b\u529b\u3002\u540c\u4f4d\u7d20\x20\u92a9\x2d\x31\x37\x30\x28\u00b9\u2077\u2070\x54\x6d\x29\u5728\u6838\u53cd\u61c9\u7210\u4e2d\u53d7\u7167\u5c04\u5f8c\u80fd\u767c\u5c04\u9ad8\u80fd\u96fb\u5b50\u8207\u4f4e\u80fd\x20\x58\x20\u5c04\u7dda\uff0c\u88ab\u88fd\u6210\u8f15\u5de7\u7684\u300c\u4fbf\u651c\u5f0f\x20\x58\x20\u5c04\u7dda\u6e90\u300d\uff0c\u7528\u65bc\u5de5\u696d\u63a2\u50b7\u8207\u6230\u5730\u91ab\u7642\u3002\u5728\u5149\u96fb\u9818\u57df\uff0c\u647b\u92a9\u96f7\u5c04\u5668\u80fd\u767c\u51fa\u4eba\u773c\u5b89\u5168\u7684\x20\x32\x2e\x30\x20\u5fae\u7c73\u7d05\u5916\u5149\uff0c\u5728\u9059\u6e2c\x28\x4c\x49\x44\x41\x52\x29\u8207\u5149\u901a\u8a0a\u7cfb\u7d71\u4e2d\u5177\u5099\u7a7f\u900f\u7159\u9727\u8207\u5927\u6c23\u7684\u512a\u52e2\u3002\u6b64\u5916\uff0c\u92a9\u7684\u85cd\u8272\u87a2\u5149\u7279\u6027\u4f7f\u5176\u88ab\u5ee3\u6cdb\u7528\u65bc\u5404\u570b\u7d19\u5e63\u7684\u9632\u507d\u58a8\u6c34\u4e2d\uff0c\u5728\u7279\u5b9a\u6ce2\u9577\u6fc0\u767c\u4e0b\u986f\u73fe\u7279\u5fb5\u8b5c\u7dda\u4ee5\u5340\u5206\u771f\u507d\u3002\x0a\x0a\u95dc\u65bc\u92a9\u7684\u7269\u7406\u7279\u6027\uff0c\u5b83\u662f\u6975\u5c11\u6578\u5728\u6975\u7aef\u689d\u4ef6\u4e0b\u80fd\u5c55\u73fe\u9435\u78c1\u6027\u898f\u5f8b\u7684\u7a00\u571f\u91d1\u5c6c\u4e4b\u4e00\uff0c\u4e14\u5176\u5c0e\u96fb\u6027\u96a8\u6eab\u5ea6\u8b8a\u5316\u7684\u8da8\u52e2\u88ab\u7528\u65bc\u4f4e\u6eab\u7269\u7406\u7684\u7814\u7a76\u3002\u6709\u8da3\u7684\u662f\uff0c\u96d6\u7136\u92a9\u6975\u5176\u7a00\u6709\uff0c\u4f46\u5176\u8207\u4eba\u9ad4\u9aa8\u9abc\u5177\u5099\u4e00\u5b9a\u7684\u89aa\u548c\u529b\uff0c\u56e0\u6b64\u5728\u751f\u91ab\u653e\u5c04\u6027\u8ffd\u8e64\u7814\u7a76\u4e2d\u4e5f\u6709\u5c11\u91cf\u5617\u8a66\u3002\u9019\u7a2e\u5f9e\u6975\u5317\u4e4b\u5730\u7684\u5e7d\u6697\u540d\u7a31\u5230\u5728\u87a2\u5149\u71c8\u7ba1\u8207\u8a3a\u65b7\u5100\u5668\u4e2d\u767c\u51fa\u7cbe\u78ba\u8f3b\u5c04\u7684\u8f49\u8b8a\uff0c\u7cbe\u78ba\u8a6e\u91cb\u4e86\u92a9\u5728\u9031\u671f\u8868\u4e2d\u4f5c\u70ba\u300c\u7a00\u6709\u529f\u80fd\u91d1\u5c6c\u300d\u7684\u51b7\u5cfb\u5730\u4f4d\u3002",
  "\x59\x62":
    "\u943f\x28\x59\x74\x74\x65\x72\x62\x69\x75\x6d\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x59\x62\uff0c\u539f\u5b50\u5e8f\x20\x37\x30\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u516d\u9031\u671f\u3001\u946d\u7cfb\u5143\u7d20\x28\x66\x20\u5340\u584a\x29\u3002\u5176\u540d\u7a31\u540c\u6a23\u6e90\u65bc\u745e\u5178\u5c0f\u93ae\u4f0a\u7279\u6bd4\u3002\x31\x38\x37\x38\x20\u5e74\u7531\u99ac\u91cc\u7d0d\u514b\x28\x4a\x65\x61\x6e\x20\x43\x68\x61\x72\x6c\x65\x73\x20\x64\x65\x20\x4d\x61\x72\x69\x67\x6e\x61\x63\x29\u5728\u5206\u6790\u927a\u571f\u6642\u5206\u96e2\u3002\u943f\u662f\u4e00\u7a2e\u9280\u767d\u8272\u7684\u8edf\u91d1\u5c6c\uff0c\u5177\u5099\u6975\u4f73\u7684\u97cc\u6027\u8207\u5ef6\u5c55\u6027\u3002\u8eab\u70ba\u946d\u7cfb\u5143\u7d20\u7684\u5012\u6578\u7b2c\u4e8c\u4f4d\uff0c\u943f\u5728\u96fb\u5b50\u7d44\u614b\u4e0a\u5c55\u73fe\u4e86\u6975\u9ad8\u7684\u7a69\u5b9a\u6027\uff0c\u4f7f\u5176\u6210\u70ba\u73fe\u4ee3\u8d85\u7cbe\u5bc6\u8a08\u6642\x28\u539f\u5b50\u9418\x29\u8207\u9ad8\u529f\u7387\u96f7\u5c04\u6280\u8853\u7684\u6838\u5fc3\u5143\u7d20\uff0c\u4ea6\u662f\u6750\u6599\u79d1\u5b78\u4e2d\u63a2\u7a76\u91d1\u5c6c\x2d\u975e\u91d1\u5c6c\u76f8\u8b8a\u7684\u7d55\u4f73\u6a23\u672c\u3002\x0a\x0a\u943f\u7684\u96fb\u5b50\u7d44\u614b\u70ba\x20\x5b\x58\x65\x5d\x34\x66\u00b9\u2074\x36\x73\u00b2\uff0c\u9019\u662f\u4e00\u500b\u6975\u5176\u95dc\u9375\u7684\u5316\u5b78\u7279\u5fb5\uff1a\u5176\x20\x34\x66\x20\u8ecc\u57df\u8655\u65bc\u5b8c\u5168\u586b\u6eff\x28\x46\x75\x6c\x6c\x20\x73\x68\x65\x6c\x6c\x29\u72c0\u614b\uff0c\u4f7f\u5176\u5728\u7269\u7406\u8207\u5316\u5b78\u884c\u70ba\u4e0a\u8207\u524d\u9762\u7684\u946d\u7cfb\u5143\u7d20\u5b58\u5728\u7d30\u5fae\u5dee\u7570\u3002\u943f\u5e38\u898b\u6c27\u5316\u614b\u70ba\x20\x2b\x33\uff0c\u4f46\x20\x2b\x32\x20\u6c27\u5316\u614b\x28\x59\x62\u00b2\u207a\x29\u4e5f\u76f8\u5c0d\u7a69\u5b9a\u4e14\u5177\u5099\u5f37\u9084\u539f\u6027\uff0c\u5e38\u4f5c\u70ba\u5316\u5b78\u5408\u6210\u4e2d\u7684\u9084\u539f\u8a66\u5291\u3002\u5728\u9ad8\u4e2d\u5316\u5b78\u63a2\u8a0e\u96fb\u5b50\u6392\u5e03\u7684\u7a69\u5b9a\u6027\u6642\uff0c\u943f\u662f\u8aaa\u660e\u300c\u5168\u6eff\u6bbc\u5c64\u300d\u80fd\u964d\u4f4e\u80fd\u91cf\u4e26\u5f71\u97ff\u539f\u5b50\u6027\u8cea\x28\u5982\u5bc6\u5ea6\u8207\u7194\u9ede\u8da8\u52e2\x29\u7684\u5b8c\u7f8e\u7bc4\u4f8b\u3002\u6b64\u5916\uff0c\u943f\u96e2\u5b50\u5728\u5149\u8b5c\u5b78\u4e2d\u5177\u5099\u7c21\u6f54\u7684\u80fd\u968e\u7d50\u69cb\uff0c\u4f7f\u5176\u5728\u5149\u5b78\u6fc0\u767c\u8207\u5438\u6536\u4e2d\u6548\u7387\u6975\u9ad8\u3002\x0a\x0a\u5728\u73fe\u4ee3\u7269\u7406\u61c9\u7528\u4e2d\uff0c\u943f\u539f\u5b50\u662f\u7cbe\u5bc6\u8a08\u6642\u9818\u57df\u7684\u660e\u661f\u3002\u76ee\u524d\u7684\u300c\u943f\u539f\u5b50\u5149\u6676\u683c\u9418\u300d\x28\x59\x62\x20\x6c\x61\x74\x74\x69\x63\x65\x20\x63\x6c\x6f\x63\x6b\x29\u5229\u7528\u943f\u539f\u5b50\u7684\u96fb\u5b50\u80fd\u7d1a\u8e8d\u9077\uff0c\u5176\u7a69\u5b9a\u5ea6\u5df2\u8d85\u8d8a\u50b3\u7d71\u92ab\u539f\u5b50\u9418\u6578\u500b\u6578\u91cf\u7d1a\uff0c\u6210\u70ba\u91cd\u65b0\u5b9a\u7fa9\u570b\u969b\u55ae\u4f4d\u5236\u300c\u79d2\u300d\u7684\u6700\u71b1\u9580\u5019\u9078\u8005\u3002\u5728\u5de5\u696d\u88fd\u9020\u65b9\u9762\uff0c\u647b\u943f\u7e96\u7dad\u96f7\u5c04\u5668\x28\x59\x62\x2d\x64\x6f\x70\x65\x64\x20\x66\x69\x62\x65\x72\x20\x6c\x61\x73\x65\x72\x29\u56e0\u5176\u5149\x2d\u5149\u8f49\u63db\u6548\u7387\u6975\u9ad8\u3001\u6563\u71b1\u6027\u597d\uff0c\u5df2\u6210\u70ba\u73fe\u4ee3\u91d1\u5c6c\u96f7\u5c04\u5207\u5272\u3001\u710a\u63a5\u8207\u7cbe\u5bc6\u6253\u6a19\u7684\u4e3b\u6d41\u8a2d\u5099\u3002\u6b64\u5916\uff0c\u5c07\u943f\u52a0\u5165\u4e0d\u93fd\u92fc\u4e2d\u80fd\u7d30\u5316\u6676\u7c92\uff0c\u5927\u5e45\u63d0\u5347\u6750\u6599\u5728\u9ad8\u6eab\u4e0b\u7684\u529b\u5b78\u5f37\u5ea6\u8207\u8010\u75b2\u52de\u6027\u80fd\u3002\x0a\x0a\u943f\u5728\u6975\u9650\u7269\u7406\u5be6\u9a57\u4e2d\u5c55\u73fe\u4e86\u9a5a\u4eba\u7684\u6027\u8cea\u3002\u5b83\u662f\u6975\u5c11\u6578\u5728\u6975\u9ad8\u58d3\u74b0\u5883\u4e0b\u6703\u5f9e\u534a\u5c0e\u9ad4\u72c0\u614b\u8f49\u5316\u70ba\u91d1\u5c6c\u72c0\u614b\u7684\u5143\u7d20\u4e4b\u4e00\uff0c\u4e14\u5176\u96fb\u963b\u7387\u96a8\u58d3\u529b\u8b8a\u5316\u7684\u898f\u5f8b\u88ab\u88fd\u6210\u58d3\u529b\u611f\u6e2c\u5668\uff0c\u7528\u65bc\u76e3\u6e2c\u7206\u70b8\u8207\u8d85\u9ad8\u58d3\u5be6\u9a57\u3002\u53cd\u76f4\u89ba\u7684\u662f\uff0c\u943f\u7684\u7269\u7406\u6027\u8cea\u5728\u946d\u7cfb\u4e2d\u5e38\u5448\u73fe\u300c\u7a81\u8b8a\u300d\uff0c\u4f8b\u5982\u5176\u7194\u9ede\x28\u7d04\x20\x38\x32\x34\x20\u00b0\x43\x29\u9060\u4f4e\u65bc\u76f8\u9130\u7684\u5143\u7d20\u3002\u9019\u7a2e\u5f9e\u5b8c\u5168\u586b\u6eff\u7684\x20\x34\x66\x20\u96fb\u5b50\u96f2\u5e36\u4f86\u7684\u5fae\u89c0\u7a69\u5b9a\u5230\u652f\u6490\u5948\u79d2\u7d1a\u96f7\u5c04\u52a0\u5de5\u8207\u767e\u5104\u5e74\u4e0d\u5dee\u4e00\u79d2\u7684\u539f\u5b50\u9418\uff0c\u7cbe\u78ba\u8a6e\u91cb\u4e86\u943f\u5728\u9031\u671f\u8868\u672b\u7aef\u4f5c\u70ba\u300c\u7a69\u5b9a\u8207\u7cbe\u78ba\u300d\u5316\u8eab\u7684\u5316\u5b78\u5167\u6db5\u3002",
  "\x4c\x75":
    "\u9465\x28\x4c\x75\x74\x65\x74\x69\x75\x6d\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x4c\x75\uff0c\u539f\u5b50\u5e8f\x20\x37\x31\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u516d\u9031\u671f\u3001\u7b2c\x20\x33\x20\u65cf\x28\x64\x20\u5340\u584a\uff0c\u6216\u8996\u70ba\u946d\u7cfb\u5143\u7d20\u7684\u7d42\u9ede\x29\u3002\u5176\u540d\u7a31\u6e90\u65bc\u5df4\u9ece\u7684\u62c9\u4e01\u8a9e\u540d\u7a31\u300c\x4c\x75\x74\x65\x74\x69\x61\u300d\u3002\x31\x39\x30\x37\x20\u5e74\u7531\u6cd5\u570b\u5316\u5b78\u5bb6\u4e8e\u723e\u73ed\x28\x47\x65\x6f\x72\x67\x65\x73\x20\x55\x72\x62\x61\x69\x6e\x29\u3001\u5967\u5730\u5229\u5316\u5b78\u5bb6\u97cb\u723e\u65af\u5df4\u8d6b\x28\x41\x75\x65\x72\x20\x76\x6f\x6e\x20\x57\x65\x6c\x73\x62\x61\x63\x68\x29\u8207\u7f8e\u570b\u5316\u5b78\u5bb6\u8a79\u59c6\u65af\x28\x43\x68\x61\x72\x6c\x65\x73\x20\x4a\x61\x6d\x65\x73\x29\u7368\u7acb\u767c\u73fe\u3002\u9465\u662f\u81ea\u7136\u754c\u4e2d\u5b58\u5728\u6700\u7a00\u6709\u4e14\u50f9\u683c\u6700\u6602\u8cb4\u7684\u7a00\u571f\u5143\u7d20\u4e4b\u4e00\u3002\u8eab\u70ba\u946d\u7cfb\u7cfb\u5217\u7684\u6700\u5f8c\u4e00\u500b\u6210\u54e1\uff0c\u9465\u5728\u7d50\u69cb\u4e0a\u5c55\u73fe\u4e86\u946d\u7cfb\u6536\u7e2e\u6548\u61c9\u7684\u6975\u81f4\uff0c\u662f\u7814\u7a76\u91cd\u7a00\u571f\u7269\u7406\u5316\u5b78\u898f\u5f8b\u7684\u91cd\u8981\u6a19\u7aff\u3002\x0a\x0a\u9465\u7684\u96fb\u5b50\u7d44\u614b\u70ba\x20\x5b\x58\x65\x5d\x34\x66\u00b9\u2074\x35\x64\u00b9\x36\x73\u00b2\uff0c\u5176\x20\x34\x66\x20\u8ecc\u57df\u5b8c\u5168\u586b\u6eff\uff0c\u9019\u4f7f\u5176\u5728\u5316\u5b78\u6027\u8cea\u4e0a\u66f4\u50cf\u662f\u4e00\u500b\u5178\u578b\u7684\u904e\u6e21\u91d1\u5c6c\uff0c\u800c\u975e\u5178\u578b\u7684\u7a00\u571f\u5143\u7d20\u3002\u9465\u5728\u5316\u5408\u7269\u4e2d\u7a69\u5b9a\u5448\u73fe\x20\x2b\x33\x20\u6c27\u5316\u614b\uff0c\u5176\u96e2\u5b50\u534a\u5f91\u662f\u6240\u6709\u946d\u7cfb\u5143\u7d20\u4e2d\u6700\u5c0f\u7684\uff0c\u9019\u5c0e\u81f4\u5176\u5177\u6709\u6975\u9ad8\u7684\u96fb\u8377\u5bc6\u5ea6\u8207\u8f03\u5f37\u7684\u914d\u4f4d\u80fd\u529b\u3002\u5728\u9ad8\u4e2d\u5316\u5b78\u63a2\u8a0e\u9031\u671f\u5f8b\u6642\uff0c\u9465\u5e38\u88ab\u7528\u4f86\u8aaa\u660e\u300c\u946d\u7cfb\u6536\u7e2e\u300d\x28\x4c\x61\x6e\x74\x68\x61\x6e\x69\x64\x65\x20\x43\x6f\x6e\x74\x72\x61\x63\x74\x69\x6f\x6e\x29\u5982\u4f55\u5c0e\u81f4\u7b2c\u516d\u9031\u671f\u904e\u6e21\u91d1\u5c6c\x28\u5982\u927f\u3001\u926d\x29\u7684\u539f\u5b50\u534a\u5f91\u5927\u5e45\u7e2e\u5c0f\uff0c\u9032\u800c\u5f71\u97ff\u6574\u500b\u5f8c\u7e8c\u9031\u671f\u7684\u7269\u7406\u6027\u8cea\u3002\u9465\u91d1\u5c6c\u5177\u5099\u9280\u767d\u8272\u5149\u6fa4\uff0c\u662f\u946d\u7cfb\u4e2d\u6700\u786c\u4e14\u5bc6\u5ea6\u6700\u9ad8\u7684\u6210\u54e1\u3002\x0a\x0a\u5728\u73fe\u4ee3\u61c9\u7528\u4e2d\uff0c\u9465\u5728\u7cbe\u5bc6\u91ab\u7642\u5f71\u50cf\u8207\u6838\u5b50\u91ab\u5b78\u4e2d\u5177\u6709\u58df\u65b7\u5730\u4f4d\u3002\u9465\u9178\u91d4\x28\x4c\x53\x4f\x29\u6676\u9ad4\u662f\u6b63\u5b50\u65b7\u5c64\u6383\u63cf\x28\x50\x45\x54\x29\u5075\u6e2c\u5668\u7684\u6838\u5fc3\u6750\u6599\uff0c\u5229\u7528\u5176\u512a\u7570\u7684\u9583\u720d\u6027\u80fd\u6355\u6349\u9ad8\u80fd\u5149\u5b50\u3002\u5728\u653e\u5c04\u6027\u6cbb\u7642\u65b9\u9762\uff0c\u540c\u4f4d\u7d20\x20\u9465\x2d\x31\x37\x37\x28\u00b9\u2077\u2077\x4c\x75\x29\u7d50\u5408\u6a19\u9776\u5206\u5b50\uff0c\u88ab\u5ee3\u6cdb\u7528\u65bc\u795e\u7d93\u5167\u5206\u6ccc\u816b\u7624\u8207\u524d\u5217\u817a\u764c\u7684\u7cbe\u6e96\u6cbb\u7642\x28\u6a19\u9776\u653e\u5c04\u6027\u6838\u7d20\u7642\u6cd5\x29\u3002\u6b64\u5916\uff0c\u9465\u5728\u77f3\u6cb9\u7cbe\u7149\u4e2d\u4f5c\u70ba\u9ad8\u6548\u80fd\u7684\u88c2\u5316\u50ac\u5316\u5291\uff0c\u4e26\u5728\u7279\u6b8a\u5408\u91d1\u4e2d\u7528\u65bc\u6539\u5584\u4e0d\u93fd\u92fc\u7684\u8010\u8150\u8755\u6027\u80fd\uff0c\u5c55\u73fe\u51fa\u5176\u5728\u6975\u7aef\u5de5\u85dd\u74b0\u5883\u4e0b\u7684\u7a69\u5b9a\u50f9\u503c\u3002\x0a\x0a\u9465\u5728\u7269\u7406\u7279\u6027\u4e0a\u5c55\u73fe\u4e86\u67d0\u4e9b\u300c\u6975\u9650\u7a69\u5b9a\u300d\u7684\u7279\u5fb5\u3002\u7531\u65bc\u5176\x20\x34\x66\x20\u6bbc\u5c64\u5168\u6eff\uff0c\u9465\u5316\u5408\u7269\u901a\u5e38\u5448\u73fe\u7121\u8272\u4e14\u4e0d\u5177\u5099\u9806\u78c1\u6027\x28\x44\x69\x61\x6d\x61\x67\x6e\x65\x74\x69\x63\x29\uff0c\u9019\u8207\u5176\u4ed6\u5177\u6709\u7e7d\u7d1b\u8272\u5f69\u8207\u5f37\u78c1\u6027\u7684\u7a00\u571f\u5143\u7d20\u5f62\u6210\u9bae\u660e\u5c0d\u6bd4\u3002\u6709\u8da3\u7684\u662f\uff0c\u96d6\u7136\u9465\u6975\u5176\u7a00\u6709\uff0c\u4f46\u5176\u539f\u5b50\u6838\u5c0d\u4e2d\u5b50\u7684\u5438\u6536\u622a\u9762\u9069\u4e2d\uff0c\u4f7f\u5176\u5728\u6838\u7269\u7406\u5be6\u9a57\u4e2d\u5e38\u88ab\u7528\u4f5c\u6d3b\u5316\u5075\u6e2c\u5668\u3002\u6b64\u5916\uff0c\u9465\u8207\u927f\u7684\u5316\u5b78\u898f\u5f8b\u76f8\u4f3c\uff0c\u4f7f\u5176\u6210\u70ba\u7814\u7a76\u6046\u661f\u8207\u9695\u77f3\u5e74\u9f61\x28\u9465\x2d\u927f\u5b9a\u5e74\u6cd5\x29\u7684\u91cd\u8981\u8a08\u6642\u5668\u3002\u9019\u7a2e\u5f9e\u5df4\u9ece\u4e4b\u540d\u5230\u5b9a\u7fa9\u91cd\u7a00\u571f\u7269\u7406\u908a\u754c\u7684\u8f49\u8b8a\uff0c\u7cbe\u78ba\u8a6e\u91cb\u4e86\u9465\u5728\u9031\u671f\u8868\u4e2d\u4f5c\u70ba\u929c\u63a5\u946d\u7cfb\u8207\u904e\u6e21\u91d1\u5c6c\u6a4b\u6a11\u7684\u7279\u6b8a\u8eab\u5206\u3002",
  "\x48\x66":
    "\u927f\x28\x48\x61\x66\x6e\x69\x75\x6d\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x48\x66\uff0c\u539f\u5b50\u5e8f\x20\x37\x32\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u516d\u9031\u671f\u3001\u7b2c\x20\x34\x20\u65cf\x28\x64\x20\u5340\u584a\x29\u3002\u5176\u540d\u7a31\u6e90\u65bc\u54e5\u672c\u54c8\u6839\u7684\u62c9\u4e01\u8a9e\u540d\u7a31\u300c\x48\x61\x66\x6e\x69\x61\u300d\u3002\x31\x38\x32\x33\x20\u5e74\u6ce2\u8033\x28\x4e\x69\x65\x6c\x73\x20\x42\x6f\x68\x72\x29\u6839\u64da\u539f\u5b50\u7d50\u69cb\u7406\u8ad6\u9810\u8a00\u5176\u61c9\u5b58\u5728\u65bc\u92ef\u7926\u4e2d\uff0c\u76f4\u5230\x20\x31\x39\x32\x33\x20\u5e74\u624d\u7531\u8377\u862d\u7269\u7406\u5b78\u5bb6\u79d1\u65af\u7279\x28\x44\x69\x72\x6b\x20\x43\x6f\x73\x74\x65\x72\x29\u8207\u5308\u7259\u5229\u5316\u5b78\u5bb6\u4f55\u97cb\u897f\x28\x47\x65\x6f\x72\x67\x65\x20\x64\x65\x20\x48\x65\x76\x65\x73\x79\x29\u900f\u904e\x20\x58\x20\u5c04\u7dda\u5149\u8b5c\u5206\u6790\u8b49\u5be6\u3002\u927f\u662f\u5178\u578b\u7684\u9ad8\u7194\u9ede\u3001\u9ad8\u5bc6\u5ea6\u7684\u904e\u6e21\u91d1\u5c6c\uff0c\u8207\u540c\u65cf\u7684\u92ef\x28\x5a\x72\x29\u6027\u8cea\u6975\u5176\u76f8\u4f3c\uff0c\u5169\u8005\u5728\u81ea\u7136\u754c\u4e2d\u59cb\u7d42\u5171\u751f\uff0c\u9019\u4f7f\u5f97\u927f\u7684\u63d0\u7d14\u6280\u8853\u6210\u70ba\u6750\u6599\u79d1\u5b78\u53f2\u4e0a\u6975\u5177\u6311\u6230\u6027\u7684\u8ab2\u984c\u3002\x0a\x0a\u927f\u7684\u96fb\u5b50\u7d44\u614b\u70ba\x20\x5b\x58\x65\x5d\x34\x66\u00b9\u2074\x35\x64\u00b2\x36\x73\u00b2\uff0c\u6700\u7a69\u5b9a\u7684\u6c27\u5316\u614b\u70ba\x20\x2b\x34\u3002\u7531\u65bc\u300c\u946d\u7cfb\u6536\u7e2e\u300d\u6548\u61c9\uff0c\u927f\u7684\u539f\u5b50\u534a\u5f91\u8207\u7b2c\u4e94\u9031\u671f\u7684\u92ef\u5e7e\u4e4e\u5b8c\u5168\u76f8\u540c\uff0c\u5c0e\u81f4\u5169\u8005\u7684\u5316\u5b78\u884c\u70ba\u5982\u96d9\u80de\u80ce\u822c\u96e3\u4ee5\u5340\u5206\u3002\u5728\u9ad8\u4e2d\u5316\u5b78\u8a0e\u8ad6\u5143\u7d20\u6027\u8cea\u898f\u5f8b\u6642\uff0c\u927f\u662f\u8aaa\u660e\u300c\u9031\u671f\u8da8\u52e2\u53d7\u5167\u5c64\x20\x66\x20\u96fb\u5b50\u5c4f\u853d\u5f71\u97ff\u300d\u6700\u5b8c\u7f8e\u7684\u6848\u4f8b\u3002\u927f\u5177\u5099\u5353\u8d8a\u7684\u6297\u8150\u8755\u6027\u80fd\uff0c\u5728\u5e38\u6eab\u4e0b\u8868\u9762\u6703\u8fc5\u901f\u5f62\u6210\u7dfb\u5bc6\u4e14\u5f37\u97cc\u7684\u6c27\u5316\u819c\uff0c\u80fd\u62b5\u79a6\u5e7e\u4e4e\u6240\u6709\u5f37\u9e7c\u8207\u9664\u6c2b\u6c1f\u9178\x28\x48\x46\x29\u5916\u7684\u591a\u6578\u5f37\u9178\u4fb5\u8755\uff0c\u5c55\u73fe\u51fa\u6975\u9ad8\u7684\u5316\u5b78\u7a69\u5b9a\u6027\u3002\x0a\x0a\u5728\u73fe\u4ee3\u9ad8\u79d1\u6280\u7522\u696d\u4e2d\uff0c\u927f\u662f\u63a8\u52d5\u534a\u5c0e\u9ad4\u6548\u80fd\u8de8\u8d8a\u6975\u9650\u7684\u95dc\u9375\u3002\u81ea\x20\x34\x35\x20\u5948\u7c73\u88fd\u7a0b\u8d77\uff0c\u4e8c\u6c27\u5316\u927f\x28\x48\x66\x4f\u2082\x29\u53d6\u4ee3\u4e86\u50b3\u7d71\u7684\u4e8c\u6c27\u5316\u77fd\uff0c\u6210\u70ba\u96fb\u6676\u9ad4\u4e2d\u7684\u300c\u9ad8\u4ecb\u96fb\u5e38\u6578\u300d\x28\x48\x69\x67\x68\x2d\x6b\x29\u9598\u6975\u7d55\u7de3\u5c64\uff0c\u6709\u6548\u89e3\u6c7a\u4e86\u5143\u4ef6\u5fae\u7e2e\u5316\u5f8c\u7684\u6f0f\u96fb\u554f\u984c\u3002\u5728\u6838\u80fd\u5de5\u7a0b\u4e2d\uff0c\u927f\u5c55\u73fe\u4e86\u8207\u92ef\u5b8c\u5168\u76f8\u53cd\u7684\u7269\u7406\u7279\u6027\uff1a\u5b83\u5177\u6709\u6975\u9ad8\u7684\u71b1\u4e2d\u5b50\u5438\u6536\u622a\u9762\x28\u70ba\u92ef\u7684\x20\x36\x30\x30\x20\u500d\u4ee5\u4e0a\x29\uff0c\u56e0\u6b64\u88ab\u5ee3\u6cdb\u88fd\u6210\u6838\u53cd\u61c9\u7210\u7684\u63a7\u5236\u68d2\uff0c\u7528\u65bc\u7cbe\u5bc6\u8abf\u7bc0\u6838\u5206\u88c2\u901f\u7387\uff0c\u662f\u78ba\u4fdd\u6838\u5b50\u52d5\u529b\u8239\u8266\u8207\u6838\u96fb\u5ee0\u5b89\u5168\u7684\u6838\u5fc3\u6750\u6599\u3002\x0a\x0a\u927f\u5728\u6750\u6599\u79d1\u5b78\u4e2d\u5c55\u73fe\u51fa\u4ee4\u4eba\u9a5a\u5606\u7684\u300c\u8010\u706b\u300d\u6975\u9650\u3002\u927f\u8207\u78b3\u5f62\u6210\u7684\u78b3\u5316\u927f\x28\x48\x66\x43\x29\u7194\u9ede\u8d85\u904e\x20\x33\x38\x39\x30\x20\u00b0\x43\uff0c\u662f\u76ee\u524d\u5df2\u77e5\u7194\u9ede\u6700\u9ad8\u7684\u4e8c\u5143\u5316\u5408\u7269\u4e4b\u4e00\u3002\u6709\u8da3\u7684\u662f\uff0c\u96d6\u7136\u927f\u5728\u5de5\u7a0b\u4e2d\u88ab\u8996\u70ba\u92ef\u7684\u4f34\u751f\u7269\uff0c\u4f46\u53ea\u9700\u6df7\u5165\u6975\u5fae\u91cf\u7684\u927f\uff0c\u5c31\u80fd\u986f\u8457\u63d0\u9ad8\u93b3\u57fa\u8d85\u5408\u91d1\u5728\u5674\u5c04\u767c\u52d5\u6a5f\u9ad8\u6eab\u74b0\u5883\u4e0b\u7684\u6676\u754c\u5f37\u5ea6\u3002\u6b64\u5916\uff0c\u927f\u5728\u967d\u6975\u6c27\u5316\u904e\u7a0b\u4e2d\u6703\u5c55\u73fe\u51fa\u8ff7\u96e2\u7684\u5149\u5b78\u5e72\u6d89\u8272\u5f69\u3002\u9019\u7a2e\u5f9e\u652f\u63f4\u73fe\u4ee3\x20\x43\x50\x55\x20\u9ad8\u901f\u904b\u7b97\u5230\u5b88\u8b77\u6838\u53cd\u61c9\u7210\u6838\u5fc3\u7684\u96d9\u91cd\u89d2\u8272\uff0c\u7cbe\u78ba\u8a6e\u91cb\u4e86\u927f\u4f5c\u70ba\u7b2c\u516d\u9031\u671f\u904e\u6e21\u5143\u7d20\u5728\u7cbe\u5bc6\u8207\u6975\u7aef\u689d\u4ef6\u4e0b\u7684\u7368\u7279\u50f9\u503c\u3002",
  "\x54\x61":
    "\u926d\x28\x54\x61\x6e\x74\x61\x6c\x75\x6d\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x54\x61\uff0c\u539f\u5b50\u5e8f\x20\x37\x33\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u516d\u9031\u671f\u3001\u7b2c\x20\x35\x20\u65cf\x28\x64\x20\u5340\u584a\x29\u3002\u5176\u540d\u7a31\u6e90\u65bc\u5e0c\u81d8\u795e\u8a71\u4e2d\u53d7\u6c38\u6046\u98e2\u6e34\u4e4b\u82e6\u7684\u570b\u738b\u5766\u5854\u6d1b\u65af\x28\x54\x61\x6e\x74\x61\x6c\x75\x73\x29\uff0c\u610f\u6307\u5176\u6c27\u5316\u7269\u5728\u5f37\u9178\u4e2d\u300c\u6ef4\u6c34\u4e0d\u9032\u300d\u7684\u5f37\u5927\u60f0\u6027\u3002\x31\x38\x30\x32\x20\u5e74\u7531\u745e\u5178\u5316\u5b78\u5bb6\u57c3\u514b\u8c9d\u91cc\x28\x41\x6e\x64\x65\x72\x73\x20\x45\x6b\x65\x62\x65\x72\x67\x29\u767c\u73fe\u3002\u926d\u662f\u4e00\u7a2e\u5e36\u6709\u85cd\u7070\u8272\u5149\u6fa4\u3001\u9ad8\u5bc6\u5ea6\u4e14\u6975\u9ad8\u7194\u9ede\x28\u7d04\x20\x33\x30\x31\x37\x20\u00b0\x43\x29\u7684\u7a00\u6709\u904e\u6e21\u91d1\u5c6c\u3002\u5b83\u4ee5\u5353\u8d8a\u7684\u5316\u5b78\u7a69\u5b9a\u6027\u3001\u9ad8\u4ecb\u96fb\u5f37\u5ea6\u8207\u512a\u7570\u7684\u751f\u7269\u76f8\u5bb9\u6027\uff0c\u5728\u901a\u8a0a\u96fb\u5b50\u3001\u822a\u592a\u5de5\u696d\u8207\u5fae\u5275\u91ab\u7642\u4e2d\u626e\u6f14\u8457\u4e0d\u53ef\u53d6\u4ee3\u7684\u89d2\u8272\u3002\x0a\x0a\u5728\u5316\u5b78\u6027\u8cea\u4e0a\uff0c\u926d\u7684\u96fb\u5b50\u7d44\u614b\u70ba\x20\x5b\x58\x65\x5d\x34\x66\u00b9\u2074\x35\x64\u00b3\x36\x73\u00b2\uff0c\u7a69\u5b9a\u6c27\u5316\u614b\u70ba\x20\x2b\x35\u3002\u926d\u7684\u5316\u5b78\u60f0\u6027\u6975\u9ad8\uff0c\u5728\x20\x31\x35\x30\x20\u00b0\x43\x20\u4ee5\u4e0b\u5e7e\u4e4e\u4e0d\u8207\u4efb\u4f55\u5f37\u9178\u53cd\u61c9\uff0c\u751a\u81f3\u9023\u5f37\u5927\u6c27\u5316\u529b\u7684\u738b\u6c34\u4e5f\u7121\u6cd5\u4fb5\u8755\u5176\u8868\u9762\u3002\u5728\u9ad8\u4e2d\u5316\u5b78\u63a2\u8a0e\u6c27\u5316\u7269\u8584\u819c\u8207\u920d\u5316\u73fe\u8c61\u6642\uff0c\u926d\u662f\u5177\u5099\u9ad8\u5ea6\u4ee3\u8868\u6027\u7684\u5be6\u4f8b\uff1a\u5176\u8868\u9762\u751f\u6210\u7684\u4e94\u6c27\u5316\u4e8c\u926d\x28\x54\x61\u2082\x4f\u2085\x29\u5c64\u6975\u5176\u7dfb\u5bc6\u4e14\u5177\u5099\u6975\u9ad8\u7684\u7d55\u7de3\u6027\u80fd\u8207\u4ecb\u96fb\u5e38\u6578\u3002\u9019\u7a2e\u7269\u7406\u7279\u6027\u4f7f\u5f97\u926d\u80fd\u900f\u904e\u967d\u6975\u8655\u7406\u6280\u8853\uff0c\u5728\u6975\u5c0f\u7684\u9ad4\u7a4d\u5167\u5132\u5b58\u5927\u91cf\u96fb\u8377\uff0c\u6210\u70ba\u96fb\u8def\u8a2d\u8a08\u4e2d\u7a69\u5b9a\u96fb\u6d41\u7684\u95dc\u9375\u90e8\u4ef6\u3002\x0a\x0a\u5728\u53f0\u7063\u9ad8\u4e2d\u8ab2\u7db1\u8207\u96fb\u5b50\u7522\u696d\u8108\u7d61\u4e2d\uff0c\u926d\u96fb\u5bb9\u5668\x28\x54\x61\x6e\x74\x61\x6c\x75\x6d\x20\x63\x61\x70\x61\x63\x69\x74\x6f\x72\x29\u662f\u9ad8\u6027\u80fd\u96fb\u5b50\u8a2d\u5099\x28\u5982\u667a\u6167\u578b\u624b\u6a5f\u3001\u4f3a\u670d\u5668\x29\u7684\u5fc3\u81df\uff0c\u5177\u5099\u9577\u58fd\u547d\u3001\u8010\u9ad8\u6eab\u8207\u6975\u4f73\u7684\u8a0a\u865f\u7a69\u5b9a\u5ea6\u3002\u5728\u91ab\u7642\u6750\u6599\u79d1\u5b78\u4e2d\uff0c\u7531\u65bc\u926d\u5c0d\u4eba\u9ad4\u9ad4\u6db2\u5b8c\u5168\u5448\u5316\u5b78\u60f0\u6027\uff0c\u4e14\u80fd\u8207\u9aa8\u9abc\u7d44\u7e54\u7dca\u5bc6\u7d50\u5408\uff0c\u56e0\u6b64\u88ab\u5ee3\u6cdb\u7528\u65bc\u88fd\u9020\u4eba\u5de5\u9aa8\u9abc\u3001\u9871\u9aa8\u4fee\u88dc\u7247\u3001\u8840\u7ba1\u652f\u67b6\u4ee5\u53ca\u7e2b\u5408\u91dd\u3002\u6b64\u5916\uff0c\u926d\u5728\u5316\u5b78\u5de5\u696d\u4e2d\u88ab\u88fd\u6210\u5404\u7a2e\u6297\u8150\u8755\u53cd\u61c9\u69fd\u8207\u71b1\u4ea4\u63db\u5668\uff0c\u5176\u8010\u7528\u5e74\u9650\u9060\u8d85\u666e\u901a\u4e0d\u93fd\u92fc\u6216\u9226\u6750\u3002\x0a\x0a\u926d\u5c55\u73fe\u4e86\u67d0\u4e9b\u53cd\u76f4\u89ba\u7684\u7269\u7406\u8207\u6a5f\u68b0\u7279\u5fb5\u3002\u96d6\u7136\u5b83\u5177\u5099\u6975\u9ad8\u7684\u786c\u5ea6\u8207\u5f37\u5ea6\uff0c\u4f46\u926d\u540c\u6642\u64c1\u6709\u6975\u4f73\u7684\u5ef6\u5c55\u6027\uff0c\u53ef\u4ee5\u88ab\u62bd\u6210\u6bd4\u982d\u9aee\u9084\u7d30\u7684\u7d30\u7d72\u800c\u4e0d\u65b7\u88c2\u3002\u6709\u8da3\u7684\u662f\uff0c\u5118\u7ba1\u926d\u7684\u5316\u5b78\u6027\u8cea\u6975\u5176\u60f0\u6027\uff0c\u4f46\u7576\u6eab\u5ea6\u5347\u81f3\x20\x31\x35\x30\x20\u00b0\x43\x20\u4ee5\u4e0a\u6642\uff0c\u5b83\u6703\u8207\u6c1f\u6c23\u6216\u6c1f\u5316\u6c2b\u767c\u751f\u5287\u70c8\u53cd\u61c9\uff0c\u5c55\u73fe\u4e86\u9e75\u7d20\u5c0d\u9ad8\u50f9\u614b\u91d1\u5c6c\u7684\u5f37\u5927\u8a98\u5c0e\u529b\u3002\u6b64\u5916\uff0c\u926d\u5728\u6975\u4f4e\u6eab\u4e0b\u6703\u8868\u73fe\u51fa\u8d85\u5c0e\u7279\u6027\u3002\u9019\u7a2e\u5f9e\u795e\u8a71\u4e2d\u6c38\u6046\u7684\u6e34\u671b\u5230\u73fe\u4ee3\u96fb\u5b50\u901a\u8a0a\u8207\u751f\u547d\u91ab\u7642\u7684\u652f\u6490\u8005\uff0c\u7cbe\u78ba\u8a6e\u91cb\u4e86\u926d\u5728\u9031\u671f\u8868\u4e2d\u6240\u5c55\u73fe\u7684\u5805\u97cc\u8207\u7d30\u81a9\u3002",
  "\x57":
    "\u93a2\x28\x54\x75\x6e\x67\x73\x74\x65\x6e\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x57\uff0c\u539f\u5b50\u5e8f\x20\x37\x34\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u516d\u9031\u671f\u3001\u7b2c\x20\x36\x20\u65cf\x28\x64\x20\u5340\u584a\x29\u3002\u5176\u540d\u7a31\u6e90\u65bc\u745e\u5178\u8a9e\u300c\x74\x75\x6e\x67\x20\x73\x74\x65\x6e\u300d\uff0c\u610f\u70ba\u300c\u6c89\u91cd\u7684\u77f3\u982d\u300d\uff1b\u7b26\u865f\x20\x57\x20\u5247\u4f86\u81ea\u5fb7\u8a9e\u540d\u7a31\u300c\x57\x6f\x6c\x66\x72\x61\x6d\u300d\uff0c\u8a9e\u6e90\u6307\u5176\u65e9\u671f\u7926\u77f3\u6703\u50cf\u300c\u72fc\u4e00\u822c\u541e\u566c\u300d\u932b\u7926\u3002\x31\x37\x38\x33\x20\u5e74\u7531\u897f\u73ed\u7259\u5316\u5b78\u5bb6\u5fb7\u57c3\u76e7\u4e9e\u723e\u5144\u5f1f\x28\x45\x6c\x68\x75\x79\x61\x72\x20\x62\x72\x6f\x74\x68\x65\x72\x73\x29\u5206\u96e2\u51fa\u7d14\u91d1\u5c6c\u3002\u93a2\u662f\u6240\u6709\u91d1\u5c6c\u4e2d\u7194\u9ede\u6700\u9ad8\x28\x33\x34\x32\x32\x20\u00b0\x43\x29\u3001\u6cb8\u9ede\u6700\u9ad8\u4e14\u6297\u62c9\u5f37\u5ea6\u6975\u9ad8\u7684\u6210\u54e1\u3002\u5b83\u4ee5\u5176\u9a5a\u4eba\u7684\u8010\u71b1\u6027\u8207\u9ad8\u5bc6\u5ea6\uff0c\u6210\u70ba\u5de5\u696d\u5207\u5272\u3001\u822a\u592a\u79d1\u6280\u8207\u570b\u9632\u5de5\u7a0b\u4e2d\u5b9a\u7fa9\u786c\u5ea6\u8207\u5f37\u5ea6\u7684\u6838\u5fc3\u6307\u6a19\u3002\x0a\x0a\u93a2\u7684\u96fb\u5b50\u7d44\u614b\u70ba\x20\x5b\x58\x65\x5d\x34\x66\u00b9\u2074\x35\x64\u2074\x36\x73\u00b2\uff0c\u5176\u96fb\u5b50\u5206\u5e03\u6709\u5229\u65bc\u5f62\u6210\u6975\u5f37\u7684\u91d1\u5c6c\u9375\uff0c\u9019\u6b63\u662f\u5176\u9ad8\u7194\u9ede\u8207\u4f4e\u81a8\u8139\u4fc2\u6578\u7684\u5fae\u89c0\u6210\u56e0\u3002\u93a2\u7684\u6c27\u5316\u614b\u5206\u5e03\u7531\x20\x2d\x32\x20\u5230\x20\x2b\x36\uff0c\u5176\u4e2d\x20\x2b\x36\x20\u50f9\u6700\u70ba\u5e38\u898b\u3002\u5728\u9ad8\u4e2d\u5316\u5b78\u63a2\u8a0e\u56fa\u9ad4\u7d50\u69cb\u8207\u6027\u8cea\u6642\uff0c\u93a2\u662f\u7406\u89e3\u300c\u904e\u6e21\u91d1\u5c6c\u4e2d\u9375\u7d50\u5f37\u5ea6\u8207\u7194\u9ede\u8da8\u52e2\u300d\u7684\u6975\u81f4\u7bc4\u4f8b\uff1a\u96a8\u8457\x20\x64\x20\u8ecc\u57df\u672a\u6210\u5c0d\u96fb\u5b50\u6578\u589e\u52a0\uff0c\u91d1\u5c6c\u9375\u5f37\u5ea6\u5728\u7b2c\x20\x36\x20\u65cf\u9644\u8fd1\u9054\u5230\u5dd4\u5cf0\u3002\u6b64\u5916\uff0c\u93a2\u5177\u5099\u6975\u9ad8\u7684\u96fb\u5b50\u5bc6\u5ea6\u8207\u539f\u5b50\u534a\u5f91\u7684\u5fae\u5999\u5e73\u8861\uff0c\u4f7f\u5176\u5728\u96fb\u5b50\u767c\u5c04\u9818\u57df\u5177\u6709\u512a\u7570\u7684\u7269\u7406\u7a69\u5b9a\u6027\u3002\x0a\x0a\u5728\u53f0\u7063\u9ad8\u4e2d\u8ab2\u7db1\u8207\u5de5\u696d\u61c9\u7528\u4e2d\uff0c\u78b3\u5316\u93a2\x28\x57\x43\x29\u662f\u6700\u91cd\u8981\u7684\u5316\u5b78\u89c0\u5ff5\u4e4b\u4e00\u3002\u78b3\u5316\u93a2\u7684\u786c\u5ea6\u63a5\u8fd1\u947d\u77f3\uff0c\u88ab\u5ee3\u6cdb\u7528\u65bc\u88fd\u9020\u5207\u524a\u5de5\u5177\u3001\u947d\u982d\u53ca\u8010\u78e8\u96f6\u4ef6\u3002\u5728\u7167\u660e\u53f2\u4e0a\uff0c\u93a2\u7d72\u71c8\u6ce1\u627f\u8f09\u4e86\u767e\u5e74\u7684\u6587\u660e\u9032\u6b65\uff0c\u5229\u7528\u5176\u9ad8\u96fb\u963b\u8207\u6975\u9ad8\u7194\u9ede\u767c\u51fa\u767d\u71be\u5149\u800c\u4e0d\u7194\u6bc0\u3002\u5728\u73fe\u4ee3\u534a\u5c0e\u9ad4\u88fd\u7a0b\u4e2d\uff0c\u93a2\u88ab\u7528\u65bc\u88fd\u9020\u7a4d\u9ad4\u96fb\u8def\u4e2d\u7684\u300c\u93a2\u585e\u300d\x28\x57\x2d\x70\x6c\x75\x67\x29\uff0c\u4f5c\u70ba\u5c64\u9593\u9023\u7dda\u7684\u5c0e\u96fb\u901a\u8def\u3002\u5728\u570b\u9632\u6280\u8853\u4e0a\uff0c\u7531\u65bc\u93a2\u7684\u5bc6\u5ea6\x28\u7d04\x20\x31\x39\x2e\x33\x20\x67\x2f\x63\x6d\u00b3\x29\u8207\u9ec3\u91d1\u76f8\u4eff\uff0c\u5176\u88fd\u6210\u7684\u52d5\u80fd\u7a7f\u7532\u5f48\u5177\u5099\u5f37\u5927\u7684\u8cab\u7a7f\u529b\uff0c\u662f\u6230\u8eca\u9632\u8b77\u9ad4\u7cfb\u7684\u524b\u661f\u3002\x0a\x0a\u93a2\u5c55\u73fe\u4e86\u8a31\u591a\u6975\u7aef\u7684\u7269\u7406\u884c\u70ba\u3002\u5b83\u662f\u6240\u6709\u91d1\u5c6c\u4e2d\u71b1\u81a8\u8139\u4fc2\u6578\u6700\u4f4e\u7684\u6210\u54e1\u4e4b\u4e00\uff0c\u9019\u4f7f\u5176\u5728\u6eab\u5ea6\u5287\u70c8\u8b8a\u52d5\u7684\u74b0\u5883\x28\u5982\u6838\u878d\u5408\u5be6\u9a57\u88dd\u7f6e\u7684\u7b2c\u4e00\u58c1\u6216\u592a\u7a7a\u8239\u91cd\u8fd4\u5927\u6c23\u5c64\u7684\u9694\u71b1\u5c64\x29\u4e2d\u80fd\u4fdd\u6301\u6975\u4f73\u7684\u5c3a\u5bf8\u7cbe\u5ea6\u3002\u53cd\u76f4\u89ba\u7684\u662f\uff0c\u96d6\u7136\u93a2\u6975\u5176\u5805\u786c\uff0c\u4f46\u5c07\u5176\u62c9\u6210\u7d30\u7d72\u5f8c\u537b\u5177\u5099\u6975\u4f73\u7684\u67d4\u97cc\u6027\u3002\u6b64\u5916\uff0c\u4e09\u6c27\u5316\u93a2\x28\x57\x4f\u2083\x29\u5c55\u73fe\u4e86\u986f\u8457\u7684\u300c\u96fb\u81f4\u8b8a\u8272\u300d\u6548\u61c9\uff0c\u53ef\u61c9\u7528\u65bc\u667a\u80fd\u7bc0\u80fd\u7a97\u3002\u9019\u7a2e\u5f9e\u50b3\u7d71\u93a2\u7d72\u71c8\u7684\u5fae\u5149\u5230\u652f\u6490\u6975\u7aef\u9ad8\u6eab\u5207\u5272\u8207\u534a\u5c0e\u9ad4\u5948\u7c73\u9023\u7dda\u7684\u8de8\u5ea6\uff0c\u7cbe\u78ba\u8a6e\u91cb\u4e86\u93a2\u5728\u9031\u671f\u8868\u4e2d\u4f5c\u70ba\u300c\u5f37\u5ea6\u5dd4\u5cf0\u300d\u7684\u9738\u4e3b\u5730\u4f4d\u3002",
  "\x52\x65":
    "\u9338\x28\x52\x68\x65\x6e\x69\x75\x6d\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x52\x65\uff0c\u539f\u5b50\u5e8f\x20\x37\x35\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u516d\u9031\u671f\u3001\u7b2c\x20\x37\x20\u65cf\x28\x64\x20\u5340\u584a\x29\u3002\u5176\u540d\u7a31\u6e90\u65bc\u5fb7\u570b\u840a\u8335\u6cb3\u7684\u62c9\u4e01\u8a9e\u540d\u7a31\u300c\x52\x68\x65\x6e\x75\x73\u300d\u3002\x31\x38\x32\x35\x20\u5e74\u7531\u5fb7\u570b\u5316\u5b78\u5bb6\u8afe\u9054\u514b\x28\x57\x61\x6c\x74\x65\x72\x20\x4e\x6f\x64\x64\x61\x63\x6b\x29\u592b\u5a66\u8207\u5854\u514b\x28\x4f\x74\x74\x6f\x20\x42\x65\x72\x67\x29\u5171\u540c\u767c\u73fe\uff0c\u662f\u81ea\u7136\u754c\u4e2d\u6700\u5f8c\u4e00\u500b\u88ab\u767c\u73fe\u7684\u7a69\u5b9a\u5143\u7d20\u3002\u9338\u6975\u7aef\u7a00\u6709\u4e14\u9ad8\u5ea6\u5206\u6563\uff0c\u901a\u5e38\u4f34\u751f\u65bc\u926c\u7926\u4e2d\u3002\u5b83\u4ee5\u6975\u9ad8\u7684\u7194\u9ede\x28\u7d04\x20\x33\x31\x38\x30\x20\u00b0\x43\uff0c\u91d1\u5c6c\u4e2d\u50c5\u6b21\u65bc\u93a2\x29\u8207\u5353\u8d8a\u7684\u6297\u8815\u8b8a\u5f37\u5ea6\uff0c\u6210\u70ba\u73fe\u4ee3\u822a\u592a\u8207\u9ad8\u6eab\u5de5\u696d\u7684\u6230\u7565\u652f\u67f1\u3002\x0a\x0a\u5728\u5316\u5b78\u884c\u70ba\u4e0a\uff0c\u9338\u7684\u96fb\u5b50\u7d44\u614b\u70ba\x20\x5b\x58\x65\x5d\x34\x66\u00b9\u2074\x35\x64\u2075\x36\x73\u00b2\uff0c\u5177\u5099\u5f9e\x20\x2d\x31\x20\u5230\x20\x2b\x37\x20\u7684\u6975\u5bec\u5ee3\u6c27\u5316\u614b\u3002\u9338\u5728\u5316\u5408\u7269\u4e2d\u5e38\u5c55\u73fe\u51fa\u5f37\u5927\u7684\u6210\u9375\u80fd\u529b\uff0c\u7279\u5225\u662f\u5728\u9ad8\u4e2d\u5316\u5b78\u8a0e\u8ad6\u904e\u6e21\u91d1\u5c6c\u932f\u5408\u7269\u8207\u7279\u6b8a\u5316\u5b78\u9375\u6642\uff0c\u9338\u9e7d\u96e2\u5b50\x20\x5b\x52\x65\u2082\x43\x6c\u2088\x5d\u00b2\u207b\x20\u56e0\u5176\u5177\u5099\u986f\u8457\u7684\u300c\u56db\u91cd\u9375\u300d\x28\x51\x75\x61\x64\x72\x75\x70\x6c\x65\x20\x62\x6f\x6e\x64\x29\u7d50\u69cb\uff0c\u6210\u70ba\u7814\u7a76\u91d1\u5c6c\uff0d\u91d1\u5c6c\u9375\u7406\u8ad6\u7684\u7d93\u5178\u6848\u4f8b\u3002\u9338\u7684\u96fb\u8ca0\u5ea6\u7d04\u70ba\x20\x31\x2e\x39\uff0c\u5176\u6c27\u5316\u7269\x28\u5982\x20\x52\x65\u2082\x4f\u2087\x29\u5177\u6709\u63ee\u767c\u6027\u4e14\u5c55\u73fe\u51fa\u9178\u6027\u7279\u5fb5\uff0c\u53cd\u6620\u4e86\u9ad8\u6c27\u5316\u614b\u904e\u6e21\u5143\u7d20\u7684\u975e\u91d1\u5c6c\u6027\u8cea\u898f\u5f8b\u3002\x0a\x0a\u5728\u73fe\u4ee3\u79d1\u6280\u8207\u6750\u6599\u79d1\u5b78\u9818\u57df\uff0c\u9338\u7684\u4e3b\u8981\u50f9\u503c\u9ad4\u73fe\u5728\u9ad8\u6027\u80fd\u300c\u9338\u57fa\u8d85\u5408\u91d1\u300d\u4e2d\u3002\u5c07\u5fae\u91cf\u9338\x28\u7d04\x20\x33\x25\u2013\x36\x25\x29\u52a0\u5165\u93b3\u57fa\u5408\u91d1\uff0c\u80fd\u6975\u5927\u5730\u63d0\u5347\u5f15\u64ce\u8449\u7247\u5728\u9ad8\u6eab\u3001\u9ad8\u58d3\u8207\u5287\u70c8\u96e2\u5fc3\u529b\u4e0b\u7684\u7d50\u69cb\u7a69\u5b9a\u6027\uff0c\u9019\u662f\u5674\u5c04\u767c\u52d5\u6a5f\u8207\u71c3\u6c23\u6e26\u8f2a\u6a5f\u80fd\u5920\u9ad8\u6548\u904b\u884c\u7684\u95dc\u9375\u3002\u5728\u5316\u5b78\u5de5\u696d\u4e2d\uff0c\u9338\uff0d\u9251\u50ac\u5316\u5291\u88ab\u5ee3\u6cdb\u7528\u65bc\u77f3\u6cb9\u91cd\u7d44\uff0c\u80fd\u9ad8\u6548\u751f\u7522\u7121\u925b\u3001\u9ad8\u8f9b\u70f7\u503c\u7684\u6c7d\u6cb9\uff0c\u5c55\u73fe\u4e86\u9338\u5728\u63d0\u5347\u5316\u5b78\u53cd\u61c9\u9078\u64c7\u6027\u4e0a\u7684\u5353\u8d8a\u5929\u8ce6\u3002\u6b64\u5916\uff0c\u9338\u8207\u93a2\u5f62\u6210\u7684\u5408\u91d1\u5e38\u88ab\u88fd\u6210\u7cbe\u5bc6\u71b1\u96fb\u5076\uff0c\u7528\u65bc\u6e2c\u91cf\u8d85\u904e\x20\x32\x30\x30\x30\x20\u00b0\x43\x20\u7684\u6975\u7aef\u9ad8\u6eab\u3002\x0a\x0a\u9338\u5c55\u73fe\u4e86\u67d0\u4e9b\u53cd\u76f4\u89ba\u7684\u7269\u7406\u6027\u8cea\u3002\u96d6\u7136\u9338\u6975\u5176\u8010\u706b\u4e14\u5805\u786c\uff0c\u4f46\u5176\u5ef6\u5c55\u6027\u8207\u710a\u63a5\u6027\u80fd\u537b\u512a\u65bc\u93a2\u6216\u926c\u3002\u9338\u5728\u9ad8\u6eab\u4e0b\u4e0d\u6703\u50cf\u5176\u4ed6\u96e3\u7194\u91d1\u5c6c\u90a3\u6a23\u767c\u751f\u518d\u7d50\u6676\u8106\u5316\uff0c\u9019\u4f7f\u5176\u5728\u96fb\u5b50\u7ba1\u8207\u822a\u592a\u63a8\u529b\u5668\u7684\u5674\u5634\u4e2d\u6975\u5177\u8010\u7528\u6027\u3002\u6709\u8da3\u7684\u662f\uff0c\u96d6\u7136\u9338\u5728\u5730\u6bbc\u4e2d\u6975\u5176\u7f55\u898b\uff0c\u4f46\u5b83\u5728\u8d85\u5c0e\u7814\u7a76\u4e2d\u4e5f\u5360\u6709\u4e00\u5e2d\u4e4b\u5730\uff0c\u5728\u6975\u4f4e\u6eab\u4e0b\u6703\u8868\u73fe\u51fa\u96f6\u96fb\u963b\u7279\u6027\u3002\u9019\u7a2e\u5f9e\u840a\u8335\u6cb3\u4e4b\u540d\u7684\u6d6a\u6f2b\u5230\u5b9a\u7fa9\u73fe\u4ee3\u5674\u5c04\u52d5\u529b\u6975\u9650\u7684\u5be6\u529b\uff0c\u7cbe\u78ba\u8a6e\u91cb\u4e86\u9338\u5728\u9031\u671f\u8868\u4e2d\u4f5c\u70ba\u300c\u96e3\u7194\u91d1\u5c6c\u4e4b\u5dd4\u300d\u7684\u51b7\u5cfb\u5730\u4f4d\u3002",
  "\x4f\x73":
    "\u92e8\x28\x4f\x73\x6d\x69\x75\x6d\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x4f\x73\uff0c\u539f\u5b50\u5e8f\x20\x37\x36\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u516d\u9031\u671f\u3001\u7b2c\x20\x38\x20\u65cf\x28\x64\x20\u5340\u584a\x29\uff0c\u662f\u9251\u65cf\u5143\u7d20\x28\x50\x47\x4d\x29\u7684\u4e00\u54e1\u3002\u5176\u540d\u7a31\u6e90\u65bc\u5e0c\u81d8\u8a9e\u300c\x6f\x73\x6d\x65\u300d\uff0c\u610f\u70ba\u300c\u6c23\u5473\u300d\uff0c\u56e0\u5176\u6c27\u5316\u7269\u56db\u6c27\u5316\u92e8\x28\x4f\x73\x4f\u2084\x29\u5177\u6709\u5f37\u70c8\u4e14\u5177\u523a\u6fc0\u6027\u7684\u60e1\u81ed\u3002\x31\x38\x30\x33\x20\u5e74\u7531\u82f1\u570b\u5316\u5b78\u5bb6\u7530\u7d0d\u7279\x28\x53\x6d\x69\x74\x68\x73\x6f\x6e\x20\x54\x65\x6e\x6e\x61\x6e\x74\x29\u5f9e\u7c97\u9251\u7926\u7684\u6b98\u6e23\u4e2d\u767c\u73fe\u3002\u92e8\u662f\u81ea\u7136\u754c\u4e2d\u300c\u5bc6\u5ea6\u6700\u9ad8\u300d\u7684\u5929\u7136\u5143\u7d20\x28\u7d04\x20\x32\x32\x2e\x35\x39\x20\x67\x2f\x63\x6d\u00b3\x29\uff0c\u5176\u91cd\u91cf\u7d04\u70ba\u540c\u9ad4\u7a4d\u6c34\u7684\x20\x32\x32\x2e\x36\x20\u500d\uff0c\u5177\u5099\u6975\u9ad8\u7684\u786c\u5ea6\u8207\u6297\u8755\u6027\uff0c\u662f\u6750\u6599\u79d1\u5b78\u4e2d\u7814\u7a76\u6975\u9650\u58d3\u7e2e\u7387\u8207\u9ad8\u7a69\u5b9a\u6027\u7684\u6a19\u7aff\u3002\x0a\x0a\u92e8\u7684\u96fb\u5b50\u7d44\u614b\u70ba\x20\x5b\x58\x65\x5d\x34\x66\u00b9\u2074\x35\x64\u2076\x36\x73\u00b2\uff0c\u6700\u7a69\u5b9a\u7684\u6c27\u5316\u614b\u70ba\x20\x2b\x34\x20\u8207\x20\x2b\x38\u3002\u5728\u9ad8\u4e2d\u5316\u5b78\u63a2\u8a0e\u904e\u6e21\u91d1\u5c6c\u6027\u8cea\u6642\uff0c\u92e8\u662f\u8aaa\u660e\u300c\u6975\u9ad8\u6c27\u5316\u614b\u300d\u53ef\u80fd\u6027\u7684\u6700\u4f73\u5be6\u4f8b\uff1a\u56db\u6c27\u5316\u92e8\x28\x4f\x73\x4f\u2084\x29\u662f\u5c11\u6578\u5448\u73fe\x20\x2b\x38\x20\u50f9\u7684\u7a69\u5b9a\u5316\u5408\u7269\uff0c\u4e14\u7531\u65bc\u5176\u5206\u5b50\u7d50\u69cb\u5c0d\u7a31\x28\u56db\u9762\u9ad4\x29\uff0c\u5c55\u73fe\u51fa\u63ee\u767c\u6027\u8207\u975e\u6975\u6027\u7279\u5fb5\u3002\u6b64\u5916\uff0c\x4f\x73\x4f\u2084\x20\u5728\u6709\u6a5f\u5408\u6210\u4e2d\u5177\u5099\u6838\u5fc3\u5730\u4f4d\uff0c\u662f\u50ac\u5316\u70ef\u70f4\u767c\u751f\u300c\u9806\u5f0f\u4e8c\u7fa5\u57fa\u5316\u300d\x28\x73\x79\x6e\x2d\x64\x69\x68\x79\x64\x72\x6f\x78\x79\x6c\x61\x74\x69\x6f\x6e\x29\u53cd\u61c9\u7684\u9ad8\u6548\u8a66\u5291\u3002\u7136\u800c\uff0c\x4f\x73\x4f\u2084\x20\u5177\u5099\u5287\u6bd2\u4e14\u6613\u6607\u83ef\uff0c\u80fd\u8207\u4eba\u9ad4\u7d44\u7e54\u767c\u751f\u5287\u70c8\u53cd\u61c9\u5c0e\u81f4\u5931\u660e\u6216\u547c\u5438\u9053\u640d\u50b7\uff0c\u4f7f\u7528\u6642\u9700\u6975\u56b4\u5bc6\u7684\u9632\u8b77\u3002\x0a\x0a\u5728\u73fe\u4ee3\u61c9\u7528\u4e2d\uff0c\u92e8\u7684\u6975\u81f4\u786c\u5ea6\u8207\u8010\u78e8\u6027\u4f7f\u5176\u5e38\u8207\u92a5\u3001\u9251\u88fd\u6210\u8d85\u786c\u5408\u91d1\uff0c\u5ee3\u6cdb\u61c9\u7528\u65bc\u9700\u8981\u9577\u671f\u6469\u64e6\u6d88\u8017\u7684\u7cbe\u5bc6\u96f6\u4ef6\uff0c\u5982\u92fc\u7b46\u5c16\u3001\u7559\u8072\u6a5f\u91dd\u982d\u4ee5\u53ca\u7cbe\u5bc6\u5100\u5668\u7684\u8f49\u8ef8\u3002\u5728\u80fd\u6e90\u8207\u96fb\u5316\u5b78\u9818\u57df\uff0c\u92e8\u7684\u932f\u5408\u7269\u5c55\u73fe\u51fa\u512a\u7570\u7684\u5149\u4f0f\u7279\u6027\uff0c\u5e38\u88ab\u7814\u7a76\u7528\u65bc\u65b0\u578b\u67d3\u6599\u654f\u5316\u592a\u967d\u80fd\u96fb\u6c60\u4e2d\u3002\u6b64\u5916\uff0c\u7531\u65bc\u92e8\u5c0d\u7d05\u5916\u5149\u5177\u6709\u6975\u4f73\u7684\u53cd\u5c04\u7387\uff0c\u5b83\u4e5f\u88ab\u61c9\u7528\u65bc\u7279\u5b9a\u9ad8\u80fd\u96f7\u5c04\u8207\u5149\u5b78\u8a2d\u5099\u7684\u53cd\u5c04\u5c64\u6750\u6599\uff0c\u78ba\u4fdd\u5728\u6975\u7aef\u689d\u4ef6\u4e0b\u7d50\u69cb\u4e0d\u8b8a\u5f62\u3002\x0a\x0a\u95dc\u65bc\u92e8\u7684\u7269\u7406\u7279\u5fb5\uff0c\u5b83\u64c1\u6709\u6975\u9ad8\u7684\u300c\u9ad4\u7a4d\u6a21\u6578\u300d\x28\x42\x75\x6c\x6b\x20\x4d\x6f\x64\x75\x6c\x75\x73\x29\uff0c\u5176\u5c0d\u5916\u90e8\u58d3\u529b\u7684\u62b5\u6297\u80fd\u529b\u751a\u81f3\u53ef\u8207\u947d\u77f3\u5ab2\u7f8e\u3002\u53cd\u76f4\u89ba\u7684\u662f\uff0c\u96d6\u7136\u92e8\u662f\u91d1\u5c6c\uff0c\u4f46\u5176\u55ae\u8cea\u975e\u5e38\u8106\uff0c\u96e3\u4ee5\u900f\u904e\u5e38\u898f\u7684\u6a5f\u68b0\u52a0\u5de5\u6210\u5f62\u3002\u6709\u8da3\u7684\u662f\uff0c\u7531\u65bc\u92e8\u7684\u539f\u5b50\u6392\u5217\u6975\u5176\u7dca\u5bc6\uff0c\u5b83\u5e38\u88ab\u7528\u65bc\u96fb\u5b50\u986f\u5fae\u93e1\u6a19\u672c\u7684\u5857\u5c64\uff0c\u4ee5\u63d0\u4f9b\u6975\u4f73\u7684\u5c0e\u96fb\u6027\u4e26\u9632\u6b62\u6a19\u672c\u53d7\u640d\u3002\u9019\u7a2e\u5f9e\u5730\u7cbe\u822c\u6563\u767c\u60e1\u81ed\u7684\u6c27\u5316\u7269\u5230\u5b9a\u7fa9\u5730\u7403\u7269\u8cea\u5bc6\u5ea6\u5dd4\u5cf0\u7684\u8f49\u8b8a\uff0c\u7cbe\u78ba\u8a6e\u91cb\u4e86\u92e8\u5728\u9031\u671f\u8868\u4e2d\u4f5c\u70ba\u300c\u91cd\u91d1\u5c6c\u4e4b\u9996\u300d\u7684\u7269\u7406\u5f35\u529b\u3002",
  "\x49\x72":
    "\u92a5\x28\x49\x72\x69\x64\x69\x75\x6d\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x49\x72\uff0c\u539f\u5b50\u5e8f\x20\x37\x37\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u516d\u9031\u671f\u3001\u7b2c\x20\x31\x37\x20\u65cf\x28\x64\x20\u5340\u584a\x29\u3002\u5176\u540d\u7a31\u6e90\u65bc\u5e0c\u81d8\u8679\u5f69\u5973\u795e\u300c\x49\x72\x69\x73\u300d\uff0c\u5f97\u540d\u65bc\u5176\u9e7d\u985e\u5316\u5408\u7269\u5448\u73fe\u51fa\u591a\u7a2e\u7d62\u9e97\u7684\u8272\u5f69\u3002\x31\x38\x30\x33\x20\u5e74\u7531\u7530\u7d0d\u7279\x28\x53\x6d\x69\x74\x68\x73\x6f\x6e\x20\x54\x65\x6e\x6e\x61\x6e\x74\x29\u5728\u9251\u7926\u6b98\u6e23\u4e2d\u767c\u73fe\u3002\u92a5\u662f\u5df2\u77e5\u300c\u6297\u8150\u8755\u6027\u6700\u5f37\u300d\u7684\u91d1\u5c6c\uff0c\u5728\u5e38\u6eab\u5e38\u58d3\u4e0b\u5e7e\u4e4e\u4e0d\u8207\u4efb\u4f55\u9178\u3001\u9e7c\u767c\u751f\u53cd\u61c9\uff0c\u751a\u81f3\u5f37\u5927\u7684\u738b\u6c34\u4e5f\u7121\u6cd5\u5c0d\u5176\u9020\u6210\u640d\u5bb3\u3002\u92a5\u6975\u5ea6\u7a00\u6709\uff0c\u4f46\u5728\u67d0\u4e9b\u9695\u77f3\u4e2d\u542b\u91cf\u537b\u986f\u8457\u9ad8\u65bc\u5730\u6bbc\u5e73\u5747\u503c\uff0c\u9019\u4f7f\u5176\u5728\u5730\u7403\u79d1\u5b78\u8207\u73fe\u4ee3\u5de5\u696d\u4e2d\u5177\u5099\u7279\u6b8a\u7684\u6307\u6a19\u5730\u4f4d\u3002\x0a\x0a\u92a5\u7684\u96fb\u5b50\u7d44\u614b\u70ba\x20\x5b\x58\x65\x5d\x34\x66\u00b9\u2074\x35\x64\u2077\x36\x73\u00b2\uff0c\u6700\u5e38\u898b\u7684\u6c27\u5316\u614b\u70ba\x20\x2b\x33\x20\u8207\x20\x2b\x34\u3002\u5728\u5316\u5b78\u898f\u5f8b\u4e2d\uff0c\u92a5\u5c55\u73fe\u51fa\u6975\u9ad8\u7684\u5316\u5b78\u60f0\u6027\u8207\u7a69\u5b9a\u6027\u3002\u5b83\u7684\u5bc6\u5ea6\x28\u7d04\x20\x32\x32\x2e\x35\x36\x20\x67\x2f\x63\x6d\u00b3\x29\u8207\u92e8\u76f8\u5dee\u6975\u5fae\uff0c\u5169\u8005\u5171\u540c\u7af6\u722d\u5730\u7403\u6700\u91cd\u7269\u8cea\u7684\u5bf6\u5ea7\u3002\u5728\u9ad8\u4e2d\u5316\u5b78\u95dc\u65bc\u6a19\u6e96\u8207\u5ea6\u91cf\u7684\u8a0e\u8ad6\u4e2d\uff0c\u92a5\u6700\u91cd\u8981\u7684\u6b77\u53f2\u8ca2\u737b\u662f\u8207\u9251\u88fd\u6210\u300c\u9251\u92a5\u5408\u91d1\u300d\uff0c\u7531\u65bc\u8a72\u5408\u91d1\u96a8\u6642\u9593\u8b8a\u5f62\u6975\u5c0f\u4e14\u6297\u5316\u5b78\u4fb5\u8755\uff0c\u66fe\u88ab\u7528\u4f5c\u5b58\u653e\u65bc\u5df4\u9ece\u7684\u570b\u969b\u300c\u7c73\u539f\u5668\u300d\u8207\u300c\u516c\u65a4\u539f\u5668\u300d\u7684\u88fd\u4f5c\u6750\u6599\uff0c\u6210\u70ba\u73fe\u4ee3\u79d1\u5b78\u5ea6\u91cf\u8861\u9ad4\u7cfb\u7684\u7269\u7406\u57fa\u77f3\u3002\x0a\x0a\u5728\u73fe\u4ee3\u7cbe\u5bc6\u79d1\u6280\u4e2d\uff0c\u92a5\u7684\u9ad8\u7194\u9ede\x28\u7d04\x20\x32\x34\x34\x36\x20\u00b0\x43\x29\u8207\u5316\u5b78\u7a69\u5b9a\u6027\u4f7f\u5176\u6210\u70ba\u88fd\u9020\u9ad8\u6eab\u611f\u6e2c\u5668\u3001\u706b\u661f\u585e\u96fb\u6975\u8207\u9ad8\u54c1\u8cea\u4eba\u5de5\u55ae\u6676\u751f\u9577\u7528\u300c\u5769\u581d\u300d\u7684\u9996\u9078\u6750\u6599\u3002\u5728\u80fd\u6e90\u9818\u57df\uff0c\u92a5\u7684\u6c27\u5316\u7269\u662f\u96fb\u89e3\u6c34\u7522\u6c2b\u4e2d\u8cea\u5b50\u4ea4\u63db\u819c\x28\x50\x45\x4d\x29\u6280\u8853\u7684\u6838\u5fc3\u967d\u6975\u50ac\u5316\u5291\uff0c\u5118\u7ba1\u6210\u672c\u9ad8\u6602\uff0c\u4f46\u56e0\u5176\u5728\u9178\u6027\u74b0\u5883\u4e0b\u5353\u8d8a\u7684\u7a69\u5b9a\u6027\u800c\u4e0d\u53ef\u66ff\u4ee3\u3002\u6b64\u5916\uff0c\u92a5\u7684\u932f\u5408\u7269\u5177\u5099\u512a\u7570\u7684\u5149\u81f4\u767c\u5149\u7279\u6027\uff0c\u5ee3\u6cdb\u61c9\u7528\u65bc\u9ad8\u6548\u7387\u6709\u6a5f\u767c\u5149\u4e8c\u6975\u9ad4\x28\x4f\x4c\x45\x44\x29\u7684\u647b\u96dc\u767c\u5149\u6750\u6599\u4e2d\uff0c\u63d0\u5347\u4e86\u87a2\u5e55\u7684\u8272\u5f69\u7d14\u5ea6\u8207\u80fd\u6548\u3002\x0a\x0a\u92a5\u5728\u5730\u7403\u6b77\u53f2\u7814\u7a76\u4e2d\u5c55\u73fe\u4e86\u95dc\u9375\u7684\u300c\u79d1\u5b78\u8b49\u64da\u300d\u4f5c\u7528\u3002\u5730\u8cea\u5b78\u5bb6\u5728\u5168\u7403\u767d\u580a\u7d00\uff0d\u53e4\u8fd1\u7d00\u754c\u7dda\x28\x4b\x2d\x50\x67\x20\x62\x6f\x75\x6e\x64\x61\x72\x79\x29\u5730\u5c64\u4e2d\u767c\u73fe\u4e86\u7570\u5e38\u9ad8\u6fc3\u5ea6\u7684\u92a5\u5c64\uff0c\u9019\u6210\u70ba\u652f\u6301\u300c\u5c0f\u884c\u661f\u649e\u64ca\u5c0e\u81f4\u6050\u9f8d\u6ec5\u7d55\u300d\u5047\u8aaa\u7684\u6700\u6709\u529b\u7269\u7406\u8b49\u64da\u3002\u6709\u8da3\u7684\u662f\uff0c\u96d6\u7136\u92a5\u6975\u5176\u4e0d\u6d3b\u6f51\uff0c\u4f46\u5728\u9ad8\u6eab\u4e0b\u6703\u8207\u6c27\u7de9\u6162\u53cd\u61c9\u5f62\u6210\u63ee\u767c\u6027\u7684\u4e8c\u6c27\u5316\u92a5\u3002\u9019\u7a2e\u5f9e\u5f69\u8679\u4e4b\u795e\u7684\u540d\u865f\u5230\u63ed\u958b\u751f\u547d\u6f14\u5316\u5927\u898f\u6a21\u6ec5\u7d55\u4e4b\u8b0e\u7684\u79d1\u5b78\u8b49\u64da\uff0c\u7cbe\u78ba\u8a6e\u91cb\u4e86\u92a5\u5728\u9031\u671f\u8868\u4e2d\u4f5c\u70ba\u300c\u6c38\u6046\u4e0d\u673d\u300d\u8207\u300c\u5b87\u5b99\u4fe1\u4f7f\u300d\u7684\u96d9\u91cd\u7279\u8cea\u3002",
  "\x50\x74":
    "\u9251\x28\x50\x6c\x61\x74\x69\x6e\x75\x6d\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x50\x74\uff0c\u539f\u5b50\u5e8f\x20\x37\x38\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u516d\u9031\u671f\u3001\u7b2c\x20\x31\x30\x20\u65cf\x28\x64\x20\u5340\u584a\x29\u3002\u5176\u540d\u7a31\u6e90\u65bc\u897f\u73ed\u7259\u8a9e\u300c\x70\x6c\x61\x74\x69\x6e\x61\u300d\uff0c\u610f\u70ba\u300c\u5c0f\u9280\u300d\u3002\u9251\u5728\u53e4\u4ee3\u5357\u7f8e\u6d32\u5373\u5df2\u88ab\u539f\u4f4f\u6c11\u4f7f\u7528\uff0c\u4f46\u6b50\u6d32\u79d1\u5b78\u754c\u76f4\u5230\x20\x31\x38\x20\u4e16\u7d00\u624d\u7531\u70cf\u7565\u4e9e\x28\x41\x6e\x74\x6f\x6e\x69\x6f\x20\x64\x65\x20\x55\x6c\x6c\x6f\x61\x29\u6b63\u5f0f\u63cf\u8ff0\u3002\u9251\u662f\u4e00\u7a2e\u5448\u73fe\u9280\u767d\u8272\u6fa4\u3001\u5ef6\u5c55\u6027\u6975\u4f73\u7684\u8cb4\u91d1\u5c6c\uff0c\u5316\u5b78\u6027\u8cea\u6975\u5176\u7a69\u5b9a\u3002\u5b83\u662f\u73fe\u4ee3\u7da0\u8272\u80fd\u6e90\u3001\u91ab\u5b78\u6297\u764c\u8207\u5316\u5b78\u5de5\u696d\u4e2d\u6700\u91cd\u8981\u7684\u300c\u5168\u80fd\u578b\u50ac\u5316\u5291\u300d\uff0c\u4ea6\u662f\u9ad8\u968e\u9996\u98fe\u5e02\u5834\u4e2d\u7684\u9802\u7d1a\u6750\u6599\u3002\x0a\x0a\u9251\u7684\u57fa\u614b\u96fb\u5b50\u7d44\u614b\u5e38\u88ab\u6a19\u8a18\u70ba\x20\x5b\x58\x65\x5d\x34\x66\u00b9\u2074\x35\x64\u2079\x36\x73\u00b9\u3002\u96d6\u7136\u5b83\u88ab\u6b78\u985e\u70ba\u975e\u6d3b\u6027\u91d1\u5c6c\x28\x4e\x6f\x62\x6c\x65\x20\x6d\x65\x74\x61\x6c\x29\uff0c\u50c5\u80fd\u6eb6\u65bc\u738b\u6c34\uff0c\u4f46\u5b83\u5c0d\u6c23\u9ad4\u5206\u5b50\x28\u7279\u5225\u662f\u6c2b\u8207\u6c27\x29\u5177\u6709\u6975\u5f37\u7684\u5438\u9644\u8207\u6d3b\u5316\u80fd\u529b\u3002\u5728\u53f0\u7063\u9ad8\u4e2d\u5316\u5b78\u96fb\u5316\u5b78\u7ae0\u7bc0\u4e2d\uff0c\u9251\u662f\u5efa\u7acb\u7406\u8ad6\u57fa\u6e96\u7684\u6838\u5fc3\uff1a\u7531\u65bc\u5176\u4e0d\u53c3\u8207\u53cd\u61c9\u4e14\u5c0e\u96fb\u6027\u4f73\uff0c\u5b83\u88ab\u7528\u4f5c\u300c\u6a19\u6e96\u6c2b\u96fb\u6975\u300d\x28\x53\x48\x45\x29\u7684\u5c0e\u9ad4\uff0c\u5b9a\u7fa9\u4e86\u96fb\u6975\u96fb\u4f4d\x20\x30\x20\u4f0f\u7279\u7684\u57fa\u6e96\u9ede\u3002\u6b64\u5916\uff0c\u9251\u96fb\u6975\u5728\u591a\u7a2e\u6c27\u5316\u9084\u539f\u6ef4\u5b9a\u8207\u96fb\u89e3\u5be6\u9a57\u4e2d\u4f5c\u70ba\u60f0\u6027\u96fb\u6975\uff0c\u78ba\u4fdd\u5316\u5b78\u9ad4\u7cfb\u7684\u96fb\u5b50\u4ea4\u63db\u4e0d\u88ab\u96fb\u6975\u81ea\u8eab\u7684\u6eb6\u89e3\u6240\u5e72\u64fe\u3002\x0a\x0a\u5728\u73fe\u4ee3\u61c9\u7528\u9818\u57df\uff0c\u9251\u662f\u300c\u6c2b\u80fd\u7d93\u6fdf\u300d\u7684\u6838\u5fc3\u5f15\u64ce\u3002\u5728\u6c2b\u71c3\u6599\u96fb\u6c60\u4e2d\uff0c\u9251\u4f5c\u70ba\u9670\u967d\u5169\u6975\u7684\u50ac\u5316\u5291\uff0c\u52a0\u901f\u6c2b\u6c23\u6c27\u5316\u8207\u6c27\u6c23\u9084\u539f\uff0c\u5c07\u5316\u5b78\u80fd\u76f4\u63a5\u8f49\u5316\u70ba\u96fb\u80fd\u3002\u5728\u74b0\u5883\u4fdd\u8b77\u65b9\u9762\uff0c\u6c7d\u8eca\u5ee2\u6c23\u7684\u300c\u4e09\u5143\u89f8\u5a92\u8f49\u5316\u5668\u300d\u5229\u7528\u9251\u6c27\u5316\u4e00\u6c27\u5316\u78b3\u8207\u78b3\u6c2b\u5316\u5408\u7269\uff0c\u986f\u8457\u964d\u4f4e\u90fd\u5e02\u7a7a\u6c61\u3002\u91ab\u7642\u4e0a\uff0c\u9251\u985e\u85e5\u7269\u5982\u300c\u9806\u9251\u300d\x28\x43\x69\x73\x70\x6c\x61\x74\x69\x6e\x29\u80fd\u8207\u7d30\u80de\u5167\u7684\x20\x44\x4e\x41\x20\u7d50\u5408\uff0c\u5e72\u64fe\u764c\u7d30\u80de\u7684\u8907\u88fd\uff0c\u662f\u73fe\u4ee3\u5316\u5b78\u6cbb\u7642\u4e2d\u6700\u57fa\u790e\u7684\u6a19\u9776\u85e5\u7269\u4e4b\u4e00\u3002\u6b64\u5916\uff0c\u9251\u7684\u9ad8\u7a69\u5b9a\u6027\u4f7f\u5176\u6210\u70ba\u7cbe\u5bc6\u6eab\u5ea6\u611f\u6e2c\u5668\x28\x50\x54\x31\x30\x30\x29\u7684\u611f\u6eab\u5143\u4ef6\uff0c\u6e2c\u91cf\u7bc4\u570d\u5ee3\u6cdb\u4e14\u6578\u64da\u6975\u5176\u7a69\u5b9a\u3002\x0a\x0a\u9251\u5728\u7269\u7406\u7279\u6027\u4e0a\u5c55\u73fe\u51fa\u5353\u8d8a\u7684\u97cc\u6027\uff0c\u5373\u4f7f\u662f\u7d30\u5982\u9aee\u7d72\u7684\u9251\u7dda\u4e5f\u80fd\u627f\u53d7\u6975\u5927\u62c9\u529b\u800c\u4e0d\u65b7\u88c2\u3002\u6709\u8da3\u7684\u662f\uff0c\u96d6\u7136\u9251\u5728\u5e38\u6eab\u4e0b\u770b\u4f3c\u975c\u6b62\uff0c\u4f46\u5fae\u89c0\u4e0b\u5b83\u80fd\u6975\u5feb\u5730\u5438\u9644\u4e26\u62c6\u89e3\u6c2b\u5206\u5b50\uff0c\u9019\u4f7f\u5b83\u5728\u8655\u7406\u6838\u53cd\u61c9\u904e\u7a0b\u7522\u751f\u7684\u5371\u96aa\u6c2b\u6c23\u7d2f\u7a4d\u6642\u626e\u6f14\u95dc\u9375\u89d2\u8272\u3002\u6b64\u5916\uff0c\u9251\u8207\u9ec3\u91d1\u4e0d\u540c\uff0c\u5b83\u4e0d\u6703\u5728\u5408\u91d1\u4e2d\u892a\u8272\uff0c\u9577\u671f\u914d\u6234\u4ecd\u80fd\u4fdd\u6301\u7d14\u6de8\u7684\u767d\u5149\uff0c\u56e0\u6b64\u88ab\u8b7d\u70ba\u300c\u91d1\u5c6c\u4e4b\u738b\u300d\u3002\u9019\u7a2e\u5f9e\u5b9a\u7fa9\u5168\u7403\u96fb\u4f4d\u57fa\u6e96\u7684\u51b7\u5cfb\u5230\u5728\u4eba\u9ad4\u5167\u5c0d\u6297\u764c\u7d30\u80de\u7684\u6eab\u67d4\uff0c\u7cbe\u78ba\u8a6e\u91cb\u4e86\u9251\u5728\u904e\u6e21\u91d1\u5c6c\u4e2d\u7a69\u5b9a\u8207\u6d3b\u6027\u5b8c\u7f8e\u4e26\u5b58\u7684\u50f9\u503c\u3002",
  "\x41\x75":
    "\u91d1\x28\x47\x6f\x6c\x64\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x41\x75\uff0c\u539f\u5b50\u5e8f\x20\x37\x39\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u516d\u9031\u671f\u3001\u7b2c\x20\x31\x31\x20\u65cf\x28\x64\x20\u5340\u584a\x29\u3002\u5176\u7b26\u865f\x20\x41\x75\x20\u6e90\u81ea\u62c9\u4e01\u8a9e\u300c\x41\x75\x72\x75\x6d\u300d\uff0c\u610f\u70ba\u300c\u9583\u8000\u7684\u9ece\u660e\u300d\u3002\u91d1\u662f\u4eba\u985e\u6700\u65e9\u767c\u73fe\u4e26\u73cd\u8996\u7684\u8cb4\u91d1\u5c6c\u4e4b\u4e00\uff0c\u56e0\u5176\u7368\u7279\u7684\u8272\u6fa4\u8207\u6975\u9ad8\u7684\u5316\u5b78\u7a69\u5b9a\u6027\uff0c\u5728\u6b77\u53f2\u4e0a\u9577\u671f\u4f5c\u70ba\u8ca8\u5e63\u8207\u6b0a\u529b\u7684\u8c61\u5fb5\u3002\u91d1\u5728\u5730\u6bbc\u4e2d\u591a\u4ee5\u6e38\u96e2\u614b\u81ea\u7136\u91d1\u7684\u5f62\u5f0f\u5b58\u5728\uff0c\u662f\u5ef6\u5c55\u6027\u6700\u5f37\u7684\u91d1\u5c6c\uff0c\u80fd\u88ab\u52a0\u5de5\u6210\u6975\u8584\u7684\u7b94\u7247\u6216\u6975\u7d30\u7684\u7d72\u7dda\uff0c\u5c55\u73fe\u51fa\u5b8f\u89c0\u7269\u7406\u6975\u9650\u7684\u9b45\u529b\u3002\x0a\x0a\u5728\u5316\u5b78\u6027\u8cea\u4e0a\uff0c\u91d1\u7684\u96fb\u5b50\u7d44\u614b\u70ba\x20\x5b\x58\x65\x5d\x34\x66\u00b9\u2074\x35\x64\u00b9\u2070\x36\x73\u00b9\uff0c\u5c55\u73fe\u4e86\u986f\u8457\u7684\u7a69\u5b9a\u6027\u3002\u91d1\u7684\u96fb\u8ca0\u5ea6\u7d04\u70ba\x20\x32\x2e\x35\x34\uff0c\u5176\u6a19\u6e96\u9084\u539f\u96fb\u4f4d\u6975\u9ad8\x28\x45\u2070\x20\u2248\x20\x2b\x31\x2e\x35\x30\x20\x56\x29\uff0c\u9019\u4f7f\u5176\u5728\u81ea\u7136\u754c\u4e2d\u5e7e\u4e4e\u4e0d\u8207\u6c27\u6c23\u6216\u5927\u591a\u6578\u9178\u3001\u9e7c\u53cd\u61c9\u3002\u91d1\u5448\u73fe\u7279\u6709\u7684\u9ec3\u8272\u5149\u6fa4\uff0c\u9019\u5728\u7269\u7406\u5316\u5b78\u4e2d\u6e90\u65bc\u300c\u76f8\u5c0d\u8ad6\u6548\u61c9\u300d\x28\x52\x65\x6c\x61\x74\x69\x76\x69\x73\x74\x69\x63\x20\x65\x66\x66\x65\x63\x74\x73\x29\uff0c\u5c0e\u81f4\x20\x35\x64\x20\u8207\x20\x36\x73\x20\u8ecc\u57df\u80fd\u968e\u6536\u7e2e\u8207\u80fd\u91cf\u6539\u8b8a\uff0c\u9032\u800c\u5438\u6536\u85cd\u7d2b\u8272\u5149\u4e26\u53cd\u5c04\u91d1\u9ec3\u8272\u5149\u3002\u6b64\u5916\uff0c\u91d1\u80fd\u6eb6\u65bc\u5f37\u6c27\u5316\u529b\u7684\u300c\u738b\u6c34\u300d\x28\x41\x71\x75\x61\x20\x52\x65\x67\x69\x61\x29\uff0c\u751f\u6210\u7a69\u5b9a\u7684\u56db\u6c2f\u5408\u91d1\u96e2\u5b50\x20\x5b\x41\x75\x43\x6c\u2084\x5d\u207b\uff0c\u9019\u662f\u9ad8\u4e2d\u5316\u5b78\u63a2\u8a0e\u932f\u5408\u53cd\u61c9\u8207\u6975\u9650\u7a69\u5b9a\u6027\u7684\u91cd\u8981\u5be6\u4f8b\u3002\x0a\x0a\u5728\u53f0\u7063\u9ad8\u4e2d\u8ab2\u7db1\u8207\u73fe\u4ee3\u79d1\u6280\u61c9\u7528\u4e2d\uff0c\u91d1\u662f\u5fae\u96fb\u5b50\u7522\u696d\u7684\u547d\u8108\u3002\u7531\u65bc\u91d1\u5177\u5099\u512a\u7570\u7684\u5c0e\u96fb\u6027\u4e14\u6c38\u4e0d\u6c27\u5316\uff0c\u5b83\u88ab\u5ee3\u6cdb\u7528\u65bc\u7a4d\u9ad4\u96fb\u8def\u4e2d\u7684\u300c\u6253\u7dda\u5c01\u88dd\u300d\x28\x57\x69\x72\x65\x20\x62\x6f\x6e\x64\x69\x6e\x67\x29\u8207\u7cbe\u5bc6\u63a5\u9ede\u3002\u5728\u5948\u7c73\u6280\u8853\u4e2d\uff0c\u91d1\u5948\u7c73\u7c92\u5b50\u5177\u5099\u7368\u7279\u7684\u300c\u8868\u9762\u96fb\u6f3f\u5171\u9cf4\u300d\x28\x53\x50\x52\x29\u73fe\u8c61\uff0c\u80fd\u96a8\u7c92\u5b50\u5c3a\u5bf8\u6539\u8b8a\u986f\u73fe\u7d05\u3001\u7d2b\u7b49\u7e7d\u7d1b\u8272\u5f69\uff0c\u5ee3\u6cdb\u61c9\u7528\u65bc\u751f\u91ab\u611f\u6e2c\u8207\u6a19\u9776\u6cbb\u7642\u3002\u6b64\u5916\uff0c\u5728\u5316\u5b78\u5de5\u696d\u4e2d\uff0c\u91d1\u57fa\u50ac\u5316\u5291\u5728\u4f4e\u6eab\u6c27\u5316\u4e00\u6c27\u5316\u78b3\u8207\u6709\u6a5f\u5408\u6210\u4e2d\u5c55\u73fe\u4e86\u6975\u9ad8\u7684\u9078\u64c7\u6027\u8207\u6d3b\u6027\u3002\x0a\x0a\u91d1\u5c55\u73fe\u4e86\u67d0\u4e9b\u53cd\u76f4\u89ba\u7684\u7269\u7406\u73fe\u8c61\u3002\u96d6\u7136\u5b83\u662f\u6975\u6c89\u91cd\u7684\u91d1\u5c6c\x28\u5bc6\u5ea6\u7d04\x20\x31\x39\x2e\x33\x20\x67\x2f\x63\x6d\u00b3\x29\uff0c\u4f46\u7d14\u91d1\u537b\u6975\u5176\u67d4\u8edf\uff0c\u786c\u5ea6\u50c5\u8207\u4eba\u985e\u6307\u7532\u76f8\u4eff\u3002\u6709\u8da3\u7684\u662f\uff0c\u96d6\u7136\u91d1\u88ab\u8996\u70ba\u5316\u5b78\u60f0\u6027\uff0c\u4f46\u5728\u6975\u7aef\u689d\u4ef6\u4e0b\u80fd\u8207\u6c1f\u6216\u6c2f\u767c\u751f\u53cd\u61c9\uff0c\u751a\u81f3\u80fd\u5f62\u6210\u5e36\u8ca0\u96fb\u8377\u7684\u300c\u91d1\u8ca0\u96e2\u5b50\u300d\x28\x41\x75\u207b\x29\uff0c\u9019\u53cd\u6620\u4e86\u5176\u6975\u5f37\u7684\u96fb\u5b50\u89aa\u548c\u529b\u3002\u9019\u7a2e\u5f9e\u53e4\u5178\u8ca8\u5e63\u7684\u5c0a\u8cb4\u5230\u73fe\u4ee3\u534a\u5c0e\u9ad4\u8207\u5948\u7c73\u91ab\u5b78\u7684\u7cbe\u5bc6\uff0c\u7cbe\u78ba\u8a6e\u91cb\u4e86\u91d1\u5728\u9031\u671f\u8868\u4e2d\u4f5c\u70ba\u300c\u8cb4\u91d1\u5c6c\u4e4b\u738b\u300d\u7684\u5730\u4f4d\u3002",
  "\x48\x67":
    "\u6c5e\x28\x4d\x65\x72\x63\x75\x72\x79\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x48\x67\uff0c\u539f\u5b50\u5e8f\x20\x38\x30\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u516d\u9031\u671f\u3001\u7b2c\x20\x31\x32\x20\u65cf\x28\x64\x20\u5340\u584a\x29\u3002\u5176\u7b26\u865f\x20\x48\x67\x20\u6e90\u81ea\u62c9\u4e01\u8a9e\u300c\x48\x79\x64\x72\x61\x72\x67\x79\x72\x75\x6d\u300d\uff0c\u610f\u70ba\u300c\u6db2\u614b\u7684\u9280\u300d\u3002\u6c5e\u662f\u5e38\u6eab\u5e38\u58d3\u4e0b\u552f\u4e00\u5448\u6db2\u614b\u7684\u91d1\u5c6c\u5143\u7d20\uff0c\u81ea\u53e4\u4ee5\u4f86\u5373\u56e0\u5176\u795e\u79d8\u7684\u6d41\u52d5\u6027\u800c\u5099\u53d7\u95dc\u6ce8\u3002\x31\x38\x20\u4e16\u7d00\u62c9\u74e6\u7bc0\x28\x41\x6e\x74\x6f\x69\x6e\x65\x20\x4c\x61\x76\x6f\x69\x73\x69\x65\x72\x29\u5c07\u5176\u5217\u70ba\u5143\u7d20\u3002\u6c5e\u5728\u5730\u6bbc\u4e2d\u4e3b\u8981\u4ee5\u8fb0\u7802\x28\x48\x67\x53\x29\u7684\u5f62\u5f0f\u5b58\u5728\u3002\u96d6\u7136\u6c5e\u5728\u79d1\u5b78\u53f2\u4e0a\u66fe\u63a8\u52d5\u4e86\u6eab\u5ea6\u8207\u58d3\u529b\u6e2c\u91cf\u7684\u9769\u547d\uff0c\u4f46\u5176\u5287\u6bd2\u8207\u6613\u63ee\u767c\u7684\u7279\u6027\uff0c\u4f7f\u5176\u6210\u70ba\u7576\u524d\u74b0\u5883\u5de5\u7a0b\u76e3\u63a7\u7684\u91cd\u9ede\u76ee\u6a19\u3002\x0a\x0a\u6c5e\u7684\u96fb\u5b50\u7d44\u614b\u70ba\x20\x5b\x58\x65\x5d\x34\x66\u00b9\u2074\x35\x64\u00b9\u2070\x36\x73\u00b2\uff0c\u5176\x20\x36\x73\x20\u8ecc\u57df\u96fb\u5b50\u53d7\u5230\u539f\u5b50\u6838\u5f37\u5927\u7684\u76f8\u5c0d\u8ad6\u6027\u6536\u7e2e\u5f71\u97ff\uff0c\u5f62\u6210\u7a69\u5b9a\u7684\u5c01\u9589\u96fb\u5b50\u5c0d\u3002\u9019\u7a2e\u96fb\u5b50\u6392\u5e03\u4f7f\u5f97\u6c5e\u539f\u5b50\u9593\u7684\u300c\u91d1\u5c6c\u9375\u300d\u6975\u5176\u5fae\u5f31\uff0c\u5c0e\u81f4\u5176\u7194\u9ede\u4f4e\u81f3\x20\x2d\x33\x38\x2e\x38\x20\u00b0\x43\u3002\u6c5e\u7684\u6a19\u6e96\u6c27\u5316\u96fb\u4f4d\u4f7f\u5176\u5177\u5099\u4e00\u5b9a\u7684\u5316\u5b78\u7a69\u5b9a\u6027\uff0c\u4e0d\u6eb6\u65bc\u7a00\u9e7d\u9178\u3002\u5728\u9ad8\u4e2d\u5316\u5b78\u63a2\u8a0e\u6db2\u9ad4\u7269\u7406\u6027\u8cea\u6642\uff0c\u6c5e\u5177\u6709\u6975\u5927\u7684\u8868\u9762\u5f35\u529b\uff0c\u5728\u73bb\u7483\u5bb9\u5668\u4e2d\u6703\u5448\u73fe\u51f8\u9762\u7684\u6db2\u9762\u7d50\u69cb\x28\x43\x6f\x6e\x76\x65\x78\x20\x6d\x65\x6e\x69\x73\x63\x75\x73\x29\u3002\u6b64\u5916\uff0c\u6c5e\u80fd\u8f15\u6613\u6eb6\u89e3\u591a\u7a2e\u91d1\u5c6c\x28\u5982\u91d1\u3001\u9280\u3001\u9209\x29\uff0c\u5f62\u6210\u7a31\u70ba\u300c\u6c5e\u9f4a\u300d\x28\x41\x6d\x61\x6c\x67\x61\x6d\x29\u7684\u5408\u91d1\uff0c\u9019\u662f\u53e4\u4ee3\u7149\u91d1\u8853\u8207\u65e9\u671f\u7259\u79d1\u586b\u5145\u7684\u6838\u5fc3\u6280\u8853\u3002\x0a\x0a\u5728\u53f0\u7063\u9ad8\u4e2d\u6559\u6750\u8207\u74b0\u5883\u8b70\u984c\u4e2d\uff0c\u6c5e\u7684\u6bd2\u6027\u8207\u5faa\u74b0\u662f\u95dc\u9375\u3002\x31\x39\x35\x30\x20\u5e74\u4ee3\u7684\u300c\u6c34\u4fc1\u75c5\u300d\u63ed\u793a\u4e86\u7532\u57fa\u6c5e\x28\x43\x48\u2083\x48\x67\u207a\x29\u5728\u751f\u7269\u9ad4\u5167\u7a4d\u805a\u5c0d\u795e\u7d93\u7cfb\u7d71\u7684\u6bc0\u6ec5\u6027\u7834\u58de\uff0c\u9019\u662f\u74b0\u5883\u5316\u5b78\u63a2\u8a0e\u751f\u7269\u653e\u5927\u4f5c\u7528\u7684\u91cd\u8981\u6848\u4f8b\u3002\u5728\u73fe\u4ee3\u79d1\u6280\u4e2d\uff0c\u6c5e\u84b8\u6c23\u5728\u53d7\u6fc0\u767c\u5f8c\u80fd\u91cb\u653e\u7279\u5b9a\u5149\u8b5c\uff0c\u88ab\u7528\u65bc\u87a2\u5149\u71c8\u8207\u9ad8\u58d3\u6c5e\u71c8\u3002\u7136\u800c\uff0c\u7531\u65bc\u74b0\u5883\u4fdd\u8b77\u610f\u8b58\u62ac\u982d\uff0c\u50b3\u7d71\u6c5e\u6eab\u5ea6\u8a08\u8207\u6c23\u58d3\u8a08\u6b63\u9010\u6b65\u88ab\u6578\u4f4d\u8a2d\u5099\u53d6\u4ee3\uff0c\u800c\u300a\u6c34\u4fc1\u516c\u7d04\u300b\u7684\u7c3d\u7f72\u5247\u56b4\u683c\u9650\u5236\u4e86\u6c5e\u5728\u5de5\u696d\u88fd\u7a0b\x28\u5982\u6c2f\u9e7c\u5de5\u696d\x29\u4e2d\u7684\u4f7f\u7528\u3002\x0a\x0a\u6c5e\u5728\u73fe\u8c61\u5b78\u4e0a\u5c55\u73fe\u51fa\u8a31\u591a\u4ee4\u4eba\u8457\u8ff7\u7684\u7279\u5fb5\u3002\u7531\u65bc\u5176\u9ad8\u5bc6\u5ea6\x28\u7d04\x20\x31\x33\x2e\x36\x20\x67\x2f\x63\x6d\u00b3\x29\u8207\u5c0e\u96fb\u6027\uff0c\u6c5e\u66fe\u88ab\u7528\u65bc\u88fd\u4f5c\u300c\u6c34\u9280\u958b\u95dc\u300d\uff0c\u611f\u61c9\u50be\u659c\u72c0\u614b\u3002\u6709\u8da3\u7684\u662f\uff0c\u96d6\u7136\u6c5e\u662f\u91d1\u5c6c\uff0c\u4f46\u5176\u84b8\u6c23\u662f\u4ee5\u300c\u55ae\u539f\u5b50\u5206\u5b50\u300d\u7684\u5f62\u5f0f\u5b58\u5728\uff0c\u9019\u5728\u5316\u5b78\u9375\u7d50\u7814\u7a76\u4e2d\u6975\u5177\u4ee3\u8868\u6027\u3002\u5728\u96fb\u5316\u5b78\u5be6\u9a57\u4e2d\uff0c\u6c34\u9280\u96fb\u6975\u7684\u300c\u6c5e\u6ef4\u96fb\u6975\u300d\x28\x44\x4d\x45\x29\u56e0\u5176\u4e0d\u65b7\u66f4\u65b0\u7684\u8868\u9762\uff0c\u66fe\u662f\u6975\u8b5c\u5206\u6790\u6cd5\u7684\u57fa\u790e\u3002\u9019\u7a2e\u5f9e\u5be6\u9a57\u5ba4\u4e0d\u53ef\u6216\u7f3a\u7684\u6e2c\u91cf\u4ecb\u8cea\u5230\u88ab\u56b4\u683c\u63a7\u7ba1\u7684\u74b0\u5883\u6bd2\u7269\uff0c\u7cbe\u78ba\u8a6e\u91cb\u4e86\u6c5e\u5728\u6750\u6599\u61c9\u7528\u8207\u74b0\u5883\u502b\u7406\u9593\u7684\u8907\u96dc\u8eab\u5206\u3002",
  "\x54\x6c":
    "\u9248\x28\x54\x68\x61\x6c\x6c\x69\x75\x6d\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x54\x6c\uff0c\u539f\u5b50\u5e8f\x20\x38\x31\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u516d\u9031\u671f\u3001\u7b2c\x20\x31\x33\x20\u65cf\x28\x70\x20\u5340\u584a\x29\u3002\u5176\u540d\u7a31\u6e90\u65bc\u5e0c\u81d8\u8a9e\u300c\x74\x68\x61\x6c\x6c\x6f\x73\u300d\uff0c\u610f\u70ba\u300c\u7da0\u8272\u7684\u5ae9\u679d\u300d\uff0c\u5f97\u540d\u65bc\u5176\u5149\u8b5c\u4e2d\u7279\u5fb5\u6027\u7684\u9bae\u7da0\u8272\u8b5c\u7dda\u3002\x31\x38\x36\x31\x20\u5e74\u7531\u82f1\u570b\u5316\u5b78\u5bb6\u514b\u9b6f\u514b\u65af\x28\x57\x69\x6c\x6c\x69\x61\x6d\x20\x43\x72\x6f\x6f\x6b\x65\x73\x29\u5728\u786b\u9178\u5ee0\u7159\u7070\u4e2d\u767c\u73fe\u3002\u9248\u662f\u4e00\u7a2e\u8cea\u5730\u6975\u5176\u67d4\u8edf\u3001\u5177\u5099\u85cd\u767d\u8272\u91d1\u5c6c\u5149\u6fa4\u7684\u5143\u7d20\u3002\u56e0\u5176\u5177\u5099\u6975\u9ad8\u7684\u751f\u7269\u6bd2\u6027\u4e14\u5176\u5316\u5408\u7269\u7121\u8272\u7121\u5473\uff0c\u5728\u6cd5\u91ab\u53f2\u8207\u72af\u7f6a\u5c0f\u8aaa\u4e2d\u7d20\u6709\u300c\u6bd2\u6bba\u8005\u4e4b\u85e5\u300d\u7684\u7a31\u865f\uff0c\u662f\u5316\u5b78\u5bb6\u5728\u8655\u7406\u91cd\u91d1\u5c6c\u6642\u9700\u6700\u9ad8\u5ea6\u8b66\u6212\u7684\u5c0d\u8c61\u3002\x0a\x0a\u5728\u5316\u5b78\u884c\u70ba\u4e0a\uff0c\u9248\u7684\u96fb\u5b50\u7d44\u614b\u70ba\x20\x5b\x58\x65\x5d\x34\x66\u00b9\u2074\x35\x64\u00b9\u2070\x36\x73\u00b2\x36\x70\u00b9\u3002\u53d7\u300c\u920d\u6027\u96fb\u5b50\u5c0d\u6548\u61c9\u300d\x28\x49\x6e\x65\x72\x74\x20\x70\x61\x69\x72\x20\x65\x66\x66\x65\x63\x74\x29\u5f71\u97ff\uff0c\u5176\x20\x36\x73\u00b2\x20\u96fb\u5b50\u5c0d\u6975\u96e3\u53c3\u8207\u6210\u9375\uff0c\u5c0e\u81f4\u5176\x20\x2b\x31\x20\u6c27\u5316\u614b\x28\x54\x6c\u207a\x29\u6bd4\x20\x2b\x33\x20\u6c27\u5316\u614b\x28\x54\x6c\u00b3\u207a\x29\u7a69\u5b9a\u5f97\u591a\u3002\u5728\u9ad8\u4e2d\u5316\u5b78\u63a2\u8a0e\u65cf\u7fa4\u8da8\u52e2\u6642\uff0c\u9248\u662f\u8aaa\u660e\u300c\u7531\u4e0a\u800c\u4e0b\u9ad8\u6c27\u5316\u614b\u4e0d\u7a69\u5b9a\u300d\u7684\u6700\u4f73\u5be6\u4f8b\u3002\u9248\u7684\u96e2\u5b50\u534a\u5f91\u8207\u6027\u8cea\u8207\u9e7c\u91d1\u5c6c\x28\u5c24\u5176\u662f\u9240\x20\x4b\u207a\x29\u9a5a\u4eba\u76f8\u4f3c\uff0c\u9019\u4f7f\u5176\u80fd\u507d\u88dd\u6210\u751f\u7269\u9ad4\u5fc5\u9700\u7684\u96fb\u89e3\u8cea\u9032\u5165\u7d30\u80de\uff0c\u5e72\u64fe\u795e\u7d93\u50b3\u5c0e\u8207\u9175\u7d20\u529f\u80fd\uff0c\u9032\u800c\u5f15\u767c\u812b\u9aee\u3001\u795e\u7d93\u640d\u50b7\u751a\u81f3\u6b7b\u4ea1\uff0c\u5c55\u73fe\u4e86\u5316\u5b78\u6027\u8cea\u4e0a\u7684\u300c\u81f4\u547d\u6a21\u4eff\u300d\u3002\x0a\x0a\u5728\u73fe\u4ee3\u7cbe\u5bc6\u61c9\u7528\u4e2d\uff0c\u9248\u5728\u5149\u5b78\u8207\u91ab\u7642\u5075\u6e2c\u9818\u57df\u626e\u6f14\u95dc\u9375\u89d2\u8272\u3002\u7898\u5316\u9248\x28\x54\x6c\x49\x29\u5e38\u88ab\u6dfb\u52a0\u65bc\u9ad8\u6548\u7387\u91d1\u5c6c\u9e75\u5316\u7269\u71c8\u4e2d\uff0c\u63d0\u4f9b\u7d14\u6de8\u7684\u7da0\u5149\uff1b\u800c\u9248\u647b\u96dc\u7684\u7898\u5316\u9209\x28\x4e\x61\x49\x28\x54\x6c\x29\x29\u5247\u662f\u6838\u7269\u7406\u7814\u7a76\u4e2d\u6975\u91cd\u8981\u7684\u9583\u720d\u8a08\u6578\u5668\u6750\u6599\uff0c\u7528\u65bc\u5075\u6e2c\x20\u03b3\x20\u5c04\u7dda\u3002\u5728\u91ab\u7642\u9020\u5f71\u4e2d\uff0c\u653e\u5c04\u6027\u540c\u4f4d\u7d20\x20\u9248\x2d\x32\x30\x31\x28\u00b2\u2070\u00b9\x54\x6c\x29\u88ab\u5ee3\u6cdb\u7528\u65bc\u300c\u9248\u5fc3\u808c\u9020\u5f71\u300d\uff0c\u5354\u52a9\u91ab\u5e2b\u8a55\u4f30\u5fc3\u81df\u8840\u6d41\u72c0\u6cc1\u8207\u5fc3\u808c\u5b58\u6d3b\u7387\u3002\u6b64\u5916\uff0c\u9248\u8207\u6c5e\u5f62\u6210\u7684\u5408\u91d1\x28\u542b\x20\x38\x2e\x35\x25\x20\u9248\x29\u5177\u6709\u6975\u4f4e\u7684\u51dd\u56fa\u9ede\x28\u7d04\x20\x2d\x36\x30\x20\u00b0\x43\x29\uff0c\u9069\u7528\u65bc\u6975\u5730\u63a2\u96aa\u8207\u592a\u7a7a\u63a2\u6e2c\u7684\u4f4e\u6eab\u6e2c\u91cf\u8a2d\u5099\u3002\x0a\x0a\u9248\u5c55\u73fe\u4e86\u67d0\u4e9b\u53cd\u76f4\u89ba\u7684\u7269\u7406\u8207\u5316\u5b78\u7279\u5fb5\u3002\u96d6\u7136\u5b83\u662f\u91cd\u91d1\u5c6c\uff0c\u4f46\u9248\u5728\u7a7a\u6c23\u4e2d\u6703\u8fc5\u901f\u751f\u6210\u6c27\u5316\u7269\u819c\uff0c\u96a8\u5f8c\u5728\u6f6e\u6fd5\u74b0\u5883\u4e2d\u9032\u4e00\u6b65\u8f49\u5316\u70ba\u6c2b\u6c27\u5316\u9248\x28\x54\x6c\x4f\x48\x29\uff0c\u9019\u662f\u4e00\u7a2e\u80fd\u6eb6\u65bc\u6c34\u7684\u5f37\u9e7c\uff0c\u5176\u6027\u8cea\u8207\u6c2b\u6c27\u5316\u9240\u9ad8\u5ea6\u4e00\u81f4\u3002\u6b64\u5916\uff0c\u9248\u5728\u5ba4\u6eab\u4e0b\u5177\u5099\u6975\u4f73\u7684\u5ef6\u5c55\u6027\uff0c\u53ef\u4ee5\u7528\u666e\u901a\u5200\u5177\u5207\u958b\u4e26\u5c55\u73fe\u9280\u5149\uff0c\u4f46\u6703\u8fc5\u901f\u8f49\u70ba\u7070\u9ed1\u8272\u3002\u9019\u7a2e\u5f9e\u7f8e\u9e97\u7684\u7da0\u8272\u8b5c\u7dda\u5230\u80cc\u8ca0\u60e1\u540d\u7684\u5287\u6bd2\u53f2\uff0c\u518d\u5230\u5c16\u7aef\u91ab\u5b78\u5f71\u50cf\u7684\u6838\u5fc3\uff0c\u7cbe\u78ba\u8a6e\u91cb\u4e86\u9248\u5728\u9031\u671f\u8868\u4e2d\u65e2\u96b1\u5bc6\u53c8\u5f37\u6548\u7684\u5316\u5b78\u7279\u6027\u3002",
  "\x50\x62":
    "\u925b\x28\x4c\x65\x61\x64\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x50\x62\uff0c\u539f\u5b50\u5e8f\x20\x38\x32\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u516d\u9031\u671f\u3001\u7b2c\x20\x31\x34\x20\u65cf\x28\u78b3\u65cf\u5143\u7d20\uff0c\x70\x20\u5340\u584a\x29\u3002\u5176\u7b26\u865f\x20\x50\x62\x20\u6e90\u81ea\u62c9\u4e01\u8a9e\u300c\x50\x6c\x75\x6d\x62\x75\x6d\u300d\uff0c\u610f\u6307\u300c\u6c89\u91cd\u7684\u7269\u8cea\u300d\u3002\u925b\u662f\u4eba\u985e\u6700\u65e9\u4f7f\u7528\u7684\u91d1\u5c6c\u4e4b\u4e00\uff0c\u56e0\u5176\u4f4e\u7194\u9ede\x28\x33\x32\x37\x2e\x35\x20\u00b0\x43\x29\u8207\u6975\u4f73\u7684\u52a0\u5de5\u6027\uff0c\u81ea\u53e4\u7f85\u99ac\u6642\u671f\u5373\u88ab\u7528\u65bc\u6c34\u7ba1\u8207\u5668\u76bf\u3002\u925b\u5728\u81ea\u7136\u754c\u4e3b\u8981\u4ee5\u65b9\u925b\u7926\x28\x50\x62\x53\x29\u5f62\u5f0f\u5b58\u5728\u3002\u96d6\u7136\u5b83\u662f\u73fe\u4ee3\u6587\u660e\u4e2d\u4e0d\u53ef\u6216\u7f3a\u7684\u9632\u8b77\u8207\u5132\u80fd\u6750\u6599\uff0c\u4f46\u7531\u65bc\u925b\u5c0d\u4eba\u9ad4\u795e\u7d93\u7cfb\u7d71\u8207\u9020\u8840\u529f\u80fd\u5177\u5099\u986f\u8457\u7684\u6bd2\u6027\uff0c\u5176\u74b0\u5883\u66b4\u9732\u8b70\u984c\u4e00\u76f4\u662f\u516c\u5171\u885b\u751f\u7814\u7a76\u7684\u91cd\u9ede\u3002\x0a\x0a\u925b\u7684\u96fb\u5b50\u7d44\u614b\u70ba\x20\x5b\x58\x65\x5d\x34\x66\u00b9\u2074\x35\x64\u00b9\u2070\x36\x73\u00b2\x36\x70\u00b2\u3002\u8207\u540c\u65cf\u7684\u78b3\u3001\u77fd\u4e0d\u540c\uff0c\u53d7\u300c\u920d\u6027\u96fb\u5b50\u5c0d\u6548\u61c9\u300d\u5f71\u97ff\uff0c\u925b\u5728\u5316\u5408\u7269\u4e2d\u4e3b\u8981\u5448\u73fe\x20\x2b\x32\x20\u6c27\u5316\u614b\uff0c\u800c\x20\x2b\x34\x20\u614b\x28\u5982\x20\x50\x62\x4f\u2082\x29\u5247\u5177\u5099\u6975\u5f37\u7684\u6c27\u5316\u6027\u3002\u5728\u9ad8\u4e2d\u5316\u5b78\u63a2\u8a0e\u96fb\u5316\u5b78\u8207\u6c89\u6fb1\u5206\u6790\u6642\uff0c\u925b\u662f\u6975\u4f73\u7684\u7d20\u6750\uff1a\u5b83\u8207\u7898\u96e2\u5b50\u53cd\u61c9\u751f\u6210\u91d1\u9ec3\u8272\u9583\u8000\u7684\u7898\u5316\u925b\x28\x50\x62\x49\u2082\x29\u6c89\u6fb1\uff0c\u662f\u8457\u540d\u7684\u300c\u91d1\u96e8\u5be6\u9a57\u300d\u4e3b\u89d2\u3002\u6b64\u5916\uff0c\u925b\u5728\u63a5\u89f8\u7a7a\u6c23\u8207\u7279\u5b9a\u9178\u6db2\u6642\u6703\u7522\u751f\u300c\u920d\u5316\u73fe\u8c61\u300d\x28\x50\x61\x73\x73\x69\x76\x61\x74\x69\x6f\x6e\x29\uff0c\u8868\u9762\u751f\u6210\u7684\u786b\u9178\u925b\u6216\u6c27\u5316\u925b\u8584\u819c\u80fd\u963b\u6b62\u5167\u5c64\u7e7c\u7e8c\u8150\u8755\uff0c\u9019\u89e3\u91cb\u4e86\u70ba\u4f55\u925b\u80fd\u4f5c\u70ba\u5316\u5b78\u5de5\u696d\u4e2d\u7684\u8010\u8755\u588a\u6599\u3002\x0a\x0a\u5728\u53f0\u7063\u9ad8\u4e2d\u8ab2\u7db1\u8207\u5de5\u696d\u61c9\u7528\u4e2d\uff0c\u925b\u9178\u96fb\u6c60\x28\x4c\x65\x61\x64\x2d\x61\x63\x69\x64\x20\x62\x61\x74\x74\x65\x72\x79\x29\u662f\u6700\u5177\u6307\u6a19\u6027\u7684\u6982\u5ff5\u3002\u5176\u653e\u96fb\u904e\u7a0b\u6d89\u53ca\u925b\x28\u8ca0\u6975\x29\u8207\u4e8c\u6c27\u5316\u925b\x28\u6b63\u6975\x29\u5411\u786b\u9178\u925b\u7684\u8f49\u5316\uff0c\u662f\u5316\u5b78\u80fd\u8207\u96fb\u80fd\u76f8\u4e92\u8f49\u63db\u7684\u7d93\u5178\u7bc4\u4f8b\u3002\u5728\u96fb\u78c1\u5b78\u9632\u8b77\u65b9\u9762\uff0c\u925b\u56e0\u5177\u5099\u6975\u9ad8\u7684\u539f\u5b50\u5e8f\u8207\u5bc6\u5ea6\x28\u7d04\x20\x31\x31\x2e\x33\x20\x67\x2f\x63\x6d\u00b3\x29\uff0c\u662f\u62b5\u79a6\x20\x58\x20\u5c04\u7dda\u8207\x20\u03b3\x20\u5c04\u7dda\u6700\u6709\u6548\u7684\u5ec9\u50f9\u5c4f\u853d\u6750\u6599\uff0c\u5ee3\u6cdb\u61c9\u7528\u65bc\u91ab\u7642\u653e\u5c04\u79d1\u8207\u6838\u80fd\u8a2d\u65bd\u3002\u6b64\u5916\uff0c\u5728\u5ea6\u91cf\u8861\u53f2\u4e0a\uff0c\u925b\u66fe\u88ab\u7528\u4f5c\u65e9\u671f\u7684\u7cbe\u5bc6\u8cea\u91cf\u6a19\u6e96\uff0c\u5c55\u73fe\u5176\u5bc6\u5ea6\u8207\u7a69\u5b9a\u6027\u7684\u5e73\u8861\u3002\x0a\x0a\u925b\u5728\u6838\u7269\u7406\u4e2d\u5177\u6709\u7368\u7279\u7684\u5730\u4f4d\uff0c\u5b83\u662f\u81ea\u7136\u754c\u4e2d\u4e09\u5927\u653e\u5c04\u6027\u8870\u8b8a\u7cfb\x28\u923e\u3001\u9312\u3001\u91f7\u7cfb\x29\u7684\u6700\u7d42\u7a69\u5b9a\u6b78\u5bbf\uff0c\u56e0\u6b64\u5730\u7403\u4e0a\u925b\u540c\u4f4d\u7d20\x28\u00b2\u2070\u2076\x50\x62\u3001\u00b2\u2070\u2077\x50\x62\u3001\u00b2\u2070\u2078\x50\x62\x29\u7684\u542b\u91cf\u6bd4\u4f8b\u5e38\u88ab\u7528\u65bc\u5730\u8cea\u5b9a\u5e74\u3002\u6709\u8da3\u7684\u662f\uff0c\u96d6\u7136\u925b\u5e38\u8207\u300c\u7b28\u91cd\u300d\u639b\u9264\uff0c\u4f46\u5176\u8207\u932b\u5f62\u6210\u7684\u300c\u710a\u932b\u300d\u537b\u5177\u5099\u6975\u4f73\u7684\u6d41\u52d5\u6027\uff0c\u66fe\u63a8\u52d5\u4e86\u5168\u7403\u96fb\u5b50\u5c01\u88dd\u7684\u767c\u5c55\u3002\u53cd\u76f4\u89ba\u7684\u662f\uff0c\u96d6\u7136\u925b\u5728\u6c34\u4e2d\u6703\u751f\u6210\u5287\u6bd2\u96e2\u5b50\uff0c\u4f46\u5b83\u5728\u542b\u6709\u78b3\u9178\u6839\u6216\u786b\u9178\u6839\u7684\u81ea\u4f86\u6c34\u4e2d\uff0c\u6703\u56e0\u5f62\u6210\u96e3\u6eb6\u6c89\u6fb1\u819c\u800c\u5177\u5099\u4e00\u5b9a\u7684\u4fdd\u8b77\u529b\u3002\u9019\u7a2e\u5f9e\u53e4\u7f85\u99ac\u6c34\u7ba1\u7684\u4fbf\u5229\u5230\u73fe\u4ee3\u6838\u9632\u8b77\u7246\u7684\u5b88\u885b\uff0c\u7cbe\u78ba\u8a6e\u91cb\u4e86\u925b\u5728\u9031\u671f\u8868\u4e2d\u6240\u626e\u6f14\u7684\u539a\u91cd\u89d2\u8272\u3002",
  "\x42\x69":
    "\u924d\x28\x42\x69\x73\x6d\x75\x74\x68\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x42\x69\uff0c\u539f\u5b50\u5e8f\x20\x38\x33\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u516d\u9031\u671f\u3001\u7b2c\x20\x31\x35\x20\u65cf\x28\u6c2e\u65cf\u5143\u7d20\uff0c\x70\x20\u5340\u584a\x29\u3002\u5176\u540d\u7a31\u6e90\u65bc\u5fb7\u8a9e\u300c\x57\x69\x73\x6d\x75\x74\u300d\uff0c\u610f\u70ba\u300c\u767d\u8272\u7684\u7269\u8cea\u300d\u3002\u81ea\u53e4\u4fbf\u8207\u925b\u3001\u932b\u6df7\u6dc6\uff0c\u76f4\u5230\x20\x31\x37\x35\x33\x20\u5e74\u624d\u7531\u6cd5\u570b\u5316\u5b78\u5bb6\u82e5\u5f17\u9b6f\u74e6\x28\x43\x6c\x61\x75\x64\x65\x20\x46\x72\x61\x6e\u00e7\x6f\x69\x73\x20\x47\x65\x6f\x66\x66\x72\x6f\x79\x29\u8b49\u5be6\u70ba\u7368\u7acb\u5143\u7d20\u3002\u924d\u662f\u9577\u4e45\u4ee5\u4f86\u88ab\u8a8d\u70ba\u662f\u6700\u91cd\u7684\u7a69\u5b9a\u5143\u7d20\uff0c\u96d6\u65bc\x20\x32\x30\x30\x33\x20\u5e74\u8b49\u5be6\u5176\u552f\u4e00\u5929\u7136\u540c\u4f4d\u7d20\x20\u00b2\u2070\u2079\x42\x69\x20\u5177\u6709\u6975\u5fae\u5f31\u7684\u653e\u5c04\u6027\x28\u534a\u8870\u671f\u7d04\u70ba\u5b87\u5b99\u5e74\u9f61\u7684\u5341\u5104\u500d\x29\uff0c\u4f46\u5728\u5316\u5b78\u5be6\u52d9\u4e2d\u4ecd\u8996\u70ba\u7a69\u5b9a\u5b58\u5728\u3002\u5b83\u5177\u5099\u9280\u767d\u8272\u5e36\u7c89\u7d05\u7684\u5149\u6fa4\uff0c\u662f\u91cd\u91d1\u5c6c\u4e2d\u6975\u5c11\u6578\u5c0d\u751f\u7269\u5e7e\u4e4e\u7121\u6bd2\u7684\u6210\u54e1\u3002\x0a\x0a\u5728\u5316\u5b78\u6027\u8cea\u4e0a\uff0c\u924d\u7684\u96fb\u5b50\u7d44\u614b\u70ba\x20\x5b\x58\x65\x5d\x34\x66\u00b9\u2074\x35\x64\u00b9\u2070\x36\x73\u00b2\x36\x70\u00b3\u3002\u53d7\u300c\u920d\u6027\u96fb\u5b50\u5c0d\u6548\u61c9\u300d\u5f71\u97ff\uff0c\u5176\x20\x36\x73\u00b2\x20\u96fb\u5b50\u5c0d\u6975\u5ea6\u8da8\u65bc\u7a69\u5b9a\uff0c\u5c0e\u81f4\u924d\u5728\u5316\u5408\u7269\u4e2d\u4ee5\x20\x2b\x33\x20\u6c27\u5316\u614b\u6700\u70ba\u5e38\u898b\u4e14\u7a69\u5b9a\uff0c\u800c\x20\x2b\x35\x20\u6c27\u5316\u614b\u5247\u5177\u5099\u6975\u5f37\u7684\u6c27\u5316\u6027\x28\u5982\u924d\u9178\u9209\x20\x4e\x61\x42\x69\x4f\u2083\x29\u3002\u924d\u7684\u96fb\u8ca0\u5ea6\x28\u7d04\x20\x32\x2e\x30\x32\x29\u5c55\u73fe\u51fa\u660e\u986f\u7684\u91d1\u5c6c\u6027\u50be\u5411\uff0c\u5176\u6c27\u5316\u7269\x20\x42\x69\u2082\x4f\u2083\x20\u5177\u5099\u9e7c\u6027\u3002\u5728\u9ad8\u4e2d\u5316\u5b78\u63a2\u8a0e\u65cf\u7fa4\u8da8\u52e2\u6642\uff0c\u924d\u662f\u8aaa\u660e\u300c\u91d1\u5c6c\u6027\u96a8\u539f\u5b50\u5e8f\u905e\u589e\u800c\u589e\u5f37\u300d\u7684\u6700\u4f73\u5be6\u4f8b\uff0c\u5176\u5c0e\u96fb\u6027\u96d6\u905c\u65bc\u771f\u91d1\u5c6c\uff0c\u4f46\u9060\u512a\u65bc\u6c2e\u65cf\u4e0a\u65b9\u7684\u975e\u91d1\u5c6c\u6210\u54e1\u3002\x0a\x0a\u5728\u73fe\u4ee3\u61c9\u7528\u8207\u91ab\u5b78\u9818\u57df\uff0c\u924d\u56e0\u5176\u4f4e\u6bd2\u6027\u800c\u6210\u70ba\u925b\u7684\u7406\u60f3\u66ff\u4ee3\u54c1\u3002\u924d\u7684\u9e7d\u985e\x28\u5982\u6b21\u6c34\u694a\u9178\u924d\x29\u88ab\u5ee3\u6cdb\u7528\u65bc\u6cbb\u7642\u80c3\u8178\u75be\u75c5\uff0c\u80fd\u6709\u6548\u6291\u5236\u5e7d\u9580\u87ba\u687f\u83cc\u3002\u5728\u6750\u6599\u79d1\u5b78\u4e2d\uff0c\u924d\u6700\u986f\u8457\u7684\u8ca2\u737b\u5728\u65bc\u88fd\u9020\u4f4e\u7194\u9ede\u5408\u91d1\x28\u5982\u4f0d\u5fb7\u5408\u91d1\x29\uff0c\u5ee3\u6cdb\u61c9\u7528\u65bc\u81ea\u52d5\u6ec5\u706b\u7cfb\u7d71\u7684\u71b1\u611f\u89f8\u767c\u88dd\u7f6e\u3002\u6b64\u5916\uff0c\u924d\u5728\u51b6\u91d1\u5de5\u696d\u4e2d\u5e38\u88ab\u52a0\u5165\u92fc\u9435\u6216\u92c1\u4e2d\u4ee5\u6539\u5584\u52a0\u5de5\u6548\u80fd\u3002\u5728\u5149\u96fb\u7814\u7a76\u65b9\u9762\uff0c\u924d\u7cfb\u8d85\u5c0e\u9ad4\x28\x42\x53\x43\x43\x4f\x29\u662f\u9ad8\u6eab\u8d85\u5c0e\u6750\u6599\u7684\u91cd\u8981\u5206\u652f\uff0c\u80fd\u65bc\u6db2\u6c2e\u6eab\u5ea6\u4e0b\u5c55\u73fe\u96f6\u96fb\u963b\u7279\u6027\uff0c\u5927\u5e45\u964d\u4f4e\u8d85\u5c0e\u6280\u8853\u7684\u61c9\u7528\u9580\u6abb\u3002\x0a\x0a\u924d\u5c55\u73fe\u4e86\u67d0\u4e9b\u9a5a\u4eba\u7684\u7269\u7406\u7269\u7406\u6975\u9650\u7279\u5fb5\u3002\u5b83\u662f\u6240\u6709\u91d1\u5c6c\u4e2d\u300c\u9006\u78c1\u6027\u300d\x28\x44\x69\x61\x6d\x61\x67\x6e\x65\x74\x69\x73\x6d\x29\u6700\u5f37\u7684\u5143\u7d20\uff0c\u80fd\u8207\u5f37\u78c1\u5834\u7522\u751f\u6392\u65a5\u529b\u3002\u53cd\u76f4\u89ba\u7684\u662f\uff0c\u924d\u8207\u6c34\u3001\u92bb\u76f8\u4f3c\uff0c\u5728\u51dd\u56fa\u6210\u56fa\u9ad4\u6642\u9ad4\u7a4d\u6703\u767c\u751f\u81a8\u8139\x28\u7d04\x20\x33\x2e\x33\x25\x29\uff0c\u9019\u4f7f\u5176\u5408\u91d1\u5728\u9444\u9020\u7cbe\u5bc6\u96f6\u4ef6\u6642\u80fd\u5b8c\u7f8e\u586b\u5145\u6a21\u5177\u908a\u7de3\u3002\u6b64\u5916\uff0c\u924d\u7684\u4eba\u9020\u6676\u9ad4\u5728\u51b7\u537b\u904e\u7a0b\u4e2d\u6703\u5f62\u6210\u5c64\u758a\u905e\u9032\u7684\u300c\u968e\u68af\u72c0\u300d\u5e7e\u4f55\u7d50\u69cb\uff0c\u4e26\u56e0\u8868\u9762\u6c27\u5316\u819c\u7522\u751f\u7f8e\u9e97\u7684\u8584\u819c\u5e72\u6d89\u8679\u5f69\u3002\u9019\u7a2e\u5f9e\u85e5\u6ac3\u4e2d\u7684\u8b77\u80c3\u826f\u85e5\u5230\u5be6\u9a57\u5ba4\u4e2d\u5b9a\u7fa9\u7269\u7406\u6297\u78c1\u6975\u9650\u7684\u7269\u8cea\uff0c\u7cbe\u78ba\u8a6e\u91cb\u4e86\u924d\u5728\u9031\u671f\u8868\u672b\u7aef\u6c89\u7a69\u4e14\u6eab\u548c\u7684\u7279\u8cea\u3002",
  "\x50\x6f":
    "\u91d9\x28\x50\x6f\x6c\x6f\x6e\x69\x75\x6d\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x50\x6f\uff0c\u539f\u5b50\u5e8f\x20\x38\x34\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u516d\u9031\u671f\u3001\u7b2c\x20\x31\x36\x20\u65cf\x28\u6c27\u65cf\u5143\u7d20\uff0c\x70\x20\u5340\u584a\x29\u3002\x31\x38\x39\x38\x20\u5e74\u7531\u5c45\u79ae\u592b\u5a66\x28\x4d\x61\x72\x69\x65\x20\x61\x6e\x64\x20\x50\x69\x65\x72\x72\x65\x20\x43\x75\x72\x69\x65\x29\u5728\u8655\u7406\u701d\u9752\u923e\u7926\u6642\u767c\u73fe\uff0c\u4e26\u4ee5\u746a\u9e97\u00b7\u5c45\u79ae\u7684\u7956\u570b\u6ce2\u862d\x28\x50\x6f\x6c\x61\x6e\x64\x29\u547d\u540d\u3002\u91d9\u662f\u9031\u671f\u8868\u4e2d\u7b2c\u4e00\u500b\u88ab\u767c\u73fe\u7684\u5f37\u653e\u5c04\u6027\u5143\u7d20\uff0c\u5730\u6bbc\u4e2d\u50c5\u4ee5\u923e\u8870\u8b8a\u93c8\u4e2d\u9593\u7522\u7269\u7684\u5f62\u5f0f\u5fae\u91cf\u5b58\u5728\u3002\u5b83\u662f\u4e00\u7a2e\u9280\u7070\u8272\u7684\u91d1\u5c6c\uff0c\u7531\u65bc\u5176\u80fd\u91cf\u5bc6\u5ea6\u6975\u9ad8\u4e14\u5177\u5099\u5f37\u70c8\u7684\x20\u03b1\x20\u8f3b\u5c04\uff0c\u5728\u73fe\u4ee3\u5c16\u7aef\u822a\u592a\u8207\u539f\u5b50\u7269\u7406\u4e2d\u626e\u6f14\u8457\u5371\u96aa\u537b\u95dc\u9375\u7684\u89d2\u8272\u3002\x0a\x0a\u5728\u5316\u5b78\u884c\u70ba\u4e0a\uff0c\u91d9\u7684\u96fb\u5b50\u7d44\u614b\u70ba\x20\x5b\x58\x65\x5d\x34\x66\u00b9\u2074\x35\x64\u00b9\u2070\x36\x73\u00b2\x36\x70\u2074\uff0c\u6027\u8cea\u4ecb\u65bc\u985e\u91d1\u5c6c\u78b2\u8207\u91d1\u5c6c\u925b\u4e4b\u9593\u3002\u91d9\u7684\u6c27\u5316\u614b\u5206\u5e03\u7531\x20\x2d\x32\x20\u5230\x20\x2b\x36\uff0c\u5176\u4e2d\x20\x2b\x34\x20\u50f9\u6700\u70ba\u7a69\u5b9a\u3002\u5728\u9ad8\u4e2d\u5316\u5b78\u95dc\u65bc\u6676\u9ad4\u7d50\u69cb\u7684\u8a0e\u8ad6\u4e2d\uff0c\u91d9\u5177\u6709\u7368\u4e00\u7121\u4e8c\u7684\u79d1\u5b78\u5730\u4f4d\uff1a\u5b83\u662f\u81ea\u7136\u754c\u4e2d\u552f\u4e00\u5728\u5e38\u6eab\u4e0b\u5448\u73fe\u300c\u7c21\u55ae\u7acb\u65b9\u300d\x28\x53\x69\x6d\x70\x6c\x65\x20\x43\x75\x62\x69\x63\x29\u6676\u683c\u7d50\u69cb\u7684\u5143\u7d20\uff0c\u5176\u7a7a\u9593\u5229\u7528\u7387\u6975\u4f4e\uff0c\u9019\u53cd\u6620\u4e86\u5176\u539f\u5b50\u6838\u8207\u96fb\u5b50\u6392\u5e03\u5728\u5f37\u653e\u5c04\u6027\u5e72\u64fe\u4e0b\u7684\u7279\u6b8a\u5e73\u8861\u72c0\u614b\u3002\u7531\u65bc\u91d9\u6703\u6301\u7e8c\u91cb\u653e\x20\u03b1\x20\u7c92\u5b50\uff0c\u5176\u91d1\u5c6c\u8868\u9762\u6703\u56e0\u96fb\u96e2\u5468\u570d\u7a7a\u6c23\u800c\u7522\u751f\u5fae\u5f31\u7684\u85cd\u8272\u5e7d\u5149\u3002\x0a\x0a\u91d9\u5728\u6975\u7aef\u74b0\u5883\u4e0b\u7684\u71b1\u529b\u5b78\u6027\u8cea\u4f7f\u5176\u6210\u70ba\u7406\u60f3\u7684\u300c\u6838\u80fd\u71b1\u6e90\u300d\u3002\u6bcf\u514b\u91d9\x2d\x32\x31\x30\x20\u5728\u8870\u8b8a\u6642\u80fd\u7522\u751f\u7d04\x20\x31\x34\x30\x20\u74e6\u7684\u71b1\u529f\u7387\uff0c\u9019\u4f7f\u5176\u88ab\u88fd\u6210\u300c\u653e\u5c04\u6027\u540c\u4f4d\u7d20\u71b1\u96fb\u6a5f\u300d\x28\x52\x54\x47\x29\u7684\u7d44\u4ef6\uff0c\u70ba\u65e9\u671f\u885b\u661f\u8207\u6708\u7403\u63a2\u6e2c\u5668\u63d0\u4f9b\u7a69\u5b9a\u7684\u96fb\u529b\u4f86\u6e90\u3002\u6b64\u5916\uff0c\u91d9\u4ea6\u88ab\u7528\u65bc\u975c\u96fb\u6d88\u9664\u5668\u4e2d\uff0c\u5229\u7528\u5176\u5f37\u5927\u7684\u96fb\u96e2\u80fd\u529b\u4e2d\u548c\u7cbe\u5bc6\u6a5f\u68b0\x28\u5982\u81a0\u6372\u751f\u7522\u6216\u9020\u7d19\x29\u7522\u751f\u7684\u975c\u96fb\u7d2f\u7a4d\u3002\u5728\u6838\u7269\u7406\u7814\u7a76\u4e2d\uff0c\u91d9\u8207\u9239\u7d50\u5408\u53ef\u88fd\u6210\u4e2d\u5b50\u6e90\uff0c\u7528\u65bc\u555f\u52d5\u6838\u53cd\u61c9\u6216\u9032\u884c\u4e2d\u5b50\u6d3b\u5316\u5206\u6790\u3002\x0a\x0a\u91d9\u5177\u5099\u9a5a\u4eba\u7684\u751f\u7269\u6bd2\u6027\u8207\u7269\u7406\u6d3b\u6027\u3002\u5176\u653e\u5c04\u6027\u6bd2\u6027\u6bd4\u6c30\u5316\u6c2b\u9ad8\u51fa\u6578\u5104\u500d\uff0c\u6975\u5fae\u91cf\u5438\u5165\u5373\u53ef\u5c0e\u81f4\u6025\u6027\u5668\u5b98\u8870\u7aed\u8207\u9aa8\u9ad3\u640d\u50b7\u3002\u6709\u8da3\u7684\u662f\uff0c\u96d6\u7136\u91d9\u5728\u74b0\u5883\u4e2d\u6975\u5176\u7a00\u5c11\uff0c\u4f46\u7531\u65bc\u5176\u63ee\u767c\u6027\uff0c\u5b83\u6703\u7a4d\u805a\u5728\u83f8\u8349\u8449\u7247\u7684\u5fae\u6bdb\u7d50\u69cb\u4e2d\uff0c\u6210\u70ba\u5438\u83f8\u5c0e\u81f4\u9577\u671f\u8f3b\u5c04\u50b7\u5bb3\u7684\u96b1\u5f62\u6210\u5206\u3002\u7269\u7406\u4e0a\uff0c\u91d9\u7684\u71b1\u6548\u61c9\u6975\u5f37\uff0c\u82e5\u7d14\u5ea6\u8f03\u9ad8\uff0c\u5176\u81ea\u8eab\u6eab\u5ea6\u53ef\u5347\u81f3\x20\x35\x30\x20\u00b0\x43\x20\u4ee5\u4e0a\u3002\u9019\u7a2e\u5f9e\u5c45\u79ae\u5be6\u9a57\u5ba4\u4e2d\u7684\u5283\u6642\u4ee3\u767c\u73fe\u5230\u5b88\u8b77\u592a\u7a7a\u6df1\u8655\u63a2\u6e2c\u5668\u52d5\u529b\u7684\u8f49\u8b8a\uff0c\u7cbe\u78ba\u8a6e\u91cb\u4e86\u91d9\u5728\u6c27\u65cf\u5143\u7d20\u672b\u7aef\u4f5c\u70ba\u300c\u9ad8\u80fd\u653e\u5c04\u6027\u91d1\u5c6c\u300d\u7684\u51b7\u5cfb\u5730\u4f4d\u3002",
  "\x41\x74":
    "\u7808\x28\x41\x73\x74\x61\x74\x69\x6e\x65\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x41\x74\uff0c\u539f\u5b50\u5e8f\x20\x38\x35\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u516d\u9031\u671f\u3001\u7b2c\x20\x31\x37\x20\u65cf\x28\u9e75\u7d20\uff0c\x70\x20\u5340\u584a\x29\u3002\u5176\u540d\u7a31\u6e90\u65bc\u5e0c\u81d8\u8a9e\u300c\x61\x73\x74\x61\x74\x6f\x73\u300d\uff0c\u610f\u70ba\u300c\u4e0d\u7a69\u5b9a\u300d\u3002\x31\x38\x34\x30\x20\u5e74\u7531\u585e\u683c\u745e\x28\x45\x6d\x69\x6c\x69\x6f\x20\x53\x65\x67\x72\u00e8\x29\u7b49\u4eba\u5728\u8ff4\u65cb\u52a0\u901f\u5668\u4e2d\u900f\u904e\x20\u03b1\x20\u7c92\u5b50\u8f5f\u64ca\u924d\u9776\u9996\u6b21\u4eba\u5de5\u5408\u6210\u3002\u7808\u662f\u81ea\u7136\u754c\u4e2d\u6700\u7a00\u6709\u7684\u5929\u7136\u5143\u7d20\uff0c\u5168\u5730\u6bbc\u4e2d\u4efb\u4f55\u6642\u523b\u7684\u7e3d\u91cf\u4f30\u8a08\u4e0d\u5230\x20\x31\x20\u516c\u514b\u3002\u8eab\u70ba\u9e75\u7d20\u5bb6\u65cf\u4e2d\u539f\u5b50\u5e8f\u6700\u5927\u7684\u6210\u54e1\uff0c\u7808\u5c55\u73fe\u4e86\u5f37\u70c8\u7684\u653e\u5c04\u6027\u8207\u986f\u8457\u7684\u91d1\u5c6c\u5316\u5b78\u7279\u5fb5\uff0c\u662f\u73fe\u4ee3\u6a19\u9776\u653e\u5c04\u6cbb\u7642\u7814\u7a76\u4e2d\u6975\u5177\u6f5b\u529b\u7684\u300c\u5fae\u578b\u70b8\u5f48\u300d\u3002\x0a\x0a\u5728\u5316\u5b78\u898f\u5f8b\u4e2d\uff0c\u7808\u7684\u96fb\u5b50\u7d44\u614b\u70ba\x20\x5b\x58\x65\x5d\x34\x66\u00b9\u2074\x35\x64\u00b9\u2070\x36\x73\u00b2\x36\x70\u2075\u3002\u53d7\u76f8\u5c0d\u8ad6\u6548\u61c9\u5f71\u97ff\uff0c\u7808\u7684\u6027\u8cea\u504f\u96e2\u4e86\u5178\u578b\u7684\u975e\u91d1\u5c6c\u9e75\u7d20\u7279\u5fb5\uff0c\u8868\u73fe\u51fa\u660e\u986f\u7684\u91d1\u5c6c\u6027\u50be\u5411\uff0c\u5176\u96fb\u8ca0\u5ea6\x28\u7d04\x20\x32\x2e\x32\x29\u8207\u6c2b\u76f8\u4eff\u3002\u5728\u9ad8\u4e2d\u5316\u5b78\u63a2\u8a0e\u9e75\u7d20\u65cf\u7fa4\u8da8\u52e2\u6642\uff0c\u7808\u662f\u8aaa\u660e\u300c\u7269\u7406\u6027\u8cea\u7531\u975e\u91d1\u5c6c\u8f49\u8b8a\u70ba\u985e\u91d1\u5c6c\x2f\u91d1\u5c6c\u300d\u7684\u6975\u7aef\u4f8b\u8b49\u3002\u5b83\u5177\u5099\u6bd4\u7898\u66f4\u5f37\u7684\u9084\u539f\u6027\uff0c\u4e14\u80fd\u5f62\u6210\u7a69\u5b9a\u7684\u967d\u96e2\u5b50\x28\u5982\x20\x41\x74\u207a\x29\uff0c\u9019\u5728\u9e75\u7d20\u4e2d\u6975\u5176\u7f55\u898b\u3002\u5118\u7ba1\u7808\u6975\u4e0d\u7a69\u5b9a\uff0c\u5176\u591a\u7a2e\u6c27\u5316\u614b\x28\x2d\x31\u3001\x30\u3001\x2b\x31\u3001\x2b\x33\u3001\x2b\x35\u3001\x2b\x37\x29\u4ecd\u80fd\u900f\u904e\u5fae\u91cf\u5316\u5b78\u5be6\u9a57\u88ab\u5075\u6e2c\u5230\u3002\x0a\x0a\u73fe\u4ee3\u91ab\u5b78\u61c9\u7528\u662f\u7808\u76ee\u524d\u6700\u91cd\u8981\u7684\u7814\u7a76\u65b9\u5411\uff0c\u7279\u5225\u662f\u540c\u4f4d\u7d20\x20\u7808\x2d\x32\x31\x31\x28\u00b2\u00b9\u00b9\x41\x74\x29\u3002\u5b83\u80fd\u767c\u5c04\u9ad8\u80fd\u91cf\u3001\u77ed\u5c04\u7a0b\u7684\x20\u03b1\x20\u7c92\u5b50\uff0c\u82e5\u80fd\u900f\u904e\u55ae\u682a\u6297\u9ad4\u7cbe\u78ba\u5c0e\u5f15\u81f3\u764c\u7d30\u80de\uff0c\u5373\u53ef\u5728\u6975\u5c0f\u7bc4\u570d\u5167\u7522\u751f\u5de8\u5927\u7684\u7834\u58de\u529b\uff0c\u540c\u6642\u907f\u514d\u640d\u50b7\u5468\u570d\u5065\u5eb7\u7d44\u7e54\uff0c\u9019\u7a2e\u6280\u8853\u7a31\u70ba\u300c\u6a19\u9776\x20\u03b1\x20\u7c92\u5b50\u7642\u6cd5\u300d\x28\x54\x41\x54\x29\u3002\u7531\u65bc\u7808\u7684\u534a\u8870\u671f\u50c5\u7d04\x20\x37\x2e\x32\x20\u5c0f\u6642\uff0c\u9019\u4f7f\u5176\u5728\u9ad4\u5167\u65e2\u80fd\u5b8c\u6210\u6cbb\u7642\u53c8\u4e0d\u6703\u9020\u6210\u9577\u671f\u7684\u653e\u5c04\u6027\u6b98\u7559\u3002\u5728\u5206\u6790\u5316\u5b78\u4e2d\uff0c\u7808\u7684\u5f37\u6613\u63ee\u767c\u6027\u8207\u6607\u83ef\u7279\u6027\uff0c\u4f7f\u5176\u5728\u5206\u96e2\u88fd\u7a0b\u4e2d\u8207\u5176\u540c\u65cf\u5144\u9577\u7898\u8868\u73fe\u51fa\u76f8\u4f3c\u7684\u52d5\u529b\u5b78\u884c\u70ba\u3002\x0a\x0a\u95dc\u65bc\u7808\u7684\u6975\u9650\u73fe\u8c61\uff0c\u7531\u65bc\u5176\u9ad8\u5ea6\u7684\u653e\u5c04\u71b1\u80fd\uff0c\u7d14\u7808\u6a23\u672c\u6703\u56e0\u70ba\u81ea\u8eab\u71b1\u91cf\u800c\u8fc5\u901f\u6c7d\u5316\uff0c\u56e0\u6b64\u6975\u96e3\u89c0\u6e2c\u5230\u5b8f\u89c0\u7684\u91d1\u5c6c\u72c0\u614b\u3002\u79d1\u5b78\u5bb6\u9810\u6e2c\uff0c\u82e5\u80fd\u805a\u96c6\u8db3\u5920\u6578\u91cf\u7684\u7808\u539f\u5b50\uff0c\u5176\u5916\u89c0\u61c9\u5177\u5099\u6df1\u8272\u7684\u91d1\u5c6c\u5149\u6fa4\u3002\u6709\u8da3\u7684\u662f\uff0c\u96d6\u7136\u7808\u662f\u5929\u7136\u5b58\u5728\u7684\uff0c\u4f46\u5b83\u50c5\u5b58\u5728\u65bc\u923e\u8207\u91f7\u7684\u5feb\u901f\u8870\u8b8a\u93c8\u4e2d\uff0c\u96a8\u751f\u96a8\u6ec5\u3002\u9019\u7a2e\u5f9e\u5730\u6bbc\u4e2d\u7684\u5b64\u9ad8\u5b58\u5728\u5230\u5728\u73fe\u4ee3\u91ab\u5b78\u4e2d\u7cbe\u78ba\u72d9\u64ca\u764c\u7d30\u80de\u7684\u6280\u8853\u8f49\u8b8a\uff0c\u7cbe\u78ba\u8a6e\u91cb\u4e86\u7808\u5728\u9031\u671f\u8868\u9e75\u7d20\u672b\u7aef\u4f5c\u70ba\u300c\u8f49\u77ac\u5373\u901d\u7684\u80fd\u91cf\u8f09\u9ad4\u300d\u4e4b\u8eab\u5206\u3002",
  "\x52\x6e":
    "\u6c21\x28\x52\x61\x64\x6f\x6e\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x52\x6e\uff0c\u539f\u5b50\u5e8f\x20\x38\x36\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u516d\u9031\u671f\u3001\u7b2c\x20\x31\x38\x20\u65cf\x28\u7a00\u6709\u6c23\u9ad4\uff0c\x70\x20\u5340\u584a\x29\u3002\u5176\u540d\u7a31\u6e90\u65bc\u300c\x72\x61\x64\x69\x75\x6d\u300d\x28\u9433\x29\uff0c\u56e0\u5176\u6700\u65e9\u88ab\u767c\u73fe\u662f\u5f9e\u9433\u9e7d\u4e2d\u6563\u767c\u51fa\u7684\u653e\u5c04\u6027\u6c23\u9ad4\u3002\x31\x39\x30\x30\x20\u5e74\u7531\u5fb7\u570b\u7269\u7406\u5b78\u5bb6\u591a\u6069\x28\x46\x72\x69\x65\x64\x72\x69\x63\x68\x20\x44\x6f\x72\x6e\x29\u8b49\u5be6\u5176\u5b58\u5728\u3002\u6c21\u662f\u9031\u671f\u8868\u4e2d\u552f\u4e00\u7684\u653e\u5c04\u6027\u7a00\u6709\u6c23\u9ad4\uff0c\u4e5f\u662f\u81ea\u7136\u754c\u4e2d\u5bc6\u5ea6\u6700\u5927\u7684\u6c23\u9ad4\u4e4b\u4e00\x28\u7d04\u70ba\u7a7a\u6c23\u7684\x20\x37\x2e\x35\x20\u500d\x29\u3002\u5b83\u7121\u8272\u3001\u7121\u5473\u3001\u7121\u81ed\uff0c\u96b1\u8eab\u65bc\u5ca9\u77f3\u8207\u571f\u58e4\u7684\u7e2b\u9699\u4e2d\uff0c\u662f\u5730\u8cea\u63a2\u52d8\u8207\u74b0\u5883\u5065\u5eb7\u79d1\u5b78\u4e2d\u4e0d\u53ef\u5ffd\u8996\u7684\u6307\u6a19\u6027\u5143\u7d20\u3002\x0a\x0a\u5728\u5fae\u89c0\u7d50\u69cb\u4e0a\uff0c\u6c21\u7684\u96fb\u5b50\u7d44\u614b\u70ba\x20\x5b\x58\x65\x5d\x34\x66\u00b9\u2074\x35\x64\u00b9\u2070\x36\x73\u00b2\x36\x70\u2076\uff0c\u64c1\u6709\u7a69\u5b9a\u7684\u516b\u9685\u9ad4\u7d44\u614b\u3002\u5118\u7ba1\u5b83\u662f\u7a00\u6709\u6c23\u9ad4\uff0c\u4f46\u7531\u65bc\u5176\u539f\u5b50\u534a\u5f91\u6975\u5927\uff0c\u5916\u5c64\u96fb\u5b50\u53d7\u5230\u539f\u5b50\u6838\u7684\u675f\u7e1b\u529b\u76f8\u5c0d\u8f03\u5f31\uff0c\u5c0e\u81f4\u6c21\u5177\u6709\u6bd4\u6c19\u66f4\u9ad8\u7684\u6975\u5316\u7387\uff0c\u7406\u8ad6\u4e0a\u5176\u53cd\u61c9\u6d3b\u6027\u662f\u7a00\u6709\u6c23\u9ad4\u4e2d\u8f03\u5f37\u7684\x28\u4f8b\u5982\u80fd\u8207\u6c1f\u53cd\u61c9\u751f\u6210\u4e8c\u6c1f\u5316\u6c21\x20\x52\x6e\x46\u2082\x29\u3002\u5728\u9ad8\u4e2d\u5316\u5b78\u63a2\u8a0e\u5206\u5b50\u9593\u4f5c\u7528\u529b\u6642\uff0c\u6c21\u7684\u9ad8\u539f\u5b50\u91cf\u8207\u5f37\u5206\u6563\u529b\u4f7f\u5176\u5177\u5099\u8f03\u9ad8\u7684\u6cb8\u9ede\x28\u7d04\x20\x2d\x36\x31\x2e\x37\x20\u00b0\x43\x29\uff0c\u9019\u53cd\u6620\u4e86\u539f\u5b50\u5e8f\u589e\u52a0\u5c0d\u7a00\u6709\u6c23\u9ad4\u7269\u7406\u6027\u8cea\u7684\u7cfb\u7d71\u6027\u5f71\u97ff\u3002\u6c21\u6613\u6eb6\u65bc\u6c34\u53ca\u6709\u6a5f\u6eb6\u5291\uff0c\u9019\u4f7f\u5176\u80fd\u96a8\u5730\u4e0b\u6c34\u8207\u571f\u58e4\u7a7a\u6c23\u9032\u884c\u5927\u7bc4\u570d\u9077\u79fb\u3002\x0a\x0a\u6c21\u5728\u73fe\u4ee3\u61c9\u7528\u4e2d\u5177\u6709\u96d9\u91cd\u7684\u793e\u6703\u610f\u7fa9\u3002\u5728\u5730\u7403\u79d1\u5b78\u9818\u57df\uff0c\u7531\u65bc\u6c21\u7684\u7522\u91cf\u8207\u5730\u6bbc\u6d3b\u52d5\u5bc6\u5207\u76f8\u95dc\uff0c\u5730\u8868\u8207\u5730\u4e0b\u6c34\u4e2d\u6c21\u6fc3\u5ea6\u7684\u7570\u5e38\u8b8a\u52d5\uff0c\u5e38\u88ab\u79d1\u5b78\u5bb6\u4f5c\u70ba\u5730\u9707\u9810\u5831\u8207\u65b7\u5c64\u6383\u63cf\u7684\u53c3\u8003\u6307\u6a19\u3002\u7136\u800c\uff0c\u5728\u516c\u5171\u885b\u751f\u9818\u57df\uff0c\u6c21\u662f\u5ba4\u5167\u7a7a\u6c23\u6c61\u67d3\u7684\u91cd\u8981\u4f86\u6e90\u3002\u5b83\u6703\u7531\u571f\u58e4\u64f4\u6563\u81f3\u5efa\u7bc9\u7269\u5e95\u90e8\x28\u7279\u5225\u662f\u5730\u4e0b\u5ba4\x29\uff0c\u5176\u8870\u8b8a\u7522\u7269\x28\u6c21\u5b50\u6838\x29\u6703\u9644\u8457\u5728\u7c89\u5875\u4e0a\u4e26\u88ab\u5438\u5165\u80ba\u90e8\uff0c\u91cb\u653e\x20\u03b1\x20\u7c92\u5b50\u640d\u50b7\u7d44\u7e54\uff0c\u662f\u50c5\u6b21\u65bc\u5438\u83f8\u7684\u7b2c\u4e8c\u5927\u80ba\u764c\u8a98\u56e0\u3002\u76ee\u524d\u74b0\u5883\u5de5\u7a0b\u5df2\u958b\u767c\u51fa\u5c08\u9580\u7684\u6392\u6c21\u7cfb\u7d71\uff0c\u900f\u904e\u58d3\u529b\u5e73\u8861\u6280\u8853\u964d\u4f4e\u5ba4\u5167\u6c21\u6c23\u6fc3\u5ea6\u3002\x0a\x0a\u6c21\u5728\u7269\u7406\u73fe\u8c61\u4e0a\u5c55\u73fe\u4e86\u6975\u9ad8\u7684\u80fd\u7d1a\u5bc6\u5ea6\u3002\u7576\u6c21\u51b7\u537b\u81f3\u51dd\u56fa\u9ede\u4ee5\u4e0b\u6642\uff0c\u5176\u56fa\u614b\u6676\u9ad4\u6703\u56e0\u70ba\u5f37\u70c8\u7684\u653e\u5c04\u6027\u523a\u6fc0\u800c\u767c\u51fa\u8000\u773c\u7684\u78f7\u5149\uff0c\u96a8\u6eab\u5ea6\u964d\u4f4e\u5f9e\u9ec3\u8272\u8f49\u8b8a\u70ba\u6a59\u7d05\uff0c\u9019\u5728\u7a00\u6709\u6c23\u9ad4\u4e2d\u6975\u5177\u7279\u8272\u3002\u6709\u8da3\u7684\u662f\uff0c\u96d6\u7136\u6c21\u5177\u5099\u986f\u8457\u7684\u5065\u5eb7\u98a8\u96aa\uff0c\u4f46\u67d0\u4e9b\u6eab\u6cc9\x28\u6c21\u6cc9\x29\u56e0\u542b\u6709\u5fae\u91cf\u6c21\u800c\u5ba3\u7a31\u5177\u5099\u91ab\u7642\u529f\u80fd\x28\u5118\u7ba1\u79d1\u5b78\u754c\u5c0d\u5176\u7642\u6548\u4ecd\u6709\u722d\u8b70\x29\u3002\u9019\u7a2e\u5f9e\u5b9a\u7fa9\u7a00\u6709\u6c23\u9ad4\u5bb6\u65cf\u653e\u5c04\u6027\u908a\u754c\u5230\u5f71\u97ff\u5c45\u5bb6\u74b0\u5883\u5b89\u5168\u7684\u7279\u6027\uff0c\u7cbe\u78ba\u8a6e\u91cb\u4e86\u6c21\u5728\u9031\u671f\u8868\u672b\u7aef\u4f5c\u70ba\u300c\u96b1\u5f62\u7684\u653e\u5c04\u6027\u76e3\u6e2c\u8005\u300d\u4e4b\u8907\u96dc\u5b9a\u4f4d\u3002",
  "\x46\x72":
    "\u9345\x28\x46\x72\x61\x6e\x63\x69\x75\x6d\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x46\x72\uff0c\u539f\u5b50\u5e8f\x20\x38\x37\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u4e03\u9031\u671f\u3001\u7b2c\x20\x31\x20\u65cf\x28\u9e7c\u91d1\u5c6c\uff0c\x73\x20\u5340\u584a\x29\u3002\u5176\u540d\u7a31\u6e90\u65bc\u6cd5\u570b\x28\x46\x72\x61\x6e\x63\x65\x29\u3002\x31\x39\x33\x39\x20\u5e74\u7531\u5c45\u79ae\u5be6\u9a57\u5ba4\u7684\u4f69\u91cc\x28\x4d\x61\x72\x67\x75\x65\x72\x69\x74\x65\x20\x50\x65\x72\x65\x79\x29\u5728\u7814\u7a76\u9312\u7684\u8870\u8b8a\u7522\u7269\u6642\u767c\u73fe\uff0c\u662f\u81ea\u7136\u754c\u4e2d\u6700\u5f8c\u4e00\u500b\u5f9e\u5929\u7136\u7926\u77f3\u4e2d\u88ab\u8fa8\u8b58\u51fa\u7684\u5143\u7d20\u3002\u9345\u662f\u9e7c\u91d1\u5c6c\u5bb6\u65cf\u4e2d\u539f\u5b50\u91cf\u6700\u5927\u3001\u6d3b\u6027\u6700\u5f37\u4e14\u6700\u5177\u653e\u5c04\u6027\u7684\u6210\u54e1\uff0c\u7531\u65bc\u5176\u540c\u4f4d\u7d20\u534a\u8870\u671f\u6975\u77ed\x28\u6700\u9577\u50c5\x20\x32\x32\x20\u5206\u9418\x29\uff0c\u4f7f\u5176\u6210\u70ba\u5730\u6bbc\u4e2d\u6975\u70ba\u7f55\u898b\u7684\u5929\u7136\u5143\u7d20\uff0c\u5168\u5730\u6bbc\u7684\u7e3d\u542b\u91cf\u4f30\u8a08\u4e0d\u8d85\u904e\x20\x33\x30\x20\u516c\u514b\u3002\x0a\x0a\u5728\u5316\u5b78\u884c\u70ba\u4e0a\uff0c\u9345\u7684\u96fb\u5b50\u7d44\u614b\u70ba\x20\x5b\x52\x6e\x5d\x37\x73\u00b9\uff0c\u5176\u96fb\u8ca0\u5ea6\u7d04\u70ba\x20\x30\x2e\x37\x28\u9b91\u6797\u6a19\u5ea6\u6700\u4f4e\u503c\x29\uff0c\u9019\u610f\u5473\u8457\u5b83\u5177\u5099\u6975\u81f4\u7684\u91d1\u5c6c\u6027\u8207\u96fb\u96e2\u80fd\u6700\u4f4e\u8da8\u52e2\u3002\u5728\u53f0\u7063\u9ad8\u4e2d\u5316\u5b78\u63a2\u8a0e\u65cf\u7fa4\u898f\u5f8b\u6642\uff0c\u9345\u662f\u8aaa\u660e\u300c\u7531\u4e0a\u800c\u4e0b\u91d1\u5c6c\u53cd\u61c9\u6027\u5287\u589e\u300d\u7684\u6975\u9650\u7406\u8ad6\u6848\u4f8b\uff1a\u96d6\u7136\u96e3\u4ee5\u53d6\u5f97\u5b8f\u89c0\u6a23\u672c\u9032\u884c\u5be6\u9a57\uff0c\u4f46\u63a8\u6e2c\u5176\u8207\u6c34\u53cd\u61c9\u7684\u66b4\u70c8\u7a0b\u5ea6\u5c07\u9060\u8d85\u92ab\u8207\u92a3\u3002\u7531\u65bc\u5176\u5f37\u70c8\u7684\u653e\u5c04\u6027\u71b1\u80fd\uff0c\u7d14\u9345\u91d1\u5c6c\u584a\u82e5\u80fd\u805a\u96c6\uff0c\u6703\u56e0\u81ea\u8eab\u8870\u8b8a\u71b1\u800c\u8fc5\u901f\u6c7d\u5316\uff0c\u9019\u4f7f\u5176\u5316\u5b78\u7814\u7a76\u5927\u591a\u53ea\u80fd\u5728\u539f\u5b50\u7b49\u7d1a\u7684\u6975\u7a00\u6eb6\u6db2\u4e2d\u9032\u884c\u3002\x0a\x0a\u5728\u73fe\u4ee3\u61c9\u7528\u8207\u5c16\u7aef\u7269\u7406\u9818\u57df\uff0c\u9345\u7684\u4e3b\u8981\u50f9\u503c\u5728\u65bc\u539f\u5b50\u7d50\u69cb\u7684\u7814\u7a76\u3002\u900f\u904e\u96f7\u5c04\u51b7\u537b\u8207\u300c\u78c1\u5149\u9677\u9631\u300d\x28\x4d\x4f\x54\x29\u6280\u8853\uff0c\u79d1\u5b78\u5bb6\u80fd\u6355\u6349\u4e26\u56fa\u5b9a\u6578\u5343\u500b\u9345\u539f\u5b50\uff0c\u5229\u7528\u5176\u9ad8\u5ea6\u4e0d\u7a69\u5b9a\u7684\u6838\u6027\u8cea\u89c0\u6e2c\u5f31\u4ea4\u4e92\u4f5c\u7528\x28\x57\x65\x61\x6b\x20\x69\x6e\x74\x65\x72\x61\x63\x74\x69\x6f\x6e\x29\u4e2d\u7684\u5b87\u7a31\u4e0d\u5b88\u6046\u73fe\u8c61\u3002\u6b64\u5916\uff0c\u9345\u4f5c\u70ba\u9312\u8870\u8b8a\u93c8\u7684\u4e00\u74b0\uff0c\u5176\u5728\u7279\u5b9a\u5730\u8cea\u6a23\u672c\u4e2d\u7684\u6fc3\u5ea6\uff0c\u53ef\u7528\u65bc\u8ffd\u8e64\u5730\u4e0b\u6838\u6d3b\u52d5\u8207\u91cd\u6838\u5143\u7d20\u9077\u79fb\u3002\u5728\u91ab\u5b78\u4e0a\uff0c\u96d6\u7136\u9345\u7684\u61c9\u7528\u53d7\u9650\u65bc\u5176\u77ed\u534a\u8870\u671f\uff0c\u4f46\u5176\u91cb\u653e\u7684\u9ad8\u80fd\u7c92\u5b50\u4ecd\u88ab\u8996\u70ba\u6a19\u9776\u653e\u5c04\u6cbb\u7642\u7814\u7a76\u7684\u6f5b\u5728\u7269\u7a2e\u3002\x0a\x0a\u95dc\u65bc\u9345\u7684\u7269\u7406\u6975\u9650\uff0c\u5b83\u88ab\u9810\u6e2c\u5177\u5099\u6975\u4f4e\u7684\u7194\u9ede\x28\u7d04\x20\x32\x37\x20\u00b0\x43\x29\uff0c\u9019\u4f7f\u5176\u8207\u92ab\u4e00\u6a23\u53ef\u80fd\u5728\u63a5\u8fd1\u5ba4\u6eab\u6642\u5448\u73fe\u6db2\u614b\u3002\u6709\u8da3\u7684\u662f\uff0c\u9345\u662f\u5df2\u77e5\u6240\u6709\u5143\u7d20\u4e2d\u96fb\u8ca0\u5ea6\u6700\u4f4e\u7684\uff0c\u9019\u4f7f\u5176\u5728\u5f62\u6210\u5316\u5b78\u9375\u6642\uff0c\u5176\u50f9\u96fb\u5b50\u5e7e\u4e4e\u5b8c\u5168\u4e0d\u53d7\u539f\u5b50\u6838\u675f\u7e1b\uff0c\u5c55\u73fe\u51fa\u8fd1\u4e4e\u5b8c\u7f8e\u7684\u96e2\u5b50\u9375\u7279\u6027\u3002\u9019\u7a2e\u5f9e\u6cd5\u862d\u897f\u4e4b\u540d\u7684\u6d6a\u6f2b\u5230\u5b9a\u7fa9\u9e7c\u91d1\u5c6c\u53cd\u61c9\u6027\u8207\u7a00\u6709\u6027\u5dd4\u5cf0\u7684\u8f49\u8b8a\uff0c\u7cbe\u78ba\u8a6e\u91cb\u4e86\u9345\u5728\u9031\u671f\u8868\u5e95\u90e8\u4f5c\u70ba\u300c\u8f49\u77ac\u5373\u901d\u4e4b\u738b\u300d\u7684\u5730\u4f4d\u3002",
  "\x52\x61":
    "\u9433\x28\x52\x61\x64\x69\x75\x6d\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x52\x61\uff0c\u539f\u5b50\u5e8f\x20\x38\x38\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u4e03\u9031\u671f\u3001\u7b2c\x20\x32\x20\u65cf\x28\u9e7c\u571f\u91d1\u5c6c\uff0c\x73\x20\u5340\u584a\x29\u3002\u5176\u540d\u7a31\u6e90\u65bc\u62c9\u4e01\u8a9e\u300c\x72\x61\x64\x69\x75\x73\u300d\uff0c\u610f\u70ba\u300c\u5c04\u7dda\u300d\u3002\x31\x38\x39\x38\x20\u5e74\u7531\u5c45\u79ae\u592b\u5a66\x28\x4d\x61\x72\x69\x65\x20\x61\x6e\x64\x20\x50\x69\x65\x72\x72\x65\x20\x43\x75\x72\x69\x65\x29\u5728\u8655\u7406\u5927\u91cf\u701d\u9752\u923e\u7926\u6642\u767c\u73fe\uff0c\u958b\u555f\u4e86\u4eba\u985e\u5c0d\u653e\u5c04\u6027\u5316\u5b78\u8207\u539f\u5b50\u7269\u7406\u7684\u65b0\u7d00\u5143\u3002\u9433\u662f\u9e7c\u571f\u91d1\u5c6c\u4e2d\u6700\u91cd\u7684\u6210\u54e1\uff0c\u5177\u5099\u5f37\u70c8\u7684\u653e\u5c04\u6027\u8207\u9280\u767d\u8272\u7684\u91d1\u5c6c\u5149\u6fa4\uff0c\u5176\u5316\u5b78\u884c\u70ba\u8207\u540c\u65cf\u7684\u92c7\u6975\u5176\u76f8\u4f3c\u3002\u5b83\u662f\u79d1\u5b78\u53f2\u4e0a\u6975\u5177\u50b3\u5947\u8272\u5f69\u7684\u5143\u7d20\uff0c\u66fe\u63a8\u52d5\u4e86\u65e9\u671f\u764c\u75c7\u6cbb\u7642\u8207\u91cf\u5b50\u529b\u5b78\u7684\u767c\u5c55\u3002\x0a\x0a\u5728\u5fae\u89c0\u7d50\u69cb\u4e0a\uff0c\u9433\u7684\u96fb\u5b50\u7d44\u614b\u70ba\x20\x5b\x52\x6e\x5d\x37\x73\u00b2\uff0c\u6700\u7a69\u5b9a\u7684\u6c27\u5316\u614b\u70ba\x20\x2b\x32\u3002\u9433\u7684\u96fb\u96e2\u80fd\u6975\u4f4e\u4e14\u91d1\u5c6c\u6d3b\u6027\u6975\u9ad8\uff0c\u5728\u7a7a\u6c23\u4e2d\u6703\u8fc5\u901f\u8207\u6c2e\u3001\u6c27\u53cd\u61c9\u5f62\u6210\u6c2e\u5316\u7269\u8207\u6c27\u5316\u7269\u3002\u5728\u9ad8\u4e2d\u5316\u5b78\u95dc\u65bc\u6838\u53cd\u61c9\u8207\u8870\u8b8a\u93c8\u7684\u6559\u5b78\u4e2d\uff0c\u9433\u662f\u95dc\u9375\u7bc0\u9ede\uff1a\u00b2\u00b2\u2076\x52\x61\x20\u7d93\u7531\x20\u03b1\x20\u8870\u8b8a\u7522\u751f\u6c21\u6c23\x28\x52\x6e\x29\uff0c\u9019\u4e00\u904e\u7a0b\u662f\u5ba4\u5167\u6c21\u6c23\u6c61\u67d3\u7684\u6e90\u982d\uff0c\u4ea6\u662f\u5730\u8cea\u5e74\u4ee3\u6e2c\u5b9a\u7684\u6307\u6a19\u3002\u9433\u9e7d\u5728\u9ed1\u6697\u4e2d\u6703\u767c\u51fa\u5fae\u5f31\u7684\u6de1\u85cd\u8272\u87a2\u5149\uff0c\u9019\u6e90\u65bc\u5176\u9ad8\u80fd\u8f3b\u5c04\u4f7f\u5468\u570d\u7a7a\u6c23\u96fb\u96e2\u800c\u7522\u751f\u7684\u7269\u7406\u73fe\u8c61\u3002\x0a\x0a\u5728\u73fe\u4ee3\u79d1\u6280\u4e2d\uff0c\u9433\u7684\u61c9\u7528\u5df2\u7531\u65e9\u671f\u7684\u65e5\u5e38\u767c\u5149\u5291\u8f49\u5411\u5c08\u696d\u7684\u91ab\u7642\u8207\u5de5\u696d\u9818\u57df\u3002\u5728\u653e\u5c04\u91ab\u5b78\u53f2\u4e0a\uff0c\u9433\u9e7d\u66fe\u88ab\u7528\u65bc\u5c01\u9589\u5f0f\u8fd1\u63a5\u653e\u5c04\u6cbb\u7642\x28\x42\x72\x61\x63\x68\x79\x74\x68\x65\x72\x61\x70\x79\x29\u4ee5\u6d88\u6ec5\u816b\u7624\uff0c\u96d6\u7136\u73fe\u4ee3\u591a\u5df2\u88ab\u66f4\u7cbe\u78ba\u7684\u653e\u5c04\u6e90\u53d6\u4ee3\uff0c\u4f46\u5176\u540c\u4f4d\u7d20\x20\u00b2\u00b2\u00b3\x52\x61\x20\u76ee\u524d\u88ab\u6838\u51c6\u7528\u65bc\u6cbb\u7642\u9aa8\u8f49\u79fb\u764c\u75c7\uff0c\u5229\u7528\u5176\u8207\u9223\u76f8\u4f3c\u7684\u5316\u5b78\u6027\u8cea\u9032\u5165\u9aa8\u9abc\uff0c\u91cb\u653e\u77ed\u7a0b\x20\u03b1\x20\u7c92\u5b50\u7cbe\u78ba\u64ca\u788e\u75c5\u7076\u3002\u6b64\u5916\uff0c\u9433\u8207\u9239\u7d44\u6210\u7684\u6df7\u5408\u6e90\u80fd\u7522\u751f\u7a69\u5b9a\u4e2d\u5b50\u6d41\uff0c\u7528\u65bc\u4e2d\u5b50\u6d3b\u5316\u5206\u6790\u8207\u7279\u5b9a\u5100\u5668\u7684\u6821\u6e96\u3002\x0a\x0a\u9433\u5728\u7269\u7406\u73fe\u8c61\u4e0a\u5c55\u73fe\u4e86\u9a5a\u4eba\u7684\u80fd\u91cf\u7279\u5fb5\u3002\u5176\u8870\u8b8a\u7522\u751f\u7684\u71b1\u91cf\u6975\u5927\uff0c\u6bcf\u514b\u9433\u6bcf\u5c0f\u6642\u7d04\u91cb\u653e\x20\x31\x34\x30\x20\u5361\u8def\u91cc\u7684\u71b1\u91cf\uff0c\u9019\u8db3\u4ee5\u4f7f\u5176\u5468\u570d\u74b0\u5883\u6eab\u5ea6\u986f\u8457\u5347\u9ad8\uff0c\u751a\u81f3\u4f7f\u5176\u5316\u5408\u7269\u5448\u73fe\u81ea\u6211\u767c\u5149\u7684\u6548\u679c\u3002\u53cd\u76f4\u89ba\u7684\u662f\uff0c\u96d6\u7136\u9433\u5728\x20\x32\x30\x20\u4e16\u7d00\u521d\u66fe\u88ab\u6dfb\u52a0\u65bc\u98f2\u7528\u6c34\u6216\u5316\u599d\u54c1\u4e2d\u4f5c\u70ba\u5065\u5eb7\u88dc\u54c1\x28\u5982\u8457\u540d\u7684\x20\x52\x61\x64\x69\x74\x68\x6f\x72\x29\uff0c\u4f46\u96a8\u5f8c\u7684\u91ab\u5b78\u7814\u7a76\u8b49\u5be6\u5176\u7d2f\u7a4d\u5728\u9aa8\u9abc\u4e2d\u6703\u5c0e\u81f4\u6bc0\u6ec5\u6027\u7684\u5167\u8f3b\u5c04\u50b7\u5bb3\u3002\u9019\u7a2e\u5f9e\u5c45\u79ae\u5be6\u9a57\u5ba4\u4e2d\u5283\u6642\u4ee3\u7684\u300c\u5149\u8292\u300d\u5230\u73fe\u4ee3\u91ab\u5b78\u7cbe\u6e96\u6297\u764c\u7684\u5de5\u5177\uff0c\u7cbe\u78ba\u8a6e\u91cb\u4e86\u9433\u4f5c\u70ba\u653e\u5c04\u6027\u5148\u9a45\u5728\u5316\u5b78\u53f2\u4e2d\u7684\u539a\u91cd\u8eab\u5206\u3002",
  "\x41\x63":
    "\u9312\x28\x41\x63\x74\x69\x6e\x69\x75\x6d\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x41\x63\uff0c\u539f\u5b50\u5e8f\x20\x38\x39\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u4e03\u9031\u671f\u3001\u7b2c\x20\x33\x20\u65cf\x28\u9312\u7cfb\u5143\u7d20\u7684\u8d77\u9ede\uff0c\x64\x2f\x66\x20\u5340\u584a\x29\u3002\u5176\u540d\u7a31\u6e90\u65bc\u5e0c\u81d8\u8a9e\u300c\x61\x6b\x74\x69\x6e\x6f\x73\u300d\uff0c\u610f\u70ba\u300c\u5149\u675f\u300d\u6216\u300c\u5c04\u7dda\u300d\u3002\x31\x38\x39\x39\x20\u5e74\u7531\u6cd5\u570b\u5316\u5b78\u5bb6\u5fb7\u6bd4\u57c3\u7d0d\x28\x41\x6e\x64\x72\u00e9\x2d\x4c\x6f\x75\x69\x73\x20\x44\x65\x62\x69\x65\x72\x6e\x65\x29\u5f9e\u701d\u9752\u923e\u7926\u4e2d\u767c\u73fe\u3002\u9312\u662f\u4e00\u7a2e\u9280\u767d\u8272\u7684\u5f37\u653e\u5c04\u6027\u91d1\u5c6c\uff0c\u56e0\u5176\u6975\u5f37\u7684\u6e38\u96e2\u80fd\u529b\uff0c\u5728\u6697\u8655\u6703\u767c\u51fa\u660e\u986f\u7684\u5e7d\u85cd\u8272\u5149\u8292\u3002\u5b83\u662f\u9031\u671f\u8868\u4e2d\u300c\u9312\u7cfb\u5143\u7d20\u300d\u7684\u547d\u540d\u6a19\u6e96\uff0c\u4e0d\u50c5\u5728\u6838\u5de5\u696d\u4e2d\u626e\u6f14\u4e2d\u5b50\u6e90\u7684\u89d2\u8272\uff0c\u66f4\u662f\u73fe\u4ee3\u6a19\u9776\u653e\u5c04\u6cbb\u7642\x28\x54\x41\x54\x29\u4e2d\u6975\u5177\u524d\u77bb\u6027\u7684\u91ab\u5b78\u660e\u661f\u3002\x0a\x0a\u9312\u7684\u96fb\u5b50\u7d44\u614b\u70ba\x20\x5b\x52\x6e\x5d\x36\x64\u00b9\x37\x73\u00b2\uff0c\u5728\u5316\u5b78\u53cd\u61c9\u4e2d\u5c55\u73fe\u51fa\u7a69\u5b9a\u7684\x20\x2b\x33\x20\u6c27\u5316\u614b\u3002\u7531\u65bc\u5176\u96e2\u5b50\u534a\u5f91\u8f03\u5927\uff0c\u9312\u7684\u5316\u5b78\u884c\u70ba\u8207\u540c\u65cf\u7684\u946d\x28\x4c\x61\x29\u6975\u5176\u76f8\u4f3c\uff0c\u5c55\u73fe\u51fa\u5f37\u70c8\u7684\u91d1\u5c6c\u6027\u8207\u9084\u539f\u6027\u3002\u5728\u9ad8\u4e2d\u5316\u5b78\u63a2\u8a0e\u9031\u671f\u5f8b\u5206\u5340\u8207\u5167\u904e\u6e21\u5143\u7d20\u6642\uff0c\u9312\u662f\u7406\u89e3\x20\x35\x66\x20\u8ecc\u57df\u958b\u59cb\u586b\u5145\u7684\u6a19\u8a8c\u3002\u9312\u5177\u5099\u6975\u9ad8\u7684\u6bd4\u653e\u5c04\u6d3b\u6027\uff0c\u5176\u7a69\u5b9a\u540c\u4f4d\u7d20\x20\u00b2\u00b2\u2077\x41\x63\x28\u534a\u8870\u671f\u7d04\x20\x32\x31\x2e\x38\x20\u5e74\x29\u4e3b\u8981\u91cb\u653e\u9ad8\u80fd\u96fb\u5b50\u6d41\u3002\u7531\u65bc\u5176\u5c0d\u6c27\u7684\u6975\u5f37\u89aa\u548c\u529b\uff0c\u91d1\u5c6c\u9312\u5728\u7a7a\u6c23\u4e2d\u6703\u8fc5\u901f\u5f62\u6210\u6c27\u5316\u5c64\uff0c\u5c55\u73fe\u51fa\u9e7c\u571f\u91d1\u5c6c\u822c\u7684\u6d3b\u6f51\u7279\u5fb5\u3002\x0a\x0a\u5728\u73fe\u4ee3\u61c9\u7528\u9818\u57df\uff0c\u9312\u5728\u6297\u764c\u6280\u8853\u4e2d\u5177\u6709\u9769\u547d\u6027\u6f5b\u529b\u3002\u540c\u4f4d\u7d20\x20\u00b2\u00b2\u2075\x41\x63\x20\u662f\u300c\u6a19\u9776\x20\u03b1\x20\u7c92\u5b50\u7642\u6cd5\u300d\u7684\u6838\u5fc3\u85e5\u7269\uff0c\u5b83\u80fd\u767c\u5c04\u5c04\u7a0b\u6975\u77ed\u4f46\u80fd\u91cf\u5de8\u5927\u7684\x20\u03b1\x20\u7c92\u5b50\uff0c\u82e5\u7d50\u5408\u7279\u5b9a\u7684\u55ae\u682a\u6297\u9ad4\uff0c\u80fd\u50cf\u7cbe\u78ba\u5f15\u5c0e\u7684\u300c\u5fae\u578b\u9b5a\u96f7\u300d\u822c\u76f4\u63a5\u6467\u6bc0\u764c\u7d30\u80de\u6838\uff0c\u800c\u5c0d\u5468\u570d\u5065\u5eb7\u7d44\u7e54\u7684\u50b7\u5bb3\u6975\u5c0f\u3002\u6b64\u5916\uff0c\u9312\u8207\u9239\u7d50\u5408\u6210\u7684\x20\x41\x63\x2d\x42\x65\x20\u4e2d\u5b50\u6e90\uff0c\u5176\u7a69\u5b9a\u6027\u512a\u65bc\u9433\u6e90\uff0c\u88ab\u5ee3\u6cdb\u7528\u65bc\u77f3\u6cb9\u52d8\u63a2\u4e2d\u7684\u4e2d\u5b50\u4e95\u6e2c\u8207\u6838\u8a2d\u65bd\u7684\u555f\u52d5\u6e90\u3002\u5728\u71b1\u80fd\u8f49\u5316\u65b9\u9762\uff0c\u9312\u7684\u9ad8\u71b1\u767c\u5c04\u7387\u4f7f\u5176\u5728\u7279\u5b9a\u71b1\u96fb\u7522\u751f\u88dd\u7f6e\u4e2d\u5177\u5099\u7814\u7a76\u50f9\u503c\u3002\x0a\x0a\u95dc\u65bc\u9312\u7684\u7269\u7406\u7279\u5fb5\uff0c\u5b83\u5c55\u73fe\u4e86\u7269\u8cea\u8207\u8f3b\u5c04\u7684\u9ad8\u5ea6\u8026\u5408\u3002\u9312\u91d1\u5c6c\u584a\u7684\u8868\u9762\u6eab\u5ea6\u5e38\u56e0\u5176\u5167\u90e8\u653e\u5c04\u6027\u8870\u8b8a\u800c\u9ad8\u65bc\u74b0\u5883\u6eab\u5ea6\uff0c\u4e14\u5176\u7522\u751f\u7684\u85cd\u8272\u87a2\u5149\u5728\u67d0\u4e9b\u689d\u4ef6\u4e0b\u751a\u81f3\u8db3\u4ee5\u76f4\u63a5\u66dd\u5149\u611f\u5149\u5e95\u7247\u3002\u6709\u8da3\u7684\u662f\uff0c\u96d6\u7136\u9312\u5728\u81ea\u7136\u754c\u4e2d\u6975\u5176\u7a00\u5c11\x28\u50c5\u5b58\u5728\u65bc\u923e\u7926\u8870\u8b8a\u93c8\u4e2d\x29\uff0c\u4f46\u900f\u904e\u6838\u53cd\u61c9\u7210\u4e2d\u7684\u4e2d\u5b50\u7167\u5c04\u9433\x2d\x32\x32\x36\uff0c\u5df2\u80fd\u5be6\u73fe\u6beb\u514b\u7d1a\u7684\u7522\u91cf\u3002\u9019\u7a2e\u5f9e\u300c\u5149\u675f\u300d\u4e4b\u540d\u5230\u5728\u5948\u7c73\u5c3a\u5ea6\u4e0b\u7cbe\u6e96\u5c0d\u6297\u764c\u75c7\u7684\u6280\u8853\u8e8d\u9032\uff0c\u7cbe\u78ba\u8a6e\u91cb\u4e86\u9312\u5728\u7b2c\u4e03\u9031\u671f\u5143\u7d20\u4e2d\u4f5c\u70ba\u9ad8\u80fd\u80fd\u91cf\u8f09\u9ad4\u7684\u7368\u7279\u5730\u4f4d\u3002",
  "\x54\x68":
    "\u91f7\x28\x54\x68\x6f\x72\x69\x75\x6d\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x54\x68\uff0c\u539f\u5b50\u5e8f\x20\x39\x30\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u4e03\u9031\u671f\u3001\u9312\u7cfb\u5143\u7d20\x28\x66\x20\u5340\u584a\x29\u3002\u5176\u540d\u7a31\u6e90\u65bc\u5317\u6b50\u96f7\u795e\u300c\u7d22\u723e\u300d\x28\x54\x68\x6f\x72\x29\u3002\x31\x38\x32\x38\x20\u5e74\u7531\u745e\u5178\u5316\u5b78\u5bb6\u8c9d\u9f4a\u91cc\u70cf\u65af\x28\x4a\u00f6\x6e\x73\x20\x4a\x61\x63\x6f\x62\x20\x42\x65\x72\x7a\x65\x6c\x69\x75\x73\x29\u5728\u5206\u6790\u632a\u5a01\u7684\u7926\u77f3\u6642\u767c\u73fe\u3002\u91f7\u662f\u4e00\u7a2e\u9280\u7070\u8272\u3001\u8cea\u5730\u67d4\u8edf\u4e14\u5177\u5099\u9ad8\u5bc6\u5ea6\u7684\u653e\u5c04\u6027\u91d1\u5c6c\uff0c\u5176\u5730\u6bbc\u542b\u91cf\u8207\u925b\u76f8\u7576\uff0c\u9060\u9ad8\u65bc\u923e\u3002\u5b83\u662f\u73fe\u4ee3\u80fd\u6e90\u79d1\u6280\u4e2d\u6975\u5177\u6f5b\u529b\u7684\u300c\u6b21\u4e16\u4ee3\u6838\u71c3\u6599\u300d\uff0c\u4ea6\u662f\u6750\u6599\u79d1\u5b78\u4e2d\u63d0\u5347\u8010\u71b1\u6027\u8207\u5149\u5b78\u6027\u80fd\u7684\u91cd\u8981\u6dfb\u52a0\u5143\u7d20\u3002\x0a\x0a\u91f7\u7684\u96fb\u5b50\u7d44\u614b\u5728\u57fa\u614b\u8207\u6df7\u6210\u4e0b\u8f03\u70ba\u8907\u96dc\uff0c\u5e38\u6a19\u8a18\u70ba\x20\x5b\x52\x6e\x5d\x36\x64\u00b2\x37\x73\u00b2\uff0c\u6700\u7a69\u5b9a\u7684\u6c27\u5316\u614b\u70ba\x20\x2b\x34\u3002\u96d6\u7136\u88ab\u6b78\u985e\u70ba\u9312\u7cfb\u5143\u7d20\uff0c\u4f46\u91f7\u5728\u5316\u5b78\u6027\u8cea\u4e0a\u8207\u5176\u4e0a\u65b9\u7684\u92ef\x28\x5a\x72\x29\u53ca\u927f\x28\x48\x66\x29\u5c55\u73fe\u51fa\u9a5a\u4eba\u7684\u76f8\u4f3c\u6027\uff0c\u5c55\u73fe\u51fa\u7a69\u5b9a\u7684\u56db\u50f9\u5316\u5b78\u7279\u5fb5\u3002\u5728\u9ad8\u4e2d\u5316\u5b78\u8a0e\u8ad6\u6838\u80fd\u767c\u96fb\u8207\u540c\u4f4d\u7d20\u6642\uff0c\u91f7\x2d\x32\x33\x32\x28\u00b2\u00b3\u00b2\x54\x68\x29\u662f\u6838\u5fc3\u6982\u5ff5\uff1a\u5b83\u80fd\u900f\u904e\u6355\u6349\u4e2d\u5b50\u8f49\u5316\u70ba\u6613\u5206\u88c2\u7684\u923e\x2d\x32\x33\x33\u3002\u6b64\u5916\uff0c\u6c27\u5316\u91f7\x28\x54\x68\x4f\u2082\x29\u5177\u5099\u6975\u9ad8\u7684\u7194\u9ede\x28\u7d04\x20\x33\x33\x30\x30\x20\u00b0\x43\x29\uff0c\u662f\u6240\u6709\u6c27\u5316\u7269\u4e2d\u6700\u9ad8\u7684\uff0c\u9019\u8ce6\u4e88\u4e86\u91f7\u512a\u7570\u7684\u71b1\u529b\u5b78\u7a69\u5b9a\u6027\u3002\x0a\x0a\u5728\u73fe\u4ee3\u5de5\u696d\u8207\u6838\u5de5\u7a0b\u8108\u7d61\u4e2d\uff0c\u91f7\u88ab\u8996\u70ba\u300c\u66f4\u4e7e\u6de8\u7684\u6838\u80fd\u300d\u3002\u91f7\u53cd\u61c9\u7210\x28\u5982\u6db2\u614b\u6c1f\u5316\u91f7\u53cd\u61c9\u7210\uff0c\x4c\x46\x54\x52\x29\u76f8\u6bd4\u50b3\u7d71\u923e\u53cd\u61c9\u7210\uff0c\u5177\u6709\u5b89\u5168\u6027\u66f4\u9ad8\u3001\u6838\u5ee2\u6599\u58fd\u547d\u77ed\u4e14\u4e0d\u5177\u5099\u6b66\u5668\u7d1a\u64f4\u6563\u98a8\u96aa\u7684\u512a\u52e2\u3002\u5728\u51b6\u91d1\u5b78\u4e2d\uff0c\u91f7\u88ab\u7528\u65bc\u88fd\u9020\u300c\u91f7\u93a2\u96fb\u6975\u300d\uff0c\u5ee3\u6cdb\u61c9\u7528\u65bc\x20\x54\x49\x47\x20\u710a\u63a5\u4e2d\u4ee5\u7a69\u5b9a\u96fb\u5f27\uff1b\u800c\u5728\u822a\u592a\u5de5\u696d\u4e2d\uff0c\u9382\u91f7\u5408\u91d1\u5247\u56e0\u5176\u8f15\u91cf\u4e14\u5728\u9ad8\u6eab\u4e0b\u4ecd\u80fd\u4fdd\u6301\u9ad8\u5f37\u5ea6\u800c\u88ab\u7528\u65bc\u5c0e\u5f48\u8207\u98db\u6a5f\u7d50\u69cb\u3002\u5728\u7167\u660e\u6280\u8853\u53f2\u4e2d\uff0c\u91f7\u66fe\u662f\u6c7d\u5316\u71c8\u71c8\u7db2\x28\x47\x61\x73\x20\x6d\x61\x6e\x74\x6c\x65\x29\u7684\u6838\u5fc3\u6210\u5206\uff0c\u5229\u7528\u5176\u5728\u9ad8\u6eab\u4e0b\u7684\u5f37\u70c8\u767d\u71be\u767c\u5149\u7279\u6027\u63d0\u4f9b\u7167\u660e\u3002\x0a\x0a\u91f7\u5728\u7269\u7406\u73fe\u8c61\u4e0a\u5c55\u73fe\u4e86\u6975\u81f4\u7684\u7a69\u5b9a\u8207\u8010\u706b\u6027\u3002\u6c27\u5316\u91f7\u6676\u9ad4\u5177\u5099\u6975\u4f4e\u7684\u71b1\u81a8\u8139\u4fc2\u6578\uff0c\u9019\u4f7f\u5176\u5728\u7cbe\u5bc6\u5100\u5668\u7684\u6297\u71b1\u9707\u96f6\u4ef6\u4e2d\u4e0d\u53ef\u6216\u7f3a\u3002\u6709\u8da3\u7684\u662f\uff0c\u96d6\u7136\u91d1\u5c6c\u91f7\u5728\u65e5\u5e38\u751f\u6d3b\u4e2d\u4e0d\u5e38\u898b\uff0c\u4f46\u5176\u6c27\u5316\u7269\u66fe\u662f\u986f\u5fae\u93e1\u8207\u76f8\u6a5f\u93e1\u982d\u4e2d\u9ad8\u6298\u5c04\u7387\u3001\u4f4e\u8272\u6563\u73bb\u7483\u7684\u91cd\u8981\u6210\u5206\x28\u96d6\u7136\u5f8c\u4f86\u56e0\u653e\u5c04\u6027\u7591\u616e\u800c\u6539\u7528\u946d\x29\u3002\u6b64\u5916\uff0c\u91f7\u662f\u81ea\u7136\u754c\u4e2d\u552f\u4e00\u80fd\u5927\u898f\u6a21\u5b58\u5728\u7684\u3001\u975e\u923e\u8870\u8b8a\u93c8\u8d77\u9ede\u7684\u653e\u5c04\u6027\u5143\u7d20\u3002\u9019\u7a2e\u5f9e\u5317\u6b50\u6230\u795e\u7684\u547d\u540d\u5230\u5b9a\u7fa9\u672a\u4f86\u5b89\u5168\u80fd\u6e90\u7684\u8f49\u8b8a\uff0c\u7cbe\u78ba\u8a6e\u91cb\u4e86\u91f7\u5728\u9031\u671f\u8868\u4e2d\u4f5c\u70ba\u300c\u91cd\u578b\u7a69\u5b9a\u80fd\u91cf\u6e90\u300d\u7684\u95dc\u9375\u5730\u4f4d\u3002",
  "\x50\x61":
    "\u93f7\x28\x50\x72\x6f\x74\x61\x63\x74\x69\x6e\x69\x75\x6d\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x50\x61\uff0c\u539f\u5b50\u5e8f\x20\x39\x31\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u4e03\u9031\u671f\u3001\u9312\u7cfb\u5143\u7d20\x28\x66\x20\u5340\u584a\x29\u3002\u5176\u540d\u7a31\u6e90\u65bc\u5e0c\u81d8\u8a9e\u300c\x70\x72\x6f\x74\x6f\x73\u300d\uff0c\u610f\u70ba\u300c\u7b2c\u4e00\u500b\u300d\uff0c\u7d50\u5408\u300c\x61\x63\x74\x69\x6e\x69\x75\x6d\u300d\x28\u9312\x29\uff0c\u6307\u5176\u70ba\u9312\u7684\u524d\u9a45\u7269\x28\u00b2\u00b3\u00b9\x50\x61\x20\u7d93\x20\u03b1\x20\u8870\u8b8a\u7522\u751f\x20\u00b2\u00b2\u2077\x41\x63\x29\u3002\x31\x39\x31\x33\x20\u5e74\u7531\u6cd5\u63da\u65af\x28\x4b\x61\x73\x69\x6d\x69\x72\x20\x46\x61\x6a\x61\x6e\x73\x29\u8207\u6208\u6797\x28\x4f\x73\x77\x61\x6c\x64\x20\x48\x65\x6c\x6d\x75\x74\x68\x20\x47\u00f6\x68\x72\x69\x6e\x67\x29\u9996\u6b21\u8fa8\u8b58\u51fa\u77ed\u58fd\u547d\u540c\u4f4d\u7d20\uff0c\u96a8\u5f8c\u7531\u9081\u7279\u7d0d\x28\x4c\x69\x73\x65\x20\x4d\x65\x69\x74\x6e\x65\x72\x29\u8207\u54c8\u6069\x28\x4f\x74\x74\x6f\x20\x48\x61\x68\x6e\x29\u65bc\x20\x31\x39\x31\x37\x20\u5e74\u5206\u96e2\u51fa\u9577\u58fd\u547d\u7684\x20\u00b2\u00b3\u00b9\x50\x61\u3002\u93f7\u662f\u4e00\u7a2e\u5177\u6709\u9280\u7070\u8272\u91d1\u5c6c\u5149\u6fa4\u7684\u653e\u5c04\u6027\u5143\u7d20\uff0c\u5730\u6bbc\u542b\u91cf\u6975\u5176\u7a00\u5c11\uff0c\u662f\u6838\u7269\u7406\u7814\u7a76\u4e2d\u7406\u89e3\u9312\u7cfb\u5143\u7d20\u96fb\u5b50\u904e\u6e21\u7279\u6027\u7684\u95dc\u9375\u5c0d\u8c61\u3002\x0a\x0a\u5728\u5316\u5b78\u884c\u70ba\u4e0a\uff0c\u93f7\u7684\u96fb\u5b50\u7d44\u614b\u70ba\x20\x5b\x52\x6e\x5d\x35\x66\u00b2\x36\x64\u00b9\x37\x73\u00b2\u3002\u93f7\u7684\u5316\u5b78\u6027\u8cea\u6975\u5176\u8907\u96dc\uff0c\u80fd\u5c55\u73fe\x20\x2b\x34\x20\u8207\x20\x2b\x35\x20\u5169\u7a2e\u6c27\u5316\u614b\uff0c\u5176\u4e2d\x20\x2b\x35\x20\u50f9\u5728\u6c34\u6eb6\u6db2\u4e2d\u8f03\u70ba\u7a69\u5b9a\u3002\u7531\u65bc\u5176\u4f4d\u65bc\u9312\u8207\u923e\u4e4b\u9593\uff0c\u93f7\u7684\u6027\u8cea\u5c55\u73fe\u51fa\u5f9e\u300c\u985e\u9312\u300d\u5230\u300c\u985e\u923e\u300d\u7684\u904e\u6e21\u7279\u5fb5\u3002\u93f7\u5728\u7a7a\u6c23\u4e2d\u6703\u7de9\u6162\u6c27\u5316\uff0c\u4e14\u6613\u6eb6\u65bc\u7121\u6a5f\u9178\u5f62\u6210\u591a\u7a2e\u932f\u96e2\u5b50\u3002\u5728\u9ad8\u4e2d\u5316\u5b78\u63a2\u8a0e\u9312\u7cfb\u6536\u7e2e\u8207\u96fb\u5b50\u8ecc\u57df\u586b\u5145\u898f\u5f8b\u6642\uff0c\u93f7\u662f\u7814\u7a76\x20\x35\x66\x20\u8ecc\u57df\u958b\u59cb\u7a69\u5b9a\u53c3\u8207\u6210\u9375\u7684\u91cd\u8981\u6848\u4f8b\u3002\u93f7\u53ca\u5176\u5316\u5408\u7269\u5177\u5099\u6975\u9ad8\u7684\u653e\u5c04\u6bd2\u6027\uff0c\u5fc5\u9808\u5728\u53d7\u63a7\u74b0\u5883\u4e0b\u9032\u884c\u5fae\u91cf\u5316\u5b78\u7814\u7a76\u3002\x0a\x0a\u5728\u73fe\u4ee3\u61c9\u7528\u9818\u57df\uff0c\u93f7\u56e0\u5176\u6975\u9ad8\u7684\u7a00\u6709\u6027\u8207\u653e\u5c04\u6027\uff0c\u76ee\u524d\u5c1a\u7121\u5927\u898f\u6a21\u7684\u5de5\u696d\u7528\u9014\uff0c\u4e3b\u8981\u7528\u65bc\u57fa\u790e\u79d1\u5b78\u7814\u7a76\u8207\u5730\u8cea\u5e74\u4ee3\u6e2c\u5b9a\u3002\u900f\u904e\u5206\u6790\u6c89\u7a4d\u7269\u4e2d\x20\u00b2\u00b3\u00b9\x50\x61\x20\u8207\x20\u00b2\u00b3\u2070\x54\x68\x20\u7684\u6bd4\u4f8b\uff0c\u6d77\u6d0b\u5b78\u5bb6\u80fd\u63a8\u7b97\u904e\u53bb\u5341\u842c\u5e74\u5167\u7684\u6d77\u6d0b\u5faa\u74b0\u8207\u6c89\u7a4d\u901f\u7387\uff0c\u9019\u5728\u53e4\u6c23\u5019\u5b78\u7814\u7a76\u4e2d\u5177\u5099\u6838\u5fc3\u50f9\u503c\u3002\u6b64\u5916\uff0c\u5728\u5148\u9032\u6838\u80fd\u7cfb\u7d71\u7814\u7a76\u4e2d\uff0c\u93f7\u662f\u91f7\u71c3\u6599\u5faa\u74b0\x28\x54\x68\x6f\x72\x69\x75\x6d\x20\x63\x79\x63\x6c\x65\x29\u4e2d\u7684\u95dc\u9375\u4e2d\u9593\u7522\u7269\uff1a\u00b2\u00b3\u00b2\x54\x68\x20\u6355\u6349\u4e2d\u5b50\u5f8c\u5148\u8f49\u5316\u70ba\x20\u00b2\u00b3\u00b3\x50\x61\uff0c\u518d\u8870\u8b8a\u70ba\u53ef\u5206\u88c2\u7684\x20\u00b2\u00b3\u00b3\x55\uff0c\u56e0\u6b64\u76e3\u63a7\u93f7\u7684\u7522\u91cf\u5c0d\u65bc\u8a2d\u8a08\u9ad8\u6548\u91f7\u53cd\u61c9\u7210\u81f3\u95dc\u91cd\u8981\u3002\x0a\x0a\u95dc\u65bc\u93f7\u7684\u7269\u7406\u73fe\u8c61\uff0c\u5b83\u5728\u6975\u7aef\u74b0\u5883\u4e0b\u5c55\u73fe\u51fa\u6709\u8da3\u7684\u7269\u7406\u7279\u6027\u3002\u93f7\u662f\u9312\u7cfb\u5143\u7d20\u4e2d\u5c11\u6578\u5177\u5099\u8d85\u5c0e\u6027\u7684\u6210\u54e1\uff0c\u5728\u7d55\u5c0d\u6eab\u5ea6\x20\x31\x2e\x34\x20\x4b\x20\u4ee5\u4e0b\u6703\u8868\u73fe\u51fa\u96f6\u96fb\u963b\u73fe\u8c61\u3002\u6b64\u5916\uff0c\u93f7\u91d1\u5c6c\u5177\u5099\u6975\u9ad8\u7684\u9ad4\u7a4d\u5f48\u6027\u6a21\u6578\uff0c\u9019\u53cd\u6620\u4e86\u5176\x20\x35\x66\x20\u96fb\u5b50\u5728\u6676\u683c\u4e2d\u7684\u5f37\u70c8\u53c3\u8207\u611f\u3002\u6709\u8da3\u7684\u662f\uff0c\u96d6\u7136\u93f7\u5728\u81ea\u7136\u754c\u4e2d\u4e3b\u8981\u5b58\u5728\u65bc\u923e\u7926\u4e2d\uff0c\u4f46\u5176\u6fc3\u5ea6\u50c5\u7d04\u767e\u842c\u5206\u4e4b\u4e00\uff0c\u9019\u4f7f\u5f97\u63d0\u7149\u93f7\u7684\u904e\u7a0b\u6bd4\u63d0\u7149\u9433\u66f4\u70ba\u8271\u8f9b\u3002\u9019\u7a2e\u5f9e\u300c\u9312\u4e4b\u7236\u300d\u7684\u6b77\u53f2\u547d\u540d\u5230\u4f5c\u70ba\u6d77\u6d0b\u5b9a\u5e74\u7cbe\u5bc6\u8a08\u6642\u5668\u7684\u8f49\u8b8a\uff0c\u7cbe\u78ba\u8a6e\u91cb\u4e86\u93f7\u5728\u9312\u7cfb\u5143\u7d20\u4e2d\u795e\u79d8\u4e14\u5177\u5099\u5b78\u8853\u6df1\u5ea6\u7684\u7279\u5fb5\u3002",
  "\x55":
    "\u923e\x28\x55\x72\x61\x6e\x69\x75\x6d\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x55\uff0c\u539f\u5b50\u5e8f\x20\x39\x32\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u4e03\u9031\u671f\u3001\u9312\u7cfb\u5143\u7d20\x28\x66\x20\u5340\u584a\x29\u3002\u5176\u540d\u7a31\u6e90\u65bc\x20\x31\x37\x38\x31\x20\u5e74\u767c\u73fe\u7684\u5929\u738b\u661f\x28\x55\x72\x61\x6e\x75\x73\x29\u3002\x31\x37\x38\x39\x20\u5e74\u7531\u5fb7\u570b\u5316\u5b78\u5bb6\u514b\u62c9\u666e\u7f85\u7279\x28\x4d\x61\x72\x74\x69\x6e\x20\x48\x65\x69\x6e\x72\x69\x63\x68\x20\x4b\x6c\x61\x70\x72\x6f\x74\x68\x29\u5728\u5206\u6790\u701d\u9752\u923e\u7926\u6642\u767c\u73fe\u3002\u923e\u662f\u81ea\u7136\u754c\u4e2d\u539f\u5b50\u5e8f\u6700\u5927\u7684\u539f\u751f\u5143\u7d20\uff0c\u5177\u5099\u9280\u767d\u8272\u7684\u91d1\u5c6c\u5149\u6fa4\u4e14\u5bc6\u5ea6\u6975\u9ad8\x28\u7d04\x20\x31\x39\x2e\x31\x20\x67\x2f\x63\x6d\u00b3\x29\u3002\u5b83\u662f\u73fe\u4ee3\u6838\u80fd\u6280\u8853\u8207\u5730\u8cea\u79d1\u5b78\u7684\u9748\u9b42\u5143\u7d20\uff0c\u5176\u6838\u5206\u88c2\u7522\u751f\u7684\u5de8\u5927\u80fd\u91cf\u76f4\u63a5\u6539\u8b8a\u4e86\u4eba\u985e\u7684\u80fd\u6e90\u7d50\u69cb\u8207\u5730\u7de3\u653f\u6cbb\u683c\u5c40\u3002\x0a\x0a\u5728\u5316\u5b78\u6027\u8cea\u4e0a\uff0c\u923e\u7684\u96fb\u5b50\u7d44\u614b\u70ba\x20\x5b\x52\x6e\x5d\x35\x66\u00b3\x36\x64\u00b9\x37\x73\u00b2\uff0c\u5177\u5099\u5f9e\x20\x2b\x33\x20\u5230\x20\x2b\x36\x20\u7684\u5bec\u5ee3\u6c27\u5316\u614b\u3002\u5176\u4e2d\x20\x2b\x36\x20\u50f9\u6700\u70ba\u7a69\u5b9a\uff0c\u901a\u5e38\u4ee5\u91af\u57fa\u96e2\u5b50\u300c\u923e\u91af\u96e2\u5b50\u300d\x28\x55\x4f\u2082\u00b2\u207a\x29\u7684\u5f62\u5f0f\u5b58\u5728\u65bc\u6c34\u6eb6\u6db2\u4e2d\uff0c\u5448\u73fe\u7279\u5fb5\u7684\u4eae\u9ec3\u8272\u3002\u5728\u9ad8\u4e2d\u5316\u5b78\u63a2\u8a0e\u6c27\u5316\u9084\u539f\u8207\u914d\u4f4d\u5316\u5b78\u6642\uff0c\u923e\u7684\u591a\u8b8a\u50f9\u614b\u8207\u932f\u5408\u7269\u986f\u8272\u53cd\u61c9\u662f\u9032\u968e\u7814\u7a76\u7684\u91cd\u9ede\u3002\u91d1\u5c6c\u923e\u6975\u5177\u5316\u5b78\u6d3b\u6027\uff0c\u5728\u7a7a\u6c23\u4e2d\u6703\u8fc5\u901f\u751f\u6210\u9ed1\u8272\u6c27\u5316\u5c64\uff0c\u4e14\u5176\u7d30\u788e\u7c89\u672b\u5177\u5099\u300c\u81ea\u71c3\u6027\u300d\x28\x50\x79\x72\x6f\x70\x68\x6f\x72\x69\x63\x29\u3002\u923e\u7684\u4e3b\u8981\u540c\u4f4d\u7d20\u5305\u62ec\x20\u00b2\u00b3\u2078\x55\x20\u8207\u5177\u5099\u6838\u5206\u88c2\u7279\u6027\u7684\x20\u00b2\u00b3\u2075\x55\uff0c\u5f8c\u8005\u662f\u6838\u5b50\u9023\u9396\u53cd\u61c9\u7684\u7269\u8cea\u57fa\u790e\u3002\x0a\x0a\u5728\u53f0\u7063\u9ad8\u4e2d\u8ab2\u7db1\u8207\u5168\u7403\u80fd\u6e90\u8108\u7d61\u4e2d\uff0c\u923e\u662f\u5b9a\u7fa9\u300c\u6838\u80fd\u300d\u7684\u6838\u5fc3\u89c0\u5ff5\u3002\u900f\u904e\u923e\u6fc3\u7e2e\x28\x45\x6e\x72\x69\x63\x68\x6d\x65\x6e\x74\x29\u6280\u8853\u63d0\u5347\x20\u00b2\u00b3\u2075\x55\x20\u7684\u6bd4\u4f8b\uff0c\u53ef\u88fd\u6210\u6838\u53cd\u61c9\u7210\u7684\u71c3\u6599\u68d2\u6216\u6838\u6b66\u5668\u3002\u5728\u6750\u6599\u5de5\u7a0b\u4e2d\uff0c\u812b\u9776\u5f8c\u7684\u300c\u8ca7\u923e\u300d\x28\x44\x65\x70\x6c\x65\x74\x65\x64\x20\x55\x72\x61\x6e\x69\x75\x6d\x2c\x20\x44\x55\x29\u56e0\u5176\u6975\u9ad8\u5bc6\u5ea6\u8207\u786c\u5ea6\uff0c\u88ab\u88fd\u6210\u6230\u8eca\u88dd\u7532\u6216\u7a7f\u7532\u5f48\u3002\u5728\u5730\u7403\u79d1\u5b78\u9818\u57df\uff0c\u923e\uff0d\u925b\u5b9a\u5e74\u6cd5\x28\x55\x2d\x50\x62\x20\x64\x61\x74\x69\x6e\x67\x29\u5229\u7528\u5176\u9577\u534a\u8870\u671f\u7684\u653e\u5c04\u6027\u8870\u8b8a\uff0c\u7cbe\u78ba\u6e2c\u5b9a\u4e86\u5730\u7403\u7684\u5e74\u9f61\x28\u7d04\x20\x34\x35\x2e\x34\x20\u5104\u5e74\x29\u3002\u6b64\u5916\uff0c\u923e\u5316\u5408\u7269\u5728\u5de5\u696d\u4e0a\u66fe\u88ab\u7528\u4f5c\u9676\u74f7\u91c9\u6599\u8207\u9ec3\u7da0\u8272\u7684\u300c\u923e\u73bb\u7483\u300d\uff0c\u5176\u5728\u7d2b\u5916\u7dda\u4e0b\u767c\u51fa\u7684\u5f37\u70c8\u7da0\u8272\u87a2\u5149\uff0c\u81f3\u4eca\u4ecd\u662f\u73bb\u7483\u6536\u85cf\u754c\u7684\u5947\u73cd\u3002\x0a\x0a\u923e\u5728\u73fe\u8c61\u5b78\u4e0a\u5c55\u73fe\u4e86\u7269\u8cea\u8207\u80fd\u91cf\u9ad8\u5ea6\u8f49\u63db\u7684\u7279\u5fb5\u3002\u6bcf\u514b\x20\u00b2\u00b3\u2075\x55\x20\u5206\u88c2\u91cb\u653e\u7684\u80fd\u91cf\u7d04\u7b49\u65bc\x20\x33\x20\u516c\u5678\u7164\u70ad\u71c3\u71d2\u7522\u751f\u7684\u71b1\u80fd\uff0c\u9019\u7a2e\u9a5a\u4eba\u7684\u80fd\u91cf\u5bc6\u5ea6\u78ba\u7acb\u4e86\u5176\u80fd\u6e90\u9738\u6b0a\u5730\u4f4d\u3002\u53cd\u76f4\u89ba\u7684\u662f\uff0c\u96d6\u7136\u91d1\u5c6c\u923e\u5177\u5099\u5f37\u653e\u5c04\u6027\uff0c\u4f46\u5728\u584a\u9ad4\u72c0\u614b\u4e0b\u5176\u8f3b\u5c04\u4e3b\u8981\u7531\x20\u03b1\x20\u7c92\u5b50\u7d44\u6210\uff0c\u4e00\u5f35\u7d19\u5373\u53ef\u963b\u9694\uff0c\u4e3b\u8981\u7684\u74b0\u5883\u5a01\u8105\u4f86\u81ea\u65bc\u5176\u5316\u5b78\u6bd2\u6027\u5c0d\u814e\u81df\u7684\u640d\u50b7\u3002\u6709\u8da3\u7684\u662f\uff0c\u923e\u662f\u6975\u5c11\u6578\u80fd\u5448\u73fe\u9806\u78c1\u6027\u4e14\u5728\u8d85\u4f4e\u6eab\u4e0b\u5c55\u73fe\u8d85\u5c0e\u7279\u6027\u7684\u91cd\u5143\u7d20\u3002\u9019\u7a2e\u5f9e\u661f\u7a7a\u4e4b\u540d\u5230\u652f\u6490\u5168\u7403\u96fb\u529b\u4f9b\u61c9\u8207\u63ed\u958b\u5730\u7403\u8eab\u4e16\u4e4b\u8b0e\u7684\u8de8\u5ea6\uff0c\u7cbe\u78ba\u8a6e\u91cb\u4e86\u923e\u5728\u9031\u671f\u8868\u4e2d\u539a\u91cd\u4e14\u6975\u5177\u885d\u64ca\u529b\u7684\u89d2\u8272\u3002",
  "\x4e\x70":
    "\u933c\x28\x4e\x65\x70\x74\x75\x6e\x69\x75\x6d\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x4e\x70\uff0c\u539f\u5b50\u5e8f\x20\x39\x33\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u4e03\u9031\u671f\u3001\u9312\u7cfb\u5143\u7d20\x28\x66\x20\u5340\u584a\x29\u3002\u5176\u540d\u7a31\u6e90\u65bc\u6d77\u738b\u661f\x28\x4e\x65\x70\x74\x75\x6e\x65\x29\uff0c\u7dca\u96a8\u4ee5\u5929\u738b\u661f\u547d\u540d\u7684\u923e\u4e4b\u5f8c\u3002\x31\x39\x34\x30\x20\u5e74\u7531\u9ea5\u514b\u7c73\u502b\x28\x45\x64\x77\x69\x6e\x20\x4d\x63\x4d\x69\x6c\x6c\x61\x6e\x29\u8207\u827e\u8c9d\u723e\u68ee\x28\x50\x68\x69\x6c\x69\x70\x20\x41\x62\x65\x6c\x73\x6f\x6e\x29\u5728\u67cf\u514b\u840a\u52a0\u5dde\u5927\u5b78\u5229\u7528\u4e2d\u5b50\u8f5f\u64ca\u923e\u9776\u9996\u6b21\u6210\u529f\u4eba\u5de5\u5408\u6210\uff0c\u6210\u70ba\u4eba\u985e\u53f2\u4e0a\u7b2c\u4e00\u500b\u88ab\u88fd\u5f97\u7684\u300c\u8d85\u923e\u5143\u7d20\u300d\x28\x54\x72\x61\x6e\x73\x75\x72\x61\x6e\x69\x75\x6d\x20\x65\x6c\x65\x6d\x65\x6e\x74\x29\u3002\u933c\u662f\u4e00\u7a2e\u9280\u767d\u8272\u7684\u653e\u5c04\u6027\u91d1\u5c6c\uff0c\u4e3b\u8981\u4ee5\u6838\u53cd\u61c9\u7210\u7684\u526f\u7522\u7269\u5b58\u5728\uff0c\u662f\u9023\u7d50\u923e\u8207\u923d\u4e4b\u9593\u95dc\u9375\u7684\u6838\u7269\u7406\u6a4b\u6a11\u3002\x0a\x0a\u5728\u5316\u5b78\u884c\u70ba\u4e0a\uff0c\u933c\u7684\u96fb\u5b50\u7d44\u614b\u70ba\x20\x5b\x52\x6e\x5d\x35\x66\u2074\x36\x64\u00b9\x37\x73\u00b2\u3002\u933c\u7684\u6c27\u5316\u614b\u7bc4\u570d\u6975\u5ee3\x28\u7531\x20\x2b\x33\x20\u81f3\x20\x2b\x37\x29\uff0c\u9019\u4f7f\u5176\u5316\u5b78\u6027\u8cea\u5c55\u73fe\u51fa\u4ecb\u65bc\u923e\u8207\u923d\u4e4b\u9593\u7684\u904e\u6e21\u7279\u8cea\u3002\u5728\u6c34\u6eb6\u6db2\u4e2d\uff0c\u4e0d\u540c\u6c27\u5316\u614b\u7684\u933c\u96e2\u5b50\u5c55\u73fe\u51fa\u8c50\u5bcc\u7684\u8272\u5f69\uff1a\x2b\x33\x20\u50f9\u70ba\u6de1\u7d2b\u8272\u3001\x2b\x34\x20\u50f9\u70ba\u6de1\u7da0\u8272\u3001\x2b\x35\x20\u50f9\u70ba\u85cd\u7da0\u8272\x28\x4e\x70\x4f\u2082\u207a\x29\uff0c\u800c\u6700\u9ad8\u50f9\u7684\x20\x2b\x37\x20\u50f9\u5247\u5448\u73fe\u6df1\u7da0\u8272\u3002\u5728\u9ad8\u4e2d\u5316\u5b78\u63a2\u8a0e\u96fb\u5b50\u5c64\u7d50\u69cb\u8207\u6c27\u5316\u614b\u7a69\u5b9a\u6027\u6642\uff0c\u933c\u662f\u8aaa\u660e\x20\x35\x66\x20\u96fb\u5b50\u5982\u4f55\u96a8\u8457\u539f\u5b50\u5e8f\u589e\u52a0\u800c\u9010\u6f38\u300c\u5b9a\u57df\u5316\u300d\u7684\u5178\u578b\u4f8b\u8b49\u3002\u91d1\u5c6c\u933c\u5177\u5099\u8f03\u9ad8\u7684\u5316\u5b78\u6d3b\u6027\uff0c\u80fd\u8207\u6c27\u3001\u84b8\u6c7d\u8207\u591a\u6578\u9178\u767c\u751f\u53cd\u61c9\u3002\x0a\x0a\u5728\u73fe\u4ee3\u61c9\u7528\u8207\u6838\u80fd\u7ba1\u7406\u4e2d\uff0c\u933c\u7684\u4e3b\u8981\u89d2\u8272\u662f\u4f5c\u70ba\u300c\u540c\u4f4d\u7d20\u751f\u7522\u7684\u524d\u9a45\u7269\u300d\u3002\u6700\u91cd\u8981\u7684\u540c\u4f4d\u7d20\x20\u00b2\u00b3\u2077\x4e\x70\x28\u534a\u8870\u671f\u7d04\x20\x32\x31\x34\x20\u842c\u5e74\x29\u5728\u6355\u6349\u4e2d\u5b50\u5f8c\u6703\u8f49\u5316\u70ba\x20\u00b2\u00b3\u2078\x4e\x70\uff0c\u96a8\u5f8c\u8870\u8b8a\u7522\u751f\x20\u00b2\u00b3\u2078\x50\x75\u3002\u7531\u65bc\x20\u00b2\u00b3\u2078\x50\x75\x20\u662f\u88fd\u9020\u822a\u592a\u7528\u300c\u653e\u5c04\u6027\u540c\u4f4d\u7d20\u71b1\u96fb\u6a5f\u300d\x28\x52\x54\x47\x29\u7684\u6838\u5fc3\u71c3\u6599\x28\u5982\u7528\u65bc\u822a\u6d77\u5bb6\u865f\u6216\u6bc5\u529b\u865f\u706b\u661f\u8eca\x29\uff0c\u56e0\u6b64\u933c\u7684\u56de\u6536\u8207\u88fd\u5099\u662f\u6df1\u7a7a\u63a2\u6e2c\u6280\u8853\u7684\u80fd\u6e90\u57fa\u77f3\u3002\u6b64\u5916\uff0c\u933c\u5728\u9577\u6548\u6838\u5ee2\u6599\u7ba1\u7406\u4e2d\u4ea6\u662f\u95dc\u9375\u7269\u7a2e\uff0c\u56e0\u5176\u534a\u8870\u671f\u9577\u4e14\u5728\u5730\u4e0b\u6c34\u4e2d\u5177\u5099\u4e00\u5b9a\u7684\u9077\u79fb\u6027\uff0c\u5176\u74b0\u5883\u884c\u70ba\u662f\u6838\u5b50\u5de5\u7a0b\u5b89\u5168\u6027\u8a55\u4f30\u7684\u91cd\u9ede\u3002\x0a\x0a\u933c\u5728\u7269\u7406\u6027\u8cea\u4e0a\u5c55\u73fe\u4e86\u986f\u8457\u7684\u300c\u591a\u6676\u578b\u6027\u300d\x28\x41\x6c\x6c\x6f\x74\x72\x6f\x70\x79\x29\u3002\u5b83\u81f3\u5c11\u64c1\u6709\u4e09\u7a2e\u4e0d\u540c\u7684\u6676\u9ad4\u7d50\u69cb\uff0c\u5176\u5bc6\u5ea6\u96a8\u76f8\u8b8a\u800c\u986f\u8457\u6539\u8b8a\uff0c\u9019\u7a2e\u6027\u8cea\u6e90\u65bc\x20\x35\x66\x20\u96fb\u5b50\u5728\u6676\u683c\u9375\u7d50\u4e2d\u8907\u96dc\u7684\u53c3\u8207\u6a21\u5f0f\u3002\u6709\u8da3\u7684\u662f\uff0c\u933c\u662f\u6975\u5c11\u6578\u5177\u5099\u8d85\u5c0e\u6027\u7684\u9312\u7cfb\u5143\u7d20\u4e4b\u4e00\uff0c\u4e14\u5176\u5728\u9ad8\u58d3\u4e0b\u5c55\u73fe\u51fa\u8c50\u5bcc\u7684\u78c1\u5b78\u884c\u70ba\u3002\u96d6\u7136\u81ea\u7136\u754c\u4e2d\u6975\u5fae\u91cf\u7684\u933c\u5b58\u5728\u65bc\u923e\u7926\u4e2d\x28\u6e90\u65bc\u5929\u7136\u4e2d\u5b50\u6355\u7372\x29\uff0c\u4f46\u5176\u5b8f\u89c0\u6a23\u672c\u5168\u8cf4\u4eba\u5de5\u5408\u6210\u3002\u9019\u7a2e\u5f9e\u79d1\u5b78\u5be6\u9a57\u5ba4\u4e2d\u8de8\u8d8a\u8d85\u923e\u754c\u7dda\u7684\u7a81\u7834\uff0c\u5230\u652f\u6490\u4eba\u985e\u63a2\u7d22\u592a\u967d\u7cfb\u908a\u7de3\u7684\u80fd\u6e90\u4f9b\u61c9\uff0c\u7cbe\u78ba\u8a6e\u91cb\u4e86\u933c\u5728\u9031\u671f\u8868\u4e2d\u300c\u627f\u5148\u555f\u5f8c\u300d\u7684\u7368\u7279\u5730\u4f4d\u3002",
  "\x50\x75":
    "\u923d\x28\x50\x6c\x75\x74\x6f\x6e\x69\x75\x6d\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x50\x75\uff0c\u539f\u5b50\u5e8f\x20\x39\x34\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u4e03\u9031\u671f\u3001\u9312\u7cfb\u5143\u7d20\x28\x66\x20\u5340\u584a\x29\u3002\u5176\u540d\u7a31\u6e90\u65bc\u51a5\u738b\u661f\x28\x50\x6c\x75\x74\x6f\x29\uff0c\u5ef6\u7e8c\u4e86\u9312\u7cfb\u5143\u7d20\u4ee5\u884c\u661f\u547d\u540d\u7684\u50b3\u7d71\u3002\x31\x39\x34\x30\x20\u5e74\u7531\u5e2d\u535a\u683c\x28\x47\x6c\x65\x6e\x6e\x20\x54\x2e\x20\x53\x65\x61\x62\x6f\x72\x67\x29\u9818\u5c0e\u7684\u5718\u968a\u5229\u7528\u6c18\u6838\u8f5f\u64ca\u923e\u9776\u9996\u6b21\u767c\u73fe\u3002\u923d\u662f\u4e00\u7a2e\u5177\u5099\u5f37\u70c8\u653e\u5c04\u6027\u4e14\u5316\u5b78\u6027\u8cea\u6975\u5176\u8907\u96dc\u7684\u9280\u767d\u8272\u91d1\u5c6c\u3002\u5b83\u662f\u76ee\u524d\u4eba\u985e\u6587\u660e\u4e2d\u6700\u53d7\u77da\u76ee\u4e5f\u6700\u5177\u722d\u8b70\u7684\u5143\u7d20\u4e4b\u4e00\uff0c\u4e0d\u50c5\u662f\u6838\u6b66\u5668\u8207\u6838\u80fd\u96fb\u5ee0\u7684\u9ad8\u6548\u71c3\u6599\uff0c\u4ea6\u662f\u822a\u592a\u63a2\u6e2c\u4e2d\u4e0d\u53ef\u6216\u7f3a\u7684\u52d5\u529b\u5fc3\u81df\u3002\x0a\x0a\u5728\u5fae\u89c0\u7d50\u69cb\u4e0a\uff0c\u923d\u7684\u96fb\u5b50\u7d44\u614b\u70ba\x20\x5b\x52\x6e\x5d\x35\x66\u2076\x37\x73\u00b2\u3002\u923d\u5177\u5099\u5f9e\x20\x2b\x33\x20\u5230\x20\x2b\x37\x20\u7684\u4e94\u7a2e\u7a69\u5b9a\u6c27\u5316\u614b\uff0c\u4e14\u5728\u6eb6\u6db2\u4e2d\u5e38\u767c\u751f\u5287\u70c8\u7684\u6b67\u5316\u53cd\u61c9\uff0c\u751a\u81f3\u53ef\u80fd\u5728\u55ae\u4e00\u6eb6\u6db2\u4e2d\u540c\u6642\u5171\u5b58\u56db\u7a2e\u6c27\u5316\u614b\uff0c\u9019\u5728\u9031\u671f\u8868\u4e2d\u6975\u70ba\u7f55\u898b\u3002\u5728\u9ad8\u4e2d\u5316\u5b78\u63a2\u8a0e\u591a\u91cd\u5e73\u8861\u8207\u8907\u96dc\u96e2\u5b50\u984f\u8272\u6642\uff0c\u923d\u662f\u6975\u9650\u6848\u4f8b\uff1a\x2b\x33\x20\u50f9\u5448\u6de1\u7d2b\u8272\u3001\x2b\x34\x20\u50f9\u5448\u68d5\u8272\u3001\x2b\x35\x20\u50f9\u5448\u7c89\u7d05\u8272\x28\x50\x75\x4f\u2082\u207a\x29\u3001\x2b\x36\x20\u50f9\u5247\u5448\u73fe\u6a58\u9ec3\u8272\x28\x50\x75\x4f\u2082\u00b2\u207a\x29\u3002\u91d1\u5c6c\u923d\u5177\u5099\u6975\u9ad8\u7684\u5316\u5b78\u53cd\u61c9\u6027\uff0c\u6613\u8207\u7a7a\u6c23\u3001\u6c34\u5206\u53ca\u591a\u6578\u9178\u53cd\u61c9\uff0c\u4e14\u5176\u653e\u5c04\u6027\u8870\u8b8a\u7522\u751f\u7684\u300c\u81ea\u52a0\u71b1\u300d\u73fe\u8c61\uff0c\u4f7f\u5f97\u5927\u584a\u91d1\u5c6c\u923d\u89f8\u6478\u6642\u5e38\u5e36\u6709\u6eab\u71b1\u611f\u3002\x0a\x0a\u5728\u53f0\u7063\u9ad8\u4e2d\u8ab2\u7db1\u8207\u80fd\u6e90\u6280\u8853\u8108\u7d61\u4e2d\uff0c\u00b2\u00b3\u2079\x50\x75\x20\u540c\u4f4d\u7d20\u662f\u5b9a\u7fa9\u300c\u6838\u88c2\u8b8a\u300d\u7684\u91cd\u8981\u95dc\u9375\u5b57\u3002\u900f\u904e\u6838\u53cd\u61c9\u7210\u4e2d\u7684\x20\u00b2\u00b3\u2078\x55\x20\u6355\u6349\u4e2d\u5b50\uff0c\u53ef\u5927\u898f\u6a21\u751f\u7522\x20\u00b2\u00b3\u2079\x50\x75\uff0c\u9019\u4f7f\u5176\u6210\u70ba\u300c\u6df7\u5408\u6c27\u5316\u7269\u71c3\u6599\u300d\x28\x4d\x4f\x58\x29\u8207\u6230\u7565\u6838\u6b66\u7684\u6838\u5fc3\u3002\u5728\u6c11\u751f\u8207\u79d1\u5b78\u63a2\u7d22\u65b9\u9762\uff0c\u00b2\u00b3\u2078\x50\x75\x20\u540c\u4f4d\u7d20\u56e0\u5176\u6975\u9ad8\u7684\u529f\u7387\u5bc6\u5ea6\u4e14\u767c\u5c04\u7d14\u6de8\u7684\x20\u03b1\x20\u5c04\u7dda\x28\u6613\u65bc\u5c4f\u853d\x29\uff0c\u88ab\u5ee3\u6cdb\u7528\u4f5c\u300c\u653e\u5c04\u6027\u540c\u4f4d\u7d20\u71b1\u96fb\u6a5f\u300d\x28\x52\x54\x47\x29\u7684\u71b1\u6e90\uff0c\u652f\u6490\u4e86\u65c5\u884c\u8005\u865f\u3001\u65b0\u5730\u5e73\u7dda\u865f\u53ca\u6bc5\u529b\u865f\u7b49\u9577\u671f\u6df1\u7a7a\u4efb\u52d9\u3002\u7136\u800c\uff0c\u923d\u5177\u5099\u6975\u9ad8\u7684\u751f\u7269\u6bd2\u6027\u8207\u5316\u5b78\u6bd2\u6027\uff0c\u4e00\u65e6\u9032\u5165\u4eba\u9ad4\u6703\u7a4d\u805a\u65bc\u9aa8\u9abc\u8207\u80ba\u90e8\u9020\u6210\u9577\u671f\u640d\u50b7\u3002\x0a\x0a\u923d\u5728\u7269\u7406\u6027\u8cea\u4e0a\u5c55\u73fe\u4e86\u91d1\u5c6c\u754c\u4e2d\u6700\u53cd\u76f4\u89ba\u7684\u7279\u5fb5\u3002\u5b83\u64c1\u6709\u516d\u7a2e\u540c\u7d20\u7570\u5f62\u9ad4\uff0c\u4e14\u5404\u76f8\u9593\u7684\u5bc6\u5ea6\u5dee\u7570\u9ad8\u9054\x20\x32\x35\x25\u3002\u6700\u5947\u7279\u7684\u662f\uff0c\u5176\x20\u03b4\x20\u76f8\u5728\u53d7\u71b1\u6642\u6703\u767c\u751f\u6536\u7e2e\u800c\u975e\u81a8\u8139\uff0c\u9019\u7a2e\u300c\u8ca0\u71b1\u81a8\u8139\u300d\u884c\u70ba\u8207\u6c34\u5728\u7279\u5b9a\u6eab\u5ea6\u7684\u6027\u8cea\u76f8\u4f3c\uff0c\u4f46\u5728\u91d1\u5c6c\u4e2d\u6975\u5176\u7f55\u898b\u3002\u6b64\u5916\uff0c\u923d\u5728\u51dd\u56fa\u6642\u9ad4\u7a4d\u6703\u81a8\u8139\x28\u985e\u4f3c\u65bc\u924d\u8207\u51b0\x29\uff0c\u9019\u4f7f\u5f97\u7cbe\u5bc6\u9444\u9020\u923d\u96f6\u4ef6\u8b8a\u5f97\u7570\u5e38\u56f0\u96e3\u3002\u9019\u7a2e\u5f9e\u5b9a\u7fa9\u5927\u570b\u6230\u7565\u5e73\u8861\u7684\u5a01\u529b\u5230\u9a45\u52d5\u4eba\u985e\u6307\u91dd\u5411\u5916\u592a\u7a7a\u6df1\u8655\u822a\u884c\u7684\u80fd\u91cf\uff0c\u7cbe\u78ba\u8a6e\u91cb\u4e86\u923d\u5728\u9031\u671f\u8868\u4e2d\u4f5c\u70ba\u300c\u80fd\u91cf\u8207\u8907\u96dc\u6027\u5dd4\u5cf0\u300d\u7684\u6df1\u6c89\u9b45\u529b\u3002",
  "\x41\x6d":
    "\u92c2\x28\x41\x6d\x65\x72\x69\x63\x69\x75\x6d\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x41\x6d\uff0c\u539f\u5b50\u5e8f\x20\x39\x35\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u4e03\u9031\u671f\u3001\u9312\u7cfb\u5143\u7d20\x28\x66\x20\u5340\u584a\x29\u3002\u5176\u540d\u7a31\u6e90\u65bc\u7f8e\u6d32\x28\x41\x6d\x65\x72\x69\x63\x61\x73\x29\uff0c\u4ee5\u5c0d\u61c9\u5176\u4e0a\u65b9\u946d\u7cfb\u5143\u7d20\u92aa\x28\x45\x75\x72\x6f\x70\x69\x75\x6d\uff0c\u6e90\u65bc\u6b50\u6d32\x29\u7684\u547d\u540d\u898f\u5f8b\u3002\x31\x39\x34\x34\x20\u5e74\u7531\u5e2d\u535a\u683c\x28\x47\x6c\x65\x6e\x6e\x20\x54\x2e\x20\x53\x65\x61\x62\x6f\x72\x67\x29\u9818\u5c0e\u7684\u5718\u968a\u5728\u829d\u52a0\u54e5\u5927\u5b78\u51b6\u91d1\u5be6\u9a57\u5ba4\u4e2d\uff0c\u5229\u7528\u4e2d\u5b50\u8f5f\u64ca\u923d\x2d\x32\x33\x39\x20\u9996\u6b21\u4eba\u5de5\u5408\u6210\u3002\u92c2\u662f\u4e00\u7a2e\u5177\u5099\u5f37\u70c8\u653e\u5c04\u6027\u7684\u9280\u767d\u8272\u91d1\u5c6c\uff0c\u662f\u8d85\u923e\u5143\u7d20\u4e2d\u5c11\u6578\u8207\u5927\u773e\u751f\u6d3b\u6709\u76f4\u63a5\u9023\u7d50\u7684\u6210\u54e1\uff0c\u5176\u5316\u5b78\u6027\u8cea\u6d3b\u6f51\u4e14\u5177\u5099\u986f\u8457\u7684\u767c\u5149\u7279\u5fb5\u3002\x0a\x0a\u92c2\u7684\u96fb\u5b50\u7d44\u614b\u70ba\x20\x5b\x52\x6e\x5d\x35\x66\u2077\x37\x73\u00b2\uff0c\u5c55\u73fe\u4e86\u6975\u5176\u7a69\u5b9a\u7684\u300c\u534a\u586b\u6eff\u300d\x35\x66\u2077\x20\u7d50\u69cb\u3002\u9019\u4f7f\u5f97\u92c2\u5728\u5316\u5b78\u6027\u8cea\u4e0a\u9664\u4e86\u5e38\u898b\u7684\x20\x2b\x33\x20\u6c27\u5316\u614b\u5916\uff0c\u4ea6\u80fd\u5c55\u73fe\u51fa\u8f03\u70ba\u7a69\u5b9a\u7684\u9ad8\u50f9\u614b\x28\u5982\x20\x2b\x34\u3001\x2b\x35\u3001\x2b\x36\x29\uff0c\u5176\u4e2d\u92c2\u91af\u96e2\u5b50\x28\x41\x6d\x4f\u2082\u207a\u3001\x41\x6d\x4f\u2082\u00b2\u207a\x29\u8207\u5176\u540c\u65cf\u7684\u92aa\x28\x45\x75\x29\u5c55\u73fe\u51fa\u4e0d\u540c\u7684\u50f9\u614b\u5206\u5e03\u908f\u8f2f\u3002\u5728\u9ad8\u4e2d\u5316\u5b78\u63a2\u8a0e\u539f\u5b50\u8ecc\u57df\u7a69\u5b9a\u6027\u6642\uff0c\u92c2\u662f\u8aaa\u660e\x20\x35\x66\x20\u96fb\u5b50\u4e91\u5982\u4f55\u5f71\u97ff\u91cd\u6838\u5143\u7d20\u7269\u7406\u7279\u5fb5\u7684\u5178\u578b\u6848\u4f8b\u3002\u91d1\u5c6c\u92c2\u5728\u7a7a\u6c23\u4e2d\u6703\u7de9\u6162\u5931\u53bb\u5149\u6fa4\uff0c\u4e14\u7531\u65bc\u5176\u91cb\u653e\u7684\u653e\u5c04\u6027\u80fd\u91cf\uff0c\u5927\u584a\u7684\u92c2\u5728\u6697\u8655\u6703\u767c\u51fa\u5fae\u5f31\u7684\u5149\u8292\u3002\x0a\x0a\u5728\u73fe\u4ee3\u61c9\u7528\u4e2d\uff0c\u92c2\x2d\x32\x34\x31\x28\u00b2\u2074\u00b9\x41\x6d\x29\u662f\u5bb6\u7528\u96e2\u5b50\u5f0f\u7159\u9727\u5075\u6e2c\u5668\u7684\u6838\u5fc3\u7d44\u4ef6\u3002\u5b83\u5229\u7528\x20\u03b1\x20\u8870\u8b8a\u96fb\u96e2\u5075\u6e2c\u5ba4\u5167\u7684\u7a7a\u6c23\uff0c\u5f62\u6210\u5fae\u5f31\u96fb\u6d41\uff1b\u7576\u7159\u9727\u9846\u7c92\u9032\u5165\u4e26\u9644\u8457\u5728\u96e2\u5b50\u4e0a\u6642\uff0c\u96fb\u6d41\u6703\u56e0\u96fb\u5c0e\u7387\u4e0b\u964d\u800c\u89f8\u767c\u8b66\u5831\uff0c\u5c55\u73fe\u4e86\u653e\u5c04\u6027\u540c\u4f4d\u7d20\u5728\u611f\u6e2c\u6280\u8853\u4e2d\u7684\u7cbe\u5bc6\u61c9\u7528\u3002\u6b64\u5916\uff0c\u92c2\u8207\u9239\u7d50\u5408\u53ef\u88fd\u6210\x20\x41\x6d\x2d\x42\x65\x20\u4e2d\u5b50\u6e90\uff0c\u5ee3\u6cdb\u61c9\u7528\u65bc\u77f3\u6cb9\u6e2c\u4e95\u8207\u6750\u6599\u7121\u640d\u6aa2\u6e2c\u3002\u5728\u91ab\u5b78\u7814\u7a76\u4e0a\uff0c\u92c2\u7684\u653e\u5c04\u6027\u4ea6\u66fe\u88ab\u63a2\u8a0e\u7528\u65bc\u88fd\u5099\u9ad8\u54c1\u8cea\u7684\u8a3a\u65b7\u7528\x20\u03b3\x20\u5c04\u7dda\u6e90\uff0c\u96d6\u7136\u73fe\u4ee3\u591a\u5df2\u88ab\u5176\u4ed6\u540c\u4f4d\u7d20\u53d6\u4ee3\u3002\x0a\x0a\u92c2\u5728\u7269\u7406\u73fe\u8c61\u4e0a\u8868\u73fe\u51fa\u986f\u8457\u7684\u300c\u81ea\u767c\u5149\u300d\u7279\u5fb5\uff0c\u5176\u9ad8\u5ea6\u653e\u5c04\u6027\u7522\u751f\u7684\u71b1\u80fd\u8db3\u4ee5\u4f7f\u5176\u5316\u5408\u7269\u5728\u53d7\u6fc0\u767c\u6642\u767c\u51fa\u6de1\u7da0\u8272\u6216\u6de1\u9ec3\u8272\u7684\u5149\u3002\u6709\u8da3\u7684\u662f\uff0c\u96d6\u7136\u92c2\u662f\u4eba\u5de5\u5408\u6210\u5143\u7d20\uff0c\u4f46\u6975\u5fae\u91cf\u7684\u92c2\u53ef\u5728\u5929\u7136\u923e\u7926\u4e2d\u56e0\u4e2d\u5b50\u4fd8\u7372\u800c\u7522\u751f\uff0c\u9019\u6253\u7834\u4e86\u4eba\u9020\u5143\u7d20\u8207\u5929\u7136\u5143\u7d20\u9593\u7684\u7d55\u5c0d\u754c\u9650\u3002\u53cd\u76f4\u89ba\u7684\u662f\uff0c\u92c2\u5728\u6db2\u9ad4\u4e2d\u7684\u984f\u8272\u6703\u96a8\u6c27\u5316\u614b\u767c\u751f\u6232\u5287\u6027\u8b8a\u5316\uff1a\x2b\x33\x20\u50f9\u70ba\u6de1\u7c89\u7d05\u8272\u3001\x2b\x36\x20\u50f9\u5247\u70ba\u9ec3\u8910\u8272\u3002\u9019\u7a2e\u5f9e\u5b88\u8b77\u5c45\u5bb6\u5b89\u5168\u7684\u5075\u6e2c\u5668\u5230\u5b9a\u7fa9\u8d85\u923e\u5143\u7d20\u96fb\u5b50\u6392\u5e03\u898f\u5f8b\u7684\u89d2\u8272\uff0c\u7cbe\u78ba\u8a6e\u91cb\u4e86\u92c2\u5728\u9312\u7cfb\u5143\u7d20\u4e2d\u7a69\u5b9a\u8207\u52d5\u614b\u517c\u5177\u7684\u5730\u4f4d\u3002",
  "\x43\x6d":
    "\u92e6\x28\x43\x75\x72\x69\x75\x6d\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x43\x6d\uff0c\u539f\u5b50\u5e8f\x20\x39\x36\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u4e03\u9031\u671f\u3001\u9312\u7cfb\u5143\u7d20\x28\x66\x20\u5340\u584a\x29\u3002\u5176\u540d\u7a31\u662f\u70ba\u4e86\u7d00\u5ff5\u653e\u5c04\u6027\u7814\u7a76\u5148\u9a45\u76ae\u8036\u00b7\u5c45\u79ae\x28\x50\x69\x65\x72\x72\x65\x20\x43\x75\x72\x69\x65\x29\u8207\u746a\u9e97\u00b7\u5c45\u79ae\x28\x4d\x61\x72\x69\x65\x20\x43\x75\x72\x69\x65\x29\u592b\u5a66\u3002\x31\x39\x34\x34\x20\u5e74\u7531\u5e2d\u535a\u683c\u5718\u968a\u5229\u7528\u8ff4\u65cb\u52a0\u901f\u5668\u8f5f\u64ca\u923d\x2d\x32\x33\x39\x20\u9996\u6b21\u88fd\u5f97\u3002\u92e6\u662f\u4e00\u7a2e\u5177\u6709\u9280\u767d\u8272\u5149\u6fa4\u7684\u91d1\u5c6c\uff0c\u786c\u5ea6\u6975\u9ad8\u4e14\u5316\u5b78\u6027\u8cea\u6975\u5176\u6d3b\u6f51\u3002\u5b83\u662f\u8d85\u923e\u5143\u7d20\u7814\u7a76\u4e2d\u6975\u70ba\u91cd\u8981\u7684\u71b1\u6e90\u8207\u7c92\u5b50\u6e90\u6750\u6599\uff0c\u6a19\u8a8c\u8457\u4eba\u985e\u5c0d\u91cd\u6838\u5143\u7d20\u638c\u63a7\u80fd\u529b\u9032\u5165\u4e86\u9ad8\u80fd\u7269\u7406\u7684\u65b0\u968e\u6bb5\u3002\x0a\x0a\u92e6\u7684\u96fb\u5b50\u7d44\u614b\u70ba\x20\x5b\x52\x6e\x5d\x35\x66\u2077\x36\x64\u00b9\x37\x73\u00b2\uff0c\u5176\x20\x35\x66\x20\u8ecc\u57df\u8655\u65bc\u5b8c\u7f8e\u7684\u534a\u586b\u6eff\u72c0\u614b\u3002\u9019\u7a2e\u9ad8\u5ea6\u5c0d\u7a31\u7684\u96fb\u5b50\u5206\u5e03\u4f7f\u92e6\u7684\u5316\u5b78\u6027\u8cea\u4ee5\x20\x2b\x33\x20\u6c27\u5316\u614b\u6700\u70ba\u7a69\u5b9a\uff0c\u4e14\u5c55\u73fe\u51fa\u8f03\u5f37\u7684\u91d1\u5c6c\u9375\u7d50\u7279\u6027\u3002\u5728\u9ad8\u4e2d\u5316\u5b78\u63a2\u8a0e\u904e\u6e21\u5340\u5143\u7d20\u8207\u5167\u904e\u6e21\u5143\u7d20\u7684\u5206\u5225\u6642\uff0c\u92e6\u662f\u8aaa\u660e\u300c\x35\x66\x20\u96fb\u5b50\u5b9a\u57df\u5316\u300d\u8207\u300c\x36\x64\x20\u96fb\u5b50\u53c3\u8207\u9375\u7d50\u300d\u7af6\u722d\u95dc\u4fc2\u7684\u91cd\u8981\u5c0d\u8c61\u3002\u7531\u65bc\u92e6\u5177\u5099\u6975\u9ad8\u7684\u6bd4\u653e\u5c04\u6d3b\u6027\x28\x53\x70\x65\x63\x69\x66\x69\x63\x20\x61\x63\x74\x69\x76\x69\x74\x79\x29\uff0c\u5176\u55ae\u8cea\u8207\u5316\u5408\u7269\u5728\u8870\u8b8a\u904e\u7a0b\u4e2d\u6703\u91cb\u653e\u5927\u91cf\u71b1\u80fd\uff0c\u5c0e\u81f4\u5927\u584a\u91d1\u5c6c\u92e6\u5728\u5ba4\u6eab\u4e0b\u6703\u7522\u751f\u81ea\u767c\u6027\u7684\u9ad8\u6eab\u751a\u81f3\u7194\u5316\u3002\x0a\x0a\u5728\u73fe\u4ee3\u822a\u592a\u8207\u884c\u661f\u79d1\u5b78\u4e2d\uff0c\u92e6\x2d\x32\x34\x34\x28\u00b2\u2074\u2074\x43\x6d\x29\u626e\u6f14\u8457\u95dc\u9375\u89d2\u8272\u3002\u5b83\u662f\u591a\u7a2e\u706b\u661f\u63a2\u6e2c\u5668\x28\u5982\u597d\u5947\u865f\u3001\u6bc5\u529b\u865f\x29\u6240\u642d\u8f09\u4e4b\u300c\u03b1\x20\u7c92\u5b50\x20\x58\x20\u5c04\u7dda\u5149\u8b5c\u5100\u300d\x28\x41\x50\x58\x53\x29\u7684\u6838\u5fc3\u80fd\u91cf\u4f86\u6e90\uff0c\u5229\u7528\u5176\u91cb\u653e\u7684\x20\u03b1\x20\u7c92\u5b50\u8f5f\u64ca\u884c\u661f\u571f\u58e4\u6216\u5ca9\u77f3\u6a23\u672c\uff0c\u8a98\u767c\x20\x58\x20\u5c04\u7dda\u7522\u751f\uff0c\u9032\u800c\u5206\u6790\u5730\u5916\u661f\u9ad4\u7684\u5143\u7d20\u7d44\u6210\u3002\u6b64\u5916\uff0c\u92e6\u4ea6\u662f\u751f\u7522\u66f4\u91cd\u5143\u7d20\x28\u5982\u9272\u3001\u9440\u7b49\x29\u7684\u91cd\u8981\u521d\u59cb\u6750\u6599\u3002\u5728\u6838\u5de5\u696d\u4e2d\uff0c\u92e6\u4f5c\u70ba\u4e4f\u6838\u71c3\u6599\u4e2d\u7684\u9577\u58fd\u547d\u653e\u5c04\u6027\u5ee2\u68c4\u7269\uff0c\u5176\u74b0\u5883\u9077\u79fb\u884c\u70ba\u8207\u56fa\u5316\u8655\u7406\u6280\u8853\u662f\u73fe\u4ee3\u6838\u80fd\u5b89\u5168\u7814\u7a76\u7684\u91cd\u4e2d\u4e4b\u91cd\u3002\x0a\x0a\u95dc\u65bc\u92e6\u7684\u7269\u7406\u73fe\u8c61\uff0c\u6700\u4ee4\u4eba\u9707\u64bc\u7684\u662f\u5176\u300c\u5207\u502b\u79d1\u592b\u8f3b\u5c04\u300d\u8207\u81ea\u767c\u71b1\u3002\u5728\u6697\u8655\uff0c\u92e6\u9e7d\u6eb6\u6db2\u6703\u56e0\u70ba\u5f37\u70c8\u7684\u96fb\u96e2\u8f3b\u5c04\u6fc0\u767c\u5468\u570d\u7a7a\u6c23\u800c\u7522\u751f\u7f8e\u9e97\u4f46\u81f4\u547d\u7684\u6de1\u85cd\u8272\u5e7d\u5149\u3002\u6709\u8da3\u7684\u662f\uff0c\u96d6\u7136\u92e6\u8207\u92c2\u5728\u540c\u4e00\u5e74\u88ab\u767c\u73fe\uff0c\u4f46\u56e0\u5176\u5316\u5b78\u6027\u8cea\u6975\u5176\u76f8\u4f3c\uff0c\u5206\u96e2\u904e\u7a0b\u8017\u8cbb\u4e86\u79d1\u5b78\u5bb6\u6975\u5927\u5fc3\u529b\u3002\u6b64\u5916\uff0c\u91d1\u5c6c\u92e6\u5177\u5099\u6975\u5f37\u7684\u78c1\u6027\uff0c\u5728\u4f4e\u6eab\u4e0b\u5c55\u73fe\u51fa\u8907\u96dc\u7684\u78c1\u5e8f\u8f49\u8b8a\u3002\u9019\u7a2e\u5f9e\u7d00\u5ff5\u653e\u5c04\u6027\u59cb\u7956\u7684\u547d\u540d\u5230\u4f5c\u70ba\u4eba\u985e\u5728\u706b\u661f\u4e0a\u7684\u300c\u5316\u5b78\u63a2\u91dd\u300d\uff0c\u7cbe\u78ba\u8a6e\u91cb\u4e86\u92e6\u5728\u9312\u7cfb\u5143\u7d20\u4e2d\u4f5c\u70ba\u9ad8\u80fd\u7269\u7406\u8207\u5730\u5916\u63a2\u7d22\u6838\u5fc3\u5de5\u5177\u7684\u50f9\u503c\u3002",
  "\x42\x6b":
    "\u9273\x28\x42\x65\x72\x6b\x65\x6c\x69\x75\x6d\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x42\x6b\uff0c\u539f\u5b50\u5e8f\x20\x39\x37\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u4e03\u9031\u671f\u3001\u9312\u7cfb\u5143\u7d20\x28\x66\x20\u5340\u584a\x29\u3002\u5176\u540d\u7a31\u6e90\u65bc\u52a0\u5dde\u5927\u5b78\u67cf\u514b\u840a\u5206\u6821\x28\x55\x43\x20\x42\x65\x72\x6b\x65\x6c\x65\x79\x29\uff0c\u8a72\u5730\u662f\u773e\u591a\u8d85\u923e\u5143\u7d20\u7684\u6416\u7c43\u3002\x31\x39\x34\x39\x20\u5e74\u7531\u5e2d\u535a\u683c\u9818\u5c0e\u7684\u5718\u968a\u5229\u7528\x20\u03b1\x20\u7c92\u5b50\u8f5f\u64ca\u92c2\x2d\x32\x34\x31\x20\u9996\u6b21\u5408\u6210\u3002\u9273\u662f\u4e00\u7a2e\u5177\u6709\u9280\u7070\u8272\u5149\u6fa4\u7684\u653e\u5c04\u6027\u91d1\u5c6c\uff0c\u5728\u5730\u6bbc\u4e2d\u5b8c\u5168\u4e0d\u5b58\u5728\uff0c\u50c5\u80fd\u900f\u904e\u9ad8\u80fd\u6838\u53cd\u61c9\u7210\u5fae\u91cf\u751f\u7522\u3002\u5b83\u662f\u7814\u7a76\u8d85\u9312\u7cfb\u5143\u7d20\u6027\u8cea\u8da8\u52e2\u7684\u95dc\u9375\u7bc0\u9ede\uff0c\u4ea6\u662f\u73fe\u4ee3\u91cd\u5143\u7d20\u5408\u6210\u5be6\u9a57\u4e2d\u4e0d\u53ef\u6216\u7f3a\u7684\u300c\u9776\u6750\u300d\u5143\u7d20\u3002\x0a\x0a\u5728\u5316\u5b78\u884c\u70ba\u4e0a\uff0c\u9273\u7684\u96fb\u5b50\u7d44\u614b\u70ba\x20\x5b\x52\x6e\x5d\x35\x66\u2079\x37\x73\u00b2\u3002\u4e0d\u540c\u65bc\u524d\u65b9\u7684\u92e6\uff0c\u9273\u5728\x20\x2b\x33\x20\u6c27\u5316\u614b\u4e4b\u5916\uff0c\u9084\u80fd\u7a69\u5b9a\u5b58\u5728\u5177\u5099\u5f37\u6c27\u5316\u6027\u7684\x20\x2b\x34\x20\u6c27\u5316\u614b\x28\x42\x6b\u2074\u207a\x29\uff0c\u9019\u6e90\u65bc\u5176\x20\x35\x66\x20\u8ecc\u57df\u5728\u5931\u53bb\u96fb\u5b50\u5f8c\u80fd\u8da8\u8fd1\u65bc\u534a\u586b\u6eff\x20\x35\x66\u2077\x20\u7684\u7a69\u5b9a\u8da8\u5411\u3002\u5728\u9ad8\u4e2d\u5316\u5b78\u63a2\u8a0e\u96fb\u8ca0\u5ea6\u8207\u6c27\u5316\u9084\u539f\u96fb\u4f4d\u6642\uff0c\u9273\u662f\u8aaa\u660e\u300c\u9312\u7cfb\u5143\u7d20\u9ad8\u6c27\u5316\u614b\u7a69\u5b9a\u6027\u96a8\u539f\u5b50\u5e8f\u6ce2\u52d5\u300d\u7684\u5178\u578b\u6848\u4f8b\u3002\u91d1\u5c6c\u9273\u5728\u7a7a\u6c23\u4e2d\u6c27\u5316\u7de9\u6162\uff0c\u4e14\u5177\u5099\u5169\u7a2e\u540c\u7d20\u7570\u5f62\u9ad4\uff0c\u5728\u7279\u5b9a\u6eab\u5ea6\u4e0b\u6703\u767c\u751f\u7d50\u69cb\u8f49\u8b8a\uff0c\u53cd\u6620\u4e86\x20\x35\x66\x20\u96fb\u5b50\u5728\u91cd\u5143\u7d20\u91d1\u5c6c\u9375\u7d50\u4e2d\u8907\u96dc\u7684\u53c3\u8207\u6a21\u5f0f\u3002\x0a\x0a\u9273\u5728\u73fe\u4ee3\u79d1\u5b78\u61c9\u7528\u4e2d\u6700\u8f1d\u714c\u7684\u8ca2\u737b\u662f\u4f5c\u70ba\u300c\u5408\u6210\u65b0\u5143\u7d20\u7684\u7a2e\u5b50\u300d\u3002\u540c\u4f4d\u7d20\x20\u9273\x2d\x32\x34\x39\x28\u00b2\u2074\u2079\x42\x6b\x29\u662f\u88fd\u9020\u539f\u5b50\u5e8f\x20\x31\x31\x37\x20\u865f\u5143\u7d20\u300c\u77f3\u300d\x28\x54\x65\x6e\x6e\x65\x73\x73\x69\x6e\x65\x2c\x20\x54\x73\x29\u7684\u552f\u4e00\u53ef\u7528\u9776\u6750\u6599\uff1b\x32\x30\x31\x30\x20\u5e74\u79d1\u5b78\u5bb6\u6b63\u662f\u5229\u7528\u9223\x2d\x34\x38\x20\u96e2\u5b50\u8f5f\u64ca\u9273\u9776\uff0c\u624d\u6210\u529f\u586b\u88dc\u4e86\u9031\u671f\u8868\u6700\u5f8c\u4e00\u500b\u9e75\u7d20\u65cf\u7684\u4f4d\u7f6e\u3002\u6b64\u5916\uff0c\u9273\u7684\u653e\u5c04\u6027\u6027\u8cea\u4e5f\u88ab\u7528\u65bc\u7279\u5b9a\u7684\u6838\u7269\u7406\u63a2\u6e2c\u5668\u6a19\u5b9a\u8207\u5316\u5b78\u793a\u8e64\u7814\u7a76\u3002\u7531\u65bc\u5176\u7522\u91cf\u6975\u5176\u7a00\u5c11\x28\u5168\u7403\u5e74\u7522\u91cf\u50c5\u4ee5\u6beb\u514b\u8a08\x29\uff0c\u9273\u7684\u7814\u7a76\u9ad8\u5ea6\u96c6\u4e2d\u65bc\u4e16\u754c\u9802\u5c16\u7684\u6838\u7269\u7406\u5be6\u9a57\u5ba4\u3002\x0a\x0a\u95dc\u65bc\u9273\u7684\u73fe\u8c61\uff0c\u5b83\u5c55\u73fe\u4e86\u7269\u8cea\u5728\u5b8f\u89c0\u8207\u5fae\u89c0\u9593\u7684\u5f37\u70c8\u4e0d\u7a69\u5b9a\u611f\u3002\u9273\u7684\u5316\u5408\u7269\u5728\u53d7\u6fc0\u767c\u6642\u6703\u767c\u51fa\u7279\u5fb5\u6027\u7684\u87a2\u5149\u8b5c\u7dda\uff0c\u5176\u984f\u8272\u8207\u914d\u4f4d\u74b0\u5883\u5bc6\u5207\u76f8\u95dc\u3002\u6709\u8da3\u7684\u662f\uff0c\u96d6\u7136\u9273\u7684\u5316\u5b78\u6bd2\u6027\u8207\u653e\u5c04\u6bd2\u6027\u6975\u9ad8\uff0c\u4f46\u5b83\u5728\u6676\u9ad4\u5b78\u7814\u7a76\u4e2d\u537b\u662f\u6975\u4f73\u7684\u6a23\u672c\uff0c\u5176\u6c27\u5316\u7269\x20\x42\x6b\x4f\u2082\x20\u5c55\u73fe\u4e86\u8207\u4e8c\u6c27\u5316\u92ef\x28\x5a\x72\x4f\u2082\x29\u76f8\u4f3c\u7684\u7a69\u5b9a\u7d50\u69cb\u3002\u9019\u7a2e\u5f9e\u67cf\u514b\u840a\u5be6\u9a57\u5ba4\u4e2d\u7684\u7cbe\u5bc6\u5408\u6210\u5230\u4f5c\u70ba\u4eba\u985e\u8de8\u8d8a\x20\x31\x31\x37\x20\u865f\u5143\u7d20\u9580\u6abb\u7684\u588a\u8173\u77f3\uff0c\u7cbe\u78ba\u8a6e\u91cb\u4e86\u9273\u5728\u9031\u671f\u8868\u4e2d\u4f5c\u70ba\u300c\u91cd\u5143\u7d20\u5408\u6210\u5148\u92d2\u300d\u7684\u6230\u7565\u5730\u4f4d\u3002",
  "\x43\x66":
    "\u9272\x28\x43\x61\x6c\x69\x66\x6f\x72\x6e\x69\x75\x6d\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x43\x66\uff0c\u539f\u5b50\u5e8f\x20\x39\x38\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u4e03\u9031\u671f\u3001\u9312\u7cfb\u5143\u7d20\x28\x66\x20\u5340\u584a\x29\u3002\u5176\u540d\u7a31\u6e90\u65bc\u767c\u73fe\u5730\u7f8e\u570b\u52a0\u5229\u798f\u5c3c\u4e9e\u5dde\x28\x43\x61\x6c\x69\x66\x6f\x72\x6e\x69\x61\x29\u53ca\u5176\u5927\u5b78\u3002\x31\x39\x35\x30\x20\u5e74\u7531\u5e2d\u535a\u683c\u5718\u968a\u5728\u67cf\u514b\u840a\u5229\u7528\u6c26\u96e2\u5b50\u8f5f\u64ca\u92e6\x2d\x32\x34\x32\x20\u9996\u6b21\u5408\u6210\u3002\u9272\u662f\u6975\u5c11\u6578\u80fd\u4ee5\u5b8f\u89c0\u91cd\u91cf\u88fd\u5f97\u4e14\u5177\u5099\u6975\u5f37\u61c9\u7528\u50f9\u503c\u7684\u8d85\u923e\u5143\u7d20\uff0c\u88ab\u8b7d\u70ba\u300c\u4e2d\u5b50\u4e4b\u738b\u300d\u3002\u5b83\u662f\u4e00\u7a2e\u9280\u767d\u8272\u7684\u91d1\u5c6c\uff0c\u5177\u5099\u9ad8\u5ea6\u7684\u653e\u5c04\u6d3b\u6027\u8207\u5353\u8d8a\u7684\u5de5\u696d\u50f9\u503c\uff0c\u662f\u9023\u7d50\u539f\u5b50\u7269\u7406\u57fa\u790e\u7814\u7a76\u8207\u73fe\u4ee3\u5c16\u7aef\u5de5\u7a0b\u6280\u8853\u7684\u95dc\u9375\u6a4b\u6a11\u3002\x0a\x0a\u9272\u7684\u96fb\u5b50\u7d44\u614b\u70ba\x20\x5b\x52\x6e\x5d\x35\x66\u00b9\u2070\x37\x73\u00b2\uff0c\u6700\u7a69\u5b9a\u7684\u6c27\u5316\u614b\u70ba\x20\x2b\x33\u3002\u7531\u65bc\u5176\u4f4d\u65bc\u9312\u7cfb\u5f8c\u534a\u6bb5\uff0c\u9272\u958b\u59cb\u5c55\u73fe\u51fa\u66f4\u591a\u985e\u946d\u7cfb\u5143\u7d20\u7684\u5316\u5b78\u7279\u5fb5\uff0c\u5176\x20\x35\x66\x20\u96fb\u5b50\u96f2\u6536\u7e2e\u4f7f\u5176\u5316\u5b78\u884c\u70ba\u8da8\u65bc\u7a69\u5b9a\u4e14\u53ef\u9810\u6e2c\u3002\u5728\u9ad8\u4e2d\u5316\u5b78\u63a2\u8a0e\u6838\u88c2\u8b8a\u8207\u540c\u4f4d\u7d20\u6027\u8cea\u6642\uff0c\u9272\x2d\x32\x35\x32\x28\u00b2\u2075\u00b2\x43\x66\x29\u662f\u4e0d\u53ef\u66ff\u4ee3\u7684\u6559\u5b78\u5be6\u4f8b\uff1a\u5b83\u80fd\u767c\u751f\u300c\u81ea\u767c\u88c2\u8b8a\u300d\x28\x53\x70\x6f\x6e\x74\x61\x6e\x65\x6f\x75\x73\x20\x66\x69\x73\x73\x69\x6f\x6e\x29\uff0c\u6bcf\u79d2\u9418\u6bcf\u5fae\u514b\u91cb\u653e\u51fa\u7d04\x20\x32\x33\x30\x20\u842c\u500b\u4e2d\u5b50\uff0c\u9019\u4f7f\u5176\u6210\u70ba\u5fae\u578b\u4f46\u6975\u5176\u5f37\u5927\u7684\u4e2d\u5b50\u653e\u5c04\u6e90\u3002\u9019\u7a2e\u6975\u7aef\u7684\u6838\u6027\u8cea\u4f7f\u5f97\u9272\u5728\u55ae\u4f4d\u9ad4\u7a4d\u5167\u80fd\u63d0\u4f9b\u9060\u8d85\u5e38\u898f\u6838\u53cd\u61c9\u7210\u7684\u4e2d\u5b50\u6d41\u5bc6\u5ea6\u3002\x0a\x0a\u5728\u73fe\u4ee3\u61c9\u7528\u9818\u57df\uff0c\u9272\u662f\u7cbe\u5bc6\u6aa2\u6e2c\u8207\u91ab\u5b78\u6cbb\u7642\u7684\u9802\u7d1a\u5de5\u5177\u3002\u5728\u80fd\u6e90\u958b\u767c\u4e2d\uff0c\u9272\u88ab\u7528\u65bc\u300c\u4e2d\u5b50\u6c34\u5206\u8a08\u300d\u4ee5\u7cbe\u78ba\u5075\u6e2c\u6cb9\u4e95\u8207\u7926\u5c64\u4e2d\u7684\u6c34\u3001\u6cb9\u5206\u5e03\uff1b\u5728\u822a\u592a\u5de5\u696d\uff0c\u5b83\u88ab\u7528\u65bc\u6aa2\u6e2c\u98db\u6a5f\u6a5f\u9ad4\u5167\u90e8\u7684\u88c2\u7d0b\u8207\u91d1\u5c6c\u75b2\u52de\x28\u4e2d\u5b50\u653e\u5c04\u651d\u5f71\x29\u3002\u91ab\u5b78\u4e0a\uff0c\u9272\x2d\x32\x35\x32\x20\u66fe\u88ab\u7528\u65bc\u6cbb\u7642\u7279\u5b9a\u985e\u578b\u7684\u60e1\u6027\u816b\u7624\uff0c\u5229\u7528\u5176\u767c\u51fa\u7684\u4e2d\u5b50\u76f4\u63a5\u7834\u58de\u764c\u7d30\u80de\u7684\x20\x44\x4e\x41\uff0c\u5c0d\u67d0\u4e9b\u5c0d\x20\x58\x20\u5c04\u7dda\u5177\u5099\u6297\u6027\u7684\u816b\u7624\u6548\u679c\u986f\u8457\u3002\u6b64\u5916\uff0c\u5728\u6838\u8a2d\u65bd\u555f\u52d5\u8207\u6838\u5ee2\u6599\u5206\u6790\u4e2d\uff0c\u9272\u4ea6\u662f\u6a19\u6e96\u7684\u6821\u6e96\u8207\u6fc0\u767c\u6e90\u3002\x0a\x0a\u95dc\u65bc\u9272\u7684\u73fe\u8c61\uff0c\u5b83\u5c55\u73fe\u4e86\u4ee4\u4eba\u9a5a\u5606\u7684\u300c\u80fd\u91cf\u5bc6\u5ea6\u300d\u8207\u300c\u50f9\u683c\u6a19\u7c64\u300d\u3002\u9272\u66fe\u662f\u4e16\u754c\u4e0a\u6700\u6602\u8cb4\u7684\u5316\u5b78\u5143\u7d20\uff0c\u5176\u6bcf\u516c\u514b\u7684\u88fd\u9020\u6210\u672c\u66fe\u9ad8\u9054\u6578\u5343\u842c\u7f8e\u5143\u3002\u6709\u8da3\u7684\u662f\uff0c\u91d1\u5c6c\u9272\u5728\u52a0\u71b1\u81f3\u9ad8\u6eab\u6642\u6703\u8f49\u8b8a\u70ba\u6db2\u614b\uff0c\u5176\u7194\u9ede\u8207\u946d\u7cfb\u540c\u985e\u5143\u7d20\u76f8\u6bd4\u5448\u73fe\u51fa\u986f\u8457\u7684\u9031\u671f\u6027\u4e0b\u964d\u3002\u6b64\u5916\uff0c\u9272\u5316\u5408\u7269\u5728\u5f37\u5149\u7167\u5c04\u4e0b\u6703\u5c55\u73fe\u51fa\u6975\u5177\u7279\u8272\u7684\u5149\u81f4\u767c\u5149\u8b5c\u7dda\u3002\u9019\u7a2e\u5f9e\u52a0\u5dde\u5be6\u9a57\u5ba4\u7684\u8f1d\u714c\u767c\u73fe\u5230\u6210\u70ba\u89e3\u6c7a\u822a\u592a\u5b89\u5168\u8207\u7591\u96e3\u96dc\u75c7\u7684\u300c\u4e2d\u5b50\u624b\u8853\u5200\u300d\uff0c\u7cbe\u78ba\u8a6e\u91cb\u4e86\u9272\u5728\u9031\u671f\u8868\u4e2d\u4f5c\u70ba\u300c\u6838\u80fd\u6280\u8853\u6975\u81f4\u7e2e\u5f71\u300d\u7684\u5353\u8d8a\u8eab\u5206\u3002",
  "\x4c\x72":
    "\u9412\x28\x4c\x61\x77\x72\x65\x6e\x63\x69\x75\x6d\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x4c\x72\uff0c\u539f\u5b50\u5e8f\x20\x31\x30\x33\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u4e03\u9031\u671f\u3001\u7b2c\x20\x33\x20\u65cf\x28\u6216\u9312\u7cfb\u5143\u7d20\u7684\u7d42\u9ede\uff0c\x64\x20\u5340\u584a\x29\u3002\u5176\u540d\u7a31\u662f\u70ba\u4e86\u7d00\u5ff5\u8ff4\u65cb\u52a0\u901f\u5668\u7684\u767c\u660e\u8005\u3001\u8afe\u8c9d\u723e\u734e\u5f97\u4e3b\u6b50\u5167\u65af\u7279\u00b7\u52de\u502b\u65af\x28\x45\x72\x6e\x65\x73\x74\x20\x4c\x61\x77\x72\x65\x6e\x63\x65\x29\u3002\x31\x39\x36\x31\x20\u5e74\u7531\u5409\u5967\u7d22\x28\x41\x6c\x62\x65\x72\x74\x20\x47\x68\x69\x6f\x72\x73\x6f\x29\u9818\u5c0e\u7684\u5718\u968a\u5728\u67cf\u514b\u840a\u52a0\u5dde\u5927\u5b78\u9996\u6b21\u5408\u6210\u3002\u8eab\u70ba\u9312\u7cfb\u7cfb\u5217\u7684\u6700\u5f8c\u4e00\u500b\u6210\u54e1\uff0c\u52de\u502b\u65af\u945e\u8c61\u5fb5\u8457\x20\x35\x66\x20\u8ecc\u57df\u586b\u5145\u7684\u5b8c\u6210\uff0c\u662f\u9023\u63a5\u5167\u904e\u6e21\u5143\u7d20\u8207\x20\x36\x64\x20\u904e\u6e21\u91d1\u5c6c\u5340\u584a\u7684\u91cd\u8981\u6a4b\u6a11\u3002\x0a\x0a\u5728\u5fae\u89c0\u7d50\u69cb\u4e0a\uff0c\u52de\u502b\u65af\u945e\u5c55\u73fe\u4e86\u5f37\u70c8\u7684\u76f8\u5c0d\u8ad6\u6548\u61c9\x28\x52\x65\x6c\x61\x74\x69\x76\x69\x73\x74\x69\x63\x20\x65\x66\x66\x65\x63\x74\x73\x29\u3002\u5176\u57fa\u614b\u96fb\u5b50\u7d44\u614b\u901a\u5e38\u88ab\u6a19\u8a18\u70ba\x20\x5b\x52\x6e\x5d\x35\x66\u00b9\u2074\x37\x73\u00b2\x37\x70\u00b9\uff0c\u9019\u5728\u9ad8\u4e2d\u5316\u5b78\u63a2\u8a0e\u9031\u671f\u5f8b\u6642\u662f\u4e00\u500b\u6975\u5177\u555f\u767c\u6027\u7684\u7279\u4f8b\uff1a\u7531\u65bc\u539f\u5b50\u6838\u96fb\u8377\u6975\u9ad8\uff0c\u5c0e\u81f4\x20\x37\x70\x20\u8ecc\u57df\u80fd\u91cf\u4e0b\u964d\u4e26\u8207\x20\x37\x73\x20\u8ecc\u57df\u7522\u751f\u5f37\u70c8\u7684\u76f8\u5c0d\u8ad6\u6536\u7e2e\uff0c\u4f7f\u5176\u57fa\u614b\u6027\u8cea\u504f\u96e2\u4e86\u5178\u578b\u7684\x20\x64\x20\u8ecc\u57df\u586b\u5145\u898f\u5f8b\u3002\u5728\u5316\u5b78\u884c\u70ba\u4e0a\uff0c\u5b83\u7a69\u5b9a\u5c55\u73fe\x20\x2b\x33\x20\u6c27\u5316\u614b\uff0c\u5176\u96e2\u5b50\u534a\u5f91\u9075\u5faa\u9312\u7cfb\u6536\u7e2e\u8da8\u52e2\uff0c\u8868\u73fe\u51fa\u8207\u946d\u7cfb\u5143\u7d20\u9465\x28\x4c\x75\x29\u9ad8\u5ea6\u76f8\u4f3c\u7684\u914d\u4f4d\u5316\u5b78\u7279\u5fb5\u3002\x0a\x0a\u76ee\u524d\u5c0d\u65bc\u52de\u502b\u65af\u945e\u7684\u7814\u7a76\u5b8c\u5168\u5c40\u9650\u65bc\u539f\u5b50\u5c3a\u5ea6\u7684\u57fa\u790e\u79d1\u5b78\uff0c\u7279\u5225\u662f\u5229\u7528\u300c\u6c23\u76f8\u5c64\u6790\u5206\u6790\u300d\u89c0\u6e2c\u5176\u63ee\u767c\u6027\u8207\u71b1\u529b\u5b78\u6027\u8cea\u3002\u7531\u65bc\u5176\u6700\u9577\u58fd\u547d\u7684\u540c\u4f4d\u7d20\x20\u00b2\u2076\u2076\x4c\x72\x20\u534a\u8870\u671f\u50c5\u7d04\x20\x31\x31\x20\u5c0f\u6642\uff0c\u6240\u6709\u7684\u5316\u5b78\u9451\u5b9a\u5fc5\u9808\u5728\u6975\u901f\u81ea\u52d5\u5316\u7cfb\u7d71\u4e2d\u5b8c\u6210\u3002\u79d1\u5b78\u5bb6\u900f\u904e\u89c0\u6e2c\u5176\u7b2c\u4e00\u96fb\u96e2\u80fd\uff0c\u8b49\u5be6\u4e86\u52de\u502b\u65af\u945e\u662f\u6240\u6709\u9312\u7cfb\u5143\u7d20\u4e2d\u96fb\u96e2\u80fd\u6700\u4f4e\u7684\uff0c\u9019\u9032\u4e00\u6b65\u652f\u6301\u4e86\u5176\x20\x37\x70\x20\u96fb\u5b50\u53d7\u6838\u675f\u7e1b\u76f8\u5c0d\u8f03\u5f31\u7684\u7406\u8ad6\u9810\u6e2c\u3002\u96d6\u7136\u5c1a\u7121\u5de5\u696d\u61c9\u7528\uff0c\u4f46\u5b83\u662f\u4eba\u985e\u7406\u89e3\u91cd\u5143\u7d20\u96fb\u5b50\u6bbc\u5c64\u91cd\u7d44\u898f\u5f8b\u7684\u95dc\u9375\u6578\u64da\u4f86\u6e90\u3002\x0a\x0a\u95dc\u65bc\u52de\u502b\u65af\u945e\u7684\u7269\u7406\u7279\u5fb5\uff0c\u5b83\u5c55\u73fe\u4e86\u7269\u8cea\u5728\u6975\u9650\u539f\u5b50\u5e8f\u4e0b\u7684\u300c\u80fd\u968e\u53cd\u8f49\u300d\u73fe\u8c61\u3002\u96d6\u7136\u5728\u9031\u671f\u8868\u7684\u4f4d\u7f6e\u61c9\u8207\u9312\u3001\u946d\u5c0d\u9f4a\uff0c\u4f46\u5176\x20\x37\x70\x20\u96fb\u5b50\u7684\u5b58\u5728\u4f7f\u5176\u5728\u7279\u5b9a\u689d\u4ef6\u4e0b\u53ef\u80fd\u5c55\u73fe\u51fa\u4e0d\u540c\u65bc\u7b2c\x20\x33\x20\u65cf\u5143\u7d20\u7684\u7269\u7406\u884c\u70ba\u3002\u6709\u8da3\u7684\u662f\uff0c\u96d6\u7136\u4ee5\u52de\u502b\u65af\u547d\u540d\uff0c\u4f46\u9019\u7a2e\u5143\u7d20\u7121\u6cd5\u88ab\u8089\u773c\u89c0\u6e2c\u5176\u91d1\u5c6c\u5149\u6fa4\uff0c\u50c5\u80fd\u900f\u904e\u55ae\u500b\u539f\u5b50\u7684\u653e\u5c04\u6027\u8870\u8b8a\u8108\u885d\u4f86\u78ba\u8a8d\u5176\u8eab\u5206\u3002\u9019\u7a2e\u5f9e\u8ff4\u65cb\u52a0\u901f\u5668\u6280\u8853\u7684\u5dd4\u5cf0\u5230\u5b9a\u7fa9\u9312\u7cfb\u7d42\u9ede\u7684\u8f49\u8b8a\uff0c\u7cbe\u78ba\u8a6e\u91cb\u4e86\u52de\u502b\u65af\u945e\u5728\u9031\u671f\u8868\u4e2d\u4f5c\u70ba\u91cf\u5b50\u529b\u5b78\u5be6\u9a57\u908a\u754c\u7684\u7279\u6b8a\u5730\u4f4d\u3002",
  "\x52\x66":
    "\u946a\x28\x52\x75\x74\x68\x65\x72\x66\x6f\x72\x64\x69\x75\x6d\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x52\x66\uff0c\u539f\u5b50\u5e8f\x20\x31\x30\x34\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u4e03\u9031\u671f\u3001\u7b2c\x20\x34\x20\u65cf\x28\x64\x20\u5340\u584a\x29\u3002\u5176\u540d\u7a31\u662f\u70ba\u4e86\u81f4\u656c\u539f\u5b50\u6838\u7269\u7406\u4e4b\u7236\u6b50\u5167\u65af\u7279\u00b7\u62c9\u585e\u798f\x28\x45\x72\x6e\x65\x73\x74\x20\x52\x75\x74\x68\x65\x72\x66\x6f\x72\x64\x29\u3002\x31\x39\x36\x30\x20\u5e74\u4ee3\u7531\u8607\u806f\u675c\u5e03\u7d0d\u5718\u968a\u8207\u7f8e\u570b\u67cf\u514b\u840a\u5718\u968a\u5206\u5225\u7368\u7acb\u5408\u6210\uff0c\u4e26\u5f15\u767c\u4e86\u9577\u9054\u6578\u5341\u5e74\u7684\u300c\u8d85\u8cbb\u7c73\u5143\u7d20\u547d\u540d\u5927\u6230\u300d\u3002\u946a\u662f\u7b2c\u4e00\u500b\u300c\u8d85\u9312\u7cfb\u5143\u7d20\u300d\x28\x54\x72\x61\x6e\x73\x61\x63\x74\x69\x6e\x69\x64\x65\x29\uff0c\u6a19\u8a8c\u8457\x20\x36\x64\x20\u8ecc\u57df\u6b63\u5f0f\u958b\u59cb\u586b\u5145\uff0c\u5176\u5316\u5b78\u884c\u70ba\u7406\u8ad6\u4e0a\u61c9\u8207\u5176\u4e0a\u65b9\u7684\u92ef\x28\x5a\x72\x29\u53ca\u927f\x28\x48\x66\x29\u5c55\u73fe\u51fa\u9ad8\u5ea6\u7684\u65cf\u7fa4\u898f\u5f8b\u6027\u3002\x0a\x0a\u62c9\u585e\u798f\u946a\u7684\u96fb\u5b50\u7d44\u614b\u9810\u6e2c\u70ba\x20\x5b\x52\x6e\x5d\x35\x66\u00b9\u2074\x36\x64\u00b2\x37\x73\u00b2\u3002\u7531\u65bc\u76f8\u5c0d\u8ad6\u6548\u61c9\u5c0d\u5176\x20\x37\x73\x20\u8207\x20\x37\x70\x20\u8ecc\u57df\u7684\u5f37\u70c8\u64fe\u52d5\uff0c\u946a\u7684\u5316\u5b78\u9375\u7d50\u5c55\u73fe\u51fa\u6bd4\u927f\u66f4\u70ba\u8907\u96dc\u7684\u50be\u5411\u3002\u5728\u9ad8\u4e2d\u5316\u5b78\u63a2\u8a0e\u9031\u671f\u5f8b\u7684\u5ef6\u4f38\u61c9\u7528\u6642\uff0c\u946a\u662f\u8aaa\u660e\u300c\u540c\u65cf\u6027\u8cea\u5ef6\u7e8c\u300d\u7684\u7d42\u6975\u6848\u4f8b\uff1a\u5be6\u9a57\u8b49\u5be6\uff0c\u946a\u5728\u9178\u6027\u6eb6\u6db2\u4e2d\u5f62\u6210\u7684\u6c2f\u932f\u5408\u7269\u8207\u927f\u3001\u92ef\u6975\u5176\u76f8\u4f3c\uff0c\u7686\u4ee5\x20\x2b\x34\x20\u6c27\u5316\u614b\u70ba\u4e3b\u8981\u7279\u5fb5\u3002\u7136\u800c\uff0c\u7531\u65bc\u5176\u6700\u7a69\u5b9a\u540c\u4f4d\u7d20\x20\u00b2\u2076\u2077\x52\x66\x20\u7684\u534a\u8870\u671f\u50c5\u7d04\x20\x31\x2e\x33\x20\u5c0f\u6642\uff0c\u5176\u5316\u5b78\u6027\u8cea\u7684\u7814\u7a76\u5fc5\u9808\u5728\u6975\u77ed\u6642\u9593\u5167\u5b8c\u6210\u3002\x0a\x0a\u5728\u73fe\u4ee3\u79d1\u5b78\u61c9\u7528\u4e2d\uff0c\u62c9\u585e\u798f\u946a\u662f\u300c\u76f8\u5c0d\u8ad6\u5316\u5b78\u300d\u7684\u6838\u5fc3\u7814\u7a76\u5c0d\u8c61\u3002\u900f\u904e\u6c23\u76f8\u5c64\u6790\u5be6\u9a57\uff0c\u79d1\u5b78\u5bb6\u767c\u73fe\u946a\u7684\u56db\u6c2f\u5316\u7269\x28\x52\x66\x43\x6c\u2084\x29\u5177\u5099\u8f03\u9ad8\u7684\u63ee\u767c\u6027\uff0c\u4e14\u5176\u71b1\u529b\u5b78\u884c\u70ba\u8207\u927f\u57fa\u672c\u4e00\u81f4\uff0c\u9019\u6210\u529f\u9a57\u8b49\u4e86\u5373\u4f7f\u5728\u6975\u9ad8\u539f\u5b50\u5e8f\u4e0b\uff0c\u9031\u671f\u8868\u7684\u300c\u65cf\u898f\u5f8b\u300d\u4f9d\u7136\u6709\u6548\u3002\u76ee\u524d\u946a\u50c5\u7528\u65bc\u57fa\u790e\u539f\u5b50\u6838\u7269\u7406\u5be6\u9a57\uff0c\u5e6b\u52a9\u79d1\u5b78\u5bb6\u63a2\u7a76\u539f\u5b50\u6838\u5728\u6975\u9650\u8cea\u91cf\u4e0b\u7684\u7a69\u5b9a\u6027\u908a\u754c\u3002\u7531\u65bc\u5176\u5f37\u5927\u7684\u653e\u5c04\u6027\u8207\u88fd\u5099\u96e3\u5ea6\uff0c\u946a\u76ee\u524d\u5c1a\u7121\u4efb\u4f55\u5546\u696d\u6216\u5de5\u696d\u61c9\u7528\u3002\x0a\x0a\u95dc\u65bc\u62c9\u585e\u798f\u946a\u7684\u7269\u7406\u73fe\u8c61\uff0c\u5b83\u5c55\u73fe\u4e86\u7269\u8cea\u5728\u6975\u7aef\u96fb\u8377\u74b0\u5883\u4e0b\u7684\u300c\u8ecc\u57df\u6536\u7e2e\u300d\u7279\u5fb5\u3002\u79d1\u5b78\u5bb6\u9810\u6e2c\uff0c\u946a\u7684\u539f\u5b50\u534a\u5f91\u56e0\u70ba\x20\x37\x73\x20\u96fb\u5b50\u7684\u76f8\u5c0d\u8ad6\u6536\u7e2e\u800c\u986f\u8457\u6e1b\u5c0f\uff0c\u9019\u4f7f\u5176\u5316\u5b78\u9375\u7684\u5f37\u5ea6\u53ef\u80fd\u9ad8\u65bc\u540c\u65cf\u7684\u5176\u5b83\u6210\u54e1\u3002\u6709\u8da3\u7684\u662f\uff0c\u96d6\u7136\u946a\u5728\u81ea\u7136\u754c\u4e2d\u5b8c\u5168\u4e0d\u5b58\u5728\uff0c\u4f46\u5b83\u662f\u7406\u89e3\u8d85\u91cd\u5143\u7d20\u300c\u7a69\u5b9a\u6027\u5cf6\u300d\u7406\u8ad6\u7684\u91cd\u8981\u57fa\u77f3\u3002\u9019\u7a2e\u5f9e\u5b9a\u7fa9\u539f\u5b50\u7d50\u69cb\u7684\u79d1\u5b78\u5de8\u5320\u5230\u8de8\u8d8a\u9312\u7cfb\u9580\u6abb\u7684\u8d85\u91cd\u5143\u7d20\uff0c\u7cbe\u78ba\u8a6e\u91cb\u4e86\u62c9\u585e\u798f\u946a\u5728\u73fe\u4ee3\u5316\u5b78\u4e2d\u4f5c\u70ba\u7406\u8ad6\u898f\u5f8b\u5b88\u8b77\u8005\u7684\u50f9\u503c\u3002",
  "\x44\x62":
    "\ud862\uddc0\x28\x44\x75\x62\x6e\x69\x75\x6d\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x44\x62\uff0c\u539f\u5b50\u5e8f\x20\x31\x30\x35\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u4e03\u9031\u671f\u3001\u7b2c\x20\x35\x20\u65cf\x28\x64\x20\u5340\u584a\x29\u3002\u5176\u540d\u7a31\u6e90\u65bc\u4fc4\u7f85\u65af\u7684\u6838\u7269\u7406\u7814\u7a76\u4e2d\u5fc3\u675c\u5e03\u7d0d\x28\x44\x75\x62\x6e\x61\x29\u3002\x31\x39\x36\x38\x20\u5e74\u81f3\x20\x31\x39\x37\x30\x20\u5e74\u9593\u7531\u8607\u806f\u8207\u7f8e\u570b\u5718\u968a\u5206\u5225\u5ba3\u7a31\u767c\u73fe\uff0c\u547d\u540d\u6b0a\u722d\u8b70\u76f4\u5230\x20\x31\x39\x39\x37\x20\u5e74\u624d\u6b63\u5f0f\u5b9a\u8ad6\u3002\ud862\uddc0\u662f\u7b2c\x20\x35\x20\u65cf\u904e\u6e21\u91d1\u5c6c\u4e2d\u6700\u91cd\u7684\u4e00\u54e1\uff0c\u4f4d\u65bc\u922e\x28\x4e\x62\x29\u8207\u926d\x28\x54\x61\x29\u4e4b\u4e0b\u3002\u5b83\u662f\u4e00\u7a2e\u5f37\u653e\u5c04\u6027\u7684\u5408\u6210\u5143\u7d20\uff0c\u662f\u7814\u7a76\u76f8\u5c0d\u8ad6\u6548\u61c9\u5982\u4f55\u91cd\u5851\u904e\u6e21\u91d1\u5c6c\u65cf\u7fa4\u6027\u8cea\u905e\u8b8a\u8da8\u52e2\u7684\u95dc\u9375\u6a23\u672c\u3002\x0a\x0a\u5728\u5316\u5b78\u7279\u5fb5\u4e0a\uff0c\ud862\uddc0\u7684\u96fb\u5b50\u7d44\u614b\u9810\u6e2c\u70ba\x20\x5b\x52\x6e\x5d\x35\x66\u00b9\u2074\x36\x64\u00b3\x37\x73\u00b2\u3002\u96d6\u7136\u7406\u8ad6\u9810\u6e2c\u5176\u5316\u5b78\u6027\u8cea\u61c9\u8207\u540c\u65cf\u7684\u926d\u76f8\u4f3c\uff0c\u7a69\u5b9a\u5448\u73fe\x20\x2b\x35\x20\u6c27\u5316\u614b\uff0c\u4f46\u53d7\u5f37\u70c8\u7684\u76f8\u5c0d\u8ad6\u6548\u61c9\u5f71\u97ff\uff0c\ud862\uddc0\u5728\u6eb6\u6db2\u4e2d\u7684\u884c\u70ba\u5c55\u73fe\u51fa\u67d0\u4e9b\u53cd\u5e38\u7684\u300c\u985e\u922e\u300d\u7279\u5fb5\uff0c\u751a\u81f3\u5728\u7279\u5b9a\u689d\u4ef6\u4e0b\u6703\u51fa\u73fe\x20\x2b\x34\x20\u50f9\u3002\u5728\u9ad8\u4e2d\u5316\u5b78\u63a2\u8a0e\u9031\u671f\u8868\u898f\u5f8b\u7684\u504f\u5dee\u6642\uff0c\ud862\uddc0\u662f\u8aaa\u660e\u300c\u91cd\u539f\u5b50\u6548\u61c9\u300d\u5e72\u64fe\u65cf\u7fa4\u8da8\u52e2\u7684\u7d93\u5178\u6848\u4f8b\u3002\u4f8b\u5982\uff0c\u5176\u4e94\u6c2f\u5316\u7269\u7684\u63ee\u767c\u6027\u8207\u6eb6\u89e3\u884c\u70ba\u5728\u4e0d\u540c\u6eb6\u5291\u4e2d\u6703\u767c\u751f\u8207\u540c\u65cf\u5143\u7d20\u4e0d\u4e00\u81f4\u7684\u6f02\u79fb\uff0c\u53cd\u6620\u4e86\x20\x36\x64\x20\u8ecc\u57df\u96fb\u5b50\u96f2\u53d7\u5230\u539f\u5b50\u6838\u5f37\u5927\u5eab\u502b\u529b\u5fae\u64fe\u7684\u7d50\u679c\u3002\x0a\x0a\ud862\uddc0\u5728\u73fe\u4ee3\u79d1\u5b78\u4e2d\u7684\u50f9\u503c\u5b8c\u5168\u9ad4\u73fe\u5728\u300c\u55ae\u539f\u5b50\u5c64\u7d1a\u7684\u5316\u5b78\u5be6\u9a57\u300d\u3002\u7531\u65bc\u5176\u6700\u7a69\u5b9a\u540c\u4f4d\u7d20\x20\u00b2\u2076\u2078\x44\x62\x20\u7684\u534a\u8870\u671f\u50c5\u7d04\x20\x32\x38\x20\u5c0f\u6642\uff0c\u7814\u7a76\u4eba\u54e1\u5fc5\u9808\u5229\u7528\u5168\u81ea\u52d5\u7684\u96e2\u5b50\u4ea4\u63db\u5c64\u6790\u7cfb\u7d71\uff0c\u5728\u6578\u5206\u9418\u5167\u6355\u7372\u4e26\u5206\u6790\u55ae\u500b\ud862\uddc0\u539f\u5b50\u7684\u5316\u5b78\u6027\u8cea\u3002\u9019\u4e9b\u5be6\u9a57\u4e0d\u50c5\u662f\u70ba\u4e86\u5408\u6210\u65b0\u5143\u7d20\uff0c\u66f4\u662f\u70ba\u4e86\u6e2c\u8a66\u91cf\u5b50\u5316\u5b78\u6a21\u578b\u5728\u5f37\u76f8\u5c0d\u8ad6\u5834\u4e0b\u7684\u7cbe\u78ba\u5ea6\u3002\u76ee\u524d\u7684\ud862\uddc0\u5b8c\u5168\u7522\u81ea\u8ff4\u65cb\u52a0\u901f\u5668\uff0c\u4e14\u56e0\u5176\u6975\u9ad8\u7684\u653e\u5c04\u6d3b\u6027\uff0c\u76ee\u524d\u50c5\u4f9b\u5c16\u7aef\u5be6\u9a57\u5ba4\u9032\u884c\u6027\u8cea\u9451\u5b9a\u3002\x0a\x0a\u95dc\u65bc\ud862\uddc0\u7684\u7269\u7406\u6975\u9650\uff0c\u5b83\u5c55\u73fe\u4e86\u91cd\u6838\u5143\u7d20\u4e2d\u300c\u96fb\u5b50\u8ecc\u57df\u91cd\u7d44\u300d\u7684\u5fae\u89c0\u666f\u8c61\u3002\u79d1\u5b78\u5bb6\u9810\u6e2c\uff0c\ud862\uddc0\u7684\x20\x37\x73\x20\u96fb\u5b50\u56e0\u70ba\u76f8\u5c0d\u8ad6\u8cea\u91cf\u589e\u52a0\u800c\u6975\u5ea6\u9760\u8fd1\u539f\u5b50\u6838\uff0c\u9019\u4f7f\u5f97\u5176\u8207\x20\x36\x64\x20\u8ecc\u57df\u7684\u80fd\u7d1a\u5dee\u767c\u751f\u6539\u8b8a\u3002\u6709\u8da3\u7684\u662f\uff0c\u96d6\u7136\ud862\uddc0\u7684\u540d\u7a31\u8c61\u5fb5\u8457\u51b7\u6230\u6642\u671f\u7684\u79d1\u5b78\u89d2\u529b\uff0c\u4f46\u5b83\u73fe\u5728\u537b\u662f\u570b\u969b\u79d1\u5b78\u754c\u651c\u624b\u63a2\u8a0e\u8d85\u91cd\u5143\u7d20\u5316\u5b78\u908a\u754c\u7684\u8c61\u5fb5\u3002\u9019\u7a2e\u5f9e\u795e\u7955\u7684\u653e\u5c04\u6027\u8108\u885d\u5230\u6311\u6230\u7b2c\x20\x35\x20\u65cf\u898f\u5f8b\u7684\u7279\u6027\uff0c\u7cbe\u78ba\u8a6e\u91cb\u4e86\ud862\uddc0\u5728\u9031\u671f\u8868\u4e2d\u4f5c\u70ba\u7406\u8ad6\u9810\u6e2c\u8207\u5be6\u9a57\u89c0\u6e2c\u77db\u76fe\u9ede\u7684\u7368\u7279\u9b45\u529b\u3002",
  "\x53\x67":
    "\ud862\udf4e\x28\x53\x65\x61\x62\x6f\x72\x67\x69\x75\x6d\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x53\x67\uff0c\u539f\u5b50\u5e8f\x20\x31\x30\x36\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u4e03\u9031\u671f\u3001\u7b2c\x20\x36\x20\u65cf\x28\x64\x20\u5340\u584a\x29\u3002\u5176\u540d\u7a31\u662f\u70ba\u4e86\u7d00\u5ff5\u7f8e\u570b\u5316\u5b78\u5bb6\u683c\u502b\u00b7\u5e2d\u535a\u683c\x28\x47\x6c\x65\x6e\x6e\x20\x54\x2e\x20\x53\x65\x61\x62\x6f\x72\x67\x29\uff0c\u4ed6\u662f\u552f\u4e00\u5728\u4e16\u6642\u5c31\u88ab\u7528\u4f86\u547d\u540d\u5316\u5b78\u5143\u7d20\u7684\u79d1\u5b78\u5bb6\u3002\x31\x39\x37\x34\x20\u5e74\u7531\u67cf\u514b\u840a\u5be6\u9a57\u5ba4\u8207\u675c\u5e03\u7d0d\u5718\u968a\u5171\u540c\u5408\u6210\u3002\ud862\udf4e\u662f\u7b2c\x20\x36\x20\u65cf\u4e2d\u6392\u5728\u927b\x28\x43\x72\x29\u3001\u926c\x28\x4d\x6f\x29\u3001\u93a2\x28\x57\x29\u4e0b\u65b9\u7684\u91cd\u91d1\u5c6c\u6210\u54e1\uff0c\u662f\u4e00\u7a2e\u58fd\u547d\u6975\u77ed\u7684\u5f37\u653e\u5c04\u6027\u5143\u7d20\uff0c\u4ee3\u8868\u4e86\u4eba\u985e\u5c0d\u9ad8\u968e\u904e\u6e21\u91d1\u5c6c\u96fb\u5b50\u8ecc\u57df\u7814\u7a76\u7684\u6975\u81f4\u6975\u9650\u3002\x0a\x0a\ud862\udf4e\u7684\u96fb\u5b50\u7d44\u614b\u9810\u6e2c\u70ba\x20\x5b\x52\x6e\x5d\x35\x66\u00b9\u2074\x36\x64\u2074\x37\x73\u00b2\u3002\u5728\u5316\u5b78\u898f\u5f8b\u4e0a\uff0c\ud862\udf4e\u5c55\u73fe\u4e86\u8207\u93a2\u9ad8\u5ea6\u76f8\u4f3c\u7684\u7279\u5fb5\uff1a\u7a69\u5b9a\u6c27\u5316\u614b\u70ba\x20\x2b\x36\u3002\u5728\u9ad8\u4e2d\u5316\u5b78\u63a2\u8a0e\u904e\u6e21\u91d1\u5c6c\u6027\u8cea\u898f\u5f8b\u6642\uff0c\ud862\udf4e\u63d0\u4f9b\u4e86\u5b8c\u7f8e\u7684\u300c\u65cf\u7fa4\u7a69\u5b9a\u6027\u300d\u8b49\u660e\uff1a\u5be6\u9a57\u8b49\u5be6\ud862\udf4e\u80fd\u8207\u6c27\u53ca\u6c2f\u53cd\u61c9\u751f\u6210\u63ee\u767c\u6027\u7684\u6c27\u6c2f\u5316\u7269\x28\u5982\x20\x53\x67\x4f\u2082\x43\x6c\u2082\x29\uff0c\u5176\u5316\u5b78\u884c\u70ba\u8207\u540c\u65cf\u7684\u926c\u3001\u93a2\u6975\u5176\u4e00\u81f4\u3002\u9019\u7a2e\u9ad8\u5ea6\u7684\u53ef\u9810\u6e2c\u6027\u5728\u8d85\u91cd\u5143\u7d20\u5340\u57df\u6975\u5176\u7f55\u898b\uff0c\u8b49\u660e\u4e86\u7b2c\x20\x36\x20\u65cf\u7684\u5316\u5b78\u8da8\u52e2\u5373\u4fbf\u5728\u5f37\u5927\u76f8\u5c0d\u8ad6\u6548\u61c9\u4e0b\uff0c\u4f9d\u7136\u80fd\u4fdd\u6301\u5b8f\u89c0\u4e0a\u7684\u9023\u8cab\u6027\u3002\x0a\x0a\u5728\u73fe\u4ee3\u61c9\u7528\u4e2d\uff0c\ud862\udf4e\u50c5\u7528\u65bc\u539f\u5b50\u6838\u7d50\u69cb\u8207\u6975\u9650\u5316\u5b78\u9375\u7684\u7814\u7a76\u3002\u540c\u4f4d\u7d20\x20\u00b2\u2076\u2079\x53\x67\x20\u8207\x20\u00b2\u2077\u00b9\x53\x67\x20\u7684\u534a\u8870\u671f\u5206\u5225\u7d04\u70ba\u6578\u5206\u9418\uff0c\u9019\u70ba\u79d1\u5b78\u5bb6\u9032\u884c\u6c23\u76f8\u8272\u8b5c\u8207\u914d\u5408\u4f4d\u5316\u5b78\u5be6\u9a57\u63d0\u4f9b\u4e86\u5fae\u5c0f\u4f46\u8db3\u5920\u7684\u6642\u9593\u7a97\u53e3\u3002\u900f\u904e\u5206\u6790\ud862\udf4e\u5728\u4e0d\u540c\u4ecb\u8cea\u4e2d\u7684\u5438\u9644\u71b1\uff0c\u79d1\u5b78\u5bb6\u5f97\u4ee5\u91cf\u5316\u8d85\u91cd\u539f\u5b50\u6838\u5c0d\u50f9\u96fb\u5b50\u7684\u975c\u96fb\u5f15\u529b\u8207\u76f8\u5c0d\u8ad6\u5fae\u64fe\u3002\u76ee\u524d\ud862\udf4e\u7684\u751f\u7522\u6210\u672c\u6975\u9ad8\uff0c\u7522\u91cf\u50c5\u4ee5\u55ae\u500b\u539f\u5b50\u8a08\uff0c\u662f\u5168\u7403\u6975\u5c11\u6578\u5177\u5099\u91cd\u96e2\u5b50\u52a0\u901f\u5668\u4e4b\u7814\u7a76\u6a5f\u69cb\u7684\u5c08\u5c6c\u9818\u57df\u3002\x0a\x0a\u95dc\u65bc\ud862\udf4e\u7684\u7269\u7406\u73fe\u8c61\uff0c\u5b83\u5c55\u73fe\u4e86\u7269\u8cea\u5728\u6975\u9650\u8cea\u91cf\u4e0b\u7684\u300c\u5316\u5b78\u6163\u6027\u300d\u3002\u5118\u7ba1\u539f\u5b50\u6838\u6975\u5176\u4e0d\u7a69\u5b9a\uff0c\u5176\x20\x36\x64\x20\u8207\x20\x37\x73\x20\u96fb\u5b50\u6240\u69cb\u5efa\u7684\u5316\u5b78\u9375\u537b\u5c55\u73fe\u51fa\u8207\u93a2\u5e7e\u4e4e\u7121\u7570\u7684\u5f37\u5ea6\u3002\u6709\u8da3\u7684\u662f\uff0c\u7576\u5e74\u4ee5\u5e2d\u535a\u683c\u547d\u540d\u7684\u63d0\u6848\u66fe\u5f15\u767c\x20\x49\x55\x50\x41\x43\x20\u7684\u898f\u7bc4\u722d\u8b70\x28\u539f\u5247\u4e0a\u4e0d\u4ee5\u6d3b\u4eba\u547d\u540d\x29\uff0c\u4f46\u6700\u7d42\u56e0\u5176\u5353\u8d8a\u8ca2\u737b\u800c\u7834\u4f8b\u901a\u904e\u3002\u9019\u7a2e\u5f9e\u5b9a\u7fa9\u8d85\u923e\u5143\u7d20\u5bb6\u65cf\u7684\u5049\u5927\u5316\u5b78\u5bb6\u5230\u5b9a\u7fa9\u7b2c\x20\x36\x20\u65cf\u7269\u7406\u6975\u9650\u7684\u653e\u5c04\u6027\u91d1\u5c6c\uff0c\u7cbe\u78ba\u8a6e\u91cb\u4e86\ud862\udf4e\u5728\u9031\u671f\u8868\u4e2d\u627f\u8f09\u79d1\u5b78\u53f2\u8207\u898f\u5f8b\u6027\u96d9\u91cd\u610f\u7fa9\u7684\u5730\u4f4d\u3002",
  "\x42\x68":
    "\ud862\ude0f\x28\x42\x6f\x68\x72\x69\x75\x6d\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x42\x68\uff0c\u539f\u5b50\u5e8f\x20\x31\x30\x37\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u4e03\u9031\u671f\u3001\u7b2c\x20\x37\x20\u65cf\x28\x64\x20\u5340\u584a\x29\u3002\u5176\u540d\u7a31\u6e90\u65bc\u539f\u5b50\u6a21\u578b\u5960\u57fa\u8005\u3001\u4e39\u9ea5\u7269\u7406\u5b78\u5bb6\u5c3c\u723e\u65af\u00b7\u6ce2\u8033\x28\x4e\x69\x65\x6c\x73\x20\x42\x6f\x68\x72\x29\u3002\x31\x39\x38\x31\x20\u5e74\u7531\u5fb7\u570b\u9054\u59c6\u65bd\u5854\u7279\u91cd\u96e2\u5b50\u7814\u7a76\u6240\x28\x47\x53\x49\x29\u5229\u7528\u51b7\u878d\u5408\u6280\u8853\u6210\u529f\u5408\u6210\u3002\ud862\ude0f\u662f\u7b2c\x20\x37\x20\u65cf\u6210\u54e1\uff0c\u4f4d\u65bc\u9333\x28\x4d\x6e\x29\u3001\u939d\x28\x54\x63\x29\u3001\u9338\x28\x52\x65\x29\u4e0b\u65b9\u3002\u4f5c\u70ba\u4e00\u7a2e\u6975\u4e0d\u7a69\u5b9a\u7684\u653e\u5c04\u6027\u91d1\u5c6c\uff0c\ud862\ude0f\u662f\u4eba\u985e\u6e2c\u8a66\u904e\u6e21\u91d1\u5c6c\u5728\u9ad8\u539f\u5b50\u5e8f\u4e0b\u662f\u5426\u4ecd\u9075\u5faa\u300c\u65cf\u898f\u5f8b\u300d\u7684\u95dc\u9375\u6307\u6a19\uff0c\u5c55\u73fe\u4e86\u7269\u8cea\u5728\u6975\u77ac\u4e4b\u9593\u4ecd\u80fd\u7dad\u6301\u6709\u5e8f\u5316\u5b78\u884c\u70ba\u7684\u5947\u8e5f\u3002\x0a\x0a\u5728\u5fae\u89c0\u7279\u5fb5\u4e0a\uff0c\ud862\ude0f\u7684\u96fb\u5b50\u7d44\u614b\u9810\u6e2c\u70ba\x20\x5b\x52\x6e\x5d\x35\x66\u00b9\u2074\x36\x64\u2075\x37\x73\u00b2\u3002\u6839\u64da\u9031\u671f\u5f8b\u63a8\u6e2c\uff0c\ud862\ude0f\u6700\u7a69\u5b9a\u7684\u6c27\u5316\u614b\u61c9\u70ba\x20\x2b\x37\u3002\u5728\u9ad8\u4e2d\u5316\u5b78\u63a2\u8a0e\u591a\u6c27\u5316\u614b\u904e\u6e21\u91d1\u5c6c\u6642\uff0c\ud862\ude0f\u662f\u5ef6\u4f38\u5b78\u7fd2\u7684\u5dd4\u5cf0\u6848\u4f8b\uff1a\u5be6\u9a57\u5ba4\u6210\u529f\u88fd\u5099\u51fa\u63ee\u767c\u6027\u7684\u6c27\u6c2f\u5316\ud862\ude0f\x28\x42\x68\x4f\u2083\x43\x6c\x29\uff0c\u4e26\u8b49\u5be6\u5176\u6027\u8cea\u8207\u540c\u65cf\u7684\u9338\u6c27\u5316\u7269\u9ad8\u5ea6\u76f8\u4f3c\u3002\u9019\u9805\u5be6\u9a57\u6975\u5176\u8271\u96e3\uff0c\u9700\u8981\u5728\u6578\u79d2\u5167\u5b8c\u6210\u55ae\u539f\u5b50\u7684\u5408\u6210\u3001\u5316\u5b78\u53cd\u61c9\u8207\u6c23\u614b\u5206\u96e2\uff0c\u9019\u4e0d\u50c5\u6311\u6230\u4e86\u5316\u5b78\u5100\u5668\u7684\u6975\u9650\uff0c\u4e5f\u9a57\u8b49\u4e86\x20\x36\x64\x20\u8ecc\u57df\u5728\u5f37\u76f8\u5c0d\u8ad6\u6548\u61c9\u4e0b\u4ecd\u5177\u5099\u53c3\u8207\u9ad8\u50f9\u614b\u6210\u9375\u7684\u80fd\u529b\u3002\x0a\x0a\u73fe\u4ee3\u79d1\u5b78\u5c0d\ud862\ude0f\u7684\u7814\u7a76\u4e3b\u8981\u96c6\u4e2d\u65bc\u5176\u6838\u7d50\u69cb\u7a69\u5b9a\u6027\u3002\u6700\u9577\u58fd\u547d\u540c\u4f4d\u7d20\x20\u00b2\x42\x68\x20\u7684\u534a\u8870\u671f\u7d04\u70ba\x20\x36\x31\x20\u79d2\uff0c\u9019\u4f7f\u5176\u5316\u5b78\u7814\u7a76\u76f8\u8f03\u65bc\u5f8c\u7e8c\u5143\u7d20\u7a0d\u5177\u512a\u52e2\u3002\u79d1\u5b78\u5bb6\u900f\u904e\u89c0\u6e2c\ud862\ude0f\u8870\u8b8a\u7522\u51fa\u7684\u80fd\u91cf\u8207\u5b50\u6838\uff0c\u7cbe\u78ba\u7e6a\u88fd\u4e86\u8d85\u91cd\u5143\u7d20\u7684\u8870\u8b8a\u5730\u5716\uff0c\u5354\u52a9\u5b8c\u5584\u539f\u5b50\u6838\u7684\u6bbc\u5c64\u6a21\u578b\x28\x53\x68\x65\x6c\x6c\x20\x6d\x6f\x64\x65\x6c\x29\u3002\u7531\u65bc\u5176\u6975\u9ad8\u7684\u751f\u7522\u96e3\u5ea6\u8207\u77ac\u9593\u8870\u8b8a\u7684\u7279\u6027\uff0c\ud862\ude0f\u76ee\u524d\u5b8c\u5168\u6c92\u6709\u4efb\u4f55\u5546\u696d\u6216\u6280\u8853\u61c9\u7528\uff0c\u50c5\u5b58\u5728\u65bc\u539f\u5b50\u6838\u7269\u7406\u7684\u6700\u524d\u6cbf\u5be6\u9a57\u5ba4\u4e2d\u3002\x0a\x0a\u95dc\u65bc\ud862\ude0f\u7684\u7269\u7406\u7279\u6027\uff0c\u5b83\u5c55\u73fe\u4e86\u91cd\u91d1\u5c6c\u5728\u6c23\u76f8\u4e2d\u7684\u300c\u7a69\u5b9a\u71b1\u529b\u5b78\u898f\u5f8b\u300d\u3002\u5118\u7ba1\ud862\ude0f\u539f\u5b50\u6838\u5728\u4e0d\u5230\u4e00\u5206\u9418\u5167\u5c31\u6703\u74e6\u89e3\uff0c\u4f46\u5728\u5176\u5b58\u5728\u7684\u77ac\u9593\uff0c\u5b83\u4f9d\u7136\u80fd\u5f62\u6210\u5177\u5099\u7279\u5b9a\u5e7e\u4f55\u7d50\u69cb\u7684\u5171\u50f9\u5206\u5b50\u3002\u6709\u8da3\u7684\u662f\uff0c\u96d6\u7136\u6ce2\u8033\u7684\u539f\u5b50\u6a21\u578b\u4e3b\u8981\u63cf\u8ff0\u8f15\u5143\u7d20\uff0c\u4f46\u4ee5\u4ed6\u547d\u540d\u7684\ud862\ude0f\u537b\u8655\u65bc\u9031\u671f\u8868\u7684\u6975\u7aef\u4f4d\u7f6e\uff0c\u9ad4\u73fe\u4e86\u91cf\u5b50\u529b\u5b78\u5f9e\u6c2b\u539f\u5b50\u5230\u8d85\u91cd\u539f\u5b50\u7684\u4e00\u81f4\u6027\u3002\u9019\u7a2e\u5f9e\u91cf\u5b50\u529b\u5b78\u958b\u5c71\u7956\u5e2b\u5230\u5b9a\u7fa9\u7b2c\u4e03\u9031\u671f\u904e\u6e21\u91d1\u5c6c\u908a\u754c\u7684\u8f49\u8b8a\uff0c\u7cbe\u78ba\u8a6e\u91cb\u4e86\ud862\ude0f\u5728\u5316\u5b78\u4e16\u754c\u4e2d\u4f5c\u70ba\u300c\u898f\u5f8b\u6027\u6700\u7d42\u5b88\u885b\u8005\u300d\u7684\u8eab\u5206\u3002",
  "\x48\x73":
    "\ud862\udfe7\x28\x48\x61\x73\x73\x69\x75\x6d\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x48\x73\uff0c\u539f\u5b50\u5e8f\x20\x31\x30\x38\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u4e03\u9031\u671f\u3001\u7b2c\x20\x38\x20\u65cf\x28\x64\x20\u5340\u584a\x29\u3002\u5176\u540d\u7a31\u6e90\u65bc\u5fb7\u570b\u9ed1\u68ee\u5dde\u7684\u62c9\u4e01\u8a9e\u540d\u7a31\u300c\x48\x61\x73\x73\x69\x61\u300d\u3002\x31\x39\x38\x34\x20\u5e74\u7531\u5fb7\u570b\u9054\u59c6\u65bd\u5854\u7279\u91cd\u96e2\u5b50\u7814\u7a76\u6240\x28\x47\x53\x49\x29\u900f\u904e\u925b\x2d\x32\x30\x38\x20\u8207\u9435\x2d\x35\x38\x20\u7684\u96e2\u5b50\u649e\u64ca\u9996\u6b21\u5408\u6210\u3002\ud862\udfe7\u662f\u9435\x28\x46\x65\x29\u3001\u91d5\x28\x52\x75\x29\u3001\u92e8\x28\x4f\x73\x29\u5bb6\u65cf\u4e2d\u6700\u91cd\u7684\u6210\u54e1\uff0c\u5c6c\u65bc\u5f37\u653e\u5c04\u6027\u7684\u4eba\u5de5\u5408\u6210\u5143\u7d20\uff0c\u662f\u76ee\u524d\u79d1\u5b78\u754c\u80fd\u9032\u884c\u5316\u5b78\u5be6\u9a57\u4e26\u78ba\u8a8d\u5176\u65cf\u7fa4\u898f\u5f8b\u7684\u6975\u9650\u91cd\u5143\u7d20\u4e4b\u4e00\u3002\x0a\x0a\u5728\u5fae\u89c0\u7279\u5fb5\u4e0a\uff0c\ud862\udfe7\u7684\u96fb\u5b50\u7d44\u614b\u9810\u6e2c\u70ba\x20\x5b\x52\x6e\x5d\x35\x66\u00b9\u2074\x36\x64\u2076\x37\x73\u00b2\u3002\ud862\udfe7\u6700\u986f\u8457\u7684\u5316\u5b78\u7279\u5fb5\u662f\u5176\u6c27\u5316\u614b\u7684\u9ad8\u5ea6\u898f\u5f8b\u6027\u3002\u6839\u64da\u9ad8\u4e2d\u5316\u5b78\u63a2\u8a0e\u7684\u540c\u65cf\u6027\u8cea\u8da8\u52e2\uff0c\u7b2c\x20\x38\x20\u65cf\u5143\u7d20\u5728\u9031\u671f\u8868\u4e0b\u65b9\u50be\u5411\u65bc\u5c55\u73fe\u6700\u9ad8\u6c27\u5316\u614b\x20\x2b\x38\u3002\x32\x30\x30\x31\x20\u5e74\u79d1\u5b78\u5bb6\u6210\u529f\u88fd\u5099\u51fa\u63ee\u767c\u6027\u7684\u300c\u56db\u6c27\u5316\ud862\udfe7\u300d\x28\x48\x73\x4f\u2084\x29\uff0c\u4e26\u8b49\u5be6\u5176\u7194\u9ede\u8207\u5316\u5b78\u7a69\u5b9a\u6027\u8207\u540c\u65cf\u7684\u92e8\x28\x4f\x73\x4f\u2084\x29\u9ad8\u5ea6\u76f8\u4f3c\u3002\u9019\u9805\u5be6\u9a57\u662f\u5728\u300c\u55ae\u539f\u5b50\u300d\u898f\u6a21\u4e0b\u5b8c\u6210\u7684\u6975\u9650\u6311\u6230\uff0c\u5b8c\u7f8e\u9a57\u8b49\u4e86\u5373\u4fbf\u539f\u5b50\u91cf\u6975\u5927\u4e14\u76f8\u5c0d\u8ad6\u6548\u61c9\u5f37\u70c8\uff0c\u9031\u671f\u5f8b\u5728\u904e\u6e21\u91d1\u5c6c\u5340\u4f9d\u820a\u5c79\u7acb\u4e0d\u6416\u3002\x0a\x0a\u73fe\u4ee3\u79d1\u5b78\u5c0d\ud862\udfe7\u7684\u7814\u7a76\u4e0d\u50c5\u662f\u70ba\u4e86\u589e\u52a0\u5143\u7d20\u6e05\u55ae\uff0c\u66f4\u662f\u70ba\u4e86\u63a2\u7a76\u539f\u5b50\u6838\u7684\u300c\u7a69\u5b9a\u6027\u5cf6\u300d\x28\x49\x73\x6c\x61\x6e\x64\x20\x6f\x66\x20\x53\x74\x61\x62\x69\x6c\x69\x74\x79\x29\u7406\u8ad6\u3002\ud862\udfe7\u7684\u67d0\u4e9b\u540c\u4f4d\u7d20\u5982\x20\u00b2\u2077\u2070\x48\x73\x20\u88ab\u9810\u6e2c\u5177\u6709\u8f03\u5f37\u7684\u6838\u6bbc\u5c64\u7a69\u5b9a\u6027\uff0c\u5176\u534a\u8870\u671f\u7d04\u70ba\x20\x32\x32\x20\u79d2\uff0c\u9019\u5728\u8d85\u91cd\u5143\u7d20\u4e2d\u5df2\u5c6c\u76f8\u5c0d\u9577\u58fd\u3002\u96d6\u7136\ud862\udfe7\u76ee\u524d\u5b8c\u5168\u6c92\u6709\u5de5\u696d\u6216\u5546\u696d\u7528\u9014\uff0c\u4f46\u5b83\u5728\u6838\u7269\u7406\u5b78\u4e2d\u662f\u7814\u7a76\u8d85\u91cd\u539f\u5b50\u6838\u5f62\u72c0\x28\u5982\u8b8a\u5f62\u6210\u6a44\u6b16\u7403\u72c0\x29\u7684\u95dc\u9375\u6a21\u578b\u3002\u7531\u65bc\u5176\u751f\u7522\u6975\u5176\u56f0\u96e3\uff0c\u76ee\u524d\u5168\u7403\u7522\u91cf\u50c5\u4ee5\u55ae\u500b\u539f\u5b50\u8a08\uff0c\u50c5\u5b58\u5728\u65bc\u5177\u5099\u9802\u5c16\u91cd\u96e2\u5b50\u52a0\u901f\u5668\u7684\u5c11\u6578\u7814\u7a76\u6a5f\u69cb\u4e2d\u3002\x0a\x0a\u95dc\u65bc\ud862\udfe7\u7684\u7269\u7406\u73fe\u8c61\uff0c\u5b83\u5c55\u73fe\u4e86\u7269\u8cea\u5728\u6975\u7aef\u539f\u5b50\u5e8f\u4e0b\u7684\u300c\u6c23\u614b\u91d1\u5c6c\u5316\u5408\u7269\u300d\u5947\u8e5f\u3002\u56db\u6c27\u5316\ud862\udfe7\u5728\u5e38\u6eab\u4e0b\u5177\u5099\u986f\u8457\u7684\u63ee\u767c\u6027\uff0c\u80fd\u8207\u7279\u5b9a\u7684\u5075\u6e2c\u5668\u8868\u9762\u767c\u751f\u5316\u5b78\u5438\u9644\u3002\u6709\u8da3\u7684\u662f\uff0c\u96d6\u7136\u4ee5\u5730\u540d\u547d\u540d\uff0c\u4f46\ud862\udfe7\u7684\u767c\u73fe\u4e0d\u50c5\u662f\u5730\u57df\u6027\u7684\u52dd\u5229\uff0c\u66f4\u662f\u4eba\u985e\u5c0d\u91cf\u5b50\u529b\u5b78\u9810\u6e2c\u80fd\u529b\u7684\u4e00\u6b21\u58ef\u89c0\u6aa2\u9a57\u3002\u9019\u7a2e\u5f9e\u5fb7\u570b\u9ed1\u68ee\u5dde\u7684\u5be6\u9a57\u5ba4\u5230\u5b9a\u7fa9\u7b2c\x20\x38\x20\u65cf\u7269\u7406\u898f\u5f8b\u7d42\u9ede\u7684\u8de8\u5ea6\uff0c\u7cbe\u78ba\u8a6e\u91cb\u4e86\ud862\udfe7\u5728\u9031\u671f\u8868\u4e2d\u4f5c\u70ba\u300c\u898f\u5f8b\u6027\u71c8\u5854\u300d\u7684\u5730\u4f4d\u3002",
  "\x4d\x74":
    "\u4951\x28\x4d\x65\x69\x74\x6e\x65\x72\x69\x75\x6d\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x4d\x74\uff0c\u539f\u5b50\u5e8f\x20\x31\x30\x39\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u4e03\u9031\u671f\u3001\u7b2c\x20\x39\x20\u65cf\x28\x64\x20\u5340\u584a\x29\u3002\u5176\u540d\u7a31\u662f\u70ba\u4e86\u81f4\u656c\u767c\u73fe\u6838\u5206\u88c2\u73fe\u8c61\u7684\u7336\u592a\u88d4\u7269\u7406\u5b78\u5bb6\u8389\u6fa4\u00b7\u9081\u7279\u7d0d\x28\x4c\x69\x73\x65\x20\x4d\x65\x69\x74\x6e\x65\x72\x29\uff0c\u5979\u662f\u6b77\u53f2\u4e0a\u9996\u4f4d\u55ae\u7368\u4ee5\u975e\u795e\u8a71\u5973\u6027\u79d1\u5b78\u5bb6\u547d\u540d\u7684\u5143\u7d20\u3002\x31\x39\x38\x32\x20\u5e74\u7531\u5fb7\u570b\x20\x47\x53\x49\x20\u7814\u7a76\u5718\u968a\u900f\u904e\u51b7\u878d\u5408\u6280\u8853\u9996\u6b21\u5408\u6210\u3002\u4951\u662f\u7b2c\x20\x39\x20\u65cf\u4e2d\u6700\u91cd\u7684\u6210\u54e1\uff0c\u6392\u5728\u9237\x28\x43\x6f\x29\u3001\u92a0\x28\x52\x68\x29\u3001\u92a5\x28\x49\x72\x29\u4e4b\u4e0b\uff0c\u662f\u6975\u5176\u4e0d\u7a69\u5b9a\u4e14\u6975\u96e3\u88fd\u5f97\u7684\u4eba\u5de5\u653e\u5c04\u6027\u5143\u7d20\u3002\x0a\x0a\u4951\u7684\u96fb\u5b50\u7d44\u614b\u9810\u6e2c\u70ba\x20\x5b\x52\x6e\x5d\x35\x66\u00b9\u2074\x36\x64\u2077\x37\x73\u00b2\u3002\u7531\u65bc\u539f\u5b50\u5e8f\u6975\u9ad8\uff0c\u4951\u7684\x20\x36\x64\x20\u8207\x20\x37\x73\x20\u96fb\u5b50\u53d7\u5230\u5287\u70c8\u7684\u76f8\u5c0d\u8ad6\u6548\u61c9\x28\x52\x65\x6c\x61\x74\x69\x76\x69\x73\x74\x69\x63\x20\x65\x66\x66\x65\x63\x74\x73\x29\u5f71\u97ff\uff0c\u5c0e\u81f4\u5176\u8ecc\u57df\u80fd\u91cf\u767c\u751f\u986f\u8457\u8b8a\u5316\u3002\u5728\u9ad8\u4e2d\u5316\u5b78\u63a2\u8a0e\u904e\u6e21\u91d1\u5c6c\u6027\u8cea\u6642\uff0c\u4951\u4ee3\u8868\u4e86\u898f\u5f8b\u6027\u9810\u6e2c\u7684\u6975\u9650\u3002\u96d6\u7136\u56e0\u534a\u8870\u671f\u6975\u77ed\x28\u6700\u9577\u58fd\u540c\u4f4d\u7d20\x20\u00b2\u2077\u2078\x4d\x74\x20\u50c5\u7d04\x20\x34\x2e\x35\x20\u79d2\x29\u800c\u6975\u96e3\u9032\u884c\u6db2\u76f8\u5316\u5b78\u5be6\u9a57\uff0c\u4f46\u6839\u64da\u5176\u5728\u9031\u671f\u8868\u7684\u4f4d\u7f6e\uff0c\u79d1\u5b78\u5bb6\u9810\u6e2c\u5176\u5316\u5b78\u6027\u8cea\u61c9\u8207\u92a5\u76f8\u4f3c\uff0c\u5448\u73fe\u51fa\u9ad8\u5ea6\u7684\u5316\u5b78\u60f0\u6027\u8207\u7a69\u5b9a\u7684\u9ad8\u50f9\u614b\u8da8\u5411\u3002\x0a\x0a\u4951\u5728\u73fe\u4ee3\u79d1\u5b78\u4e2d\u7684\u50f9\u503c\u4e3b\u8981\u9ad4\u73fe\u5728\u539f\u5b50\u6838\u7269\u7406\u7684\u57fa\u790e\u63a2\u7a76\u3002\u4951\u7684\u767c\u73fe\u904e\u7a0b\u6a19\u8a8c\u8457\u300c\u51b7\u878d\u5408\u300d\u6280\u8853\u7684\u6210\u719f\uff0c\u9019\u662f\u4e00\u7a2e\u7522\u751f\u8d85\u91cd\u5143\u7d20\u6642\u5269\u9918\u80fd\u91cf\u8f03\u5c11\u3001\u8f03\u6613\u4fdd\u7559\u539f\u5b50\u6838\u7d50\u69cb\u7684\u65b9\u6cd5\u3002\u76ee\u524d\u4951\u5b8c\u5168\u6c92\u6709\u4efb\u4f55\u5546\u696d\u61c9\u7528\uff0c\u50c5\u5b58\u5728\u65bc\u539f\u5b50\u6838\u7269\u7406\u7684\u6700\u524d\u6cbf\u3002\u7531\u65bc\u5176\u5408\u6210\u6a5f\u7387\u6975\u4f4e\x28\u6578\u9031\u7684\u5be6\u9a57\u53ef\u80fd\u50c5\u7522\u751f\u4e00\u500b\u539f\u5b50\x29\uff0c\u4951\u7684\u7814\u7a76\u4e0d\u50c5\u662f\u5c0d\u79d1\u5b78\u5bb6\u8010\u5fc3\u7684\u8003\u9a57\uff0c\u66f4\u662f\u5c0d\u73fe\u6709\u6838\u7d50\u69cb\u6a21\u578b\u7cbe\u78ba\u5ea6\u7684\u6975\u9650\u6e2c\u8a66\u3002\x0a\x0a\u95dc\u65bc\u4951\u7684\u7269\u7406\u7279\u5fb5\uff0c\u5b83\u5c55\u73fe\u4e86\u8d85\u91cd\u5143\u7d20\u4e2d\u300c\u77ed\u66ab\u800c\u8000\u773c\u300d\u7684\u7279\u8cea\u3002\u96d6\u7136\u5b83\u662f\u91d1\u5c6c\uff0c\u4f46\u7531\u65bc\u5176\u5f37\u5927\u7684\u653e\u5c04\u6027\u80fd\u91cf\uff0c\u5373\u4fbf\u80fd\u805a\u96c6\u5b8f\u89c0\u6a23\u672c\uff0c\u4e5f\u6703\u56e0\u81ea\u8eab\u8870\u8b8a\u7522\u751f\u7684\u71b1\u91cf\u800c\u77ac\u9593\u7194\u5316\u3002\u6709\u8da3\u7684\u662f\uff0c\u4951\u7684\u547d\u540d\u66fe\u662f\u5316\u5b78\u53f2\u4e0a\u300c\u5143\u7d20\u547d\u540d\u5927\u6230\u300d\u7684\u91cd\u8981\u4e00\u74b0\uff0c\u6700\u7d42\u7531\u9081\u7279\u7d0d\u7372\u6b64\u6b8a\u69ae\uff0c\u5e73\u8861\u4e86\u65e9\u671f\u79d1\u5b78\u53f2\u5c0d\u5973\u6027\u8ca2\u737b\u7684\u5ffd\u8996\u3002\u9019\u7a2e\u5f9e\u6838\u5206\u88c2\u7406\u8ad6\u7684\u5960\u57fa\u8005\u5230\u8de8\u8d8a\u8d85\u9312\u7cfb\u9580\u6abb\u7684\u91cd\u91d1\u5c6c\uff0c\u7cbe\u78ba\u8a6e\u91cb\u4e86\u4951\u5728\u79d1\u5b78\u53f2\u4e0a\u4f5c\u70ba\u300c\u6b63\u7fa9\u8207\u898f\u5f8b\u300d\u8c61\u5fb5\u7684\u8eab\u5206\u3002",
  "\x44\x73":
    "\u943d\x28\x44\x61\x72\x6d\x73\x74\x61\x64\x74\x69\x75\x6d\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x44\x73\uff0c\u539f\u5b50\u5e8f\x20\x31\x31\x30\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u4e03\u9031\u671f\u3001\u7b2c\x20\x31\x30\x20\u65cf\x28\x64\x20\u5340\u584a\x29\u3002\u5176\u540d\u7a31\u6e90\u65bc\u5fb7\u570b\u7684\u79d1\u5b78\u91cd\u93ae\u9054\u59c6\u65bd\u5854\u7279\x28\x44\x61\x72\x6d\x73\x74\x61\x64\x74\x29\u3002\x31\x39\x39\x34\x20\u5e74\u7531\u9054\u59c6\u65bd\u5854\u7279\u91cd\u96e2\u5b50\u7814\u7a76\u6240\x28\x47\x53\x49\x29\u5718\u968a\u5229\u7528\u93b3\u96e2\u5b50\u8f5f\u64ca\u925b\u9776\u9996\u6b21\u88fd\u5f97\u3002\u943d\u662f\u7b2c\x20\x31\x30\x20\u65cf\x28\u93b3\u65cf\u5143\u7d20\x29\u4e2d\u6700\u91cd\u7684\u6210\u54e1\uff0c\u4f4d\u65bc\u93b3\x28\x4e\x69\x29\u3001\u9200\x28\x50\x64\x29\u3001\u9251\x28\x50\x74\x29\u6b63\u4e0b\u65b9\u3002\u5b83\u662f\u4e00\u7a2e\u6975\u5176\u77ed\u547d\u7684\u5f37\u653e\u5c04\u6027\u91d1\u5c6c\uff0c\u4ee3\u8868\u4e86\u4eba\u985e\u5728\x20\x32\x30\x20\u4e16\u7d00\u672b\u5c0d\u91cd\u96e2\u5b50\u878d\u5408\u6280\u8853\u638c\u63a7\u80fd\u529b\u7684\u91cd\u5927\u91cc\u7a0b\u7891\u3002\x0a\x0a\u943d\u7684\u96fb\u5b50\u7d44\u614b\u9810\u6e2c\u70ba\x20\x5b\x52\x6e\x5d\x35\x66\u00b9\u2074\x36\x64\u2078\x37\x73\u00b2\uff0c\u4f46\u4e5f\u53ef\u80fd\u53d7\u5f37\u5927\u7684\u76f8\u5c0d\u8ad6\u6548\u61c9\u5f71\u97ff\u800c\u767c\u751f\x20\x36\x64\x20\u8207\x20\x37\x73\x20\u8ecc\u57df\u7684\u80fd\u7d1a\u91cd\u758a\u3002\u5728\u9ad8\u4e2d\u5316\u5b78\u63a2\u8a0e\u7b2c\x20\x31\x30\x20\u65cf\u5143\u7d20\u6642\uff0c\u9019\u4e9b\u5143\u7d20\u901a\u5e38\u5177\u5099\u5353\u8d8a\u7684\u50ac\u5316\u80fd\u529b\u8207\u5316\u5b78\u7a69\u5b9a\u6027\u3002\u79d1\u5b78\u5bb6\u9810\u6e2c\uff0c\u943d\u5728\u5316\u5b78\u6027\u8cea\u4e0a\u61c9\u985e\u4f3c\u65bc\u9251\x28\x50\x74\x29\uff0c\u5c55\u73fe\u51fa\u6975\u5f37\u7684\u5316\u5b78\u60f0\u6027\u8207\u591a\u6a23\u7684\u914d\u4f4d\u5e7e\u4f55\u7d50\u69cb\u3002\u7136\u800c\uff0c\u53d7\u76f8\u5c0d\u8ad6\u6027\u6536\u7e2e\x28\x52\x65\x6c\x61\x74\x69\x76\x69\x73\x74\x69\x63\x20\x63\x6f\x6e\x74\x72\x61\x63\x74\x69\x6f\x6e\x29\u5f71\u97ff\uff0c\u943d\u7684\x20\x37\x73\x20\u8ecc\u57df\u80fd\u91cf\u5927\u5e45\u4e0b\u964d\uff0c\u4f7f\u5176\u5316\u5b78\u884c\u70ba\u53ef\u80fd\u5448\u73fe\u51fa\u67d0\u7a2e\u7a0b\u5ea6\u7684\u300c\u985e\u91d1\u300d\u7279\u5fb5\uff0c\u9019\u589e\u52a0\u4e86\u9810\u6e2c\u5176\u7cbe\u78ba\u6027\u8cea\u7684\u96e3\u5ea6\u3002\x0a\x0a\u5728\u73fe\u4ee3\u61c9\u7528\u4e2d\uff0c\u943d\u5b8c\u5168\u5c40\u9650\u65bc\u539f\u5b50\u7269\u7406\u8207\u91cd\u5143\u7d20\u5408\u6210\u7406\u8ad6\u7684\u7814\u7a76\u3002\u6700\u7a69\u5b9a\u7684\u540c\u4f4d\u7d20\x20\u00b2\u2078\u00b9\x44\x73\x20\u534a\u8870\u671f\u50c5\u7d04\x20\x31\x31\x20\u79d2\uff0c\u9019\u4f7f\u5f97\u9032\u884c\u50b3\u7d71\u5b8f\u89c0\u5316\u5b78\u5be6\u9a57\u5e7e\u4e4e\u4e0d\u53ef\u80fd\u3002\u79d1\u5b78\u5bb6\u4e3b\u8981\u900f\u904e\u89c0\u6e2c\u5176\x20\u03b1\x20\u8870\u8b8a\u93c8\u4f86\u9451\u5b9a\u5176\u8eab\u5206\uff0c\u4e26\u7814\u7a76\u5176\u539f\u5b50\u6838\u5728\u6975\u9650\u5f15\u529b\u4e0b\u7684\u7a69\u5b9a\u6027\u3002\u76ee\u524d\u943d\u7684\u751f\u7522\u50c5\u80fd\u900f\u904e\u6602\u8cb4\u7684\u9ad8\u80fd\u52a0\u901f\u5668\u9032\u884c\uff0c\u662f\u6975\u5c11\u6578\u5177\u5099\u8de8\u570b\u79d1\u7814\u5be6\u529b\u7684\u6a5f\u69cb\u624d\u80fd\u89f8\u53ca\u7684\u79d1\u5b78\u9818\u57df\uff0c\u5354\u52a9\u4eba\u985e\u63a2\u7a76\u9031\u671f\u8868\u672b\u7aef\u7684\u7d50\u69cb\u908a\u754c\u3002\x0a\x0a\u95dc\u65bc\u943d\u7684\u7269\u7406\u73fe\u8c61\uff0c\u5b83\u5c55\u73fe\u4e86\u7269\u8cea\u5728\u6975\u9ad8\u539f\u5b50\u5e8f\u4e0b\u7684\u300c\u5bc6\u5ea6\u5dd4\u5cf0\u300d\u9810\u6e2c\u3002\u79d1\u5b78\u5bb6\u63a8\u6e2c\uff0c\u82e5\u80fd\u88fd\u5099\u5b8f\u89c0\u7684\u943d\u91d1\u5c6c\uff0c\u5176\u5bc6\u5ea6\u53ef\u80fd\u9ad8\u9054\x20\x33\x34\x2e\x38\x20\x67\x2f\x63\x6d\u00b3\uff0c\u5e7e\u4e4e\u662f\u9ec3\u91d1\u7684\u5169\u500d\u3002\u6709\u8da3\u7684\u662f\uff0c\u5728\u943d\u6b63\u5f0f\u547d\u540d\u4e4b\u524d\uff0c\u79d1\u5b78\u754c\u66fe\u66ab\u6642\u7a31\u5176\u70ba\u300c\u985e\u9251\u300d\x28\x65\x6b\x61\x2d\x70\x6c\x61\x74\x69\x6e\x75\x6d\x29\u3002\u5b83\u7684\u6210\u529f\u5408\u6210\uff0c\u958b\u555f\u4e86\u4eba\u985e\u9081\u5411\u66f4\u91cd\u5143\u7d20\x28\u5982\u9fdf\u3001\u9fec\u7b49\x29\u7684\u95dc\u9375\u5927\u9580\u3002\u9019\u7a2e\u5f9e\u5fb7\u570b\u79d1\u5b78\u4e4b\u57ce\u7684\u69ae\u8000\u5230\u5b9a\u7fa9\u7b2c\x20\x31\x30\x20\u65cf\u91cd\u91d1\u5c6c\u7269\u7406\u6975\u9650\u7684\u8f49\u8b8a\uff0c\u7cbe\u78ba\u8a6e\u91cb\u4e86\u943d\u5728\u9031\u671f\u8868\u4e2d\u4f5c\u70ba\u300c\u91cd\u5143\u7d20\u7269\u7406\u57fa\u77f3\u300d\u7684\u7368\u7279\u8eab\u5206\u3002",
  "\x52\x67":
    "\u9300\x28\x52\x6f\x65\x6e\x74\x67\x65\x6e\x69\x75\x6d\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x52\x67\uff0c\u539f\u5b50\u5e8f\x20\x31\x31\x31\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u4e03\u9031\u671f\u3001\u7b2c\x20\x31\x31\x20\u65cf\x28\x64\x20\u5340\u584a\x29\u3002\u5176\u540d\u7a31\u662f\u70ba\u4e86\u7d00\u5ff5\x20\x58\x20\u5c04\u7dda\u7684\u767c\u73fe\u8005\u3001\u8afe\u8c9d\u723e\u734e\u5f97\u4e3b\u5a01\u5ec9\u00b7\u502b\u7434\x28\x57\x69\x6c\x68\x65\x6c\x6d\x20\x52\u00f6\x6e\x74\x67\x65\x6e\x29\u3002\x31\x39\x39\x34\x20\u5e74\u7531\u5fb7\u570b\u9054\u59c6\u65bd\u5854\u7279\u91cd\u96e2\u5b50\u7814\u7a76\u6240\x28\x47\x53\x49\x29\u900f\u904e\u93b3\x2d\x36\x34\x20\u96e2\u5b50\u8f5f\u64ca\u924d\x2d\x32\x30\x39\x20\u9776\u9996\u6b21\u6210\u529f\u5408\u6210\u3002\u8eab\u70ba\u9285\x28\x43\x75\x29\u3001\u9280\x28\x41\x67\x29\u3001\u91d1\x28\x41\x75\x29\u5bb6\u65cf\u4e2d\u6700\u91cd\u7684\u6210\u54e1\uff0c\u9300\u4ee3\u8868\u4e86\u4eba\u985e\u5c0d\u300c\u5e63\u91d1\u5c6c\u300d\u65cf\u7fa4\u5728\u9ad8\u80fd\u7269\u7406\u74b0\u5883\u4e0b\u6027\u8cea\u5ef6\u4f38\u7684\u6975\u81f4\u63a2\u7d22\u3002\x0a\x0a\u5728\u5fae\u89c0\u7d44\u614b\u4e0a\uff0c\u9300\u7684\u96fb\u5b50\u7d44\u614b\u9810\u6e2c\u70ba\x20\x5b\x52\x6e\x5d\x35\x66\u00b9\u2074\x36\x64\u2079\x37\x73\u00b2\u3002\u7531\u65bc\u539f\u5b50\u5e8f\u6975\u9ad8\uff0c\u9300\u53d7\u5230\u4e86\u5f37\u70c8\u7684\u76f8\u5c0d\u8ad6\u6027\u6548\u61c9\x28\x52\x65\x6c\x61\x74\x69\x76\x69\x73\x74\x69\x63\x20\x65\x66\x66\x65\x63\x74\x73\x29\u5f71\u97ff\uff0c\u9019\u5c0e\u81f4\u5176\x20\x37\x73\x20\u8ecc\u57df\u80fd\u7d1a\u986f\u8457\u4e0b\u964d\u4e26\u8207\x20\x36\x64\x20\u8ecc\u57df\u7522\u751f\u5f37\u70c8\u7684\u80fd\u968e\u91cd\u758a\u3002\u5728\u9ad8\u4e2d\u5316\u5b78\u63a2\u8a0e\u7b2c\x20\x31\x31\x20\u65cf\u5143\u7d20\u7a69\u5b9a\u6027\u6642\uff0c\u91d1\u8207\u9280\u901a\u5e38\u5177\u5099\u5353\u8d8a\u7684\u5316\u5b78\u60f0\u6027\uff0c\u800c\u7406\u8ad6\u9810\u6e2c\u9300\u53ef\u80fd\u6bd4\u91d1\u66f4\u5177\u5099\u904e\u6e21\u91d1\u5c6c\u7684\u7279\u5fb5\uff0c\u6c27\u5316\u614b\u53ef\u80fd\u9054\u5230\x20\x2b\x33\x20\u751a\u81f3\x20\x2b\x35\u3002\u76ee\u524d\u79d1\u5b78\u5bb6\u50c5\u80fd\u900f\u904e\u55ae\u539f\u5b50\u8870\u8b8a\u93c8\u89c0\u6e2c\u5176\u6838\u6027\u8cea\uff0c\u6700\u9577\u58fd\u540c\u4f4d\u7d20\x20\u00b2\u2078\u00b2\x52\x67\x20\u7684\u534a\u8870\u671f\u50c5\u7d04\x20\x31\x30\x30\x20\u79d2\u3002\x0a\x0a\u73fe\u4ee3\u79d1\u5b78\u5c0d\u65bc\u9300\u7684\u7814\u7a76\u4e3b\u8981\u96c6\u4e2d\u65bc\u9a57\u8b49\u300c\u76f8\u5c0d\u8ad6\u5316\u5b78\u300d\u7684\u7cbe\u78ba\u5ea6\u3002\u7531\u65bc\u5176\x20\x36\x64\x20\u8207\x20\x37\x73\x20\u96fb\u5b50\u7684\u7279\u6b8a\u4ea4\u4e92\u4f5c\u7528\uff0c\u9300\u7684\u7269\u7406\u6027\u8cea\u53ef\u80fd\u504f\u96e2\u5176\u4e0a\u65b9\u6210\u54e1\u7684\u55ae\u5411\u8da8\u52e2\uff0c\u5c55\u73fe\u51fa\u7368\u7279\u7684\u91d1\u5c6c\u9375\u5f37\u5ea6\u3002\u76ee\u524d\u9300\u5b8c\u5168\u6c92\u6709\u5546\u696d\u6216\u6280\u8853\u61c9\u7528\uff0c\u50c5\u5b58\u5728\u65bc\u5177\u5099\u8d85\u5927\u578b\u7c92\u5b50\u52a0\u901f\u5668\u7684\u9802\u5c16\u5be6\u9a57\u5ba4\u3002\u5b83\u7684\u5408\u6210\u6a5f\u7387\u6975\u4f4e\uff0c\u5f80\u5f80\u9700\u8981\u6578\u9031\u7684\u6301\u7e8c\u8f5f\u64ca\u624d\u80fd\u7372\u5f97\u6578\u500b\u539f\u5b50\u3002\u5728\u6750\u6599\u79d1\u5b78\u524d\u6cbf\uff0c\u9300\u7684\u7814\u7a76\u5354\u52a9\u79d1\u5b78\u5bb6\u5fae\u8abf\u539f\u5b50\u6838\u6bbc\u5c64\u6a21\u578b\uff0c\u70ba\u5c0b\u627e\u66f4\u91cd\u7684\u7a69\u5b9a\u5143\u7d20\u63d0\u4f9b\u6578\u64da\u652f\u6490\u3002\x0a\x0a\u95dc\u65bc\u9300\u7684\u7269\u7406\u73fe\u8c61\uff0c\u5b83\u5c55\u73fe\u4e86\u91cd\u91d1\u5c6c\u5728\u6975\u9650\u72c0\u614b\u4e0b\u7684\u300c\u5bc6\u5ea6\u9810\u6e2c\u300d\u5947\u8e5f\u3002\u79d1\u5b78\u5bb6\u63a8\u6e2c\uff0c\u82e5\u80fd\u88fd\u5099\u5b8f\u89c0\u7684\u9300\u91d1\u5c6c\uff0c\u5176\u5bc6\u5ea6\u53ef\u80fd\u9ad8\u9054\x20\x32\x38\x2e\x37\x20\x67\x2f\x63\x6d\u00b3\uff0c\u9060\u8d85\u9ec3\u91d1\u8207\u9251\u3002\u6709\u8da3\u7684\u662f\uff0c\u96d6\u7136\u4ee5\u502b\u7434\u547d\u540d\uff0c\u4f46\u9300\u672c\u8eab\u4e26\u4e0d\u767c\u5c04\x20\x58\x20\u5c04\u7dda\uff0c\u800c\u662f\u900f\u904e\x20\u03b1\x20\u8870\u8b8a\u91cb\u653e\u9ad8\u80fd\u6c26\u6838\u3002\u9019\u7a2e\u5f9e\u5b9a\u7fa9\u73fe\u4ee3\u91ab\u5b78\u5f71\u50cf\u7684\u79d1\u5b78\u5bb6\u5230\u5b9a\u7fa9\u7b2c\x20\x31\x31\x20\u65cf\u7269\u7406\u908a\u754c\u7684\u653e\u5c04\u6027\u5143\u7d20\uff0c\u7cbe\u78ba\u8a6e\u91cb\u4e86\u9300\u5728\u9031\u671f\u8868\u4e2d\u4f5c\u70ba\u300c\u91cd\u91d1\u5c6c\u898f\u5f8b\u63a2\u7d22\u8005\u300d\u7684\u5730\u4f4d\u3002",
  "\x43\x6e":
    "\u93b6\x20\x28\x43\x6f\x70\x65\x72\x6e\x69\x63\x69\x75\x6d\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x43\x6e\uff0c\u539f\u5b50\u5e8f\x20\x31\x31\x32\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u4e03\u9031\u671f\u3001\u7b2c\x20\x31\x32\x20\u65cf\x28\x64\x20\u5340\u584a\x29\u3002\u5176\u540d\u7a31\u662f\u70ba\u4e86\u81f4\u656c\u6ce2\u862d\u5929\u6587\u5b78\u5bb6\u5c3c\u53e4\u62c9\u00b7\u54e5\u767d\u5c3c\x28\x4e\x69\x63\x6f\x6c\x61\x75\x73\x20\x43\x6f\x70\x65\x72\x6e\x69\x63\x75\x73\x29\uff0c\u8c61\u5fb5\u5176\u5728\u79d1\u5b78\u53f2\u4e0a\u7ffb\u8f49\u4e16\u754c\u89c0\u7684\u8ca2\u737b\u3002\x31\x39\x39\x36\x20\u5e74\u7531\u5fb7\u570b\x20\x47\x53\x49\x20\u7814\u7a76\u5718\u968a\u9996\u6b21\u5408\u6210\u3002\u93b6\u6392\u5728\u92c5\x28\x5a\x6e\x29\u3001\u9398\x28\x43\x64\x29\u3001\u6c5e\x28\x48\x67\x29\u4e4b\u4e0b\uff0c\u662f\u76ee\u524d\u5df2\u77e5\u6700\u91cd\u7684\u7b2c\x20\x31\x32\x20\u65cf\u6210\u54e1\u3002\u5b83\u5728\u7269\u7406\u6027\u8cea\u4e0a\u5c55\u73fe\u51fa\u6975\u7aef\u8ff7\u4eba\u7684\u300c\u53cd\u898f\u5f8b\u300d\u73fe\u8c61\uff0c\u88ab\u8996\u70ba\u76f8\u5c0d\u8ad6\u6548\u61c9\u91cd\u5851\u5143\u7d20\u8eab\u5206\u7684\u5178\u578b\u6848\u4f8b\u3002\x0a\x0a\u93b6\u7684\u96fb\u5b50\u7d44\u614b\u9810\u6e2c\u70ba\x20\x5b\x52\x6e\x5d\x35\x66\u00b9\u2074\x36\x64\u00b9\u2070\x37\x73\u00b2\u3002\u7531\u65bc\x20\x37\x73\x20\u8ecc\u57df\u53d7\u5230\u5f37\u70c8\u7684\u76f8\u5c0d\u8ad6\u6027\u6536\u7e2e\u8207\u7a69\u5b9a\u5316\u5f71\u97ff\uff0c\u93b6\u7684\u50f9\u96fb\u5b50\u88ab\u539f\u5b50\u6838\u675f\u7e1b\u5f97\u6975\u5176\u7dca\u5bc6\uff0c\u5c55\u73fe\u51fa\u985e\u4f3c\u7a00\u6709\u6c23\u9ad4\u7684\u300c\u5316\u5b78\u60f0\u6027\u300d\u3002\u5728\u9ad8\u4e2d\u5316\u5b78\u63a2\u8a0e\u7b2c\x20\x31\x32\x20\u65cf\u5143\u7d20\u63ee\u767c\u6027\u8da8\u52e2\u6642\uff0c\u6c5e\x28\x48\x67\x29\u5728\u5e38\u6eab\u4e0b\u70ba\u6db2\u614b\u5df2\u662f\u986f\u8457\u7279\u4f8b\uff0c\u800c\u7406\u8ad6\u8207\u521d\u6b65\u5be6\u9a57\u986f\u793a\uff0c\u93b6\u53ef\u80fd\u5177\u5099\u6975\u5f37\u7684\u63ee\u767c\u6027\uff0c\u751a\u81f3\u5728\u6a19\u6e96\u72c0\u614b\u4e0b\u53ef\u80fd\u662f\u300c\u6c23\u614b\u91d1\u5c6c\u300d\u3002\u9019\u7a2e\u7531\u76f8\u5c0d\u8ad6\u6548\u61c9\u5c0e\u81f4\u7684\u91d1\u5c6c\u9375\u5f31\u5316\uff0c\u4f7f\u5176\u884c\u70ba\u5728\u67d0\u4e9b\u5be6\u9a57\u4e2d\u66f4\u63a5\u8fd1\u65bc\u6c21\x28\x52\x6e\x29\u3002\x0a\x0a\u76ee\u524d\u5c0d\u65bc\u93b6\u7684\u5316\u5b78\u5be6\u9a57\u4e3b\u8981\u96c6\u4e2d\u5728\u89c0\u6e2c\u5176\u8207\u91d1\u8868\u9762\u7684\u4ea4\u4e92\u4f5c\u7528\u3002\u79d1\u5b78\u5bb6\u5229\u7528\u6c23\u76f8\u5c64\u6790\u6280\u8853\u767c\u73fe\uff0c\u93b6\u539f\u5b50\u5728\u91d1\u8868\u9762\u4e0a\u7684\u5438\u9644\u5f37\u5ea6\u4f4e\u65bc\u6c5e\u4f46\u9ad8\u65bc\u5178\u578b\u7684\u7a00\u6709\u6c23\u9ad4\uff0c\u9019\u8b49\u5be6\u4e86\u5b83\u96d6\u7136\u5177\u5099\u5f37\u70c8\u7684\u76f8\u5c0d\u8ad6\u60f0\u6027\uff0c\u4f46\u4ecd\u4fdd\u7559\u4e86\u91d1\u5c6c\u9375\u7d50\u7684\u6b98\u9918\u7279\u5fb5\u3002\u76ee\u524d\u93b6\u5b8c\u5168\u7522\u81ea\u8ff4\u65cb\u52a0\u901f\u5668\uff0c\u6700\u7a69\u5b9a\u7684\u540c\u4f4d\u7d20\x20\u00b2\u2078\u2075\x43\x6e\x20\u534a\u8870\u671f\u7d04\u70ba\x20\x32\x38\x20\u79d2\u3002\u7531\u65bc\u5176\u88fd\u5099\u6210\u672c\u6975\u9ad8\u4e14\u7522\u91cf\u6975\u7a00\uff0c\u76ee\u524d\u50c5\u7528\u65bc\u57fa\u790e\u6838\u7269\u7406\u7814\u7a76\uff0c\u5354\u52a9\u4eba\u985e\u63a2\u8a0e\u539f\u5b50\u6838\u8207\u96fb\u5b50\u96f2\u5728\u8d85\u9ad8\u96fb\u8377\u74b0\u5883\u4e0b\u7684\u8026\u5408\u6a5f\u5236\u3002\x0a\x0a\u93b6\u5728\u73fe\u8c61\u5b78\u4e0a\u5c55\u73fe\u4e86\u7269\u7406\u5b78\u4e2d\u300c\u6163\u6027\u96fb\u5b50\u5c0d\u300d\u7684\u6975\u81f4\u8868\u73fe\u3002\u7531\u65bc\u5176\x20\x37\x73\u00b2\x20\u96fb\u5b50\u5c0d\u6975\u5ea6\u7a69\u5b9a\uff0c\u93b6\u7684\u5316\u5b78\u53cd\u61c9\u6027\u6975\u4f4e\uff0c\u9019\u6311\u6230\u4e86\u6211\u5011\u5c0d\u91d1\u5c6c\u300c\u6613\u5931\u53bb\u96fb\u5b50\u300d\u7684\u65e2\u5b9a\u5370\u8c61\u3002\u6709\u8da3\u7684\u662f\uff0c\u96d6\u7136\u4ee5\u54e5\u767d\u5c3c\u547d\u540d\uff0c\u4f46\u91d1\u5c6c\u93b6\u5728\u539f\u5b50\u5c64\u9762\u7684\u884c\u70ba\u8207\u661f\u9ad4\u904b\u884c\u7684\u898f\u5f8b\u540c\u6a23\u7cbe\u78ba\u4e14\u6df1\u5967\u3002\u9019\u7a2e\u5f9e\u6539\u8b8a\u4eba\u985e\u5b87\u5b99\u89c0\u7684\u5929\u6587\u5b78\u5bb6\u5230\u5b9a\u7fa9\u91d1\u5c6c\u8207\u6c23\u9ad4\u908a\u754c\u7684\u8d85\u91cd\u5143\u7d20\uff0c\u7cbe\u78ba\u8a6e\u91cb\u4e86\u93b6\u5728\u9031\u671f\u8868\u4e2d\u4f5c\u70ba\u300c\u76f8\u5c0d\u8ad6\u6027\u91d1\u5c6c\u300d\u7684\u7368\u7279\u9b45\u529b\u3002",
  "\x4e\x68":
    "\u9268\x20\x28\x4e\x69\x68\x6f\x6e\x69\x75\x6d\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x4e\x68\uff0c\u539f\u5b50\u5e8f\x20\x31\x31\x33\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u4e03\u9031\u671f\u3001\u7b2c\x20\x31\x33\x20\u65cf\x28\x70\x20\u5340\u584a\x29\u3002\u5176\u540d\u7a31\u6e90\u65bc\u65e5\u672c\x28\x4e\x69\x68\x6f\x6e\x29\uff0c\u662f\u6b77\u53f2\u4e0a\u7b2c\u4e00\u500b\u7531\u4e9e\u6d32\u79d1\u5b78\u5718\u968a\u547d\u540d\u4e26\u7372\u5f97\u570b\u969b\u516c\u8a8d\u7684\u5316\u5b78\u5143\u7d20\u3002\x32\x30\x30\x34\x20\u5e74\u81f3\x20\x32\x30\x31\x32\x20\u5e74\u9593\uff0c\u65e5\u672c\u7406\u5316\u5b78\u7814\u7a76\u6240\x28\x52\x49\x4b\x45\x4e\x29\u7684\u7814\u7a76\u5718\u968a\u5229\u7528\u92c5\x2d\x37\x30\x20\u96e2\u5b50\u8f5f\u64ca\u924d\x2d\x32\x30\x39\x20\u9776\uff0c\u5728\u6b77\u7d93\u4e5d\u5e74\u7684\u8271\u82e6\u5be6\u9a57\u5f8c\u6210\u529f\u5206\u96e2\u3002\u9fed\u662f\u92c1\x28\x41\x6c\x29\u3001\u93b5\x28\x47\x61\x29\u3001\u92a6\x28\x49\x6e\x29\u3001\u9248\x28\x54\x6c\x29\u5bb6\u65cf\u7684\u6700\u65b0\u6210\u54e1\uff0c\u6a19\u8a8c\u8457\u4e9e\u6d32\u5728\u8d85\u91cd\u5143\u7d20\u5408\u6210\u9818\u57df\u9032\u5165\u4e86\u4e16\u754c\u9818\u5148\u68af\u968a\u3002\x0a\x0a\u5728\u5316\u5b78\u7279\u5fb5\u4e0a\uff0c\u9fed\u7684\u96fb\u5b50\u7d44\u614b\u9810\u6e2c\u70ba\x20\x5b\x52\x6e\x5d\x35\x66\u00b9\u2074\x36\x64\u00b9\u2070\x37\x73\u00b2\x37\x70\u00b9\u3002\u53d7\u5f37\u70c8\u7684\u76f8\u5c0d\u8ad6\u6548\u61c9\u8207\u81ea\u65cb\x2d\u8ecc\u9053\u4f5c\u7528\x28\x53\x70\x69\x6e\x2d\x6f\x72\x62\x69\x74\x20\x63\x6f\x75\x70\x6c\x69\x6e\x67\x29\u5f71\u97ff\uff0c\u9fed\u7684\x20\x37\x70\x20\u8ecc\u57df\u767c\u751f\u4e86\u986f\u8457\u7684\u80fd\u968e\u5206\u88c2\uff0c\u9019\u5c0e\u81f4\u5176\u55ae\u4e00\u50f9\u96fb\u5b50\u53d7\u6838\u675f\u7e1b\u529b\u5927\u589e\u3002\u5728\u9ad8\u4e2d\u5316\u5b78\u63a2\u8a0e\u7b2c\x20\x31\x33\x20\u65cf\u300c\u6163\u6027\u96fb\u5b50\u5c0d\u6548\u61c9\u300d\u6642\uff0c\u9248\x28\x54\x6c\x29\u5df2\u8868\u73fe\u51fa\u7a69\u5b9a\u7684\x20\x2b\x31\x20\u6c27\u5316\u614b\uff0c\u800c\u7406\u8ad6\u9810\u6e2c\u9fed\u5c07\u6b64\u8da8\u52e2\u63a8\u5411\u6975\u81f4\uff0c\u5176\x20\x2b\x31\x20\u6c27\u5316\u614b\u5c07\u9060\u6bd4\x20\x2b\x33\x20\u7a69\u5b9a\u3002\u9019\u7a2e\u96fb\u5b50\u7684\u300c\u76f8\u5c0d\u8ad6\u6027\u920d\u5316\u300d\u4f7f\u5176\u5316\u5b78\u53cd\u61c9\u6027\u9810\u8a08\u5c07\u986f\u8457\u4f4e\u65bc\u5176\u4e0a\u65b9\u6210\u54e1\u3002\x0a\x0a\u73fe\u4ee3\u79d1\u5b78\u5c0d\u9fed\u7684\u7814\u7a76\u4e0d\u50c5\u5177\u6709\u4e9e\u6d32\u79d1\u5b78\u6210\u5c31\u7684\u91cc\u7a0b\u7891\u610f\u7fa9\uff0c\u66f4\u662f\u70ba\u4e86\u63a2\u5c0b\u300c\u7a69\u5b9a\u6027\u5cf6\u300d\x28\x49\x73\x6c\x61\x6e\x64\x20\x6f\x66\x20\x53\x74\x61\x62\x69\x6c\x69\x74\x79\x29\u7684\u908a\u7de3\u3002\u7531\u65bc\u9fed\u7684\u6240\u6709\u540c\u4f4d\u7d20\u7686\u5177\u5099\u6975\u77ed\u7684\u534a\u8870\u671f\x28\u6700\u9577\u58fd\u7684\x20\u00b2\u2078\u2076\x4e\x68\x20\u50c5\u7d04\x20\x31\x30\x20\u79d2\x29\uff0c\u76ee\u524d\u5c1a\u7121\u6cd5\u9032\u884c\u5b8f\u89c0\u7684\u5316\u5b78\u6027\u8cea\u9451\u5b9a\u3002\u79d1\u5b78\u5bb6\u4e3b\u8981\u900f\u904e\u89c0\u6e2c\u5176\x20\u03b1\x20\u8870\u8b8a\u5f8c\u7684\u5b50\u6838\u7522\u7269\u4f86\u56de\u63a8\u5176\u7269\u7406\u6027\u8cea\u3002\u5728\u6750\u6599\u79d1\u5b78\u9818\u57df\uff0c\u9fed\u88ab\u8996\u70ba\u7814\u7a76\u6975\u91cd\u539f\u5b50\u6838\u5728\u5f37\u5f37\u5b50\u4ea4\u4e92\u4f5c\u7528\u4e0b\u7a69\u5b9a\u6027\u6f14\u8b8a\u7684\u7406\u60f3\u6a23\u672c\uff0c\u5354\u52a9\u5b8c\u5584\u91cd\u5143\u7d20\u7684\u539f\u5b50\u6838\u6bbc\u5c64\u7406\u8ad6\u3002\x0a\x0a\u95dc\u65bc\u9fed\u7684\u7269\u7406\u7279\u6027\uff0c\u5b83\u5c55\u73fe\u4e86\u7269\u8cea\u5728\u6975\u9650\u539f\u5b50\u5e8f\u4e0b\u7684\u300c\u91cd\u529b\u611f\u300d\u3002\u79d1\u5b78\u5bb6\u9810\u6e2c\u9fed\u91d1\u5c6c\u82e5\u80fd\u4ee5\u584a\u9ad4\u5b58\u5728\uff0c\u5176\u5bc6\u5ea6\u53ef\u80fd\u9ad8\u9054\x20\x31\x36\x20\x67\x2f\x63\x6d\u00b3\u3002\u6709\u8da3\u7684\u662f\uff0c\u9fed\u7684\u767c\u73fe\u6b77\u7a0b\u6975\u5176\u66f2\u6298\uff0c\u66fe\u9762\u81e8\u4fc4\u7f8e\u5718\u968a\u7684\u7af6\u722d\u8207\u6578\u64da\u91cd\u8907\u6027\u7684\u8cea\u7591\uff0c\u6700\u7d42\u6191\u85c9\u65e5\u672c\u5718\u968a\u7cbe\u5bc6\u7684\u9577\u6642\u9593\u89c0\u6e2c\u7372\u5f97\u8a8d\u53ef\u3002\u9019\u7a2e\u5f9e\u300c\u65e5\u672c\u300d\u4e4b\u540d\u7684\u570b\u65cf\u69ae\u8000\u5230\u5b9a\u7fa9\u7b2c\x20\x31\x33\x20\u65cf\u91cd\u6838\u96fb\u5b50\u96f2\u5206\u5e03\u7684\u8f49\u8b8a\uff0c\u7cbe\u78ba\u8a6e\u91cb\u4e86\u9fed\u5728\u9031\u671f\u8868\u4e2d\u4f5c\u70ba\u300c\u4e9e\u6d32\u7b2c\u4e00\u5143\u7d20\u300d\u8207\u7269\u7406\u5be6\u9a57\u6975\u9650\u7684\u96d9\u91cd\u8eab\u5206\u3002",
  "\x46\x6c":
    "\u9207\x28\x46\x6c\x65\x72\x6f\x76\x69\x75\x6d\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x46\x6c\uff0c\u539f\u5b50\u5e8f\x20\x31\x31\x34\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u4e03\u9031\u671f\u3001\u7b2c\x20\x31\x34\x20\u65cf\x28\x70\x20\u5340\u584a\x29\u3002\u5176\u540d\u7a31\u662f\u70ba\u4e86\u7d00\u5ff5\u8607\u806f\u6838\u7269\u7406\u5b78\u5bb6\u3001\u767c\u73fe\u81ea\u767c\u88c2\u8b8a\u7684\u683c\u5967\u723e\u57fa\u00b7\u5f17\u5ed6\u7f85\u592b\x28\x47\x65\x6f\x72\x67\x79\x20\x46\x6c\x65\x72\x6f\x76\x29\u3002\x31\x39\x39\x38\x20\u5e74\u7531\u4fc4\u7f85\u65af\u675c\u5e03\u7d0d\u806f\u5408\u6838\u7814\u7a76\u6240\x28\x4a\x49\x4e\x52\x29\u5229\u7528\u9223\x2d\x34\x38\x20\u96e2\u5b50\u8f5f\u64ca\u923d\x2d\x32\x34\x34\x20\u9776\u9996\u6b21\u88fd\u5f97\u3002\u9fdf\u4f4d\u65bc\u78b3\x28\x43\x29\u3001\u77fd\x28\x53\x69\x29\u3001\u937a\x28\x47\x65\x29\u3001\u932b\x28\x53\x6e\x29\u3001\u925b\x28\x50\x62\x29\u6b63\u4e0b\u65b9\uff0c\u662f\u6838\u7269\u7406\u5b78\u5bb6\u5c0b\u627e\u50b3\u8aaa\u4e2d\u300c\u7a69\u5b9a\u6027\u5cf6\u300d\u7684\u6838\u5fc3\u76ee\u6a19\u5143\u7d20\u3002\x0a\x0a\u9fdf\u7684\u96fb\u5b50\u7d44\u614b\u9810\u6e2c\u70ba\x20\x5b\x52\x6e\x5d\x35\x66\u00b9\u2074\x36\x64\u00b9\u2070\x37\x73\u00b2\x37\x70\u00b2\u3002\u7531\u65bc\u6975\u5f37\u7684\u76f8\u5c0d\u8ad6\u6027\u6548\u61c9\uff0c\u5176\x20\x37\x70\x20\u8ecc\u57df\u5206\u88c2\u51fa\u7684\x20\x37\x70\u2081\x2f\u2082\x20\u5b50\u6bbc\u5c64\u88ab\u5b8c\u5168\u586b\u6eff\u4e14\u80fd\u91cf\u5927\u5e45\u964d\u4f4e\uff0c\u9019\u4f7f\u5176\u96fb\u5b50\u96f2\u5448\u73fe\u51fa\u4e00\u7a2e\u7f55\u898b\u7684\u300c\u6e96\u9589\u6bbc\u5c64\u300d\u7d50\u69cb\u3002\u5728\u9ad8\u4e2d\u5316\u5b78\u63a2\u8a0e\u7b2c\x20\x31\x34\x20\u65cf\u7269\u7406\u898f\u5f8b\u6642\uff0c\u925b\x28\x50\x62\x29\u5df2\u5c55\u73fe\u51fa\u660e\u986f\u7684\u91d1\u5c6c\u6027\uff0c\u4f46\u7406\u8ad6\u9810\u6e2c\u9fdf\u53d7\u76f8\u5c0d\u8ad6\u60f0\u6027\u5f71\u97ff\uff0c\u53ef\u80fd\u5448\u73fe\u51fa\u6975\u4f73\u7684\u5316\u5b78\u60f0\u6027\uff0c\u751a\u81f3\u5728\u6027\u8cea\u4e0a\u66f4\u63a5\u8fd1\u7a00\u6709\u6c23\u9ad4\u800c\u975e\u5178\u578b\u7684\u91d1\u5c6c\u3002\u9019\u7a2e\u7531\u76f8\u5c0d\u8ad6\u6548\u61c9\u5c0e\u81f4\u7684\u300c\u6027\u8cea\u56de\u6b78\u300d\uff0c\u662f\u8d85\u91cd\u5143\u7d20\u7814\u7a76\u4e2d\u6700\u5177\u5f35\u529b\u7684\u8ab2\u984c\u4e4b\u4e00\u3002\x0a\x0a\u5728\u73fe\u4ee3\u61c9\u7528\u4e2d\uff0c\u9fdf\u662f\u300c\u7a69\u5b9a\u6027\u5cf6\u300d\u7406\u8ad6\u7684\u6700\u4f73\u5be6\u9a57\u5834\u3002\u6838\u7269\u7406\u5b78\u5bb6\u9810\u6e2c\uff0c\u5728\u9fdf\u7684\u539f\u5b50\u5e8f\u9644\u8fd1\u53ef\u80fd\u5b58\u5728\u5177\u5099\u6975\u9577\u534a\u8870\u671f\u7684\u540c\u4f4d\u7d20\uff0c\u9019\u5c0d\u65bc\u7406\u89e3\u539f\u5b50\u6838\u7684\u5f37\u4ea4\u4e92\u4f5c\u7528\u529b\u5177\u6709\u6c7a\u5b9a\u6027\u610f\u7fa9\u3002\u76ee\u524d\u7684\u5be6\u9a57\u89c0\u6e2c\u986f\u793a\uff0c\u9fdf\u5728\u91d1\u8868\u9762\u5c55\u73fe\u51fa\u5fae\u5f31\u7684\u4ea4\u4e92\u4f5c\u7528\uff0c\u5176\u63ee\u767c\u6027\u9060\u9ad8\u65bc\u925b\uff0c\u9019\u8207\u7406\u8ad6\u9810\u6e2c\u7684\u300c\u985e\u6c23\u9ad4\u6027\u8cea\u300d\u90e8\u5206\u543b\u5408\u3002\u7531\u65bc\u6700\u9577\u58fd\u540c\u4f4d\u7d20\x20\u00b2\u2078\u2079\x46\x6c\x20\u7684\u534a\u8870\u671f\u50c5\u7d04\x20\x32\x2e\x36\x20\u79d2\uff0c\u76ee\u524d\u6240\u6709\u7684\u7814\u7a76\u5747\u5728\u539f\u5b50\u8a08\u6578\u7684\u6975\u5fae\u89c0\u5c3a\u5ea6\u4e0b\u5b8c\u6210\u3002\x0a\x0a\u95dc\u65bc\u9fdf\u7684\u73fe\u8c61\uff0c\u5b83\u5c55\u73fe\u4e86\u91cd\u6838\u7269\u8cea\u5728\u300c\u7a69\u5b9a\u8207\u6d88\u4ea1\u300d\u9593\u7684\u6fc0\u70c8\u62c9\u92f8\u3002\u5118\u7ba1\u539f\u5b50\u6838\u6975\u5176\u4e0d\u7a69\u5b9a\uff0c\u4f46\u5176\u5c01\u9589\u7684\u96fb\u5b50\u6bbc\u5c64\u537b\u53ef\u80fd\u8b93\u5b83\u5177\u5099\u6975\u9ad8\u7684\u6297\u5316\u5b78\u4fb5\u8755\u529b\u3002\u6709\u8da3\u7684\u662f\uff0c\u96d6\u7136\u9fdf\u88ab\u9810\u6e2c\u70ba\u60f0\u6027\uff0c\u4f46\u5728\u67d0\u4e9b\u9ad8\u58d3\u7269\u7406\u6a21\u578b\u4e2d\uff0c\u5b83\u4ecd\u53ef\u80fd\u5c55\u73fe\u51fa\u5fae\u5f31\u7684\u91d1\u5c6c\u9375\u7d50\u80fd\u529b\u3002\u9019\u7a2e\u5f9e\u8607\u806f\u6838\u7269\u7406\u5b97\u5e2b\u7684\u6b77\u53f2\u547d\u540d\u5230\u5b9a\u7fa9\u8d85\u91cd\u5143\u7d20\u7a69\u5b9a\u908a\u754c\u7684\u63a2\u8a0e\uff0c\u7cbe\u78ba\u8a6e\u91cb\u4e86\u9fdf\u5728\u9031\u671f\u8868\u4e2d\u4f5c\u70ba\u300c\u539f\u5b50\u6838\u7269\u7406\u6700\u7d42\u524d\u54e8\u300d\u7684\u95dc\u9375\u50f9\u503c\u3002",
  "\x4d\x63":
    "\u93cc\x28\x4d\x6f\x73\x63\x6f\x76\x69\x75\x6d\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x4d\x63\uff0c\u539f\u5b50\u5e8f\x20\x31\x31\x35\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u4e03\u9031\u671f\u3001\u7b2c\x20\x31\x35\x20\u65cf\x28\u6c2e\u65cf\u5143\u7d20\uff0c\x70\x20\u5340\u584a\x29\u3002\u5176\u540d\u7a31\u6e90\u65bc\u4fc4\u7f85\u65af\u7684\u83ab\u65af\u79d1\u5dde\x28\x4d\x6f\x73\x63\x6f\x77\x20\x4f\x62\x6c\x61\x73\x74\x29\uff0c\u4ee5\u81f4\u656c\u767c\u73fe\u5730\u675c\u5e03\u7d0d\u806f\u5408\u6838\u7814\u7a76\u6240\x28\x4a\x49\x4e\x52\x29\u3002\x32\x30\x30\x33\x20\u5e74\u7531\u4fc4\u7f85\u65af\u675c\u5e03\u7d0d\u8207\u7f8e\u570b\u52de\u502b\u65af\u5229\u4f5b\u6469\u570b\u5bb6\u5be6\u9a57\u5ba4\x28\x4c\x4c\x4e\x4c\x29\u5718\u968a\u5171\u540c\u5408\u6210\u3002\u93cc\u662f\u6c2e\x28\x4e\x29\u3001\u78f7\x28\x50\x29\u3001\u7837\x28\x41\x73\x29\u3001\u92bb\x28\x53\x62\x29\u3001\u924d\x28\x42\x69\x29\u5bb6\u65cf\u4e2d\u6700\u91cd\u7684\u6210\u54e1\uff0c\u4ee3\u8868\u4e86\u4eba\u985e\u5c0d\u8d85\u91cd\u6838\u5143\u7d20\u7a69\u5b9a\u898f\u5f8b\u63a2\u7d22\u7684\u53c8\u4e00\u91cd\u8981\u91cc\u7a0b\u7891\u3002\x0a\x0a\u93cc\u7684\u96fb\u5b50\u7d44\u614b\u9810\u6e2c\u70ba\x20\x5b\x52\x6e\x5d\x35\x66\u00b9\u2074\x36\x64\u00b9\u2070\x37\x73\u00b2\x37\x70\u00b3\u3002\u53d7\u5f37\u70c8\u7684\u76f8\u5c0d\u8ad6\u6548\u61c9\u5f71\u97ff\uff0c\u93cc\u7684\x20\x37\x70\x20\u8ecc\u57df\u767c\u751f\u80fd\u7d1a\u5206\u88c2\uff0c\u9019\u4f7f\u5176\u5316\u5b78\u884c\u70ba\u53ef\u80fd\u986f\u8457\u504f\u96e2\u540c\u65cf\u7684\u924d\u3002\u5728\u9ad8\u4e2d\u5316\u5b78\u63a2\u8a0e\u65cf\u7fa4\u8da8\u52e2\u6642\uff0c\u924d\u5df2\u5c55\u73fe\u51fa\u7a69\u5b9a\u7684\x20\x2b\x33\x20\u6c27\u5316\u614b\uff0c\u800c\u7406\u8ad6\u9810\u6e2c\u93cc\u7684\x20\x2b\x31\x20\u6c27\u5316\u614b\u5c07\u5177\u5099\u610f\u60f3\u4e0d\u5230\u7684\u7a69\u5b9a\u6027\uff0c\u751a\u81f3\u53ef\u80fd\u6210\u70ba\u5176\u5728\u6eb6\u6db2\u4e2d\u6700\u4e3b\u8981\u7684\u50f9\u614b\u3002\u9019\u7a2e\u7531\u76f8\u5c0d\u8ad6\u6027\x20\x37\x73\x20\u8ecc\u57df\u6536\u7e2e\u8207\x20\x37\x70\u2081\x2f\u2082\x20\u5b50\u6bbc\u5c64\u7a69\u5b9a\u5316\u5c0e\u81f4\u7684\u6027\u8cea\u504f\u79fb\uff0c\u662f\u7576\u4ee3\u91cd\u5143\u7d20\u5316\u5b78\u7814\u7a76\u7684\u6838\u5fc3\u8ab2\u984c\u3002\x0a\x0a\u5728\u73fe\u4ee3\u61c9\u7528\u4e2d\uff0c\u93cc\u4e3b\u8981\u7528\u65bc\u57fa\u790e\u6838\u7269\u7406\u7814\u7a76\uff0c\u7279\u5225\u662f\u4f5c\u70ba\u5408\u6210\x20\x31\x31\x37\x20\u865f\u8207\x20\x31\x31\x38\x20\u865f\u5143\u7d20\u7684\u8870\u8b8a\u93c8\u89c0\u6e2c\u6307\u6a19\u3002\u76ee\u524d\u6700\u9577\u58fd\u7684\u540c\u4f4d\u7d20\x20\u00b2\u2079\u2070\x4d\x63\x20\u534a\u8870\u671f\u50c5\u7d04\x20\x30\x2e\x36\x35\x20\u79d2\uff0c\u9019\u4f7f\u5f97\u9032\u884c\u50b3\u7d71\u5b8f\u89c0\u5316\u5b78\u5be6\u9a57\u6975\u5177\u6311\u6230\u3002\u79d1\u5b78\u5bb6\u4e3b\u8981\u900f\u904e\u300c\u55ae\u539f\u5b50\u5316\u5b78\u300d\u6280\u8853\uff0c\u5728\u6975\u77ed\u7684\u6642\u9593\u5167\u6355\u6349\u5176\u8870\u8b8a\u8a0a\u865f\uff0c\u85c9\u6b64\u63a8\u8ad6\u5176\u7269\u7406\u6027\u8cea\u3002\u93cc\u7684\u7814\u7a76\u6709\u52a9\u65bc\u79d1\u5b78\u5bb6\u4fee\u6b63\u539f\u5b50\u6838\u6bbc\u5c64\u6a21\u578b\uff0c\u4e26\u9032\u4e00\u6b65\u5411\u50b3\u8aaa\u4e2d\u7684\u300c\u7a69\u5b9a\u6027\u5cf6\u300d\x28\x49\x73\x6c\x61\x6e\x64\x20\x6f\x66\x20\x53\x74\x61\x62\x69\x6c\x69\x74\x79\x29\u9760\u8fd1\u3002\x0a\x0a\u95dc\u65bc\u93cc\u7684\u73fe\u8c61\uff0c\u5b83\u5c55\u73fe\u4e86\u7269\u8cea\u5728\u6975\u9ad8\u539f\u5b50\u5e8f\u4e0b\u7684\u300c\u77ac\u9593\u6f14\u8b8a\u300d\u3002\u5118\u7ba1\u539f\u5b50\u6838\u5b58\u5728\u6642\u9593\u4e0d\u5230\u4e00\u79d2\uff0c\u4f46\u93cc\u5728\u8870\u8b8a\u904e\u7a0b\u4e2d\u91cb\u653e\u51fa\u7684\u80fd\u91cf\u8207\u8def\u5f91\uff0c\u70ba\u7814\u7a76\u8d85\u91cd\u539f\u5b50\u6838\u7684\u81ea\u767c\u88c2\u8b8a\u63d0\u4f9b\u4e86\u73cd\u8cb4\u6578\u64da\u3002\u6709\u8da3\u7684\u662f\uff0c\u96d6\u7136\u93cc\u662f\u4eba\u9020\u5143\u7d20\uff0c\u4f46\u5176\u6027\u8cea\u7684\u9810\u6e2c\u5c55\u73fe\u4e86\u91cf\u5b50\u529b\u5b78\u5c0d\u6975\u7aef\u7269\u8cea\u5f62\u614b\u7684\u5f37\u5927\u89e3\u91cb\u529b\u3002\u9019\u7a2e\u5f9e\u83ab\u65af\u79d1\u5be6\u9a57\u5ba4\u7684\u52a0\u901f\u5668\u8f5f\u64ca\u5230\u5b9a\u7fa9\u7b2c\x20\x31\x35\x20\u65cf\u7269\u7406\u6975\u9650\u7684\u904e\u7a0b\uff0c\u7cbe\u78ba\u8a6e\u91cb\u4e86\u93cc\u5728\u9031\u671f\u8868\u4e2d\u4f5c\u70ba\u300c\u91cd\u6838\u63a2\u7d22\u524d\u54e8\u300d\u7684\u89d2\u8272\u3002",
  "\x4c\x76":
    "\u925d\x28\x4c\x69\x76\x65\x72\x6d\x6f\x72\x69\x75\x6d\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x4c\x76\uff0c\u539f\u5b50\u5e8f\x20\x31\x31\x36\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u4e03\u9031\u671f\u3001\u7b2c\x20\x31\x36\x20\u65cf\x28\u6c27\u65cf\u5143\u7d20\uff0c\x70\x20\u5340\u584a\x29\u3002\u5176\u540d\u7a31\u6e90\u65bc\u7f8e\u570b\u52a0\u5dde\u7684\u52de\u502b\u65af\u5229\u4f5b\u6469\u570b\u5bb6\u5be6\u9a57\u5ba4\x28\x4c\x61\x77\x72\x65\x6e\x63\x65\x20\x4c\x69\x76\x65\x72\x6d\x6f\x72\x65\x20\x4e\x61\x74\x69\x6f\x6e\x61\x6c\x20\x4c\x61\x62\x6f\x72\x61\x74\x6f\x72\x79\x29\uff0c\u8a72\u6a5f\u69cb\u5728\u8d85\u91cd\u5143\u7d20\u5408\u6210\u9818\u57df\u8ca2\u737b\u5353\u8457\u3002\x32\x30\x30\x30\x20\u5e74\u7531\u4fc4\u7f85\u65af\u675c\u5e03\u7d0d\u8207\u7f8e\u570b\x20\x4c\x4c\x4e\x4c\x20\u5718\u968a\u5229\u7528\u9223\x2d\x34\x38\x20\u96e2\u5b50\u8f5f\u64ca\u92e6\x2d\x32\x34\x38\x20\u9776\u9996\u6b21\u6210\u529f\u5408\u6210\u3002\u9feb\u6392\u5728\u6c27\x28\x4f\x29\u3001\u786b\x28\x53\x29\u3001\u7852\x28\x53\x65\x29\u3001\u78b2\x28\x54\x65\x29\u3001\u91d9\x28\x50\x6f\x29\u4e4b\u4e0b\uff0c\u662f\u76ee\u524d\u5df2\u77e5\u6700\u91cd\u7684\u6c27\u65cf\u6210\u54e1\uff0c\u5177\u5099\u5f37\u653e\u5c04\u6027\u4e14\u58fd\u547d\u6975\u77ed\u3002\x0a\x0a\u9feb\u7684\u96fb\u5b50\u7d44\u614b\u9810\u6e2c\u70ba\x20\x5b\x52\x6e\x5d\x35\x66\u00b9\u2074\x36\x64\u00b9\u2070\x37\x73\u00b2\x37\x70\u2074\u3002\u53d7\u6975\u5f37\u7684\u76f8\u5c0d\u8ad6\u6548\u61c9\u8207\u81ea\u65cb\x2d\u8ecc\u9053\u4f5c\u7528\u5f71\u97ff\uff0c\u9feb\u7684\x20\x37\x70\x20\u5b50\u6bbc\u5c64\u80fd\u7d1a\u5206\u5e03\u767c\u751f\u5287\u8b8a\uff0c\u9019\u4f7f\u5f97\u5176\u50f9\u96fb\u5b50\u7684\u5316\u5b78\u884c\u70ba\u5448\u73fe\u51fa\u9ad8\u5ea6\u7684\u60f0\u6027\u3002\u5728\u9ad8\u4e2d\u5316\u5b78\u63a2\u8a0e\u7b2c\x20\x31\x36\x20\u65cf\u5143\u7d20\u8da8\u52e2\u6642\uff0c\u7531\u975e\u91d1\u5c6c\u8f49\u8b8a\u70ba\u91d1\u5c6c\u7684\u50be\u5411\u5728\u9feb\u8eab\u4e0a\u9054\u5230\u4e86\u9802\u5cf0\u3002\u7406\u8ad6\u9810\u6e2c\u9feb\u7684\u6027\u8cea\u5c07\u66f4\u63a5\u8fd1\u65bc\u91d1\u5c6c\uff0c\u4e14\u5176\x20\x2b\x32\x20\u6c27\u5316\u614b\u53d7\u300c\u6163\u6027\u96fb\u5b50\u5c0d\u6548\u61c9\u300d\u5f71\u97ff\u800c\u6bd4\x20\x2b\x34\x20\u6216\x20\x2b\x36\x20\u50f9\u614b\u7a69\u5b9a\u5f97\u591a\uff0c\u9019\u5c55\u73fe\u4e86\u8d85\u91cd\u5143\u7d20\u9031\u671f\u5f8b\u7684\u7368\u7279\u8b8a\u594f\u3002\x0a\x0a\u73fe\u4ee3\u79d1\u5b78\u5c0d\u9feb\u7684\u7814\u7a76\u5b8c\u5168\u5c40\u9650\u65bc\u539f\u5b50\u6838\u7269\u7406\u7684\u6700\u524d\u6cbf\u3002\u6700\u9577\u58fd\u7684\u540c\u4f4d\u7d20\x20\u00b2\u2079\u00b3\x4c\x76\x20\u534a\u8870\u671f\u50c5\u7d04\x20\x35\x33\x20\u6beb\u79d2\uff0c\u9019\u610f\u5473\u8457\u9feb\u539f\u5b50\u5728\u7522\u751f\u5f8c\u5e7e\u4e4e\u8f49\u77ac\u5373\u901d\uff0c\u76ee\u524d\u5c1a\u7121\u6cd5\u9032\u884c\u50b3\u7d71\u7684\u5316\u5b78\u9375\u7d50\u5be6\u9a57\u3002\u79d1\u5b78\u5bb6\u900f\u904e\u7cbe\u5bc6\u7684\u8870\u8b8a\u80fd\u8b5c\u5206\u6790\uff0c\u7814\u7a76\u9feb\u539f\u5b50\u6838\u5728\u5f37\u5927\u5eab\u502b\u65a5\u529b\u4e0b\u7684\u7a69\u5b9a\u6027\u6a5f\u5236\u3002\u5728\u6750\u6599\u79d1\u5b78\u8996\u91ce\u4e2d\uff0c\u9feb\u88ab\u8996\u70ba\u9a57\u8b49\u8d85\u91cd\u5143\u7d20\u300c\u6bbc\u5c64\u4fee\u6b63\u80fd\u300d\u7684\u91cd\u8981\u6a23\u672c\uff0c\u5354\u52a9\u5efa\u7acb\u66f4\u7cbe\u78ba\u7684\u91cd\u5143\u7d20\u7269\u7406\u6a21\u578b\u3002\x0a\x0a\u95dc\u65bc\u9feb\u7684\u73fe\u8c61\uff0c\u5b83\u5c55\u73fe\u4e86\u91cd\u6838\u7269\u8cea\u5728\u300c\u6642\u7a7a\u5c3a\u5ea6\u300d\u4e0a\u7684\u6975\u9650\u6027\u3002\u5118\u7ba1\u9feb\u7684\u751f\u547d\u9031\u671f\u4ee5\u6beb\u79d2\u8a08\uff0c\u4f46\u5b83\u4ecd\u80fd\u5b8c\u6210\u96fb\u5b50\u7684\u6bbc\u5c64\u6392\u5217\u4e26\u5c55\u73fe\u5176\u7279\u5fb5\u5149\u8b5c\u3002\u6709\u8da3\u7684\u662f\uff0c\u9feb\u7684\u5408\u6210\u9700\u8981\u6975\u5176\u7cbe\u78ba\u7684\u649e\u64ca\u80fd\u91cf\uff0c\u82e5\u80fd\u91cf\u7a0d\u6709\u504f\u5dee\u5247\u7121\u6cd5\u5f62\u6210\u7a69\u5b9a\u7684\u8907\u5408\u6838\u3002\u9019\u7a2e\u5f9e\u5229\u4f5b\u6469\u5be6\u9a57\u5ba4\u7684\u8de8\u570b\u5408\u4f5c\u5230\u5b9a\u7fa9\u7b2c\x20\x31\x36\x20\u65cf\u91cd\u91d1\u5c6c\u7269\u7406\u908a\u754c\u7684\u8f49\u8b8a\uff0c\u7cbe\u78ba\u8a6e\u91cb\u4e86\u9feb\u5728\u9031\u671f\u8868\u4e2d\u4f5c\u70ba\u300c\u6838\u7269\u7406\u6975\u9650\u8b49\u660e\u8005\u300d\u7684\u5730\u4f4d\u3002",
  "\x54\x73":
    "\u9fec\x28\x54\x65\x6e\x6e\x65\x73\x73\x69\x6e\x65\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x54\x73\uff0c\u539f\u5b50\u5e8f\x20\x31\x31\x37\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u4e03\u9031\u671f\u3001\u7b2c\x20\x31\x37\x20\u65cf\x28\u9e75\u7d20\uff0c\x70\x20\u5340\u584a\x29\u3002\u5176\u540d\u7a31\u6e90\u65bc\u7f8e\u570b\u7530\u7d0d\u897f\u5dde\x28\x54\x65\x6e\x6e\x65\x73\x73\x65\x65\x29\uff0c\u4ee5\u7d00\u5ff5\u8a72\u5730\u5340\u591a\u500b\u7814\u7a76\u6a5f\u69cb\u5728\u8d85\u91cd\u5143\u7d20\u7814\u7a76\u8207\u9776\u6750\u88fd\u5099\u4e0a\u7684\u6838\u5fc3\u8ca2\u737b\u3002\x32\x30\x31\x30\x20\u5e74\u7531\u4fc4\u7f8e\u806f\u5408\u5718\u968a\u5229\u7528\u9223\x2d\x34\x38\x20\u96e2\u5b50\u8f5f\u64ca\u6975\u5176\u7a00\u6709\u7684\u9273\x2d\x32\x34\x39\x20\u9776\u9996\u6b21\u88fd\u5f97\u3002\u9fec\u662f\u76ee\u524d\u5df2\u77e5\u6700\u91cd\u7684\u9e75\u7d20\u6210\u54e1\uff0c\u5176\u5408\u6210\u4e0d\u50c5\u586b\u88dc\u4e86\u9031\u671f\u8868\u5012\u6578\u7b2c\u4e8c\u500b\u4f4d\u7f6e\uff0c\u4e5f\u70ba\u63a2\u8a0e\u9e75\u7d20\u65cf\u7fa4\u6027\u8cea\u5728\u6975\u9650\u539f\u5b50\u5e8f\u4e0b\u7684\u6f02\u79fb\u63d0\u4f9b\u4e86\u95dc\u9375\u6578\u64da\u3002\x0a\x0a\u9fec\u7684\u96fb\u5b50\u7d44\u614b\u9810\u6e2c\u70ba\x20\x5b\x52\x6e\x5d\x35\x66\u00b9\u2074\x36\x64\u00b9\u2070\x37\x73\u00b2\x37\x70\u2075\u3002\u53d7\u5f37\u70c8\u7684\u76f8\u5c0d\u8ad6\u6548\u61c9\u5f71\u97ff\uff0c\u9fec\u7684\u6027\u8cea\u8207\u8f15\u8cea\u9e75\u7d20\x28\u5982\u6c1f\u3001\u6c2f\u3001\u6eb4\x29\u5b8c\u5168\u4e0d\u540c\u3002\u5728\u9ad8\u4e2d\u5316\u5b78\u63a2\u8a0e\u9e75\u7d20\u975e\u91d1\u5c6c\u6027\u6642\uff0c\u6c1f\u662f\u96fb\u8ca0\u5ea6\u6700\u5f37\u7684\u5143\u7d20\uff0c\u4f46\u7406\u8ad6\u9810\u6e2c\u9fec\u53ef\u80fd\u5c55\u73fe\u51fa\u660e\u986f\u7684\u985e\u91d1\u5c6c\u6216\u91d1\u5c6c\u7279\u5fb5\uff0c\u5176\u96fb\u8ca0\u5ea6\u5927\u5e45\u4e0b\u964d\uff0c\u4e14\u53ef\u80fd\u5177\u5099\u7a69\u5b9a\u7684\x20\x2b\x31\x20\u8207\x20\x2b\x33\x20\u6c27\u5316\u614b\u3002\u7531\u65bc\x20\x37\x70\u2081\x2f\u2082\x20\u5b50\u6bbc\u5c64\u7684\u6975\u5ea6\u7a69\u5b9a\u5316\uff0c\u9fec\u53ef\u80fd\u4e0d\u50be\u5411\u5f62\u6210\u5e38\u898b\u7684\x20\x2d\x31\x20\u50f9\u9670\u96e2\u5b50\uff0c\u9019\u5fb9\u5e95\u985b\u8986\u4e86\u50b3\u7d71\u9e75\u7d20\u7684\u5316\u5b78\u5b9a\u7fa9\u3002\x0a\x0a\u76ee\u524d\u5c0d\u9fec\u7684\u7814\u7a76\u5b8c\u5168\u4f9d\u8cf4\u65bc\u5927\u80fd\u91cf\u52a0\u901f\u5668\u7684\u55ae\u539f\u5b50\u53cd\u61c9\u3002\u7531\u65bc\u6700\u9577\u58fd\u540c\u4f4d\u7d20\x20\u00b2\u2079\u2074\x54\x73\x20\u7684\u534a\u8870\u671f\u50c5\u7d04\x20\x35\x31\x20\u6beb\u79d2\uff0c\u4e14\u5408\u6210\u6240\u9700\u7684\u9273\u9776\u6750\u7522\u91cf\u6975\u4f4e\uff0c\u9fec\u7684\u6bcf\u4e00\u6b21\u6210\u529f\u5408\u6210\u90fd\u662f\u5168\u7403\u79d1\u5b78\u8cc7\u6e90\u6574\u5408\u7684\u7d50\u679c\u3002\u5728\u7269\u7406\u7814\u7a76\u4e2d\uff0c\u9fec\u88ab\u8996\u70ba\u901a\u5f80\u300c\u7a69\u5b9a\u6027\u5cf6\u300d\u4e2d\u5fc3\u7684\u91cd\u8981\u968e\u68af\uff0c\u900f\u904e\u5176\u8870\u8b8a\u93c8\uff0c\u79d1\u5b78\u5bb6\u80fd\u89c0\u5bdf\u5230\u4e2d\u5b50\u6578\u589e\u52a0\u5c0d\u91cd\u6838\u58fd\u547d\u7684\u986f\u8457\u63d0\u5347\u3002\u9fec\u76ee\u524d\u50c5\u7528\u65bc\u63a2\u7a76\u91cf\u5b50\u5316\u5b78\u8207\u6838\u7269\u7406\u7684\u908a\u754c\u7406\u8ad6\u3002\x0a\x0a\u95dc\u65bc\u9fec\u7684\u73fe\u8c61\uff0c\u5b83\u5c55\u73fe\u4e86\u91cd\u5143\u7d20\u5728\u5316\u5b78\u9375\u7d50\u4e0a\u7684\u300c\u5e7e\u4f55\u8b8a\u7570\u300d\u3002\u7406\u8ad6\u9810\u6e2c\uff0c\u53d7\u76f8\u5c0d\u8ad6\u6548\u61c9\u5f71\u97ff\uff0c\u9fec\u5f62\u6210\u7684\u5171\u50f9\u5206\u5b50\x28\u5982\x20\x54\x73\x46\x29\u53ef\u80fd\u5177\u5099\u8207\u8f15\u8cea\u9e75\u7d20\u5b8c\u5168\u4e0d\u540c\u7684\u9375\u9577\u8207\u6975\u6027\u3002\u6709\u8da3\u7684\u662f\uff0c\u96d6\u7136\u4ee5\u7530\u7d0d\u897f\u5dde\u547d\u540d\uff0c\u4f46\u9fec\u5728\u81ea\u7136\u754c\u4e2d\u96a8\u751f\u96a8\u6ec5\uff0c\u50c5\u5b58\u5728\u65bc\u79d1\u5b78\u5bb6\u7cbe\u5fc3\u8a2d\u8a08\u7684\u78b0\u649e\u77ac\u9593\u3002\u9019\u7a2e\u5f9e\u7a00\u6709\u9776\u6750\u7684\u8271\u8f9b\u88fd\u5099\u5230\u6311\u6230\u9e75\u7d20\u65cf\u7fa4\u5b9a\u7fa9\u7684\u7a81\u7834\uff0c\u7cbe\u78ba\u8a6e\u91cb\u4e86\u9fec\u5728\u9031\u671f\u8868\u4e2d\u4f5c\u70ba\u300c\u91cd\u6838\u6027\u8cea\u8f49\u578b\u8005\u300d\u7684\u7368\u7279\u8eab\u5206\u3002",
  "\x4f\x67":
    "\u9feb\x28\x4f\x67\x61\x6e\x65\x73\x73\x6f\x6e\x29\uff0c\u5143\u7d20\u7b26\u865f\x20\x4f\x67\uff0c\u539f\u5b50\u5e8f\x20\x31\x31\x38\uff0c\u4f4d\u65bc\u9031\u671f\u8868\u7b2c\u4e03\u9031\u671f\u3001\u7b2c\x20\x31\x38\x20\u65cf\x28\u7a00\u6709\u6c23\u9ad4\uff0c\x70\x20\u5340\u584a\x29\u3002\u5176\u540d\u7a31\u662f\u70ba\u4e86\u81f4\u656c\u8d85\u91cd\u5143\u7d20\u5408\u6210\u5148\u9a45\u3001\u4fc4\u7f85\u65af\u7269\u7406\u5b78\u5bb6\u5c24\u91cc\u00b7\u5967\u52a0\u6d85\u76f8\x28\x59\x75\x72\x69\x20\x4f\x67\x61\x6e\x65\x73\x73\x69\x61\x6e\x29\uff0c\u4ed6\u662f\u53f2\u4e0a\u7b2c\u4e8c\u4f4d\u5728\u4e16\u6642\u7372\u5f97\u5143\u7d20\u547d\u540d\u69ae\u8b7d\u7684\u79d1\u5b78\u5bb6\u3002\x32\x30\x30\x32\x20\u5e74\u9996\u6b21\u88ab\u89c0\u6e2c\u5230\uff0c\u4e26\u65bc\x20\x32\x30\x30\x36\x20\u5e74\u6b63\u5f0f\u78ba\u8a8d\u3002\u9feb\u662f\u76ee\u524d\u9031\u671f\u8868\u4e0a\u539f\u5b50\u5e8f\u6700\u5927\u7684\u5143\u7d20\uff0c\u5b83\u7684\u767c\u73fe\u6a19\u8a8c\u8457\u7b2c\u4e03\u9031\u671f\u7684\u6b63\u5f0f\u5b8c\u7d50\uff0c\u4ea6\u662f\u4eba\u985e\u76ee\u524d\u5c0d\u7269\u8cea\u4e16\u754c\u63a2\u7d22\u7684\u6700\u9060\u908a\u754c\u3002\x0a\x0a\u5728\u5fae\u89c0\u7d50\u69cb\u4e0a\uff0c\u9feb\u5c55\u73fe\u4e86\u6975\u81f4\u7684\u76f8\u5c0d\u8ad6\u6548\u61c9\u3002\u5176\u96fb\u5b50\u7d44\u614b\u9810\u6e2c\u70ba\x20\x5b\x52\x6e\x5d\x35\x66\u00b9\u2074\x36\x64\u00b9\u2070\x37\x73\u00b2\x37\x70\u2076\u3002\u96d6\u7136\u4f4d\u65bc\u7a00\u6709\u6c23\u9ad4\u65cf\uff0c\u4f46\u7406\u8ad6\u9810\u6e2c\u9feb\u7684\u6027\u8cea\u5c07\u5b8c\u5168\u80cc\u96e2\u300c\u60f0\u6027\u6c23\u9ad4\u300d\u7684\u7bc4\u7587\u3002\u7531\u65bc\u5176\u96fb\u5b50\u96f2\u6975\u6613\u6975\u5316\x28\x50\x6f\x6c\x61\x72\x69\x7a\x61\x62\x69\x6c\x69\x74\x79\x29\uff0c\u9feb\u539f\u5b50\u9593\u7684\u51e1\u5f97\u74e6\u529b\u5f37\u5927\u5230\u8db3\u4ee5\u4f7f\u5176\u5728\u5e38\u6eab\u4e0b\u5448\u73fe\u300c\u56fa\u614b\u300d\u3002\u5728\u9ad8\u4e2d\u5316\u5b78\u63a2\u8a0e\u7a00\u6709\u6c23\u9ad4\u7a69\u5b9a\u6027\u6642\uff0c\u9feb\u662f\u4e00\u500b\u53cd\u76f4\u89ba\u7684\u6848\u4f8b\uff1a\u53d7\u76f8\u5c0d\u8ad6\u6548\u61c9\u5f71\u97ff\uff0c\u9feb\u53ef\u80fd\u5177\u5099\u986f\u8457\u7684\u5316\u5b78\u6d3b\u6027\uff0c\u751a\u81f3\u80fd\u5f62\u6210\u7a69\u5b9a\u7684\u6c27\u5316\u7269\x28\u5982\x20\x4f\x67\x4f\u2083\x29\u6216\u6c1f\u5316\u7269\uff0c\u5c55\u73fe\u51fa\u4e0d\u540c\u65bc\u6c26\u3001\u6c16\u7684\u5316\u5b78\u4e3b\u52d5\u6027\u3002\x0a\x0a\u73fe\u4ee3\u79d1\u5b78\u5c0d\u9feb\u7684\u7814\u7a76\u4e3b\u8981\u96c6\u4e2d\u65bc\u539f\u5b50\u6838\u7269\u7406\u7684\u6975\u9650\u6311\u6230\u3002\u9feb\u7684\u6240\u6709\u540c\u4f4d\u7d20\u7686\u6975\u4e0d\u7a69\u5b9a\uff0c\u6700\u9577\u58fd\u7684\x20\u00b2\u2079\u2074\x4f\x67\x20\u534a\u8870\u671f\u50c5\u7d04\x20\x30\x2e\x37\x20\u6beb\u79d2\u3002\u5118\u7ba1\u5982\u6b64\uff0c\u9feb\u7684\u5408\u6210\u6210\u529f\u9a57\u8b49\u4e86\u300c\u7a69\u5b9a\u6027\u5cf6\u300d\u7406\u8ad6\u7684\u9810\u6e2c\u8da8\u52e2\uff0c\u5373\u4e2d\u5b50\u6578\u63a5\u8fd1\x20\x31\x38\x34\x20\u7684\u91cd\u6838\u5177\u5099\u66f4\u9577\u7684\u751f\u5b58\u58fd\u547d\u6f5b\u529b\u3002\u76ee\u524d\u9feb\u7684\u751f\u7522\u6975\u5176\u56f0\u96e3\uff0c\u5168\u7403\u50c5\u7522\u51fa\u904e\u6975\u5c11\u6578\u539f\u5b50\u3002\u5b83\u88ab\u7528\u65bc\u7814\u7a76\u539f\u5b50\u5167\u90e8\u5f37\u78c1\u5834\u8207\u5f37\u96fb\u529b\u5834\u4e0b\u7684\u91cf\u5b50\u96fb\u52d5\u529b\u5b78\x28\x51\x45\x44\x29\u73fe\u8c61\uff0c\u662f\u4eba\u985e\u7406\u89e3\u7269\u8cea\u69cb\u6210\u7684\u6700\u5c16\u7aef\u5be6\u9a57\u5ba4\u3002\x0a\x0a\u95dc\u65bc\u9feb\u7684\u7269\u7406\u7279\u6027\uff0c\u5b83\u5c55\u73fe\u4e86\u9031\u671f\u8868\u7684\u300c\u9031\u671f\u6027\u7d42\u7d50\u8207\u91cd\u751f\u300d\u3002\u96d6\u7136\u5b83\u662f\u540d\u7fa9\u4e0a\u7684\u7a00\u6709\u6c23\u9ad4\uff0c\u4f46\u5176\u6975\u9ad8\u7684\u6975\u5316\u7387\u4f7f\u5176\u5728\u5316\u5b78\u9375\u4e2d\u8868\u73fe\u5f97\u66f4\u50cf\u662f\u4e00\u500b\u5177\u5099\u534a\u5c0e\u9ad4\u7279\u6027\u7684\u534a\u91d1\u5c6c\u3002\u6709\u8da3\u7684\u662f\uff0c\u9feb\u7684\u767c\u73fe\u8b93\u4eba\u985e\u5b8c\u6210\u4e86\u9031\u671f\u8868\u524d\u4e03\u9031\u671f\u7684\u62fc\u5716\uff0c\u958b\u555f\u4e86\u672a\u4f86\u7b2c\u516b\u9031\u671f\u63a2\u7d22\u7684\u53ef\u80fd\u6027\u3002\u9019\u7a2e\u5f9e\u81f4\u656c\u7576\u4ee3\u79d1\u5b78\u5b97\u5e2b\u5230\u5b9a\u7fa9\u5b87\u5b99\u4e2d\u5df2\u77e5\u7269\u8cea\u539f\u5b50\u5e8f\u9802\u9ede\u7684\u8de8\u5ea6\uff0c\u7cbe\u78ba\u8a6e\u91cb\u4e86\u9feb\u5728\u9031\u671f\u8868\u4e2d\u4f5c\u70ba\u300c\u5df2\u77e5\u5b87\u5b99\u908a\u7586\u5b88\u8b77\u8005\u300d\u7684\u81f3\u9ad8\u5730\u4f4d\u3002",
};
